from dataclasses import asdict, dataclass, field, is_dataclass
from datetime import datetime, timezone
from enum import Enum
# Merge-compatibility no-op decorators.
# Some historical Pydantic validators were preserved on dataclass-based
# canonical models; applying real Pydantic decorators there would change the
# runtime contract. These shims preserve the callable methods without adding
# a second validation framework.
def field_validator(*_fields, **_kwargs):
    def _decorator(fn):
        return fn
    return _decorator

def model_validator(*_args, **_kwargs):
    def _decorator(fn):
        return fn
    return _decorator

from typing import (
    Any,
    Callable,
    Dict,
    Iterable,
    List,
    Mapping,
    Optional,
    Sequence,
    Set,
    Tuple,
)


# ============================================================================
# 0. VERSION / CONSTANTS
# ============================================================================

CYBER_CORE_VERSION = "0.1.0"
CYBER_CONTRACT_VERSION = "1.0"

MAX_ID_LENGTH = 160
MAX_TEXT_LENGTH = 100_000
MAX_EVENT_PAYLOAD_BYTES = 1_000_000
MAX_AUDIT_METADATA_BYTES = 100_000

SAFE_IDENTIFIER_RE = re.compile(
    r"^[A-Za-z0-9][A-Za-z0-9_.:@/-]{0,159}$"
)


# ============================================================================
# 1. COMMON UTILITIES
# ============================================================================

def utc_now() -> datetime:
    """Return a timezone-aware UTC timestamp."""
    return datetime.now(timezone.utc)


def utc_now_iso() -> str:
    """Return canonical UTC ISO-8601 timestamp."""
    return utc_now().isoformat()


def new_id(prefix: str) -> str:
    """
    Generate an opaque UUID-based identifier.

    Prefix is restricted to a safe identifier namespace.
    """
    if not prefix or not re.fullmatch(r"[a-zA-Z0-9_-]{1,32}", prefix):
        raise ValueError("Invalid ID prefix.")

    return f"{prefix}_{uuid.uuid4().hex}"


def validate_identifier(
    value: str,
    *,
    field_name: str,
    required: bool = True,
) -> str:
    """
    Validate tenant/entity/user/etc. identifiers.

    This is intentionally strict because identifiers cross trust boundaries.
    """
    if value is None:
        if required:
            raise ValueError(f"{field_name} is required.")
        return ""

    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be a string.")

    value = value.strip()

    if required and not value:
        raise ValueError(f"{field_name} is required.")

    if not value:
        return ""

    if len(value) > MAX_ID_LENGTH:
        raise ValueError(
            f"{field_name} exceeds maximum length of {MAX_ID_LENGTH}."
        )

    if not SAFE_IDENTIFIER_RE.fullmatch(value):
        raise ValueError(
            f"{field_name} contains invalid characters."
        )

    return value


def bounded_text(
    value: Any,
    *,
    field_name: str,
    max_length: int = MAX_TEXT_LENGTH,
    required: bool = False,
) -> str:
    """Normalize bounded textual input."""
    if value is None:
        if required:
            raise ValueError(f"{field_name} is required.")
        return ""

    if not isinstance(value, str):
        value = str(value)

    if len(value) > max_length:
        raise ValueError(
            f"{field_name} exceeds maximum length of {max_length}."
        )

    if required and not value.strip():
        raise ValueError(f"{field_name} cannot be empty.")

    return value


def canonical_json(value: Any) -> str:
    """
    Produce deterministic JSON.

    This is used for hashes, audit records and signatures.
    """
    # [auto-repair] added allow_nan=False (Repair Phase 8). json.dumps
    # defaults to permitting NaN/Infinity/-Infinity, which aren't valid
    # JSON tokens -- letting them through a function whose whole job is
    # producing deterministic bytes for hashes/audit/signatures is a
    # real integrity gap, not just a style nit. Now raises ValueError
    # instead of silently emitting non-standard JSON.
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        default=serialize_value,
        allow_nan=False,
    )


def canonical_json_bytes(value: Any) -> bytes:
    return canonical_json(value).encode("utf-8")


def sha256_hex(value: Any) -> str:
    return hashlib.sha256(canonical_json_bytes(value)).hexdigest()


def serialize_value(value: Any) -> Any:
    """JSON serializer for enums, dataclasses and datetimes."""
    if isinstance(value, Enum):
        return value.value

    if isinstance(value, datetime):
        return value.isoformat()

    if is_dataclass(value):
        return asdict(value)

    if isinstance(value, Mapping):
        return {
            str(k): serialize_value(v)
            for k, v in value.items()
        }

    if isinstance(value, (list, tuple, set, frozenset)):
        return [serialize_value(v) for v in value]

    return value


def deep_copy_json(value: Any) -> Any:
    """
    JSON-compatible defensive copy.

    Prevents callers from mutating payload objects after publication.
    """
    return json.loads(canonical_json(value))


