class ActorType(str, Enum):
    """[CONSOLIDATED] union of 2 independent phase definitions."""
    HUMAN = "HUMAN"
    USER = "USER"
    SERVICE = "SERVICE"
    AGENT = "AGENT"
    SYSTEM = "SYSTEM"
    CONNECTOR = "CONNECTOR"

    @classmethod
    def _missing_(cls, value):
        if isinstance(value, str):
            v = value.strip().lower()
            for member in cls:
                if member.value.lower() == v:
                    return member
        return None


