# ============================================================================
# 3. TENANT CONTEXT
# ============================================================================

@dataclass(frozen=True)
class CyberTenantContext:
    """
    Authoritative server-side execution context.

    Frontend-provided tenant identifiers must never become authoritative
    without being resolved against authenticated server identity.
    """

    tenant_id: str
    actor_id: str = "system"
    actor_type: ActorType = ActorType.HUMAN
    principal_id: str = ""
    request_id: str = ""
    session_id: str = ""
    roles: Tuple[str, ...] = ()
    permissions: Tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if self.principal_id and self.actor_id == "system":
            object.__setattr__(self, "actor_id", self.principal_id)
        object.__setattr__(
            self,
            "tenant_id",
            validate_identifier(
                self.tenant_id,
                field_name="tenant_id",
            ),
        )

        object.__setattr__(
            self,
            "actor_id",
            validate_identifier(
                self.actor_id,
                field_name="actor_id",
            ),
        )

        if self.request_id:
            object.__setattr__(
                self,
                "request_id",
                validate_identifier(
                    self.request_id,
                    field_name="request_id",
                ),
            )

        if self.session_id:
            object.__setattr__(
                self,
                "session_id",
                validate_identifier(
                    self.session_id,
                    field_name="session_id",
                ),
            )

        normalized_roles = tuple(
            validate_identifier(
                role,
                field_name="role",
            )
            for role in self.roles
        )

        normalized_permissions = tuple(
            validate_identifier(
                permission,
                field_name="permission",
            )
            for permission in self.permissions
        )

        object.__setattr__(self, "roles", normalized_roles)
        object.__setattr__(self, "permissions", normalized_permissions)

    def has_permission(self, permission: str) -> bool:
        permission = validate_identifier(
            permission,
            field_name="permission",
        )
        return permission in self.permissions

    def has_role(self, role: str) -> bool:
        role = validate_identifier(role, field_name="role")
        return role in self.roles
# --- preserved from CyberTenantContext (merged, not present in canonical host) ---
    def require_permission(self, permission: str) -> None:
        if permission not in self.permissions:
            raise PermissionError(
                f"Permission denied for operation: {permission}"
            )


