@dataclass(frozen=True)
class CyberEntity:
    """
    Generic canonical security entity.

    More specialized ontology objects will be added in later phases.
    """

    entity_id: str
    entity_type: str
    tenant_id: str
    name: str = ""
    external_id: str = ""
    attributes: Mapping[str, Any] = field(default_factory=dict)
    created_at: str = field(default_factory=utc_now_iso)
    updated_at: str = field(default_factory=utc_now_iso)

    def __post_init__(self) -> None:
        object.__setattr__(
            self,
            "entity_id",
            validate_identifier(
                self.entity_id,
                field_name="entity_id",
            ),
        )

        object.__setattr__(
            self,
            "tenant_id",
            validate_identifier(
                self.tenant_id,
                field_name="tenant_id",
            ),
        )

        object.__setattr__(
            self,
            "entity_type",
            validate_identifier(
                self.entity_type,
                field_name="entity_type",
            ),
        )

        object.__setattr__(
            self,
            "name",
            bounded_text(
                self.name,
                field_name="name",
                max_length=1_000,
            ),
        )

        object.__setattr__(
            self,
            "external_id",
            bounded_text(
                self.external_id,
                field_name="external_id",
                max_length=2_000,
            ),
        )

        object.__setattr__(
            self,
            "attributes",
            deep_copy_json(dict(self.attributes)),
        )

    def assert_tenant(self, tenant_id: str) -> None:
        tenant_id = validate_identifier(
            tenant_id,
            field_name="tenant_id",
        )

        if not hmac.compare_digest(self.tenant_id, tenant_id):
            raise PermissionError(
                "Cross-tenant entity access denied."
            )


