# 5. PROVENANCE
# ============================================================================

@dataclass(frozen=True)
class ProvenanceRecord:
    """
    Records where a security fact came from.

    Provenance is not itself proof of truth.
    It identifies origin and confidence.
    """

    provenance_id: str
    tenant_id: str
    source_type: ProvenanceType
    source_id: str
    source_event_id: str = ""
    statement: str = ""
    confidence: float = 0.0
    observed_at: str = field(default_factory=utc_now_iso)
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(
            self,
            "provenance_id",
            validate_identifier(
                self.provenance_id,
                field_name="provenance_id",
            ),
        )

        object.__setattr__(
            self,
            "tenant_id",
            validate_identifier(
                self.tenant_id,
                field_name="tenant_id",
            ),
        )

        object.__setattr__(
            self,
            "source_id",
            bounded_text(
                self.source_id,
                field_name="source_id",
                max_length=2_000,
                required=True,
            ),
        )

        object.__setattr__(
            self,
            "source_event_id",
            bounded_text(
                self.source_event_id,
                field_name="source_event_id",
                max_length=2_000,
            ),
        )

        object.__setattr__(
            self,
            "statement",
            bounded_text(
                self.statement,
                field_name="statement",
                max_length=20_000,
            ),
        )

        if not 0.0 <= float(self.confidence) <= 1.0:
            raise ValueError(
                "confidence must be between 0.0 and 1.0."
            )

        object.__setattr__(
            self,
            "confidence",
            float(self.confidence),
        )

        object.__setattr__(
            self,
            "metadata",
            deep_copy_json(dict(self.metadata)),
        )


