@dataclass(frozen=True)
class CyberEvidence:
    """
    Evidence reference.

    Evidence content can later be stored in dedicated evidence/object
    storage. This contract intentionally keeps references separate from
    potentially large blobs.
    """

    evidence_id: str
    tenant_id: str
    evidence_type: EvidenceType
    source_id: str
    statement: str = ""
    content_hash: str = ""
    provenance_ids: Tuple[str, ...] = ()
    collected_at: str = field(default_factory=utc_now_iso)
    verification_status: VerificationStatus = (
        VerificationStatus.UNVERIFIED
    )
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(
            self,
            "evidence_id",
            validate_identifier(
                self.evidence_id,
                field_name="evidence_id",
            ),
        )

        object.__setattr__(
            self,
            "tenant_id",
            validate_identifier(
                self.tenant_id,
                field_name="tenant_id",
            ),
        )

        object.__setattr__(
            self,
            "source_id",
            bounded_text(
                self.source_id,
                field_name="source_id",
                max_length=2_000,
                required=True,
            ),
        )

        object.__setattr__(
            self,
            "statement",
            bounded_text(
                self.statement,
                field_name="statement",
                max_length=20_000,
            ),
        )

        if self.content_hash:
            content_hash = self.content_hash.lower().strip()
            if not re.fullmatch(r"[a-f0-9]{64}", content_hash):
                raise ValueError(
                    "content_hash must be a SHA-256 hexadecimal digest."
                )
            object.__setattr__(
                self,
                "content_hash",
                content_hash,
            )

        object.__setattr__(
            self,
            "provenance_ids",
            tuple(
                validate_identifier(
                    item,
                    field_name="provenance_id",
                )
                for item in self.provenance_ids
            ),
        )

        object.__setattr__(
            self,
            "metadata",
            deep_copy_json(dict(self.metadata)),
        )

    def assert_tenant(self, tenant_id: str) -> None:
        tenant_id = validate_identifier(
            tenant_id,
            field_name="tenant_id",
        )

        if not hmac.compare_digest(self.tenant_id, tenant_id):
            raise PermissionError(
                "Cross-tenant evidence access denied."
            )

# ============================================================================
# 7. CYBER EVENT
# ============================================================================

@dataclass(frozen=True)
class CyberEvent:
    """
    Canonical event envelope.

    Events are immutable after construction.

    Correlation ID:
        groups related events across a workflow/incident.

    Causation ID:
        points to the event that directly caused this event.
    """

    event_id: str
    event_type: str
    tenant_id: str
    timestamp: str = field(default_factory=utc_now_iso)

    source: str = "system"
    source_event_id: str = ""

    actor_id: str = ""
    actor_type: ActorType = ActorType.SYSTEM

    request_id: str = ""
    correlation_id: str = ""
    causation_id: str = ""

    schema_version: str = CYBER_CONTRACT_VERSION

    provenance_ids: Tuple[str, ...] = ()
    entity_ids: Tuple[str, ...] = ()
    evidence_ids: Tuple[str, ...] = ()

    payload: Mapping[str, Any] = field(default_factory=dict)

    status: EventStatus = EventStatus.ACCEPTED

    def __post_init__(self) -> None:
        object.__setattr__(
            self,
            "event_id",
            validate_identifier(
                self.event_id,
                field_name="event_id",
            ),
        )

        object.__setattr__(
            self,
            "event_type",
            validate_identifier(
                self.event_type,
                field_name="event_type",
            ),
        )

        object.__setattr__(
            self,
            "tenant_id",
            validate_identifier(
                self.tenant_id,
                field_name="tenant_id",
            ),
        )

        object.__setattr__(
            self,
            "source",
            bounded_text(
                self.source,
                field_name="source",
                max_length=2_000,
                required=True,
            ),
        )

        for field_name in (
            "source_event_id",
            "actor_id",
            "request_id",
            "correlation_id",
            "causation_id",
        ):
            value = getattr(self, field_name)

            if value:
                value = validate_identifier(
                    value,
                    field_name=field_name,
                )

            object.__setattr__(self, field_name, value)

        if not self.schema_version:
            raise ValueError("schema_version is required.")

        object.__setattr__(
            self,
            "provenance_ids",
            tuple(
                validate_identifier(
                    value,
                    field_name="provenance_id",
                )
                for value in self.provenance_ids
            ),
        )

        object.__setattr__(
            self,
            "entity_ids",
            tuple(
                validate_identifier(
                    value,
                    field_name="entity_id",
                )
                for value in self.entity_ids
            ),
        )

        object.__setattr__(
            self,
            "evidence_ids",
            tuple(
                validate_identifier(
                    value,
                    field_name="evidence_id",
                )
                for value in self.evidence_ids
            ),
        )

        payload = deep_copy_json(dict(self.payload))

        payload_size = len(
            canonical_json_bytes(payload)
        )

        if payload_size > MAX_EVENT_PAYLOAD_BYTES:
            raise ValueError(
                "Event payload exceeds maximum allowed size."
            )

        object.__setattr__(self, "payload", payload)

    def assert_tenant(self, tenant_id: str) -> None:
        tenant_id = validate_identifier(
            tenant_id,
            field_name="tenant_id",
        )

        if not hmac.compare_digest(self.tenant_id, tenant_id):
            raise PermissionError(
                "Cross-tenant event access denied."
            )

    def digest(self) -> str:
        """Deterministic SHA-256 digest of the complete event."""
        return sha256_hex(self)

    def to_dict(self) -> Dict[str, Any]:
        return serialize_value(self)

