@dataclass(frozen=True)
class CyberAuditRecord:
    """
    Canonical tamper-evident audit record.

    current_hash = SHA256(canonical(record_without_current_hash))
    previous_hash links the record to the previous audit record.
    """

    audit_id: str
    tenant_id: str

    timestamp: str

    actor_type: ActorType
    actor_id: str

    action: str
    target: str

    category: AuditCategory

    decision_id: str = ""
    request_id: str = ""
    correlation_id: str = ""

    result: str = ""

    policy_effect: Optional[PolicyEffect] = None

    evidence_ids: Tuple[str, ...] = ()
    metadata: Mapping[str, Any] = field(default_factory=dict)

    previous_hash: str = ""
    current_hash: str = ""

    def __post_init__(self) -> None:
        object.__setattr__(
            self,
            "audit_id",
            validate_identifier(
                self.audit_id,
                field_name="audit_id",
            ),
        )

        object.__setattr__(
            self,
            "tenant_id",
            validate_identifier(
                self.tenant_id,
                field_name="tenant_id",
            ),
        )

        object.__setattr__(
            self,
            "actor_id",
            validate_identifier(
                self.actor_id,
                field_name="actor_id",
            ),
        )

        object.__setattr__(
            self,
            "action",
            bounded_text(
                self.action,
                field_name="action",
                max_length=2_000,
                required=True,
            ),
        )

        object.__setattr__(
            self,
            "target",
            bounded_text(
                self.target,
                field_name="target",
                max_length=2_000,
                required=True,
            ),
        )

        object.__setattr__(
            self,
            "result",
            bounded_text(
                self.result,
                field_name="result",
                max_length=10_000,
            ),
        )

        for field_name in (
            "decision_id",
            "request_id",
            "correlation_id",
        ):
            value = getattr(self, field_name)

            if value:
                value = validate_identifier(
                    value,
                    field_name=field_name,
                )

            object.__setattr__(self, field_name, value)

        object.__setattr__(
            self,
            "evidence_ids",
            tuple(
                validate_identifier(
                    value,
                    field_name="evidence_id",
                )
                for value in self.evidence_ids
            ),
        )

        metadata = deep_copy_json(dict(self.metadata))

        if len(canonical_json_bytes(metadata)) > MAX_AUDIT_METADATA_BYTES:
            raise ValueError(
                "Audit metadata exceeds maximum allowed size."
            )

        object.__setattr__(
            self,
            "metadata",
            metadata,
        )

    def unsigned_dict(
        self,
        *,
        include_previous_hash: bool = True,
    ) -> Dict[str, Any]:
        data = {
            "audit_id": self.audit_id,
            "tenant_id": self.tenant_id,
            "timestamp": self.timestamp,
            "actor_type": self.actor_type,
            "actor_id": self.actor_id,
            "action": self.action,
            "target": self.target,
            "category": self.category,
            "decision_id": self.decision_id,
            "request_id": self.request_id,
            "correlation_id": self.correlation_id,
            "result": self.result,
            "policy_effect": self.policy_effect,
            "evidence_ids": self.evidence_ids,
            "metadata": self.metadata,
        }

        if include_previous_hash:
            data["previous_hash"] = self.previous_hash

        return serialize_value(data)

    def calculate_hash(self) -> str:
        return sha256_hex(
            self.unsigned_dict(
                include_previous_hash=True,
            )
        )


# ============================================================================
# 11. AUDIT LEDGER
# ============================================================================

class AuditLedger:
    """
    Thread-safe append-only hash-chained audit ledger.

    Phase 1 implementation is in-memory.

    Later persistence must preserve:
    - ordering
    - previous_hash
    - current_hash
    - tenant ownership
    - immutable audit semantics
    """

    GENESIS_HASH = "0" * 64

    def __init__(self) -> None:
        self._lock = threading.RLock()
        self._records: List[CyberAuditRecord] = []

    def append(
        self,
        *,
        context: Optional[CyberTenantContext] = None,
        action: str,
        target: Optional[str] = None,
        category: Optional[AuditCategory] = None,
        result: str = "",
        decision_id: str = "",
        evidence_ids: Sequence[str] = (),
        metadata: Optional[Mapping[str, Any]] = None,
        policy_effect: Optional[PolicyEffect] = None,
        tenant_id: Optional[str] = None,
        actor_id: Optional[str] = None,
        resource: Optional[str] = None,
        outcome: Optional["AuditOutcome"] = None,
        request_id: Optional[str] = None,
    ) -> CyberAuditRecord:
        # NOTE(auto-repair): callers (e.g. Phase 21's self-test) also
        # append with plain tenant_id/actor_id/resource/outcome/request_id
        # kwargs rather than a CyberTenantContext + target/category.
        # Building the context here when needed rather than rejecting the
        # call.
        if context is None:
            if tenant_id is None:
                raise TypeError(
                    "append() requires either context= or tenant_id=."
                )
            context = CyberTenantContext(
                tenant_id=tenant_id,
                actor_id=actor_id or "system",
                request_id=request_id or "",
            )

        if not isinstance(context, CyberTenantContext):
            raise TypeError(
                "context must be CyberTenantContext."
            )

        resolved_target = (
            target if target is not None else resource or ""
        )
        resolved_category = (
            category
            if category is not None
            else AuditCategory.EXECUTION
        )
        resolved_result = (
            result if result else (
                # [auto-repair] was `outcome.value` unconditionally,
                # which assumed outcome is always an AuditOutcome enum
                # member. A caller passing a plain string (e.g.
                # outcome="success") -- exactly the Phase-6-style
                # calling convention this shim exists to support --
                # would hit AttributeError: 'str' object has no
                # attribute 'value'. Handles both shapes now.
                (outcome.value if hasattr(outcome, "value") else str(outcome))
                if outcome is not None else ""
            )
        )

        with self._lock:
            previous_hash = (
                self._records[-1].current_hash
                if self._records
                else self.GENESIS_HASH
            )

            record = CyberAuditRecord(
                audit_id=new_id("audit"),
                tenant_id=context.tenant_id,
                timestamp=utc_now_iso(),
                actor_type=context.actor_type,
                actor_id=context.actor_id,
                action=action,
                target=resolved_target,
                category=resolved_category,
                decision_id=decision_id,
                request_id=context.request_id,
                correlation_id="",
                result=resolved_result,
                policy_effect=policy_effect,
                evidence_ids=tuple(evidence_ids),
                metadata=metadata or {},
                previous_hash=previous_hash,
            )

            current_hash = record.calculate_hash()

            record = CyberAuditRecord(
                **{
                    **asdict(record),
                    "current_hash": current_hash,
                }
            )

            self._records.append(record)

            return record

    def verify_integrity(self) -> bool:
        # NOTE(auto-repair): didn't exist; walks the hash chain this class
        # already builds in append() and confirms both the per-record hash
        # and the previous_hash linkage are intact.
        with self._lock:
            expected_previous = self.GENESIS_HASH

            for record in self._records:
                if record.previous_hash != expected_previous:
                    return False

                if record.current_hash != record.calculate_hash():
                    return False

                expected_previous = record.current_hash

            return True

    def append_event_audit(
        self,
        event: CyberEvent,
        *,
        result: str = "accepted",
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> CyberAuditRecord:
        """
        Convenience method for auditing event acceptance.
        """
        context = CyberTenantContext(
            tenant_id=event.tenant_id,
            actor_id=(
                event.actor_id
                if event.actor_id
                else "system"
            ),
            actor_type=event.actor_type,
            request_id=event.request_id,
        )

        return self.append(
            context=context,
            action=f"event.{event.event_type}",
            target=event.event_id,
            category=AuditCategory.SYSTEM,
            result=result,
            evidence_ids=event.evidence_ids,
            metadata={
                "source": event.source,
                "schema_version": event.schema_version,
                **(metadata or {}),
            },
        )

    def records(
        self,
        *,
        tenant_id: Optional[str] = None,
        limit: int = 100,
    ) -> List[CyberAuditRecord]:
        if limit <= 0:
            return []

        with self._lock:
            records = list(reversed(self._records))

        if tenant_id is not None:
            tenant_id = validate_identifier(
                tenant_id,
                field_name="tenant_id",
            )

            records = [
                record
                for record in records
                if hmac.compare_digest(
                    record.tenant_id,
                    tenant_id,
                )
            ]

        return records[:limit]

    def verify_chain(
        self,
        *,
        tenant_id: Optional[str] = None,
    ) -> Dict[str, Any]:
        """
        Verify the audit chain.

        If tenant_id is supplied, verification is performed against the
        selected tenant's sequence as a standalone verification view.
        """
        with self._lock:
            records = list(self._records)

        if tenant_id is not None:
            tenant_id = validate_identifier(
                tenant_id,
                field_name="tenant_id",
            )

            records = [
                record
                for record in records
                if hmac.compare_digest(
                    record.tenant_id,
                    tenant_id,
                )
            ]

        expected_previous = self.GENESIS_HASH
        failures: List[Dict[str, Any]] = []

        for index, record in enumerate(records):
            if record.previous_hash != expected_previous:
                failures.append(
                    {
                        "index": index,
                        "audit_id": record.audit_id,
                        "type": "PREVIOUS_HASH_MISMATCH",
                        "expected": expected_previous,
                        "actual": record.previous_hash,
                    }
                )

            calculated = record.calculate_hash()

            if not hmac.compare_digest(
                calculated,
                record.current_hash,
            ):
                failures.append(
                    {
                        "index": index,
                        "audit_id": record.audit_id,
                        "type": "CURRENT_HASH_MISMATCH",
                        "expected": calculated,
                        "actual": record.current_hash,
                    }
                )

            expected_previous = record.current_hash

        return {
            "valid": not failures,
            "record_count": len(records),
            "failures": failures,
        }

    def size(self) -> int:
        with self._lock:
            return len(self._records)




