class EmergencyStopManager:
    """
    Controls whether execution is permitted.

    This manager is intentionally conservative.

    A stop is considered active if any applicable scope is active.
    """

    def __init__(self) -> None:
        self._lock = threading.RLock()
        self._stops: Dict[Tuple[StopScope, str], EmergencyStop] = {}

    def activate(
        self,
        *,
        scope: StopScope,
        scope_id: str,
        reason: str,
        activated_by: str,
    ) -> EmergencyStop:
        stop = EmergencyStop(
            scope=scope,
            scope_id=scope_id,
            enabled=True,
            reason=reason,
            activated_by=activated_by,
        )

        with self._lock:
            self._stops[(scope, scope_id)] = stop

        return stop

    def deactivate(
        self,
        *,
        scope: StopScope,
        scope_id: str,
        reason: str,
        activated_by: str,
    ) -> EmergencyStop:
        stop = EmergencyStop(
            scope=scope,
            scope_id=scope_id,
            enabled=False,
            reason=reason,
            activated_by=activated_by,
        )

        with self._lock:
            self._stops.pop((scope, scope_id), None)

        return stop

    def is_stopped(
        self,
        *,
        tenant_id: str,
        agent_id: str = "",
        connector_id: str = "",
        action_type: str = "",
        workflow_id: str = "",
        incident_id: str = "",
    ) -> bool:
        """
        Determine whether any applicable stop is active.

        Global stop has highest scope.

        Tenant/agent/connector/action/workflow/incident are independently
        checked.
        """
        with self._lock:
            applicable = [
                (StopScope.GLOBAL, "global"),
                (StopScope.TENANT, tenant_id),
            ]

            if agent_id:
                applicable.append(
                    (StopScope.AGENT, agent_id)
                )

            if connector_id:
                applicable.append(
                    (StopScope.CONNECTOR, connector_id)
                )

            if action_type:
                applicable.append(
                    (StopScope.ACTION_TYPE, action_type)
                )

            if workflow_id:
                applicable.append(
                    (StopScope.WORKFLOW, workflow_id)
                )

            if incident_id:
                applicable.append(
                    (StopScope.INCIDENT, incident_id)
                )

            return any(
                key in self._stops
                and self._stops[key].enabled
                for key in applicable
            )

    def active_stops(self) -> List[EmergencyStop]:
        with self._lock:
            return list(self._stops.values())




