# =============================================================================
# COMMON UTILITIES
# =============================================================================

def iso_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def make_id(prefix: str) -> str:
    return f"{prefix}_{uuid.uuid4().hex}"


def canonical_json_v2(value: Any) -> str:
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        default=_json_default,
    )


def _json_default(value: Any) -> Any:
    if isinstance(value, Enum):
        return value.value

    if isinstance(value, datetime):
        return value.isoformat()

    raise TypeError(
        f"Object of type {type(value).__name__} "
        f"is not JSON serializable"
    )


def deep_copy(value: Any) -> Any:
    return json.loads(canonical_json_v2(value))


def sha256(value: Any) -> str:
    return hashlib.sha256(
        canonical_json_v2(value).encode("utf-8")
    ).hexdigest()


def validate_id(
    value: str,
    name: str,
) -> str:
    if not isinstance(value, str):
        raise TypeError(f"{name} must be a string.")

    value = value.strip()

    if not value:
        raise ValueError(f"{name} cannot be empty.")

    if len(value) > 256:
        raise ValueError(
            f"{name} exceeds maximum length."
        )

    return value


def _legacy_require_nonempty_merged(
    value: Any,
    name: str,
) -> None:
    # NOTE(auto-repair): called from several places (agent/tool identity
    # validation) but was never defined in this half of the file -- only a
    # same-named function much later, past the point where a second merged
    # system begins requiring pydantic. Defined locally here (reusing
    # validate_id's non-empty-string check) so this half of the file
    # doesn't depend on that later, optional-dependency-gated code loading
    # successfully.
    validate_id(value, name)


