    """[CONSOLIDATED] union of 2 definitions; casing varied -> case-insensitive _missing_."""
    SUCCESS = "SUCCESS"
    DUPLICATE = "DUPLICATE"
    FAILED = "FAILED"
    REJECTED = "REJECTED"

    @classmethod
    def _missing_(cls, value):
        if isinstance(value, str):
            v = value.strip().lower()
            for member in cls:
                if member.value.lower() == v:
                    return member
        return None
