# TENANT CONTEXT
# =============================================================================

@dataclass(frozen=True)
class CyberFabricTenant:
    tenant_id: str
    actor_id: str = "system"
    request_id: str = ""

    def __post_init__(self) -> None:
        validate_id(self.tenant_id, "tenant_id")
        validate_id(self.actor_id, "actor_id")

        if self.request_id:
            validate_id(
                self.request_id,
                "request_id",
            )


def assert_tenant(
    active_tenant: CyberFabricTenant,
    resource_tenant_id: str,
) -> None:
    if not hmac.compare_digest(
        active_tenant.tenant_id,
        resource_tenant_id,
    ):
        raise TenantIsolationError(
            "Cross-tenant data access denied."
        )


# =============================================================================
# LINEAGE
# =============================================================================



@dataclass
class Lineage:
    entries: List[LineageEntry] = field(
        default_factory=list
    )

    def add(
        self,
        stage: LineageStage,
        *,
        actor: str,
        details: Optional[Mapping[str, Any]] = None,
    ) -> None:
        self.entries.append(
            LineageEntry(
                stage=stage,
                timestamp=iso_now(),
                actor=actor,
                details=deep_copy(
                    details or {}
                ),
            )
        )

    def contains(
        self,
        stage: LineageStage,
    ) -> bool:
        return any(
            entry.stage == stage
            for entry in self.entries
        )

    def to_dict(self) -> List[Dict[str, Any]]:
        return [
            {
                "stage": entry.stage.value,
                "timestamp": entry.timestamp,
                "actor": entry.actor,
                "details": dict(entry.details),
            }
            for entry in self.entries
        ]


# =============================================================================
# CYBER TELEMETRY
# =============================================================================

@dataclass
class CyberTelemetry:
    """
    Canonical normalized telemetry record.

    Raw source payload is preserved separately from normalized data so
    normalization never destroys original evidence.
    """

    record_id: str
    tenant_id: str

    connector_id: str
    source: str
    source_record_type: str

    observed_at: str

    normalized: Dict[str, Any]

    raw_payload: Dict[str, Any]

    source_record_id: str = ""

    event_id: str = ""

    state: RecordState = RecordState.RECEIVED

    schema_version: str = CYBER_DATA_SCHEMA_VERSION

    idempotency_key: str = ""

    content_hash: str = ""

    entity_refs: List[str] = field(
        default_factory=list
    )

    enrichment: Dict[str, Any] = field(
        default_factory=dict
    )

    context: Dict[str, Any] = field(
        default_factory=dict
    )

    correlation_refs: List[str] = field(
        default_factory=list
    )

    lineage: Lineage = field(
        default_factory=Lineage
    )

    created_at: str = field(
        default_factory=iso_now
    )

    ingested_at: str = ""

    def __post_init__(self) -> None:
        validate_id(
            self.record_id,
            "record_id",
        )

        validate_id(
            self.tenant_id,
            "tenant_id",
        )

        validate_id(
            self.connector_id,
            "connector_id",
        )

        validate_id(
            self.source,
            "source",
        )

        validate_id(
            self.source_record_type,
            "source_record_type",
        )

        if self.source_record_id:
            validate_id(
                self.source_record_id,
                "source_record_id",
            )

        self.normalized = deep_copy(
            self.normalized
        )

        self.raw_payload = deep_copy(
            self.raw_payload
        )

        self.enrichment = deep_copy(
            self.enrichment
        )

        self.context = deep_copy(
            self.context
        )

        if not self.content_hash:
            self.content_hash = self.calculate_fingerprint()
    def calculate_fingerprint(self) -> str:
        return hashlib.sha256(
            canonical_json_v2({
                "tenant_id": self.tenant_id,
                "connector_id": self.connector_id,
                "source": self.source,
                "source_record_type": self.source_record_type,
                "source_record_id": self.source_record_id,
                "observed_at": self.observed_at,
                "raw_payload": self.raw_payload,
            }).encode("utf-8")
        ).hexdigest()

    def ensure_fingerprint(self) -> str:
        if not self.content_hash:
            self.content_hash = self.calculate_fingerprint()
        return self.content_hash

    def to_dict(self) -> Dict[str, Any]:
        return {
            "record_id": self.record_id,
            "tenant_id": self.tenant_id,
            "connector_id": self.connector_id,
            "source": self.source,
            "source_record_type": self.source_record_type,
            "source_record_id": self.source_record_id,
            "observed_at": self.observed_at,
            "normalized": deep_copy(self.normalized),
            "raw_payload": deep_copy(self.raw_payload),
            "event_id": self.event_id,
            "state": self.state.value,
            "schema_version": self.schema_version,
            "idempotency_key": self.idempotency_key,
            "content_hash": self.content_hash,
            "entity_refs": list(self.entity_refs),
            "enrichment": deep_copy(self.enrichment),
            "context": deep_copy(self.context),
            "correlation_refs": list(self.correlation_refs),
            "lineage": self.lineage.to_dict(),
            "created_at": self.created_at,
            "ingested_at": self.ingested_at,
        }


# =============================================================================
# SCHEMA REGISTRY
# =============================================================================

@dataclass(frozen=True)
class SchemaDefinition:
    schema_id: str
    version: str
    required: Tuple[str, ...] = ()
    field_types: Mapping[str, str] = field(
        default_factory=dict
    )
    allowed_values: Mapping[str, Tuple[Any, ...]] = field(
        default_factory=dict
    )
    # Type is SchemaStatus (str, Enum), defined later in the file; the plain
    # string default avoids a forward-reference NameError at class-definition
    # time while still comparing equal to SchemaStatus.ACTIVE at runtime,
    # since SchemaStatus subclasses str.
    status: "SchemaStatus" = "active"


class CyberSchemaRegistry:
    """
    Versioned source-schema registry.

    Schemas validate incoming records BEFORE normalization.
    """

    def __init__(self) -> None:
        self._lock = threading.RLock()

        self._schemas: Dict[
            Tuple[str, str],
            SchemaDefinition,
        ] = {}

    def register(
        self,
        schema: SchemaDefinition,
    ) -> None:
        validate_id(
            schema.schema_id,
            "schema_id",
        )

        validate_id(
            schema.version,
            "version",
        )

        key = (
            schema.schema_id,
            schema.version,
        )

        with self._lock:
            if key in self._schemas:
                raise ValueError(
                    f"Schema already registered: {key}"
                )

            self._schemas[key] = schema

    def get(
        self,
        schema_id: str,
        version: str,
    ) -> SchemaDefinition:
        key = (
            schema_id,
            version,
        )

        with self._lock:
            schema = self._schemas.get(key)

        if schema is None:
            raise SchemaValidationError(
                f"Unknown schema: {schema_id}@{version}"
            )

        return schema

    def has(
        self,
        schema_id: str,
        version: str,
    ) -> bool:
        with self._lock:
            return (
                schema_id,
                version,
            ) in self._schemas
    # --- preserved from CyberSchemaRegistry (merged, not present in canonical host) ---
    def validate(
        self,
        name: str,
        version: str,
        payload: Mapping[str, Any],
    ) -> SchemaValidationResult:

        schema = self.get(name, version)

        if schema.status == SchemaStatus.RETIRED:
            return SchemaValidationResult(
                valid=False,
                violations=(
                    f"Schema {name}:{version} is retired.",
                ),
            )

        violations: List[str] = []
        warnings: List[str] = []

        for field_name in schema.required:
            if field_name not in payload:
                violations.append(
                    f"Missing required field: {field_name}"
                )

        for field_name, expected_type in schema.field_types.items():

            if field_name not in payload:
                continue

            value = payload[field_name]

            type_ok = {
                "str": isinstance(value, str),
                "int": isinstance(value, int)
                and not isinstance(value, bool),
                "float": isinstance(value, (int, float))
                and not isinstance(value, bool),
                "bool": isinstance(value, bool),
                "dict": isinstance(value, dict),
                "list": isinstance(value, list),
            }.get(expected_type)

            if type_ok is False:
                violations.append(
                    f"Field {field_name} expected {expected_type}, "
                    f"got {type(value).__name__}"
                )

            elif type_ok is None:
                warnings.append(
                    f"No runtime validator registered for type "
                    f"{expected_type} on {field_name}."
                )

        return SchemaValidationResult(
            valid=not violations,
            violations=tuple(violations),
            warnings=tuple(warnings),
        )
    # --- preserved from CyberSchemaRegistry (merged, not present in canonical host) ---
    def versions(self, name: str) -> List[str]:
        with self._lock:
            return sorted(
                version
                for schema_name, version in self._schemas
                if schema_name == name
            )
    # --- preserved from CyberSchemaRegistry (merged, not present in canonical host) ---
    def list(self) -> Tuple[CyberSchema, ...]:
        with self._lock:
            return tuple(
                self._schemas.values()
            )


# =============================================================================
# SCHEMA VALIDATOR
# =============================================================================

class CyberSchemaValidator:

    TYPE_MAP = {
        "str": str,
        "int": int,
        "float": float,
        "bool": bool,
        "dict": dict,
        "list": list,
    }

    def __init__(
        self,
        registry: CyberSchemaRegistry,
    ) -> None:
        self.registry = registry

    def validate(
        self,
        raw: Mapping[str, Any],
        schema_id: str,
        schema_version: str,
    ) -> List[str]:

        if not isinstance(raw, Mapping):
            return [
                "payload must be an object"
            ]

        schema = self.registry.get(
            schema_id,
            schema_version,
        )

        violations: List[str] = []

        for field_name in schema.required:
            if field_name not in raw:
                violations.append(
                    f"missing required field: {field_name}"
                )

        for field_name, type_name in (
            schema.field_types.items()
        ):
            if field_name not in raw:
                continue

            expected = self.TYPE_MAP.get(
                type_name
            )

            if expected is None:
                violations.append(
                    f"unknown schema type: {type_name}"
                )
                continue

            value = raw[field_name]

            # bool is an int subclass in Python.
            if expected is int and isinstance(
                value,
                bool,
            ):
                violations.append(
                    f"{field_name} expected int"
                )
                continue

            if not isinstance(
                value,
                expected,
            ):
                violations.append(
                    f"{field_name} expected {type_name}"
                )

        for field_name, values in (
            schema.allowed_values.items()
        ):
            if field_name in raw:
                if raw[field_name] not in values:
                    violations.append(
                        f"{field_name} contains "
                        f"unsupported value"
                    )

        return violations

    def assert_valid(
        self,
        raw: Mapping[str, Any],
        schema_id: str,
        schema_version: str,
    ) -> None:
        violations = self.validate(
            raw,
            schema_id,
            schema_version,
        )

        if violations:
            raise SchemaValidationError(
                "; ".join(violations)
            )


# =============================================================================
# NORMALIZER
# =============================================================================

class CyberNormalizer(ABC):

    @abstractmethod
    def normalize(
        self,
        raw: Mapping[str, Any],
    ) -> Mapping[str, Any]:
        """
        Convert source-specific payload into canonical Cyber structure.
        """
        raise NotImplementedError


class IdentityNormalizer(CyberNormalizer):
    """
    Example canonical identity normalizer.

    This is a generic source-independent normalizer, NOT an integration
    with a real identity vendor.
    """

    def normalize(
        self,
        raw: Mapping[str, Any],
    ) -> Mapping[str, Any]:

        return {
            "entity_type": "Identity",
            "identity_id": raw.get(
                "identity_id"
            ),
            "username": raw.get(
                "username"
            ),
            "email": raw.get(
                "email"
            ),
            "status": raw.get(
                "status"
            ),
            "attributes": deep_copy(
                raw.get(
                    "attributes",
                    {},
                )
            ),
        }


class GenericTelemetryNormalizer(CyberNormalizer):

    def normalize(
        self,
        raw: Mapping[str, Any],
    ) -> Mapping[str, Any]:

        return {
            "entity_type": "Telemetry",
            "data": deep_copy(
                dict(raw)
            ),
        }


# =============================================================================
# ENRICHMENT / ENTITY RESOLUTION / CONTEXTUALIZATION
# =============================================================================

EnrichmentFunction = Callable[
    [CyberFabricTenant, CyberTelemetry],
    Mapping[str, Any],
]

EntityResolver = Callable[
    [CyberFabricTenant, CyberTelemetry],
    Sequence[str],
]

Contextualizer = Callable[
    [CyberFabricTenant, CyberTelemetry],
    Mapping[str, Any],
]

Correlator = Callable[
    [CyberFabricTenant, CyberTelemetry],
    Sequence[str],
]


class CyberEnrichmentPipeline:

    def __init__(self) -> None:
        self._enrichers: List[
            EnrichmentFunction
        ] = []

        self._resolvers: List[
            EntityResolver
        ] = []

        self._contextualizers: List[
            Contextualizer
        ] = []

        self._correlators: List[
            Correlator
        ] = []

    def add_enricher(
        self,
        fn: EnrichmentFunction,
    ) -> None:
        self._enrichers.append(fn)

    def add_resolver(
        self,
        fn: EntityResolver,
    ) -> None:
        self._resolvers.append(fn)

    def add_contextualizer(
        self,
        fn: Contextualizer,
    ) -> None:
        self._contextualizers.append(fn)

    def add_correlator(
        self,
        fn: Correlator,
    ) -> None:
        self._correlators.append(fn)

    def enrich(
        self,
        tenant: CyberFabricTenant,
        record: CyberTelemetry,
    ) -> None:
        for enricher in self._enrichers:
            result = enricher(
                tenant,
                record,
            )

            record.enrichment.update(
                deep_copy(result)
            )

        record.state = RecordState.ENRICHED

        record.lineage.add(
            LineageStage.ENRICHED,
            actor="enrichment_pipeline",
        )

    def resolve(
        self,
        tenant: CyberFabricTenant,
        record: CyberTelemetry,
    ) -> None:
        refs: List[str] = []

        for resolver in self._resolvers:
            refs.extend(
                resolver(
                    tenant,
                    record,
                )
            )

        record.entity_refs = sorted(
            set(refs)
        )

        record.state = RecordState.RESOLVED

        record.lineage.add(
            LineageStage.RESOLVED,
            actor="entity_resolver",
            details={
                "entity_count": len(
                    record.entity_refs
                )
            },
        )

    def contextualize(
        self,
        tenant: CyberFabricTenant,
        record: CyberTelemetry,
    ) -> None:
        for contextualizer in (
            self._contextualizers
        ):
            result = contextualizer(
                tenant,
                record,
            )

            record.context.update(
                deep_copy(result)
            )

        record.state = (
            RecordState.CONTEXTUALIZED
        )

        record.lineage.add(
            LineageStage.CONTEXTUALIZED,
            actor="contextualizer",
        )

    def correlate(
        self,
        tenant: CyberFabricTenant,
        record: CyberTelemetry,
    ) -> None:
        refs: List[str] = []

        for correlator in self._correlators:
            refs.extend(
                correlator(
                    tenant,
                    record,
                )
            )

        record.correlation_refs = sorted(
            set(refs)
        )

        record.state = RecordState.CORRELATED

        record.lineage.add(
            LineageStage.CORRELATED,
            actor="correlator",
            details={
                "correlation_count": len(
                    record.correlation_refs
                )
            },
        )


# =============================================================================
# CONNECTOR RESULT
# =============================================================================

@dataclass(frozen=True)
class ConnectorHealth:
    connector_id: str
    state: ConnectorState = ConnectorState.CREATED
    checked_at: str = field(default_factory=iso_now)
    latency_ms: float = 0.0
    message: str = ""
    status: Optional[ConnectorStatus] = None
    metadata: Mapping[str, Any] = field(default_factory=dict)
    tenant_id: str = ""
    status_code: Optional[int] = None
    consecutive_failures: int = 0

    def __post_init__(self) -> None:
        if self.status is None and "ConnectorStatus" in globals():
            object.__setattr__(self, "status", ConnectorStatus.HEALTHY if self.state in {ConnectorState.CONNECTED, ConnectorState.HEALTHY} else ConnectorStatus.UNHEALTHY)


@dataclass(frozen=True)
class ConnectorAccount:
    account_id: str
    tenant_id: str
    metadata: Mapping[str, Any] = field(
        default_factory=dict
    )

    def __post_init__(self) -> None:
        validate_id(
            self.account_id,
            "account_id",
        )

        validate_id(
            self.tenant_id,
            "tenant_id",
        )
    connector_id: str = None  # merged from ConnectorAccount, made optional for safety


@dataclass(frozen=True)
class ConnectorResult:
    status: CapabilityStatus = CapabilityStatus.SUPPORTED
    records: Tuple[Mapping[str, Any], ...] = ()
    message: str = ""
    success: bool = True
    events: Tuple[Any, ...] = ()
    cursor: Optional[str] = None
    error: Optional[str] = None
    retryable: bool = False
    latency_ms: float = 0.0
    metadata: Mapping[str, Any] = field(default_factory=dict)


# =============================================================================
# CONNECTOR SDK
# =============================================================================

class CyberConnector(ABC):
    """
    Independent Cyber connector contract.

    Unsupported operations MUST raise ConnectorNotSupported.

    NOTE: this class previously contained ~20 duplicate method definitions
    left behind by an automated merge (each pair silently shadowed by
    whichever definition came last), several of which referenced
    self.config / self.capabilities / self._credential_provider in ways
    that were never initialized for a plain connector_id+display_name
    construction (only for construction from a ConnectorConfig object).
    This consolidated version supports both construction styles.
    """

    def __init__(
        self,
        connector_id: Any,
        display_name: Optional[str] = None,
        *,
        capabilities: Optional[Iterable["ConnectorCapability"]] = None,
        tenant_id: Optional[str] = None,
        family: Optional["ConnectorFamily"] = None,
    ) -> None:
        self.config: Optional["ConnectorConfig"] = None

        if display_name is None and hasattr(connector_id, "connector_id"):
            # Constructed from a ConnectorConfig-like object.
            config = connector_id
            self.config = config
            connector_id = config.connector_id
            display_name = getattr(
                config, "name", getattr(config, "connector_id", "connector")
            )
            self._status = getattr(
                config, "status", ConnectorStatus.REGISTERED
            )
        else:
            self._status = ConnectorStatus.REGISTERED

        self._connector_id = validate_id(str(connector_id), "connector_id")
        self.display_name = str(display_name or self._connector_id)
        self._capabilities = frozenset(capabilities or ())
        self._tenant_id = tenant_id
        self._family = family
        self._last_error: Optional[str] = None
        self.credential_provider = None

        self._state = ConnectorState.CREATED
        self._lock = threading.RLock()

    @property
    def state(self) -> ConnectorState:
        with self._lock:
            return self._state

    def _set_state(
        self,
        state: ConnectorState,
    ) -> None:
        with self._lock:
            self._state = state

    # --- legacy operation surface (kept for connectors written against it) ---
    def authenticate(
        self,
        account: ConnectorAccount,
    ) -> ConnectorResult:
        raise ConnectorNotSupported(
            "authenticate() not implemented."
        )

    def health(
        self,
        account: ConnectorAccount,
    ) -> ConnectorHealth:
        raise ConnectorNotSupported(
            "health() not implemented."
        )

    def discover(
        self,
        account: ConnectorAccount,
    ) -> ConnectorResult:
        raise ConnectorNotSupported(
            "discover() not implemented."
        )

    def read(
        self,
        account: ConnectorAccount,
        resource: Optional[str] = None,
        *,
        cursor: Optional[str] = None,
    ) -> ConnectorResult:
        raise ConnectorNotSupported(
            "read() not implemented."
        )

    def search(
        self,
        account: ConnectorAccount,
        query: str,
    ) -> ConnectorResult:
        raise ConnectorNotSupported(
            "search() not implemented."
        )

    def ingest(
        self,
        account: ConnectorAccount,
        resource: str,
        *,
        cursor: Optional[str] = None,
    ) -> ConnectorResult:
        raise ConnectorNotSupported(
            "ingest() not implemented."
        )

    def handle_webhook(
        self,
        account: ConnectorAccount,
        payload: bytes,
        headers: Mapping[str, str],
    ) -> ConnectorResult:
        raise ConnectorNotSupported(
            "handle_webhook() not implemented."
        )

    def act(
        self,
        account: ConnectorAccount,
        action: Mapping[str, Any],
    ) -> ConnectorResult:
        raise ConnectorNotSupported(
            "act() not implemented."
        )

    def verify(
        self,
        account: ConnectorAccount,
        action: Mapping[str, Any],
    ) -> ConnectorResult:
        raise ConnectorNotSupported(
            "verify() not implemented."
        )

    def rollback(
        self,
        account: ConnectorAccount,
        action: Mapping[str, Any],
    ) -> ConnectorResult:
        raise ConnectorNotSupported(
            "rollback() not implemented."
        )

    # --- capability / identity / status surface ---
    def capabilities(
        self,
    ) -> "frozenset[ConnectorCapability]":
        return self._capabilities

    def supports(
        self,
        capability: "ConnectorCapability",
    ) -> bool:
        return capability in self.capabilities()

    def _require(
        self,
        capability: "ConnectorCapability",
    ) -> None:
        if not self.supports(capability):
            raise ConnectorOperationNotSupported(
                f"Connector '{self.connector_id}' does not support "
                f"'{capability.value}'."
            )

    @property
    def connector_id(self) -> str:
        if self.config is not None:
            return self.config.connector_id
        return self._connector_id

    @property
    def family(self) -> "ConnectorFamily":
        if self.config is not None:
            return self.config.family
        return self._family

    @property
    def tenant_id(self) -> str:
        if self.config is not None:
            return self.config.tenant_id
        return self._tenant_id

    @property
    def status(self) -> "ConnectorStatus":
        with self._lock:
            return self._status

    @property
    def last_error(self) -> Optional[str]:
        with self._lock:
            return self._last_error

    def _require_ready(self) -> None:
        if self.status != ConnectorStatus.READY:
            raise ConnectorNotReadyError(
                f"Connector {self.connector_id} is not ready."
            )

    # --- lifecycle ---
    def close(self) -> None:
        with self._lock:
            if self._status in {
                ConnectorStatus.STOPPED,
                ConnectorStatus.CREATED,
            }:
                self._status = ConnectorStatus.STOPPED
                return

            self._status = ConnectorStatus.STOPPING
            try:
                self._close()
            finally:
                self._status = ConnectorStatus.STOPPED

    def _close(self) -> None:
        return None

    def initialize(self) -> None:
        with self._lock:
            if self.config is not None and not self.config.enabled:
                self._status = ConnectorStatus.STOPPED
                return

            self._status = ConnectorStatus.INITIALIZING
            try:
                self._initialize()
            except Exception as exc:
                self._last_error = f"{type(exc).__name__}: {exc}"
                self._status = ConnectorStatus.FAILED
                raise

            self._status = ConnectorStatus.READY

    def _initialize(self) -> None:
        """Optional connector-specific initialization."""
        return None

    def health_check(self) -> ConnectorHealth:
        started = time.perf_counter()

        try:
            if ConnectorCapability.HEALTH not in self.capabilities():
                return ConnectorHealth(
                    connector_id=self.connector_id,
                    status=self.status,
                    checked_at=utc_now(),
                    latency_ms=(time.perf_counter() - started) * 1000,
                    message="Health capability not implemented.",
                )

            message = self._health_check()

            return ConnectorHealth(
                connector_id=self.connector_id,
                status=self.status,
                checked_at=utc_now(),
                latency_ms=(time.perf_counter() - started) * 1000,
                message=message,
            )

        except Exception as exc:
            with self._lock:
                self._last_error = f"{type(exc).__name__}: {exc}"
                self._status = ConnectorStatus.FAILED

            return ConnectorHealth(
                connector_id=self.connector_id,
                status=ConnectorStatus.FAILED,
                checked_at=utc_now(),
                latency_ms=(time.perf_counter() - started) * 1000,
                message=str(exc),
            )

    def _health_check(self) -> Optional[str]:
        return "connector-ready"

    # --- data / action operations ---
    def execute_action(
        self,
        action: ConnectorAction,
        parameters: Mapping[str, Any],
    ) -> Mapping[str, Any]:
        if ConnectorCapability.ACTION not in self.capabilities():
            raise ConnectorCapabilityError(
                f"{self.connector_id} does not support actions"
            )
        raise NotImplementedError

    def poll(
        self,
        *,
        cursor: Optional[str] = None,
    ) -> ConnectorResult:
        self._require_ready()
        if ConnectorCapability.POLL not in self.capabilities():
            raise ConnectorCapabilityError(
                "Connector does not support POLL."
            )
        return self._poll(cursor=cursor)

    def _poll(
        self,
        *,
        cursor: Optional[str] = None,
    ) -> ConnectorResult:
        raise ConnectorCapabilityError(
            "POLL capability declared without implementation."
        )

    def _read(
        self,
        *,
        cursor: Optional[str] = None,
    ) -> ConnectorResult:
        raise ConnectorCapabilityError(
            "READ capability declared without implementation."
        )

    def stream(
        self,
        *,
        cursor: Optional[str] = None,
    ) -> Iterator[ConnectorEvent]:
        self._require_ready()
        if ConnectorCapability.STREAM not in self.capabilities():
            raise ConnectorCapabilityError(
                "Connector does not support STREAM."
            )
        yield from self._stream(cursor=cursor)

    def _stream(
        self,
        *,
        cursor: Optional[str] = None,
    ) -> Iterator[ConnectorEvent]:
        raise ConnectorCapabilityError(
            "STREAM capability declared without implementation."
        )

    def _resolve_credentials(self) -> Mapping[str, str]:
        reference = (
            self.config.credential_reference
            if self.config is not None
            else None
        )

        if reference is None:
            return {}

        provider = self.credential_provider
        if provider is None:
            raise ConnectorAuthenticationError(
                "No credential provider configured."
            )

        return provider.resolve(reference)


# =============================================================================
# CONNECTOR REGISTRY
# =============================================================================

class CyberConnectorRegistry:

    def __init__(self) -> None:
        self._lock = threading.RLock()

        self._connectors: Dict[
            str,
            CyberConnector,
        ] = {}

    def register(
        self,
        connector: CyberConnector,
    ) -> None:
        with self._lock:
            if connector.connector_id in (
                self._connectors
            ):
                raise ValueError(
                    f"Connector already registered: "
                    f"{connector.connector_id}"
                )

            self._connectors[
                connector.connector_id
            ] = ConnectorRegistration(connector=connector)

    def get(
        self,
        connector_id: str,
    ) -> CyberConnector:
        with self._lock:
            registration = self._connectors.get(
                connector_id
            )

        if registration is None:
            raise ConnectorError(
                f"Unknown connector: {connector_id}"
            )

        return registration.connector

    def list(self) -> List[str]:
        with self._lock:
            return sorted(
                self._connectors.keys()
            )
    def disable(
        self,
        connector_id: str,
    ) -> None:
        with self._lock:
            registration = self._connectors.get(connector_id)
            if registration is None:
                raise ConnectorNotFoundError(connector_id)
            registration.status = ConnectorStatus.DISABLED

    def enable(
        self,
        connector_id: str,
    ) -> None:
        with self._lock:
            registration = self._connectors.get(connector_id)
            if registration is None:
                raise ConnectorNotFoundError(connector_id)
            if registration.status == ConnectorStatus.DISABLED:
                registration.status = ConnectorStatus.REGISTERED

    def health(
        self,
        account: ConnectorAccount,
    ) -> ConnectorHealth:
        # NOTE(auto-repair): this used to call assert_connector_tenant(),
        # which is defined much later in the file (past the point where a
        # second, independently-merged system begins and starts requiring
        # pydantic). That made this method's behavior depend on unrelated
        # code loading successfully. Inlined the same simple check here
        # instead, since it only needs TenantIsolationError, which is
        # already defined earlier in this same module.
        if not account.tenant_id.strip():
            raise TenantIsolationError(
                "Connector account has no tenant."
            )

        connector = self.get(account.connector_id)

        with self._lock:
            registration = self._connectors.get(account.connector_id)
            if registration is None:
                raise ConnectorNotFoundError(account.connector_id)

            if registration.status == ConnectorStatus.DISABLED:
                result = ConnectorHealth(
                    connector_id=connector.connector_id,
                    status=ConnectorStatus.DISABLED,
                    checked_at=iso_now_v2(),
                    message="Connector is disabled.",
                )
            else:
                try:
                    result = connector.health(account)
                except Exception:
                    LOGGER.exception(
                        "Connector health check failed: %s",
                        connector.connector_id,
                    )
                    result = ConnectorHealth(
                        connector_id=connector.connector_id,
                        status=ConnectorStatus.FAILED,
                        checked_at=iso_now_v2(),
                        message="Health check failed.",
                    )

            registration.last_health = result
            registration.status = result.status
            return result


