# CONNECTOR MANAGER
# =============================================================================

@dataclass
class ConnectorRuntime:
    connector: CyberConnector
    account: ConnectorAccount
    connected_at: str = ""
    last_health: Optional[
        ConnectorHealth
    ] = None


class CyberConnectorManager:

    def __init__(
        self,
        registry: CyberConnectorRegistry,
    ) -> None:
        self.registry = registry

        self._lock = threading.RLock()

        self._runtime: Dict[
            Tuple[str, str],
            ConnectorRuntime,
        ] = {}

    def connect(
        self,
        tenant: CyberFabricTenant,
        account: ConnectorAccount,
    ) -> ConnectorRuntime:

        assert_tenant(
            tenant,
            account.tenant_id,
        )

        connector = self.registry.get(
            account.account_id.split(":", 1)[0]
            if ":" in account.account_id
            else account.account_id
        )

        # The account ID may not necessarily equal connector ID.
        # The explicit metadata route is preferred.
        connector_id = account.metadata.get(
            "connector_id"
        )

        if connector_id:
            connector = self.registry.get(
                str(connector_id)
            )

        connector._set_state(
            ConnectorState.CONNECTING
        )

        result = connector.authenticate(
            account
        )

        if result.status != (
            CapabilityStatus.SUPPORTED
        ):
            connector._set_state(
                ConnectorState.FAILED
            )

            raise ConnectorError(
                result.message
                or "Connector authentication failed."
            )

        connector._set_state(
            ConnectorState.CONNECTED
        )

        runtime = ConnectorRuntime(
            connector=connector,
            account=account,
            connected_at=iso_now(),
        )

        with self._lock:
            self._runtime[
                (
                    connector.connector_id,
                    account.account_id,
                )
            ] = runtime

        return runtime

    def get_runtime(
        self,
        tenant: CyberFabricTenant,
        connector_id: str,
        account_id: str,
    ) -> ConnectorRuntime:

        validate_id(
            connector_id,
            "connector_id",
        )

        validate_id(
            account_id,
            "account_id",
        )

        with self._lock:
            runtime = self._runtime.get(
                (
                    connector_id,
                    account_id,
                )
            )

        if runtime is None:
            raise ConnectorError(
                "Connector runtime is not connected."
            )

        assert_tenant(
            tenant,
            runtime.account.tenant_id,
        )

        return runtime
    # [auto-repair] removed incremental_sync() -- merge artifact
    # referencing self.fabric (a CyberDataFabric instance), which this
    # class never constructs or receives (only self.registry exists).
    # Would have raised AttributeError on first call. Wiring a real
    # CyberDataFabric dependency into this class is a legitimate feature
    # (would also unblock CyberDataFabric.ingest_batch below), but it's a
    # constructor/design change, not a one-line fix -- flagging for your
    # call rather than guessing at the wiring.
    # --- preserved from CyberConnectorManager (merged, not present in canonical host) ---
    def health(
        self,
        account: ConnectorAccount,
    ) -> ConnectorHealth:

        return self.registry.health(
            account
        )
    # --- preserved from CyberConnectorManager (merged, not present in canonical host) ---
    def ingest(
        self,
        account: ConnectorAccount,
        payload: Mapping[str, Any],
    ) -> Sequence[ConnectorRecord]:

        assert_connector_tenant(
            account
        )

        connector = self.registry.get(
            account.connector_id
        )

        return connector.ingest(
            account,
            payload,
        )
    # --- preserved from CyberConnectorManager (merged, not present in canonical host) ---
    def read(
        self,
        account: ConnectorAccount,
        cursor: Optional[str] = None,
    ) -> Sequence[ConnectorRecord]:

        assert_connector_tenant(
            account
        )

        connector = self.registry.get(
            account.connector_id
        )

        return connector.read(
            account,
            cursor,
        )


# =============================================================================
# SQLITE STORAGE INITIALIZATION
# =============================================================================

def initialize_data_fabric_db(
    connection: sqlite3.Connection,
) -> None:
    """
    Create Phase-2 durable local storage.

    Production deployment can replace this backend with PostgreSQL without
    changing the contracts/pipeline.
    """

    connection.execute(
        "PRAGMA foreign_keys = ON"
    )

    connection.execute(
        "PRAGMA journal_mode = WAL"
    )

    connection.execute(
        """
        CREATE TABLE IF NOT EXISTS cyber_telemetry (
            record_id TEXT PRIMARY KEY,
            tenant_id TEXT NOT NULL,
            connector_id TEXT NOT NULL,
            source TEXT NOT NULL,
            source_record_type TEXT NOT NULL,
            source_record_id TEXT,
            observed_at TEXT NOT NULL,
            event_id TEXT,
            state TEXT NOT NULL,
            schema_version TEXT NOT NULL,
            idempotency_key TEXT,
            content_hash TEXT NOT NULL,
            normalized_json TEXT NOT NULL,
            raw_payload_json TEXT NOT NULL,
            enrichment_json TEXT NOT NULL,
            entity_refs_json TEXT NOT NULL,
            context_json TEXT NOT NULL,
            correlation_refs_json TEXT NOT NULL,
            lineage_json TEXT NOT NULL,
            created_at TEXT NOT NULL,
            ingested_at TEXT
        )
        """
    )

    connection.execute(
        """
        CREATE INDEX IF NOT EXISTS
        idx_cyber_telemetry_tenant_time
        ON cyber_telemetry (
            tenant_id,
            observed_at
        )
        """
    )

    connection.execute(
        """
        CREATE INDEX IF NOT EXISTS
        idx_cyber_telemetry_source
        ON cyber_telemetry (
            tenant_id,
            connector_id,
            source_record_id
        )
        """
    )

    connection.execute(
        """
        CREATE INDEX IF NOT EXISTS
        idx_cyber_telemetry_hash
        ON cyber_telemetry (
            tenant_id,
            content_hash
        )
        """
    )

    connection.execute(
        """
        CREATE TABLE IF NOT EXISTS cyber_idempotency (
            tenant_id TEXT NOT NULL,
            idempotency_key TEXT NOT NULL,
            record_id TEXT NOT NULL,
            status TEXT NOT NULL,
            created_at TEXT NOT NULL,
            completed_at TEXT,
            PRIMARY KEY (
                tenant_id,
                idempotency_key
            )
        )
        """
    )

    connection.execute(
        """
        CREATE TABLE IF NOT EXISTS cyber_dead_letters (
            dead_letter_id TEXT PRIMARY KEY,
            tenant_id TEXT NOT NULL,
            record_id TEXT NOT NULL,
            connector_id TEXT NOT NULL,
            reason TEXT NOT NULL,
            raw_payload_json TEXT NOT NULL,
            created_at TEXT NOT NULL,
            replay_count INTEGER NOT NULL DEFAULT 0
        )
        """
    )

    connection.execute(
        """
        CREATE INDEX IF NOT EXISTS
        idx_cyber_dead_letter_tenant
        ON cyber_dead_letters (
            tenant_id,
            created_at
        )
        """
    )

    connection.execute(
        """
        CREATE TABLE IF NOT EXISTS cyber_checkpoints (
            tenant_id TEXT NOT NULL,
            connector_id TEXT NOT NULL,
            account_id TEXT NOT NULL,
            cursor TEXT,
            watermark TEXT,
            updated_at TEXT NOT NULL,
            PRIMARY KEY (
                tenant_id,
                connector_id,
                account_id
            )
        )
        """
    )

    connection.execute(
        """
        CREATE TABLE IF NOT EXISTS cyber_event_journal (
            sequence INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id TEXT NOT NULL,
            tenant_id TEXT NOT NULL,
            event_type TEXT NOT NULL,
            timestamp TEXT NOT NULL,
            payload_json TEXT NOT NULL,
            replayed INTEGER NOT NULL DEFAULT 0
        )
        """
    )

    connection.execute(
        """
        CREATE INDEX IF NOT EXISTS
        idx_cyber_event_journal_tenant
        ON cyber_event_journal (
            tenant_id,
            sequence
        )
        """
    )

    connection.execute(
        """
        CREATE TABLE IF NOT EXISTS cyber_observability (
            metric_id TEXT PRIMARY KEY,
            tenant_id TEXT,
            metric_name TEXT NOT NULL,
            value REAL NOT NULL,
            dimensions_json TEXT NOT NULL,
            created_at TEXT NOT NULL
        )
        """
    )

    connection.commit()


# =============================================================================
# TELEMETRY STORE
# =============================================================================

class CyberTelemetryStore:

    def __init__(
        self,
        connection: sqlite3.Connection,
    ) -> None:
        self.connection = connection
        self._lock = threading.RLock()

    def insert(
        self,
        tenant: CyberFabricTenant,
        record: CyberTelemetry,
    ) -> None:

        assert_tenant(
            tenant,
            record.tenant_id,
        )

        with self._lock:
            self.connection.execute(
                """
                INSERT INTO cyber_telemetry (
                    record_id,
                    tenant_id,
                    connector_id,
                    source,
                    source_record_type,
                    source_record_id,
                    observed_at,
                    event_id,
                    state,
                    schema_version,
                    idempotency_key,
                    content_hash,
                    normalized_json,
                    raw_payload_json,
                    enrichment_json,
                    entity_refs_json,
                    context_json,
                    correlation_refs_json,
                    lineage_json,
                    created_at,
                    ingested_at
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                        ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    record.record_id,
                    record.tenant_id,
                    record.connector_id,
                    record.source,
                    record.source_record_type,
                    record.source_record_id,
                    record.observed_at,
                    record.event_id,
                    record.state.value,
                    record.schema_version,
                    record.idempotency_key,
                    record.content_hash,
                    canonical_json_v2(
                        record.normalized
                    ),
                    canonical_json_v2(
                        record.raw_payload
                    ),
                    canonical_json_v2(
                        record.enrichment
                    ),
                    canonical_json_v2(
                        record.entity_refs
                    ),
                    canonical_json_v2(
                        record.context
                    ),
                    canonical_json_v2(
                        record.correlation_refs
                    ),
                    canonical_json_v2(
                        record.lineage.to_dict()
                    ),
                    record.created_at,
                    record.ingested_at,
                ),
            )

            self.connection.commit()

    def get(
        self,
        tenant: CyberFabricTenant,
        record_id: str,
    ) -> Optional[CyberTelemetry]:

        validate_id(
            record_id,
            "record_id",
        )

        with self._lock:
            row = self.connection.execute(
                """
                SELECT *
                FROM cyber_telemetry
                WHERE record_id = ?
                """,
                (record_id,),
            ).fetchone()

        if row is None:
            return None

        # [BUGFIX — integration/hardening pass] same off-by-one as query() below:
        # PRAGMA table_info's first field is the ordinal cid, not the name.
        columns = [
            item[1]
            for item in self.connection.execute(
                "PRAGMA table_info(cyber_telemetry)"
            ).fetchall()
        ]

        data = dict(
            zip(columns, row)
        )

        assert_tenant(
            tenant,
            data["tenant_id"],
        )

        return self._row_to_record(data)

    def query(
        self,
        tenant: CyberFabricTenant,
        *,
        connector_id: Optional[str] = None,
        source_record_type: Optional[str] = None,
        limit: int = 100,
    ) -> List[CyberTelemetry]:

        if limit <= 0:
            return []

        clauses = [
            "tenant_id = ?"
        ]

        params: List[Any] = [
            tenant.tenant_id
        ]

        if connector_id:
            clauses.append(
                "connector_id = ?"
            )
            params.append(
                connector_id
            )

        if source_record_type:
            clauses.append(
                "source_record_type = ?"
            )
            params.append(
                source_record_type
            )

        params.append(limit)

        sql = f"""
            SELECT *
            FROM cyber_telemetry
            WHERE {' AND '.join(clauses)}
            ORDER BY observed_at DESC
            LIMIT ?
        """

        with self._lock:
            rows = self.connection.execute(
                sql,
                tuple(params),
            ).fetchall()

            # [BUGFIX — integration/hardening pass] PRAGMA table_info returns rows
            # shaped (cid, name, type, notnull, dflt_value, pk); item[0] is the
            # ordinal position (0,1,2,...), not the column name. Using item[0] built
            # a columns list of bare integers, so dict(zip(columns, row)) produced
            # {0: val, 1: val, ...} instead of {"tenant_id": val, ...}, and every
            # data["tenant_id"] lookup below raised KeyError. item[1] is the name.
            columns = [
                item[1]
                for item in self.connection.execute(
                    "PRAGMA table_info(cyber_telemetry)"
                ).fetchall()
            ]

        result: List[
            CyberTelemetry
        ] = []

        for row in rows:
            data = dict(
                zip(columns, row)
            )

            # Defensive second tenant check.
            assert_tenant(
                tenant,
                data["tenant_id"],
            )

            result.append(
                self._row_to_record(data)
            )

        return result

    @staticmethod
    def _row_to_record(
        data: Mapping[str, Any],
    ) -> CyberTelemetry:

        lineage = Lineage()

        for item in json.loads(
            data["lineage_json"]
        ):
            lineage.add(
                LineageStage(
                    item["stage"]
                ),
                actor=item["actor"],
                details=item.get(
                    "details",
                    {},
                ),
            )

        return CyberTelemetry(
            record_id=data["record_id"],
            tenant_id=data["tenant_id"],
            connector_id=data["connector_id"],
            source=data["source"],
            source_record_type=data[
                "source_record_type"
            ],
            source_record_id=(
                data["source_record_id"]
                or ""
            ),
            observed_at=data["observed_at"],
            event_id=data["event_id"] or "",
            state=RecordState(
                data["state"]
            ),
            schema_version=data[
                "schema_version"
            ],
            idempotency_key=(
                data["idempotency_key"]
                or ""
            ),
            content_hash=data[
                "content_hash"
            ],
            normalized=json.loads(
                data["normalized_json"]
            ),
            raw_payload=json.loads(
                data["raw_payload_json"]
            ),
            enrichment=json.loads(
                data["enrichment_json"]
            ),
            entity_refs=json.loads(
                data["entity_refs_json"]
            ),
            context=json.loads(
                data["context_json"]
            ),
            correlation_refs=json.loads(
                data["correlation_refs_json"]
            ),
            lineage=lineage,
            created_at=data["created_at"],
            ingested_at=(
                data["ingested_at"]
                or ""
            ),
        )
    # --- preserved from CyberTelemetryStore (merged, not present in canonical host) ---
    @staticmethod
    def _provenance_json(
        provenance: Sequence[ProvenanceRef],
    ) -> str:

        return canonical_json_v3(
            [
                {
                    "source_type": item.source_type,
                    "source_id": item.source_id,
                    "source_record_id": item.source_record_id,
                    "observed_at": item.observed_at,
                    "metadata": dict(item.metadata),
                }
                for item in provenance
            ]
        )
    # --- preserved from CyberTelemetryStore (merged, not present in canonical host) ---
    def list(
        self,
        context: CyberTenantContext,
        *,
        limit: int = 100,
    ) -> List[CyberTelemetry]:

        if limit <= 0:
            raise ValueError(
                "limit must be greater than zero"
            )

        with self._lock:
            rows = self.connection.execute(
                """
                SELECT
                    record_id,
                    tenant_id,
                    source,
                    source_event_id,
                    event_type,
                    observed_at,
                    received_at,
                    schema_name,
                    schema_version,
                    fingerprint,
                    state,
                    correlation_id,
                    causation_id,
                    payload_json,
                    provenance_json,
                    entity_refs_json,
                    metadata_json
                FROM cyber_telemetry
                WHERE tenant_id=?
                ORDER BY observed_at ASC
                LIMIT ?
                """,
                (
                    context.tenant_id,
                    limit,
                ),
            ).fetchall()

        return [
            self._row_to_record(row)
            for row in rows
        ]
    # --- preserved from CyberTelemetryStore (merged, not present in canonical host) ---
    def save(
        self,
        context: CyberTenantContext,
        record: CyberTelemetry,
    ) -> bool:

        assert_tenant(
            context,
            record.tenant_id,
        )

        with self._lock:
            try:
                self.connection.execute(
                    """
                    INSERT INTO cyber_telemetry (
                        record_id,
                        tenant_id,
                        source,
                        source_event_id,
                        event_type,
                        observed_at,
                        received_at,
                        schema_name,
                        schema_version,
                        fingerprint,
                        state,
                        correlation_id,
                        causation_id,
                        payload_json,
                        provenance_json,
                        entity_refs_json,
                        metadata_json
                    )
                    VALUES (
                        ?, ?, ?, ?, ?, ?, ?, ?,
                        ?, ?, ?, ?, ?, ?, ?, ?, ?
                    )
                    """,
                    (
                        record.record_id,
                        record.tenant_id,
                        record.source,
                        record.source_event_id,
                        record.event_type,
                        record.observed_at,
                        record.received_at,
                        record.schema_name,
                        record.schema_version,
                        record.fingerprint,
                        record.state.value,
                        record.correlation_id,
                        record.causation_id,
                        json.dumps(
                            dict(record.payload),
                            sort_keys=True,
                            default=str,
                        ),
                        json.dumps(
                            [
                                item.to_dict()
                                for item in record.provenance
                            ],
                            sort_keys=True,
                            default=str,
                        ),
                        json.dumps(
                            list(record.entity_refs),
                            sort_keys=True,
                        ),
                        json.dumps(
                            dict(record.metadata),
                            sort_keys=True,
                            default=str,
                        ),
                    ),
                )

                self.connection.commit()
                return True

            except sqlite3.IntegrityError:
                self.connection.rollback()
                return False


# =============================================================================
# IDEMPOTENCY STORE
# =============================================================================

class CyberIdempotencyStore:

    def __init__(
        self,
        connection: sqlite3.Connection,
    ) -> None:
        self.connection = connection
        self._lock = threading.RLock()
        # Reconcile legacy idempotency schemas before use. Older merged
        # definitions omitted status/completed_at, while the canonical store
        # contract requires them.
        columns = {row[1] for row in self.connection.execute("PRAGMA table_info(cyber_idempotency)").fetchall()}
        if "status" not in columns:
            self.connection.execute("ALTER TABLE cyber_idempotency ADD COLUMN status TEXT NOT NULL DEFAULT 'PROCESSING'")
        if "completed_at" not in columns:
            self.connection.execute("ALTER TABLE cyber_idempotency ADD COLUMN completed_at TEXT")
        self.connection.commit()

    def get(
        self,
        tenant: CyberFabricTenant,
        key: str,
    ) -> Optional[Dict[str, Any]]:

        validate_id(
            key,
            "idempotency_key",
        )

        with self._lock:
            row = self.connection.execute(
                """
                SELECT
                    record_id,
                    status,
                    created_at,
                    completed_at
                FROM cyber_idempotency
                WHERE tenant_id = ?
                  AND idempotency_key = ?
                """,
                (
                    tenant.tenant_id,
                    key,
                ),
            ).fetchone()

        if row is None:
            return None

        return {
            "record_id": row[0],
            "status": row[1],
            "created_at": row[2],
            "completed_at": row[3],
        }

    def begin(
        self,
        tenant: CyberFabricTenant,
        key: str,
        record_id: str,
    ) -> bool:

        validate_id(
            key,
            "idempotency_key",
        )

        validate_id(
            record_id,
            "record_id",
        )

        with self._lock:
            try:
                self.connection.execute(
                    """
                    INSERT INTO cyber_idempotency (
                        tenant_id,
                        idempotency_key,
                        record_id,
                        status,
                        created_at
                    )
                    VALUES (?, ?, ?, ?, ?)
                    """,
                    (
                        tenant.tenant_id,
                        key,
                        record_id,
                        "PROCESSING",
                        iso_now(),
                    ),
                )

                self.connection.commit()
                return True

            except sqlite3.IntegrityError:
                self.connection.rollback()
                return False

    def complete(
        self,
        tenant: CyberFabricTenant,
        key: str,
        record_id: str,
    ) -> None:

        assert_tenant(
            tenant,
            tenant.tenant_id,
        )

        with self._lock:
            self.connection.execute(
                """
                UPDATE cyber_idempotency
                SET
                    status = ?,
                    record_id = ?,
                    completed_at = ?
                WHERE tenant_id = ?
                  AND idempotency_key = ?
                """,
                (
                    "COMPLETED",
                    record_id,
                    iso_now(),
                    tenant.tenant_id,
                    key,
                ),
            )

            self.connection.commit()
    # --- preserved from CyberIdempotencyStore (merged, not present in canonical host) ---
    def claim(
        self,
        context: CyberTenantContext,
        idempotency_key: str,
        record_id: str,
    ) -> bool:

        if not idempotency_key.strip():
            raise ValueError(
                "idempotency_key cannot be empty"
            )

        with self._lock:
            try:
                self.connection.execute(
                    """
                    INSERT INTO cyber_idempotency (
                        tenant_id,
                        idempotency_key,
                        record_id,
                        created_at
                    )
                    VALUES (?, ?, ?, ?)
                    """,
                    (
                        context.tenant_id,
                        idempotency_key,
                        record_id,
                        iso_now(),
                    ),
                )

                self.connection.commit()
                return True

            except sqlite3.IntegrityError:
                self.connection.rollback()
                return False
    # --- preserved from CyberIdempotencyStore (merged, not present in canonical host) ---
    def get_record_id(
        self,
        context: CyberTenantContext,
        idempotency_key: str,
    ) -> Optional[str]:

        with self._lock:
            row = self.connection.execute(
                """
                SELECT record_id
                FROM cyber_idempotency
                WHERE tenant_id=?
                  AND idempotency_key=?
                """,
                (
                    context.tenant_id,
                    idempotency_key,
                ),
            ).fetchone()

        return None if row is None else str(row[0])


# =============================================================================
# DEAD LETTER STORE
# =============================================================================

@dataclass(frozen=True)
class DeadLetter:
    dead_letter_id: str
    tenant_id: str
    record_id: str
    connector_id: str
    reason: str
    raw_payload: Mapping[str, Any]
    created_at: str
    replay_count: int = 0


class CyberDeadLetterStore:

    def __init__(
        self,
        connection: sqlite3.Connection,
    ) -> None:
        self.connection = connection
        self._lock = threading.RLock()
        columns = {row[1] for row in self.connection.execute("PRAGMA table_info(cyber_dead_letters)").fetchall()}
        additions = {
            "connector_id": "TEXT NOT NULL DEFAULT ''",
            "reason": "TEXT NOT NULL DEFAULT ''",
            "raw_payload_json": "TEXT NOT NULL DEFAULT '{}'",
            "raw_payload": "TEXT NOT NULL DEFAULT '{}'",
            "replay_count": "INTEGER NOT NULL DEFAULT 0",
        }
        for column, definition in additions.items():
            if column not in columns:
                self.connection.execute(f"ALTER TABLE cyber_dead_letters ADD COLUMN {column} {definition}")
        self.connection.commit()

    def add(
        self,
        tenant: CyberFabricTenant,
        record_id: str,
        connector_id: str,
        reason: str,
        raw_payload: Mapping[str, Any],
    ) -> DeadLetter:

        assert_tenant(
            tenant,
            tenant.tenant_id,
        )

        item = DeadLetter(
            dead_letter_id=make_id("dlq"),
            tenant_id=tenant.tenant_id,
            record_id=record_id,
            connector_id=connector_id,
            reason=str(reason),
            raw_payload=deep_copy(
                raw_payload
            ),
            created_at=iso_now(),
        )

        with self._lock:
            # NOTE(auto-repair): this table name (cyber_dead_letters) is
            # shared with a second, independently-written store
            # (SQLiteDeadLetterStore) whose schema uses a plain
            # `raw_payload TEXT NOT NULL` column with no DEFAULT, instead of
            # this class's `raw_payload_json`. Whichever store's CREATE
            # TABLE runs first wins, so if the other store created the
            # table, this INSERT (which never mentioned `raw_payload`) left
            # it NULL and violated that NOT NULL constraint. This class's
            # own __init__ already self-heals by adding both
            # raw_payload_json and raw_payload columns if missing, so the
            # INSERT below now always populates both, regardless of which
            # store created the table first.
            payload_json = canonical_json_v2(
                item.raw_payload
            )

            self.connection.execute(
                """
                INSERT INTO cyber_dead_letters (
                    dead_letter_id,
                    tenant_id,
                    record_id,
                    connector_id,
                    reason,
                    raw_payload_json,
                    raw_payload,
                    created_at,
                    replay_count
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    item.dead_letter_id,
                    item.tenant_id,
                    item.record_id,
                    item.connector_id,
                    item.reason,
                    payload_json,
                    payload_json,
                    item.created_at,
                    item.replay_count,
                ),
            )

            self.connection.commit()

        return item

    def list(
        self,
        tenant: CyberFabricTenant,
        *,
        limit: int = 100,
    ) -> List[DeadLetter]:

        with self._lock:
            rows = self.connection.execute(
                """
                SELECT
                    dead_letter_id,
                    tenant_id,
                    record_id,
                    connector_id,
                    reason,
                    raw_payload_json,
                    created_at,
                    replay_count
                FROM cyber_dead_letters
                WHERE tenant_id = ?
                ORDER BY created_at DESC
                LIMIT ?
                """,
                (
                    tenant.tenant_id,
                    limit,
                ),
            ).fetchall()

        result: List[DeadLetter] = []

        for row in rows:
            assert_tenant(
                tenant,
                row[1],
            )

            result.append(
                DeadLetter(
                    dead_letter_id=row[0],
                    tenant_id=row[1],
                    record_id=row[2],
                    connector_id=row[3],
                    reason=row[4],
                    raw_payload=json.loads(
                        row[5]
                    ),
                    created_at=row[6],
                    replay_count=row[7],
                )
            )

        return result

    def mark_replayed(
        self,
        tenant: CyberFabricTenant,
        dead_letter_id: str,
    ) -> None:

        with self._lock:
            self.connection.execute(
                """
                UPDATE cyber_dead_letters
                SET replay_count = replay_count + 1
                WHERE dead_letter_id = ?
                  AND tenant_id = ?
                """,
                (
                    dead_letter_id,
                    tenant.tenant_id,
                ),
            )

            self.connection.commit()


