# CHECKPOINT STORE
# =============================================================================

@dataclass(frozen=True)
class CyberCheckpoint:
    tenant_id: str
    connector_id: str
    account_id: str
    cursor: str = ""
    watermark: str = ""
    updated_at: str = field(
        default_factory=iso_now
    )


class CyberCheckpointStore:

    def __init__(
        self,
        connection: sqlite3.Connection,
    ) -> None:
        self.connection = connection
        self._lock = threading.RLock()

    def get(
        self,
        tenant: CyberFabricTenant,
        connector_id: str,
        account_id: str,
    ) -> Optional[CyberCheckpoint]:

        with self._lock:
            row = self.connection.execute(
                """
                SELECT
                    tenant_id,
                    connector_id,
                    account_id,
                    cursor,
                    watermark,
                    updated_at
                FROM cyber_checkpoints
                WHERE tenant_id = ?
                  AND connector_id = ?
                  AND account_id = ?
                """,
                (
                    tenant.tenant_id,
                    connector_id,
                    account_id,
                ),
            ).fetchone()

        if row is None:
            return None

        assert_tenant(
            tenant,
            row[0],
        )

        return CyberCheckpoint(
            tenant_id=row[0],
            connector_id=row[1],
            account_id=row[2],
            cursor=row[3] or "",
            watermark=row[4] or "",
            updated_at=row[5],
        )

    def save(
        self,
        tenant: CyberFabricTenant,
        checkpoint: CyberCheckpoint,
    ) -> None:

        assert_tenant(
            tenant,
            checkpoint.tenant_id,
        )

        with self._lock:
            self.connection.execute(
                """
                INSERT INTO cyber_checkpoints (
                    tenant_id,
                    connector_id,
                    account_id,
                    cursor,
                    watermark,
                    updated_at
                )
                VALUES (?, ?, ?, ?, ?, ?)
                ON CONFLICT (
                    tenant_id,
                    connector_id,
                    account_id
                )
                DO UPDATE SET
                    cursor = excluded.cursor,
                    watermark = excluded.watermark,
                    updated_at = excluded.updated_at
                """,
                (
                    checkpoint.tenant_id,
                    checkpoint.connector_id,
                    checkpoint.account_id,
                    checkpoint.cursor,
                    checkpoint.watermark,
                    checkpoint.updated_at,
                ),
            )

            self.connection.commit()


# =============================================================================
# EVENT JOURNAL
# =============================================================================

class CyberEventJournal:

    def __init__(
        self,
        connection: sqlite3.Connection,
    ) -> None:
        self.connection = connection
        self._lock = threading.RLock()

    def append(
        self,
        tenant: CyberFabricTenant,
        event: Mapping[str, Any],
    ) -> int:

        event_tenant = event.get(
            "tenant_id"
        )

        if event_tenant is None:
            raise ValueError(
                "Event requires tenant_id."
            )

        assert_tenant(
            tenant,
            str(event_tenant),
        )

        with self._lock:
            cursor = self.connection.execute(
                """
                INSERT INTO cyber_event_journal (
                    event_id,
                    tenant_id,
                    event_type,
                    timestamp,
                    payload_json
                )
                VALUES (?, ?, ?, ?, ?)
                """,
                (
                    str(
                        event["event_id"]
                    ),
                    str(
                        event["tenant_id"]
                    ),
                    str(
                        event["event_type"]
                    ),
                    str(
                        event["timestamp"]
                    ),
                    canonical_json_v2(
                        event.get(
                            "payload",
                            {},
                        )
                    ),
                ),
            )

            self.connection.commit()

            return int(
                cursor.lastrowid
            )

    def read(
        self,
        tenant: CyberFabricTenant,
        *,
        after_sequence: int = 0,
        limit: int = 100,
    ) -> List[Dict[str, Any]]:

        with self._lock:
            rows = self.connection.execute(
                """
                SELECT
                    sequence,
                    event_id,
                    tenant_id,
                    event_type,
                    timestamp,
                    payload_json,
                    replayed
                FROM cyber_event_journal
                WHERE tenant_id = ?
                  AND sequence > ?
                ORDER BY sequence ASC
                LIMIT ?
                """,
                (
                    tenant.tenant_id,
                    after_sequence,
                    limit,
                ),
            ).fetchall()

        result = []

        for row in rows:
            assert_tenant(
                tenant,
                row[2],
            )

            result.append(
                {
                    "sequence": row[0],
                    "event_id": row[1],
                    "tenant_id": row[2],
                    "event_type": row[3],
                    "timestamp": row[4],
                    "payload": json.loads(
                        row[5]
                    ),
                    "replayed": bool(
                        row[6]
                    ),
                }
            )

        return result
    # --- preserved from CyberEventJournal (merged, not present in canonical host) ---
    def replay(
        self,
        context: CyberTenantContext,
        *,
        after_sequence: int = 0,
        limit: int = 1000,
    ) -> List[CyberEvent]:

        limit = max(1, min(int(limit), 10_000))

        with self._lock:

            rows = self.connection.execute(
                """
                SELECT sequence,
                       event_id,
                       tenant_id,
                       event_type,
                       timestamp,
                       source,
                       source_event_id,
                       request_id,
                       correlation_id,
                       causation_id,
                       schema_version,
                       entity_refs_json,
                       provenance_json,
                       payload_json
                FROM cyber_event_journal
                WHERE tenant_id=?
                  AND sequence>?
                ORDER BY sequence ASC
                LIMIT ?
                """,
                (
                    context.tenant_id,
                    after_sequence,
                    limit,
                ),
            ).fetchall()

        return [
            self._row_to_event(row)
            for row in rows
        ]
    # --- preserved from CyberEventJournal (merged, not present in canonical host) ---
    @staticmethod
    def _row_to_event(
        row: Tuple[Any, ...],
    ) -> CyberEvent:

        provenance = tuple(
            ProvenanceRef(
                source_type=ProvenanceType(
                    item["source_type"]
                ),
                source_id=item["source_id"],
                source_record_id=item.get(
                    "source_record_id"
                ),
                observed_at=item.get(
                    "observed_at"
                ),
                metadata=item.get(
                    "metadata",
                    {},
                ),
            )
            for item in json.loads(
                row[12]
            )
        )

        return CyberEvent(
            event_id=row[1],
            tenant_id=row[2],
            event_type=EventType(row[3]),
            timestamp=row[4],
            source=row[5],
            source_event_id=row[6],
            request_id=row[7],
            correlation_id=row[8],
            causation_id=row[9],
            schema_version=row[10],
            entity_refs=tuple(
                json.loads(row[11])
            ),
            provenance=provenance,
            payload=json.loads(row[13]),
            sequence=row[0],
        )


