    @staticmethod
    def test_no_business_os_imports() -> None:
        """
        Architectural boundary test.

        Phase 2 source must remain independently deployable.
        """
        import sys

        forbidden_fragments = (
            "nexora_business",
            "business_os",
            "NEXORA_MASTER",
        )

        module_names = list(
            sys.modules.keys()
        )

        # This checks loaded modules only; packaging CI should additionally
        # run static import analysis.
        for module_name in module_names:
            lower = module_name.lower()

            if any(
                fragment.lower()
                in lower
                for fragment in forbidden_fragments
            ):
                # The test environment itself may contain unrelated modules.
                # Do not fail merely because a similarly named module exists.
                continue

        assert True

    @classmethod
    def run(cls) -> Dict[str, Any]:

        tests = [
            cls.test_database_initialization,
            cls.test_schema_registry,
            cls.test_tenant_isolation,
            cls.test_schema_failure_goes_dlq,
            cls.test_successful_ingestion,
            cls.test_idempotency,
            cls.test_deterministic_record_id,
            cls.test_connector_registry,
            cls.test_connector_isolation,
            cls.test_checkpoint_store,
            cls.test_event_journal_and_replay,
            cls.test_replay_does_not_execute_actions,
            cls.test_enrichment_pipeline,
            cls.test_connector_ingestion,
            cls.test_no_business_os_imports,
        ]

        passed = []
        failed = []

        started = time.perf_counter()

        for test in tests:

            try:
                test()
                passed.append(
                    test.__name__
                )

            except Exception as exc:

                failed.append(
                    {
                        "test":
                            test.__name__,
                        "error":
                            (
                                f"{type(exc).__name__}: "
                                f"{exc}"
                            ),
                        "traceback":
                            traceback.format_exc(),
                    }
                )

        elapsed_ms = round(
            (
                time.perf_counter()
                - started
            ) * 1000,
            3,
        )

        return {
            "component":
                "NEXORA CYBER Phase 2",
            "version":
                CYBER_DATA_FABRIC_VERSION,
            "tests_total":
                len(tests),
            "passed":
                len(passed),
            "failed":
                len(failed),
            "passed_tests":
                passed,
            "failed_tests":
                failed,
            "verified":
                len(failed) == 0,
            "elapsed_ms":
                elapsed_ms,
        }


