# [auto-repair] was a byte-for-byte duplicate of utc_now() -- consolidated to a thin alias (Repair Phase 6).
utc_now_v2 = utc_now


def iso_now_v2() -> str:
    return utc_now_v2().isoformat()


def new_id_v2(prefix: str = "id") -> str:
    return f"{prefix}_{uuid.uuid4().hex}"


def canonical_json_v3(value: Any) -> str:
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        default=str,
    )


def sha256_text(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def stable_hash(value: Any) -> str:
    return sha256_text(canonical_json_v3(value))


def bounded_text_v2(
    value: Any,
    *,
    max_chars: int = 100_000,
) -> str:
    text = str(value if value is not None else "")
    return text[:max_chars]


def clamp(
    value: Any,
    low: float = 0.0,
    high: float = 1.0,
) -> float:
    try:
        return max(low, min(high, float(value)))
    except (TypeError, ValueError):
        return low


