TENANT_RE = re.compile(r"^[A-Za-z0-9_.:-]{1,160}$")


class TenantContextError(PermissionError):
    pass




def require_tenant(
    supplied_tenant_id: str,
    context: CyberTenantContext,
) -> None:
    """
    Defense-in-depth tenant check.

    Callers must never be allowed to use an arbitrary tenant ID.
    """

    if supplied_tenant_id != context.tenant_id:
        raise TenantContextError(
            "Cross-tenant operation denied."
        )


