@dataclass(frozen=True)
class ConnectorCheckpoint:
    tenant_id: str
    connector_id: str
    cursor: Optional[str]
    updated_at: str
    account_id: str = ""
    sequence: Optional[int] = None




class SQLiteCheckpointStore:

    def __init__(self, connection: sqlite3.Connection) -> None:
        self.connection = connection
        self._lock = threading.RLock()

        self.connection.execute(
            """
            CREATE TABLE IF NOT EXISTS cyber_connector_checkpoints (
                tenant_id TEXT NOT NULL,
                connector_id TEXT NOT NULL,
                account_id TEXT NOT NULL,
                cursor TEXT,
                updated_at TEXT NOT NULL,
                PRIMARY KEY (
                    tenant_id,
                    connector_id,
                    account_id
                )
            )
            """
        )

        self.connection.commit()

    def get(
        self,
        tenant_id: str,
        connector_id: str,
        account_id: str,
    ) -> Optional[ConnectorCheckpoint]:

        with self._lock:

            row = self.connection.execute(
                """
                SELECT tenant_id,
                       connector_id,
                       account_id,
                       cursor,
                       updated_at
                FROM cyber_connector_checkpoints
                WHERE tenant_id=?
                  AND connector_id=?
                  AND account_id=?
                """,
                (
                    tenant_id,
                    connector_id,
                    account_id,
                ),
            ).fetchone()

            if row is None:
                return None

            return ConnectorCheckpoint(
                tenant_id=row[0],
                connector_id=row[1],
                account_id=row[2],
                cursor=row[3],
                updated_at=row[4],
            )

    def save(
        self,
        checkpoint: ConnectorCheckpoint,
    ) -> None:

        with self._lock:

            self.connection.execute(
                """
                INSERT INTO cyber_connector_checkpoints (
                    tenant_id,
                    connector_id,
                    account_id,
                    cursor,
                    updated_at
                )
                VALUES (?, ?, ?, ?, ?)
                ON CONFLICT (
                    tenant_id,
                    connector_id,
                    account_id
                )
                DO UPDATE SET
                    cursor=excluded.cursor,
                    updated_at=excluded.updated_at
                """,
                (
                    checkpoint.tenant_id,
                    checkpoint.connector_id,
                    checkpoint.account_id,
                    checkpoint.cursor,
                    checkpoint.updated_at,
                ),
            )

            self.connection.commit()


