class SQLiteIdempotencyStore:

    def __init__(
        self,
        connection: sqlite3.Connection,
    ) -> None:

        self.connection = connection
        self._lock = threading.RLock()

        self.connection.execute(
            """
            CREATE TABLE IF NOT EXISTS cyber_idempotency (
                tenant_id TEXT NOT NULL,
                idempotency_key TEXT NOT NULL,
                record_id TEXT NOT NULL,
                created_at TEXT NOT NULL,
                PRIMARY KEY (
                    tenant_id,
                    idempotency_key
                )
            )
            """
        )

        self.connection.commit()

    def get(
        self,
        tenant_id: str,
        key: str,
    ) -> Optional[IdempotencyRecord]:

        with self._lock:

            row = self.connection.execute(
                """
                SELECT tenant_id,
                       idempotency_key,
                       record_id,
                       created_at
                FROM cyber_idempotency
                WHERE tenant_id=?
                  AND idempotency_key=?
                """,
                (tenant_id, key),
            ).fetchone()

            if row is None:
                return None

            return IdempotencyRecord(
                tenant_id=row[0],
                key=row[1],
                record_id=row[2],
                created_at=row[3],
            )

    def put(
        self,
        record: IdempotencyRecord,
    ) -> None:

        with self._lock:

            self.connection.execute(
                """
                INSERT OR IGNORE INTO cyber_idempotency (
                    tenant_id,
                    idempotency_key,
                    record_id,
                    created_at
                )
                VALUES (?, ?, ?, ?)
                """,
                (
                    record.tenant_id,
                    record.key,
                    record.record_id,
                    record.created_at,
                ),
            )

            self.connection.commit()


