@dataclass(frozen=True)
class DeadLetterRecord:
    dead_letter_id: str
    tenant_id: str
    record_id: str
    reason: str
    raw_payload: str
    created_at: str
    source: str = None  # merged from DeadLetterRecord, made optional for safety
    error: str = None  # merged from DeadLetterRecord, made optional for safety
    payload: Mapping[str, Any] = None  # merged from DeadLetterRecord, made optional for safety


class SQLiteDeadLetterStore:

    def __init__(
        self,
        connection: sqlite3.Connection,
    ) -> None:

        self.connection = connection
        self._lock = threading.RLock()

        self.connection.execute(
            """
            CREATE TABLE IF NOT EXISTS cyber_dead_letters (
                dead_letter_id TEXT PRIMARY KEY,
                tenant_id TEXT NOT NULL,
                record_id TEXT NOT NULL,
                reason TEXT NOT NULL,
                raw_payload TEXT NOT NULL,
                created_at TEXT NOT NULL
            )
            """
        )

        self.connection.execute(
            """
            CREATE INDEX IF NOT EXISTS idx_cyber_dlq_tenant
            ON cyber_dead_letters (
                tenant_id,
                created_at DESC
            )
            """
        )

        self.connection.commit()

    def add(
        self,
        tenant_id: str,
        record_id: str,
        reason: str,
        raw_payload: Mapping[str, Any],
    ) -> DeadLetterRecord:

        result = DeadLetterRecord(
            dead_letter_id=new_id_v2("dlq"),
            tenant_id=tenant_id,
            record_id=record_id,
            reason=bounded_text_v2(reason, max_chars=4_000),
            raw_payload=canonical_json_v3(raw_payload),
            created_at=iso_now_v2(),
        )

        with self._lock:

            self.connection.execute(
                """
                INSERT INTO cyber_dead_letters (
                    dead_letter_id,
                    tenant_id,
                    record_id,
                    reason,
                    raw_payload,
                    created_at
                )
                VALUES (?, ?, ?, ?, ?, ?)
                """,
                (
                    result.dead_letter_id,
                    result.tenant_id,
                    result.record_id,
                    result.reason,
                    result.raw_payload,
                    result.created_at,
                ),
            )

            self.connection.commit()

        return result

    def list(
        self,
        context: CyberTenantContext,
        limit: int = 100,
    ) -> List[DeadLetterRecord]:

        limit = max(1, min(int(limit), 1000))

        with self._lock:

            rows = self.connection.execute(
                """
                SELECT dead_letter_id,
                       tenant_id,
                       record_id,
                       reason,
                       raw_payload,
                       created_at
                FROM cyber_dead_letters
                WHERE tenant_id=?
                ORDER BY created_at DESC
                LIMIT ?
                """,
                (
                    context.tenant_id,
                    limit,
                ),
            ).fetchall()

        return [
            DeadLetterRecord(
                dead_letter_id=row[0],
                tenant_id=row[1],
                record_id=row[2],
                reason=row[3],
                raw_payload=row[4],
                created_at=row[5],
            )
            for row in rows
        ]


