EventHandler = Callable[[CyberEvent], None]


class CyberEventBus:

    def __init__(self) -> None:
        self._subscribers: Dict[
            CyberEventType,
            List[EventHandler],
        ] = {}

        self._lock = threading.RLock()

    def subscribe(
        self,
        event_type: CyberEventType,
        handler: EventHandler,
    ) -> None:

        with self._lock:
            self._subscribers.setdefault(
                event_type,
                [],
            ).append(handler)

    def publish(
        self,
        event: CyberEvent,
    ) -> None:

        with self._lock:
            handlers = list(
                self._subscribers.get(
                    event.event_type,
                    [],
                )
            )

        for handler in handlers:
            try:
                handler(event)
            except Exception:
                # Subscriber failure must not prevent the event bus from
                # delivering the event to other subscribers.
                LOGGER.exception(
                    "Cyber event subscriber failed: %s",
                    event.event_type.value,
                )
    # --- preserved from CyberEventBus (merged, not present in canonical host) ---
    def unsubscribe(
        self,
        event_type: EventType,
        handler: EventHandler,
    ) -> None:

        with self._lock:
            handlers = self._subscribers.get(
                event_type,
                [],
            )

            if handler in handlers:
                handlers.remove(handler)


