class TelemetryTransformer(Protocol):

    def normalize(
        self,
        record: CyberTelemetry,
    ) -> CyberTelemetry:
        ...

    def enrich(
        self,
        record: CyberTelemetry,
    ) -> CyberTelemetry:
        ...

    def resolve_entities(
        self,
        record: CyberTelemetry,
    ) -> CyberTelemetry:
        ...

    def contextualize(
        self,
        record: CyberTelemetry,
    ) -> CyberTelemetry:
        ...

    def correlate(
        self,
        record: CyberTelemetry,
    ) -> CyberTelemetry:
        ...


class DefaultCyberTransformer:

    def normalize(
        self,
        record: CyberTelemetry,
    ) -> CyberTelemetry:

        payload = dict(record.payload)

        record.payload = payload
        record.state = RecordState.NORMALIZED

        record.lineage.add(
            LineageStage.NORMALIZED,
            "default_normalizer",
        )

        return record

    def enrich(
        self,
        record: CyberTelemetry,
    ) -> CyberTelemetry:

        # No fabricated threat intelligence or external enrichment.
        # This stage is deliberately deterministic until real enrichment
        # providers are attached.

        record.state = RecordState.ENRICHED

        record.lineage.add(
            LineageStage.ENRICHED,
            "default_enricher",
            enrichment_count=0,
        )

        return record

    def resolve_entities(
        self,
        record: CyberTelemetry,
    ) -> CyberTelemetry:

        refs: List[str] = list(record.entity_refs)

        for key in (
            "asset_id",
            "endpoint_id",
            "identity_id",
            "user_id",
            "device_id",
            "cloud_resource_id",
        ):

            value = record.payload.get(key)

            if value is not None:
                ref = str(value)

                if ref not in refs:
                    refs.append(ref)

        record.entity_refs = tuple(refs)
        record.state = RecordState.RESOLVED

        record.lineage.add(
            LineageStage.ENTITY_RESOLVED,
            "default_entity_resolver",
            entity_count=len(refs),
        )

        return record

    def contextualize(
        self,
        record: CyberTelemetry,
    ) -> CyberTelemetry:

        record.state = RecordState.CONTEXTUALIZED

        record.lineage.add(
            LineageStage.CONTEXTUALIZED,
            "default_contextualizer",
        )

        return record

    def correlate(
        self,
        record: CyberTelemetry,
    ) -> CyberTelemetry:

        record.state = RecordState.CORRELATED

        record.lineage.add(
            LineageStage.CORRELATED,
            "default_correlator",
        )

        return record
    # --- preserved from DefaultCyberTransformer (merged, not present in canonical host) ---
    @staticmethod
    def _with_state(
        record: CyberTelemetry,
        state: RecordState,
    ) -> CyberTelemetry:

        return CyberTelemetry(
            **{
                **record.__dict__,
                "state": state,
            }
        )


