@dataclass(frozen=True)
class DataFabricHealth:

    status: str

    schema_registry: str
    telemetry_store: str
    checkpoint_store: str
    idempotency_store: str
    dead_letter_store: str
    event_journal: str
    event_bus: str

    version: str
    connectors: Tuple[str, ...] = None  # merged from DataFabricHealth, made optional for safety


def data_fabric_health(
    fabric: CyberDataFabric,
) -> DataFabricHealth:

    checks = {
        "schema_registry": fabric.schema_registry is not None,
        "telemetry_store": fabric.store is not None,
        "checkpoint_store": fabric.checkpoints is not None,
        "idempotency_store": fabric.idempotency is not None,
        "dead_letter_store": fabric.dead_letters is not None,
        "event_journal": fabric.event_journal is not None,
        "event_bus": fabric.event_bus is not None,
    }

    healthy = all(checks.values())

    return DataFabricHealth(
        status="HEALTHY" if healthy else "DEGRADED",
        schema_registry=(
            "AVAILABLE"
            if checks["schema_registry"]
            else "UNAVAILABLE"
        ),
        telemetry_store=(
            "AVAILABLE"
            if checks["telemetry_store"]
            else "UNAVAILABLE"
        ),
        checkpoint_store=(
            "AVAILABLE"
            if checks["checkpoint_store"]
            else "UNAVAILABLE"
        ),
        idempotency_store=(
            "AVAILABLE"
            if checks["idempotency_store"]
            else "UNAVAILABLE"
        ),
        dead_letter_store=(
            "AVAILABLE"
            if checks["dead_letter_store"]
            else "UNAVAILABLE"
        ),
        event_journal=(
            "AVAILABLE"
            if checks["event_journal"]
            else "UNAVAILABLE"
        ),
        event_bus=(
            "AVAILABLE"
            if checks["event_bus"]
            else "UNAVAILABLE"
        ),
        version=CyberDataFabric.VERSION,
    )


