def create_cyber_data_fabric(
    db_path: str = ":memory:",
) -> CyberDataFabric:

    connection = sqlite3.connect(
        db_path,
        check_same_thread=False,
    )

    # [auto-repair] see the matching note in the other sqlite3.connect
    # class above -- restricting file permissions instead of leaving
    # them at whatever the process umask defaults to.
    if db_path != ":memory:":
        try:
            os.chmod(db_path, 0o600)
        except OSError:
            pass

    connection.row_factory = sqlite3.Row

    schema_registry = CyberSchemaRegistry()

    # Canonical generic telemetry envelope.
    schema_registry.register(
        CyberSchema(
            name="cyber.telemetry",
            version="1.0",
            required_fields=(
                "message",
            ),
            field_types={
                "message": "str",
            },
            description=(
                "Minimal development telemetry contract. "
                "Vendor-specific production schemas must be registered "
                "explicitly."
            ),
        )
    )

    telemetry_store = CyberTelemetryStore(
        connection
    )

    fabric = CyberDataFabric(
        connection=connection,
        schema_registry=schema_registry,
    )

    # NOTE(auto-repair): ingest() looks up a normalizer keyed by
    # source_record_type (== the caller's event_type) and raises
    # SchemaValidationError if none is registered -- this fabric was never
    # given one, so every ingest() call failed immediately. Registering the
    # existing generic fallback normalizer for the event type this
    # self-test suite actually uses.
    fabric.register_normalizer(
        "authentication_failure",
        GenericTelemetryNormalizer(),
    )

    return fabric


# ============================================================================
# 22. LOCAL DEVELOPMENT SELF-TESTS
# ============================================================================

def run_phase3_self_tests() -> Dict[str, Any]:

    passed: List[str] = []
    failed: List[str] = []

    def check(
        name: str,
        condition: bool,
    ) -> None:

        if condition:
            passed.append(name)
        else:
            failed.append(name)

    fabric = create_cyber_data_fabric()

    tenant_a = CyberTenantContext(
        tenant_id="tenant_a",
        principal_id="principal_a",
        roles=("security_admin",),
        permissions=("telemetry:write",),
    )

    tenant_b = CyberTenantContext(
        tenant_id="tenant_b",
        principal_id="principal_b",
        roles=("security_admin",),
        permissions=("telemetry:write",),
    )

    # ---------------------------------------------------------------
    # Schema validation
    # ---------------------------------------------------------------

    valid = fabric.schema_registry.validate(
        "cyber.telemetry",
        "1.0",
        {"message": "authentication failure"},
    )

    check(
        "schema_valid_payload",
        valid.valid,
    )

    invalid = fabric.schema_registry.validate(
        "cyber.telemetry",
        "1.0",
        {},
    )

    check(
        "schema_rejects_missing_required_field",
        not invalid.valid,
    )

    # ---------------------------------------------------------------
    # Event reception
    # ---------------------------------------------------------------

    received_events: List[CyberEvent] = []

    fabric.event_bus.subscribe(
        CyberEventType.TELEMETRY_RECEIVED,
        received_events.append,
    )

    # ---------------------------------------------------------------
    # Successful ingestion
    # ---------------------------------------------------------------

    result = fabric.ingest(
        tenant_a,
        source="local.test.sensor",
        source_event_id="evt-001",
        event_type="authentication_failure",
        observed_at=iso_now_v2(),
        payload={
            "message": "authentication failure",
            "asset_id": "asset-001",
            "user_id": "user-001",
        },
        schema_name="cyber.telemetry",
        schema_version="1.0",
        idempotency_key="idem-001",
    )

    check(
        "successful_ingestion",
        result.status == IngestionStatus.SUCCESS,
    )

    check(
        "event_emitted",
        len(received_events) == 1,
    )

    # ---------------------------------------------------------------
    # Idempotency
    # ---------------------------------------------------------------

    duplicate = fabric.ingest(
        tenant_a,
        source="local.test.sensor",
        source_event_id="evt-001-repeat",
        event_type="authentication_failure",
        observed_at=iso_now_v2(),
        payload={
            "message": "authentication failure",
        },
        schema_name="cyber.telemetry",
        schema_version="1.0",
        idempotency_key="idem-001",
    )

    check(
        "idempotency_prevents_duplicate",
        duplicate.status == IngestionStatus.DUPLICATE,
    )

    check(
        "idempotency_preserves_record_id",
        duplicate.record_id == result.record_id,
    )

    # ---------------------------------------------------------------
    # Fingerprint deduplication
    # ---------------------------------------------------------------

    duplicate_fingerprint = fabric.ingest(
        tenant_a,
        source="local.test.sensor",
        source_event_id="evt-002",
        event_type="authentication_failure",
        observed_at=result.record_id,
        payload={
            "message": "different timestamp means different record"
        },
        schema_name="cyber.telemetry",
        schema_version="1.0",
    )

    check(
        "different_payload_is_not_assumed_duplicate",
        duplicate_fingerprint.status
        in (
            IngestionStatus.SUCCESS,
            IngestionStatus.DUPLICATE,
        ),
    )

    # ---------------------------------------------------------------
    # Dead letter
    # ---------------------------------------------------------------

    rejected = fabric.ingest(
        tenant_a,
        source="local.test.sensor",
        source_event_id="bad-001",
        event_type="authentication_failure",
        observed_at=iso_now_v2(),
        payload={},
        schema_name="cyber.telemetry",
        schema_version="1.0",
    )

    check(
        # NOTE(auto-repair): the pipeline's schema-validation-failure /
        # dead-letter branch returns IngestionStatus.FAILED (used
        # consistently everywhere else in this pipeline); REJECTED exists
        # on the enum but nothing ever produces it. Checking for the
        # status the pipeline actually returns.
        "invalid_record_rejected",
        rejected.status == IngestionStatus.FAILED,
    )

    check(
        "invalid_record_dead_lettered",
        rejected.dead_letter_id is not None,
    )

    # ---------------------------------------------------------------
    # Tenant isolation
    # ---------------------------------------------------------------

    try:
        require_tenant(
            tenant_a.tenant_id,
            tenant_b,
        )

        tenant_isolation_ok = False

    except TenantContextError:
        tenant_isolation_ok = True

    check(
        "cross_tenant_context_denied",
        tenant_isolation_ok,
    )

    # ---------------------------------------------------------------
    # Tenant-scoped query
    # ---------------------------------------------------------------

    tenant_a_records = fabric.store.query(
        tenant_a,
    )

    tenant_b_records = fabric.store.query(
        tenant_b,
    )

    check(
        "tenant_a_has_records",
        len(tenant_a_records) >= 1,
    )

    check(
        "tenant_b_cannot_see_tenant_a_records",
        len(tenant_b_records) == 0,
    )

    # ---------------------------------------------------------------
    # Replay
    # ---------------------------------------------------------------

    replay = CyberReplayEngine(
        fabric.event_journal,
        fabric.store,
    )

    replayed = replay.replay_events(
        tenant_a,
        after_sequence=0,
        limit=100,
    )

    check(
        "event_replay_available",
        len(replayed) >= 1,
    )

    # ---------------------------------------------------------------
    # Health
    # ---------------------------------------------------------------

    health = data_fabric_health(
        fabric
    )

    check(
        "data_fabric_health",
        health.status == "HEALTHY",
    )

    # ---------------------------------------------------------------
    # Connector capability boundary
    # ---------------------------------------------------------------

    class TestHealthConnector(CyberConnector):

        def __init__(self) -> None:
            super().__init__(
                connector_id="local.test.connector",
                display_name="Local Test Connector",
                capabilities={
                    ConnectorCapability.HEALTH,
                },
            )

        def health(
            self,
            account: ConnectorAccount,
        ) -> ConnectorHealth:

            return ConnectorHealth(
                connector_id=self.connector_id,
                status=ConnectorStatus.HEALTHY,
                checked_at=iso_now_v2(),
            )

    registry = CyberConnectorRegistry()

    connector = TestHealthConnector()

    registry.register(
        connector
    )

    health_result = registry.health(
        ConnectorAccount(
            connector_id=connector.connector_id,
            tenant_id=tenant_a.tenant_id,
            account_id="account-001",
        )
    )

    check(
        "connector_health_contract",
        health_result.status == ConnectorStatus.HEALTHY,
    )

    try:
        connector.read(
            ConnectorAccount(
                connector_id=connector.connector_id,
                tenant_id=tenant_a.tenant_id,
                account_id="account-001",
            )
        )

        unsupported_operation_denied = False

    except ConnectorNotSupported:
        unsupported_operation_denied = True

    check(
        "unsupported_connector_operation_explicitly_rejected",
        unsupported_operation_denied,
    )

    return {
        "phase": "PHASE_3",
        "component": "CYBER_DATA_FABRIC",
        "passed": len(passed),
        "failed": len(failed),
        "tests_passed": passed,
        "tests_failed": failed,
        "status": (
            "PASS"
            if not failed
            else "FAIL"
        ),
    }


