@dataclass(frozen=True)
class CredentialReference:
    """
    Reference only.

    Actual secret material must NOT be stored in connector
    configuration.
    """

    reference_id: str
    secret_type: str

    def __post_init__(self) -> None:
        if not self.reference_id:
            raise ValueError("credential reference_id required")

        if not self.secret_type:
            raise ValueError("credential secret_type required")


class CredentialProvider(ABC):

    @abstractmethod
    def resolve(
        self,
        reference: CredentialReference,
        *,
        tenant_id: str,
    ) -> Mapping[str, str]:
        raise NotImplementedError


class InMemoryCredentialProvider(CredentialProvider):
    """
    Development/test provider.

    Production should be backed by an external secrets system.
    """

    def __init__(self) -> None:
        # [auto-repair] was Dict[str, ...], keyed on reference_id alone,
        # same issue as InMemorySecretProvider elsewhere in this file:
        # CredentialReference has no tenant_id field, so two tenants
        # using the same reference_id (plausible if it's derived from a
        # predictable naming scheme) would silently share/overwrite
        # each other's connector credentials. This is the default
        # credential provider wired into connectors (see below), so
        # this wasn't just test scaffolding.
        self._values: Dict[Tuple[str, str], Mapping[str, str]] = {}

    def put(
        self,
        reference_id: str,
        values: Mapping[str, str],
        *,
        tenant_id: str,
    ) -> None:
        self._values[(tenant_id, reference_id)] = dict(values)

    def resolve(
        self,
        reference: CredentialReference,
        *,
        tenant_id: str,
    ) -> Mapping[str, str]:
        key = (tenant_id, reference.reference_id)

        if key not in self._values:
            raise KeyError(
                f"Credential reference not found: "
                f"{reference.reference_id}"
            )

        return dict(self._values[key])


