@dataclass(frozen=True)
class ConnectorConfig:
    connector_id: str
    tenant_id: str
    name: str
    family: ConnectorFamily

    endpoint: Optional[str] = None

    auth_type: AuthType = AuthType.NONE
    credential_reference: Optional[CredentialReference] = None

    timeout_seconds: float = 10.0
    max_retries: int = 3

    enabled: bool = True

    verify_tls: bool = True

    metadata: Mapping[str, Any] = field(
        default_factory=dict
    )

    def __post_init__(self) -> None:

        if not self.connector_id:
            raise ValueError("connector_id is required")

        if not self.tenant_id:
            raise ValueError("tenant_id is required")

        if not self.name:
            raise ValueError("connector name is required")

        if self.timeout_seconds <= 0:
            raise ValueError(
                "timeout_seconds must be > 0"
            )

        if self.max_retries < 0:
            raise ValueError(
                "max_retries cannot be negative"
            )
    connector_type: ConnectorType = None  # merged from ConnectorConfig, made optional for safety
    base_url: str = None  # merged from ConnectorConfig, made optional for safety
    credentials: ConnectorCredentials = None  # merged from ConnectorConfig, made optional for safety
    retry_backoff_seconds: float = None  # merged from ConnectorConfig, made optional for safety
    default_headers: Mapping[str, str] = None  # merged from ConnectorConfig, made optional for safety


