# ============================================================
# 11. CHECKPOINT
# ============================================================



class CheckpointStore(ABC):

    @abstractmethod
    def get(
        self,
        connector_id: str,
    ) -> Optional[ConnectorCheckpoint]:
        raise NotImplementedError

    @abstractmethod
    def put(
        self,
        checkpoint: ConnectorCheckpoint,
    ) -> None:
        raise NotImplementedError
    @abstractmethod
    def delete(
        self,
        connector_id: str,
        tenant_id: str,
    ) -> None:
        raise NotImplementedError

    @abstractmethod
    def save(
        self,
        checkpoint: ConnectorCheckpoint,
    ) -> None:
        raise NotImplementedError


class InMemoryCheckpointStore(CheckpointStore):

    def __init__(self) -> None:
        self._data: Dict[
            str,
            ConnectorCheckpoint,
        ] = {}

        self._lock = threading.Lock()

    def get(
        self,
        connector_id: str,
    ) -> Optional[ConnectorCheckpoint]:

        with self._lock:
            return self._data.get(connector_id)

    def put(
        self,
        checkpoint: ConnectorCheckpoint,
    ) -> None:

        with self._lock:
            self._data[
                checkpoint.connector_id
            ] = checkpoint
    def delete(
        self,
        connector_id: str,
        tenant_id: str,
    ) -> None:
        # NOTE: this store is keyed by connector_id only (matching get()/put()
        # above), so tenant_id is accepted for interface compatibility but not
        # part of the key. If per-tenant checkpoint isolation is required, the
        # key scheme for get()/put()/delete()/save() must be changed together
        # (see CheckpointStore ABC) rather than diverging here.
        with self._lock:
            self._data.pop(connector_id, None)

    def save(
        self,
        checkpoint: ConnectorCheckpoint,
    ) -> None:
        validate_identifier(
            checkpoint.connector_id,
            field_name="checkpoint.connector_id",
        )

        validate_identifier(
            checkpoint.tenant_id,
            field_name="checkpoint.tenant_id",
        )

        with self._lock:
            self._data[checkpoint.connector_id] = checkpoint


