# 15. GENERIC REST TRANSPORT
# ============================================================

@dataclass(frozen=True)
class HTTPResponse:
    status_code: int
    headers: Mapping[str, str]
    body: bytes
# --- preserved from HTTPResponse (merged, not present in canonical host) ---
    def json(self) -> Any:
        return json.loads(self.text)
# --- preserved from HTTPResponse (merged, not present in canonical host) ---
    @property
    def text(self) -> str:
        return self.body.decode(
            "utf-8",
            errors="replace",
        )


class HTTPTransport:

    def __init__(
        self,
        timeout_seconds: float = 10.0,
    ) -> None:

        self.timeout_seconds = timeout_seconds

    def request(
        self,
        *,
        method: str,
        url: str,
        headers: Optional[Mapping[str, str]] = None,
        body: Optional[bytes] = None,
    ) -> HTTPResponse:

        req = urllib_request.Request(
            url=url,
            method=method.upper(),
            headers=dict(headers or {}),
            data=body,
        )

        try:

            with urllib_request.urlopen(
                req,
                timeout=self.timeout_seconds,
            ) as response:

                return HTTPResponse(
                    status_code=response.status,
                    headers=dict(response.headers.items()),
                    body=response.read(),
                )

        except urllib_error.HTTPError as exc:

            if exc.code == 401:
                raise ConnectorAuthenticationError(
                    "External system rejected authentication"
                )

            if exc.code == 403:
                raise ConnectorAuthorizationError(
                    "External system rejected authorization"
                )

            if exc.code == 429:

                retry_after = None

                raw = exc.headers.get(
                    "Retry-After"
                )

                if raw:
                    try:
                        retry_after = float(raw)
                    except ValueError:
                        retry_after = None

                raise ConnectorRateLimitError(
                    "External system rate-limited request",
                    retry_after=retry_after,
                )

            if 500 <= exc.code < 600:
                raise ConnectorUnavailableError(
                    f"External server error: {exc.code}"
                )

            raise ConnectorProtocolError(
                f"HTTP error: {exc.code}"
            )

        except TimeoutError as exc:

            raise ConnectorTimeoutError(
                "Connector request timed out"
            ) from exc

        except urllib_error.URLError as exc:

            raise ConnectorUnavailableError(
                str(exc)
            ) from exc


# ============================================================
# 16. GENERIC REST CONNECTOR
# ============================================================

class RESTConnector(CyberConnector):

    def __init__(
        self,
        config: ConnectorConfig,
        transport: Optional[HTTPTransport] = None,
        credential_provider: Optional[
            CredentialProvider
        ] = None,
        event_parser: Optional[
            Callable[
                [Mapping[str, Any]],
                Iterable[
                    Tuple[
                        str,
                        Mapping[str, Any],
                    ]
                ],
            ]
        ] = None,
        read_path: str = "/events",
    ) -> None:

        super().__init__(config)

        self.transport = transport or HTTPTransport(
            config.timeout_seconds
        )

        self.credential_provider = (
            credential_provider
            or InMemoryCredentialProvider()
        )

        self.event_parser = event_parser

        self.read_path = read_path

        # [auto-repair] _request_with_retry() below already expected
        # self.retry_policy; nothing ever set it, even though a working
        # RetryPolicy class already exists elsewhere in this file. Wiring
        # it here instead of deleting the (otherwise solid) retry method.
        self.retry_policy = RetryPolicy()

    def capabilities(
        self,
    ) -> frozenset[ConnectorCapability]:

        return frozenset(
            {
                ConnectorCapability.READ,
                ConnectorCapability.POLL,
                ConnectorCapability.HEALTH_CHECK,
            }
        )

    def _headers(self) -> Dict[str, str]:

        headers = {
            "Accept": "application/json",
            "User-Agent": "NEXORA-CYBER-Connector/1.0",
        }

        reference = self.config.credential_reference

        if reference is None:
            return headers

        credentials = (
            self.credential_provider.resolve(
                reference,
                tenant_id=self.config.tenant_id,
            )
        )

        if self.config.auth_type == AuthType.API_KEY:

            api_key = credentials.get("api_key")

            if not api_key:
                raise ConnectorAuthenticationError(
                    "API key missing"
                )

            headers["X-API-Key"] = api_key

        elif self.config.auth_type == AuthType.BEARER:

            token = credentials.get("token")

            if not token:
                raise ConnectorAuthenticationError(
                    "Bearer token missing"
                )

            headers["Authorization"] = (
                f"Bearer {token}"
            )

        elif self.config.auth_type == AuthType.BASIC:

            import base64

            username = credentials.get(
                "username"
            )
            password = credentials.get(
                "password"
            )

            if username is None or password is None:
                raise ConnectorAuthenticationError(
                    "Basic authentication credentials missing"
                )

            encoded = base64.b64encode(
                f"{username}:{password}".encode()
            ).decode()

            headers["Authorization"] = (
                f"Basic {encoded}"
            )

        return headers

    def initialize(self) -> None:

        if not self.config.enabled:
            self._status = ConnectorStatus.STOPPED
            return

        if not self.config.endpoint:
            raise ConnectorConfigurationError(
                "REST connector requires endpoint"
            )

        self._status = (
            ConnectorStatus.INITIALIZING
        )

        health = self.health_check()

        if health.status in {
            ConnectorStatus.READY,
            ConnectorStatus.DEGRADED,
        }:
            self._status = health.status
        else:
            self._status = ConnectorStatus.FAILED

    def health_check(
        self,
    ) -> ConnectorHealth:

        started = time.perf_counter()

        try:

            if not self.config.endpoint:
                raise ConnectorConfigurationError(
                    "endpoint required"
                )

            response = self.transport.request(
                method="GET",
                url=self.config.endpoint,
                headers=self._headers(),
            )

            latency = (
                time.perf_counter()
                - started
            ) * 1000

            if 200 <= response.status_code < 300:

                return ConnectorHealth(
                    connector_id=self.connector_id,
                    status=ConnectorStatus.READY,
                    checked_at=utc_now_v3(),
                    latency_ms=latency,
                    message="healthy",
                )

            return ConnectorHealth(
                connector_id=self.connector_id,
                status=ConnectorStatus.DEGRADED,
                checked_at=utc_now_v3(),
                latency_ms=latency,
                message=(
                    f"unexpected HTTP "
                    f"status {response.status_code}"
                ),
            )

        except ConnectorAuthenticationError as exc:

            self._status = ConnectorStatus.FAILED

            return ConnectorHealth(
                connector_id=self.connector_id,
                status=self._status,
                checked_at=utc_now_v3(),
                latency_ms=(
                    time.perf_counter()
                    - started
                ) * 1000,
                message=str(exc),
            )

        except ConnectorError as exc:

            self._status = ConnectorStatus.DEGRADED

            return ConnectorHealth(
                connector_id=self.connector_id,
                status=self._status,
                checked_at=utc_now_v3(),
                latency_ms=(
                    time.perf_counter()
                    - started
                ) * 1000,
                message=str(exc),
            )

    def _parse_response(
        self,
        response: HTTPResponse,
    ) -> Mapping[str, Any]:

        try:

            value = json.loads(
                response.body.decode(
                    "utf-8"
                )
            )

        except Exception as exc:

            raise ConnectorProtocolError(
                "External connector returned "
                "invalid JSON"
            ) from exc

        if not isinstance(value, Mapping):

            raise ConnectorProtocolError(
                "Expected JSON object"
            )

        return value

    def read(
        self,
        cursor: Optional[str] = None,
    ) -> ConnectorResult:

        started = time.perf_counter()

        if not self.config.endpoint:
            raise ConnectorConfigurationError(
                "endpoint required"
            )

        url = (
            self.config.endpoint.rstrip("/")
            + "/"
            + self.read_path.lstrip("/")
        )

        if cursor:
            separator = "&" if "?" in url else "?"
            url += (
                separator
                + "cursor="
                + cursor
            )

        policy = RetryPolicy(
            max_attempts=max(
                1,
                self.config.max_retries + 1,
            )
        )

        def operation() -> HTTPResponse:

            return self.transport.request(
                method="GET",
                url=url,
                headers=self._headers(),
            )

        try:

            response = execute_with_retry(
                operation,
                policy,
                retry_if=lambda exc: isinstance(
                    exc,
                    (
                        ConnectorUnavailableError,
                        ConnectorTimeoutError,
                        ConnectorRateLimitError,
                    ),
                ),
            )

            payload = self._parse_response(
                response
            )

            events: List[ConnectorEvent] = []

            if self.event_parser is not None:

                parsed = self.event_parser(
                    payload
                )

                for event_type, event_payload in parsed:

                    events.append(
                        ConnectorEventFactory.create(
                            config=self.config,
                            event_type=event_type,
                            payload=event_payload,
                        )
                    )

            else:

                events.append(
                    ConnectorEventFactory.create(
                        config=self.config,
                        event_type="connector.response",
                        payload=payload,
                    )
                )

            next_cursor = None

            raw_cursor = payload.get(
                "next_cursor"
            )

            if raw_cursor is not None:
                next_cursor = str(
                    raw_cursor
                )

            return ConnectorResult(
                success=True,
                events=events,
                cursor=next_cursor,
                latency_ms=(
                    time.perf_counter()
                    - started
                ) * 1000,
            )

        except ConnectorRateLimitError as exc:

            return ConnectorResult(
                success=False,
                error=str(exc),
                retryable=True,
                latency_ms=(
                    time.perf_counter()
                    - started
                ) * 1000,
            )

        except ConnectorError as exc:

            return ConnectorResult(
                success=False,
                error=str(exc),
                retryable=isinstance(
                    exc,
                    (
                        ConnectorUnavailableError,
                        ConnectorTimeoutError,
                    ),
                ),
                latency_ms=(
                    time.perf_counter()
                    - started
                ) * 1000,
            )
    # --- preserved from RESTConnector (merged, not present in canonical host) ---
    def _apply_credentials(
        self,
        headers: Dict[str, str],
        credentials: Mapping[str, str],
    ) -> None:

        if not credentials:
            return

        if self.config.auth_type == AuthType.API_KEY:

            key_name = credentials.get(
                "header_name",
                "X-API-Key",
            )

            key_value = credentials.get(
                "api_key"
            )

            if not key_value:
                raise ConnectorAuthenticationError(
                    "API key credential material missing."
                )

            headers[key_name] = key_value

        elif self.config.auth_type == AuthType.BEARER:

            token = credentials.get("token")

            if not token:
                raise ConnectorAuthenticationError(
                    "Bearer token missing."
                )

            headers["Authorization"] = (
                f"Bearer {token}"
            )

        elif self.config.auth_type == AuthType.BASIC:

            username = credentials.get(
                "username"
            )

            password = credentials.get(
                "password"
            )

            if username is None or password is None:
                raise ConnectorAuthenticationError(
                    "Basic authentication material missing."
                )

            import base64

            encoded = base64.b64encode(
                f"{username}:{password}".encode(
                    "utf-8"
                )
            ).decode("ascii")

            headers["Authorization"] = (
                f"Basic {encoded}"
            )

        elif self.config.auth_type in {
            AuthType.OAUTH2,
            AuthType.CUSTOM,
            AuthType.AWS_SIGNATURE,
        }:

            # Phase 4 establishes the credential boundary.
            # Provider-specific signing is intentionally not fabricated.
            raise ConnectorAuthenticationError(
                f"Authentication type "
                f"{self.config.auth_type.value} "
                "requires a provider-specific adapter."
            )
    # --- preserved from RESTConnector (merged, not present in canonical host) ---
    def _health_check(self) -> Optional[str]:

        if not self.config.endpoint:
            return "configured-without-endpoint"

        return "transport-ready"
    # --- preserved from RESTConnector (merged, not present in canonical host) ---
    def _poll(
        self,
        *,
        cursor: Optional[str] = None,
    ) -> ConnectorResult:

        return self._read(
            cursor=cursor
        )
    # --- preserved from RESTConnector (merged, not present in canonical host) ---
    def _read(
        self,
        *,
        cursor: Optional[str] = None,
    ) -> ConnectorResult:

        started = time.perf_counter()

        path = ""

        if cursor:
            path = cursor

        response = self._request_with_retry(
            method="GET",
            path=path,
        )

        latency_ms = (
            time.perf_counter()
            - started
        ) * 1000

        if response.status_code in {
            401,
            403,
        }:

            raise ConnectorAuthenticationError(
                f"Remote endpoint rejected authentication: "
                f"HTTP {response.status_code}"
            )

        if response.status_code >= 400:

            return ConnectorResult(
                success=False,
                error=(
                    f"Remote endpoint returned "
                    f"HTTP {response.status_code}"
                ),
                retryable=response.status_code
                in {408, 429, 500, 502, 503, 504},
                latency_ms=latency_ms,
            )

        try:
            data = response.json()

        except json.JSONDecodeError as exc:

            raise ConnectorProtocolError(
                "REST endpoint returned invalid JSON."
            ) from exc

        event = ConnectorEventFactory.create(
            config=self.config,
            event_type="connector.rest.response",
            payload={
                "response": data,
                "http_status": response.status_code,
            },
            source_reference=(
                response.headers.get(
                    "X-Request-ID"
                )
            ),
        )

        return ConnectorResult(
            success=True,
            events=[event],
            latency_ms=latency_ms,
            metadata={
                "http_status": response.status_code,
            },
        )
    # --- preserved from RESTConnector (merged, not present in canonical host) ---
    def _request_with_retry(
        self,
        *,
        method: str,
        path: str = "",
        headers: Optional[
            Mapping[str, str]
        ] = None,
        body: Optional[bytes] = None,
    ) -> HTTPResponse:

        if not self.config.endpoint:
            raise ConnectorConfigurationError(
                "REST connector requires an endpoint."
            )

        url = (
            self.config.endpoint.rstrip("/")
            + "/"
            + path.lstrip("/")
        )

        request_headers = dict(
            headers or {}
        )

        credentials = (
            self._resolve_credentials()
        )

        self._apply_credentials(
            request_headers,
            credentials,
        )

        last_error: Optional[
            Exception
        ] = None

        for attempt in range(
            1,
            self.retry_policy.max_attempts + 1,
        ):

            try:

                response = self.transport.request(
                    method=method,
                    url=url,
                    headers=request_headers,
                    body=body,
                    timeout_seconds=(
                        self.config.timeout_seconds
                    ),
                )

                if response.status_code == 429:

                    retry_after = (
                        self._retry_after_seconds(
                            response.headers
                        )
                    )

                    if (
                        attempt
                        >= self.retry_policy.max_attempts
                    ):
                        raise ConnectorRateLimitError(
                            "Remote endpoint rate-limited "
                            "the connector.",
                            retry_after=retry_after,
                        )

                    delay = (
                        retry_after
                        if retry_after is not None
                        else self.retry_policy.delay(
                            attempt
                        )
                    )

                    if delay > 0:
                        time.sleep(
                            min(
                                delay,
                                MAX_BACKOFF_SECONDS,
                            )
                        )

                    continue

                if (
                    response.status_code
                    in {408, 425, 500, 502, 503, 504}
                ):

                    if (
                        attempt
                        >= self.retry_policy.max_attempts
                    ):
                        raise ConnectorUnavailableError(
                            "Remote endpoint remained "
                            f"unavailable: "
                            f"HTTP {response.status_code}"
                        )

                    time.sleep(
                        self.retry_policy.delay(
                            attempt
                        )
                    )

                    continue

                return response

            except (
                ConnectorUnavailableError,
                ConnectorTimeoutError,
            ) as exc:

                last_error = exc

                if (
                    attempt
                    >= self.retry_policy.max_attempts
                ):
                    raise

                time.sleep(
                    self.retry_policy.delay(
                        attempt
                    )
                )

        if last_error is not None:
            raise last_error

        raise ConnectorError(
            "REST request failed without a result."
        )
    # --- preserved from RESTConnector (merged, not present in canonical host) ---
    @staticmethod
    def _retry_after_seconds(
        headers: Mapping[str, str],
    ) -> Optional[float]:

        value = None

        for key, item in headers.items():
            if key.lower() == "retry-after":
                value = item
                break

        if value is None:
            return None

        try:
            parsed = float(value)

            if parsed < 0:
                return None

            return min(
                parsed,
                MAX_BACKOFF_SECONDS,
            )

        except ValueError:
            return None


# ============================================================
# 17. POLLING CONTRACT
# ============================================================

class ConnectorPoller:

    def __init__(
        self,
        connector: CyberConnector,
        checkpoint_store: CheckpointStore,
    ) -> None:

        self.connector = connector
        self.checkpoint_store = checkpoint_store

    def poll_once(self) -> ConnectorResult:

        checkpoint = (
            self.checkpoint_store.get(
                self.connector.connector_id
            )
        )

        cursor = (
            checkpoint.cursor
            if checkpoint
            else None
        )

        result = self.connector.read(
            cursor=cursor
        )

        if result.success:

            self.checkpoint_store.put(
                ConnectorCheckpoint(
                    connector_id=(
                        self.connector.connector_id
                    ),
                    tenant_id=(
                        self.connector.tenant_id
                    ),
                    cursor=result.cursor,
                    updated_at=utc_now_v3(),
                )
            )

        return result
    def poll(
        self,
        *,
        cursor: Optional[str] = None,
    ) -> ConnectorResult:
        """Compatibility polling entrypoint using the canonical read contract."""
        result = self.connector.read(cursor=cursor)
        if result.success:
            self.checkpoint_store.put(
                ConnectorCheckpoint(
                    connector_id=self.connector.connector_id,
                    tenant_id=self.connector.tenant_id,
                    cursor=result.cursor,
                    updated_at=utc_now_v3(),
                )
            )
        return result


