# ============================================================
# 20. CONNECTOR REGISTRY
# ============================================================

class ConnectorRegistry:

    def __init__(self) -> None:

        self._connectors: Dict[
            str,
            CyberConnector,
        ] = {}

        self._lock = threading.RLock()

    def register(
        self,
        connector: CyberConnector,
    ) -> None:

        with self._lock:

            if (
                connector.connector_id
                in self._connectors
            ):
                raise ValueError(
                    "Connector already registered: "
                    f"{connector.connector_id}"
                )

            self._connectors[
                connector.connector_id
            ] = connector

    def get(
        self,
        connector_id: str,
    ) -> CyberConnector:

        with self._lock:

            if connector_id not in self._connectors:
                raise KeyError(
                    "Connector not found: "
                    f"{connector_id}"
                )

            return self._connectors[
                connector_id
            ]

    def remove(
        self,
        connector_id: str,
    ) -> None:

        with self._lock:

            connector = self._connectors.pop(
                connector_id,
                None,
            )

            if connector:
                connector.close()

    def list(self) -> List[CyberConnector]:

        with self._lock:
            return list(
                self._connectors.values()
            )

    def by_family(
        self,
        family: ConnectorFamily,
    ) -> List[CyberConnector]:

        return [
            connector
            for connector in self.list()
            if connector.family == family
        ]
    # --- preserved from ConnectorRegistry (merged, not present in canonical host) ---
    def contains(
        self,
        connector_id: str,
    ) -> bool:

        with self._lock:
            return connector_id in self._connectors
    # --- preserved from ConnectorRegistry (merged, not present in canonical host) ---
    def count(self) -> int:

        with self._lock:
            return len(
                self._connectors
            )
    # --- preserved from ConnectorRegistry (merged, not present in canonical host) ---
    def list_for_tenant(
        self,
        tenant_id: str,
    ) -> Tuple[EnterpriseConnector, ...]:

        require_non_empty(
            tenant_id,
            "tenant_id",
        )

        return tuple(
            connector
            for (
                connector_tenant,
                _,
            ), connector
            in self._connectors.items()
            if connector_tenant == tenant_id
        )


# ============================================================
# 21. CONNECTOR MANAGER
# ============================================================

class ConnectorManager:

    def __init__(
        self,
        registry: ConnectorRegistry,
    ) -> None:

        self.registry = registry

    def initialize_all(self) -> None:

        for connector in self.registry.list():

            try:
                connector.initialize()

            except Exception:
                connector._status = (
                    ConnectorStatus.FAILED
                )

    def health_report(
        self,
    ) -> List[ConnectorHealth]:

        results = []

        for connector in self.registry.list():

            results.append(
                connector.health_check()
            )

        return results

    def stop_all(self) -> None:

        for connector in self.registry.list():
            connector.close()


# ============================================================
# 22. SIMULATOR EVENT
# ============================================================

@dataclass(frozen=True)
class SimulatedEvent:
    event_type: str
    payload: Mapping[str, Any]

    observed_at: Optional[datetime] = None

    source_reference: Optional[str] = None
    sequence: Optional[int] = None  # merged from SimulatedEvent, made optional for safety


# ============================================================
# 23. CONNECTOR SIMULATOR
# ============================================================

class SimulatedConnector(
    ActionConnector
):

    def __init__(
        self,
        config: ConnectorConfig,
        events: Optional[
            Iterable[SimulatedEvent]
        ] = None,
        failure_mode: Optional[str] = None,
        latency_seconds: float = 0.0,
        actions: Optional[
            Iterable[ConnectorAction]
        ] = None,
    ) -> None:

        super().__init__(config)

        self._events = list(
            events or []
        )

        self._failure_mode = failure_mode

        self._latency_seconds = (
            latency_seconds
        )

        self._actions = set(
            actions or []
        )

        self._initialized = False

        self._cursor = 0

        self._action_history: List[
            Mapping[str, Any]
        ] = []

    def capabilities(
        self,
    ) -> frozenset[ConnectorCapability]:

        capabilities = {
            ConnectorCapability.READ,
            ConnectorCapability.POLL,
            ConnectorCapability.HEALTH_CHECK,
        }

        if self._actions:
            capabilities.add(
                ConnectorCapability.ACTION
            )

        return frozenset(capabilities)

    def initialize(self) -> None:

        self._status = (
            ConnectorStatus.INITIALIZING
        )

        if self._failure_mode == "initialize":

            self._status = (
                ConnectorStatus.FAILED
            )

            raise ConnectorConfigurationError(
                "simulated initialization failure"
            )

        self._initialized = True

        self._status = (
            ConnectorStatus.READY
        )

    def health_check(
        self,
    ) -> ConnectorHealth:

        started = time.perf_counter()

        if self._failure_mode == "health":

            self._status = (
                ConnectorStatus.FAILED
            )

            return ConnectorHealth(
                connector_id=self.connector_id,
                status=self._status,
                checked_at=utc_now_v3(),
                latency_ms=(
                    time.perf_counter()
                    - started
                ) * 1000,
                message="simulated health failure",
            )

        return ConnectorHealth(
            connector_id=self.connector_id,
            status=self._status,
            checked_at=utc_now_v3(),
            latency_ms=(
                time.perf_counter()
                - started
            ) * 1000,
            message="healthy",
        )

    def read(
        self,
        cursor: Optional[str] = None,
    ) -> ConnectorResult:

        started = time.perf_counter()

        if not self._initialized:

            raise ConnectorError(
                "connector is not initialized"
            )

        if self._failure_mode == "read":

            return ConnectorResult(
                success=False,
                error="simulated read failure",
                retryable=True,
                latency_ms=(
                    time.perf_counter()
                    - started
                ) * 1000,
            )

        if self._latency_seconds:
            time.sleep(
                self._latency_seconds
            )

        start = self._cursor

        if cursor is not None:

            try:
                start = int(cursor)

            except ValueError:
                raise ConnectorProtocolError(
                    "invalid simulator cursor"
                )

        events = []

        for item in self._events[start:]:

            events.append(
                ConnectorEventFactory.create(
                    config=self.config,
                    event_type=item.event_type,
                    payload=item.payload,
                    observed_at=item.observed_at,
                    source_reference=(
                        item.source_reference
                    ),
                )
            )

        self._cursor = len(
            self._events
        )

        return ConnectorResult(
            success=True,
            events=events,
            cursor=str(self._cursor),
            latency_ms=(
                time.perf_counter()
                - started
            ) * 1000,
        )

    def execute_action(
        self,
        action: ConnectorAction,
        parameters: Mapping[str, Any],
    ) -> Mapping[str, Any]:

        if (
            ConnectorCapability.ACTION
            not in self.capabilities()
        ):
            raise ConnectorCapabilityError(
                "action capability unavailable"
            )

        if action not in self._actions:

            raise ConnectorCapabilityError(
                f"unsupported simulated action: "
                f"{action.value}"
            )

        if self._failure_mode == "action":

            raise ConnectorUnavailableError(
                "simulated action failure"
            )

        record = {
            "action_id": str(uuid.uuid4()),
            "action": action.value,
            "parameters": dict(parameters),
            "created_at": utc_now_v3().isoformat(),
        }

        self._action_history.append(
            record
        )

        return record

    @property
    def action_history(
        self,
    ) -> List[Mapping[str, Any]]:

        return list(
            self._action_history
        )
    # --- preserved from SimulatedConnector (merged, not present in canonical host) ---
    def _execute_action(
        self,
        action: ConnectorAction,
        parameters: Mapping[str, Any],
    ) -> Mapping[str, Any]:

        self._sleep_if_needed()

        if self._failure_mode == "action":
            raise ConnectorUnavailableError(
                "Simulated action failure."
            )

        if action not in self._actions:
            raise ConnectorCapabilityError(
                "Simulated connector does not support "
                f"action {action.value}."
            )

        if not isinstance(parameters, Mapping):
            raise TypeError(
                "Action parameters must be a mapping."
            )

        action_id = str(
            uuid.uuid4()
        )

        record = {
            "action_id": action_id,
            "connector_id": self.connector_id,
            "tenant_id": self.tenant_id,
            "action": action.value,
            "parameters": dict(parameters),
            "simulated": True,
            "executed_at": utc_iso(),
        }

        self._action_history.append(
            record
        )

        return dict(record)
    # --- preserved from SimulatedConnector (merged, not present in canonical host) ---
    def _health_check(self) -> Optional[str]:

        if self._failure_mode == "health":
            raise ConnectorUnavailableError(
                "Simulated health failure."
            )

        return "simulated-connector-healthy"
    # --- preserved from SimulatedConnector (merged, not present in canonical host) ---
    def _initialize(self) -> None:

        if self._failure_mode == "initialize":
            raise ConnectorConfigurationError(
                "Simulated initialization failure."
            )
    # --- preserved from SimulatedConnector (merged, not present in canonical host) ---
    def _poll(
        self,
        *,
        cursor: Optional[str] = None,
    ) -> ConnectorResult:

        return self._read(
            cursor=cursor
        )
    # --- preserved from SimulatedConnector (merged, not present in canonical host) ---
    def _read(
        self,
        *,
        cursor: Optional[str] = None,
    ) -> ConnectorResult:

        self._sleep_if_needed()

        if self._failure_mode == "read":
            raise ConnectorUnavailableError(
                "Simulated read failure."
            )

        start_index = self._cursor

        if cursor is not None:

            try:
                start_index = int(cursor)

            except ValueError as exc:
                raise ConnectorProtocolError(
                    "Invalid simulator cursor."
                ) from exc

        events: List[ConnectorEvent] = []

        for index in range(
            start_index,
            len(self._events),
        ):

            item = self._events[index]

            event = ConnectorEventFactory.create(
                config=self.config,
                event_type=item.event_type,
                payload=item.payload,
                observed_at=item.observed_at,
                source_reference=item.source_reference,
                sequence=(
                    item.sequence
                    if item.sequence is not None
                    else index
                ),
            )

            events.append(event)

        self._cursor = len(
            self._events
        )

        return ConnectorResult(
            success=True,
            events=events,
            cursor=str(
                self._cursor
            ),
            metadata={
                "simulated": True,
            },
        )
    # --- preserved from SimulatedConnector (merged, not present in canonical host) ---
    def _sleep_if_needed(self) -> None:

        if self._latency_seconds > 0:
            time.sleep(
                self._latency_seconds
            )
    # --- preserved from SimulatedConnector (merged, not present in canonical host) ---
    def _stream(
        self,
        *,
        cursor: Optional[str] = None,
    ) -> Iterator[ConnectorEvent]:

        result = self._read(
            cursor=cursor
        )

        for event in result.events:
            yield event


