class FamilyRESTConnector(
    RESTConnector
):

    FAMILY: ConnectorFamily

    def __init__(
        self,
        config: ConnectorConfig,
        **kwargs: Any,
    ) -> None:

        if config.family != self.FAMILY:

            raise ConnectorConfigurationError(
                f"Expected family "
                f"{self.FAMILY.value}, got "
                f"{config.family.value}"
            )

        super().__init__(
            config,
            **kwargs,
        )


