CONNECTOR_TYPES: Dict[
    ConnectorFamily,
    type[CyberConnector],
] = {
    ConnectorFamily.ENDPOINT:
        EndpointConnector,

    ConnectorFamily.EDR_XDR:
        EDRXDRConnector,

    ConnectorFamily.FIREWALL:
        FirewallConnector,

    ConnectorFamily.DNS:
        DNSConnector,

    ConnectorFamily.PROXY:
        ProxyConnector,

    ConnectorFamily.IDS_IPS:
        IDSIPSConnector,

    ConnectorFamily.IAM:
        IAMConnector,

    ConnectorFamily.SSO:
        SSOConnector,

    ConnectorFamily.DIRECTORY:
        DirectoryConnector,

    ConnectorFamily.AWS:
        AWSConnector,

    ConnectorFamily.AZURE:
        AzureConnector,

    ConnectorFamily.GCP:
        GCPConnector,

    ConnectorFamily.SIEM:
        SIEMConnector,

    ConnectorFamily.VULNERABILITY:
        VulnerabilityConnector,

    ConnectorFamily.THREAT_INTELLIGENCE:
        ThreatIntelligenceConnector,

    ConnectorFamily.EMAIL:
        EmailConnector,

    ConnectorFamily.SAAS:
        SaaSConnector,

    ConnectorFamily.ITSM:
        ITSMConnector,

    ConnectorFamily.GIT:
        GitConnector,

    ConnectorFamily.CICD:
        CICDConnector,

    ConnectorFamily.CONTAINER:
        ContainerConnector,

    ConnectorFamily.KUBERNETES:
        KubernetesConnector,
}


class ConnectorFactory:

    @staticmethod
    def create(
        config: ConnectorConfig,
        **kwargs: Any,
    ) -> CyberConnector:

        connector_type = CONNECTOR_TYPES.get(
            config.family
        )

        if connector_type is None:

            raise ConnectorConfigurationError(
                "No connector implementation registered "
                f"for family {config.family.value}"
            )

        return connector_type(
            config,
            **kwargs,
        )


# ============================================================
