# ============================================================

@dataclass(frozen=True)
class ConnectorTestResult:
    name: str
    passed: bool
    details: str = ""


# ============================================================
# 27. CONNECTOR TEST HARNESS
# ============================================================

class ConnectorTestHarness:

    def __init__(self) -> None:
        self.results: List[
            ConnectorTestResult
        ] = []

    def _record(
        self,
        name: str,
        passed: bool,
        details: str = "",
    ) -> None:

        self.results.append(
            ConnectorTestResult(
                name=name,
                passed=passed,
                details=details,
            )
        )

    def test_initialization(
        self,
        connector: CyberConnector,
    ) -> None:

        try:

            connector.initialize()

            self._record(
                "initialization",
                connector.status
                == ConnectorStatus.READY,
                f"status={connector.status.value}",
            )

        except Exception as exc:

            self._record(
                "initialization",
                False,
                repr(exc),
            )

    def test_capabilities(
        self,
        connector: CyberConnector,
    ) -> None:

        try:

            capabilities = (
                connector.capabilities()
            )

            valid = (
                isinstance(
                    capabilities,
                    frozenset,
                )
                and len(capabilities) > 0
                and all(
                    isinstance(
                        item,
                        ConnectorCapability,
                    )
                    for item in capabilities
                )
            )

            self._record(
                "capability_contract",
                valid,
                str(
                    [
                        x.value
                        for x in capabilities
                    ]
                ),
            )

        except Exception as exc:

            self._record(
                "capability_contract",
                False,
                repr(exc),
            )

    def test_health(
        self,
        connector: CyberConnector,
    ) -> None:

        try:

            health = connector.health_check()

            valid = (
                isinstance(
                    health,
                    ConnectorHealth,
                )
                and health.connector_id
                == connector.connector_id
            )

            self._record(
                "health_contract",
                valid,
                f"status={health.status.value}",
            )

        except Exception as exc:

            self._record(
                "health_contract",
                False,
                repr(exc),
            )

    def test_read_contract(
        self,
        connector: CyberConnector,
    ) -> None:

        try:

            result = connector.read()

            valid = (
                isinstance(
                    result,
                    ConnectorResult,
                )
                and result.success
                and all(
                    isinstance(
                        event,
                        ConnectorEvent,
                    )
                    for event in result.events
                )
            )

            self._record(
                "read_contract",
                valid,
                f"events={len(result.events)}",
            )

        except Exception as exc:

            self._record(
                "read_contract",
                False,
                repr(exc),
            )

    def test_tenant_boundary(
        self,
        connector: CyberConnector,
    ) -> None:

        try:

            result = connector.read()

            valid = all(
                event.tenant_id
                == connector.tenant_id
                and event.provenance.tenant_id
                == connector.tenant_id
                for event in result.events
            )

            self._record(
                "tenant_boundary",
                valid,
                "event tenant identity preserved",
            )

        except Exception as exc:

            self._record(
                "tenant_boundary",
                False,
                repr(exc),
            )

    def test_provenance(
        self,
        connector: CyberConnector,
    ) -> None:

        try:

            result = connector.read()

            valid = all(
                event.provenance.connector_id
                == connector.connector_id
                and event.provenance.connector_family
                == connector.family.value
                for event in result.events
            )

            self._record(
                "provenance",
                valid,
                "connector provenance preserved",
            )

        except Exception as exc:

            self._record(
                "provenance",
                False,
                repr(exc),
            )

    def test_idempotency(
        self,
        connector: CyberConnector,
    ) -> None:

        if not isinstance(
            connector,
            SimulatedConnector,
        ):
            return

        try:

            connector._cursor = 0

            first = connector.read()

            connector._cursor = 0

            second = connector.read()

            first_keys = {
                event.idempotency_key
                for event in first.events
            }

            second_keys = {
                event.idempotency_key
                for event in second.events
            }

            self._record(
                "idempotency",
                first_keys == second_keys,
                "stable source-event identity",
            )

        except Exception as exc:

            self._record(
                "idempotency",
                False,
                repr(exc),
            )

    def test_checkpointing(
        self,
        connector: CyberConnector,
    ) -> None:

        if not isinstance(
            connector,
            SimulatedConnector,
        ):
            return

        try:

            store = (
                InMemoryCheckpointStore()
            )

            poller = ConnectorPoller(
                connector,
                store,
            )

            result = poller.poll_once()

            checkpoint = store.get(
                connector.connector_id
            )

            valid = (
                result.success
                and checkpoint is not None
                and checkpoint.cursor
                == result.cursor
            )

            self._record(
                "checkpoint_contract",
                valid,
                f"cursor={result.cursor}",
            )

        except Exception as exc:

            self._record(
                "checkpoint_contract",
                False,
                repr(exc),
            )

    def test_registry(
        self,
        connector: CyberConnector,
    ) -> None:

        try:

            registry = (
                ConnectorRegistry()
            )

            registry.register(
                connector
            )

            retrieved = registry.get(
                connector.connector_id
            )

            self._record(
                "registry",
                retrieved is connector,
                "connector registration/retrieval",
            )

        except Exception as exc:

            self._record(
                "registry",
                False,
                repr(exc),
            )

    def run_all(
        self,
        connector: CyberConnector,
    ) -> List[ConnectorTestResult]:

        self.results.clear()

        self.test_initialization(
            connector
        )

        self.test_capabilities(
            connector
        )

        self.test_health(
            connector
        )

        self.test_read_contract(
            connector
        )

        self.test_tenant_boundary(
            connector
        )

        self.test_provenance(
            connector
        )

        self.test_idempotency(
            connector
        )

        self.test_checkpointing(
            connector
        )

        self.test_registry(
            connector
        )

        return list(self.results)

    def passed(self) -> bool:

        return (
            bool(self.results)
            and all(
                result.passed
                for result in self.results
            )
        )
    # --- preserved from ConnectorTestHarness (merged, not present in canonical host) ---
    def test_action_boundary(
        self,
        connector: CyberConnector,
    ) -> None:

        if not isinstance(
            connector,
            ActionConnector,
        ):
            self._record(
                "action_boundary",
                True,
                "Connector is read-only.",
            )
            return

        actions = [
            action
            for action
            in ConnectorAction
        ]

        if not actions:
            self._record(
                "action_boundary",
                False,
                "No action types defined.",
            )
            return

        try:

            connector.execute_action(
                actions[0],
                {},
            )

            self._record(
                "action_boundary",
                True,
                "Action contract callable.",
            )

        except ConnectorCapabilityError:

            self._record(
                "action_boundary",
                True,
                "Unsupported action explicitly rejected.",
            )

        except Exception as exc:

            self._record(
                "action_boundary",
                False,
                f"{type(exc).__name__}: {exc}",
            )
    # --- preserved from ConnectorTestHarness (merged, not present in canonical host) ---
    def test_event_tenant_integrity(
        self,
        connector: CyberConnector,
    ) -> None:

        if (
            ConnectorCapability.READ
            not in connector.capabilities()
        ):
            self._record(
                "tenant_integrity",
                True,
                "READ capability not required.",
            )
            return

        try:

            result = connector.read()

            valid = all(
                event.tenant_id
                == connector.tenant_id
                for event
                in result.events
            )

            self._record(
                "tenant_integrity",
                valid,
                (
                    f"events_checked="
                    f"{len(result.events)}"
                ),
            )

        except Exception as exc:

            self._record(
                "tenant_integrity",
                False,
                f"{type(exc).__name__}: {exc}",
            )
    # --- preserved from ConnectorTestHarness (merged, not present in canonical host) ---
    def test_read(
        self,
        connector: CyberConnector,
    ) -> None:

        if (
            ConnectorCapability.READ
            not in connector.capabilities()
        ):
            self._record(
                "read_contract",
                True,
                "READ capability not required.",
            )
            return

        try:

            result = connector.read()

            self._record(
                "read_contract",
                isinstance(
                    result,
                    ConnectorResult,
                )
                and result.success,
                (
                    f"events={len(result.events)}"
                ),
            )

        except Exception as exc:

            self._record(
                "read_contract",
                False,
                f"{type(exc).__name__}: {exc}",
            )


# ============================================================
# 28. SECURITY CONTRACT TESTS
# ============================================================

class ConnectorSecurityTests:

    @staticmethod
    def test_no_secret_in_config(
        config: ConnectorConfig,
    ) -> bool:

        serialized = json.dumps(
            {
                "connector_id":
                    config.connector_id,
                "tenant_id":
                    config.tenant_id,
                "name":
                    config.name,
                "family":
                    config.family.value,
                "endpoint":
                    config.endpoint,
                "auth_type":
                    config.auth_type.value,
                "credential_reference":
                    (
                        config
                        .credential_reference
                        .reference_id
                        if config.credential_reference
                        else None
                    ),
                "metadata":
                    dict(config.metadata),
            },
            default=str,
        ).lower()

        forbidden = [
            "password",
            "secret_value",
            "private_key",
            "access_key",
            "token_value",
        ]

        return not any(
            item in serialized
            for item in forbidden
        )

    @staticmethod
    def test_event_tenant_integrity(
        connector: CyberConnector,
    ) -> bool:

        result = connector.read()

        return all(
            event.tenant_id
            == connector.tenant_id
            and event.provenance.tenant_id
            == connector.tenant_id
            for event in result.events
        )
    # --- preserved from ConnectorSecurityTests (merged, not present in canonical host) ---
    @staticmethod
    def test_credential_reference_only(
        config: ConnectorConfig,
    ) -> bool:

        if config.auth_type == AuthType.NONE:
            return (
                config.credential_reference
                is None
            )

        return (
            config.credential_reference
            is not None
        )
    # --- preserved from ConnectorSecurityTests (merged, not present in canonical host) ---
    @staticmethod
    def test_cross_tenant_event_rejection(
        event: ConnectorEvent,
        expected_tenant_id: str,
    ) -> bool:

        return (
            event.tenant_id
            == expected_tenant_id
            and event.provenance.tenant_id
            == expected_tenant_id
        )


