def run_phase4_verification() -> None:

    print("=" * 70)
    print("NEXORA CYBER — PHASE 4 VERIFICATION")
    print("=" * 70)

    config = ConnectorConfig(
        connector_id="sim-edr-001",
        tenant_id="tenant-demo",
        name="Simulated EDR",
        family=ConnectorFamily.EDR_XDR,
    )

    # [BUGFIX — integration/hardening pass] these SimulatedEvents didn't pass
    # observed_at, so ConnectorEventFactory.create() fell back to "now" on every
    # read() call, giving each read a different idempotency_key for what's
    # supposed to be the same historical event -- exactly the failure the
    # idempotency test below caught. Real connectors always have a source
    # timestamp; the simulator should too.
    events = [
        SimulatedEvent(
            event_type="authentication",
            payload={
                "user":
                    "analyst@example.test",
                "result":
                    "success",
                "source_ip":
                    "192.0.2.10",
            },
            observed_at=datetime(2026, 1, 1, 0, 0, 0, tzinfo=timezone.utc),
            source_reference="sim-auth-001",
        ),

        SimulatedEvent(
            event_type="process",
            payload={
                "process":
                    "example.exe",
                "host":
                    "endpoint-01",
            },
            observed_at=datetime(2026, 1, 1, 0, 0, 1, tzinfo=timezone.utc),
            source_reference="sim-process-001",
        ),

        SimulatedEvent(
            event_type="network",
            payload={
                "destination":
                    "203.0.113.10",
                "port":
                    443,
            },
            observed_at=datetime(2026, 1, 1, 0, 0, 2, tzinfo=timezone.utc),
            source_reference="sim-net-001",
        ),
    ]

    connector = SimulatedConnector(
        config=config,
        events=events,
        actions=[
            ConnectorAction.ISOLATE_ENDPOINT,
            ConnectorAction.BLOCK_IOC,
            ConnectorAction.COLLECT_EVIDENCE,
        ],
    )

    harness = ConnectorTestHarness()

    results = harness.run_all(
        connector
    )

    for result in results:

        status = (
            "PASS"
            if result.passed
            else "FAIL"
        )

        print(
            f"[{status}] "
            f"{result.name}: "
            f"{result.details}"
        )

    security_1 = (
        ConnectorSecurityTests
        .test_no_secret_in_config(
            config
        )
    )

    security_2 = (
        ConnectorSecurityTests
        .test_event_tenant_integrity(
            connector
        )
    )

    print(
        "[{}] secret-boundary: {}".format(
            "PASS" if security_1 else "FAIL",
            "configuration contains no secret material"
        )
    )

    print(
        "[{}] tenant-integrity: {}".format(
            "PASS" if security_2 else "FAIL",
            "event tenant preserved"
        )
    )

    failure_results = {
        "initialize_failure":
            ConnectorFailureTests
            .test_initialize_failure(),

        "read_failure":
            ConnectorFailureTests
            .test_read_failure(),

        "health_failure":
            ConnectorFailureTests
            .test_health_failure(),

        "action_failure":
            ConnectorFailureTests
            .test_action_failure(),

        "family_coverage":
            verify_connector_family_coverage(),

        "action_contract":
            verify_action_contract(),
    }

    for name, passed in failure_results.items():

        print(
            "[{}] {}".format(
                "PASS" if passed else "FAIL",
                name,
            )
        )

    all_passed = (
        harness.passed()
        and security_1
        and security_2
        and all(
            failure_results.values()
        )
    )

    print("=" * 70)

    if not all_passed:

        print(
            "PHASE 4 VERIFICATION: FAILED"
        )

        raise AssertionError(
            "One or more Phase 4 verification "
            "tests failed."
        )

    print(
        "PHASE 4 VERIFICATION: PASSED"
    )

    print("=" * 70)


