# ============================================================
# 1. ENUMERATIONS
# ============================================================

class IOCType(str, Enum):
    IPV4 = "ipv4"
    IPV6 = "ipv6"
    DOMAIN = "domain"
    URL = "url"
    MD5 = "md5"
    SHA1 = "sha1"
    SHA256 = "sha256"
    EMAIL = "email"
    FILE_NAME = "file_name"
    REGISTRY_KEY = "registry_key"
    CVE = "cve"
    CERTIFICATE = "certificate"


class ConfidenceLevel(str, Enum):
    UNKNOWN = "unknown"
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    VERY_HIGH = "very_high"


class Reputation(str, Enum):
    UNKNOWN = "unknown"
    BENIGN = "benign"
    SUSPICIOUS = "suspicious"
    MALICIOUS = "malicious"


class RelationshipType(str, Enum):
    ATTRIBUTED_TO = "attributed_to"
    ASSOCIATED_WITH = "associated_with"
    USED_BY = "used_by"
    PART_OF = "part_of"
    DELIVERS = "delivers"
    DROPS = "drops"
    COMMUNICATES_WITH = "communicates_with"
    TARGETS = "targets"
    INDICATES = "indicates"
    USES_TECHNIQUE = "uses_technique"
    EXECUTES = 'executes'  # merged from RelationshipType


class EntityType(str, Enum):
    THREAT_ACTOR = "threat_actor"
    CAMPAIGN = "campaign"
