# ============================================================
# 2. VALIDATION / TIME HELPERS
# ============================================================

# [auto-repair] was a byte-for-byte duplicate of utc_now() -- consolidated to a thin alias (Repair Phase 6).
utc_now_v4 = utc_now


def ensure_utc(value: datetime) -> datetime:
    if value.tzinfo is None:
        return value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc)


def clamp_v2(value: float, minimum: float = 0.0, maximum: float = 1.0) -> float:
    return max(minimum, min(maximum, float(value)))


def confidence_to_score(level: ConfidenceLevel) -> float:
    return {
        ConfidenceLevel.UNKNOWN: 0.0,
        ConfidenceLevel.LOW: 0.25,
        ConfidenceLevel.MEDIUM: 0.50,
        ConfidenceLevel.HIGH: 0.75,
        ConfidenceLevel.VERY_HIGH: 1.0,
    }[level]


def validate_nonempty(value: str, field_name: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{field_name} must be a non-empty string")
    return value.strip()


# ============================================================
# 3. IOC NORMALIZATION
# ============================================================

class IOCNormalizer:
    """
    Pure Phase-5 IOC normalization.

    It does not enrich, detect, correlate, or investigate.
    """

    EMAIL_RE = re.compile(
        r"^[^@\s]+@[^@\s]+\.[^@\s]+$",
        re.IGNORECASE,
    )

    SHA256_RE = re.compile(r"^[a-fA-F0-9]{64}$")
    SHA1_RE = re.compile(r"^[a-fA-F0-9]{40}$")
    MD5_RE = re.compile(r"^[a-fA-F0-9]{32}$")
    CVE_RE = re.compile(r"^CVE-\d{4}-\d{4,}$", re.IGNORECASE)

    @staticmethod
    def normalize(value: str, ioc_type: IOCType) -> str:
        value = validate_nonempty(value, "IOC value")

        if ioc_type in {
            IOCType.IPV4,
            IOCType.IPV6,
        }:
            try:
                return str(ipaddress.ip_address(value))
            except ValueError as exc:
                raise ValueError(f"Invalid IP IOC: {value}") from exc

        if ioc_type == IOCType.DOMAIN:
            value = value.lower().rstrip(".")
            if not IOCNormalizer._valid_domain(value):
                raise ValueError(f"Invalid domain IOC: {value}")
            return value

        if ioc_type == IOCType.URL:
            parsed = urlparse(value)

            if parsed.scheme.lower() not in {"http", "https"}:
                raise ValueError("URL IOC must use HTTP or HTTPS")

            if not parsed.hostname:
                raise ValueError("URL IOC has no valid hostname")

            return value.strip()

        if ioc_type == IOCType.EMAIL:
            value = value.lower()
            if not IOCNormalizer.EMAIL_RE.match(value):
                raise ValueError(f"Invalid email IOC: {value}")
            return value

        if ioc_type == IOCType.MD5:
            if not IOCNormalizer.MD5_RE.match(value):
                raise ValueError("Invalid MD5 IOC")
            return value.lower()

        if ioc_type == IOCType.SHA1:
            if not IOCNormalizer.SHA1_RE.match(value):
                raise ValueError("Invalid SHA1 IOC")
            return value.lower()

        if ioc_type == IOCType.SHA256:
            if not IOCNormalizer.SHA256_RE.match(value):
                raise ValueError("Invalid SHA256 IOC")
            return value.lower()

        if ioc_type == IOCType.CVE:
            value = value.upper()
            if not IOCNormalizer.CVE_RE.match(value):
                raise ValueError(f"Invalid CVE identifier: {value}")
            return value

        return value.strip()

    @staticmethod
    def _valid_domain(value: str) -> bool:
        if len(value) > 253 or "." not in value:
            return False

        labels = value.split(".")

        for label in labels:
            if not label:
                return False
            if len(label) > 63:
                return False
            if label.startswith("-") or label.endswith("-"):
                return False
            if not re.match(r"^[a-z0-9-]+$", label):
                return False

        return True


# ============================================================
# 4. PROVENANCE
# ============================================================

@dataclass(frozen=True)
class ThreatIntelProvenance:
    source_id: str
    source_name: str
    source_type: str
    observed_at: datetime
    collected_at: datetime
    source_confidence: float = 0.5
    reference: Optional[str] = None
    raw_record_id: Optional[str] = None

    def __post_init__(self) -> None:
        validate_nonempty(self.source_id, "source_id")
        validate_nonempty(self.source_name, "source_name")
        validate_nonempty(self.source_type, "source_type")

        object.__setattr__(
            self,
            "source_confidence",
            clamp_v2(self.source_confidence),
        )

        object.__setattr__(
            self,
            "observed_at",
            ensure_utc(self.observed_at),
        )

        object.__setattr__(
            self,
            "collected_at",
            ensure_utc(self.collected_at),
        )
    metadata: Mapping[str, Any] = None  # merged from ThreatIntelProvenance, made optional for safety


# ============================================================
# 5. IOC MODEL
# ============================================================

@dataclass
class IOC:
    ioc_id: str
    tenant_id: str
    ioc_type: IOCType
    value: str

    first_seen: datetime
    last_seen: datetime

    confidence: ConfidenceLevel = ConfidenceLevel.UNKNOWN
    reputation: Reputation = Reputation.UNKNOWN

    tags: set[str] = field(default_factory=set)
    sources: List[ThreatIntelProvenance] = field(default_factory=list)

    enrichment: Dict[str, Any] = field(default_factory=dict)

    created_at: datetime = field(default_factory=utc_now_v4)
    updated_at: datetime = field(default_factory=utc_now_v4)

    active: bool = True

    def __post_init__(self) -> None:
        validate_nonempty(self.ioc_id, "ioc_id")
        validate_nonempty(self.tenant_id, "tenant_id")

        self.value = IOCNormalizer.normalize(
            self.value,
            self.ioc_type,
        )

        self.first_seen = ensure_utc(self.first_seen)
        self.last_seen = ensure_utc(self.last_seen)

        if self.last_seen < self.first_seen:
            raise ValueError("last_seen cannot be earlier than first_seen")

        self.created_at = ensure_utc(self.created_at)
        self.updated_at = ensure_utc(self.updated_at)

    @property
    def canonical_key(self) -> str:
        return (
            f"{self.tenant_id}:"
            f"{self.ioc_type.value}:"
            f"{self.value}"
        )

    @property
    def confidence_score(self) -> float:
        return confidence_to_score(self.confidence)

    def add_provenance(self, provenance: ThreatIntelProvenance) -> None:
        self.sources.append(provenance)
        self.updated_at = utc_now_v4()

    def add_tag(self, tag: str) -> None:
        tag = validate_nonempty(tag, "tag").lower()
        self.tags.add(tag)
        self.updated_at = utc_now_v4()

    def update_reputation(
        self,
        reputation: Reputation,
        confidence: ConfidenceLevel,
    ) -> None:
        self.reputation = reputation
        self.confidence = confidence
        self.updated_at = utc_now_v4()


