# ============================================================
# 8. FRESHNESS
# ============================================================

@dataclass(frozen=True)
class FreshnessResult:
    age_seconds: float
    freshness_score: float
    stale: bool


class FreshnessCalculator:
    def __init__(self, stale_after: timedelta = timedelta(days=30)):
        self.stale_after = stale_after

    def calculate(
        self,
        observed_at: datetime,
        now: Optional[datetime] = None,
    ) -> FreshnessResult:
        now = ensure_utc(now or utc_now_v4())
        observed_at = ensure_utc(observed_at)

        age = max(0.0, (now - observed_at).total_seconds())
        threshold = self.stale_after.total_seconds()

        if threshold <= 0:
            raise ValueError("stale_after must be positive")

        score = clamp_v2(1.0 - (age / threshold))

        return FreshnessResult(
            age_seconds=age,
            freshness_score=score,
            stale=age > threshold,
        )


# ============================================================
# 9. THREAT SCORE
# ============================================================

@dataclass(frozen=True)
class ThreatScore:
    score: float
    reputation_component: float
    confidence_component: float
    freshness_component: float
    provenance_component: float
    enrichment_component: float
    rationale: Tuple[str, ...]


class ThreatIntelScorer:
    """
    TI score only.

    This is NOT the Cyber Risk Engine.
    It deliberately does not calculate asset/identity/
    vulnerability/attack-path/business risk.
    """

    REPUTATION_WEIGHT = 0.35
    CONFIDENCE_WEIGHT = 0.20
    FRESHNESS_WEIGHT = 0.20
    PROVENANCE_WEIGHT = 0.15
    ENRICHMENT_WEIGHT = 0.10

    def score(
        self,
        ioc: IOC,
        now: Optional[datetime] = None,
    ) -> ThreatScore:

        reputation_component = {
            Reputation.UNKNOWN: 0.0,
            Reputation.BENIGN: 0.0,
            Reputation.SUSPICIOUS: 0.60,
            Reputation.MALICIOUS: 1.0,
        }[ioc.reputation]

        freshness = FreshnessCalculator().calculate(
            ioc.last_seen,
            now,
        )

        provenance_component = clamp_v2(
            len(ioc.sources) / 3.0
        )

        enrichment_component = clamp_v2(
            len(ioc.enrichment) / 10.0
        )

        score = (
            reputation_component * self.REPUTATION_WEIGHT
            + ioc.confidence_score * self.CONFIDENCE_WEIGHT
            + freshness.freshness_score * self.FRESHNESS_WEIGHT
            + provenance_component * self.PROVENANCE_WEIGHT
            + enrichment_component * self.ENRICHMENT_WEIGHT
        )

        rationale: List[str] = []

        if ioc.reputation == Reputation.MALICIOUS:
            rationale.append("source reputation is malicious")

        if ioc.confidence in {
            ConfidenceLevel.HIGH,
            ConfidenceLevel.VERY_HIGH,
        }:
            rationale.append("high-confidence intelligence")

        if freshness.stale:
            rationale.append("intelligence is stale")
        else:
            rationale.append("intelligence is relatively fresh")

        if len(ioc.sources) > 1:
            rationale.append("multiple provenance records exist")

        if ioc.enrichment:
            rationale.append("enrichment metadata is available")

        return ThreatScore(
            score=clamp_v2(score),
            reputation_component=reputation_component,
            confidence_component=ioc.confidence_score,
            freshness_component=freshness.freshness_score,
            provenance_component=provenance_component,
            enrichment_component=enrichment_component,
            rationale=tuple(rationale),
        )


