# ============================================================
# 11. PROVIDER REGISTRY
# ============================================================

class ThreatIntelProviderRegistry:

    def __init__(self) -> None:
        self._providers: Dict[str, ThreatIntelProvider] = {}
        self._lock = threading.RLock()

    def register(self, provider: ThreatIntelProvider) -> None:
        provider_id = validate_nonempty(
            provider.provider_id,
            "provider_id",
        )

        with self._lock:
            if provider_id in self._providers:
                raise ValueError(
                    f"Provider already registered: {provider_id}"
                )

            self._providers[provider_id] = provider

    def unregister(self, provider_id: str) -> None:
        with self._lock:
            self._providers.pop(provider_id, None)

    def get_all(self) -> Tuple[ThreatIntelProvider, ...]:
        with self._lock:
            return tuple(self._providers.values())
    # --- preserved from ThreatIntelProviderRegistry (merged, not present in canonical host) ---
    def count(self) -> int:

        with self._lock:
            return len(
                self._providers
            )
    # --- preserved from ThreatIntelProviderRegistry (merged, not present in canonical host) ---
    def get(
        self,
        provider_id: str,
    ) -> ThreatIntelProvider:

        provider_id = validate_identifier(
            provider_id,
            "provider_id",
        )

        with self._lock:

            provider = self._providers.get(
                provider_id
            )

            if provider is None:
                raise KeyError(
                    f"Provider not found: "
                    f"{provider_id}"
                )

            return provider


# ============================================================
# 12. PHASE 5 REPOSITORY
# ============================================================

class ThreatIntelRepository:

    def __init__(self) -> None:
        self._iocs: Dict[str, IOC] = {}
        self._records: Dict[str, ThreatIntelRecord] = {}

        self._actors: Dict[str, ThreatActor] = {}
        self._campaigns: Dict[str, Campaign] = {}
        self._malware: Dict[str, Malware] = {}
        self._techniques: Dict[str, ATTACKTechnique] = {}

        self._relationships: Dict[str, ThreatRelationship] = {}

        self._lock = threading.RLock()

    # --------------------------------------------------------
    # IOC
    # --------------------------------------------------------

    def upsert_ioc(self, ioc: IOC) -> IOC:
        with self._lock:
            existing = self._iocs.get(ioc.canonical_key)

            if existing is None:
                self._iocs[ioc.canonical_key] = ioc
                return ioc

            existing.first_seen = min(
                existing.first_seen,
                ioc.first_seen,
            )

            existing.last_seen = max(
                existing.last_seen,
                ioc.last_seen,
            )

            existing.tags.update(ioc.tags)

            existing.sources.extend(
                source
                for source in ioc.sources
                if source not in existing.sources
            )

            if ioc.confidence_score > existing.confidence_score:
                existing.confidence = ioc.confidence

            if (
                existing.reputation != Reputation.MALICIOUS
                and ioc.reputation == Reputation.MALICIOUS
            ):
                existing.reputation = Reputation.MALICIOUS

            existing.enrichment.update(ioc.enrichment)
            existing.updated_at = utc_now_v4()

            return existing

    def get_ioc(
        self,
        tenant_id: str,
        ioc_type: IOCType,
        value: str,
    ) -> Optional[IOC]:

        normalized = IOCNormalizer.normalize(
            value,
            ioc_type,
        )

        key = f"{tenant_id}:{ioc_type.value}:{normalized}"

        with self._lock:
            return self._iocs.get(key)

    def list_iocs(
        self,
        tenant_id: str,
        ioc_type: Optional[IOCType] = None,
    ) -> List[IOC]:

        with self._lock:
            result = [
                ioc
                for ioc in self._iocs.values()
                if ioc.tenant_id == tenant_id
            ]

            if ioc_type is not None:
                result = [
                    ioc
                    for ioc in result
                    if ioc.ioc_type == ioc_type
                ]

            return list(result)

    # --------------------------------------------------------
    # Threat entities
    # --------------------------------------------------------

    def save_actor(self, actor: ThreatActor) -> None:
        with self._lock:
            self._actors[actor.actor_id] = actor

    def save_campaign(self, campaign: Campaign) -> None:
        with self._lock:
            self._campaigns[campaign.campaign_id] = campaign

    def save_malware(self, malware: Malware) -> None:
        with self._lock:
            self._malware[malware.malware_id] = malware

    def save_technique(self, technique: ATTACKTechnique) -> None:
        with self._lock:
            self._techniques[technique.technique_id] = technique

    def get_actor(self, actor_id: str) -> Optional[ThreatActor]:
        return self._actors.get(actor_id)

    def get_campaign(self, campaign_id: str) -> Optional[Campaign]:
        return self._campaigns.get(campaign_id)

    def get_malware(self, malware_id: str) -> Optional[Malware]:
        return self._malware.get(malware_id)

    def get_technique(
        self,
        technique_id: str,
    ) -> Optional[ATTACKTechnique]:
        return self._techniques.get(technique_id)

    # --------------------------------------------------------
    # TI records
    # --------------------------------------------------------

    def save_record(self, record: ThreatIntelRecord) -> None:
        with self._lock:
            self._records[record.record_id] = record

    def get_record(
        self,
        record_id: str,
        tenant_id: str,
    ) -> Optional[ThreatIntelRecord]:
        # [auto-repair] added a required tenant_id. ThreatIntelRecord
        # has its own tenant_id field (unlike ThreatActor/Campaign/
        # Malware/ATTACKTechnique above, which are genuinely global
        # threat-intel data with no tenant_id field at all -- those are
        # fine as-is). This previously returned any tenant's record to
        # anyone who knew/guessed a record_id, same pattern as the
        # SessionManager/ApprovalManager fixes elsewhere in this file.
        with self._lock:
            record = self._records.get(record_id)
            if record is not None and record.tenant_id != tenant_id:
                return None
            return record

    # --------------------------------------------------------
    # Relationships
    # --------------------------------------------------------

    def save_relationship(
        self,
        relationship: ThreatRelationship,
    ) -> None:

        relationship_key = self._relationship_key(
            relationship
        )

        with self._lock:
            self._relationships[relationship_key] = relationship

    def get_relationships(
        self,
        source_id: Optional[str] = None,
        target_id: Optional[str] = None,
    ) -> List[ThreatRelationship]:

        with self._lock:
            relationships = list(
                self._relationships.values()
            )

        if source_id is not None:
            relationships = [
                r for r in relationships
                if r.source_id == source_id
            ]

        if target_id is not None:
            relationships = [
                r for r in relationships
                if r.target_id == target_id
            ]

        return relationships

    @staticmethod
    def _relationship_key(
        relationship: ThreatRelationship,
    ) -> str:

        return "|".join(
            [
                relationship.source_type.value,
                relationship.source_id,
                relationship.relationship.value,
                relationship.target_type.value,
                relationship.target_id,
            ]
        )


# ============================================================
# 13. RECORD ID GENERATION
# ============================================================

def deterministic_id(*parts: str) -> str:
    payload = "|".join(parts).encode("utf-8")
    return sha256(payload).hexdigest()


# ============================================================
# 14. INGESTION SERVICE
# ============================================================

@dataclass(frozen=True)
class IOCInput:
    tenant_id: str
    ioc_type: IOCType
    value: str

    observed_at: datetime

    source: ThreatIntelProvenance

    reputation: Reputation = Reputation.UNKNOWN
    confidence: ConfidenceLevel = ConfidenceLevel.UNKNOWN

    tags: Tuple[str, ...] = ()

    enrichment: Mapping[str, Any] = field(
        default_factory=dict
    )


class ThreatIntelService:

    def __init__(
        self,
        repository: ThreatIntelRepository,
        provider_registry: Optional[
            ThreatIntelProviderRegistry
        ] = None,
        scorer: Optional[ThreatIntelScorer] = None,
    ) -> None:

        self.repository = repository

        self.providers = (
            provider_registry
            or ThreatIntelProviderRegistry()
        )

        self.scorer = scorer or ThreatIntelScorer()

    # --------------------------------------------------------
    # INGEST
    # --------------------------------------------------------

    def ingest_ioc(
        self,
        payload: IOCInput,
    ) -> IOC:

        validate_nonempty(
            payload.tenant_id,
            "tenant_id",
        )

        normalized = IOCNormalizer.normalize(
            payload.value,
            payload.ioc_type,
        )

        observed_at = ensure_utc(
            payload.observed_at
        )

        ioc_id = deterministic_id(
            payload.tenant_id,
            payload.ioc_type.value,
            normalized,
        )

        ioc = IOC(
            ioc_id=ioc_id,
            tenant_id=payload.tenant_id,
            ioc_type=payload.ioc_type,
            value=normalized,
            first_seen=observed_at,
            last_seen=observed_at,
            confidence=payload.confidence,
            reputation=payload.reputation,
            tags=set(payload.tags),
            sources=[payload.source],
            enrichment=dict(payload.enrichment),
        )

        return self.repository.upsert_ioc(ioc)

    # --------------------------------------------------------
    # ENRICH
    # --------------------------------------------------------

    def enrich_ioc(
        self,
        tenant_id: str,
        ioc_type: IOCType,
        value: str,
    ) -> IOC:

        ioc = self.repository.get_ioc(
            tenant_id,
            ioc_type,
            value,
        )

        if ioc is None:
            raise KeyError("IOC not found")

        for provider in self.providers.get_all():

            record = provider.lookup(
                ioc.ioc_type,
                ioc.value,
            )

            if record is None:
                continue

            if record.tenant_id != tenant_id:
                raise SecurityError(
                    "Provider returned cross-tenant intelligence"
                )

            if record.ioc_id != ioc.ioc_id:
                raise SecurityError(
                    "Provider returned mismatched IOC identity"
                )

            ioc.update_reputation(
                record.reputation,
                record.confidence,
            )

            ioc.enrichment.update(
                dict(record.enrichment)
            )

            for actor_id in record.threat_actor_ids:
                self._attach_actor(
                    ioc,
                    actor_id,
                    record,
                )

            for campaign_id in record.campaign_ids:
                self._attach_campaign(
                    ioc,
                    campaign_id,
                    record,
                )

            for malware_id in record.malware_ids:
                self._attach_malware(
                    ioc,
                    malware_id,
                    record,
                )

            for technique_id in record.technique_ids:
                self._attach_technique(
                    ioc,
                    technique_id,
                    record,
                )

        return ioc

    # --------------------------------------------------------
    # SCORE
    # --------------------------------------------------------

    def score_ioc(
        self,
        tenant_id: str,
        ioc_type: IOCType,
        value: str,
    ) -> ThreatScore:

        ioc = self.repository.get_ioc(
            tenant_id,
            ioc_type,
            value,
        )

        if ioc is None:
            raise KeyError("IOC not found")

        return self.scorer.score(ioc)

    # --------------------------------------------------------
    # SEARCH
    # --------------------------------------------------------

    def search(
        self,
        tenant_id: str,
        query: str,
    ) -> List[IOC]:

        query = validate_nonempty(
            query,
            "query",
        ).lower()

        results = []

        for ioc in self.repository.list_iocs(
            tenant_id
        ):
            if (
                query in ioc.value.lower()
                or query in ioc.ioc_id.lower()
                or any(
                    query in tag.lower()
                    for tag in ioc.tags
                )
            ):
                results.append(ioc)

        return results

    # --------------------------------------------------------
    # RELATIONSHIP ATTACHMENT
    # --------------------------------------------------------

    def _attach_actor(
        self,
        ioc: IOC,
        actor_id: str,
        record: ThreatIntelRecord,
    ) -> None:

        relationship = ThreatRelationship(
            source_type=EntityType.THREAT_ACTOR,
            source_id=actor_id,
            relationship=RelationshipType.INDICATES,
            target_type=self._ioc_entity_type(),
            target_id=ioc.ioc_id,
            confidence=confidence_to_score(
                record.confidence
            ),
            provenance=record.source,
        )

        self.repository.save_relationship(
            relationship
        )

    def _attach_campaign(
        self,
        ioc: IOC,
        campaign_id: str,
        record: ThreatIntelRecord,
    ) -> None:

        relationship = ThreatRelationship(
            source_type=EntityType.CAMPAIGN,
            source_id=campaign_id,
            relationship=RelationshipType.INDICATES,
            target_type=self._ioc_entity_type(),
            target_id=ioc.ioc_id,
            confidence=confidence_to_score(
                record.confidence
            ),
            provenance=record.source,
        )

        self.repository.save_relationship(
            relationship
        )

    def _attach_malware(
        self,
        ioc: IOC,
        malware_id: str,
        record: ThreatIntelRecord,
    ) -> None:

        relationship = ThreatRelationship(
            source_type=EntityType.MALWARE,
            source_id=malware_id,
            relationship=RelationshipType.INDICATES,
            target_type=self._ioc_entity_type(),
            target_id=ioc.ioc_id,
            confidence=confidence_to_score(
                record.confidence
            ),
            provenance=record.source,
        )

        self.repository.save_relationship(
            relationship
        )

    def _attach_technique(
        self,
        ioc: IOC,
        technique_id: str,
        record: ThreatIntelRecord,
    ) -> None:

        relationship = ThreatRelationship(
            source_type=EntityType.TECHNIQUE,
            source_id=technique_id,
            relationship=RelationshipType.INDICATES,
            target_type=self._ioc_entity_type(),
            target_id=ioc.ioc_id,
            confidence=confidence_to_score(
                record.confidence
            ),
            provenance=record.source,
        )

        self.repository.save_relationship(
            relationship
        )

    @staticmethod
    def _ioc_entity_type() -> EntityType:
        # IOC is intentionally not added to the Phase-5
        # threat-entity taxonomy as a graph engine concept.
        #
        # Relationships are represented through a neutral
        # serialized entity namespace.
        return EntityType.TECHNIQUE
    # --- preserved from ThreatIntelService (merged, not present in canonical host) ---
    def _apply_provider_record(
        self,
        ioc: IOC,
        record: ThreatIntelRecord,
    ) -> None:

        ioc.add_provenance(
            record.source
        )

        ioc.enrichment.update(
            record.enrichment
        )

        reputation_priority = {
            Reputation.UNKNOWN: 0,
            Reputation.BENIGN: 1,
            Reputation.SUSPICIOUS: 2,
            Reputation.MALICIOUS: 3,
        }

        if (
            reputation_priority[
                record.reputation
            ]
            >
            reputation_priority[
                ioc.reputation
            ]
        ):

            ioc.reputation = (
                record.reputation
            )

        if (
            confidence_to_score(
                record.confidence
            )
            >
            ioc.confidence_score
        ):

            ioc.confidence = (
                record.confidence
            )

        for actor_id in (
            record.threat_actor_ids
        ):

            self._attach_actor(
                ioc,
                actor_id,
                record,
            )

        for campaign_id in (
            record.campaign_ids
        ):

            self._attach_campaign(
                ioc,
                campaign_id,
                record,
            )

        for malware_id in (
            record.malware_ids
        ):

            self._attach_malware(
                ioc,
                malware_id,
                record,
            )

        for technique_id in (
            record.technique_ids
        ):

            self._attach_technique(
                ioc,
                technique_id,
                record,
            )

        self.repository.save_record(
            record
        )


class SecurityError(Exception):
    """Raised when a Phase-5 security boundary is violated."""


# ============================================================
# 15. SIMULATED THREAT INTEL PROVIDER
# ============================================================

class SimulatedThreatIntelProvider:

    def __init__(
        self,
        provider_id: str,
        records: Iterable[ThreatIntelRecord],
    ) -> None:

        self._provider_id = validate_nonempty(
            provider_id,
            "provider_id",
        )

        self._records: Dict[
            Tuple[IOCType, str],
            ThreatIntelRecord,
        ] = {}

        for record in records:
            # Simulation intentionally stores provider records
            # by IOC id. Actual provider adapters can implement
            # the same contract independently.
            self._records[
                ("record", record.ioc_id)
            ] = record

    @property
    def provider_id(self) -> str:
        return self._provider_id

    def lookup(
        self,
        ioc_type: IOCType,
        value: str,
    ) -> Optional[ThreatIntelRecord]:

        normalized = IOCNormalizer.normalize(
            value,
            ioc_type,
        )

        ioc_id_candidates = [
            deterministic_id(
                record.tenant_id,
                ioc_type.value,
                normalized,
            )
            for record in self._records.values()
        ]

        for record in self._records.values():
            if record.ioc_id in ioc_id_candidates:
                return record

        return None


# ============================================================
# 16. BULK INGESTION
# ============================================================

@dataclass(frozen=True)
class BulkIngestionResult:
    accepted: int
    rejected: int
    errors: Tuple[str, ...]
    record_ids: Tuple[str, ...] = None  # merged from BulkIngestionResult, made optional for safety


class ThreatIntelBulkIngestor:

    def __init__(
        self,
        service: ThreatIntelService,
    ) -> None:
        self.service = service

    def ingest(
        self,
        records: Sequence[IOCInput],
    ) -> BulkIngestionResult:

        accepted = 0
        rejected = 0
        errors: List[str] = []

        for index, record in enumerate(records):

            try:
                self.service.ingest_ioc(record)
                accepted += 1

            except Exception as exc:
                rejected += 1
                errors.append(
                    f"record[{index}]: {type(exc).__name__}: {exc}"
                )

        return BulkIngestionResult(
            accepted=accepted,
            rejected=rejected,
            errors=tuple(errors),
        )


# ============================================================
# 17. ATT&CK REGISTRY
# ============================================================

class ATTACKRegistry:

    def __init__(self) -> None:
        self._techniques: Dict[
            str,
            ATTACKTechnique,
        ] = {}

    def register(
        self,
        technique: ATTACKTechnique,
    ) -> None:

        if technique.technique_id in self._techniques:
            raise ValueError(
                f"Technique already exists: "
                f"{technique.technique_id}"
            )

        self._techniques[
            technique.technique_id
        ] = technique

    def get(
        self,
        technique_id: str,
    ) -> Optional[ATTACKTechnique]:

        return self._techniques.get(technique_id)

    def all(self) -> Tuple[ATTACKTechnique, ...]:
        return tuple(
            self._techniques.values()
        )


