    def __init__(
        self,
        repository: Optional[
            ThreatIntelRepository
        ] = None,
    ) -> None:

        self.repository = (
            repository
            or ThreatIntelRepository()
        )

        self.providers = (
            ThreatIntelProviderRegistry()
        )

        self.service = ThreatIntelService(
            repository=self.repository,
            provider_registry=self.providers,
        )

        # [auto-repair] bulk_ingest() below already expected
        # self.bulk_ingestor; nothing ever set it, even though a working
        # ThreatIntelBulkIngestor class already exists in this file.
        # Wiring it here instead of deleting the (otherwise fine)
        # bulk_ingest() method.
        self.bulk_ingestor = ThreatIntelBulkIngestor(self.service)

        self.attack_registry = ATTACKRegistry()

    def register_provider(
        self,
        provider: ThreatIntelProvider,
    ) -> None:

        self.providers.register(provider)

    def ingest(
        self,
        payload: IOCInput,
    ) -> IOC:

        return self.service.ingest_ioc(
            payload
        )

    def enrich(
        self,
        tenant_id: str,
        ioc_type: IOCType,
        value: str,
    ) -> IOC:

        return self.service.enrich_ioc(
            tenant_id,
            ioc_type,
            value,
        )

    def score(
        self,
        tenant_id: str,
        ioc_type: IOCType,
        value: str,
    ) -> ThreatScore:

        return self.service.score_ioc(
            tenant_id,
            ioc_type,
            value,
        )

    def search(
        self,
        tenant_id: str,
        query: str,
    ) -> List[IOC]:

        return self.service.search(
            tenant_id,
            query,
        )

    def register_attack_technique(
        self,
        technique: ATTACKTechnique,
    ) -> None:

        self.attack_registry.register(
            technique
        )
    # --- preserved from CyberThreatIntelligence (merged, not present in canonical host) ---
    def bulk_ingest(
        self,
        records: Sequence[IOCInput],
    ) -> BulkIngestionResult:

        return self.bulk_ingestor.ingest(
            records
        )


