def _test_freshness_degrades() -> None:
    calculator = FreshnessCalculator(
        stale_after=timedelta(days=10)
    )

    now = utc_now_v4()

    fresh = calculator.calculate(
        now - timedelta(hours=1),
        now,
    )

    old = calculator.calculate(
        now - timedelta(days=20),
        now,
    )

    assert fresh.freshness_score > old.freshness_score
    assert old.stale is True


