def _test_cross_tenant_provider_result_rejected() -> None:
    repo = ThreatIntelRepository()

    now = utc_now_v4()

    source = ThreatIntelProvenance(
        source_id="provider",
        source_name="provider",
        source_type="simulator",
        observed_at=now,
        collected_at=now,
    )

    target_ioc_id = deterministic_id(
        "tenant-b",
        IOCType.IPV4.value,
        "8.8.8.8",
    )

    record = ThreatIntelRecord(
        record_id="record",
        tenant_id="tenant-b",
        ioc_id=target_ioc_id,
        source=source,
        reputation=Reputation.MALICIOUS,
        confidence=ConfidenceLevel.HIGH,
    )

    provider = SimulatedThreatIntelProvider(
        "provider",
        [record],
    )

    registry = ThreatIntelProviderRegistry()
    registry.register(provider)

    service = ThreatIntelService(
        repo,
        registry,
    )

    service.ingest_ioc(
        IOCInput(
            tenant_id="tenant-a",
            ioc_type=IOCType.IPV4,
            value="8.8.8.8",
            observed_at=now,
            source=source,
        )
    )

    # The simulated provider record deliberately belongs
    # to another tenant. The service must reject it.
    try:
        service.enrich_ioc(
            "tenant-a",
            IOCType.IPV4,
            "8.8.8.8",
        )
    except SecurityError:
        return

    raise AssertionError(
        "Cross-tenant provider intelligence was accepted"
    )


