class Role:
    role_id: str
    name: str
    permissions: Set[str] = field(default_factory=set)


class RBACManager:
    def __init__(self) -> None:
        self._roles: Dict[str, Role] = {}
        self._permissions: Dict[str, Permission] = {}
        # [auto-repair] was Dict[str, Set[str]], keyed on principal_id
        # alone. Nothing in this file guarantees principal_id is
        # globally unique across tenants (TenantPrincipal treats
        # (tenant_id, principal_id) as the real identity everywhere
        # else) -- so two tenants both having a user called "admin"
        # meant assigning a role to one could silently also grant it to
        # the other. Roles/permissions themselves stay global
        # (shared definitions like "security_analyst" are fine to
        # share), but who-has-which-role is now tenant-scoped.
        self._principal_roles: Dict[Tuple[str, str], Set[str]] = {}
        self._lock = threading.RLock()

    def register_permission(
        self,
        permission: Permission,
    ) -> None:
        with self._lock:
            self._permissions[permission.permission_id] = permission

    def register_role(
        self,
        role: Role,
    ) -> None:
        with self._lock:
            self._roles[role.role_id] = role

    def assign_role(
        self,
        principal_id: str,
        role_id: str,
        *,
        tenant_id: str,
    ) -> None:
        with self._lock:
            if role_id not in self._roles:
                raise AuthorizationError(
                    f"Unknown role: {role_id}"
                )

            self._principal_roles.setdefault(
                (tenant_id, principal_id),
                set(),
            ).add(role_id)

    def revoke_role(
        self,
        principal_id: str,
        role_id: str,
        *,
        tenant_id: str,
    ) -> None:
        with self._lock:
            self._principal_roles.get(
                (tenant_id, principal_id),
                set(),
            ).discard(role_id)

    def has_permission(
        self,
        principal_id: str,
        resource: str,
        operation: str,
        *,
        tenant_id: str,
        scope: Optional[str] = None,
    ) -> bool:
        with self._lock:
            role_ids = self._principal_roles.get(
                (tenant_id, principal_id),
                set(),
            )

            for role_id in role_ids:
                role = self._roles.get(role_id)

                if role is None:
                    continue

                for permission_id in role.permissions:
                    permission = self._permissions.get(
                        permission_id
                    )

                    if permission and permission.matches(
                        resource,
                        operation,
                        scope,
                    ):
                        return True

            return False


