@dataclass(frozen=True)
class SecurityAttributes:
    values: Mapping[str, Any]

    def get(self, key: str, default: Any = None) -> Any:
        return self.values.get(key, default)


@dataclass(frozen=True)
class AuthorizationRequest:
    principal: TenantPrincipal
    resource: str
    operation: str
    resource_tenant_id: str
    resource_attributes: SecurityAttributes = field(
        default_factory=lambda: SecurityAttributes({})
    )
    environment_attributes: SecurityAttributes = field(
        default_factory=lambda: SecurityAttributes({})
    )
# --- preserved from AuthorizationRequest (merged, not present in canonical host) ---
    def validate(self) -> None:
        # [auto-repair] was self.tenant_id, which doesn't exist on this
        # class -- the real field is resource_tenant_id.
        require_non_empty(
            self.resource_tenant_id,
            "resource_tenant_id",
        )

        if self.principal.tenant_id != self.resource_tenant_id:
            raise TenantIsolationError(
                "Principal tenant does not match request tenant"
            )


class ABACEngine:
    """
    Small deterministic ABAC engine.

    Rules are callable predicates. Rules are evaluated server-side.
    """

    def __init__(self) -> None:
        self._rules: List[Any] = []
        self._lock = threading.RLock()

    def add_rule(self, predicate) -> None:
        with self._lock:
            self._rules.append(predicate)

    def evaluate(
        self,
        request: AuthorizationRequest,
    ) -> bool:
        for rule in list(self._rules):
            if not bool(rule(request)):
                return False

        return True
    # --- preserved from ABACEngine (merged, not present in canonical host) ---
    def clear(self) -> None:
        with self._lock:
            self._rules.clear()


