# MFA
# =============================================================================

class MFAProvider:
    """
    Provider boundary.

    Actual enterprise MFA is supplied by an identity provider.
    This class does not pretend to perform external MFA verification.
    """

    def __init__(self) -> None:
        # NOTE(auto-repair): create_challenge() below (issuing/tracking a
        # local challenge code) needs this state regardless of which
        # verify() implementation a subclass provides -- issuing a
        # challenge for the user to respond to isn't the part this class
        # deliberately declines to fake (that's the actual cryptographic
        # verification in verify()).
        self._lock = threading.RLock()
        self._challenges: Dict[str, "MFAChallenge"] = {}

    def verify(
        self,
        principal: TenantPrincipal,
        assertion: Optional[str],
    ) -> bool:
        raise NotImplementedError
    # --- preserved from MFAProvider (merged, not present in canonical host) ---
    def create_challenge(
        self,
        actor_id: str,
        tenant_id: str,
        ttl_seconds: int = 300,
    ) -> MFAChallenge:
        challenge = MFAChallenge(
            challenge_id=secrets.token_urlsafe(32),
            actor_id=actor_id,
            tenant_id=tenant_id,
            expires_at=now_ts() + ttl_seconds,
        )

        with self._lock:
            self._challenges[challenge.challenge_id] = challenge

        return challenge

    def verify_challenge(
        self,
        challenge_id: str,
        actor_id: str,
        validator: Callable[["MFAChallenge"], bool],
    ) -> bool:
        # NOTE(auto-repair): this method didn't exist -- callers (e.g.
        # Phase 21's own self-test) verify a previously-issued challenge by
        # id + actor + a caller-supplied validator callback, a different
        # shape than the abstract verify(principal, assertion) above (which
        # deliberately stays unimplemented pending a real IdP). Looking up
        # and expiring/validating a locally-issued challenge isn't the part
        # that gets faked.
        with self._lock:
            challenge = self._challenges.get(challenge_id)

            if challenge is None:
                return False

            if challenge.actor_id != actor_id:
                return False

            if challenge.expires_at < now_ts():
                return False

            ok = bool(validator(challenge))

            if ok:
                challenge.verified = True

            return ok


class AssertionMFAProvider(MFAProvider):
    """
    Testable local MFA assertion provider.

    Production deployment should replace this with a real IdP-backed
    verification implementation.
    """

    def __init__(self, expected_assertion: str) -> None:
        super().__init__()
        self._expected = expected_assertion

    def verify(
        self,
        principal: TenantPrincipal,
        assertion: Optional[str],
    ) -> bool:
        return bool(
            assertion
            and hmac.compare_digest(
                assertion,
                self._expected,
            )
        )


class MFAEnforcer:
    def __init__(
        self,
        provider: MFAProvider,
    ) -> None:
        self.provider = provider

    def require(
        self,
        principal: TenantPrincipal,
        assertion: Optional[str],
    ) -> TenantPrincipal:
        if principal.mfa_verified:
            return principal

        if not self.provider.verify(
            principal,
            assertion,
        ):
            raise AuthenticationError(
                "MFA verification failed."
            )

        return TenantPrincipal(
            principal_id=principal.principal_id,
            actor_type=principal.actor_type,
            tenant_id=principal.tenant_id,
            authenticated=principal.authenticated,
            mfa_verified=True,
        )


# =============================================================================
# OIDC / SAML SECURITY BOUNDARIES
# =============================================================================

@dataclass(frozen=True)
class IdentityProviderConfig:
    provider_id: str
    issuer: str
    client_id: str
    enabled: bool = True


class OIDCProvider:
    """
    Protocol boundary only.

    No fabricated provider calls.
    """

    def __init__(
        self,
        config: IdentityProviderConfig,
    ) -> None:
        self.config = config

    def authorization_url(
        self,
        state: str,
        redirect_uri: str,
    ) -> str:
        if not self.config.enabled:
            raise AuthenticationError(
                "OIDC provider is disabled."
            )

        if not state:
            raise ValidationError(
                "OIDC state is required."
            )

        if not redirect_uri.startswith("https://"):
            raise ValidationError(
                "OIDC redirect URI must use HTTPS."
            )

        return (
            f"{self.config.issuer}"
            f"?client_id={self.config.client_id}"
            f"&state={state}"
            f"&redirect_uri={redirect_uri}"
        )

    def validate_callback(
        self,
        expected_state: str,
        received_state: str,
    ) -> None:
        if not hmac.compare_digest(
            expected_state,
            received_state,
        ):
            raise AuthenticationError(
                "OIDC state validation failed."
            )
    # --- preserved from OIDCProvider (merged, not present in canonical host) ---
    def authenticate(
        self,
        authorization_code: str,
    ) -> TenantPrincipal:
        raise NotImplementedError(
            "Bind OIDCProvider to an actual enterprise IdP adapter."
        )
    # --- preserved from OIDCProvider (merged, not present in canonical host) ---
    def validate_configuration(self) -> bool:
        return bool(
            self.config.enabled
            and self.config.issuer
            and self.config.client_id
        )


class SAMLProvider:
    """
    SAML integration boundary.

    Actual XML signature/assertion validation belongs to the configured
    enterprise identity provider adapter.
    """

    def __init__(
        self,
        config: IdentityProviderConfig,
    ) -> None:
        self.config = config

    def validate_assertion(
        self,
        assertion: Mapping[str, Any],
    ) -> bool:
        """
        [auto-repair] Clarified what this actually checks. This is a
        SHAPE/CONTRACT check only -- required claim keys present --
        NOT cryptographic signature or trust-chain validation. A True
        return here must never be treated as "this assertion is
        authentic." Real SAML assertion validation (XML signature,
        issuer trust, replay/expiry) belongs in a real IdP adapter;
        authenticate() below correctly refuses to mint a
        TenantPrincipal until one is bound, specifically so this
        weaker check can't be mistaken for that.
        """
        if not self.config.enabled:
            return False

        required = {
            "subject",
            "issuer",
            "audience",
        }

        return required.issubset(
            assertion.keys()
        )
    # --- preserved from SAMLProvider (merged, not present in canonical host) ---
    def authenticate(
        self,
        saml_response: str,
    ) -> TenantPrincipal:
        raise NotImplementedError(
            "Bind SAMLProvider to an actual enterprise IdP adapter."
        )
    # --- preserved from SAMLProvider (merged, not present in canonical host) ---
    def validate_configuration(self) -> bool:
        return bool(
            self.config.enabled
            and self.config.issuer
            and self.config.client_id
        )


# =============================================================================
# SESSION SECURITY
# =============================================================================

@dataclass
class CyberSession:
    session_id: str
    principal_id: str
    tenant_id: str
    issued_at: datetime
    expires_at: datetime
    status: SessionStatus = SessionStatus.ACTIVE
    device_id: Optional[str] = None
    ip_fingerprint: Optional[str] = None

    def is_active(self) -> bool:
        return (
            self.status == SessionStatus.ACTIVE
            and utc_now_v5() < self.expires_at
        )


class SessionManager:
    def __init__(
        self,
        ttl_seconds: int = 3600,
    ) -> None:
        if ttl_seconds <= 0:
            raise ValueError("Session TTL must be positive.")

        self.ttl_seconds = ttl_seconds
        self._sessions: Dict[str, CyberSession] = {}
        self._lock = threading.RLock()

    def create(
        self,
        principal: Optional[TenantPrincipal] = None,
        device_id: Optional[str] = None,
        *,
        actor_id: Optional[str] = None,
        tenant_id: Optional[str] = None,
        auth_method: Optional["AuthenticationMethod"] = None,
        mfa_verified: Optional[bool] = None,
    ) -> CyberSession:
        # NOTE(auto-repair): callers (e.g. Phase 21's self-test) also
        # create sessions from plain actor_id/tenant_id kwargs rather than
        # a full TenantPrincipal object. auth_method/mfa_verified aren't
        # tracked on CyberSession (no field for them); accepted for call
        # compatibility rather than silently rejected.
        if principal is None:
            if actor_id is None or tenant_id is None:
                raise ValueError(
                    "Either principal, or both actor_id and "
                    "tenant_id, are required."
                )
            principal_id = actor_id
            resolved_tenant_id = tenant_id
        else:
            principal_id = principal.principal_id
            resolved_tenant_id = principal.tenant_id

        now = utc_now_v5()

        session = CyberSession(
            # [auto-repair] was secure_id("sess") (a UUID4-based ID --
            # 122 usable random bits, still generated via os.urandom
            # under the hood so not practically brute-forceable, but
            # not the purpose-built token generator either). Session
            # identifiers are exactly the case secrets.token_urlsafe
            # exists for -- 256 bits, no version/variant bits
            # consumed, and it signals "this is a bearer credential"
            # rather than "this is an object identifier" the way a
            # UUID does elsewhere in this file.
            session_id=f"sess_{secrets.token_urlsafe(32)}",
            principal_id=principal_id,
            tenant_id=resolved_tenant_id,
            issued_at=now,
            expires_at=now + timedelta(
                seconds=self.ttl_seconds
            ),
            device_id=device_id,
        )

        with self._lock:
            self._sessions[session.session_id] = session

        return session

    def require_active(
        self,
        session_id: str,
        principal: TenantPrincipal,
    ) -> CyberSession:
        with self._lock:
            session = self._sessions.get(session_id)

            if session is None:
                raise SessionError("Unknown session.")

            if session.tenant_id != principal.tenant_id:
                raise TenantIsolationError(
                    "Session tenant mismatch."
                )

            if session.principal_id != principal.principal_id:
                raise SessionError(
                    "Session principal mismatch."
                )

            if not session.is_active():
                session.status = (
                    SessionStatus.EXPIRED
                    if utc_now_v5() >= session.expires_at
                    else SessionStatus.REVOKED
                )
                raise SessionError(
                    "Session is not active."
                )

            return session

    def revoke(
        self,
        session_id: str,
        principal: Optional[TenantPrincipal] = None,
        *,
        actor_id: Optional[str] = None,
        tenant_id: Optional[str] = None,
    ) -> None:
        # [auto-repair] this previously took only session_id -- any
        # caller who knew/guessed a session_id could revoke (force
        # logout) any OTHER tenant's session, no ownership check at
        # all. require_active() right above already does this
        # correctly (tenant_id + principal_id match); bringing this in
        # line with it. Accepts either a TenantPrincipal or raw
        # actor_id/tenant_id kwargs, matching create()'s existing
        # dual-calling-convention above. Fails closed: if no
        # authorization context is given at all, it refuses rather
        # than silently revoking.
        with self._lock:
            session = self._sessions.get(session_id)

            if session is None:
                return

            if principal is not None:
                check_tenant_id = principal.tenant_id
            elif tenant_id is not None:
                check_tenant_id = tenant_id
            else:
                raise ValueError(
                    "revoke() requires a principal, or tenant_id, "
                    "to verify session ownership."
                )

            if session.tenant_id != check_tenant_id:
                raise TenantIsolationError(
                    "Session tenant mismatch."
                )

            session.status = SessionStatus.REVOKED

    def revoke_principal(
        self,
        principal_id: str,
        tenant_id: str,
    ) -> int:
        # [auto-repair] added a required tenant_id. Previously this
        # matched on principal_id alone across every tenant's sessions
        # -- fine if principal_id is guaranteed globally unique, but
        # nothing in this file enforces that, and the rest of the
        # codebase treats (tenant_id, principal_id) as the real identity
        # (see TenantPrincipal). Two different tenants both having a
        # user called "admin" would otherwise let one tenant revoke the
        # other's session. No internal caller currently exists, so
        # this can't have been exercised by the self-tests.
        count = 0

        with self._lock:
            for session in self._sessions.values():
                if (
                    session.principal_id == principal_id
                    and session.tenant_id == tenant_id
                    and session.status == SessionStatus.ACTIVE
                ):
                    session.status = SessionStatus.REVOKED
                    count += 1

        return count
    # --- preserved from SessionManager (merged, not present in canonical host) ---
    def get(
        self,
        session_id: str,
        principal: Optional[TenantPrincipal] = None,
        *,
        tenant_id: Optional[str] = None,
    ) -> CyberSession:
        # [auto-repair] this previously took only session_id and
        # returned any tenant's session to any caller who knew/guessed
        # the id -- same missing-ownership-check issue as revoke()
        # above, fixed the same way (principal or tenant_id required).
        # Also fixed the return type annotation: this dict stores
        # CyberSession objects (see self._sessions above), not
        # SecuritySession -- another sign this method was pasted in
        # from a different, incompatible session design.
        with self._lock:
            session = self._sessions.get(session_id)

            if not session:
                raise PermissionError("Invalid session")

            if principal is not None:
                check_tenant_id = principal.tenant_id
            elif tenant_id is not None:
                check_tenant_id = tenant_id
            else:
                raise ValueError(
                    "get() requires a principal, or tenant_id, "
                    "to verify session ownership."
                )

            if session.tenant_id != check_tenant_id:
                raise PermissionError("Invalid session")

            if session.status != SessionStatus.ACTIVE:
                raise PermissionError("Session is not active")

            if session.expires_at <= utc_now_v5():
                session.status = SessionStatus.EXPIRED
                raise PermissionError("Session expired")

            return session
    # --- preserved from SessionManager (merged, not present in canonical host) ---
    def revoke_actor(self, actor_id: str) -> None:
        # [auto-repair] was self.sessions, which doesn't exist -- the
        # real attribute set in __init__ is self._sessions.
        with self._lock:
            for session in self._sessions.values():
                if session.actor_id == actor_id:
                    session.status = SessionStatus.REVOKED


