# AGENT SECURITY
# =============================================================================

@dataclass(frozen=True)
class AgentIdentity:
    agent_id: Any
    tenant_id: Any
    name: str = ""
    capabilities: frozenset[str] = frozenset()
    allowed_action_types: frozenset[str] = frozenset()
    max_risk_level: RiskLevel = RiskLevel.LOW
    enabled: bool = True
    agent_type: Any = None
    version: str = "1.0.0"
    status: Any = "active"
    # NOTE(auto-repair): AgentPermissionManager.authorize() (a separate,
    # simpler permission-check system) needs these two on whatever it's
    # given as an "AgentIdentity" -- neither was a real field before.
    permissions: "frozenset[str]" = frozenset()
    max_action_level: "ActionLevel" = None
    # [auto-repair] added created_at + a __post_init__ placeholder below.
    # This file's compatibility-patch section does
    # `AgentIdentity.__post_init__ = _agent_identity_post_init`, and that
    # patched version reads self.created_at -- but (a) created_at wasn't
    # a field at all, and (b) dataclass only wires up a __post_init__
    # call in the generated __init__ if __post_init__ already existed
    # on the class *at @dataclass-decoration time*. Since the original
    # class body had none, the patch was silently never being invoked --
    # AgentIdentity() was skipping validation entirely, not crashing.
    # This restores it for real.
    created_at: Optional[datetime] = None

    def __post_init__(self) -> None:
        pass

    def validate(self) -> None:
        require_nonempty(self.name, "name")
        require_nonempty(self.version, "version")
        if "UUID" in globals() and not isinstance(self.agent_id, UUID):
            raise TypeError("agent_id must be UUID.")
        if self.agent_type is not None and "AgentType" in globals() and not isinstance(self.agent_type, AgentType):
            raise TypeError("agent_type must be AgentType.")
        if "UUID" in globals() and not isinstance(self.tenant_id, UUID):
            raise TypeError("tenant_id must be UUID.")
        if "AgentStatus" in globals() and not isinstance(self.status, AgentStatus):
            object.__setattr__(self, "status", AgentStatus(str(self.status).strip().lower()))


class AgentAuthorization:
    """
    Explicit least-privilege boundary for Cyber agents.
    """

    RISK_ORDER = {
        RiskLevel.READ_ONLY: 0,
        RiskLevel.LOW: 1,
        RiskLevel.MEDIUM: 2,
        RiskLevel.HIGH: 3,
        RiskLevel.CRITICAL: 4,
    }

    def authorize(
        self,
        agent: AgentIdentity,
        tenant_id: str,
        action_type: str,
        requested_risk: RiskLevel,
    ) -> None:
        if not agent.enabled:
            raise AuthorizationError(
                "Agent is disabled."
            )

        if agent.tenant_id != tenant_id:
            raise TenantIsolationError(
                "Agent tenant mismatch."
            )

        if action_type not in agent.allowed_action_types:
            raise AuthorizationError(
                "Agent lacks action capability."
            )

        if (
            self.RISK_ORDER[requested_risk]
            > self.RISK_ORDER[agent.max_risk_level]
        ):
            raise AuthorizationError(
                "Requested risk exceeds agent risk limit."
            )


