@dataclass(frozen=True)
class ActionRiskProfile:
    action_type: str = ""
    risk_level: RiskLevel = RiskLevel.LOW
    requires_approval: bool = False
    requires_mfa: bool = False
    emergency_break_glass_allowed: bool = False
    security_benefit: float | None = None
    operational_risk: float | None = None
    collateral_risk: float | None = None
    availability_impact: float | None = None
    threat_reduction: float | None = None


class ActionRiskRegistry:
    def __init__(self) -> None:
        self._profiles: Dict[str, ActionRiskProfile] = {}

    def register(
        self,
        profile: ActionRiskProfile,
    ) -> None:
        self._profiles[profile.action_type] = profile

    def get(
        self,
        action_type: str,
    ) -> ActionRiskProfile:
        try:
            return self._profiles[action_type]
        except KeyError:
            raise AuthorizationError(
                f"No risk profile registered for action: "
                f"{action_type}"
            )


