# APPROVALS
# =============================================================================

@dataclass
class ApprovalRequest:
    approval_id: str
    tenant_id: str
    requested_by: str
    action_type: str
    risk_level: RiskLevel
    target: str
    required_approvals: int
    created_at: datetime
    approvals: Set[str] = field(default_factory=set)
    rejected_by: Optional[str] = None
    action_id: Optional[UUID] = None

    @property
    def approved(self) -> bool:
        return (
            self.rejected_by is None
            and len(self.approvals)
            >= self.required_approvals
        )
# [auto-repair] removed validate() -- merge artifact referencing
    # self.expires_at, which isn't a field on this dataclass (it has
    # approval_id, tenant_id, requested_by, action_type, risk_level,
    # target, required_approvals, created_at, approvals, rejected_by,
    # action_id). Nothing calls it, so it was dead/unreachable, not a
    # currently-active bug -- but would have raised AttributeError the
    # moment anything did call it.


class ApprovalManager:
    def __init__(self) -> None:
        self._requests: Dict[str, ApprovalRequest] = {}
        self._lock = threading.RLock()

    def create(
        self,
        tenant_id: str,
        requested_by: str,
        action_type: str,
        risk_level: RiskLevel,
        target: str,
        required_approvals: int = 1,
    ) -> ApprovalRequest:
        if required_approvals < 1:
            raise ValidationError(
                "At least one approval is required."
            )

        request = ApprovalRequest(
            approval_id=secure_id("approval"),
            tenant_id=tenant_id,
            requested_by=requested_by,
            action_type=action_type,
            risk_level=risk_level,
            target=target,
            required_approvals=required_approvals,
            created_at=utc_now_v5(),
        )

        with self._lock:
            self._requests[request.approval_id] = request

        return request

    def approve(
        self,
        approval_id: str,
        principal: TenantPrincipal,
    ) -> ApprovalRequest:
        with self._lock:
            request = self._requests.get(approval_id)

            if request is None:
                raise ValidationError(
                    "Unknown approval request."
                )

            if request.tenant_id != principal.tenant_id:
                raise TenantIsolationError(
                    "Approval tenant mismatch."
                )

            if request.requested_by == principal.principal_id:
                raise AuthorizationError(
                    "Requester cannot self-approve."
                )

            if request.rejected_by:
                raise PolicyDeniedError(
                    "Approval request was rejected."
                )

            request.approvals.add(
                principal.principal_id
            )

            return request

    def reject(
        self,
        approval_id: str,
        principal: TenantPrincipal,
    ) -> ApprovalRequest:
        with self._lock:
            request = self._requests.get(approval_id)

            if request is None:
                raise ValidationError(
                    "Unknown approval request."
                )

            if request.tenant_id != principal.tenant_id:
                raise TenantIsolationError(
                    "Approval tenant mismatch."
                )

            request.rejected_by = principal.principal_id

            return request

    def get(
        self,
        approval_id: str,
        principal: TenantPrincipal,
    ) -> ApprovalRequest:
        # [auto-repair] this previously took no principal and returned
        # any tenant's approval request to any caller who knew/guessed
        # the approval_id -- no tenant check at all, unlike approve()
        # and reject() right above, which both correctly enforce
        # `request.tenant_id != principal.tenant_id`. IDs here are
        # random UUIDs (secure_id()), so this wasn't trivially guessable,
        # but "the ID is hard to guess" isn't an authorization check --
        # bringing this in line with its siblings.
        with self._lock:
            request = self._requests.get(approval_id)

            if request is None:
                raise ValidationError(
                    "Unknown approval request."
                )

            if request.tenant_id != principal.tenant_id:
                raise TenantIsolationError(
                    "Approval tenant mismatch."
                )

            return request
    # [auto-repair] removed expire_if_needed()/revoke() -- merge
    # artifacts from a different, repository-backed ApprovalManager
    # design (self.repository, ApprovalRecord, approval.transition(),
    # ApprovalStatus.REVOKED). This ApprovalManager is dict-based
    # (self._requests) and its ApprovalRequest objects have no
    # .transition()/.is_expired() methods, so these would have raised
    # AttributeError immediately on call. If tenant-scoped expiry/revoke
    # is wanted here, it needs building against the real self._requests
    # store, not this pasted-in repository pattern -- happy to do that
    # as a real feature if useful.


