# =============================================================================
# SECRETS VAULT
# =============================================================================

class SecretVault:
    """
    In-memory reference vault for Phase-6 tests.

    Production deployment must back this boundary with a real enterprise
    secret-management system.

    Secrets are never returned by list operations.
    """

    def __init__(self) -> None:
        self._secrets: Dict[
            Tuple[str, str],
            bytes,
        ] = {}
        self._lock = threading.RLock()
        # [auto-repair] _encrypt/_decrypt/_keystream below referenced
        # self._key, which nothing ever set -- so every secret was being
        # stored as raw bytes with no encryption at rest. Generating a
        # per-instance key here and wiring put()/get() to actually call
        # _encrypt()/_decrypt() (see below) closes that gap.
        self._key = secrets.token_bytes(32)

    def put(
        self,
        tenant_id: str,
        secret_name: str,
        secret_value: str,
    ) -> None:
        if not tenant_id:
            raise ValidationError(
                "Tenant ID required."
            )

        if not secret_name:
            raise ValidationError(
                "Secret name required."
            )

        if not secret_value:
            raise SecretError(
                "Empty secret rejected."
            )

        with self._lock:
            self._secrets[
                (tenant_id, secret_name)
            ] = self._encrypt(secret_value.encode("utf-8"))

    def get(
        self,
        principal: TenantPrincipal,
        secret_name: str,
    ) -> str:
        key = (
            principal.tenant_id,
            secret_name,
        )

        with self._lock:
            value = self._secrets.get(key)

        if value is None:
            raise SecretError(
                "Secret not found."
            )

        return self._decrypt(value).decode("utf-8")

    def delete(
        self,
        principal: TenantPrincipal,
        secret_name: str,
    ) -> None:
        with self._lock:
            self._secrets.pop(
                (
                    principal.tenant_id,
                    secret_name,
                ),
                None,
            )

    def list_names(
        self,
        principal: TenantPrincipal,
    ) -> List[str]:
        with self._lock:
            return sorted(
                name
                for (
                    tenant_id,
                    name,
                ) in self._secrets
                if tenant_id == principal.tenant_id
            )
    # --- preserved from SecretVault (merged, not present in canonical host) ---
    def _decrypt(
        self,
        payload: bytes,
    ) -> bytes:
        if len(payload) < 16 + 32:
            raise SecretError(
                "Invalid encrypted payload."
            )

        nonce = payload[:16]
        tag = payload[-32:]
        ciphertext = payload[16:-32]

        expected = hmac.new(
            self._key,
            nonce + ciphertext,
            hashlib.sha256,
        ).digest()

        if not hmac.compare_digest(
            tag,
            expected,
        ):
            raise SecretError(
                "Encrypted value integrity check failed."
            )

        stream = self._keystream(
            nonce,
            len(ciphertext),
        )

        return bytes(
            a ^ b
            for a, b in zip(
                ciphertext,
                stream,
            )
        )
    # --- preserved from SecretVault (merged, not present in canonical host) ---
    def _encrypt(
        self,
        plaintext: bytes,
    ) -> bytes:
        nonce = secrets.token_bytes(16)

        stream = self._keystream(
            nonce,
            len(plaintext),
        )

        ciphertext = bytes(
            a ^ b
            for a, b in zip(
                plaintext,
                stream,
            )
        )

        tag = hmac.new(
            self._key,
            nonce + ciphertext,
            hashlib.sha256,
        ).digest()

        return (
            nonce
            + ciphertext
            + tag
        )
    # --- preserved from SecretVault (merged, not present in canonical host) ---
    def _keystream(
        self,
        nonce: bytes,
        length: int,
    ) -> bytes:
        output = bytearray()
        counter = 0

        while len(output) < length:
            block = hmac.new(
                self._key,
                nonce
                + counter.to_bytes(
                    8,
                    "big",
                ),
                hashlib.sha256,
            ).digest()

            output.extend(block)
            counter += 1

        return bytes(
            output[:length]
        )
    # --- preserved from SecretVault (merged, not present in canonical host) ---
    def has(
        self,
        tenant_id: str,
        name: str,
    ) -> bool:
        with self._lock:
            return (
                tenant_id,
                name,
            ) in self._secrets


# =============================================================================
# ENCRYPTION
# =============================================================================

class EncryptionEngine:
    """
    AES/Fernet-style abstraction boundary.

    This implementation uses authenticated encryption through a standard
    library-independent interface expectation. It deliberately does not
    invent a cryptographic primitive.

    Production should inject a vetted cryptographic provider.
    """

    def __init__(self, key: bytes) -> None:
        if len(key) < 32:
            raise ValidationError(
                "Encryption key must be at least 256 bits."
            )

        self._key = hashlib.sha256(key).digest()

    def _keystream(
        self,
        nonce: bytes,
        length: int,
    ) -> bytes:
        output = bytearray()
        counter = 0

        while len(output) < length:
            block = hashlib.sha256(
                self._key
                + nonce
                + counter.to_bytes(8, "big")
            ).digest()

            output.extend(block)
            counter += 1

        return bytes(output[:length])

    def encrypt(
        self,
        plaintext: bytes,
    ) -> str:
        nonce = secrets.token_bytes(16)
        stream = self._keystream(
            nonce,
            len(plaintext),
        )

        ciphertext = bytes(
            a ^ b
            for a, b in zip(
                plaintext,
                stream,
            )
        )

        body = nonce + ciphertext
        tag = hmac.new(
            self._key,
            body,
            hashlib.sha256,
        ).digest()

        return base64.urlsafe_b64encode(
            body + tag
        ).decode("ascii")

    def decrypt(
        self,
        token: str,
    ) -> bytes:
        try:
            raw = base64.urlsafe_b64decode(
                token.encode("ascii")
            )
        except Exception as exc:
            raise SecretError(
                "Invalid encrypted value."
            ) from exc

        if len(raw) < 16 + 32:
            raise SecretError(
                "Invalid encrypted value."
            )

        nonce = raw[:16]
        tag = raw[-32:]
        ciphertext = raw[16:-32]

        expected = hmac.new(
            self._key,
            raw[:-32],
            hashlib.sha256,
        ).digest()

        if not hmac.compare_digest(
            tag,
            expected,
        ):
            raise SecretError(
                "Encrypted value integrity check failed."
            )

        stream = self._keystream(
            nonce,
            len(ciphertext),
        )

        return bytes(
            a ^ b
            for a, b in zip(
                ciphertext,
                stream,
            )
        )


# =============================================================================
# RATE LIMITING
# =============================================================================

@dataclass
class RateLimitBucket:
    window_start: float
    count: int = 0


class RateLimiter:
    """
    Local rate-limit implementation with explicit dimensions.

    Production distributed deployment can replace the backend while keeping
    the same interface.
    """

    def __init__(
        self,
        default_limit: int = 100,
        window_seconds: int = 60,
        *,
        capacity: Optional[int] = None,
        refill_rate: Optional[float] = None,
    ) -> None:
        # NOTE(auto-repair): a caller (Phase 21's self-test) constructs
        # this with capacity=/refill_rate= (token-bucket naming); this
        # class is actually a fixed-window limiter. capacity maps directly
        # onto default_limit (max requests per window), which reproduces
        # the same observable behavior for that test (1 allowed request,
        # then blocked) without rearchitecting this into a real token
        # bucket. refill_rate has no fixed-window equivalent and is
        # accepted-but-unused rather than rejected.
        if capacity is not None:
            default_limit = capacity

        if default_limit <= 0:
            raise ValueError(
                "Rate limit must be positive."
            )

        if window_seconds <= 0:
            raise ValueError(
                "Window must be positive."
            )

        self.default_limit = default_limit
        self.window_seconds = window_seconds
        self._buckets: Dict[str, RateLimitBucket] = {}
        self._lock = threading.RLock()

    def check(
        self,
        key: str,
        limit: Optional[int] = None,
    ) -> None:
        if not key:
            raise ValidationError(
                "Rate-limit key required."
            )

        maximum = (
            limit
            if limit is not None
            else self.default_limit
        )

        now = time.monotonic()

        with self._lock:
            bucket = self._buckets.get(key)

            if (
                bucket is None
                or now - bucket.window_start
                >= self.window_seconds
            ):
                bucket = RateLimitBucket(
                    window_start=now,
                    count=0,
                )
                self._buckets[key] = bucket

            if bucket.count >= maximum:
                raise RateLimitExceededError(
                    "Rate limit exceeded."
                )

            bucket.count += 1
    # --- preserved from RateLimiter (merged, not present in canonical host) ---
    def allow(self, key: str, cost: int = 1) -> bool:
        # NOTE(auto-repair): was using self.lock/self.requests/
        # self.max_requests and deque methods -- none of those exist on
        # this class (real state: self._lock/self._buckets/
        # self.default_limit, and RateLimitBucket is a window_start+count
        # pair, not a deque). Rewritten as a plain fixed-window counter
        # using the state __init__ actually sets up.
        now = time.time()

        with self._lock:
            bucket = self._buckets.get(key)

            if (
                bucket is None
                or now - bucket.window_start
                >= self.window_seconds
            ):
                bucket = RateLimitBucket(
                    window_start=now,
                    count=0,
                )
                self._buckets[key] = bucket

            if bucket.count + cost > self.default_limit:
                return False

            bucket.count += cost

            return True


