@dataclass(frozen=True)
class PolicyRule:
    rule_id: str
    effect: PolicyEffect
    priority: int
    resource: str = "*"
    operation: str = "*"
    actor_types: frozenset[ActorType] = frozenset()
    tenant_ids: frozenset[str] = frozenset()
    required_risk_at_most: Optional[RiskLevel] = None
    reason: str = ""

    def matches(
        self,
        principal: TenantPrincipal,
        resource: str,
        operation: str,
        risk_level: RiskLevel,
    ) -> bool:
        if self.resource not in ("*", resource):
            return False

        if self.operation not in ("*", operation):
            return False

        if (
            self.actor_types
            and principal.actor_type not in self.actor_types
        ):
            return False

        if (
            self.tenant_ids
            and principal.tenant_id not in self.tenant_ids
        ):
            return False

        if self.required_risk_at_most is not None:
            order = {
                RiskLevel.READ_ONLY: 0,
                RiskLevel.LOW: 1,
                RiskLevel.MEDIUM: 2,
                RiskLevel.HIGH: 3,
                RiskLevel.CRITICAL: 4,
            }

            if (
                order[risk_level]
                > order[self.required_risk_at_most]
            ):
                return False

        return True


@dataclass(frozen=True)
class GovernanceDecision:
    decision_id: str
    effect: PolicyEffect
    reason: str
    matched_rule_ids: Tuple[str, ...]
    risk_level: RiskLevel
    approval_required: bool
    emergency_stopped: bool

    # NOTE(auto-repair): a large amount of code elsewhere (~30 call sites)
    # was written treating GovernanceDecision itself as the ALLOW/DENY/
    # REQUIRE_APPROVAL enum -- that enum is PolicyEffect; this class is a
    # richer decision *record* that carries a PolicyEffect in .effect.
    # These ClassVar aliases let bare `GovernanceDecision.ALLOW`-style
    # access resolve correctly without touching every call site; they are
    # not dataclass fields (ClassVar excludes them from __init__).
    ALLOW: ClassVar[PolicyEffect] = PolicyEffect.ALLOW
    DENY: ClassVar[PolicyEffect] = PolicyEffect.DENY
    REQUIRE_APPROVAL: ClassVar[PolicyEffect] = PolicyEffect.REQUIRE_APPROVAL
    EMERGENCY_STOP: ClassVar[PolicyEffect] = PolicyEffect.EMERGENCY_STOP
    COMPLIANCE_BLOCK: ClassVar[PolicyEffect] = PolicyEffect.COMPLIANCE_BLOCK
    # [auto-repair] added. This is a frozen DATACLASS, not an Enum --
    # frozen only blocks instance attribute mutation, so the two
    # module-level `GovernanceDecision.BREAK_GLASS = PolicyEffect.
    # EMERGENCY_STOP` statements elsewhere in this file (search for
    # them) were NOT dead/swallowed-exception code the way the
    # EventType.TELEMETRY_RECEIVED one was -- they genuinely succeeded,
    # setting this as a class attribute at runtime, just scattered
    # across two duplicate module-level patches instead of living here
    # with its five siblings above. Moved here properly; duplicates
    # removed.
    BREAK_GLASS: ClassVar[PolicyEffect] = PolicyEffect.EMERGENCY_STOP




# =============================================================================
# PHASE 6 SECURITY CONTROL PLANE
# =============================================================================

class CyberSecurityControlPlane:
    """
    Canonical Phase-6 orchestration boundary.

    This does NOT execute cyber response actions.
    It decides whether a proposed action is authorized.
    """

    def __init__(self, *, mfa_provider: Optional["MFAProvider"] = None) -> None:
        self.tenant_boundary = TenantBoundary()

        self.rbac = RBACManager()
        self.abac = ABACEngine()

        self.sessions = SessionManager()
        self.emergency_stop = EmergencyStopManager()
        self.break_glass = BreakGlassManager()

        # [auto-repair] this used to hardcode
        # AssertionMFAProvider("PHASE6_TEST_MFA") unconditionally --
        # "PHASE6_TEST_MFA" is a literal, predictable string sitting in
        # the source of what this class's own docstring calls the
        # "Canonical Phase-6 orchestration boundary" that "decides
        # whether a proposed action is authorized". Anyone who could
        # read the source (or just guess it) could pass that exact
        # string as an MFA assertion and pass verification for any
        # principal. Now injectable via mfa_provider=; if nothing is
        # injected, falls back to a provider keyed with a fresh random
        # secret per instance -- still not a real IdP integration (see
        # AssertionMFAProvider's own docstring), but no longer a fixed,
        # guessable bypass string.
        self.mfa = MFAEnforcer(
            mfa_provider
            if mfa_provider is not None
            else AssertionMFAProvider(secrets.token_urlsafe(32))
        )

        self.risk_registry = ActionRiskRegistry()
        self.approvals = ApprovalManager()

        self.vault = SecretVault()
        self.encryption = EncryptionEngine(
            secrets.token_bytes(32)
        )

        self.rate_limiter = RateLimiter()

        self.audit = AuditLedger()

        self.policy = CyberPolicyEngine(
            tenant_boundary=self.tenant_boundary,
            rbac=self.rbac,
            abac=self.abac,
            emergency_stop=self.emergency_stop,
            risk_registry=self.risk_registry,
        )

        self.agent_authorization = AgentAuthorization()

    def authorize_action(
        self,
        request: AuthorizationRequest,
        action_type: str,
        agent: Optional[AgentIdentity] = None,
    ) -> GovernanceDecision:
        self.tenant_boundary.require_authenticated(
            request.principal
        )

        if agent:
            profile = self.risk_registry.get(
                action_type
            )

            self.agent_authorization.authorize(
                agent=agent,
                tenant_id=request.principal.tenant_id,
                action_type=action_type,
                requested_risk=profile.risk_level,
            )

        decision = self.policy.evaluate(
            request=request,
            action_type=action_type,
        )

        self.audit.append(
            tenant_id=request.principal.tenant_id,
            actor_type=request.principal.actor_type,
            actor_id=request.principal.principal_id,
            action=f"authorize:{action_type}",
            target=request.resource,
            category=AuditCategory.AUTHORIZATION,
            result=decision.effect.value,
            policy_decision=decision.effect.value,
            decision_id=decision.decision_id,
        )

        return decision
    # --- preserved from CyberSecurityControlPlane (merged, not present in canonical host) ---
    def _audit_decision(
        self,
        request: AuthorizationRequest,
        action_type: str,
        decision: GovernanceDecision,
    ) -> None:
        self.audit.append(
            tenant_id=(
                request.principal.tenant_id
            ),
            actor_type=(
                request.principal.actor_type
            ),
            actor_id=(
                request.principal.principal_id
            ),
            action=(
                f"authorize:{action_type}"
            ),
            target=request.resource,
            category=(
                AuditCategory.AUTHORIZATION
            ),
            result=(
                decision.effect.value
            ),
            policy_decision=(
                decision.effect.value
            ),
            decision_id=(
                decision.decision_id
            ),
            request_id=request.request_id,
            correlation_id=(
                request.correlation_id
            ),
        )


# =============================================================================
# PHASE 6 DEFAULT SECURITY CONFIGURATION
# =============================================================================

def configure_phase6_defaults(
    control: CyberSecurityControlPlane,
) -> None:
    """
    Safe baseline policy configuration.

    Default posture is deny unless explicitly allowed.
    """

    # -------------------------------------------------------------------------
    # Permissions
    # -------------------------------------------------------------------------

    control.rbac.register_permission(
        Permission(
            permission_id="security.read",
            resource="security",
            operation="read",
        )
    )

    control.rbac.register_permission(
        Permission(
            permission_id="security.approve",
            resource="security",
            operation="approve",
        )
    )

    control.rbac.register_permission(
        Permission(
            permission_id="security.admin",
            resource="security",
            operation="admin",
        )
    )

    # -------------------------------------------------------------------------
    # Roles
    # -------------------------------------------------------------------------

    control.rbac.register_role(
        Role(
            role_id="security_analyst",
            name="Security Analyst",
            permissions={
                "security.read",
            },
        )
    )

    control.rbac.register_role(
        Role(
            role_id="security_approver",
            name="Security Approver",
            permissions={
                "security.read",
                "security.approve",
            },
        )
    )

    control.rbac.register_role(
        Role(
            role_id="security_admin",
            name="Security Administrator",
            permissions={
                "security.read",
                "security.approve",
                "security.admin",
            },
        )
    )

    # -------------------------------------------------------------------------
    # Action profiles
    # -------------------------------------------------------------------------

    control.risk_registry.register(
        ActionRiskProfile(
            action_type="read_security_state",
            risk_level=RiskLevel.READ_ONLY,
        )
    )

    control.risk_registry.register(
        ActionRiskProfile(
            action_type="collect_evidence",
            risk_level=RiskLevel.LOW,
        )
    )

    control.risk_registry.register(
        ActionRiskProfile(
            action_type="create_security_ticket",
            risk_level=RiskLevel.LOW,
        )
    )

    control.risk_registry.register(
        ActionRiskProfile(
            action_type="revoke_session",
            risk_level=RiskLevel.MEDIUM,
            requires_approval=True,
            requires_mfa=True,
        )
    )

    control.risk_registry.register(
        ActionRiskProfile(
            action_type="disable_identity",
            risk_level=RiskLevel.HIGH,
            requires_approval=True,
            requires_mfa=True,
            emergency_break_glass_allowed=True,
        )
    )

    control.risk_registry.register(
        ActionRiskProfile(
            action_type="modify_security_control",
            risk_level=RiskLevel.CRITICAL,
            requires_approval=True,
            requires_mfa=True,
            emergency_break_glass_allowed=True,
        )
    )

    # -------------------------------------------------------------------------
    # ABAC baseline
    # -------------------------------------------------------------------------

    control.abac.add_rule(
        lambda request: (
            request.principal.authenticated
            and bool(request.principal.tenant_id)
        )
    )

    # -------------------------------------------------------------------------
    # Explicit policies
    # -------------------------------------------------------------------------

    control.policy.register_rule(
        PolicyRule(
            rule_id="allow_authenticated_read",
            effect=PolicyEffect.ALLOW,
            priority=100,
            resource="security",
            operation="read",
            reason="Authenticated security read.",
        )
    )

    control.policy.register_rule(
        PolicyRule(
            rule_id="allow_ticket_creation",
            effect=PolicyEffect.ALLOW,
            priority=100,
            resource="security",
            operation="create_ticket",
            reason="Low-risk security ticket creation.",
        )
    )

    control.policy.register_rule(
        PolicyRule(
            rule_id="require_approval_for_high_risk",
            effect=PolicyEffect.REQUIRE_APPROVAL,
            priority=200,
            resource="security",
            operation="high_risk_action",
            reason="High-risk action requires approval.",
        )
    )


# =============================================================================
# PHASE 6 TEST SUITE
# =============================================================================

class Phase6Tests:

    @staticmethod
    def _assert(
        condition: bool,
        message: str,
    ) -> None:
        if not condition:
            raise AssertionError(message)

    @classmethod
    def test_tenant_isolation(cls) -> None:
        control = CyberSecurityControlPlane()

        principal = TenantPrincipal(
            principal_id="user-a",
            actor_type=ActorType.USER,
            tenant_id="tenant-a",
            # [auto-repair] TenantPrincipal.authenticated now defaults
            # to False (was True -- see its class definition). This
            # test isn't testing authentication itself, so it needs an
            # authenticated principal explicitly.
            authenticated=True,
        )

        control.tenant_boundary.assert_same_tenant(
            principal,
            "tenant-a",
        )

        denied = False

        try:
            control.tenant_boundary.assert_same_tenant(
                principal,
                "tenant-b",
            )
        except TenantIsolationError:
            denied = True

        cls._assert(
            denied,
            "Cross-tenant access was not denied.",
        )

    @classmethod
    def test_rbac(cls) -> None:
        control = CyberSecurityControlPlane()
        configure_phase6_defaults(control)

        control.rbac.assign_role(
            "user-1",
            "security_analyst",
            tenant_id="tenant-1",
        )

        cls._assert(
            control.rbac.has_permission(
                "user-1",
                "security",
                "read",
                tenant_id="tenant-1",
            ),
            "RBAC read permission failed.",
        )

        cls._assert(
            not control.rbac.has_permission(
                "user-1",
                "security",
                "admin",
                tenant_id="tenant-1",
            ),
            "RBAC privilege escalation occurred.",
        )

        # [auto-repair] added: this test previously had no coverage at
        # all for the tenant-isolation fix in RBACManager (see its
        # class definition) -- a role assigned to "user-1" in one
        # tenant must not silently apply to a different tenant's
        # "user-1".
        cls._assert(
            not control.rbac.has_permission(
                "user-1",
                "security",
                "read",
                tenant_id="tenant-2",
            ),
            "RBAC role leaked across tenants.",
        )

