# =============================================================================
# PHASE 6 VERIFICATION
# =============================================================================

def verify_phase6() -> Dict[str, Any]:
    results = Phase6Tests.run_all()

    passed = [
        name
        for name, result in results.items()
        if result == "PASS"
    ]

    failed = [
        name
        for name, result in results.items()
        if result != "PASS"
    ]

    return {
        "phase": "PHASE_6",
        "scope": "GOVERNANCE_SECURITY_ENTERPRISE_CONTROL",
        "tests_total": len(results),
        "tests_passed": len(passed),
        "tests_failed": len(failed),
        "results": results,
        "status": (
            "VERIFIED"
            if not failed
            else "FAILED"
        ),
    }


