@dataclass(frozen=True)
class RiskFactor:
    name: str
    value: float
    weight: float
    source: str
    evidence_ids: Tuple[str, ...] = ()

    @property
    def contribution(self) -> float:
        return max(0.0, min(100.0, self.value)) * max(0.0, self.weight)


@dataclass
class AssetRiskContext:
    asset_id: str
    criticality: float = 0.0
    exposure: float = 0.0
    exploitability: float = 0.0
    threat_activity: float = 0.0
    business_impact: float = 0.0
    historical_risk: float = 0.0
    identity_privilege: float = 0.0
    attack_path_risk: float = 0.0


@dataclass
class VulnerabilityContext:
    vulnerability_id: str
    cvss: float = 0.0
    exploitable: bool = False
    internet_exposed: bool = False
    exploit_available: bool = False
    active_threat_activity: float = 0.0
    affected_asset_criticality: float = 0.0
    compensating_controls: float = 0.0
    evidence_ids: Tuple[str, ...] = ()

    def exploitability_score(self) -> float:
        score = self.cvss * 10.0

        if self.exploitable:
            score += 12.0

        if self.internet_exposed:
            score += 12.0

        if self.exploit_available:
            score += 15.0

        score += self.active_threat_activity * 0.20
        score -= self.compensating_controls * 0.20

        return max(0.0, min(100.0, score))


@dataclass(frozen=True)
class GraphNode:
    node_id: str
    node_type: NodeType
    criticality: float = 0.0
    privilege: float = 0.0
    exposure: float = 0.0
    metadata: Dict[str, str] = field(default_factory=dict)


@dataclass(frozen=True)
class GraphEdge:
    source: str
    target: str
    edge_type: EdgeType
    confidence: float = 1.0
    exploitability: float = 0.0
    risk_weight: float = 1.0
    evidence_ids: Tuple[str, ...] = ()


@dataclass
class AttackPath:
    path_id: str
    nodes: List[str]
    edges: List[GraphEdge]
    exploitability: float
    impact: float
    risk_score: float
    evidence_ids: List[str]


@dataclass
class RiskAssessment:
    subject_id: str
    score: float
    level: RiskLevel
    factors: List[RiskFactor]
    attack_path_ids: List[str]
    evidence_ids: List[str]
    explanation: str
    calculated_at: float


# ============================================================
# GRAPH
# ============================================================

class CyberAttackGraph:
    """
    In-memory attack graph for Phase 7.

    Storage backend is intentionally abstracted.
    Phase 7 owns graph semantics, not enterprise persistence.
    """

    def __init__(self) -> None:
        self._nodes: Dict[str, GraphNode] = {}
        self._edges: List[GraphEdge] = []  # [BUGFIX] was `{}` (dict), but .append() below needs a list
        self._adjacency: Dict[str, List[GraphEdge]] = {}

    def add_node(self, node: GraphNode) -> None:
        self._nodes[node.node_id] = node
        self._adjacency.setdefault(node.node_id, [])

    def add_edge(self, edge: GraphEdge) -> None:
        if edge.source not in self._nodes:
            raise ValueError(f"Unknown source node: {edge.source}")

        if edge.target not in self._nodes:
            raise ValueError(f"Unknown target node: {edge.target}")

        confidence = max(0.0, min(1.0, edge.confidence))

        normalized = GraphEdge(
            source=edge.source,
            target=edge.target,
            edge_type=edge.edge_type,
            confidence=confidence,
            exploitability=max(0.0, min(100.0, edge.exploitability)),
            risk_weight=max(0.0, edge.risk_weight),
            evidence_ids=edge.evidence_ids,
        )

        self._edges.append(normalized)
        self._adjacency.setdefault(normalized.source, []).append(normalized)

    def node(self, node_id: str) -> GraphNode:
        return self._nodes[node_id]

    def neighbors(self, node_id: str) -> Sequence[GraphEdge]:
        return tuple(self._adjacency.get(node_id, ()))

    def nodes(self) -> Sequence[GraphNode]:
        return tuple(self._nodes.values())

    def edges(self) -> Sequence[GraphEdge]:
        return tuple(self._edges)
    # --- preserved from CyberAttackGraph (merged, not present in canonical host) ---
    def edge_count(self) -> int:
        return len(self._edges)
    # --- preserved from CyberAttackGraph (merged, not present in canonical host) ---
    def has_node(self, node_id: str) -> bool:
        return node_id in self._nodes
    # --- preserved from CyberAttackGraph (merged, not present in canonical host) ---
    def node_count(self) -> int:
        return len(self._nodes)


# ============================================================
# ASSET CRITICALITY
# ============================================================

class AssetCriticalityEngine:

    def calculate(
        self,
        *,
        business_value: float,
        data_sensitivity: float,
        operational_dependency: float,
        regulatory_impact: float,
        recovery_difficulty: float,
    ) -> float:

        values = [
            business_value,
            data_sensitivity,
            operational_dependency,
            regulatory_impact,
            recovery_difficulty,
        ]

        normalized = [
            max(0.0, min(100.0, value))
            for value in values
        ]

        weights = [
            0.30,
            0.25,
            0.20,
            0.15,
            0.10,
        ]

        return round(
            sum(value * weight for value, weight in zip(normalized, weights)),
            4,
        )


# ============================================================
# VULNERABILITY CONTEXT
# ============================================================

class VulnerabilityContextEngine:

    def assess(
        self,
        vulnerability: VulnerabilityContext,
    ) -> float:
        return vulnerability.exploitability_score()


# ============================================================
# ATTACK PATH DISCOVERY
# ============================================================

class AttackPathEngine:

    def __init__(self, graph: CyberAttackGraph) -> None:
        self.graph = graph

    def discover_paths(
        self,
        source_ids: Iterable[str],
        target_ids: Iterable[str],
        *,
        max_depth: int = 8,
        max_paths: int = 100,
    ) -> List[AttackPath]:

        sources = set(source_ids)
        targets = set(target_ids)

        results: List[AttackPath] = []
        seen_signatures: Set[Tuple[str, ...]] = set()

        for source in sources:
            self._dfs(
                current=source,
                targets=targets,
                path_nodes=[source],
                path_edges=[],
                visited={source},
                depth=0,
                max_depth=max_depth,
                max_paths=max_paths,
                results=results,
                seen_signatures=seen_signatures,
            )

            if len(results) >= max_paths:
                break

        return sorted(
            results,
            key=lambda path: path.risk_score,
            reverse=True,
        )[:max_paths]

    def _dfs(
        self,
        *,
        current: str,
        targets: Set[str],
        path_nodes: List[str],
        path_edges: List[GraphEdge],
        visited: Set[str],
        depth: int,
        max_depth: int,
        max_paths: int,
        results: List[AttackPath],
        seen_signatures: Set[Tuple[str, ...]],
    ) -> None:

        if len(results) >= max_paths:
            return

        if depth > max_depth:
            return

        if current in targets and len(path_nodes) > 1:
            signature = tuple(path_nodes)

            if signature in seen_signatures:
                return

            seen_signatures.add(signature)

            exploitability = self._path_exploitability(path_edges)
            impact = self._path_impact(path_nodes)
            risk = self._path_risk(
                exploitability,
                impact,
                path_edges,
            )

            evidence = sorted({
                evidence_id
                for edge in path_edges
                for evidence_id in edge.evidence_ids
            })

            path_id = self._path_id(path_nodes)

            results.append(
                AttackPath(
                    path_id=path_id,
                    nodes=list(path_nodes),
                    edges=list(path_edges),
                    exploitability=exploitability,
                    impact=impact,
                    risk_score=risk,
                    evidence_ids=evidence,
                )
            )

            return

        for edge in self.graph.neighbors(current):
            if edge.target in visited:
                continue

            self._dfs(
                current=edge.target,
                targets=targets,
                path_nodes=path_nodes + [edge.target],
                path_edges=path_edges + [edge],
                visited=visited | {edge.target},
                depth=depth + 1,
                max_depth=max_depth,
                max_paths=max_paths,
                results=results,
                seen_signatures=seen_signatures,
            )

    def _path_exploitability(
        self,
        edges: Sequence[GraphEdge],
    ) -> float:

        if not edges:
            return 0.0

        probability = 1.0

        for edge in edges:
            exploitability = max(
                0.0,
                min(100.0, edge.exploitability),
            ) / 100.0

            probability *= exploitability * edge.confidence

        return round(probability * 100.0, 4)

    def _path_impact(
        self,
        nodes: Sequence[str],
    ) -> float:

        criticalities = [
            self.graph.node(node_id).criticality
            for node_id in nodes
        ]

        privileges = [
            self.graph.node(node_id).privilege
            for node_id in nodes
        ]

        if not criticalities:
            return 0.0

        target_criticality = max(criticalities)
        privilege_amplifier = max(privileges) * 0.25

        return round(
            min(100.0, target_criticality + privilege_amplifier),
            4,
        )

    def _path_risk(
        self,
        exploitability: float,
        impact: float,
        edges: Sequence[GraphEdge],
    ) -> float:

        confidence = 1.0

        if edges:
            confidence = math.prod(
                max(0.0, min(1.0, edge.confidence))
                for edge in edges
            )

        return round(
            min(
                100.0,
                exploitability * 0.55
                + impact * 0.45,
            ) * confidence,
            4,
        )

    @staticmethod
    def _path_id(nodes: Sequence[str]) -> str:
        raw = "->".join(nodes).encode("utf-8")
        return hashlib.sha256(raw).hexdigest()[:24]
    # --- preserved from AttackPathEngine (merged, not present in canonical host) ---
    @staticmethod
    def _normalize_node_ids(
        values: Iterable[str],
        *,
        name: str,
    ) -> Set[str]:

        if values is None:
            raise ValidationError(
                f"{name} cannot be None."
            )

        normalized: Set[str] = set()

        for value in values:
            if not isinstance(value, str):
                raise ValidationError(
                    f"{name} must contain strings."
                )

            value = value.strip()

            if value:
                normalized.add(value)

        return normalized


# ============================================================
# RISK PROPAGATION
# ============================================================

class RiskPropagationEngine:

    def propagate(
        self,
        graph: CyberAttackGraph,
        seed_risks: Dict[str, float],
        *,
        iterations: int = 5,
        damping: float = 0.70,
    ) -> Dict[str, float]:

        risks = {
            node_id: max(0.0, min(100.0, value))
            for node_id, value in seed_risks.items()
        }

        for node in graph.nodes():
            risks.setdefault(node.node_id, 0.0)

        for _ in range(iterations):
            next_risks = dict(risks)

            for edge in graph.edges():
                source_risk = risks.get(edge.source, 0.0)

                transfer = (
                    source_risk
                    * max(0.0, min(1.0, edge.confidence))
                    * max(0.0, min(1.0, edge.risk_weight))
                    * damping
                )

                next_risks[edge.target] = max(
                    next_risks.get(edge.target, 0.0),
                    min(100.0, transfer),
                )

            risks = next_risks

        return {
            node_id: round(score, 4)
            for node_id, score in risks.items()
        }


# ============================================================
# RISK LEVEL
# ============================================================

class RiskClassifier:

    @staticmethod
    def classify(score: float) -> RiskLevel:
        score = max(0.0, min(100.0, score))

        if score >= 90:
            return RiskLevel.CRITICAL

        if score >= 70:
            return RiskLevel.HIGH

        if score >= 40:
            return RiskLevel.MEDIUM

        if score > 0:
            return RiskLevel.LOW

        return RiskLevel.NONE


# ============================================================
# CONTEXTUAL RISK ENGINE
# ============================================================

class CyberRiskEngine:

    WEIGHTS = {
        "threat": 0.12,
        "exposure": 0.12,
        "exploitability": 0.14,
        "asset_criticality": 0.14,
        "identity_privilege": 0.08,
        "attack_path": 0.14,
        "threat_activity": 0.08,
        "business_impact": 0.10,
        "historical_evidence": 0.08,
    }

    def calculate(
        self,
        context: AssetRiskContext,
        *,
        evidence_ids: Sequence[str] = (),
        attack_path_ids: Sequence[str] = (),
    ) -> RiskAssessment:

        values = {
            "threat": context.threat_activity,
            "exposure": context.exposure,
            "exploitability": context.exploitability,
            "asset_criticality": context.criticality,
            "identity_privilege": context.identity_privilege,
            "attack_path": context.attack_path_risk,
            "threat_activity": context.threat_activity,
            "business_impact": context.business_impact,
            "historical_evidence": context.historical_risk,
        }

        factors = [
            RiskFactor(
                name=name,
                value=max(0.0, min(100.0, value)),
                weight=self.WEIGHTS[name],
                source="phase7_contextual_risk",
                evidence_ids=tuple(evidence_ids),
            )
            for name, value in values.items()
        ]

        score = sum(
            factor.contribution
            for factor in factors
        )

        score = round(
            max(0.0, min(100.0, score)),
            4,
        )

        level = RiskClassifier.classify(score)

        explanation = self._explain(
            score=score,
            level=level,
            factors=factors,
        )

        return RiskAssessment(
            subject_id=context.asset_id,
            score=score,
            level=level,
            factors=factors,
            attack_path_ids=list(attack_path_ids),
            evidence_ids=list(evidence_ids),
            explanation=explanation,
            calculated_at=time.time(),
        )

    @staticmethod
    def _explain(
        *,
        score: float,
        level: RiskLevel,
        factors: Sequence[RiskFactor],
    ) -> str:

        dominant = sorted(
            factors,
            key=lambda factor: factor.contribution,
            reverse=True,
        )[:3]

        drivers = ", ".join(
            f"{factor.name}={factor.value:.1f}"
            for factor in dominant
        )

        return (
            f"Risk score {score:.2f}/100 ({level.value}). "
            f"Primary drivers: {drivers}."
        )
    # --- preserved from CyberRiskEngine (merged, not present in canonical host) ---
    @staticmethod
    def _clean_ids(
        values: Sequence[str],
    ) -> List[str]:

        if values is None:
            return []

        result = []

        for value in values:
            if not isinstance(
                value,
                str,
            ):
                raise ValidationError(
                    "Evidence/path identifiers must be strings."
                )

            value = value.strip()

            if value:
                result.append(value)

        return sorted(set(result))


# ============================================================
# RISK AGGREGATOR
# ============================================================

class RiskAggregationEngine:

    def organizational_posture(
        self,
        assessments: Sequence[RiskAssessment],
    ) -> float:

        if not assessments:
            return 0.0

        weighted = []

        for assessment in assessments:
            weight = 1.0

            for factor in assessment.factors:
                if factor.name == "asset_criticality":
                    weight += factor.value / 100.0

            weighted.append(
                assessment.score * weight
            )

        return round(
            min(
                100.0,
                sum(weighted) / len(weighted),
            ),
            4,
        )

    def aggregate_by_subject(
        self,
        assessments: Sequence[RiskAssessment],
    ) -> Dict[str, float]:

        result: Dict[str, float] = {}

        for assessment in assessments:
            current = result.get(
                assessment.subject_id,
                0.0,
            )

            result[assessment.subject_id] = max(
                current,
                assessment.score,
            )

        return {
            key: round(value, 4)
            for key, value in result.items()
        }


# ============================================================
# PHASE 7 SERVICE
