class Phase7RiskAttackPathService:

    def __init__(self) -> None:
        self.graph = CyberAttackGraph()
        self.criticality = AssetCriticalityEngine()
        self.vulnerability = VulnerabilityContextEngine()
        self.attack_paths = AttackPathEngine(self.graph)
        self.propagation = RiskPropagationEngine()
        self.risk = CyberRiskEngine()
        self.aggregation = RiskAggregationEngine()

    def add_node(self, node: GraphNode) -> None:
        self.graph.add_node(node)

    def add_edge(self, edge: GraphEdge) -> None:
        self.graph.add_edge(edge)

    def discover_attack_paths(
        self,
        source_ids: Iterable[str],
        target_ids: Iterable[str],
        *,
        max_depth: int = 8,
        max_paths: int = 100,
    ) -> List[AttackPath]:

        return self.attack_paths.discover_paths(
            source_ids,
            target_ids,
            max_depth=max_depth,
            max_paths=max_paths,
        )

    def assess_risk(
        self,
        context: AssetRiskContext,
        *,
        attack_paths: Sequence[AttackPath] = (),
        evidence_ids: Sequence[str] = (),
    ) -> RiskAssessment:

        highest_path_risk = max(
            (
                path.risk_score
                for path in attack_paths
            ),
            default=0.0,
        )

        enriched = AssetRiskContext(
            asset_id=context.asset_id,
            criticality=context.criticality,
            exposure=context.exposure,
            exploitability=context.exploitability,
            threat_activity=context.threat_activity,
            business_impact=context.business_impact,
            historical_risk=context.historical_risk,
            identity_privilege=context.identity_privilege,
            attack_path_risk=highest_path_risk,
        )

        return self.risk.calculate(
            enriched,
            evidence_ids=evidence_ids,
            attack_path_ids=[
                path.path_id
                for path in attack_paths
            ],
        )
    # --- preserved from Phase7RiskAttackPathService (merged, not present in canonical host) ---
    def aggregate_by_subject(
        self,
        assessments: Sequence[RiskAssessment],
    ) -> Dict[str, float]:

        return self.aggregation.aggregate_by_subject(
            assessments
        )
    # --- preserved from Phase7RiskAttackPathService (merged, not present in canonical host) ---
    def assess_vulnerability(
        self,
        vulnerability: VulnerabilityContext,
    ) -> float:

        return self.vulnerability.assess(
            vulnerability
        )
    # --- preserved from Phase7RiskAttackPathService (merged, not present in canonical host) ---
    def calculate_asset_criticality(
        self,
        *,
        business_value: float,
        data_sensitivity: float,
        operational_dependency: float,
        regulatory_impact: float,
        recovery_difficulty: float,
    ) -> float:

        return self.criticality.calculate(
            business_value=business_value,
            data_sensitivity=data_sensitivity,
            operational_dependency=operational_dependency,
            regulatory_impact=regulatory_impact,
            recovery_difficulty=recovery_difficulty,
        )
    # --- preserved from Phase7RiskAttackPathService (merged, not present in canonical host) ---
    def organizational_posture(
        self,
        assessments: Sequence[RiskAssessment],
    ) -> float:

        return self.aggregation.organizational_posture(
            assessments
        )
    # --- preserved from Phase7RiskAttackPathService (merged, not present in canonical host) ---
    def propagate_risk(
        self,
        seed_risks: Mapping[str, float],
        *,
        iterations: int = 5,
        damping: float = 0.70,
    ) -> Dict[str, float]:

        return self.propagation.propagate(
            self.graph,
            seed_risks,
            iterations=iterations,
            damping=damping,
        )


