def test_asset_criticality() -> None:
    engine = AssetCriticalityEngine()

    score = engine.calculate(
        business_value=100,
        data_sensitivity=100,
        operational_dependency=90,
        regulatory_impact=80,
        recovery_difficulty=70,
    )

    assert 0 <= score <= 100
    assert score > 80


def test_vulnerability_context() -> None:
    vulnerability = VulnerabilityContext(
        vulnerability_id="CVE-TEST-001",
        cvss=9.8,
        exploitable=True,
        internet_exposed=True,
        exploit_available=True,
        active_threat_activity=90,
        compensating_controls=0,
    )

    score = VulnerabilityContextEngine().assess(
        vulnerability
    )

    assert score > 80
    assert score <= 100


def test_attack_graph_path() -> None:
    service = Phase7RiskAttackPathService()

    service.add_node(
        GraphNode(
            node_id="internet",
            node_type=NodeType.INTERNET,
        )
    )

    service.add_node(
        GraphNode(
            node_id="server",
            node_type=NodeType.ASSET,
            criticality=70,
        )
    )

    service.add_node(
        GraphNode(
            node_id="database",
            node_type=NodeType.DATA,
            criticality=100,
        )
    )

    service.add_edge(
        GraphEdge(
            source="internet",
            target="server",
            edge_type=EdgeType.EXPOSES,
            confidence=1.0,
            exploitability=90,
            evidence_ids=("ev-001",),
        )
    )

    service.add_edge(
        GraphEdge(
            source="server",
            target="database",
            edge_type=EdgeType.CONNECTS_TO,
            confidence=0.95,
            exploitability=70,
            evidence_ids=("ev-002",),
        )
    )

    paths = service.discover_attack_paths(
        ["internet"],
        ["database"],
    )

    assert len(paths) == 1
    assert paths[0].nodes == [
        "internet",
        "server",
        "database",
    ]
    assert paths[0].risk_score > 0
    assert "ev-001" in paths[0].evidence_ids
    assert "ev-002" in paths[0].evidence_ids


def test_attack_graph_rejects_unknown_node() -> None:
    graph = CyberAttackGraph()

    graph.add_node(
        GraphNode(
            node_id="asset-1",
            node_type=NodeType.ASSET,
        )
    )

    try:
        graph.add_edge(
            GraphEdge(
                source="asset-1",
                target="missing",
                edge_type=EdgeType.CONNECTS_TO,
            )
        )
    except ValueError:
        return

    raise AssertionError(
        "Graph accepted an edge to an unknown node."
    )


def test_risk_calculation() -> None:
    context = AssetRiskContext(
        asset_id="asset-critical",
        criticality=100,
        exposure=90,
        exploitability=95,
        threat_activity=85,
        business_impact=95,
        historical_risk=70,
        identity_privilege=80,
        attack_path_risk=90,
    )

    assessment = CyberRiskEngine().calculate(
        context,
        evidence_ids=("evidence-1",),
    )

    assert 0 <= assessment.score <= 100
    assert assessment.score > 70
    assert assessment.level in {
        RiskLevel.HIGH,
        RiskLevel.CRITICAL,
    }
    assert "evidence-1" in assessment.evidence_ids
    assert assessment.explanation


def test_risk_propagation() -> None:
    graph = CyberAttackGraph()

    for node_id in ("a", "b", "c"):
        graph.add_node(
            GraphNode(
                node_id=node_id,
                node_type=NodeType.ASSET,
            )
        )

    graph.add_edge(
        GraphEdge(
            source="a",
            target="b",
            edge_type=EdgeType.LEADS_TO,
            confidence=1.0,
            risk_weight=1.0,
        )
    )

    graph.add_edge(
        GraphEdge(
            source="b",
            target="c",
            edge_type=EdgeType.LEADS_TO,
            confidence=1.0,
            risk_weight=1.0,
        )
    )

    result = RiskPropagationEngine().propagate(
        graph,
        {"a": 100},
        iterations=3,
    )

    assert result["a"] == 100
    assert result["b"] > 0
    assert result["c"] > 0


def test_no_fake_risk_evidence() -> None:
    context = AssetRiskContext(
        asset_id="asset-no-evidence",
        criticality=50,
        exposure=50,
    )

    result = CyberRiskEngine().calculate(
        context
    )

    assert result.evidence_ids == []
    assert result.attack_path_ids == []


def test_posture_aggregation() -> None:
    engine = CyberRiskEngine()

    assessments = [
        engine.calculate(
            AssetRiskContext(
                asset_id="a",
                criticality=80,
                exposure=70,
                exploitability=80,
            )
        ),
        engine.calculate(
            AssetRiskContext(
                asset_id="b",
                criticality=40,
                exposure=30,
                exploitability=20,
            )
        ),
    ]

    posture = RiskAggregationEngine().organizational_posture(
        assessments
    )

    assert 0 <= posture <= 100


def run_phase7_tests() -> None:
    tests = [
        test_asset_criticality,
        test_vulnerability_context,
        test_attack_graph_path,
        test_attack_graph_rejects_unknown_node,
        test_risk_calculation,
        test_risk_propagation,
        test_no_fake_risk_evidence,
        test_posture_aggregation,
    ]

    failures = []

    for test in tests:
        try:
            test()
        except Exception as exc:
            failures.append(
                f"{test.__name__}: {exc}"
            )

    if failures:
        raise AssertionError(
            "PHASE 7 TEST FAILURE:\n"
            + "\n".join(failures)
        )

    print(
        f"PHASE 7 VERIFICATION PASSED: "
        f"{len(tests)}/{len(tests)} tests"
    )


