class AgentType(str, Enum):
    """[CONSOLIDATED] identical member names in both defs; THREAT_INTEL value string
    differed (threat_intelligence_agent vs threat_intel_agent) -> alias handled in _missing_."""
    SUPERVISOR = "cyber_supervisor"
    DETECTION = "detection_agent"
    INVESTIGATION = "investigation_agent"
    THREAT_INTEL = "threat_intel_agent"
    RISK = "risk_agent"
    ATTACK_PATH = "attack_path_agent"
    RESPONSE_PLANNER = "response_planner"
    GOVERNANCE = "governance_agent"
    EXECUTION = "execution_agent"
    VERIFICATION = "verification_agent"
    LEARNING = "learning_agent"

    @classmethod
    def _missing_(cls, value):
        if value == "threat_intelligence_agent":
            return cls.THREAT_INTEL
        if isinstance(value, str):
            v = value.strip().lower()
            for member in cls:
                if member.value.lower() == v:
                    return member
        return None
    SYSTEM = 'system'  # merged from AgentType
    HUMAN = 'human'  # merged from AgentType
    SERVICE = 'service'  # merged from AgentType
    THREAT_INTELLIGENCE = 'threat_intelligence'  # merged from AgentType


