# ------------------------------------------------------------
# Agent limits
# ------------------------------------------------------------

@dataclass(frozen=True)
class AgentLimits:
    max_actions_per_run: int = 10
    max_tool_calls_per_run: int = 100
    max_execution_risk_score: float = 0.0
    max_high_risk_requests: int = 0
    max_execution_requests: int = 0
    max_risk_level: RiskLevel = RiskLevel.READ_ONLY
    allow_external_side_effects: bool = False
    allow_external_execution: bool = False
    require_human_approval_above: RiskLevel = RiskLevel.READ_ONLY

    def validate(self) -> None:
        if self.max_actions_per_run < 0:
            raise ValueError("max_actions_per_run cannot be negative")

        if self.max_tool_calls_per_run < 0:
            raise ValueError("max_tool_calls_per_run cannot be negative")

        if not 0.0 <= self.max_execution_risk_score <= 100.0:
            raise ValueError(
                "max_execution_risk_score must be between 0 and 100"
            )




# ------------------------------------------------------------
# Agent context
# ------------------------------------------------------------

@dataclass(frozen=True)
class AgentContext:
    run_id: UUID
    tenant_id: UUID
    actor_id: UUID
    agent_identity: AgentIdentity

    correlation_id: str
    request_id: str | None = None

    metadata: Mapping[str, Any] = field(default_factory=dict)

    created_at: datetime = field(default_factory=utc_now_v6)

    def validate(self) -> None:
        if self.tenant_id != self.agent_identity.tenant_id:
            raise PermissionError(
                "Agent tenant does not match execution tenant"
            )
        if self.actor_id != self.agent_identity.agent_id:
            raise PermissionError(
                "Agent actor does not match agent identity"
            )

        if self.agent_identity.status != AgentStatus.ACTIVE:
            raise PermissionError(
                f"Agent is not active: {self.agent_identity.status.value}"
            )


