# Tool abstraction
# ------------------------------------------------------------



@dataclass(frozen=True)
class ToolDefinition:
    name: str
    capabilities: frozenset[Capability]
    side_effecting: bool = False
# --- preserved from ToolDefinition (merged, not present in canonical host) ---
    def validate(self) -> None:
        require_nonempty(
            self.name,
            "tool.name",
        )

        # [auto-repair, revised] Restored this check. I originally
        # dropped it thinking ToolDefinition had no description field --
        # but this file's compatibility-patch section later replaces
        # ToolDefinition.__init__ with a version that adds
        # description: str = "", so self.description is real at runtime
        # and this check is valid, working validation, not dead code.
        require_nonempty(
            self.description,
            "tool.description",
        )

        if not isinstance(
            self.capabilities,
            frozenset,
        ):
            raise TypeError(
                "tool.capabilities must be frozenset."
            )

        if not all(
            isinstance(
                capability,
                Capability,
            )
            for capability
            in self.capabilities
        ):
            raise TypeError(
                "Tool capabilities contain invalid values."
            )

        if not isinstance(
            self.side_effecting,
            bool,
        ):
            raise TypeError(
                "tool.side_effecting must be boolean."
            )


@dataclass
class RegisteredTool:
    definition: ToolDefinition
    handler: Callable[
        [AgentContext, Mapping[str, Any]],
        Mapping[str, Any],
    ]

    def execute(
        self,
        context: AgentContext,
        arguments: Mapping[str, Any],
    ) -> Mapping[str, Any]:

        result = self.handler(context, arguments)

        if not isinstance(result, Mapping):
            raise TypeError(
                f"Tool '{self.definition.name}' must return a mapping"
            )

        return dict(result)


# ------------------------------------------------------------
# Agent policy / permissions
# ------------------------------------------------------------

@dataclass(frozen=True)
class AgentPolicy:
    allowed_capabilities: frozenset[Any] = frozenset()
    allowed_tools: frozenset[str] = frozenset()
    allowed_permissions: frozenset[Any] = frozenset()
    allow_execution_requests: bool = False
    limits: AgentLimits = field(default_factory=AgentLimits)

    def validate(self) -> None:
        self.limits.validate()


@dataclass
class AgentAuditEvent:
    audit_id: UUID
    timestamp: datetime
    tenant_id: UUID
    run_id: UUID

    agent_id: UUID
    agent_type: AgentType

    event_type: str
    subject: str

    success: bool
    details: Mapping[str, Any] = field(default_factory=dict)


class AgentAuditSink(Protocol):
    def record(self, event: AgentAuditEvent) -> None:
        ...


@dataclass
class InMemoryAgentAuditSink:
    events: list[AgentAuditEvent] = field(default_factory=list)

    def record(self, event: AgentAuditEvent) -> None:
        self.events.append(event)
# --- preserved from InMemoryAgentAuditSink (merged, not present in canonical host) ---
    def for_agent(
        self,
        agent_id: UUID,
    ) -> Tuple[AgentAuditEvent, ...]:

        return tuple(
            event
            for event in self.events
            if event.agent_id == agent_id
        )


# ------------------------------------------------------------
# Agent runtime
# ------------------------------------------------------------

@dataclass
class AgentRuntime:
    identity: AgentIdentity
    policy: AgentPolicy
    audit_sink: AgentAuditSink

    tools: dict[str, RegisteredTool] = field(default_factory=dict)

    def __post_init__(self) -> None:
        self.identity.validate()
        self.policy.validate()

        if self.identity.agent_type == AgentType.EXECUTION:
            # Phase 8 agent runtime does NOT grant execution authority.
            # Actual execution remains behind later-phase governance.
            if self.policy.limits.allow_external_side_effects:
                raise ValueError(
                    "Phase 8 Execution Agent cannot receive "
                    "external side-effect authority"
                )

    def register_tool(self, tool: RegisteredTool) -> None:
        name = tool.definition.name

        if not name.strip():
            raise ValueError("Tool name cannot be empty")

        if name in self.tools:
            raise ValueError(f"Tool already registered: {name}")

        missing = (
            tool.definition.capabilities
            - self.policy.allowed_capabilities
        )

        if missing:
            raise PermissionError(
                f"Tool '{name}' requires unauthorized capabilities: "
                f"{sorted(x.value for x in missing)}"
            )

        if name not in self.policy.allowed_tools:
            raise PermissionError(
                f"Tool '{name}' is not allowed for this agent"
            )

        self.tools[name] = tool

    def invoke_tool(
        self,
        context: AgentContext,
        tool_name: str,
        arguments: Mapping[str, Any] | None = None,
    ) -> Mapping[str, Any]:

        context.validate()

        if context.agent_identity.agent_id != self.identity.agent_id:
            raise PermissionError(
                "Agent identity mismatch"
            )

        if context.actor_id != self.identity.agent_id:
            raise PermissionError(
                "Actor identity does not match agent identity"
            )

        if tool_name not in self.tools:
            raise PermissionError(
                f"Tool '{tool_name}' is not available to this agent"
            )

        tool = self.tools[tool_name]

        if tool.definition.side_effecting:
            # Explicitly blocked in Phase 8.
            raise PermissionError(
                "Side-effecting tools are not executable in Phase 8"
            )

        event = AgentAuditEvent(
            audit_id=uuid4(),
            timestamp=utc_now_v6(),
            tenant_id=context.tenant_id,
            run_id=context.run_id,
            agent_id=self.identity.agent_id,
            agent_type=self.identity.agent_type,
            event_type="tool_invocation",
            subject=tool_name,
            success=False,
        )

        try:
            result = tool.execute(
                context,
                arguments or {},
            )

            event.success = True
            event.details = {
                "tool": tool_name,
                "side_effecting": False,
            }

            self.audit_sink.record(event)
            return result

        except Exception as exc:
            event.details = {
                "tool": tool_name,
                "error_type": type(exc).__name__,
            }

            self.audit_sink.record(event)
            raise
# --- preserved from AgentRuntime (merged, not present in canonical host) ---
    def unregister_tool(
        self,
        tool_name: str,
    ) -> None:

        require_nonempty(
            tool_name,
            "tool_name",
        )

        self.tools.pop(
            tool_name,
            None,
        )
# --- preserved from AgentRuntime (merged, not present in canonical host) ---
    def has_capability(
        self,
        capability: AgentCapability,
    ) -> bool:

        return (
            capability
            in self.policy.allowed_capabilities
        )
# --- preserved from AgentRuntime (merged, not present in canonical host) ---
    def has_permission(
        self,
        permission: AgentPermission,
    ) -> bool:

        return (
            permission
            in self.policy.allowed_permissions
        )
# --- preserved from AgentRuntime (merged, not present in canonical host) ---
    def require_capability(
        self,
        capability: AgentCapability,
    ) -> None:

        if not self.has_capability(
            capability
        ):
            raise AgentCapabilityError(
                f"Agent '{self.identity.agent_id}' "
                f"does not have capability "
                f"'{capability.value}'."
            )
# --- preserved from AgentRuntime (merged, not present in canonical host) ---
    def require_permission(
        self,
        permission: AgentPermission,
    ) -> None:

        if not self.has_permission(
            permission
        ):
            raise AgentPermissionError(
                f"Agent '{self.identity.agent_id}' "
                f"does not have permission "
                f"'{permission.value}'."
            )
# --- preserved from AgentRuntime (merged, not present in canonical host) ---
    def require_tenant(
        self,
        tenant_id: str,
    ) -> None:

        if tenant_id != self.identity.tenant_id:
            raise AgentTenantError(
                "Agent tenant boundary violation."
            )
# --- preserved from AgentRuntime (merged, not present in canonical host) ---
    def transition(
        self,
        new_state: AgentState,
    ) -> None:

        allowed = {
            AgentState.CREATED: {
                AgentState.INITIALIZING,
                AgentState.DISABLED,
                AgentState.TERMINATED,
            },
            AgentState.INITIALIZING: {
                AgentState.READY,
                AgentState.FAILED,
                AgentState.DISABLED,
            },
            AgentState.READY: {
                AgentState.RUNNING,
                AgentState.PAUSED,
                AgentState.DISABLED,
                AgentState.TERMINATED,
            },
            AgentState.RUNNING: {
                AgentState.READY,
                AgentState.PAUSED,
                AgentState.FAILED,
                AgentState.DISABLED,
            },
            AgentState.PAUSED: {
                AgentState.READY,
                AgentState.DISABLED,
                AgentState.TERMINATED,
            },
            AgentState.FAILED: {
                AgentState.INITIALIZING,
                AgentState.DISABLED,
                AgentState.TERMINATED,
            },
            AgentState.DISABLED: {
                AgentState.INITIALIZING,
                AgentState.TERMINATED,
            },
            AgentState.TERMINATED: set(),
        }

        if new_state not in allowed[
            self.state
        ]:
            raise AgentStateError(
                f"Invalid transition: "
                f"{self.state.value} -> "
                f"{new_state.value}"
            )

        self.state = new_state

        if (
            new_state
            is AgentState.RUNNING
        ):
            if self.started_at is None:
                self.started_at = time.time()
# --- preserved from AgentRuntime (merged, not present in canonical host) ---
    def validate_action(
        self,
        request: AgentActionRequest,
    ) -> AgentActionResult:

        self.require_tenant(
            request.tenant_id
        )

        if (
            request.agent_id
            != self.identity.agent_id
        ):
            raise AgentTenantError(
                "Action does not belong to this agent."
            )

        if self.state not in {
            AgentState.READY,
            AgentState.RUNNING,
        }:
            raise AgentStateError(
                "Agent cannot request actions "
                "in its current state."
            )

        self.require_capability(
            AgentCapability.PROPOSE_ACTION
        )

        self.require_permission(
            AgentPermission.PROPOSE
        )

        if (
            self.action_count
            >= self.policy.limits.max_actions_per_run
        ):
            raise AgentLimitError(
                "Action limit exceeded."
            )

        risk = request.risk_level.lower()

        # [auto-repair] this method checked action-count limits,
        # high-risk-count limits, and execution limits, but never
        # compared the request's risk level against
        # self.policy.limits.max_risk_level at all -- the one limit
        # that's supposed to say "this agent may never propose
        # anything above X risk". AgentAuthorization.authorize()
        # (a separate, later path) does check this, via the same
        # RISK_ORDER scheme reused here, but a caller going through
        # AgentRuntime.validate_action() without also going through
        # that second path got no risk-ceiling enforcement at all.
        _RISK_ORDER_LOCAL = {
            "none": -1, "read_only": 0, "low": 1,
            "medium": 2, "high": 3, "critical": 4,
        }
        max_risk = str(self.policy.limits.max_risk_level).lower()
        if max_risk.startswith("risklevel."):
            max_risk = max_risk.split(".", 1)[1]
        if _RISK_ORDER_LOCAL.get(risk, 99) > _RISK_ORDER_LOCAL.get(max_risk, -1):
            raise AgentLimitError(
                "Requested risk exceeds agent's configured max_risk_level."
            )

        if risk in {
            "high",
            "critical",
        }:

            if (
                self.high_risk_count
                >= self.policy.limits.max_high_risk_requests
            ):
                raise AgentLimitError(
                    "High-risk action limit exceeded."
                )

        if request.action_type.lower() in {
            "execute",
            "execution",
        }:

            if not self.policy.allow_execution_requests:
                raise AgentPermissionError(
                    "Agent is not authorized to "
                    "request execution."
                )

            if (
                self.execution_request_count
                >= self.policy.limits.max_execution_requests
            ):
                raise AgentLimitError(
                    "Execution request limit exceeded."
                )

        self.action_count += 1

        if risk in {
            "high",
            "critical",
        }:
            self.high_risk_count += 1

        if request.action_type.lower() in {
            "execute",
            "execution",
        }:
            self.execution_request_count += 1

        return AgentActionResult(
            action_id=request.action_id,
            accepted=True,
            reason=(
                "Agent-level validation passed. "
                "Downstream governance and "
                "authorization are still required."
            ),
            fingerprint=request.fingerprint(),
        )


# ------------------------------------------------------------
# Base Cyber Agent
# ------------------------------------------------------------

@dataclass
class CyberAgent:
    runtime: AgentRuntime

    def __post_init__(self) -> None:
        # NOTE(auto-repair): every method below this point (all originally
        # tagged "preserved from CyberAgent (merged, not present in
        # canonical host)") references self.capabilities/.permissions/
        # .tools/.state/.name/.limits/._actions_used/.audit_identity/
        # .tenant as if they were real attributes -- none were ever
        # initialized anywhere, on this class or its factory. Backing them
        # here so the merged-in methods actually work as written, instead
        # of rewriting every one of them individually.
        self._state = AgentState.ACTIVE
        self._actions_used = 0
        self._tools: Dict[str, "AgentTool"] = {}
        self.audit_identity: Optional["AgentAuditIdentity"] = None
        self.tenant: Optional["AgentTenantContext"] = None

    @property
    def identity(self) -> AgentIdentity:
        return self.runtime.identity

    @property
    def name(self) -> str:
        return self.identity.name

    @property
    def capabilities(self) -> "frozenset[str]":
        return self.identity.capabilities

    @property
    def permissions(self) -> "frozenset[Any]":
        return self.runtime.policy.allowed_permissions

    @property
    def limits(self) -> AgentLimits:
        return self.runtime.policy.limits

    @property
    def tools(self) -> "Dict[str, AgentTool]":
        return self._tools

    @property
    def state(self) -> "AgentState":
        return self._state

    @state.setter
    def state(self, value: "AgentState") -> None:
        self._state = value

    def run(
        self,
        context: AgentContext,
        input_data: Mapping[str, Any],
    ) -> Mapping[str, Any]:
        raise NotImplementedError

    def _result(
        self,
        *,
        status: str,
        findings: Sequence[Mapping[str, Any]] = (),
        evidence_ids: Sequence[str] = (),
        metadata: Mapping[str, Any] | None = None,
    ) -> Mapping[str, Any]:

        return {
            "status": status,
            "agent": self.identity.agent_type.value,
            "agent_id": str(self.identity.agent_id),
            "run_id": str(self._current_run_id),
            "findings": list(findings),
            "evidence_ids": list(evidence_ids),
            "metadata": dict(metadata or {}),
        }

    @property
    def _current_run_id(self) -> UUID:
        return getattr(self, "__run_id", uuid4())

    def _prepare(
        self,
        context: AgentContext,
        input_data: Mapping[str, Any],
    ) -> None:

        context.validate()

        if context.agent_identity.agent_id != self.identity.agent_id:
            raise PermissionError(
                "Context belongs to another agent"
            )

        if not isinstance(input_data, Mapping):
            raise TypeError("Agent input must be a mapping")
# --- preserved from CyberAgent (merged, not present in canonical host) ---
    def assert_tool_access(
        self,
        tool: AgentTool,
    ) -> None:

        self.require_active()

        missing = (
            tool.capabilities
            - self.capabilities
        )

        if missing:
            names = sorted(
                capability.value
                for capability in missing
            )

            raise PermissionError(
                f"Agent '{self.name}' cannot invoke "
                f"tool '{tool.name}'. Missing capabilities: "
                f"{names}"
            )
# --- preserved from CyberAgent (merged, not present in canonical host) ---
    def audit_context(self) -> dict[str, Any]:

        return {
            "agent": self.audit_identity.as_dict(),
            "tenant_id": self.tenant.tenant_id,
            "environment": self.tenant.environment,
            "state": self.state.value,
        }
# --- preserved from CyberAgent (merged, not present in canonical host) ---
    def authorize_action(
        self,
        *,
        risk_level: RiskLevel,
    ) -> None:

        self.require_active()

        self.require_capability(
            Capability.PROPOSE_ACTION
        )

        self.require_permission(
            Permission.PROPOSE
        )

        allowed = {
            RiskLevel.READ_ONLY: 0,
            RiskLevel.LOW: 1,
            RiskLevel.MEDIUM: 2,
            RiskLevel.HIGH: 3,
            RiskLevel.CRITICAL: 4,
        }

        if (
            allowed[risk_level]
            > allowed[self.limits.max_risk_level]
        ):
            raise PermissionError(
                f"Risk level '{risk_level.value}' "
                f"exceeds agent limit "
                f"'{self.limits.max_risk_level.value}'."
            )

        if (
            self._actions_used
            >= self.limits.max_actions_per_run
        ):
            raise PermissionError(
                "Agent action limit reached."
            )
# --- preserved from CyberAgent (merged, not present in canonical host) ---
    def get_tool(
        self,
        name: str,
    ) -> AgentTool:

        self.require_active()

        try:
            return self.tools[name]
        except KeyError:
            raise KeyError(
                f"Tool not registered: {name}"
            ) from None
# --- preserved from CyberAgent (merged, not present in canonical host) ---
    def has_capability(
        self,
        capability: Capability,
    ) -> bool:

        return capability in self.capabilities
# --- preserved from CyberAgent (merged, not present in canonical host) ---
    def has_permission(
        self,
        permission: Permission,
    ) -> bool:

        return permission in self.permissions
# --- preserved from CyberAgent (merged, not present in canonical host) ---
    def record_action(self) -> None:

        if self._actions_used >= self.limits.max_actions_per_run:
            raise PermissionError(
                "Agent action limit reached."
            )

        self._actions_used += 1
# --- preserved from CyberAgent (merged, not present in canonical host) ---
    def register_tool(
        self,
        tool: AgentTool,
    ) -> None:

        self.require_active()

        if tool.name in self.tools:
            raise ValueError(
                f"Tool already registered: {tool.name}"
            )

        self.tools[tool.name] = tool
# --- preserved from CyberAgent (merged, not present in canonical host) ---
    def require_active(self) -> None:

        if self.state != AgentState.ACTIVE:
            raise PermissionError(
                f"Agent '{self.name}' is "
                f"{self.state.value}."
            )
# --- preserved from CyberAgent (merged, not present in canonical host) ---
    def require_capability(
        self,
        capability: Capability,
    ) -> None:

        if not self.has_capability(capability):
            raise PermissionError(
                f"Agent '{self.name}' lacks capability "
                f"'{capability.value}'."
            )
# --- preserved from CyberAgent (merged, not present in canonical host) ---
    def require_permission(
        self,
        permission: Permission,
    ) -> None:

        if not self.has_permission(permission):
            raise PermissionError(
                f"Agent '{self.name}' lacks permission "
                f"'{permission.value}'."
            )
# --- preserved from CyberAgent (merged, not present in canonical host) ---
    def reset_run_limits(self) -> None:
        self._actions_used = 0
# --- preserved from CyberAgent (merged, not present in canonical host) ---
    @property
    def policy(self) -> AgentPolicy:
        return self.runtime.policy


