class DetectionAgent(CyberAgent):

    def run(
        self,
        context: AgentContext,
        input_data: Mapping[str, Any],
    ) -> Mapping[str, Any]:

        self._prepare(context, input_data)

        return self._result(
            status="ready",
            metadata={
                "operation": "detection_analysis",
                "input_received": True,
            },
        )


