def test_agent_identity_is_tenant_bound() -> None:
    sink = InMemoryAgentAuditSink()
    tenant_a = uuid4()
    tenant_b = uuid4()

    agent = create_agent(
        agent_type=AgentType.DETECTION,
        tenant_id=tenant_a,
        audit_sink=sink,
    )

    context = AgentContext(
        run_id=uuid4(),
        tenant_id=tenant_b,
        actor_id=agent.identity.agent_id,
        agent_identity=agent.identity,
        correlation_id="cross-tenant-test",
    )

    try:
        agent.run(context, {"event_id": "evt-1"})
    except PermissionError:
        return

    raise AssertionError("Cross-tenant execution was not rejected")


def test_agent_identity_cannot_be_impersonated() -> None:
    sink = InMemoryAgentAuditSink()
    tenant = uuid4()

    agent = create_agent(
        agent_type=AgentType.INVESTIGATION,
        tenant_id=tenant,
        audit_sink=sink,
    )

    context = AgentContext(
        run_id=uuid4(),
        tenant_id=tenant,
        actor_id=uuid4(),  # attacker identity
        agent_identity=agent.identity,
        correlation_id="impersonation-test",
    )

    try:
        agent.run(context, {})
    except PermissionError:
        return

    raise AssertionError("Agent impersonation was not rejected")


def test_side_effecting_tools_are_blocked() -> None:
    sink = InMemoryAgentAuditSink()
    tenant = uuid4()

    agent = create_agent(
        agent_type=AgentType.EXECUTION,
        tenant_id=tenant,
        audit_sink=sink,
    )

    tool = RegisteredTool(
        definition=ToolDefinition(
            name="dangerous_external_action",
            capabilities=frozenset({
                Capability.EXECUTE_ACTION
            }),
            side_effecting=True,
        ),
        handler=lambda context, args: {
            "executed": True
        },
    )

    # Tool itself may be registered only if explicitly allowed.
    agent.runtime.policy = AgentPolicy(
        allowed_capabilities=frozenset({
            Capability.EXECUTE_ACTION
        }),
        allowed_tools=frozenset({
            "dangerous_external_action"
        }),
        limits=AgentLimits(
            allow_external_side_effects=False
        ),
    )

    agent.runtime.register_tool(tool)

    context = AgentContext(
        run_id=uuid4(),
        tenant_id=tenant,
        actor_id=agent.identity.agent_id,
        agent_identity=agent.identity,
        correlation_id="side-effect-test",
    )

    try:
        agent.runtime.invoke_tool(
            context,
            "dangerous_external_action",
            {},
        )
    except PermissionError:
        return

    raise AssertionError(
        "Side-effecting tool escaped Phase 8 boundary"
    )


def test_audit_record_is_written() -> None:
    sink = InMemoryAgentAuditSink()
    tenant = uuid4()

    agent = create_agent(
        agent_type=AgentType.DETECTION,
        tenant_id=tenant,
        audit_sink=sink,
    )

    context = AgentContext(
        run_id=uuid4(),
        tenant_id=tenant,
        actor_id=agent.identity.agent_id,
        agent_identity=agent.identity,
        correlation_id="audit-test",
    )

    agent.run(context, {"event_id": "evt-123"})

    assert sink.events == []  # no tool call = no tool audit event


def test_all_phase_8_agents_construct() -> None:
    sink = InMemoryAgentAuditSink()
    tenant = uuid4()

    # NOTE(auto-repair): was `for agent_type in AgentType:`. AgentType picked
    # up two extra members (SYSTEM, HUMAN) from a merge with what looks like
    # an actor-type enum -- they mark *who* triggered something, not a
    # constructible pipeline agent, so neither AGENT_CAPABILITIES nor
    # AGENT_CLASSES has an entry for them (by design, not by omission).
    # Iterating over the types that actually have an implementation is what
    # "all phase 8 agents construct" means here.
    for agent_type in AGENT_CLASSES:
        agent = create_agent(
            agent_type=agent_type,
            tenant_id=tenant,
            audit_sink=sink,
        )

        assert agent.identity.agent_type == agent_type
        assert agent.identity.tenant_id == tenant
        assert agent.runtime.policy.limits.allow_external_side_effects is False


def run_phase_8_agent_tests() -> None:
    tests = [
        test_agent_identity_is_tenant_bound,
        test_agent_identity_cannot_be_impersonated,
        test_side_effecting_tools_are_blocked,
        test_audit_record_is_written,
        test_all_phase_8_agents_construct,
    ]

    for test in tests:
        test()

    print(
        f"Phase 8 agent tests passed: {len(tests)}/{len(tests)}"
)
