from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Mapping, Protocol
from uuid import UUID, uuid4
from datetime import datetime, timezone


# ============================================================
# NEXORA CYBER — PHASE 9
# GOVERNANCE + CONTROLLED RESPONSE AUTHORIZATION
#
# Scope:
#   Risk gate
#   Policy evaluation
#   Permission evaluation
#   Approval workflow
#   Execution authorization
#   Supported response adapters
#   Emergency stop
#   Break-glass
#   Governance audit trail
#
# Explicitly NOT implemented here:
#   Post-action verification
#   Learning
#   Production policy self-modification
#   Future enterprise infrastructure
# ============================================================


# [auto-repair] was a byte-for-byte duplicate of utc_now() -- consolidated to a thin alias (Repair Phase 6).
utc_now_v7 = utc_now


# ------------------------------------------------------------
# ENUMERATIONS
# ------------------------------------------------------------

class ActionLevel(str, Enum):
    """
    [CONSOLIDATED — integration/hardening pass]
    Canonical ActionLevel shared across all phases. Originally defined
    independently 3x with divergent member names for the same 5 risk tiers
    (e.g. HIGH_RISK_HUMAN vs HIGH_RISK_HUMAN_APPROVAL vs HIGH_RISK). Superset
    below preserves every name any phase's code refers to; consuming code
    written against any of the 3 original variants keeps working unchanged.
    """
    READ_ONLY = "read_only"
    LOW_RISK_AUTONOMOUS = "low_risk_autonomous"
    LOW_RISK = "low_risk"
    MEDIUM_RISK_APPROVAL = "medium_risk_approval"
    MEDIUM_RISK = "medium_risk"
    HIGH_RISK_HUMAN = "high_risk_human"
    HIGH_RISK_HUMAN_APPROVAL = "high_risk_human_approval"
    HIGH_RISK = "high_risk"
    EMERGENCY_BREAK_GLASS = "emergency_break_glass"
    EMERGENCY = "emergency"




class ApprovalStatus(str, Enum):
    """[CONSOLIDATED] union of 2 definitions."""
    NOT_REQUIRED = "not_required"
    PENDING = "pending"
    APPROVED = "approved"
    REJECTED = "rejected"
    EXPIRED = "expired"
    REVOKED = "revoked"
    REQUIRED = 'required'  # merged from ApprovalStatus


class ExecutionStatus(str, Enum):
    NOT_AUTHORIZED = "not_authorized"
    AUTHORIZED = "authorized"
    EXECUTED = "executed"
    FAILED = "failed"
    STARTED = 'started'  # merged from ExecutionStatus
    COMPLETED = 'completed'  # merged from ExecutionStatus
    CANCELLED = 'cancelled'  # merged from ExecutionStatus


class ResponseAction(str, Enum):
    ISOLATE_ENDPOINT = "isolate_endpoint"
    BLOCK_IOC = "block_ioc"
    REVOKE_SESSION = "revoke_session"
    DISABLE_ACCOUNT = "disable_account"
    ROTATE_CREDENTIAL = "rotate_credential"
    QUARANTINE_ARTIFACT = "quarantine_artifact"
    MODIFY_SECURITY_CONTROL = "modify_security_control"
    CREATE_TICKET = "create_ticket"
    NOTIFY_SECURITY_TEAM = "notify_security_team"
    COLLECT_EVIDENCE = "collect_evidence"


class BreakGlassReason(str, Enum):
    ACTIVE_CRITICAL_THREAT = "active_critical_threat"
    SAFETY_CRITICAL = "safety_critical"
    TIME_CRITICAL = "time_critical"


# ------------------------------------------------------------
# ACTION REQUEST
# ------------------------------------------------------------

@dataclass(frozen=True)
class CyberActionRequest:
    action_id: UUID
    tenant_id: UUID

    requested_by: UUID
    agent_id: UUID

    action: ResponseAction
    action_level: ActionLevel

    target_id: str
    target_type: str

    risk_score: float
    confidence: float

    incident_id: str | None = None
    finding_id: str | None = None

    reason: str = ""
    evidence_ids: tuple[str, ...] = ()

    requested_at: datetime = field(default_factory=utc_now_v7)

    def validate(self) -> None:
        if not 0.0 <= self.risk_score <= 100.0:
            raise ValueError("risk_score must be between 0 and 100")

        if not 0.0 <= self.confidence <= 1.0:
            raise ValueError("confidence must be between 0 and 1")

        if not self.target_id.strip():
            raise ValueError("target_id cannot be empty")

        if not self.target_type.strip():
            raise ValueError("target_type cannot be empty")
    @classmethod
    def create(
        cls,
        *,
        tenant_id: UUID,
        requested_by: UUID,
        agent_id: UUID,
        action: "ResponseAction",
        action_level: "ActionLevel",
        target_id: str,
        target_type: str,
        risk_score: float,
        confidence: float,
        incident_id: Optional[str] = None,
        finding_id: Optional[str] = None,
        reason: str = "",
        evidence_ids: Sequence[str] = (),
    ) -> "CyberActionRequest":
        # NOTE: this consolidates three previously-duplicated `create()`
        # definitions left behind by a bad merge. All three (and the code
        # that called them) used a schema — tenant_id/principal_id/
        # principal_type/action_type/risk_level/metadata — that does not
        # match this dataclass's actual fields (action_id/requested_by/
        # agent_id/action/action_level/target_type/risk_score/confidence).
        # That mismatched version would raise TypeError on the very first
        # call. This version is built against the real fields instead, and
        # delegates to validate() below rather than duplicating its checks.
        if not isinstance(target_id, str) or not target_id.strip():
            raise ValueError("target_id is required.")

        if not isinstance(target_type, str) or not target_type.strip():
            raise ValueError("target_type is required.")

        if not isinstance(action, ResponseAction):
            raise TypeError("action must be a ResponseAction.")

        if not isinstance(action_level, ActionLevel):
            raise TypeError("action_level must be an ActionLevel.")

        instance = cls(
            action_id=uuid4(),
            tenant_id=tenant_id,
            requested_by=requested_by,
            agent_id=agent_id,
            action=action,
            action_level=action_level,
            target_id=target_id.strip(),
            target_type=target_type.strip(),
            risk_score=risk_score,
            confidence=confidence,
            incident_id=incident_id,
            finding_id=finding_id,
            reason=reason.strip(),
            evidence_ids=tuple(
                str(item).strip()
                for item in evidence_ids
                if str(item).strip()
            ),
        )
        instance.validate()
        return instance


# ------------------------------------------------------------
# POLICY
# ------------------------------------------------------------

@dataclass(frozen=True)
class CyberPolicyRule:
    name: str
    action: ResponseAction | None
    minimum_confidence: float
    maximum_risk_score: float
    allowed_levels: frozenset[ActionLevel]
    enabled: bool = True

    def matches(self, request: CyberActionRequest) -> bool:
        if not self.enabled:
            return False

        if self.action is not None and self.action != request.action:
            return False

        if request.confidence < self.minimum_confidence:
            return False

        if request.risk_score > self.maximum_risk_score:
            return False

        return request.action_level in self.allowed_levels


@dataclass(frozen=True)
class CyberPolicy:
    policy_id: UUID
    tenant_id: UUID
    name: str
    rules: tuple[CyberPolicyRule, ...]
    version: str

    immutable: bool = True

    def validate(self) -> None:
        if not self.name.strip():
            raise ValueError("Policy name cannot be empty")

        if not self.version.strip():
            raise ValueError("Policy version cannot be empty")

        if not self.rules:
            raise ValueError("Policy must contain at least one rule")
# --- preserved from CyberPolicy (merged, not present in canonical host) ---
    def matches(
        self,
        request: CyberActionRequest,
        context: Mapping[str, Any],
    ) -> bool:

        # NOTE: this method previously referenced self.enabled, self.subject,
        # and self.conditions -- none of which exist on this dataclass
        # (fields are only policy_id/tenant_id/name/rules/version/immutable)
        # -- plus request.principal_id/principal_type/action_type/metadata,
        # none of which exist on CyberActionRequest either. That body could
        # never have run; it was merged in from an incompatible, richer
        # policy-subject design. This replaces it with matching logic that
        # actually uses this class's real fields, delegating rule-level
        # matching to CyberPolicyRule.matches() (which is correct).
        if self.tenant_id != request.tenant_id:
            return False

        return any(
            rule.matches(request)
            for rule in self.rules
        )


