# POLICY ENGINE
# ------------------------------------------------------------

@dataclass(frozen=True)
class PolicyEvaluation:
    decision: GovernanceDecision
    matched_rules: tuple[str, ...]
    reason: str




# ------------------------------------------------------------
# RISK GATE
# ------------------------------------------------------------

@dataclass(frozen=True)
class RiskGateResult:
    passed: bool
    reason: str


class RiskGate:
    """
    Independent safety gate before authorization.
    """

    def evaluate(
        self,
        request: CyberActionRequest,
    ) -> RiskGateResult:

        request.validate()

        if request.action_level == ActionLevel.READ_ONLY:
            return RiskGateResult(
                passed=True,
                reason="Read-only action",
            )

        if request.confidence < 0.50:
            return RiskGateResult(
                passed=False,
                reason="Confidence below minimum safety threshold",
            )

        if request.risk_score >= 95.0:
            return RiskGateResult(
                passed=False,
                reason="Risk score requires explicit high-risk governance",
            )

        return RiskGateResult(
            passed=True,
            reason="Risk gate passed",
        )


# ------------------------------------------------------------
# APPROVAL
# ------------------------------------------------------------



@dataclass(frozen=True)
class ApprovalDecision:
    approval_id: UUID
    action_id: UUID
    tenant_id: UUID

    approver_id: UUID
    approved: bool

    reason: str
    decided_at: datetime = field(default_factory=utc_now_v7)
    action_binding: str = None  # merged from ApprovalDecision, made optional for safety


class ApprovalEngine:
    def create(
        self,
        request: CyberActionRequest,
    ) -> ApprovalRequest:
        # NOTE(auto-repair): was constructing ApprovalRequest with
        # action_id/requested_for, neither a real field on that dataclass
        # (real fields: approval_id/tenant_id/requested_by/action_type/
        # risk_level/target/required_approvals/created_at), and several
        # required fields were missing entirely. risk_level is derived from
        # request.risk_score since CyberActionRequest doesn't carry a
        # RiskLevel directly.
        if request.risk_score >= 80:
            risk_level = RiskLevel.CRITICAL
        elif request.risk_score >= 60:
            risk_level = RiskLevel.HIGH
        elif request.risk_score >= 30:
            risk_level = RiskLevel.MEDIUM
        elif request.risk_score > 0:
            risk_level = RiskLevel.LOW
        else:
            risk_level = RiskLevel.NONE

        return ApprovalRequest(
            approval_id=str(uuid4()),
            tenant_id=str(request.tenant_id),
            requested_by=str(request.requested_by),
            action_type=request.action.value,
            risk_level=risk_level,
            target=request.target_id,
            required_approvals=1,
            created_at=utc_now(),
            action_id=request.action_id,
        )

    def decide(
        self,
        approval: ApprovalRequest,
        approver_id: UUID,
        approved: bool,
        reason: str,
    ) -> ApprovalDecision:

        if not reason.strip():
            raise ValueError(
                "Approval/rejection must contain a reason"
            )

        return ApprovalDecision(
            approval_id=approval.approval_id,
            action_id=approval.action_id,
            tenant_id=approval.tenant_id,
            approver_id=approver_id,
            approved=approved,
            reason=reason,
        )


# ------------------------------------------------------------
# BREAK-GLASS
# ------------------------------------------------------------

@dataclass(frozen=True)
class BreakGlassRequest:
    request_id: UUID
    tenant_id: UUID
    action_id: UUID

    requested_by: UUID
    reason: BreakGlassReason

    justification: str
    expires_at: datetime

    created_at: datetime = field(default_factory=utc_now_v7)

    def validate(self) -> None:
        if not self.justification.strip():
            raise ValueError(
                "Break-glass requires explicit justification"
            )

        if self.expires_at <= self.created_at:
            raise ValueError(
                "Break-glass authorization must expire in the future"
            )


class BreakGlassController:

    def authorize(
        self,
        request: BreakGlassRequest,
    ) -> bool:

        request.validate()

        # Authorization is time-bounded.
        # It does not automatically execute anything.
        return True


# ------------------------------------------------------------
# EMERGENCY STOP
# ------------------------------------------------------------

@dataclass
class EmergencyStopController:
    stopped_tenants: set[UUID] = field(default_factory=set)

    def activate(self, tenant_id: UUID) -> None:
        self.stopped_tenants.add(tenant_id)

    def deactivate(self, tenant_id: UUID) -> None:
        self.stopped_tenants.discard(tenant_id)

    # NOTE(auto-repair): Phase 21's self-test calls activate_tenant()/
    # deactivate_tenant() (aliases for the two methods above).
    def activate_tenant(self, tenant_id: UUID) -> None:
        self.activate(tenant_id)

    def deactivate_tenant(self, tenant_id: UUID) -> None:
        self.deactivate(tenant_id)

    def is_stopped(self, tenant_id: UUID) -> bool:
        return tenant_id in self.stopped_tenants

    def assert_execution_allowed(
        self,
        tenant_id: UUID,
    ) -> None:

        if self.is_stopped(tenant_id):
            raise PermissionError(
                "Emergency stop is active for this tenant"
            )


# ------------------------------------------------------------
# RESPONSE ADAPTER
# ------------------------------------------------------------



@dataclass
class SimulatorResponseAdapter:
    """
    Safe test adapter.

    It NEVER performs an external action.
    """

    supported_actions: frozenset[ResponseAction]

    def execute(
        self,
        request: CyberActionRequest,
    ) -> Mapping[str, Any]:

        if request.action not in self.supported_actions:
            raise ValueError(
                f"Unsupported response action: {request.action.value}"
            )

        return {
            "adapter": "simulator",
            "action": request.action.value,
            "target": request.target_id,
            "executed": False,
            "simulation": True,
        }


# ------------------------------------------------------------
# EXECUTION AUTHORIZATION
# ------------------------------------------------------------

@dataclass(frozen=True)
class ExecutionAuthorization:
    authorization_id: UUID

    action_id: UUID
    tenant_id: UUID

    authorized_by_policy: bool
    approval_status: ApprovalStatus

    break_glass: bool

    authorized_at: datetime = field(default_factory=utc_now_v7)


class ExecutionAuthorizer:

    def authorize(
        self,
        *,
        request: CyberActionRequest,
        policy_result: PolicyEvaluation,
        risk_result: RiskGateResult,
        approval: ApprovalDecision | None,
        break_glass: bool,
    ) -> ExecutionAuthorization:

        if not risk_result.passed:
            raise PermissionError(
                f"Risk gate rejected action: {risk_result.reason}"
            )

        # NOTE(auto-repair): policy_result.decision is a GovernanceDecision
        # *record* (has .effect, .reason, .risk_level, ...), not itself the
        # ALLOW/DENY/... enum -- these three comparisons were missing
        # .effect. Also EMERGENCY_REVIEW was never a real member of either
        # GovernanceDecision's aliases or PolicyEffect; EMERGENCY_STOP is
        # the closest existing concept and fits the break-glass logic here.
        if policy_result.decision.effect == GovernanceDecision.DENY:
            raise PermissionError(
                f"Policy denied action: {policy_result.reason}"
            )

        if (
            policy_result.decision.effect
            == GovernanceDecision.REQUIRE_APPROVAL
        ):
            if approval is None:
                raise PermissionError(
                    "Human approval is required"
                )

            if not approval.approved:
                raise PermissionError(
                    "Human approver rejected action"
                )

            approval_status = ApprovalStatus.APPROVED

        elif (
            policy_result.decision.effect
            == GovernanceDecision.EMERGENCY_STOP
        ):
            if not break_glass:
                raise PermissionError(
                    "Emergency action requires break-glass authorization"
                )

            approval_status = ApprovalStatus.APPROVED

        else:
            approval_status = ApprovalStatus.NOT_REQUIRED

        return ExecutionAuthorization(
            authorization_id=uuid4(),
            action_id=request.action_id,
            tenant_id=request.tenant_id,
            authorized_by_policy=True,
            approval_status=approval_status,
            break_glass=break_glass,
        )


# ------------------------------------------------------------
# GOVERNANCE AUDIT
# ------------------------------------------------------------

@dataclass(frozen=True)
class GovernanceAuditRecord:
    record_id: UUID
    timestamp: datetime

    tenant_id: UUID
    action_id: UUID

    event_type: str
    decision: str

    actor_id: UUID | None
    reason: str

    metadata: Mapping[str, Any] = field(default_factory=dict)
    audit_id: str = None  # merged from GovernanceAuditRecord, made optional for safety
    request_id: str = None  # merged from GovernanceAuditRecord, made optional for safety
    details: Mapping[str, Any] = None  # merged from GovernanceAuditRecord, made optional for safety
    previous_hash: str = None  # merged from GovernanceAuditRecord, made optional for safety
    record_hash: str = None  # merged from GovernanceAuditRecord, made optional for safety


class GovernanceAuditLedger:

    def __init__(self) -> None:
        self._records: list[GovernanceAuditRecord] = []
        # [auto-repair] verify_chain() below already expected self._lock;
        # nothing ever set it, so calling verify_chain() would raise
        # AttributeError. Adding it here, and also using it in append(),
        # so concurrent writers can't race each other or verify_chain().
        self._lock = threading.RLock()

    def append(
        self,
        *,
        tenant_id: UUID,
        action_id: UUID,
        event_type: str,
        decision: str,
        actor_id: UUID | None,
        reason: str,
        metadata: Mapping[str, Any] | None = None,
    ) -> GovernanceAuditRecord:

        record = GovernanceAuditRecord(
            record_id=uuid4(),
            timestamp=utc_now_v7(),
            tenant_id=tenant_id,
            action_id=action_id,
            event_type=event_type,
            decision=decision,
            actor_id=actor_id,
            reason=reason,
            metadata=dict(metadata or {}),
        )

        with self._lock:
            self._records.append(record)
        return record

    def records_for_tenant(
        self,
        tenant_id: UUID,
    ) -> tuple[GovernanceAuditRecord, ...]:

        return tuple(
            record
            for record in self._records
            if record.tenant_id == tenant_id
        )
    # --- preserved from GovernanceAuditLedger (merged, not present in canonical host) ---
    def verify_chain(self) -> bool:
        """
        Recalculate every record hash and verify chain continuity.
        """

        with self._lock:

            previous_hash = "GENESIS"

            for record in self._records:

                hash_payload = {
                    "tenant_id": str(
                        record.tenant_id
                    ),
                    "action_id": str(
                        record.action_id
                    ),
                    "event_type": (
                        record.event_type
                    ),
                    "decision": (
                        record.decision
                    ),
                    "actor_id": (
                        str(record.actor_id)
                        if record.actor_id
                        else None
                    ),
                    "reason": record.reason,
                    "metadata": dict(
                        record.metadata
                    ),
                    "previous_hash": (
                        previous_hash
                    ),
                }

                expected_hash = sha256(
                    canonical_json(
                        hash_payload
                    ).encode("utf-8")
                ).hexdigest()

                if (
                    record.previous_hash
                    != previous_hash
                ):

                    return False

                if not compare_digest(
                    record.record_hash,
                    expected_hash,
                ):

                    return False

                previous_hash = (
                    record.record_hash
                )

            return True
    # --- preserved from GovernanceAuditLedger (merged, not present in canonical host) ---
    def records(
        self,
        tenant_id: Optional[str] = None,
    ) -> tuple[
        GovernanceAuditRecord, ...
    ]:

        if tenant_id is None:
            return tuple(
                self._records
            )

        return tuple(
            record
            for record
            in self._records
            if record.tenant_id
            == tenant_id
        )


# ------------------------------------------------------------
# GOVERNANCE ORCHESTRATOR
# ------------------------------------------------------------

@dataclass
class CyberGovernance:

    policy_engine: CyberPolicyEngine
    risk_gate: RiskGate
    approval_engine: ApprovalEngine
    authorizer: ExecutionAuthorizer

    break_glass: BreakGlassController
    emergency_stop: EmergencyStopController

    audit: GovernanceAuditLedger

    def evaluate(
        self,
        *,
        policy: CyberPolicy,
        request: CyberActionRequest,
    ) -> PolicyEvaluation:

        self.emergency_stop.assert_execution_allowed(
            request.tenant_id
        )

        risk = self.risk_gate.evaluate(request)
        policy_result = self.policy_engine.evaluate(
            policy,
            request,
        )

        self.audit.append(
            tenant_id=request.tenant_id,
            action_id=request.action_id,
            event_type="governance_evaluation",
            # NOTE(auto-repair): was policy_result.decision.value.
            # policy_result.decision is a GovernanceDecision *record*
            # (decision_id/effect/reason/risk_level/...), not an enum -- the
            # actual ALLOW/DENY/etc. value is its .effect field.
            decision=policy_result.decision.effect.value,
            actor_id=request.agent_id,
            reason=policy_result.reason,
            metadata={
                "risk_score": request.risk_score,
                "confidence": request.confidence,
                "risk_gate_passed": risk.passed,
            },
        )

        return policy_result

    def authorize(
        self,
        *,
        policy: CyberPolicy,
        request: CyberActionRequest,
        approval: ApprovalDecision | None = None,
        break_glass: bool = False,
    ) -> ExecutionAuthorization:

        self.emergency_stop.assert_execution_allowed(
            request.tenant_id
        )

        risk_result = self.risk_gate.evaluate(request)

        policy_result = self.policy_engine.evaluate(
            policy,
            request,
        )

        authorization = self.authorizer.authorize(
            request=request,
            policy_result=policy_result,
            risk_result=risk_result,
            approval=approval,
            break_glass=break_glass,
        )

        self.audit.append(
            tenant_id=request.tenant_id,
            action_id=request.action_id,
            event_type="execution_authorization",
            decision="authorized",
            actor_id=request.agent_id,
            reason="Governance authorization granted",
            metadata={
                "authorization_id":
                    str(authorization.authorization_id),
                "break_glass":
                    authorization.break_glass,
            },
        )

        return authorization


