    tenant_a = uuid4()
    tenant_b = uuid4()
    agent = uuid4()

    governance = build_governance()
    policy = build_test_policy(tenant_a)

    request = build_request(
        tenant_id=tenant_b,
        agent_id=agent,
        action=ResponseAction.ISOLATE_ENDPOINT,
        level=ActionLevel.LOW_RISK_AUTONOMOUS,
        risk=50.0,
        confidence=0.95,
    )

    # Policy itself belongs to tenant A.
    # Request belongs to tenant B.
    # Must not authorize across tenant boundary.

    try:
        governance.authorize(
            policy=policy,
            request=request,
        )
    except (PermissionError, ValueError):
        return

    raise AssertionError(
        "Cross-tenant policy authorization was possible"
    )


