# [auto-repair] was a byte-for-byte duplicate of utc_now() -- consolidated to a thin alias (Repair Phase 6).
utc_now_v8 = utc_now


def clamp_v3(value: float, low: float = 0.0, high: float = 1.0) -> float:
    return max(low, min(high, value))


def weighted_average(values: Iterable[Tuple[float, float]]) -> float:
    numerator = 0.0
    denominator = 0.0

    for value, weight in values:
        if weight <= 0:
            continue

        numerator += value * weight
        denominator += weight

    if denominator == 0:
        return 0.0

    return clamp_v3(numerator / denominator)


