@dataclass(frozen=True)
class PredictionEvidence:
    evidence_id: str
    source: str
    observation: str
    reliability: float = 0.5
    provenance: Optional[str] = None

    def __post_init__(self) -> None:
        if not self.evidence_id:
            raise ValueError("evidence_id is required")

        if not self.source:
            raise ValueError("source is required")

        if not self.observation:
            raise ValueError("observation is required")

        if not 0.0 <= self.reliability <= 1.0:
            raise ValueError("reliability must be between 0 and 1")


@dataclass(frozen=True)
class CyberPrediction:
    prediction_id: str
    tenant_id: str
    prediction_type: PredictionType

    subject_id: str
    predicted_state: str

    probability: float
    confidence: float

    time_horizon_seconds: int

    severity: RiskLevel

    evidence: Tuple[PredictionEvidence, ...] = ()
    assumptions: Tuple[str, ...] = ()

    generated_at: datetime = field(default_factory=utc_now_v8)

    def __post_init__(self) -> None:
        if not self.prediction_id:
            raise ValueError("prediction_id is required")

        if not self.tenant_id:
            raise ValueError("tenant_id is required")

        if not self.subject_id:
            raise ValueError("subject_id is required")

        if not self.predicted_state:
            raise ValueError("predicted_state is required")

        if not 0.0 <= self.probability <= 1.0:
            raise ValueError("probability must be between 0 and 1")

        if not 0.0 <= self.confidence <= 1.0:
            raise ValueError("confidence must be between 0 and 1")

        if self.time_horizon_seconds < 0:
            raise ValueError("time_horizon_seconds cannot be negative")


# ============================================================
# SIMULATION MODELS
# ============================================================


@dataclass(frozen=True)
class CyberState:
    state_id: str
    assets: Mapping[str, Mapping[str, Any]]
    identities: Mapping[str, Mapping[str, Any]]
    threats: Mapping[str, Mapping[str, Any]]
    relationships: Mapping[str, Sequence[str]] = field(default_factory=dict)

    def clone(self) -> "CyberState":
        return CyberState(
            state_id=str(uuid4()),
            assets={
                key: dict(value)
                for key, value in self.assets.items()
            },
            identities={
                key: dict(value)
                for key, value in self.identities.items()
            },
            threats={
                key: dict(value)
                for key, value in self.threats.items()
            },
            relationships={
                key: tuple(value)
                for key, value in self.relationships.items()
            },
        )


@dataclass(frozen=True)
class ProposedAction:
    action_id: str
    action_type: str
    target_id: str
    parameters: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if not self.action_id:
            raise ValueError("action_id is required")

        if not self.action_type:
            raise ValueError("action_type is required")

        if not self.target_id:
            raise ValueError("target_id is required")


@dataclass(frozen=True)
class SimulationConsequence:
    description: str
    probability: float
    severity: RiskLevel
    affected_entities: Tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if not self.description:
            raise ValueError("description is required")

        if not 0.0 <= self.probability <= 1.0:
            raise ValueError("probability must be between 0 and 1")


@dataclass(frozen=True)
class SimulationResult:
    simulation_id: str
    tenant_id: str
    mode: SimulationMode
    status: SimulationStatus

    action: ProposedAction

    security_benefit: float
    operational_risk: float
    residual_threat: float

    recommendation_score: float

    predicted_consequences: Tuple[SimulationConsequence, ...]
    alternatives: Tuple[str, ...]

    confidence: float
    assumptions: Tuple[str, ...]
    provenance: Tuple[str, ...]

    generated_at: datetime = field(default_factory=utc_now_v8)
    # [auto-repair] duration_seconds below referenced self.started_at /
    # self.finished_at, which didn't exist on this dataclass at all.
    # Added with safe defaults so existing call sites don't break; for a
    # meaningful (non-zero) duration, callers should pass real values.
    started_at: datetime = field(default_factory=utc_now_v8)
    finished_at: datetime = field(default_factory=utc_now_v8)

    @property
    def risk_level(self) -> RiskLevel:
        if self.operational_risk >= 0.85:
            return RiskLevel.CRITICAL
        if self.operational_risk >= 0.65:
            return RiskLevel.HIGH
        if self.operational_risk >= 0.35:
            return RiskLevel.MEDIUM
        return RiskLevel.LOW
# --- preserved from SimulationResult (merged, not present in canonical host) ---
    @property
    def duration_seconds(self) -> float:
        return (
            self.finished_at
            - self.started_at
        ).total_seconds()


# ============================================================
# PREDICTION ENGINE
# ============================================================


class PredictionEngine:
    """
    Deterministic prediction layer.

    This engine deliberately does NOT execute actions.
    It estimates future security states using supplied evidence
    and current cyber state.
    """

    def predict_threat_progression(
        self,
        *,
        tenant_id: str,
        subject_id: str,
        threat_activity: float,
        exposure: float,
        exploitability: float,
        privilege: float,
        evidence: Sequence[PredictionEvidence] = (),
        time_horizon_seconds: int = 3600,
    ) -> CyberPrediction:

        threat_activity = clamp_v3(threat_activity)
        exposure = clamp_v3(exposure)
        exploitability = clamp_v3(exploitability)
        privilege = clamp_v3(privilege)

        evidence_quality = weighted_average(
            (
                (item.reliability, 1.0)
                for item in evidence
            )
        )

        base_probability = weighted_average(
            (
                (threat_activity, 0.30),
                (exposure, 0.20),
                (exploitability, 0.25),
                (privilege, 0.15),
                (evidence_quality, 0.10),
            )
        )

        probability = clamp_v3(base_probability)

        confidence = weighted_average(
            (
                (evidence_quality, 0.60),
                (1.0 - abs(probability - 0.5), 0.40),
            )
        )

        severity = self._risk_level(probability)

        predicted_state = (
            "likely_escalation"
            if probability >= 0.70
            else "possible_escalation"
            if probability >= 0.40
            else "stable_or_contained"
        )

        assumptions = (
            "External telemetry is treated as untrusted input.",
            "Prediction does not constitute proof of compromise.",
            "Probability is bounded by supplied evidence quality.",
        )

        return CyberPrediction(
            prediction_id=str(uuid4()),
            tenant_id=tenant_id,
            prediction_type=PredictionType.THREAT_PROGRESSION,
            subject_id=subject_id,
            predicted_state=predicted_state,
            probability=probability,
            confidence=confidence,
            time_horizon_seconds=time_horizon_seconds,
            severity=severity,
            evidence=tuple(evidence),
            assumptions=assumptions,
        )

    def predict_response_outcome(
        self,
        *,
        tenant_id: str,
        subject_id: str,
        action_effectiveness: float,
        threat_activity: float,
        detection_confidence: float,
        evidence: Sequence[PredictionEvidence] = (),
        time_horizon_seconds: int = 900,
    ) -> CyberPrediction:

        effectiveness = clamp_v3(action_effectiveness)
        threat_activity = clamp_v3(threat_activity)
        detection_confidence = clamp_v3(detection_confidence)

        evidence_quality = weighted_average(
            (
                (item.reliability, 1.0)
                for item in evidence
            )
        )

        success_probability = weighted_average(
            (
                (effectiveness, 0.45),
                (detection_confidence, 0.25),
                (1.0 - threat_activity, 0.20),
                (evidence_quality, 0.10),
            )
        )

        confidence = weighted_average(
            (
                (evidence_quality, 0.50),
                (detection_confidence, 0.30),
                (effectiveness, 0.20),
            )
        )

        predicted_state = (
            "likely_contained"
            if success_probability >= 0.75
            else "partially_contained"
            if success_probability >= 0.45
            else "likely_unsuccessful"
        )

        return CyberPrediction(
            prediction_id=str(uuid4()),
            tenant_id=tenant_id,
            prediction_type=PredictionType.RESPONSE_OUTCOME,
            subject_id=subject_id,
            predicted_state=predicted_state,
            probability=success_probability,
            confidence=confidence,
            time_horizon_seconds=time_horizon_seconds,
            severity=self._risk_level(1.0 - success_probability),
            evidence=tuple(evidence),
            assumptions=(
                "No external action is executed during prediction.",
                "Predicted outcome requires later external verification.",
            ),
        )

    @staticmethod
    def _risk_level(score: float) -> RiskLevel:
        if score >= 0.85:
            return RiskLevel.CRITICAL
        if score >= 0.65:
            return RiskLevel.HIGH
        if score >= 0.35:
            return RiskLevel.MEDIUM
        return RiskLevel.LOW
    # --- preserved from PredictionEngine (merged, not present in canonical host) ---
    def predict_incident_escalation(
        self,
        *,
        tenant_id: str,
        subject_id: str,
        incident_pressure: float,
        evidence: Sequence[
            PredictionEvidence
        ] = (),
        time_horizon_seconds: int = 3600,
    ) -> CyberPrediction:

        if not tenant_id.strip():
            raise ValueError(
                "tenant_id is required."
            )

        if not subject_id.strip():
            raise ValueError(
                "subject_id is required."
            )

        pressure = clamp(
            incident_pressure
        )

        evidence_confidence = (
            weighted_average(
                tuple(
                    (
                        item.reliability,
                        1.0,
                    )
                    for item in evidence
                )
            )
            if evidence
            else 0.5
        )

        confidence = clamp(
            0.55
            + (
                evidence_confidence
                * 0.35
            )
        )

        return CyberPrediction(
            prediction_id=str(
                uuid4()
            ),

            tenant_id=tenant_id,

            prediction_type=(
                PredictionType
                .INCIDENT_ESCALATION
            ),

            subject_id=subject_id,

            predicted_state={
                "escalation_probability":
                    pressure,
            },

            probability=pressure,

            confidence=confidence,

            time_horizon_seconds=max(
                1,
                int(
                    time_horizon_seconds
                )
            ),

            severity=(
                self._risk_level(
                    pressure
                )
            ),

            evidence=tuple(
                evidence
            ),

            assumptions=(
                "Escalation probability is estimated from supplied pressure.",
            ),
        )


# ============================================================
# SIMULATION ENGINE
# ============================================================


class SimulationEngine:
    """
    Safe counterfactual simulator.

    It operates exclusively on cloned state.
    No connector, external system, or response action is invoked.
    """

    ACTION_EFFECTS: Dict[str, Dict[str, float]] = {
        "isolate_endpoint": {
            "security_benefit": 0.82,
            "operational_risk": 0.48,
            "threat_reduction": 0.75,
        },
        "block_ioc": {
            "security_benefit": 0.72,
            "operational_risk": 0.22,
            "threat_reduction": 0.58,
        },
        "revoke_session": {
            "security_benefit": 0.68,
            "operational_risk": 0.18,
            "threat_reduction": 0.55,
        },
        "disable_account": {
            "security_benefit": 0.84,
            "operational_risk": 0.55,
            "threat_reduction": 0.78,
        },
        "quarantine_artifact": {
            "security_benefit": 0.76,
            "operational_risk": 0.25,
            "threat_reduction": 0.66,
        },
        "collect_evidence": {
            "security_benefit": 0.28,
            "operational_risk": 0.05,
            "threat_reduction": 0.04,
        },
        "create_ticket": {
            "security_benefit": 0.15,
            "operational_risk": 0.02,
            "threat_reduction": 0.02,
        },
    }

    def simulate(
        self,
        *,
        tenant_id: str,
        current_state: CyberState,
        action: ProposedAction,
        mode: SimulationMode = SimulationMode.RESPONSE,
        threat_pressure: float = 0.5,
        asset_criticality: float = 0.5,
        identity_privilege: float = 0.0,
        evidence: Sequence[PredictionEvidence] = (),
    ) -> SimulationResult:

        if not tenant_id:
            raise ValueError("tenant_id is required")

        if not current_state:
            raise ValueError("current_state is required")

        threat_pressure = clamp_v3(threat_pressure)
        asset_criticality = clamp_v3(asset_criticality)
        identity_privilege = clamp_v3(identity_privilege)

        # Never mutate the supplied state.
        simulated_state = current_state.clone()

        effect = self.ACTION_EFFECTS.get(action.action_type)

        if effect is None:
            return SimulationResult(
                simulation_id=str(uuid4()),
                tenant_id=tenant_id,
                mode=mode,
                status=SimulationStatus.FAILED,
                action=action,
                security_benefit=0.0,
                operational_risk=1.0,
                residual_threat=1.0,
                recommendation_score=0.0,
                predicted_consequences=(
                    SimulationConsequence(
                        description=(
                            "Action has no registered simulation model; "
                            "no execution is permitted."
                        ),
                        probability=1.0,
                        severity=RiskLevel.HIGH,
                        affected_entities=(action.target_id,),
                    ),
                ),
                alternatives=(
                    "collect_evidence",
                    "create_ticket",
                ),
                confidence=1.0,
                assumptions=(
                    "Unsupported action types are fail-closed.",
                ),
                provenance=("simulation.action-model",),
            )

        criticality_penalty = asset_criticality * 0.20
        privilege_penalty = identity_privilege * 0.15

        operational_risk = clamp_v3(
            effect["operational_risk"]
            + criticality_penalty
            + privilege_penalty
        )

        security_benefit = clamp_v3(
            effect["security_benefit"]
            * (0.70 + (0.30 * (1.0 - threat_pressure)))
        )

        residual_threat = clamp_v3(
            threat_pressure
            * (1.0 - effect["threat_reduction"])
        )

        evidence_quality = weighted_average(
            (
                (item.reliability, 1.0)
                for item in evidence
            )
        )

        confidence = (
            evidence_quality
            if evidence
            else 0.45
        )

        recommendation_score = clamp_v3(
            (
                (security_benefit * 0.50)
                + ((1.0 - operational_risk) * 0.25)
                + ((1.0 - residual_threat) * 0.25)
            )
            * (0.70 + (0.30 * confidence))
        )

        consequences = self._build_consequences(
            action=action,
            operational_risk=operational_risk,
            residual_threat=residual_threat,
            asset_criticality=asset_criticality,
            identity_privilege=identity_privilege,
        )

        alternatives = self._alternatives(action.action_type)

        assumptions = (
            "Simulation is isolated from real-world execution.",
            "External connector state is not modified.",
            "Predicted consequences are probabilistic estimates.",
            "Unsupported execution paths fail closed.",
        )

        provenance = (
            "simulation.action-model",
            "simulation.state-clone",
            "simulation.risk-model",
        )

        status = (
            SimulationStatus.COMPLETED
            if evidence
            else SimulationStatus.PARTIAL
        )

        # Explicitly retain clone only as a simulation boundary.
        del simulated_state

        return SimulationResult(
            simulation_id=str(uuid4()),
            tenant_id=tenant_id,
            mode=mode,
            status=status,
            action=action,
            security_benefit=security_benefit,
            operational_risk=operational_risk,
            residual_threat=residual_threat,
            recommendation_score=recommendation_score,
            predicted_consequences=tuple(consequences),
            alternatives=alternatives,
            confidence=confidence,
            assumptions=assumptions,
            provenance=provenance,
        )

    def compare_actions(
        self,
        *,
        tenant_id: str,
        current_state: CyberState,
        actions: Sequence[ProposedAction],
        threat_pressure: float,
        asset_criticality: float,
        identity_privilege: float = 0.0,
        evidence: Sequence[PredictionEvidence] = (),
    ) -> Tuple[SimulationResult, ...]:

        results = [
            self.simulate(
                tenant_id=tenant_id,
                current_state=current_state,
                action=action,
                mode=SimulationMode.COUNTERFACTUAL,
                threat_pressure=threat_pressure,
                asset_criticality=asset_criticality,
                identity_privilege=identity_privilege,
                evidence=evidence,
            )
            for action in actions
        ]

        return tuple(
            sorted(
                results,
                key=lambda item: item.recommendation_score,
                reverse=True,
            )
        )

    def _build_consequences(
        self,
        *,
        action: ProposedAction,
        operational_risk: float,
        residual_threat: float,
        asset_criticality: float,
        identity_privilege: float,
    ) -> List[SimulationConsequence]:

        consequences: List[SimulationConsequence] = []

        if residual_threat >= 0.50:
            consequences.append(
                SimulationConsequence(
                    description=(
                        "Threat activity may persist after the proposed action."
                    ),
                    probability=residual_threat,
                    severity=RiskLevel.HIGH,
                    affected_entities=(action.target_id,),
                )
            )

        if operational_risk >= 0.35:
            severity = (
                RiskLevel.CRITICAL
                if operational_risk >= 0.85
                else RiskLevel.HIGH
                if operational_risk >= 0.65
                else RiskLevel.MEDIUM
            )

            consequences.append(
                SimulationConsequence(
                    description=(
                        "The proposed action may disrupt legitimate "
                        "operations or availability."
                    ),
                    probability=operational_risk,
                    severity=severity,
                    affected_entities=(action.target_id,),
                )
            )

        if asset_criticality >= 0.75:
            consequences.append(
                SimulationConsequence(
                    description=(
                        "High-criticality asset requires additional "
                        "operational-impact consideration."
                    ),
                    probability=asset_criticality,
                    severity=RiskLevel.HIGH,
                    affected_entities=(action.target_id,),
                )
            )

        if identity_privilege >= 0.75:
            consequences.append(
                SimulationConsequence(
                    description=(
                        "Privileged identity context increases the "
                        "potential blast radius."
                    ),
                    probability=identity_privilege,
                    severity=RiskLevel.HIGH,
                    affected_entities=(action.target_id,),
                )
            )

        if not consequences:
            consequences.append(
                SimulationConsequence(
                    description="No material adverse consequence predicted.",
                    probability=0.20,
                    severity=RiskLevel.LOW,
                    affected_entities=(action.target_id,),
                )
            )

        return consequences

    @staticmethod
    def _alternatives(action_type: str) -> Tuple[str, ...]:
        alternatives = {
            "isolate_endpoint": (
                "collect_evidence",
                "block_ioc",
                "revoke_session",
            ),
            "block_ioc": (
                "collect_evidence",
                "isolate_endpoint",
            ),
            "revoke_session": (
                "collect_evidence",
                "disable_account",
            ),
            "disable_account": (
                "revoke_session",
                "collect_evidence",
            ),
            "quarantine_artifact": (
                "collect_evidence",
                "block_ioc",
            ),
        }

        return alternatives.get(
            action_type,
            (
                "collect_evidence",
                "create_ticket",
            ),
        )


# ============================================================
# COUNTERFACTUAL ANALYSIS
# ============================================================


@dataclass(frozen=True)
class CounterfactualResult:
    baseline_threat: float
    simulated_threat: float
    threat_reduction: float

    baseline_operational_risk: float
    simulated_operational_risk: float

    net_security_gain: float
    preferred: bool

    explanation: str


class CounterfactualAnalyzer:
    """
    Compares a proposed action against doing nothing.

    No action is executed.
    """

    def analyze(
        self,
        *,
        baseline_threat: float,
        simulation: SimulationResult,
    ) -> CounterfactualResult:

        baseline_threat = clamp_v3(baseline_threat)

        threat_reduction = clamp_v3(
            baseline_threat - simulation.residual_threat
        )

        net_security_gain = clamp_v3(
            threat_reduction - (
                simulation.operational_risk * 0.50
            )
        )

        preferred = (
            simulation.status != SimulationStatus.FAILED
            and net_security_gain > 0.0
        )

        if preferred:
            explanation = (
                "The simulated security benefit outweighs the "
                "estimated operational cost under the supplied assumptions."
            )
        else:
            explanation = (
                "The proposed action does not demonstrate sufficient "
                "net security gain under the supplied assumptions."
            )

        return CounterfactualResult(
            baseline_threat=baseline_threat,
            simulated_threat=simulation.residual_threat,
            threat_reduction=threat_reduction,
            baseline_operational_risk=0.0,
            simulated_operational_risk=simulation.operational_risk,
            net_security_gain=net_security_gain,
            preferred=preferred,
            explanation=explanation,
        )


# ============================================================
# PHASE 10 ORCHESTRATOR
# ============================================================


class CyberPredictionSimulationService:
    """
    Phase-10 service boundary.

    Responsibilities:
        prediction
        simulation
        counterfactual comparison
        alternative evaluation

    It does NOT:
        execute response actions
        approve actions
        change policies
        modify production state
        call external connectors
    """

    def __init__(
        self,
        prediction_engine: Optional[PredictionEngine] = None,
        simulation_engine: Optional[SimulationEngine] = None,
        counterfactual_analyzer: Optional[CounterfactualAnalyzer] = None,
    ) -> None:

        self.prediction_engine = (
            prediction_engine or PredictionEngine()
        )

        self.simulation_engine = (
            simulation_engine or SimulationEngine()
        )

        self.counterfactual_analyzer = (
            counterfactual_analyzer
            or CounterfactualAnalyzer()
        )

    def evaluate_response(
        self,
        *,
        tenant_id: str,
        current_state: CyberState,
        action: ProposedAction,
        threat_pressure: float,
        asset_criticality: float,
        identity_privilege: float = 0.0,
        evidence: Sequence[PredictionEvidence] = (),
    ) -> Tuple[SimulationResult, CounterfactualResult]:

        simulation = self.simulation_engine.simulate(
            tenant_id=tenant_id,
            current_state=current_state,
            action=action,
            mode=SimulationMode.RESPONSE,
            threat_pressure=threat_pressure,
            asset_criticality=asset_criticality,
            identity_privilege=identity_privilege,
            evidence=evidence,
        )

        counterfactual = self.counterfactual_analyzer.analyze(
            baseline_threat=threat_pressure,
            simulation=simulation,
        )

        return simulation, counterfactual

    def compare_response_options(
        self,
        *,
        tenant_id: str,
        current_state: CyberState,
        actions: Sequence[ProposedAction],
        threat_pressure: float,
        asset_criticality: float,
        identity_privilege: float = 0.0,
        evidence: Sequence[PredictionEvidence] = (),
    ) -> Tuple[SimulationResult, ...]:

        return self.simulation_engine.compare_actions(
            tenant_id=tenant_id,
            current_state=current_state,
            actions=actions,
            threat_pressure=threat_pressure,
            asset_criticality=asset_criticality,
            identity_privilege=identity_privilege,
            evidence=evidence,
        )


# ============================================================
# PHASE 10 TESTS
# ============================================================


def _test_prediction_bounds() -> None:
    engine = PredictionEngine()

    prediction = engine.predict_threat_progression(
        tenant_id="tenant-a",
        subject_id="asset-1",
        threat_activity=1.5,
        exposure=-1.0,
        exploitability=0.8,
        privilege=0.9,
    )

    assert 0.0 <= prediction.probability <= 1.0
    assert 0.0 <= prediction.confidence <= 1.0


def _test_prediction_uses_evidence() -> None:
    engine = PredictionEngine()

    evidence = (
        PredictionEvidence(
            evidence_id="ev-1",
            source="edr",
            observation="Suspicious process execution",
            reliability=0.95,
        ),
    )

    prediction = engine.predict_threat_progression(
        tenant_id="tenant-a",
        subject_id="asset-1",
        threat_activity=0.8,
        exposure=0.8,
        exploitability=0.8,
        privilege=0.7,
        evidence=evidence,
    )

    assert prediction.evidence
    assert prediction.confidence > 0.5


def _test_simulation_does_not_mutate_state() -> None:
    state = CyberState(
        state_id="state-1",
        assets={
            "asset-1": {
                "criticality": 0.8,
                "isolated": False,
            }
        },
        identities={},
        threats={
            "threat-1": {
                "active": True,
            }
        },
    )

    original_isolated = state.assets["asset-1"]["isolated"]

    engine = SimulationEngine()

    action = ProposedAction(
        action_id="action-1",
        action_type="isolate_endpoint",
        target_id="asset-1",
    )

    result = engine.simulate(
        tenant_id="tenant-a",
        current_state=state,
        action=action,
        threat_pressure=0.8,
        asset_criticality=0.8,
    )

    assert result.status in (
        SimulationStatus.COMPLETED,
        SimulationStatus.PARTIAL,
    )

    assert state.assets["asset-1"]["isolated"] == original_isolated


def _test_unknown_action_fails_closed() -> None:
    state = CyberState(
        state_id="state-1",
        assets={},
        identities={},
        threats={},
    )

    action = ProposedAction(
        action_id="unknown-1",
        action_type="unknown_external_action",
        target_id="asset-1",
    )

    result = SimulationEngine().simulate(
        tenant_id="tenant-a",
        current_state=state,
        action=action,
    )

    assert result.status == SimulationStatus.FAILED
    assert result.operational_risk == 1.0
    assert result.recommendation_score == 0.0


def _test_action_comparison() -> None:
    state = CyberState(
        state_id="state-1",
        assets={
            "endpoint-1": {
                "criticality": 0.6,
            }
        },
        identities={},
        threats={
            "threat-1": {
                "active": True,
            }
        },
    )

    actions = (
        ProposedAction(
            action_id="a1",
            action_type="isolate_endpoint",
            target_id="endpoint-1",
        ),
        ProposedAction(
            action_id="a2",
            action_type="collect_evidence",
            target_id="endpoint-1",
        ),
        ProposedAction(
            action_id="a3",
            action_type="block_ioc",
            target_id="endpoint-1",
        ),
    )

    results = SimulationEngine().compare_actions(
        tenant_id="tenant-a",
        current_state=state,
        actions=actions,
        threat_pressure=0.8,
        asset_criticality=0.6,
    )

    assert len(results) == 3

    scores = [
        item.recommendation_score
        for item in results
    ]

    assert scores == sorted(scores, reverse=True)


def _test_counterfactual() -> None:
    state = CyberState(
        state_id="state-1",
        assets={},
        identities={},
        threats={},
    )

    action = ProposedAction(
        action_id="a1",
        action_type="block_ioc",
        target_id="ioc-1",
    )

    simulation = SimulationEngine().simulate(
        tenant_id="tenant-a",
        current_state=state,
        action=action,
        threat_pressure=0.9,
        asset_criticality=0.4,
    )

    result = CounterfactualAnalyzer().analyze(
        baseline_threat=0.9,
        simulation=simulation,
    )

    assert 0.0 <= result.threat_reduction <= 1.0
    assert 0.0 <= result.net_security_gain <= 1.0


def _test_tenant_boundary() -> None:
    state = CyberState(
        state_id="state-1",
        assets={},
        identities={},
        threats={},
    )

    action = ProposedAction(
        action_id="a1",
        action_type="collect_evidence",
        target_id="asset-1",
    )

    service = CyberPredictionSimulationService()

    simulation, _ = service.evaluate_response(
        tenant_id="tenant-a",
        current_state=state,
        action=action,
        threat_pressure=0.4,
        asset_criticality=0.4,
    )

    assert simulation.tenant_id == "tenant-a"


def _test_no_execution_boundary() -> None:
    """
    Architectural safety test:
    Phase 10 must never execute an external action.
    """

    state = CyberState(
        state_id="state-1",
        assets={
            "endpoint-1": {
                "isolated": False,
            }
        },
        identities={},
        threats={},
    )

    action = ProposedAction(
        action_id="a1",
        action_type="isolate_endpoint",
        target_id="endpoint-1",
    )

    result = SimulationEngine().simulate(
        tenant_id="tenant-a",
        current_state=state,
        action=action,
    )

    assert result is not None
    assert state.assets["endpoint-1"]["isolated"] is False


def run_phase10_tests() -> Dict[str, str]:
    tests = {
        "prediction_bounds": _test_prediction_bounds,
        "prediction_evidence": _test_prediction_uses_evidence,
        "simulation_state_isolation": _test_simulation_does_not_mutate_state,
        "unknown_action_fail_closed": _test_unknown_action_fails_closed,
        "action_comparison": _test_action_comparison,
        "counterfactual_analysis": _test_counterfactual,
        "tenant_boundary": _test_tenant_boundary,
        "no_execution_boundary": _test_no_execution_boundary,
    }

    results: Dict[str, str] = {}

    for name, test in tests.items():
        try:
            test()
            results[name] = "PASS"
        except Exception as exc:
            results[name] = f"FAIL: {exc}"

    return results
