# [dedup-fix] removed duplicate: from __future__ import annotations

import hashlib
import json
import time
import uuid
from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Callable, Iterable, Mapping, Optional, Sequence


# ----------------------------------------------------------------
# Validation result model
# ----------------------------------------------------------------

class ValidationStatus(str, Enum):
    PASS = "PASS"
    FAIL = "FAIL"
    SKIP = "SKIP"


@dataclass(frozen=True)
class ValidationResult:
    name: str
    status: ValidationStatus
    message: str = ""
    duration_ms: float = 0.0
    evidence: Mapping[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == ValidationStatus.PASS


@dataclass
class ValidationReport:
    phase: str
    results: list[ValidationResult] = field(default_factory=list)

    def add(self, result: ValidationResult) -> None:
        self.results.append(result)

    @property
    def passed(self) -> bool:
        return bool(self.results) and all(
            r.status != ValidationStatus.FAIL
            for r in self.results
        )

    @property
    def failed(self) -> list[ValidationResult]:
        return [
            r for r in self.results
            if r.status == ValidationStatus.FAIL
        ]

    def summary(self) -> dict[str, Any]:
        return {
            "phase": self.phase,
            "total": len(self.results),
            "passed": sum(
                r.status == ValidationStatus.PASS
                for r in self.results
            ),
            "failed": sum(
                r.status == ValidationStatus.FAIL
                for r in self.results
            ),
            "skipped": sum(
                r.status == ValidationStatus.SKIP
                for r in self.results
            ),
            "status": "PASS" if self.passed else "FAIL",
        }
# --- preserved from ValidationReport (merged, not present in canonical host) ---
    @staticmethod
    def build(
        suite: TestSuiteResult,
        gates: Sequence[ValidationGate],
    ) -> Dict[str, Any]:

        by_type: Dict[str, Dict[str, int]] = {}

        for test_type in TestType:
            results = [
                r
                for r in suite.results
                if r.test_type == test_type
            ]

            if not results:
                continue

            by_type[test_type.value] = {
                "total": len(results),
                "passed": sum(
                    r.status == TestStatus.PASS
                    for r in results
                ),
                "failed": sum(
                    r.status == TestStatus.FAIL
                    for r in results
                ),
                "errors": sum(
                    r.status == TestStatus.ERROR
                    for r in results
                ),
            }

        return {
            "suite_id": suite.suite_id,
            "name": suite.name,
            "started_at": suite.started_at,
            "finished_at": suite.finished_at,
            "summary": {
                "total": suite.total,
                "passed": suite.passed,
                "failed": suite.failed,
                "errors": suite.errors,
                "skipped": suite.skipped,
                "pass_rate": suite.pass_rate,
            },
            "by_type": by_type,
            "gates": [
                asdict(g)
                for g in gates
            ],
            "results": [
                asdict(r)
                for r in suite.results
            ],
        }


# ----------------------------------------------------------------
# Validation runner
# ----------------------------------------------------------------

class CyberValidationRunner:
    """
    Phase-11 validation runner.

    This layer does not implement Cyber functionality.
    It verifies existing Cyber functionality through contracts,
    invariants and adversarial test cases.
    """

    def __init__(self) -> None:
        self.report = ValidationReport(
            phase="NEXORA_CYBER_PHASE_11"
        )

    def run(
        self,
        name: str,
        check: Callable[[], Any],
    ) -> ValidationResult:

        started = time.perf_counter()

        try:
            result = check()

            duration_ms = (
                time.perf_counter() - started
            ) * 1000

            if result is False:
                validation = ValidationResult(
                    name=name,
                    status=ValidationStatus.FAIL,
                    message="Validation returned False.",
                    duration_ms=duration_ms,
                )
            else:
                validation = ValidationResult(
                    name=name,
                    status=ValidationStatus.PASS,
                    message="Validation passed.",
                    duration_ms=duration_ms,
                    evidence=(
                        result
                        if isinstance(result, Mapping)
                        else {}
                    ),
                )

        except Exception as exc:
            duration_ms = (
                time.perf_counter() - started
            ) * 1000

            validation = ValidationResult(
                name=name,
                status=ValidationStatus.FAIL,
                message=f"{type(exc).__name__}: {exc}",
                duration_ms=duration_ms,
            )

        self.report.add(validation)
        return validation

    def skip(
        self,
        name: str,
        reason: str,
    ) -> ValidationResult:

        result = ValidationResult(
            name=name,
            status=ValidationStatus.SKIP,
            message=reason,
        )

        self.report.add(result)
        return result


