# ----------------------------------------------------------------
# Tenant-isolation validation
# ----------------------------------------------------------------

class TenantIsolationValidator:

    def __init__(self, service: Any) -> None:
        self.service = service

    def validate_cross_tenant_denial(
        self,
        tenant_a: str,
        tenant_b: str,
    ) -> dict[str, Any]:

        if tenant_a == tenant_b:
            raise ValueError(
                "Tenant identifiers must differ."
            )

        # Supported service interfaces are intentionally detected
        # rather than invented.
        query = getattr(
            self.service,
            "query",
            None,
        )

        if query is None:
            raise RuntimeError(
                "Validation target does not expose query()."
            )

        try:
            result = query(
                tenant_id=tenant_b,
                actor_tenant_id=tenant_a,
            )
        except (PermissionError, ValueError):
            return {
                "cross_tenant_access": False,
                "expected": "DENIED",
            }

        if result:
            raise AssertionError(
                "Cross-tenant data was returned."
            )

        return {
            "cross_tenant_access": False,
            "expected": "DENIED",
        }


# ----------------------------------------------------------------
# Provenance validation
# ----------------------------------------------------------------

class ProvenanceValidator:

    REQUIRED = (
        "source",
        "source_event_id",
        "observed_at",
    )

    @classmethod
    def validate(
        cls,
        record: Mapping[str, Any],
    ) -> dict[str, Any]:

        missing = [
            field
            for field in cls.REQUIRED
            if not record.get(field)
        ]

        if missing:
            raise AssertionError(
                f"Provenance missing: {missing}"
            )

        return {
            "provenance_complete": True,
            "fields": list(cls.REQUIRED),
        }


# ----------------------------------------------------------------
# Evidence integrity validation
# ----------------------------------------------------------------

class EvidenceIntegrityValidator:

    @staticmethod
    def canonical_hash(
        evidence: Mapping[str, Any],
    ) -> str:

        canonical = json.dumps(
            evidence,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        )

        return hashlib.sha256(
            canonical.encode("utf-8")
        ).hexdigest()

    @classmethod
    def validate(
        cls,
        evidence: Mapping[str, Any],
        expected_hash: Optional[str] = None,
    ) -> dict[str, Any]:

        digest = cls.canonical_hash(evidence)

        if expected_hash is not None:
            if digest != expected_hash:
                raise AssertionError(
                    "Evidence integrity hash mismatch."
                )

        return {
            "sha256": digest,
            "integrity": True,
        }


# ----------------------------------------------------------------
# Replay safety validation
# ----------------------------------------------------------------

class ReplaySafetyValidator:

    FORBIDDEN_REAL_EXECUTION_NAMES = {
        "execute",
        "act",
        "delete",
        "disable",
        "isolate",
        "block",
        "revoke",
        "rotate",
    }

    @classmethod
    def validate_replay_target(
        cls,
        target: Any,
    ) -> dict[str, Any]:

        mode = getattr(
            target,
            "mode",
            None,
        )

        if mode is not None:
            normalized = str(mode).lower()

            if normalized not in {
                "replay",
                "simulation",
                "dry_run",
                "test",
            }:
                raise AssertionError(
                    "Replay target is not operating in a "
                    "non-destructive mode."
                )

        return {
            "non_destructive": True,
        }


# ----------------------------------------------------------------
# AI evidence discipline validation
# ----------------------------------------------------------------

class EvidenceDisciplineValidator:

    VERIFIED_STATES = {
        "VERIFIED",
        "PARTIALLY_VERIFIED",
        "DISPROVEN",
        "UNVERIFIED",
    }

    @classmethod
    def validate_hypothesis(
        cls,
        hypothesis: Mapping[str, Any],
    ) -> dict[str, Any]:

        state = str(
            hypothesis.get(
                "verification_status",
                "",
            )
        ).upper()

        if state not in cls.VERIFIED_STATES:
            raise AssertionError(
                f"Invalid verification state: {state}"
            )

        evidence = hypothesis.get(
            "evidence",
            [],
        )

        if state == "VERIFIED" and not evidence:
            raise AssertionError(
                "A VERIFIED hypothesis must contain evidence."
            )

        return {
            "verification_status": state,
            "evidence_count": len(evidence),
        }


# ----------------------------------------------------------------
# Confidence-boundary validation
# ----------------------------------------------------------------

class ConfidenceValidator:

    @staticmethod
    def validate(value: Any) -> dict[str, Any]:

        confidence = float(value)

        if not 0.0 <= confidence <= 1.0:
            raise AssertionError(
                f"Confidence outside [0,1]: {confidence}"
            )

        return {
            "confidence": confidence,
            "bounded": True,
        }


# ----------------------------------------------------------------
# Secret-leak validation
# ----------------------------------------------------------------

class SecretLeakValidator:

    SECRET_KEYS = {
        "password",
        "secret",
        "api_key",
        "access_token",
        "refresh_token",
        "private_key",
        "client_secret",
    }

    @classmethod
    def scan(
        cls,
        value: Any,
    ) -> dict[str, Any]:

        serialized = json.dumps(
            value,
            default=str,
        ).lower()

        exposed = [
            key
            for key in cls.SECRET_KEYS
            if f'"{key}"' in serialized
        ]

        # Presence of a key alone is not automatically leakage.
        # The validator specifically rejects obvious raw values.
        for key in exposed:
            marker = f'"{key}"'
            index = serialized.find(marker)

            fragment = serialized[
                index:index + 300
            ]

            if '""' not in fragment and "null" not in fragment:
                raise AssertionError(
                    f"Potential secret exposure detected: {key}"
                )

        return {
            "secret_leak_detected": False,
        }


# ----------------------------------------------------------------
# Untrusted telemetry validation
# ----------------------------------------------------------------

class UntrustedInputValidator:

    @staticmethod
    def validate(
        payload: Mapping[str, Any],
    ) -> dict[str, Any]:

        # External telemetry must remain data.
        # It must never be interpreted as executable instructions.
        for key, value in payload.items():

            if not isinstance(
                key,
                str,
            ):
                raise AssertionError(
                    "Telemetry field name is not a string."
                )

            if callable(value):
                raise AssertionError(
                    "Callable object found in telemetry."
                )

        return {
            "trusted_as_code": False,
            "payload_fields": len(payload),
        }


# ----------------------------------------------------------------
# Audit-chain validation
# ----------------------------------------------------------------

class AuditChainValidator:

    @staticmethod
    def compute_hash(
        record: Mapping[str, Any],
    ) -> str:

        canonical = json.dumps(
            record,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        )

        return hashlib.sha256(
            canonical.encode("utf-8")
        ).hexdigest()

    @classmethod
    def validate_chain(
        cls,
        records: Sequence[Mapping[str, Any]],
    ) -> dict[str, Any]:

        previous = ""

        for index, record in enumerate(records):

            recorded_previous = record.get(
                "previous_hash",
                "",
            )

            if recorded_previous != previous:
                raise AssertionError(
                    f"Audit chain broken at index {index}."
                )

            payload = dict(record)
            payload.pop(
                "current_hash",
                None,
            )

            current = cls.compute_hash(payload)

            if record.get("current_hash") != current:
                raise AssertionError(
                    f"Audit hash mismatch at index {index}."
                )

            previous = current

        return {
            "chain_valid": True,
            "records": len(records),
        }


# ----------------------------------------------------------------
# Idempotency validation
# ----------------------------------------------------------------

class IdempotencyValidator:

    @staticmethod
    def validate(
        processor: Callable[[str], Any],
        event_id: str,
    ) -> dict[str, Any]:

        first = processor(event_id)
        second = processor(event_id)

        if first != second:
            raise AssertionError(
                "Repeated processing produced "
                "different results."
            )

        return {
            "idempotent": True,
            "event_id": event_id,
        }


# ----------------------------------------------------------------
# Phase-11 validation suite
# ----------------------------------------------------------------

class CyberPhase11ValidationSuite:
    # [auto-repair] _check_contracts() below referenced self.CONTRACTS,
    # which was never defined anywhere on this class. Mirrors the same
    # contract-name list already used in validate_core_contracts() below.
    CONTRACTS: ClassVar[tuple[str, ...]] = (
        "CyberContext",
        "CyberEntity",
        "CyberEvent",
        "CyberEvidence",
        "CyberFinding",
        "CyberIncident",
        "CyberRisk",
        "CyberDecision",
        "CyberAction",
        "CyberApproval",
        "CyberExecution",
        "CyberVerification",
        "CyberMemory",
        "CyberAgent",
        "CyberPolicy",
        "CyberAuditRecord",
    )

    def __init__(
        self,
        *,
        cyber_services: Optional[Mapping[str, Any]] = None,
    ) -> None:

        self.services = dict(
            cyber_services or {}
        )

        self.runner = CyberValidationRunner()

    # ------------------------------------------------------------
    # Core contract validation
    # ------------------------------------------------------------

    def validate_core_contracts(self) -> None:

        contracts = (
            "CyberContext",
            "CyberEntity",
            "CyberEvent",
            "CyberEvidence",
            "CyberFinding",
            "CyberIncident",
            "CyberRisk",
            "CyberDecision",
            "CyberAction",
            "CyberApproval",
            "CyberExecution",
            "CyberVerification",
            "CyberMemory",
            "CyberAgent",
            "CyberPolicy",
            "CyberAuditRecord",
        )

        registry = self.services.get(
            "contracts"
        )

        if registry is None:
            self.runner.skip(
                "cyber_core_contracts",
                "No contract registry supplied.",
            )
            return

        def check():
            missing = [
                name
                for name in contracts
                if name not in registry
            ]

            if missing:
                raise AssertionError(
                    f"Missing Cyber contracts: {missing}"
                )

            return {
                "contracts": len(contracts),
                "missing": [],
            }

        self.runner.run(
            "cyber_core_contracts",
            check,
        )

    # ------------------------------------------------------------
    # Tenant isolation
    # ------------------------------------------------------------

    def validate_tenant_isolation(self) -> None:

        service = self.services.get(
            "tenant_scoped_store"
        )

        if service is None:
            self.runner.skip(
                "tenant_isolation",
                "No tenant-scoped store supplied.",
            )
            return

        validator = TenantIsolationValidator(
            service
        )

        self.runner.run(
            "tenant_isolation",
            lambda: validator.validate_cross_tenant_denial(
                "tenant-A",
                "tenant-B",
            ),
        )

    # ------------------------------------------------------------
    # Provenance
    # ------------------------------------------------------------

    def validate_provenance(
        self,
        records: Iterable[Mapping[str, Any]],
    ) -> None:

        for index, record in enumerate(records):

            self.runner.run(
                f"provenance_record_{index}",
                lambda record=record:
                    ProvenanceValidator.validate(
                        record
                    ),
            )

    # ------------------------------------------------------------
    # Evidence
    # ------------------------------------------------------------

    def validate_evidence(
        self,
        evidence: Mapping[str, Any],
    ) -> None:

        self.runner.run(
            "evidence_integrity",
            lambda: EvidenceIntegrityValidator.validate(
                evidence
            ),
        )

    # ------------------------------------------------------------
    # Replay
    # ------------------------------------------------------------

    def validate_replay(
        self,
        replay_target: Any,
    ) -> None:

        self.runner.run(
            "replay_non_destructive",
            lambda: ReplaySafetyValidator.validate_replay_target(
                replay_target
            ),
        )

    # ------------------------------------------------------------
    # Hypothesis verification
    # ------------------------------------------------------------

    def validate_reasoning(
        self,
        hypotheses: Iterable[Mapping[str, Any]],
    ) -> None:

        for index, hypothesis in enumerate(hypotheses):

            self.runner.run(
                f"hypothesis_{index}",
                lambda hypothesis=hypothesis:
                    EvidenceDisciplineValidator.validate_hypothesis(
                        hypothesis
                    ),
            )

    # ------------------------------------------------------------
    # Confidence
    # ------------------------------------------------------------

    def validate_confidence(
        self,
        values: Iterable[Any],
    ) -> None:

        for index, value in enumerate(values):

            self.runner.run(
                f"confidence_{index}",
                lambda value=value:
                    ConfidenceValidator.validate(
                        value
                    ),
            )

    # ------------------------------------------------------------
    # External input
    # ------------------------------------------------------------

    def validate_external_input(
        self,
        payload: Mapping[str, Any],
    ) -> None:

        self.runner.run(
            "untrusted_telemetry",
            lambda: UntrustedInputValidator.validate(
                payload
            ),
        )

    # ------------------------------------------------------------
    # Audit chain
    # ------------------------------------------------------------

    def validate_audit_chain(
        self,
        records: Sequence[Mapping[str, Any]],
    ) -> None:

        self.runner.run(
            "audit_chain",
            lambda: AuditChainValidator.validate_chain(
                records
            ),
        )

    # ------------------------------------------------------------
    # Idempotency
    # ------------------------------------------------------------

    def validate_idempotency(
        self,
        processor: Callable[[str], Any],
    ) -> None:

        self.runner.run(
            "event_idempotency",
            lambda: IdempotencyValidator.validate(
                processor,
                f"validation-{uuid.uuid4().hex}",
            ),
        )

    # ------------------------------------------------------------
    # Secret exposure
    # ------------------------------------------------------------

    def validate_secret_boundary(
        self,
        payload: Any,
    ) -> None:

        self.runner.run(
            "secret_leak_detection",
            lambda: SecretLeakValidator.scan(
                payload
            ),
        )

    # ------------------------------------------------------------
    # Final execution
    # ------------------------------------------------------------

    def run_all(
        self,
        *,
        provenance_records: Optional[
            Iterable[Mapping[str, Any]]
        ] = None,
        evidence: Optional[
            Mapping[str, Any]
        ] = None,
        hypotheses: Optional[
            Iterable[Mapping[str, Any]]
        ] = None,
        confidence_values: Optional[
            Iterable[Any]
        ] = None,
        external_payload: Optional[
            Mapping[str, Any]
        ] = None,
        audit_records: Optional[
            Sequence[Mapping[str, Any]]
        ] = None,
        replay_target: Any = None,
        idempotency_processor: Optional[
            Callable[[str], Any]
        ] = None,
        secret_payload: Any = None,
    ) -> ValidationReport:

        self.validate_core_contracts()
        self.validate_tenant_isolation()

        if provenance_records is not None:
            self.validate_provenance(
                provenance_records
            )

        if evidence is not None:
            self.validate_evidence(
                evidence
            )

        if hypotheses is not None:
            self.validate_reasoning(
                hypotheses
            )

        if confidence_values is not None:
            self.validate_confidence(
                confidence_values
            )

        if external_payload is not None:
            self.validate_external_input(
                external_payload
            )

        if audit_records is not None:
            self.validate_audit_chain(
                audit_records
            )

        if replay_target is not None:
            self.validate_replay(
                replay_target
            )

        if idempotency_processor is not None:
            self.validate_idempotency(
                idempotency_processor
            )

        if secret_payload is not None:
            self.validate_secret_boundary(
                secret_payload
            )

        return self.runner.report
    # --- preserved from CyberPhase11ValidationSuite (merged, not present in canonical host) ---
    def _check_contracts(
        self,
        registry: Any,
    ) -> dict[str, Any]:

        missing = [
            name
            for name in self.CONTRACTS
            if name not in registry
        ]

        if missing:

            raise AssertionError(
                f"Missing Cyber contracts: {missing}"
            )

        return {
            "contracts": len(
                self.CONTRACTS
            ),
            "missing": [],
        }
