# ================================================================
# PHASE 12 TESTS
# ================================================================

def test_agent_identity() -> None:

    agent = StandardCyberAgents.detection(
        "tenant-A"
    )

    assert agent.audit_identity.agent_id
    assert (
        agent.audit_identity.agent_type
        == AgentType.DETECTION
    )

    assert (
        agent.tenant.tenant_id
        == "tenant-A"
    )


def test_tenant_context_isolation() -> None:

    first = StandardCyberAgents.detection(
        "tenant-A"
    )

    second = StandardCyberAgents.detection(
        "tenant-B"
    )

    assert (
        first.tenant.tenant_id
        != second.tenant.tenant_id
    )


def test_capability_boundary() -> None:

    agent = StandardCyberAgents.detection(
        "tenant-A"
    )

    agent.require_capability(
        Capability.READ_EVENTS
    )

    try:
        agent.require_capability(
            Capability.EXECUTE_ACTION
        )
    except PermissionError:
        return

    raise AssertionError(
        "Detection agent received execution capability."
    )


def test_execution_agent_limit() -> None:

    agent = StandardCyberAgents.execution(
        "tenant-A"
    )

    agent.authorize_action(
        risk_level=RiskLevel.LOW
    )

    agent.record_action()

    try:
        agent.authorize_action(
            risk_level=RiskLevel.LOW
        )
    except PermissionError:
        return

    raise AssertionError(
        "Execution action limit was bypassed."
    )


def test_read_only_agent_cannot_execute() -> None:

    agent = StandardCyberAgents.investigation(
        "tenant-A"
    )

    try:
        agent.require_capability(
            Capability.EXECUTE_ACTION
        )
    except PermissionError:
        return

    raise AssertionError(
        "Investigation agent gained execution capability."
    )


def test_high_risk_boundary() -> None:

    agent = StandardCyberAgents.execution(
        "tenant-A"
    )

    try:
        agent.authorize_action(
            risk_level=RiskLevel.HIGH
        )
    except PermissionError:
        return

    raise AssertionError(
        "Agent exceeded configured risk boundary."
    )


def test_disabled_agent_cannot_use_tools() -> None:

    agent = StandardCyberAgents.detection(
        "tenant-A"
    )

    tool = AgentTool(
        name="event_reader",
        description="Test event reader",
        capabilities=frozenset({
            Capability.READ_EVENTS,
        }),
        handler=lambda **_: {"ok": True},
    )

    agent.register_tool(tool)
    agent.state = AgentState.DISABLED

    try:
        agent.get_tool("event_reader")
    except PermissionError:
        return

    raise AssertionError(
        "Disabled agent accessed a tool."
    )


def test_tool_capability_enforcement() -> None:

    agent = StandardCyberAgents.detection(
        "tenant-A"
    )

    tool = AgentTool(
        name="execution_tool",
        description="Execution test tool",
        capabilities=frozenset({
            Capability.EXECUTE_ACTION,
        }),
        handler=lambda **_: {"executed": True},
    )

    agent.register_tool(tool)

    try:
        tool.invoke(
            agent=agent,
            arguments={},
        )
    except PermissionError:
        return

    raise AssertionError(
        "Agent invoked unauthorized tool."
    )


def test_registry_tenant_filtering() -> None:

    registry = CyberAgentRegistry()

    a = StandardCyberAgents.detection(
        "tenant-A"
    )

    b = StandardCyberAgents.investigation(
        "tenant-B"
    )

    registry.register(a)
    registry.register(b)

    tenant_a_agents = registry.for_tenant(
        "tenant-A"
    )

    assert len(tenant_a_agents) == 1
    assert (
        tenant_a_agents[0].tenant.tenant_id
        == "tenant-A"
    )


def test_audit_context() -> None:

    agent = StandardCyberAgents.supervisor(
        "tenant-A"
    )

    context = agent.audit_context()

    assert (
        context["tenant_id"]
        == "tenant-A"
    )

    assert (
        context["agent"]["agent_id"]
        == agent.audit_identity.agent_id
    )


# ================================================================
# Test Runner
# ================================================================

def run_phase_12_tests() -> dict[str, Any]:

    tests = [
        test_agent_identity,
        test_tenant_context_isolation,
        test_capability_boundary,
        test_execution_agent_limit,
        test_read_only_agent_cannot_execute,
        test_high_risk_boundary,
        test_disabled_agent_cannot_use_tools,
        test_tool_capability_enforcement,
        test_registry_tenant_filtering,
        test_audit_context,
    ]

    passed = 0
    failed: list[dict[str, str]] = []

    for test in tests:

        try:
            test()
            passed += 1

        except Exception as exc:
            failed.append({
                "test": test.__name__,
                "error": str(exc),
            })

    return {
        "phase": "12",
        "component": "Cyber Agent System",
        "tests": len(tests),
        "passed": passed,
        "failed": len(failed),
        "failures": failed,
        "status": (
            "PASS"
            if not failed
            else "FAIL"
        ),
    }


