# [dedup-fix] removed duplicate: from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Callable, Mapping, Optional
from uuid import uuid4


# ================================================================
# Lifecycle States
# ================================================================

class LifecycleStage(str, Enum):
    OBSERVE = "observe"
    DETECT = "detect"
    CORRELATE = "correlate"
    INVESTIGATE = "investigate"
    REASON = "reason"
    RISK_ASSESS = "risk_assess"
    PREDICT = "predict"
    SIMULATE = "simulate"
    PLAN = "plan"
    GOVERN = "govern"
    APPROVE = "approve"
    EXECUTE = "execute"
    VERIFY = "verify"
    LEARN = "learn"
    UPDATE_POSTURE = "update_posture"


class LifecycleStatus(str, Enum):
    CREATED = "created"
    RUNNING = "running"
    WAITING = "waiting"
    COMPLETED = "completed"
    FAILED = "failed"
    STOPPED = "stopped"


# ================================================================
# Lifecycle Events
# ================================================================

@dataclass(frozen=True)
class LifecycleEvent:
    run_id: str
    stage: LifecycleStage
    event_type: str
    timestamp: float
    payload: Mapping[str, Any] = field(
        default_factory=dict
    )


# ================================================================
# Lifecycle Context
# ================================================================

@dataclass
class CyberLifecycleContext:
    run_id: str
    tenant_id: str
    input_data: Mapping[str, Any]

    data: dict[str, Any] = field(
        default_factory=dict
    )

    history: list[LifecycleEvent] = field(
        default_factory=list
    )

    current_stage: Optional[LifecycleStage] = None
    status: LifecycleStatus = LifecycleStatus.CREATED

    stop_requested: bool = False

    def record(
        self,
        stage: LifecycleStage,
        event_type: str,
        timestamp: float,
        payload: Optional[Mapping[str, Any]] = None,
    ) -> None:

        self.history.append(
            LifecycleEvent(
                run_id=self.run_id,
                stage=stage,
                event_type=event_type,
                timestamp=timestamp,
                payload=dict(payload or {}),
            )
        )


# ================================================================
# Stage Adapter
# ================================================================

@dataclass(frozen=True)
class LifecycleStageAdapter:
    """
    Thin adapter around an existing Cyber capability.

    Phase 13 orchestrates capabilities.
    It does not implement those capabilities.
    """

    stage: LifecycleStage
    handler: Callable[
        [CyberLifecycleContext],
        Mapping[str, Any] | None
    ]

    def execute(
        self,
        context: CyberLifecycleContext,
    ) -> Mapping[str, Any]:

        result = self.handler(context)

        if result is None:
            return {}

        if not isinstance(result, Mapping):
            raise TypeError(
                f"{self.stage.value} handler must return Mapping."
            )

        return dict(result)


# ================================================================
# Lifecycle Transition Model
# ================================================================

@dataclass(frozen=True)
class LifecycleTransition:
    source: LifecycleStage
    target: LifecycleStage


class LifecycleTransitionError(RuntimeError):
    pass


class LifecycleExecutionError(RuntimeError):
    pass


# ================================================================
# Canonical Lifecycle Graph
# ================================================================

class CyberLifecycleGraph:

    ORDER = (
        LifecycleStage.OBSERVE,
        LifecycleStage.DETECT,
        LifecycleStage.CORRELATE,
        LifecycleStage.INVESTIGATE,
        LifecycleStage.REASON,
        LifecycleStage.RISK_ASSESS,
        LifecycleStage.PREDICT,
        LifecycleStage.SIMULATE,
        LifecycleStage.PLAN,
        LifecycleStage.GOVERN,
        LifecycleStage.APPROVE,
        LifecycleStage.EXECUTE,
        LifecycleStage.VERIFY,
        LifecycleStage.LEARN,
        LifecycleStage.UPDATE_POSTURE,
    )

    @classmethod
    def transitions(cls) -> frozenset[LifecycleTransition]:

        return frozenset(
            LifecycleTransition(
                source=cls.ORDER[index],
                target=cls.ORDER[index + 1],
            )
            for index in range(
                len(cls.ORDER) - 1
            )
        )

    @classmethod
    def next_stage(
        cls,
        current: LifecycleStage,
    ) -> Optional[LifecycleStage]:

        try:
            index = cls.ORDER.index(current)
        except ValueError:
            raise LifecycleTransitionError(
                f"Unknown lifecycle stage: {current}"
            ) from None

        if index + 1 >= len(cls.ORDER):
            return None

        return cls.ORDER[index + 1]

    @classmethod
    def can_transition(
        cls,
        source: LifecycleStage,
        target: LifecycleStage,
    ) -> bool:

        return LifecycleTransition(
            source=source,
            target=target,
        ) in cls.transitions()


# ================================================================
# Lifecycle Policy
# ================================================================

@dataclass(frozen=True)
class LifecyclePolicy:
    """
    Orchestration-level safety controls.

    This is not the Cyber Governance engine.
    """

    max_stage_executions: int = 1
    stop_on_stage_failure: bool = True
    require_explicit_stage_handlers: bool = True
    allow_execution_without_adapter: bool = False

    def __post_init__(self) -> None:

        if self.max_stage_executions < 1:
            raise ValueError(
                "max_stage_executions must be >= 1."
            )


# ================================================================
# Lifecycle Audit Sink
# ================================================================

class LifecycleAuditSink:

    def __init__(self) -> None:
        self.events: list[LifecycleEvent] = []

    def append(
        self,
        event: LifecycleEvent,
    ) -> None:

        self.events.append(event)

    def snapshot(self) -> tuple[LifecycleEvent, ...]:
        return tuple(self.events)


# ================================================================
# Autonomous Lifecycle Orchestrator
# ================================================================

class CyberAutonomousLifecycle:

    def __init__(
        self,
        *,
        adapters: Mapping[
            LifecycleStage,
            LifecycleStageAdapter
        ],
        policy: Optional[LifecyclePolicy] = None,
        audit_sink: Optional[LifecycleAuditSink] = None,
        clock: Optional[Callable[[], float]] = None,
    ) -> None:

        self.adapters = dict(adapters)

        self.policy = (
            policy
            or LifecyclePolicy()
        )

        self.audit_sink = (
            audit_sink
            or LifecycleAuditSink()
        )

        self.clock = clock

    # ------------------------------------------------------------
    # Time
    # ------------------------------------------------------------

    def _now(self) -> float:

        if self.clock is not None:
            return float(self.clock())

        import time

        return time.time()

    # ------------------------------------------------------------
    # Event recording
    # ------------------------------------------------------------

    def _record(
        self,
        context: CyberLifecycleContext,
        stage: LifecycleStage,
        event_type: str,
        payload: Optional[Mapping[str, Any]] = None,
    ) -> None:

        event = LifecycleEvent(
            run_id=context.run_id,
            stage=stage,
            event_type=event_type,
            timestamp=self._now(),
            payload=dict(payload or {}),
        )

        context.history.append(event)
        self.audit_sink.append(event)

    # ------------------------------------------------------------
    # Context creation
    # ------------------------------------------------------------

    def create_context(
        self,
        *,
        tenant_id: str,
        input_data: Mapping[str, Any],
    ) -> CyberLifecycleContext:

        if not tenant_id.strip():
            raise ValueError(
                "tenant_id is required."
            )

        return CyberLifecycleContext(
            run_id=f"run_{uuid4().hex}",
            tenant_id=tenant_id,
            input_data=dict(input_data),
        )

    # ------------------------------------------------------------
    # Stage validation
    # ------------------------------------------------------------

    def _validate_stage(
        self,
        stage: LifecycleStage,
    ) -> LifecycleStageAdapter:

        adapter = self.adapters.get(stage)

        if adapter is None:

            if self.policy.require_explicit_stage_handlers:
                raise LifecycleExecutionError(
                    f"No handler registered for "
                    f"stage '{stage.value}'."
                )

            raise LifecycleExecutionError(
                f"Stage '{stage.value}' cannot execute."
            )

        if adapter.stage != stage:
            raise LifecycleExecutionError(
                "Stage adapter identity mismatch."
            )

        return adapter

    # ------------------------------------------------------------
    # Stage execution
    # ------------------------------------------------------------

    def execute_stage(
        self,
        context: CyberLifecycleContext,
        stage: LifecycleStage,
    ) -> Mapping[str, Any]:

        if context.stop_requested:
            context.status = LifecycleStatus.STOPPED

            self._record(
                context,
                stage,
                "stage_skipped_stop_requested",
            )

            return {}

        adapter = self._validate_stage(stage)

        previous = context.current_stage

        if previous is not None:

            if not CyberLifecycleGraph.can_transition(
                previous,
                stage,
            ):
                raise LifecycleTransitionError(
                    f"Illegal lifecycle transition: "
                    f"{previous.value} -> {stage.value}"
                )

        context.current_stage = stage
        context.status = LifecycleStatus.RUNNING

        self._record(
            context,
            stage,
            "stage_started",
        )

        try:

            result = adapter.execute(context)

            context.data[stage.value] = result

            self._record(
                context,
                stage,
                "stage_completed",
                result,
            )

            return result

        except Exception as exc:

            context.status = LifecycleStatus.FAILED

            self._record(
                context,
                stage,
                "stage_failed",
                {
                    "error_type": type(exc).__name__,
                    "error": str(exc),
                },
            )

            if self.policy.stop_on_stage_failure:
                context.stop_requested = True

            raise LifecycleExecutionError(
                f"Lifecycle stage '{stage.value}' failed."
            ) from exc

    # ------------------------------------------------------------
    # Full lifecycle
    # ------------------------------------------------------------

    def run(
        self,
        context: CyberLifecycleContext,
    ) -> CyberLifecycleContext:

        context.status = LifecycleStatus.RUNNING

        current: Optional[LifecycleStage] = None

        try:

            for stage in CyberLifecycleGraph.ORDER:

                if context.stop_requested:
                    break

                if current is not None:
                    if not CyberLifecycleGraph.can_transition(
                        current,
                        stage,
                    ):
                        raise LifecycleTransitionError(
                            f"Invalid transition "
                            f"{current.value} -> {stage.value}"
                        )

                self.execute_stage(
                    context,
                    stage,
                )

                current = stage

            if context.stop_requested:
                context.status = LifecycleStatus.STOPPED

            else:
                context.status = LifecycleStatus.COMPLETED

                if (
                    context.current_stage
                    != LifecycleStage.UPDATE_POSTURE
                ):
                    raise LifecycleExecutionError(
                        "Lifecycle ended before final stage."
                    )

            return context

        except Exception:

            if context.status != LifecycleStatus.FAILED:
                context.status = LifecycleStatus.FAILED

            raise

    # ------------------------------------------------------------
    # Controlled stop
    # ------------------------------------------------------------

    def request_stop(
        self,
        context: CyberLifecycleContext,
        reason: str = "",
    ) -> None:

        context.stop_requested = True

        self._record(
            context,
            context.current_stage
            or LifecycleStage.OBSERVE,
            "stop_requested",
            {
                "reason": reason,
            },
        )
    # --- preserved from CyberAutonomousLifecycle (merged, not present in canonical host) ---
    @staticmethod
    def can_transition(
        source: LifecycleStage,
        target: LifecycleStage,
    ) -> bool:

        return (
            CyberLifecycleGraph
            .can_transition(
                source,
                target,
            )
        )


# ================================================================
# Lifecycle Builder
# ================================================================

class CyberLifecycleBuilder:

    def __init__(self) -> None:
        self._adapters: dict[
            LifecycleStage,
            LifecycleStageAdapter
        ] = {}

    def register(
        self,
        stage: LifecycleStage,
        handler: Callable[
            [CyberLifecycleContext],
            Mapping[str, Any] | None
        ],
    ) -> "CyberLifecycleBuilder":

        if stage in self._adapters:
            raise ValueError(
                f"Handler already registered for "
                f"'{stage.value}'."
            )

        self._adapters[stage] = (
            LifecycleStageAdapter(
                stage=stage,
                handler=handler,
            )
        )

        return self

    def build(
        self,
        *,
        policy: Optional[LifecyclePolicy] = None,
        audit_sink: Optional[LifecycleAuditSink] = None,
    ) -> CyberAutonomousLifecycle:

        return CyberAutonomousLifecycle(
            adapters=self._adapters,
            policy=policy,
            audit_sink=audit_sink,
        )


