def run_phase_13_tests() -> dict[str, Any]:

    tests = [
        test_canonical_lifecycle_has_all_stages,
        test_transition_graph_is_linear,
        test_invalid_transition_rejected,
        test_context_has_unique_run_id,
        test_full_lifecycle_execution,
        test_stage_order_preserved,
        test_missing_stage_handler_fails,
        test_stage_failure_stops_lifecycle,
        test_stop_request_prevents_following_stages,
        test_tenant_context_preserved,
        test_audit_events_have_run_identity,
        test_no_implicit_stage_execution,
    ]

    passed = 0
    failures: list[dict[str, str]] = []

    for test in tests:

        try:
            test()
            passed += 1

        except Exception as exc:
            failures.append({
                "test": test.__name__,
                "error": f"{type(exc).__name__}: {exc}",
            })

    return {
        "phase": 13,
        "component": (
            "Autonomous Cyber Lifecycle"
        ),
        "total_tests": len(tests),
        "passed": passed,
        "failed": len(failures),
        "failures": failures,
        "status": (
            "PASS"
            if not failures
            else "FAIL"
        ),
    }


