@dataclass
class CyberApproval:
    approval_id: str
    request_id: str
    tenant_id: str

    required: bool
    status: ApprovalStatus

    required_approvers: frozenset[str] = frozenset()

    approved_by: list[str] = field(
        default_factory=list
    )

    rejected_by: Optional[str] = None
    rejection_reason: Optional[str] = None

    expires_at: Optional[float] = None

    metadata: dict[str, Any] = field(
        default_factory=dict
    )

    def is_expired(
        self,
        now: float,
    ) -> bool:

        if (
            self.expires_at is not None
            and now >= self.expires_at
        ):
            self.status = ApprovalStatus.EXPIRED
            return True

        return False

    def approve(
        self,
        approver_id: str,
        now: float,
    ) -> None:

        if not approver_id.strip():
            raise ValueError(
                "approver_id is required."
            )

        if self.is_expired(now):
            raise PermissionError(
                "Approval has expired."
            )

        if self.status != ApprovalStatus.PENDING:
            raise PermissionError(
                f"Approval cannot be approved from "
                f"state '{self.status.value}'."
            )

        if (
            self.required_approvers
            and approver_id not in self.required_approvers
        ):
            raise PermissionError(
                "Approver is not authorized for this request."
            )

        if approver_id not in self.approved_by:
            self.approved_by.append(
                approver_id
            )

        if (
            not self.required_approvers
            or self.required_approvers.issubset(
                self.approved_by
            )
        ):
            self.status = ApprovalStatus.APPROVED

    def reject(
        self,
        approver_id: str,
        reason: str,
        now: float,
    ) -> None:

        if self.is_expired(now):
            raise PermissionError(
                "Approval has expired."
            )

        if self.status != ApprovalStatus.PENDING:
            raise PermissionError(
                f"Approval cannot be rejected from "
                f"state '{self.status.value}'."
            )

        if (
            self.required_approvers
            and approver_id not in self.required_approvers
        ):
            raise PermissionError(
                "Approver is not authorized."
            )

        self.status = ApprovalStatus.REJECTED
        self.rejected_by = approver_id
        self.rejection_reason = reason
# [auto-repair] removed normalize_approval_times()/validate_approval_state()
    # -- merge artifacts referencing requested_at/decided_at/approver_id,
