# ================================================================
# POLICY STORE
# ================================================================

class CyberPolicyStore:

    def __init__(self) -> None:
        self._policies: dict[str, CyberPolicy] = {}

    def add(
        self,
        policy: CyberPolicy,
    ) -> None:

        if policy.policy_id in self._policies:
            raise ValueError(
                f"Policy already exists: {policy.policy_id}"
            )

        self._policies[policy.policy_id] = policy

    def update(
        self,
        policy: CyberPolicy,
    ) -> None:

        if policy.policy_id not in self._policies:
            raise KeyError(
                f"Unknown policy: {policy.policy_id}"
            )

        self._policies[policy.policy_id] = policy

    def get(
        self,
        policy_id: str,
    ) -> CyberPolicy:

        return self._policies[policy_id]

    def active_for_tenant(
        self,
        tenant_id: str,
    ) -> list[CyberPolicy]:

        policies = [
            policy
            for policy in self._policies.values()
            if policy.enabled
            and (
                policy.subject.tenant_id is None
                or policy.subject.tenant_id == tenant_id
            )
        ]

        return sorted(
            policies,
            key=lambda policy: policy.priority,
        )


