class CyberApprovalStore:

    def __init__(self) -> None:
        self._approvals: dict[str, CyberApproval] = {}

    def create(
        self,
        *,
        request_id: str,
        tenant_id: str,
        required_approvers: Sequence[str] = (),
        expires_at: Optional[float] = None,
    ) -> CyberApproval:

        approval = CyberApproval(
            approval_id=f"approval_{uuid4().hex}",
            request_id=request_id,
            tenant_id=tenant_id,
            required=True,
            status=ApprovalStatus.PENDING,
            required_approvers=frozenset(
                required_approvers
            ),
            expires_at=expires_at,
        )

        self._approvals[
            approval.approval_id
        ] = approval

        return approval

    def get(
        self,
        approval_id: str,
    ) -> CyberApproval:

        return self._approvals[approval_id]


# ================================================================
# ACTION-LEVEL CLASSIFIER
# ================================================================

class ActionLevelClassifier:

    READ_ACTIONS = frozenset({
        "read",
        "query",
        "inspect",
        "collect_evidence",
        "view",
    })

    LOW_RISK_ACTIONS = frozenset({
        "create_ticket",
        "notify_security_team",
        "collect_artifact",
    })

    MEDIUM_RISK_ACTIONS = frozenset({
        "quarantine_artifact",
        "block_ioc",
        "revoke_session",
    })

    HIGH_RISK_ACTIONS = frozenset({
        "isolate_endpoint",
        "disable_account",
        "rotate_credential",
        "modify_security_control",
    })

    @classmethod
    def classify(
        cls,
        action_type: str,
    ) -> ActionLevel:

        action = action_type.strip().lower()

        if action in cls.READ_ACTIONS:
            return ActionLevel.READ_ONLY

        if action in cls.LOW_RISK_ACTIONS:
            return ActionLevel.LOW_RISK_AUTONOMOUS

        if action in cls.MEDIUM_RISK_ACTIONS:
            return ActionLevel.MEDIUM_RISK_APPROVAL

        if action in cls.HIGH_RISK_ACTIONS:
            return ActionLevel.HIGH_RISK_HUMAN_APPROVAL

        # Unknown actions are conservatively treated as high risk.
        return ActionLevel.HIGH_RISK_HUMAN_APPROVAL


# ================================================================
# GOVERNANCE ENGINE
# ================================================================

class CyberGovernanceEngine:

    def __init__(
        self,
        *,
        policy_store: Optional[CyberPolicyStore] = None,
        approval_store: Optional[CyberApprovalStore] = None,
        audit_ledger: Optional[GovernanceAuditLedger] = None,
        clock: Optional[callable] = None,
    ) -> None:

        self.policy_store = (
            policy_store
            or CyberPolicyStore()
        )

        self.approval_store = (
            approval_store
            or CyberApprovalStore()
        )

        self.audit_ledger = (
            audit_ledger
            or GovernanceAuditLedger()
        )

        self.clock = clock

    def _now(self) -> float:

        if self.clock:
            return float(self.clock())

        import time
        return time.time()

    # ------------------------------------------------------------
    # Policy evaluation
    # ------------------------------------------------------------

    def evaluate_policies(
        self,
        request: CyberActionRequest,
        context: Optional[Mapping[str, Any]] = None,
    ) -> tuple[CyberPolicy, ...]:

        context = dict(context or {})

        matched = []

        for policy in self.policy_store.active_for_tenant(
            request.tenant_id
        ):
            if policy.matches(
                request,
                context,
            ):
                matched.append(policy)

        return tuple(matched)

    # ------------------------------------------------------------
    # Default action-level control
    # ------------------------------------------------------------

    @staticmethod
    def _default_decision(
        risk_level: ActionLevel,
    ) -> GovernanceDecision:

        if risk_level == ActionLevel.READ_ONLY:
            return GovernanceDecision.ALLOW

        if risk_level == ActionLevel.LOW_RISK_AUTONOMOUS:
            return GovernanceDecision.ALLOW

        if risk_level == ActionLevel.MEDIUM_RISK_APPROVAL:
            return GovernanceDecision.REQUIRE_APPROVAL

        if risk_level == ActionLevel.HIGH_RISK_HUMAN_APPROVAL:
            return GovernanceDecision.REQUIRE_APPROVAL

        if risk_level == ActionLevel.EMERGENCY_BREAK_GLASS:
            return GovernanceDecision.BREAK_GLASS

        return GovernanceDecision.DENY

    # ------------------------------------------------------------
    # Governance evaluation
    # ------------------------------------------------------------

    def evaluate(
        self,
        request: CyberActionRequest,
        *,
        context: Optional[Mapping[str, Any]] = None,
    ) -> GovernanceDecisionRecord:

        context = dict(context or {})

        matched = self.evaluate_policies(
            request,
            context,
        )

        # Default deny for explicitly unknown policy outcomes
        # is avoided only where the action-level model provides
        # a deterministic baseline.
        decision = self._default_decision(
            request.risk_level
        )

        reasons: list[str] = []

        if request.risk_level == ActionLevel.READ_ONLY:
            reasons.append(
                "read_only_action"
            )

        elif request.risk_level == ActionLevel.LOW_RISK_AUTONOMOUS:
            reasons.append(
                "low_risk_autonomous_action"
            )

        elif request.risk_level == ActionLevel.MEDIUM_RISK_APPROVAL:
            reasons.append(
                "medium_risk_requires_approval"
            )

        elif request.risk_level == ActionLevel.HIGH_RISK_HUMAN_APPROVAL:
            reasons.append(
                "high_risk_requires_human_approval"
            )

        elif request.risk_level == ActionLevel.EMERGENCY_BREAK_GLASS:
            reasons.append(
                "emergency_break_glass_path"
            )

        # Policies are evaluated in priority order.
        # First matching explicit DENY is authoritative.
        for policy in matched:

            if policy.effect == PolicyEffect.DENY:
                decision = GovernanceDecision.DENY
                reasons.append(
                    f"policy_denied:{policy.policy_id}"
                )
                break

            if policy.effect == PolicyEffect.REQUIRE_APPROVAL:
                decision = GovernanceDecision.REQUIRE_APPROVAL
                reasons.append(
                    f"policy_requires_approval:{policy.policy_id}"
                )

            elif policy.effect == PolicyEffect.ALLOW:
                if decision != GovernanceDecision.REQUIRE_APPROVAL:
                    decision = GovernanceDecision.ALLOW

                reasons.append(
                    f"policy_allowed:{policy.policy_id}"
                )

        record = GovernanceDecisionRecord(
            decision_id=f"gov_{uuid4().hex}",
            request_id=request.request_id,
            tenant_id=request.tenant_id,
            decision=decision,
            action_level=request.risk_level,
            matched_policy_ids=tuple(
                policy.policy_id
                for policy in matched
            ),
            reason_codes=tuple(reasons),
        )

        self._audit(
            request=request,
            event_type="governance_evaluated",
            decision=decision,
            actor_id=request.principal_id,
            details={
                "decision_id": record.decision_id,
                "risk_level": request.risk_level.value,
                "matched_policies": list(
                    record.matched_policy_ids
                ),
            },
        )

        return record

    # ------------------------------------------------------------
    # Approval creation
    # ------------------------------------------------------------

    def create_required_approval(
        self,
        request: CyberActionRequest,
        decision: GovernanceDecisionRecord,
        *,
        approvers: Sequence[str] = (),
        ttl_seconds: Optional[float] = None,
    ) -> CyberApproval:

        if decision.decision != GovernanceDecision.REQUIRE_APPROVAL:
            raise ValueError(
                "Approval is only valid for "
                "REQUIRE_APPROVAL decisions."
            )

        expires_at = None

        if ttl_seconds is not None:

            if ttl_seconds <= 0:
                raise ValueError(
                    "ttl_seconds must be positive."
                )

            expires_at = (
                self._now()
                + ttl_seconds
            )

        approval = self.approval_store.create(
            request_id=request.request_id,
            tenant_id=request.tenant_id,
            required_approvers=approvers,
            expires_at=expires_at,
        )

        self._audit(
            request=request,
            event_type="approval_created",
            decision=decision.decision,
            actor_id=request.principal_id,
            details={
                "approval_id": approval.approval_id,
                "required_approvers": list(
                    approval.required_approvers
                ),
            },
        )

        return approval

    # ------------------------------------------------------------
    # Approval completion
    # ------------------------------------------------------------

    def approve(
        self,
        request: CyberActionRequest,
        approval_id: str,
        approver_id: str,
    ) -> CyberApproval:

        approval = self.approval_store.get(
            approval_id
        )

        if approval.request_id != request.request_id:
            raise PermissionError(
                "Approval does not belong to action request."
            )

        if approval.tenant_id != request.tenant_id:
            raise PermissionError(
                "Cross-tenant approval access denied."
            )

        approval.approve(
            approver_id,
            self._now(),
        )

        self._audit(
            request=request,
            event_type="approval_updated",
            decision=(
                GovernanceDecision.ALLOW
                if approval.status == ApprovalStatus.APPROVED
                else None
            ),
            actor_id=approver_id,
            details={
                "approval_id": approval.approval_id,
                "status": approval.status.value,
            },
        )

        return approval

    def reject(
        self,
        request: CyberActionRequest,
        approval_id: str,
        approver_id: str,
        reason: str,
    ) -> CyberApproval:

        approval = self.approval_store.get(
            approval_id
        )

        if approval.request_id != request.request_id:
            raise PermissionError(
                "Approval does not belong to action request."
            )

        if approval.tenant_id != request.tenant_id:
            raise PermissionError(
                "Cross-tenant approval access denied."
            )

        approval.reject(
            approver_id,
            reason,
            self._now(),
        )

        self._audit(
            request=request,
            event_type="approval_rejected",
            decision=GovernanceDecision.DENY,
            actor_id=approver_id,
            details={
                "approval_id": approval.approval_id,
                "reason": reason,
            },
        )

        return approval

    # ------------------------------------------------------------
    # Final authorization
    # ------------------------------------------------------------

    def authorize_execution(
        self,
        request: CyberActionRequest,
        decision: GovernanceDecisionRecord,
        *,
        approval_id: Optional[str] = None,
    ) -> bool:

        if decision.decision == GovernanceDecision.DENY:
            return False

        if decision.decision == GovernanceDecision.ALLOW:
            self._audit(
                request=request,
                event_type="execution_authorized",
                decision=decision.decision,
                actor_id=request.principal_id,
                details={
                    "authorization": "allowed"
                },
            )
            return True

        if decision.decision == GovernanceDecision.REQUIRE_APPROVAL:

            if approval_id is None:
                return False

            approval = self.approval_store.get(
                approval_id
            )

            if approval.request_id != request.request_id:
                raise PermissionError(
                    "Approval/request mismatch."
                )

            if approval.tenant_id != request.tenant_id:
                raise PermissionError(
                    "Cross-tenant approval denied."
                )

            if approval.status != ApprovalStatus.APPROVED:
                return False

            if approval.is_expired(self._now()):
                return False

            self._audit(
                request=request,
                event_type="execution_authorized",
                decision=decision.decision,
                actor_id=request.principal_id,
                details={
                    "authorization": "approval_confirmed",
                    "approval_id": approval_id,
                },
            )

            return True

        if decision.decision == GovernanceDecision.BREAK_GLASS:

            # Break-glass is never silently authorized.
            # An explicit break-glass authorization token
            # must be supplied through the approval layer.
            return False

        return False

    # ------------------------------------------------------------
    # Audit
    # ------------------------------------------------------------

    def _audit(
        self,
        *,
        request: CyberActionRequest,
        event_type: str,
        decision: Optional[GovernanceDecision],
        actor_id: str,
        details: Mapping[str, Any],
    ) -> None:

        self.audit_ledger.append(
            GovernanceAuditRecord(
                audit_id=f"gov_audit_{uuid4().hex}",
                request_id=request.request_id,
                tenant_id=request.tenant_id,
                event_type=event_type,
                actor_id=actor_id,
                decision=decision,
                timestamp=self._now(),
                details=dict(details),
            )
        )
    # --- preserved from CyberGovernanceEngine (merged, not present in canonical host) ---
    @staticmethod
    def _assert_approval_binding(
        request: CyberActionRequest,
        approval: CyberApproval,
    ) -> None:

        if (
            approval.request_id
            != request.request_id
        ):

            raise PermissionError(
                "Approval does not belong "
                "to action request."
            )

        if (
            approval.tenant_id
            != request.tenant_id
        ):

            raise PermissionError(
                "Cross-tenant approval "
                "access denied."
            )


