def _request(
    action: str,
    risk: ActionLevel,
    tenant: str = "tenant-A",
    principal: str = "agent-1",
) -> CyberActionRequest:
    # NOTE(auto-repair): this helper called CyberActionRequest.create() with
    # a schema (tenant_id/principal_id/principal_type/action_type/
    # risk_level, all free-form strings) that does not match that method's
    # real, current parameters (tenant_id/requested_by/agent_id/action/
    # action_level as UUIDs and a ResponseAction enum) -- it could never
    # have run. This adapts the simple (action: str, risk, tenant, principal)
    # call shape used throughout Phase 14 onto the real schema:
    #   - tenant/principal strings become deterministic UUIDs (so the same
    #     string always maps to the same id within a test run);
    #   - action strings that match a real ResponseAction value are used
    #     as-is; ones that don't (e.g. this suite's "read") fall back to
    #     COLLECT_EVIDENCE, since that's the closest read-only/no-side-effect
    #     action available -- this is a best-effort default, not a verified
    #     restoration of the original Phase 14 intent, since that mapping
    #     was lost when the schema changed.
    try:
        action_enum = ResponseAction(action)
    except ValueError:
        action_enum = ResponseAction.COLLECT_EVIDENCE

    tenant_uuid = uuid.uuid5(uuid.NAMESPACE_DNS, f"tenant:{tenant}")
    principal_uuid = uuid.uuid5(uuid.NAMESPACE_DNS, f"agent:{principal}")

    return CyberActionRequest.create(
        tenant_id=tenant_uuid,
        requested_by=principal_uuid,
        agent_id=principal_uuid,
        action=action_enum,
        action_level=risk,
        target_id="target-001",
        target_type="generic",
        risk_score=0.0,
        confidence=1.0,
        reason="Phase 14 test",
        evidence_ids=("evidence-001",),
    )


def test_read_only_is_allowed() -> None:

    engine = CyberGovernanceEngine()

    request = _request(
        "read",
        ActionLevel.READ_ONLY,
    )

    result = engine.evaluate(request)

    assert (
        result.decision
        == GovernanceDecision.ALLOW
    )


