def test_deny_policy_overrides_allow() -> None:

    store = CyberPolicyStore()

    store.add(
        CyberPolicy(
            policy_id="deny-policy",
            name="Deny account disablement",
            priority=1,
            effect=PolicyEffect.DENY,
            subject=PolicySubject(
                tenant_id="tenant-A",
                action_types=frozenset({
                    "disable_account",
                }),
            ),
        )
    )

    engine = CyberGovernanceEngine(
        policy_store=store
    )

    request = _request(
        "disable_account",
        ActionLevel.HIGH_RISK_HUMAN_APPROVAL,
    )

    result = engine.evaluate(request)

    assert (
        result.decision
        == GovernanceDecision.DENY
    )

    assert (
        "deny-policy"
        in result.matched_policy_ids
    )


