def test_approval_required_before_execution() -> None:

    engine = CyberGovernanceEngine()

    request = _request(
        "revoke_session",
        ActionLevel.MEDIUM_RISK_APPROVAL,
    )

    decision = engine.evaluate(request)

    approval = engine.create_required_approval(
        request,
        decision,
        approvers=("human-1",),
    )

    assert not engine.authorize_execution(
        request,
        decision,
        approval_id=approval.approval_id,
    )


def test_valid_approval_authorizes_execution() -> None:

    engine = CyberGovernanceEngine()

    request = _request(
        "revoke_session",
        ActionLevel.MEDIUM_RISK_APPROVAL,
    )

    decision = engine.evaluate(request)

    approval = engine.create_required_approval(
        request,
        decision,
        approvers=("human-1",),
    )

    engine.approve(
        request,
        approval.approval_id,
        "human-1",
    )

    assert engine.authorize_execution(
        request,
        decision,
        approval_id=approval.approval_id,
    )


def test_unauthorized_approver_rejected() -> None:

    engine = CyberGovernanceEngine()

    request = _request(
        "disable_account",
        ActionLevel.HIGH_RISK_HUMAN_APPROVAL,
    )

    decision = engine.evaluate(request)

    approval = engine.create_required_approval(
        request,
        decision,
        approvers=("human-1",),
    )

    try:
        engine.approve(
            request,
            approval.approval_id,
            "attacker",
        )
    except PermissionError:
        return

    raise AssertionError(
        "Unauthorized approver was accepted."
    )


def test_rejected_approval_blocks_execution() -> None:

    engine = CyberGovernanceEngine()

    request = _request(
        "disable_account",
        ActionLevel.HIGH_RISK_HUMAN_APPROVAL,
    )

    decision = engine.evaluate(request)

    approval = engine.create_required_approval(
        request,
        decision,
        approvers=("human-1",),
    )

    engine.reject(
        request,
        approval.approval_id,
        "human-1",
        "Insufficient evidence.",
    )

    assert not engine.authorize_execution(
        request,
        decision,
        approval_id=approval.approval_id,
    )


def test_expired_approval_blocks_execution() -> None:

    current_time = [1000.0]

    engine = CyberGovernanceEngine(
        clock=lambda: current_time[0]
    )

    request = _request(
        "disable_account",
        ActionLevel.HIGH_RISK_HUMAN_APPROVAL,
    )

    decision = engine.evaluate(request)

    approval = engine.create_required_approval(
        request,
        decision,
        approvers=("human-1",),
        ttl_seconds=10,
    )

    current_time[0] = 1011.0

    try:
        engine.approve(
            request,
            approval.approval_id,
            "human-1",
        )
    except PermissionError:
        pass
    else:
        raise AssertionError(
            "Expired approval was accepted."
        )

    assert not engine.authorize_execution(
        request,
        decision,
        approval_id=approval.approval_id,
    )


def test_cross_tenant_approval_denied() -> None:

    engine = CyberGovernanceEngine()

    request_a = _request(
        "disable_account",
        ActionLevel.HIGH_RISK_HUMAN_APPROVAL,
        tenant="tenant-A",
    )

    request_b = _request(
        "disable_account",
        ActionLevel.HIGH_RISK_HUMAN_APPROVAL,
        tenant="tenant-B",
    )

    decision = engine.evaluate(request_a)

    approval = engine.create_required_approval(
        request_a,
        decision,
        approvers=("human-1",),
    )

    try:
        engine.approve(
            request_b,
            approval.approval_id,
            "human-1",
        )
    except PermissionError:
        return

    raise AssertionError(
        "Cross-tenant approval was accepted."
    )


