# ================================================================
# TEST RUNNER
# ================================================================

def run_phase_14_tests() -> dict[str, Any]:

    tests = [
        test_read_only_is_allowed,
        test_low_risk_autonomous_action_allowed,
        test_medium_risk_requires_approval_v2,
        test_high_risk_requires_human_approval,
        test_unknown_action_is_conservatively_high_risk,
        test_deny_policy_overrides_allow,
        test_policy_can_require_approval,
        test_approval_required_before_execution,
        test_valid_approval_authorizes_execution,
        test_unauthorized_approver_rejected,
        test_rejected_approval_blocks_execution,
        test_expired_approval_blocks_execution,
        test_cross_tenant_approval_denied,
        test_break_glass_not_silently_authorized,
        test_audit_record_created,
        test_policy_priority_is_deterministic,
    ]

    passed = 0
    failures: list[dict[str, str]] = []

    for test in tests:
        try:
            test()
            passed += 1
        except Exception as exc:
            failures.append({
                "test": test.__name__,
                "error": (
                    f"{type(exc).__name__}: {exc}"
                ),
            })

    return {
        "phase": 14,
        "component": "Cyber Governance",
        "total_tests": len(tests),
        "passed": passed,
        "failed": len(failures),
        "failures": failures,
        "status": (
            "PASS"
            if not failures
            else "FAIL"
        ),
    }


