# ================================================================
# RESPONSE REQUEST
# ================================================================

@dataclass(frozen=True)
class CyberResponseRequest:
    response_id: str

    tenant_id: str

    action_type: ResponseActionType
    target_id: str

    requested_by: str

    reason: str = ""

    evidence_ids: tuple[str, ...] = ()

    idempotency_key: str = ""

    parameters: Mapping[str, Any] = field(
        default_factory=dict
    )

    metadata: Mapping[str, Any] = field(
        default_factory=dict
    )

    @staticmethod
    def create(
        *,
        tenant_id: str,
        action_type: ResponseActionType,
        target_id: str,
        requested_by: str,
        reason: str = "",
        evidence_ids: Sequence[str] = (),
        idempotency_key: Optional[str] = None,
        parameters: Optional[Mapping[str, Any]] = None,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> "CyberResponseRequest":

        if not tenant_id.strip():
            raise ValueError("tenant_id is required")

        if not target_id.strip():
            raise ValueError("target_id is required")

        if not requested_by.strip():
            raise ValueError("requested_by is required")

        generated_key = (
            idempotency_key
            or (
                f"{tenant_id}:"
                f"{action_type.value}:"
                f"{target_id}"
            )
        )

        return CyberResponseRequest(
            response_id=f"response_{uuid4().hex}",
            tenant_id=tenant_id,
            action_type=action_type,
            target_id=target_id,
            requested_by=requested_by,
            reason=reason,
            evidence_ids=tuple(evidence_ids),
            idempotency_key=generated_key,
            parameters=dict(parameters or {}),
            metadata=dict(metadata or {}),
        )


# ================================================================
# CONNECTOR RESULT
# ================================================================

@dataclass(frozen=True)
class ConnectorResponse:
    connector_id: str

    accepted: bool

    status: ResponseStatus

    external_request_id: Optional[str] = None

    message: str = ""

    raw: Mapping[str, Any] = field(
        default_factory=dict
    )


# ================================================================
# RESPONSE RESULT
# ================================================================

@dataclass(frozen=True)
class CyberResponseResult:
    response_id: str

    tenant_id: str

    action_type: ResponseActionType
    target_id: str

    status: ResponseStatus

    connector_id: Optional[str] = None

    external_request_id: Optional[str] = None

    attempts: int = 0

    message: str = ""

    executed: bool = False

    idempotent_replay: bool = False


# ================================================================
# CONNECTOR CONTRACT
# ================================================================

@dataclass(frozen=True)
class ResponseConnectorCapability:
    # NOTE(auto-repair): find_capable() below needs one of these per
    # (connector, supported action) pair -- it reads .tenant_id/.enabled/
    # .action_type. The Protocol below declared capabilities() as
    # returning bare ConnectorCapability enum members (a different,
    # protocol-level enum: AUTHENTICATE/HEALTH/READ/...), and the one real
    # implementation (SimulatedResponseConnector) was actually trying to
    # call that enum as if it were this kind of record, which crashed
    # immediately. This is the record type both sides actually need.
    connector_id: str
    family: "ConnectorFamily"
    action_type: "ResponseActionType"
    tenant_id: str
    enabled: bool = True


class CyberResponseConnector(Protocol):

    @property
    def connector_id(self) -> str:
        ...

    @property
    def tenant_id(self) -> str:
        ...

    def capabilities(self) -> Sequence[ResponseConnectorCapability]:
        ...

    def execute(
        self,
        request: CyberResponseRequest,
        *,
        timeout_seconds: float,
    ) -> ConnectorResponse:
        ...


# ================================================================
# CONNECTOR REGISTRY
# ================================================================

class ResponseConnectorRegistry:

    def __init__(self) -> None:
        self._connectors: dict[
            str,
            CyberResponseConnector
        ] = {}

    def register(
        self,
        connector: CyberResponseConnector,
    ) -> None:

        connector_id = connector.connector_id

        if not connector_id.strip():
            raise ValueError(
                "Connector ID cannot be empty."
            )

        if connector_id in self._connectors:
            raise ValueError(
                f"Connector already registered: "
                f"{connector_id}"
            )

        self._connectors[
            connector_id
        ] = connector

    def get(
        self,
        connector_id: str,
    ) -> CyberResponseConnector:

        return self._connectors[connector_id]

    def find_capable(
        self,
        *,
        tenant_id: str,
        action_type: ResponseActionType,
    ) -> tuple[CyberResponseConnector, ...]:

        result = []

        for connector in self._connectors.values():

            if connector.tenant_id != tenant_id:
                continue

            for capability in connector.capabilities():

                if (
                    capability.tenant_id == tenant_id
                    and capability.enabled
                    and capability.action_type
                    == action_type
                ):
                    result.append(connector)
                    break

        return tuple(result)


# ================================================================
# IDEMPOTENCY STORE
# ================================================================

@dataclass(frozen=True)
class IdempotencyRecord:
    key: str

    response_id: str

    result: CyberResponseResult

    created_at: float
    tenant_id: str = None  # merged from IdempotencyRecord, made optional for safety
    record_id: str = None  # merged from IdempotencyRecord, made optional for safety


class ResponseIdempotencyStore:

    def __init__(self) -> None:
        self._records: dict[
            str,
            IdempotencyRecord
        ] = {}

    def get(
        self,
        key: str,
    ) -> Optional[IdempotencyRecord]:

        return self._records.get(key)

    def put(
        self,
        key: str,
        result: CyberResponseResult,
        *,
        now: float,
    ) -> None:

        if key in self._records:
            return

        self._records[key] = IdempotencyRecord(
            key=key,
            response_id=result.response_id,
            result=result,
            created_at=now,
        )


# ================================================================
# RESPONSE JOURNAL
# ================================================================

@dataclass(frozen=True)
class ResponseJournalEntry:
    journal_id: str

    response_id: str

    tenant_id: str

    action_type: ResponseActionType

    status: ResponseStatus

    timestamp: float

    connector_id: Optional[str]

    actor_id: str

    details: Mapping[str, Any] = field(
        default_factory=dict
    )


class ResponseJournal:

    def __init__(self) -> None:
        self._entries: list[
            ResponseJournalEntry
        ] = []

    def append(
        self,
        *,
        response_id: str,
        tenant_id: str,
        action_type: ResponseActionType,
        status: ResponseStatus,
        timestamp: float,
        connector_id: Optional[str],
        actor_id: str,
        details: Optional[Mapping[str, Any]] = None,
    ) -> None:

        self._entries.append(
            ResponseJournalEntry(
                journal_id=f"journal_{uuid4().hex}",
                response_id=response_id,
                tenant_id=tenant_id,
                action_type=action_type,
                status=status,
                timestamp=timestamp,
                connector_id=connector_id,
                actor_id=actor_id,
                details=dict(details or {}),
            )
        )

    def entries(
        self,
        tenant_id: Optional[str] = None,
    ) -> tuple[ResponseJournalEntry, ...]:

        if tenant_id is None:
            return tuple(self._entries)

        return tuple(
            entry
            for entry in self._entries
            if entry.tenant_id == tenant_id
        )


# ================================================================
# RESPONSE POLICY
# ================================================================

@dataclass(frozen=True)
class ResponseDispatchPolicy:
    timeout_seconds: float = 30.0

    max_attempts: int = 3

    retry_delay_seconds: float = 0.0

    retryable_statuses: frozenset[
        ResponseStatus
    ] = frozenset({
        ResponseStatus.TIMEOUT,
        ResponseStatus.FAILED,
    })

    def __post_init__(self) -> None:

        if self.timeout_seconds <= 0:
            raise ValueError(
                "timeout_seconds must be positive."
            )

        if self.max_attempts < 1:
            raise ValueError(
                "max_attempts must be >= 1."
            )

        if self.retry_delay_seconds < 0:
            raise ValueError(
                "retry_delay_seconds cannot be negative."
            )


# ================================================================
# RESPONSE VALIDATOR
# ================================================================

class ResponseRequestValidator:

    @staticmethod
    def validate(
        request: CyberResponseRequest,
    ) -> None:

        if not request.tenant_id.strip():
            raise ValueError(
                "Response request has no tenant."
            )

        if not request.target_id.strip():
            raise ValueError(
                "Response request has no target."
            )

        if not request.requested_by.strip():
            raise ValueError(
                "Response request has no actor."
            )

        if not request.idempotency_key.strip():
            raise ValueError(
                "Response request has no idempotency key."
            )

        # Actions requiring target-specific identifiers.
        if request.action_type in {
            ResponseActionType.BLOCK_IOC,
            ResponseActionType.REVOKE_SESSION,
            ResponseActionType.DISABLE_ACCOUNT,
            ResponseActionType.ROTATE_CREDENTIAL,
            ResponseActionType.QUARANTINE_ARTIFACT,
        }:
            if not request.target_id.strip():
                raise ValueError(
                    "Target is required for this response action."
                )


# ================================================================
# SAFE PARAMETER FILTER
# ================================================================

class ResponseParameterGuard:

    # Fields that must never be accepted as arbitrary
    # executable instructions from untrusted telemetry.
    FORBIDDEN_KEYS = frozenset({
        "shell",
        "command",
        "exec",
        "script",
        "eval",
        "python",
        "powershell",
        "bash",
        "raw_command",
    })

    @classmethod
    def sanitize(
        cls,
        parameters: Mapping[str, Any],
    ) -> dict[str, Any]:

        clean: dict[str, Any] = {}

        for key, value in parameters.items():

            normalized = str(key).strip().lower()

            if normalized in cls.FORBIDDEN_KEYS:
                raise ValueError(
                    f"Unsafe response parameter rejected: "
                    f"{key}"
                )

            clean[str(key)] = value

        return clean


# ================================================================
# RESPONSE DISPATCHER
# ================================================================

class CyberResponseDispatcher:

    def __init__(
        self,
        *,
        connector_registry: ResponseConnectorRegistry,
        idempotency_store: Optional[
            ResponseIdempotencyStore
        ] = None,
        journal: Optional[ResponseJournal] = None,
        policy: Optional[ResponseDispatchPolicy] = None,
        clock: Optional[Callable[[], float]] = None,
        sleeper: Optional[Callable[[float], None]] = None,
    ) -> None:

        self.connector_registry = connector_registry

        self.idempotency_store = (
            idempotency_store
            or ResponseIdempotencyStore()
        )

        self.journal = (
            journal
            or ResponseJournal()
        )

        self.policy = (
            policy
            or ResponseDispatchPolicy()
        )

        self.clock = clock or time.time
        self.sleeper = sleeper or time.sleep

    # ------------------------------------------------------------
    # Public dispatch
    # ------------------------------------------------------------

    def dispatch(
        self,
        request: CyberResponseRequest,
    ) -> CyberResponseResult:

        ResponseRequestValidator.validate(
            request
        )

        clean_parameters = (
            ResponseParameterGuard.sanitize(
                request.parameters
            )
        )

        request = CyberResponseRequest(
            response_id=request.response_id,
            tenant_id=request.tenant_id,
            action_type=request.action_type,
            target_id=request.target_id,
            requested_by=request.requested_by,
            reason=request.reason,
            evidence_ids=request.evidence_ids,
            idempotency_key=request.idempotency_key,
            parameters=clean_parameters,
            metadata=request.metadata,
        )

        # --------------------------------------------------------
        # Idempotency
        # --------------------------------------------------------

        existing = self.idempotency_store.get(
            request.idempotency_key
        )

        if existing is not None:

            previous = existing.result

            replay = CyberResponseResult(
                response_id=previous.response_id,
                tenant_id=previous.tenant_id,
                action_type=previous.action_type,
                target_id=previous.target_id,
                status=previous.status,
                connector_id=previous.connector_id,
                external_request_id=(
                    previous.external_request_id
                ),
                attempts=previous.attempts,
                message=previous.message,
                executed=previous.executed,
                idempotent_replay=True,
            )

            self.journal.append(
                response_id=request.response_id,
                tenant_id=request.tenant_id,
                action_type=request.action_type,
                status=previous.status,
                timestamp=self.clock(),
                connector_id=previous.connector_id,
                actor_id=request.requested_by,
                details={
                    "idempotent_replay": True,
                    "original_response_id": (
                        previous.response_id
                    ),
                },
            )

            return replay

        # --------------------------------------------------------
        # Find real capable connector
        # --------------------------------------------------------

        connectors = (
            self.connector_registry.find_capable(
                tenant_id=request.tenant_id,
                action_type=request.action_type,
            )
        )

        if not connectors:

            result = CyberResponseResult(
                response_id=request.response_id,
                tenant_id=request.tenant_id,
                action_type=request.action_type,
                target_id=request.target_id,
                status=ResponseStatus.UNSUPPORTED,
                message=(
                    "No registered connector supports "
                    f"{request.action_type.value} "
                    "for this tenant."
                ),
                executed=False,
            )

            self.idempotency_store.put(
                request.idempotency_key,
                result,
                now=self.clock(),
            )

            self.journal.append(
                response_id=request.response_id,
                tenant_id=request.tenant_id,
                action_type=request.action_type,
                status=result.status,
                timestamp=self.clock(),
                connector_id=None,
                actor_id=request.requested_by,
                details={
                    "executed": False,
                    "reason": "unsupported_action",
                },
            )

            return result

        # --------------------------------------------------------
        # Connector selection
        #
        # The dispatcher selects the first registered capable
        # connector deterministically.
        # --------------------------------------------------------

        connector = connectors[0]

        self.journal.append(
            response_id=request.response_id,
            tenant_id=request.tenant_id,
            action_type=request.action_type,
            status=ResponseStatus.DISPATCHING,
            timestamp=self.clock(),
            connector_id=connector.connector_id,
            actor_id=request.requested_by,
            details={},
        )

        # --------------------------------------------------------
        # Execute with bounded retries
        # --------------------------------------------------------

        attempts = 0
        final_response: Optional[
            ConnectorResponse
        ] = None

        while attempts < self.policy.max_attempts:

            attempts += 1

            try:

                final_response = connector.execute(
                    request,
                    timeout_seconds=(
                        self.policy.timeout_seconds
                    ),
                )

            except TimeoutError as exc:

                final_response = ConnectorResponse(
                    connector_id=connector.connector_id,
                    accepted=False,
                    status=ResponseStatus.TIMEOUT,
                    message=str(exc),
                )

            except Exception as exc:

                final_response = ConnectorResponse(
                    connector_id=connector.connector_id,
                    accepted=False,
                    status=ResponseStatus.FAILED,
                    message=(
                        f"{type(exc).__name__}: {exc}"
                    ),
                )

            # [auto-repair] was a bare assert (Repair Phase 17) --
            # stripped under python -O, and this is a real dispatch
            # invariant, not a test check.
            if final_response is None:
                raise ConnectorProtocolError(
                    "Dispatch loop produced no response."
                )

            if (
                final_response.status
                not in self.policy.retryable_statuses
            ):
                break

            if attempts < self.policy.max_attempts:

                self.journal.append(
                    response_id=request.response_id,
                    tenant_id=request.tenant_id,
                    action_type=request.action_type,
                    status=ResponseStatus.RETRYING,
                    timestamp=self.clock(),
                    connector_id=connector.connector_id,
                    actor_id=request.requested_by,
                    details={
                        "attempt": attempts,
                        "next_attempt": attempts + 1,
                    },
                )

                if self.policy.retry_delay_seconds:
                    self.sleeper(
                        self.policy.retry_delay_seconds
                    )

        # --------------------------------------------------------
        # Normalize connector result
        # --------------------------------------------------------

        # [auto-repair] was a bare assert (Repair Phase 17) --
        # stripped under python -O, and this is a real dispatch
        # invariant, not a test check.
        if final_response is None:
            raise ConnectorProtocolError(
                "Dispatch loop produced no response."
            )

        if final_response.accepted:

            status = (
                final_response.status
                if final_response.status
                in {
                    ResponseStatus.ACCEPTED,
                    ResponseStatus.COMPLETED,
                }
                else ResponseStatus.ACCEPTED
            )

            executed = True

        else:

            status = final_response.status

            if status not in {
                ResponseStatus.FAILED,
                ResponseStatus.TIMEOUT,
                ResponseStatus.UNSUPPORTED,
                ResponseStatus.CANCELLED,
            }:
                status = ResponseStatus.FAILED

            executed = False

        result = CyberResponseResult(
            response_id=request.response_id,
            tenant_id=request.tenant_id,
            action_type=request.action_type,
            target_id=request.target_id,
            status=status,
            connector_id=connector.connector_id,
            external_request_id=(
                final_response.external_request_id
            ),
            attempts=attempts,
            message=final_response.message,
            executed=executed,
        )

        # --------------------------------------------------------
        # Persist idempotent result
        # --------------------------------------------------------

        self.idempotency_store.put(
            request.idempotency_key,
            result,
            now=self.clock(),
        )

        # --------------------------------------------------------
        # Journal
        # --------------------------------------------------------

        self.journal.append(
            response_id=request.response_id,
            tenant_id=request.tenant_id,
            action_type=request.action_type,
            status=status,
            timestamp=self.clock(),
            connector_id=connector.connector_id,
            actor_id=request.requested_by,
            details={
                "attempts": attempts,
                "executed": executed,
                "external_request_id": (
                    final_response.external_request_id
                ),
            },
        )

        return result


# ================================================================
# SIMULATED CONNECTOR
#
# This is a TEST HARNESS only.
# It is deliberately not presented as a real EDR/cloud/identity
# integration.
# ================================================================

class SimulatedResponseConnector:

    def __init__(
        self,
        *,
        connector_id: str,
        tenant_id: str,
        supported_actions: Sequence[
            ResponseActionType
        ],
        executor: Optional[
            Callable[
                [CyberResponseRequest],
                ConnectorResponse
            ]
        ] = None,
    ) -> None:

        self._connector_id = connector_id
        self._tenant_id = tenant_id
        self._supported_actions = frozenset(
            supported_actions
        )
        self._executor = executor

        self.calls: list[
            CyberResponseRequest
        ] = []

    @property
    def connector_id(self) -> str:
        return self._connector_id

    @property
    def tenant_id(self) -> str:
        return self._tenant_id

    def capabilities(
        self,
    ) -> Sequence[ResponseConnectorCapability]:

        return tuple(
            ResponseConnectorCapability(
                connector_id=self.connector_id,
                family=ConnectorFamily.ENDPOINT,
                action_type=action,
                tenant_id=self.tenant_id,
            )
            for action in self._supported_actions
        )

    def execute(
        self,
        request: CyberResponseRequest,
        *,
        timeout_seconds: float,
    ) -> ConnectorResponse:

        if request.action_type not in (
            self._supported_actions
        ):
            return ConnectorResponse(
                connector_id=self.connector_id,
                accepted=False,
                status=ResponseStatus.UNSUPPORTED,
                message="Action not supported.",
            )

        self.calls.append(request)

        if self._executor:
            return self._executor(request)

        # Simulator behavior only.
        return ConnectorResponse(
            connector_id=self.connector_id,
            accepted=True,
            status=ResponseStatus.ACCEPTED,
            external_request_id=(
                f"sim_{uuid4().hex}"
            ),
            message=(
                "Simulator accepted response action."
            ),
        )


# ================================================================
# PHASE 15 TESTS
# ================================================================

def test_unsupported_action_never_executes() -> None:

    registry = ResponseConnectorRegistry()

    connector = SimulatedResponseConnector(
        connector_id="edr-1",
        tenant_id="tenant-A",
        supported_actions=(
            ResponseActionType.ISOLATE_ENDPOINT,
        ),
    )

    registry.register(connector)

    dispatcher = CyberResponseDispatcher(
        connector_registry=registry
    )

    request = CyberResponseRequest.create(
        tenant_id="tenant-A",
        action_type=ResponseActionType.DISABLE_ACCOUNT,
        target_id="user-1",
        requested_by="agent-1",
    )

    result = dispatcher.dispatch(request)

    assert result.status == ResponseStatus.UNSUPPORTED
    assert result.executed is False
    assert connector.calls == []


