def test_idempotency_prevents_duplicate_execution() -> None:

    registry = ResponseConnectorRegistry()

    connector = SimulatedResponseConnector(
        connector_id="edr-1",
        tenant_id="tenant-A",
        supported_actions=(
            ResponseActionType.ISOLATE_ENDPOINT,
        ),
    )

    registry.register(connector)

    dispatcher = CyberResponseDispatcher(
        connector_registry=registry
    )

    request = CyberResponseRequest.create(
        tenant_id="tenant-A",
        action_type=ResponseActionType.ISOLATE_ENDPOINT,
        target_id="endpoint-1",
        requested_by="agent-1",
        idempotency_key="isolate:tenant-A:endpoint-1",
    )

    first = dispatcher.dispatch(request)
    second = dispatcher.dispatch(request)

    assert first.executed is True
    assert second.executed is True
    assert second.idempotent_replay is True

    # Actual connector was called only once.
    assert len(connector.calls) == 1


def test_failed_connector_is_bounded_by_retry_limit() -> None:

    calls = []

    def failing_executor(
        request: CyberResponseRequest,
    ) -> ConnectorResponse:

        calls.append(request)

        return ConnectorResponse(
            connector_id="edr-1",
            accepted=False,
            status=ResponseStatus.FAILED,
            message="External system failure.",
        )

    registry = ResponseConnectorRegistry()

    connector = SimulatedResponseConnector(
        connector_id="edr-1",
        tenant_id="tenant-A",
        supported_actions=(
            ResponseActionType.ISOLATE_ENDPOINT,
        ),
        executor=failing_executor,
    )

    registry.register(connector)

    dispatcher = CyberResponseDispatcher(
        connector_registry=registry,
        policy=ResponseDispatchPolicy(
            max_attempts=3,
            retry_delay_seconds=0,
        ),
    )

    request = CyberResponseRequest.create(
        tenant_id="tenant-A",
        action_type=ResponseActionType.ISOLATE_ENDPOINT,
        target_id="endpoint-1",
        requested_by="agent-1",
    )

    result = dispatcher.dispatch(request)

    assert result.status == ResponseStatus.FAILED
    assert result.executed is False
    assert result.attempts == 3
    assert len(calls) == 3


