def test_connector_failure_is_journaled() -> None:

    def failing_executor(
        request: CyberResponseRequest,
    ) -> ConnectorResponse:

        return ConnectorResponse(
            connector_id="identity-1",
            accepted=False,
            status=ResponseStatus.FAILED,
            message="Identity provider unavailable.",
        )

    registry = ResponseConnectorRegistry()

    connector = SimulatedResponseConnector(
        connector_id="identity-1",
        tenant_id="tenant-A",
        supported_actions=(
            ResponseActionType.REVOKE_SESSION,
        ),
        executor=failing_executor,
    )

    registry.register(connector)

    journal = ResponseJournal()

    dispatcher = CyberResponseDispatcher(
        connector_registry=registry,
        journal=journal,
        policy=ResponseDispatchPolicy(
            max_attempts=1
        ),
    )

    request = CyberResponseRequest.create(
        tenant_id="tenant-A",
        action_type=ResponseActionType.REVOKE_SESSION,
        target_id="session-1",
        requested_by="agent-1",
    )

    result = dispatcher.dispatch(request)

    assert result.status == ResponseStatus.FAILED

    entries = journal.entries(
        tenant_id="tenant-A"
    )

    assert any(
        entry.status == ResponseStatus.FAILED
        for entry in entries
    )


# ================================================================
# PHASE 15 TEST RUNNER
# ================================================================

def run_phase_15_tests() -> dict[str, Any]:

    tests = [
        test_unsupported_action_never_executes,
        test_supported_endpoint_isolation_dispatches,
        test_block_ioc_dispatches_to_capable_connector,
        test_cross_tenant_connector_is_not_used,
        test_idempotency_prevents_duplicate_execution,
        test_failed_connector_is_bounded_by_retry_limit,
        test_timeout_does_not_claim_success,
        test_unsafe_parameters_are_rejected,
        test_empty_tenant_is_rejected,
        test_empty_target_is_rejected,
        test_journal_records_unsupported_response,
        test_multiple_unsupported_actions_do_not_fake_success,
        test_response_contains_external_request_id,
        test_no_connector_means_no_external_execution,
        test_connector_failure_is_journaled,
    ]

    passed = 0
    failures: list[dict[str, str]] = []

    for test in tests:

        try:
            test()
            passed += 1

        except Exception as exc:

            failures.append({
                "test": test.__name__,
                "error": (
                    f"{type(exc).__name__}: {exc}"
                ),
            })

    return {
        "phase": 15,
        "component": "Cyber Response System",
        "total_tests": len(tests),
        "passed": passed,
        "failed": len(failures),
        "failures": failures,
        "status": (
            "PASS"
            if not failures
            else "FAIL"
        ),
    }


