from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Mapping, Optional, Sequence
from uuid import uuid4


# ================================================================
# ENUMERATIONS
# ================================================================



class ConsequenceSeverity(str, Enum):
    NONE = "none"
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"


class Recommendation(str, Enum):
    PROCEED = "proceed"
    PROCEED_WITH_CAUTION = "proceed_with_caution"
    REQUIRE_REVIEW = "require_review"
    AVOID = "avoid"


class ImpactType(str, Enum):
    SECURITY = "security"
    AVAILABILITY = "availability"
    CONFIDENTIALITY = "confidentiality"
    INTEGRITY = "integrity"
    IDENTITY = "identity"
    NETWORK = "network"
    BUSINESS = "business"


# ================================================================
# SECURITY ASSET STATE
# ================================================================

@dataclass(frozen=True)
class SimulatedAsset:
    asset_id: str
    asset_type: str

    criticality: float = 0.5

    internet_exposed: bool = False

    active_threat: bool = False

    privileged: bool = False

    dependencies: tuple[str, ...] = ()

    tags: tuple[str, ...] = ()

    metadata: Mapping[str, Any] = field(
        default_factory=dict
    )

    def __post_init__(self) -> None:

        if not self.asset_id.strip():
            raise ValueError(
                "asset_id is required"
            )

        if not 0.0 <= self.criticality <= 1.0:
            raise ValueError(
                "criticality must be between 0 and 1"
            )


# ================================================================
# CURRENT SECURITY STATE
# ================================================================

@dataclass(frozen=True)
class CyberSimulationState:
    tenant_id: str

    assets: tuple[SimulatedAsset, ...]

    active_incidents: int = 0

    active_threats: int = 0

    compromised_identities: int = 0

    exposed_assets: int = 0

    privileged_identities: int = 0

    critical_vulnerabilities: int = 0

    metadata: Mapping[str, Any] = field(
        default_factory=dict
    )

    def __post_init__(self) -> None:

        if not self.tenant_id.strip():
            raise ValueError(
                "tenant_id is required"
            )

        counters = (
            self.active_incidents,
            self.active_threats,
            self.compromised_identities,
            self.exposed_assets,
            self.privileged_identities,
            self.critical_vulnerabilities,
        )

        if any(value < 0 for value in counters):
            raise ValueError(
                "Security state counters cannot be negative"
            )


# ================================================================
# PROPOSED ACTION
# ================================================================

@dataclass(frozen=True)
class SimulationAction:
    action_id: str

    action_type: str

    target_id: str

    description: str

    estimated_duration_seconds: int = 0

    parameters: Mapping[str, Any] = field(
        default_factory=dict
    )

    metadata: Mapping[str, Any] = field(
        default_factory=dict
    )

    @staticmethod
    def create(
        *,
        action_type: str,
        target_id: str,
        description: str,
        estimated_duration_seconds: int = 0,
        parameters: Optional[Mapping[str, Any]] = None,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> "SimulationAction":

        if not action_type.strip():
            raise ValueError(
                "action_type is required"
            )

        if not target_id.strip():
            raise ValueError(
                "target_id is required"
            )

        if not description.strip():
            raise ValueError(
                "description is required"
            )

        if estimated_duration_seconds < 0:
            raise ValueError(
                "estimated_duration_seconds "
                "cannot be negative"
            )

        return SimulationAction(
            action_id=f"sim_action_{uuid4().hex}",
            action_type=action_type,
            target_id=target_id,
            description=description,
            estimated_duration_seconds=(
                estimated_duration_seconds
            ),
            parameters=dict(parameters or {}),
            metadata=dict(metadata or {}),
        )


# ================================================================
# PREDICTED CONSEQUENCE
# ================================================================

@dataclass(frozen=True)
class PredictedConsequence:
    impact_type: ImpactType

    severity: ConsequenceSeverity

    probability: float

    description: str

    affected_assets: tuple[str, ...] = ()

    positive: bool = False

    evidence: tuple[str, ...] = ()

    def __post_init__(self) -> None:

        if not 0.0 <= self.probability <= 1.0:
            raise ValueError(
                "probability must be between 0 and 1"
            )

        if not self.description.strip():
            raise ValueError(
                "consequence description is required"
            )


# ================================================================
# SIMULATION METRICS
# ================================================================

@dataclass(frozen=True)
class SimulationMetrics:
    security_benefit: float

    operational_risk: float

    collateral_risk: float

    threat_reduction: float

    availability_impact: float

    confidence: float

    net_score: float

    def __post_init__(self) -> None:

        values = (
            self.security_benefit,
            self.operational_risk,
            self.collateral_risk,
            self.threat_reduction,
            self.availability_impact,
            self.confidence,
        )

        if any(
            not 0.0 <= value <= 1.0
            for value in values
        ):
            raise ValueError(
                "Simulation metric values "
                "must be between 0 and 1"
            )


# ================================================================
# SIMULATION ALTERNATIVE
# ================================================================

@dataclass(frozen=True)
class SimulationAlternative:
    alternative_id: str

    action_type: str

    description: str

    security_benefit: float

    operational_risk: float

    collateral_risk: float

    net_score: float

    rationale: str

    def __post_init__(self) -> None:

        for value in (
            self.security_benefit,
            self.operational_risk,
            self.collateral_risk,
        ):
            if not 0.0 <= value <= 1.0:
                raise ValueError(
                    "Alternative scores must "
                    "be between 0 and 1"
                )


# ================================================================
# SIMULATION RESULT
# ================================================================

@dataclass(frozen=True)
class CyberSimulationResult:
    simulation_id: str

    tenant_id: str

    mode: SimulationMode

    action: SimulationAction

    recommendation: Recommendation

    metrics: SimulationMetrics

    consequences: tuple[
        PredictedConsequence, ...
    ]

    alternatives: tuple[
        SimulationAlternative, ...
    ]

    assumptions: tuple[str, ...]

    limitations: tuple[str, ...]

    simulated_only: bool = True

    execution_performed: bool = False

    source_state_fingerprint: str = ""


# ================================================================
# STATE FINGERPRINT
# ================================================================

class SimulationStateFingerprint:

    @staticmethod
    def generate(
        state: CyberSimulationState,
    ) -> str:

        asset_data = tuple(
            (
                asset.asset_id,
                asset.asset_type,
                asset.criticality,
                asset.internet_exposed,
                asset.active_threat,
                asset.privileged,
            )
            for asset in sorted(
                state.assets,
                key=lambda item: item.asset_id,
            )
        )

        raw = repr(
            (
                state.tenant_id,
                asset_data,
                state.active_incidents,
                state.active_threats,
                state.compromised_identities,
                state.exposed_assets,
                state.privileged_identities,
                state.critical_vulnerabilities,
            )
        )

        # Stable standard-library hash representation.
        import hashlib

        return hashlib.sha256(
            raw.encode("utf-8")
        ).hexdigest()


