# ================================================================
# CONSEQUENCE PREDICTOR
# ================================================================

class ConsequencePredictor:

    def predict(
        self,
        *,
        state: CyberSimulationState,
        action: SimulationAction,
    ) -> tuple[PredictedConsequence, ...]:

        profile = ActionRiskProfiles.get(
            action.action_type
        )

        consequences = []

        target = next(
            (
                asset
                for asset in state.assets
                if asset.asset_id == action.target_id
            ),
            None,
        )

        if target is None:

            consequences.append(
                PredictedConsequence(
                    impact_type=ImpactType.BUSINESS,
                    severity=ConsequenceSeverity.HIGH,
                    probability=0.90,
                    description=(
                        "Target is not present in the "
                        "simulation state; predicted "
                        "impact has reduced confidence."
                    ),
                    positive=False,
                    evidence=(
                        "target_not_in_state",
                    ),
                )
            )

        # --------------------------------------------------------
        # Security benefit
        # --------------------------------------------------------

        if state.active_threats > 0:

            consequences.append(
                PredictedConsequence(
                    impact_type=ImpactType.SECURITY,
                    severity=ConsequenceSeverity.HIGH,
                    probability=profile.security_benefit,
                    description=(
                        "Proposed action is predicted "
                        "to reduce active threat exposure."
                    ),
                    affected_assets=(
                        (action.target_id,)
                        if target
                        else ()
                    ),
                    positive=True,
                    evidence=(
                        "active_threat_present",
                    ),
                )
            )

        # --------------------------------------------------------
        # Availability impact
        # --------------------------------------------------------

        if profile.availability_impact > 0:

            severity = (
                ConsequenceSeverity.LOW
                if profile.availability_impact < 0.25
                else ConsequenceSeverity.MEDIUM
                if profile.availability_impact < 0.50
                else ConsequenceSeverity.HIGH
            )

            consequences.append(
                PredictedConsequence(
                    impact_type=ImpactType.AVAILABILITY,
                    severity=severity,
                    probability=(
                        profile.availability_impact
                    ),
                    description=(
                        "The proposed action may "
                        "reduce availability of "
                        "the targeted resource."
                    ),
                    affected_assets=(
                        (action.target_id,)
                        if target
                        else ()
                    ),
                    positive=False,
                    evidence=(
                        "action_profile",
                    ),
                )
            )

        # --------------------------------------------------------
        # Privileged target
        # --------------------------------------------------------

        if (
            target is not None
            and target.privileged
        ):

            consequences.append(
                PredictedConsequence(
                    impact_type=ImpactType.IDENTITY,
                    severity=ConsequenceSeverity.HIGH,
                    probability=0.65,
                    description=(
                        "Target has privileged context; "
                        "incorrect response could create "
                        "significant operational impact."
                    ),
                    affected_assets=(
                        action.target_id,
                    ),
                    positive=False,
                    evidence=(
                        "privileged_target",
                    ),
                )
            )

        # --------------------------------------------------------
        # Critical asset
        # --------------------------------------------------------

        if (
            target is not None
            and target.criticality >= 0.80
        ):

            consequences.append(
                PredictedConsequence(
                    impact_type=ImpactType.BUSINESS,
                    severity=ConsequenceSeverity.HIGH,
                    probability=0.70,
                    description=(
                        "Target is business-critical; "
                        "response collateral impact "
                        "requires additional caution."
                    ),
                    affected_assets=(
                        action.target_id,
                    ),
                    positive=False,
                    evidence=(
                        "critical_asset",
                    ),
                )
            )

        return tuple(consequences)


# ================================================================
# METRIC CALCULATOR
# ================================================================

class SimulationMetricCalculator:

    def calculate(
        self,
        *,
        state: CyberSimulationState,
        action: SimulationAction,
        consequences: Sequence[
            PredictedConsequence
        ],
    ) -> SimulationMetrics:

        profile = ActionRiskProfiles.get(
            action.action_type
        )

        security_benefit = (
            profile.security_benefit
        )

        threat_reduction = (
            profile.threat_reduction
            if state.active_threats > 0
            else profile.threat_reduction * 0.40
        )

        operational_risk = (
            profile.operational_risk
        )

        collateral_risk = (
            profile.collateral_risk
        )

        availability_impact = (
            profile.availability_impact
        )

        # Increase risk for critical targets.
        target = next(
            (
                asset
                for asset in state.assets
                if asset.asset_id == action.target_id
            ),
            None,
        )

        if target is not None:

            if target.criticality >= 0.80:
                operational_risk = min(
                    1.0,
                    operational_risk + 0.15,
                )

                collateral_risk = min(
                    1.0,
                    collateral_risk + 0.15,
                )

            if target.privileged:
                operational_risk = min(
                    1.0,
                    operational_risk + 0.10,
                )

        # Unknown target reduces confidence.
        target_known = target is not None

        confidence = 0.85 if target_known else 0.45

        if state.active_threats == 0:
            confidence *= 0.85

        net_score = (
            security_benefit * 0.40
            + threat_reduction * 0.30
            - operational_risk * 0.15
            - collateral_risk * 0.10
            - availability_impact * 0.05
        )

        net_score = max(
            -1.0,
            min(1.0, net_score),
        )

        return SimulationMetrics(
            security_benefit=security_benefit,
            operational_risk=operational_risk,
            collateral_risk=collateral_risk,
            threat_reduction=threat_reduction,
            availability_impact=availability_impact,
            confidence=confidence,
            net_score=net_score,
        )


# ================================================================
# ALTERNATIVE GENERATOR
# ================================================================

class SimulationAlternativeGenerator:

    DEFAULT_ALTERNATIVES = {
        "isolate_endpoint": (
            (
                "block_ioc",
                "Block the known indicator instead "
                "of isolating the endpoint."
            ),
            (
                "collect_evidence",
                "Collect additional evidence before "
                "disrupting the endpoint."
            ),
            (
                "notify_security_team",
                "Notify the security team while "
                "maintaining current endpoint state."
            ),
        ),

        "disable_account": (
            (
                "revoke_session",
                "Revoke active sessions without "
                "fully disabling the identity."
            ),
            (
                "rotate_credential",
                "Rotate the credential while "
                "preserving account availability."
            ),
            (
                "notify_security_team",
                "Escalate to the security team "
                "without immediate account disablement."
            ),
        ),

        "modify_security_control": (
            (
                "notify_security_team",
                "Escalate the proposed control change "
                "for controlled handling."
            ),
            (
                "create_ticket",
                "Create a security change request "
                "without changing the control."
            ),
        ),
    }

    def generate(
        self,
        *,
        state: CyberSimulationState,
        action: SimulationAction,
    ) -> tuple[SimulationAlternative, ...]:

        raw_alternatives = (
            self.DEFAULT_ALTERNATIVES.get(
                action.action_type,
                (),
            )
        )

        results = []

        for alternative_type, description in (
            raw_alternatives
        ):

            profile = ActionRiskProfiles.get(
                alternative_type
            )

            target = next(
                (
                    asset
                    for asset in state.assets
                    if asset.asset_id
                    == action.target_id
                ),
                None,
            )

            security_benefit = (
                profile.security_benefit
            )

            operational_risk = (
                profile.operational_risk
            )

            collateral_risk = (
                profile.collateral_risk
            )

            if target is not None:

                if target.criticality >= 0.80:
                    operational_risk = min(
                        1.0,
                        operational_risk + 0.05,
                    )

            net_score = (
                security_benefit * 0.45
                - operational_risk * 0.30
                - collateral_risk * 0.25
            )

            results.append(
                SimulationAlternative(
                    alternative_id=(
                        f"alternative_{uuid4().hex}"
                    ),
                    action_type=alternative_type,
                    description=description,
                    security_benefit=security_benefit,
                    operational_risk=operational_risk,
                    collateral_risk=collateral_risk,
                    net_score=net_score,
                    rationale=(
                        "Alternative generated from "
                        "the action risk profile and "
                        "current simulated state."
                    ),
                )
            )

        return tuple(
            sorted(
                results,
                key=lambda item: item.net_score,
                reverse=True,
            )
        )


# ================================================================
# RECOMMENDATION ENGINE
# ================================================================

class SimulationRecommendationEngine:

    def recommend(
        self,
        metrics: SimulationMetrics,
    ) -> Recommendation:

        if metrics.confidence < 0.50:
            return Recommendation.REQUIRE_REVIEW

        if metrics.operational_risk >= 0.75:
            return Recommendation.AVOID

        if metrics.collateral_risk >= 0.75:
            return Recommendation.REQUIRE_REVIEW

        if metrics.net_score >= 0.45:
            return Recommendation.PROCEED

        if metrics.net_score >= 0.20:
            return Recommendation.PROCEED_WITH_CAUTION

        return Recommendation.REQUIRE_REVIEW


# ================================================================
# SIMULATION ENGINE
# ================================================================

class CyberSimulationEngine:

    def __init__(
        self,
        *,
        consequence_predictor: Optional[
            ConsequencePredictor
        ] = None,
        metric_calculator: Optional[
            SimulationMetricCalculator
        ] = None,
        alternative_generator: Optional[
            SimulationAlternativeGenerator
        ] = None,
        recommendation_engine: Optional[
            SimulationRecommendationEngine
        ] = None,
    ) -> None:

        self.consequence_predictor = (
            consequence_predictor
            or ConsequencePredictor()
        )

        self.metric_calculator = (
            metric_calculator
            or SimulationMetricCalculator()
        )

        self.alternative_generator = (
            alternative_generator
            or SimulationAlternativeGenerator()
        )

        self.recommendation_engine = (
            recommendation_engine
            or SimulationRecommendationEngine()
        )

    def simulate(
        self,
        *,
        state: CyberSimulationState,
        action: SimulationAction,
        mode: SimulationMode = SimulationMode.DRY_RUN,
    ) -> CyberSimulationResult:

        if state.tenant_id.strip() == "":
            raise ValueError(
                "Simulation state has no tenant."
            )

        consequences = (
            self.consequence_predictor.predict(
                state=state,
                action=action,
            )
        )

        metrics = (
            self.metric_calculator.calculate(
                state=state,
                action=action,
                consequences=consequences,
            )
        )

        alternatives = (
            self.alternative_generator.generate(
                state=state,
                action=action,
            )
        )

        recommendation = (
            self.recommendation_engine.recommend(
                metrics
            )
        )

        assumptions = (
            "Simulation does not call external "
            "security systems.",
            "Predictions are based only on supplied "
            "state and action information.",
            "Simulation results do not establish "
            "actual post-action state.",
        )

        limitations = (
            "External system behavior is not directly "
            "observed during simulation.",
            "Prediction confidence depends on "
            "state completeness.",
        )

        return CyberSimulationResult(
            simulation_id=(
                f"simulation_{uuid4().hex}"
            ),
            tenant_id=state.tenant_id,
            mode=mode,
            action=action,
            recommendation=recommendation,
            metrics=metrics,
            consequences=consequences,
            alternatives=alternatives,
            assumptions=assumptions,
            limitations=limitations,
            simulated_only=True,
            execution_performed=False,
            source_state_fingerprint=(
                SimulationStateFingerprint.generate(
                    state
                )
            ),
        )


# ================================================================
# SIMULATION-ONLY BOUNDARY
# ================================================================

class SimulationExecutionBoundary:

    """
    Hard safety boundary.

    Phase 16 is not allowed to execute a real response action.
    """

    @staticmethod
    def assert_simulation_only(
        result: CyberSimulationResult,
    ) -> None:

        if not result.simulated_only:
            raise RuntimeError(
                "Phase 16 violation: "
                "simulation result is not simulation-only."
            )

        if result.execution_performed:
            raise RuntimeError(
                "Phase 16 violation: "
                "external execution occurred."
            )


