def test_simulation_does_not_execute() -> None:

    state = build_test_state()

    action = SimulationAction.create(
        action_type="isolate_endpoint",
        target_id="endpoint-001",
        description=(
            "Simulate endpoint isolation."
        ),
    )

    engine = CyberSimulationEngine()

    result = engine.simulate(
        state=state,
        action=action,
    )

    SimulationExecutionBoundary.assert_simulation_only(
        result
    )

    assert result.simulated_only is True
    assert result.execution_performed is False


