# [dedup-fix] removed duplicate: from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from hashlib import sha256
from typing import Any, Mapping, Optional, Sequence
from uuid import uuid4


# ================================================================
# ENUMERATIONS
# ================================================================

# [CONSOLIDATED] VerificationStatus duplicate removed — canonical definition now at line 276.


class VerificationDimension(str, Enum):
    ACTION_ACCEPTANCE = "action_acceptance"
    TARGET_STATE = "target_state"
    THREAT_STATE = "threat_state"
    COLLATERAL_IMPACT = "collateral_impact"


class ObservationSourceType(str, Enum):
    CONNECTOR = "connector"
    API = "api"
    SENSOR = "sensor"
    POLL = "poll"
    UNKNOWN = "unknown"


# ================================================================
# EXPECTED STATE
# ================================================================

@dataclass(frozen=True)
class ExpectedState:
    target_id: str

    expected_attributes: Mapping[str, Any]

    expected_threat_state: Optional[str] = None

    prohibited_attributes: Mapping[str, Any] = field(
        default_factory=dict
    )

    maximum_collateral_impact: float = 0.0

    def __post_init__(self) -> None:
        if not self.target_id.strip():
            raise ValueError("target_id is required")

        if not 0.0 <= self.maximum_collateral_impact <= 1.0:
            raise ValueError(
                "maximum_collateral_impact must be between 0 and 1"
            )


