# ================================================================
# VERIFICATION EVIDENCE
# ================================================================

@dataclass(frozen=True)
class VerificationEvidence:
    evidence_id: str

    dimension: VerificationDimension

    source: str

    description: str

    observed_value: Any

    expected_value: Any

    reliable: bool

    timestamp: str

    metadata: Mapping[str, Any] = field(
        default_factory=dict
    )

    @property
    def passed(self) -> bool:
        # NOTE(auto-repair): the engine's aggregation logic
        # (checks_passed/checks_failed) reads evidence.passed, but that
        # was never a real field on this class -- it's folded into
        # metadata by _evidence() above.
        value = self.metadata.get("passed")
        return bool(value) if value is not None else self.reliable

    @property
    def tenant_id(self) -> Optional[str]:
        return self.metadata.get("tenant_id")

    @property
    def quality(self) -> Optional["VerificationEvidenceQuality"]:
        value = self.metadata.get("quality")
        return (
            VerificationEvidenceQuality(value)
            if value is not None
            else None
        )

    @property
    def authoritative(self) -> bool:
        return bool(self.metadata.get("authoritative", False))

    @property
    def verification_id(self) -> Optional[str]:
        return self.metadata.get("verification_id")

    @property
    def check_type(self) -> Optional["VerificationCheckType"]:
        value = self.metadata.get("check_type")
        return (
            VerificationCheckType(value)
            if value is not None
            else None
        )

    @property
    def observed_at(self) -> str:
        # Alias for the real field `timestamp`.
        return self.timestamp

    @property
    def value(self) -> Any:
        # Alias for the real field `observed_value`.
        return self.observed_value

    @property
    def expected(self) -> Any:
        # Alias for the real field `expected_value`.
        return self.expected_value

    @property
    def provenance(self) -> "Mapping[str, Any]":
        return {
            k: v
            for k, v in self.metadata.items()
            if k in ("mode", "connector_id")
        }

    @staticmethod
    def create(
        *,
        dimension: VerificationDimension,
        source: str,
        description: str,
        observed_value: Any,
        expected_value: Any,
        reliable: bool,
        timestamp: str,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> "VerificationEvidence":

        if not source.strip():
            raise ValueError("source is required")

        if not description.strip():
            raise ValueError(
                "description is required"
            )

        if not timestamp.strip():
            raise ValueError(
                "timestamp is required"
            )

        return VerificationEvidence(
            evidence_id=(
                f"verification_evidence_{uuid4().hex}"
            ),
            dimension=dimension,
            source=source,
            description=description,
            observed_value=observed_value,
            expected_value=expected_value,
            reliable=reliable,
            timestamp=timestamp,
            metadata=dict(metadata or {}),
        )
# --- preserved from VerificationEvidence (merged, not present in canonical host) ---
    def calculate_digest(self) -> str:
        payload = {
            "evidence_id": self.evidence_id,
            "tenant_id": self.tenant_id,
            "verification_id": self.verification_id,
            "check_type": self.check_type.value,
            "source": self.source,
            "observed_at": self.timestamp,
            "value": self.value,
            "expected": self.expected,
            "passed": self.passed,
            "quality": self.quality.value,
            "authoritative": self.authoritative,
            "provenance": dict(self.provenance),
        }

        canonical = json.dumps(
            payload,
            sort_keys=True,
            default=str,
            separators=(",", ":"),
        )

        return sha256(canonical.encode("utf-8")).hexdigest()

    @property
    def digest(self) -> Optional[str]:
        # NOTE(auto-repair): validate_integrity() below reads self.digest,
        # but there's no real digest field here -- metadata is where any
        # extra data (including a digest, if one is ever computed and
        # stored there) lives on this class.
        return self.metadata.get("digest")
# --- preserved from VerificationEvidence (merged, not present in canonical host) ---
    def validate_integrity(self) -> None:
        if self.digest and self.digest != self.calculate_digest():
            raise EvidenceIntegrityError(
                f"Evidence integrity check failed: {self.evidence_id}"
            )


