@dataclass(frozen=True)
class VerificationDimensionResult:
    dimension: VerificationDimension

    passed: bool

    confidence: float

    explanation: str

    evidence: tuple[
        VerificationEvidence, ...
    ] = ()

    def __post_init__(self) -> None:
        if not 0.0 <= self.confidence <= 1.0:
            raise ValueError(
                "confidence must be between 0 and 1"
            )


# ================================================================
# VERIFICATION RESULT
# ================================================================

@dataclass(frozen=True)
class CyberVerificationResult:
    verification_id: str

    tenant_id: str

    action_id: str

    target_id: str

    status: VerificationStatus

    confidence: float

    dimensions: tuple[
        VerificationDimensionResult, ...
    ]

    evidence: tuple[
        VerificationEvidence, ...
    ]

    verified_at: str

    state_fingerprint: str

    external_reference: Optional[str]

    actual_state_confirmed: bool

    threat_state_confirmed: bool

    collateral_impact_checked: bool

    verification_complete: bool

    metadata: Mapping[str, Any] = field(
        default_factory=dict
    )

    def __post_init__(self) -> None:
        if not self.tenant_id.strip():
            raise ValueError(
                "tenant_id is required"
            )

        if not self.action_id.strip():
            raise ValueError(
                "action_id is required"
            )

        if not self.target_id.strip():
            raise ValueError(
                "target_id is required"
            )

        if not 0.0 <= self.confidence <= 1.0:
            raise ValueError(
                "confidence must be between 0 and 1"
            )


# ================================================================
# STATE FINGERPRINT
# ================================================================

class VerificationStateFingerprint:

    @staticmethod
    def generate(
        observation: ActualStateObservation,
    ) -> str:

        normalized = (
            observation.target_id,
            tuple(
                sorted(
                    (
                        str(key),
                        repr(value),
                    )
                    for key, value
                    in observation.attributes.items()
                )
            ),
            observation.threat_state,
            observation.collateral_impact,
            observation.source_type.value,
            observation.source_name,
            observation.observed_at,
        )

        return sha256(
            repr(normalized).encode("utf-8")
        ).hexdigest()


# ================================================================
# ACTION ACCEPTANCE VERIFIER
# ================================================================

class ActionAcceptanceVerifier:

    def verify(
        self,
        response: ExternalActionResponse,
    ) -> VerificationDimensionResult:

        evidence = VerificationEvidence.create(
            dimension=(
                VerificationDimension.ACTION_ACCEPTANCE
            ),
            source=response.connector_name,
            description=(
                "External system action acceptance "
                "was evaluated."
            ),
            observed_value=response.accepted,
            expected_value=True,
            reliable=True,
            timestamp=response.observed_at,
            metadata={
                "response_code": response.response_code,
                "external_reference": (
                    response.external_reference
                ),
            },
        )

        if response.accepted:
            return VerificationDimensionResult(
                dimension=(
                    VerificationDimension.ACTION_ACCEPTANCE
                ),
                passed=True,
                confidence=0.90,
                explanation=(
                    "External system reported that "
                    "the action was accepted."
                ),
                evidence=(evidence,),
            )

        return VerificationDimensionResult(
            dimension=(
                VerificationDimension.ACTION_ACCEPTANCE
            ),
            passed=False,
            confidence=0.95,
            explanation=(
                "External system reported that "
                "the action was not accepted."
            ),
            evidence=(evidence,),
        )


# ================================================================
# TARGET STATE VERIFIER
# ================================================================

class TargetStateVerifier:

    def verify(
        self,
        *,
        expected: ExpectedState,
        observed: ActualStateObservation,
    ) -> VerificationDimensionResult:

        if expected.target_id != observed.target_id:
            evidence = VerificationEvidence.create(
                dimension=(
                    VerificationDimension.TARGET_STATE
                ),
                source=observed.source_name,
                description=(
                    "Observed target does not match "
                    "expected target."
                ),
                observed_value=observed.target_id,
                expected_value=expected.target_id,
                reliable=True,
                timestamp=observed.observed_at,
            )

            return VerificationDimensionResult(
                dimension=(
                    VerificationDimension.TARGET_STATE
                ),
                passed=False,
                confidence=0.99,
                explanation=(
                    "Target identity mismatch."
                ),
                evidence=(evidence,),
            )

        evidence_items = []

        missing = []

        for key, expected_value in (
            expected.expected_attributes.items()
        ):
            observed_value = observed.attributes.get(
                key
            )

            passed = (
                observed_value == expected_value
            )

            if not passed:
                missing.append(key)

            evidence_items.append(
                VerificationEvidence.create(
                    dimension=(
                        VerificationDimension.TARGET_STATE
                    ),
                    source=observed.source_name,
                    description=(
                        f"Target attribute '{key}' "
                        f"was checked."
                    ),
                    observed_value=observed_value,
                    expected_value=expected_value,
                    reliable=True,
                    timestamp=observed.observed_at,
                )
            )

        prohibited_found = []

        for key, prohibited_value in (
            expected.prohibited_attributes.items()
        ):
            observed_value = observed.attributes.get(
                key
            )

            if observed_value == prohibited_value:
                prohibited_found.append(key)

            evidence_items.append(
                VerificationEvidence.create(
                    dimension=(
                        VerificationDimension.TARGET_STATE
                    ),
                    source=observed.source_name,
                    description=(
                        f"Prohibited attribute '{key}' "
                        f"was checked."
                    ),
                    observed_value=observed_value,
                    expected_value=prohibited_value,
                    reliable=True,
                    timestamp=observed.observed_at,
                )
            )

        passed = (
            not missing
            and not prohibited_found
        )

        if passed:
            explanation = (
                "Observed target state matches "
                "the expected state."
            )
            confidence = 0.92
        else:
            explanation = (
                "Observed target state does not "
                "fully match the expected state."
            )
            confidence = 0.90

        return VerificationDimensionResult(
            dimension=(
                VerificationDimension.TARGET_STATE
            ),
            passed=passed,
            confidence=confidence,
            explanation=explanation,
            evidence=tuple(evidence_items),
        )


# ================================================================
# THREAT STATE VERIFIER
# ================================================================

class ThreatStateVerifier:

    def verify(
        self,
        *,
        expected: ExpectedState,
        observed: ActualStateObservation,
    ) -> VerificationDimensionResult:

        if expected.expected_threat_state is None:

            evidence = VerificationEvidence.create(
                dimension=(
                    VerificationDimension.THREAT_STATE
                ),
                source=observed.source_name,
                description=(
                    "No explicit expected threat "
                    "state was supplied."
                ),
                observed_value=observed.threat_state,
                expected_value=None,
                reliable=True,
                timestamp=observed.observed_at,
            )

            return VerificationDimensionResult(
                dimension=(
                    VerificationDimension.THREAT_STATE
                ),
                passed=True,
                confidence=0.60,
                explanation=(
                    "Threat state was observed but "
                    "no target state assertion was "
                    "provided."
                ),
                evidence=(evidence,),
            )

        passed = (
            observed.threat_state
            == expected.expected_threat_state
        )

        evidence = VerificationEvidence.create(
            dimension=(
                VerificationDimension.THREAT_STATE
            ),
            source=observed.source_name,
            description=(
                "Actual threat state was compared "
                "with the expected threat state."
            ),
            observed_value=observed.threat_state,
            expected_value=(
                expected.expected_threat_state
            ),
            reliable=True,
            timestamp=observed.observed_at,
        )

        return VerificationDimensionResult(
            dimension=(
                VerificationDimension.THREAT_STATE
            ),
            passed=passed,
            confidence=0.88 if passed else 0.93,
            explanation=(
                "Threat state matches expectation."
                if passed
                else
                "Threat state does not match "
                "expectation."
            ),
            evidence=(evidence,),
        )


# ================================================================
# COLLATERAL IMPACT VERIFIER
# ================================================================

class CollateralImpactVerifier:

    def verify(
        self,
        *,
        expected: ExpectedState,
        observed: ActualStateObservation,
    ) -> VerificationDimensionResult:

        passed = (
            observed.collateral_impact
            <= expected.maximum_collateral_impact
        )

        evidence = VerificationEvidence.create(
            dimension=(
                VerificationDimension.COLLATERAL_IMPACT
            ),
            source=observed.source_name,
            description=(
                "Observed collateral impact was "
                "compared with the permitted threshold."
            ),
            observed_value=(
                observed.collateral_impact
            ),
            expected_value=(
                expected.maximum_collateral_impact
            ),
            reliable=True,
            timestamp=observed.observed_at,
        )

        return VerificationDimensionResult(
            dimension=(
                VerificationDimension.COLLATERAL_IMPACT
            ),
            passed=passed,
            confidence=0.90,
            explanation=(
                "Collateral impact is within "
                "the expected threshold."
                if passed
                else
                "Collateral impact exceeds "
                "the expected threshold."
            ),
            evidence=(evidence,),
        )


# ================================================================
# VERIFICATION STATUS CALCULATOR
# ================================================================

class VerificationStatusCalculator:

    def calculate(
        self,
        dimensions: Sequence[
            VerificationDimensionResult
        ],
    ) -> tuple[
        VerificationStatus,
        float,
    ]:

        if not dimensions:
            return (
                VerificationStatus.INCONCLUSIVE,
                0.0,
            )

        passed = sum(
            1
            for item in dimensions
            if item.passed
        )

        total = len(dimensions)

        confidence = sum(
            item.confidence
            for item in dimensions
        ) / total

        if passed == total:
            return (
                VerificationStatus.VERIFIED,
                confidence,
            )

        if passed == 0:
            return (
                VerificationStatus.FAILED,
                confidence,
            )

        return (
            VerificationStatus.PARTIALLY_VERIFIED,
            confidence,
        )


# ================================================================
# VERIFICATION ENGINE
# ================================================================

class CyberVerificationEngine:

    def __init__(
        self,
        *,
        acceptance_verifier: Optional[
            ActionAcceptanceVerifier
        ] = None,
        target_verifier: Optional[
            TargetStateVerifier
        ] = None,
        threat_verifier: Optional[
            ThreatStateVerifier
        ] = None,
        collateral_verifier: Optional[
            CollateralImpactVerifier
        ] = None,
        status_calculator: Optional[
            VerificationStatusCalculator
        ] = None,
    ) -> None:

        self.acceptance_verifier = (
            acceptance_verifier
            or ActionAcceptanceVerifier()
        )

        self.target_verifier = (
            target_verifier
            or TargetStateVerifier()
        )

        self.threat_verifier = (
            threat_verifier
            or ThreatStateVerifier()
        )

        self.collateral_verifier = (
            collateral_verifier
            or CollateralImpactVerifier()
        )

        self.status_calculator = (
            status_calculator
            or VerificationStatusCalculator()
        )

    def verify(
        self,
        *,
        tenant_id: str,
        response: ExternalActionResponse,
        expected_state: ExpectedState,
        actual_state: ActualStateObservation,
        verified_at: str,
    ) -> CyberVerificationResult:

        if not tenant_id.strip():
            raise ValueError(
                "tenant_id is required"
            )

        if response.action_id.strip() == "":
            raise ValueError(
                "action_id is required"
            )

        if expected_state.target_id != actual_state.target_id:
            raise ValueError(
                "Expected and observed target IDs "
                "must match."
            )

        dimensions = (
            self.acceptance_verifier.verify(
                response
            ),
            self.target_verifier.verify(
                expected=expected_state,
                observed=actual_state,
            ),
            self.threat_verifier.verify(
                expected=expected_state,
                observed=actual_state,
            ),
            self.collateral_verifier.verify(
                expected=expected_state,
                observed=actual_state,
            ),
        )

        status, confidence = (
            self.status_calculator.calculate(
                dimensions
            )
        )

        evidence = tuple(
            evidence_item
            for dimension in dimensions
            for evidence_item in dimension.evidence
        )

        target_confirmed = (
            next(
                item
                for item in dimensions
                if item.dimension
                == VerificationDimension.TARGET_STATE
            ).passed
        )

        threat_confirmed = (
            next(
                item
                for item in dimensions
                if item.dimension
                == VerificationDimension.THREAT_STATE
            ).passed
        )

        collateral_checked = (
            any(
                item.dimension
                == VerificationDimension.COLLATERAL_IMPACT
                for item in dimensions
            )
        )

        complete = (
            status
            == VerificationStatus.VERIFIED
        )

        return CyberVerificationResult(
            verification_id=(
                f"verification_{uuid4().hex}"
            ),
            tenant_id=tenant_id,
            action_id=response.action_id,
            target_id=actual_state.target_id,
            status=status,
            confidence=confidence,
            dimensions=dimensions,
            evidence=evidence,
            verified_at=verified_at,
            state_fingerprint=(
                VerificationStateFingerprint.generate(
                    actual_state
                )
            ),
            external_reference=(
                response.external_reference
            ),
            actual_state_confirmed=(
                target_confirmed
            ),
            threat_state_confirmed=(
                threat_confirmed
            ),
            collateral_impact_checked=(
                collateral_checked
            ),
            verification_complete=complete,
        )


# ================================================================
# STRICT VERIFICATION BOUNDARY
# ================================================================

class VerificationBoundary:

    @staticmethod
    def assert_not_verified_without_state(
        result: CyberVerificationResult,
    ) -> None:

        if (
            result.verification_complete
            and not result.actual_state_confirmed
        ):
            raise RuntimeError(
                "Verification boundary violation: "
                "verification cannot be complete "
                "without actual target-state confirmation."
            )

    @staticmethod
    def assert_failed_state_is_not_success(
        result: CyberVerificationResult,
    ) -> None:

        if (
            result.status
            == VerificationStatus.FAILED
            and result.verification_complete
        ):
            raise RuntimeError(
                "Verification boundary violation: "
                "failed verification cannot be marked complete."
            )


