# ================================================================

def run_phase_17_tests() -> dict[str, Any]:

    tests = [
        test_successful_verification,
        test_action_acceptance_failure,
        test_actual_state_mismatch_fails_verification,
        test_threat_state_mismatch_detected,
        test_collateral_impact_is_checked,
        test_prohibited_state_is_detected,
        test_target_identity_mismatch_is_rejected,
        test_state_fingerprint_changes_when_actual_state_changes,
        test_evidence_is_attached,
        test_external_reference_is_preserved,
        test_verification_does_not_execute_any_action,
        test_no_false_success_after_threat_failure,
        test_confidence_is_bounded,
        test_tenant_is_preserved,
        test_unique_verification_ids,
        test_boundary_accepts_real_verified_state,
        test_missing_expected_threat_state_is_not_claimed_as_strong_verification,
        test_empty_tenant_rejected,
    ]

    passed = 0
    failures = []

    for test in tests:
        try:
            test()
            passed += 1
        except Exception as exc:
            failures.append(
                {
                    "test": test.__name__,
                    "error": (
                        f"{type(exc).__name__}: {exc}"
                    ),
                }
            )

    return {
        "phase": 17,
        "component": "Security Verification Engine",
        "total_tests": len(tests),
        "passed": passed,
        "failed": len(failures),
        "failures": failures,
        "status": (
            "PASS"
            if not failures
            else "FAIL"
        ),
    }


