# ================================================================
# BASE MEMORY
# ================================================================

@dataclass(frozen=True)
class CyberMemoryRecord:
    memory_id: str
    tenant_id: str
    memory_type: MemoryType
    created_at: str
    source: str
    content: Mapping[str, Any]
    confidence: float
    provenance: tuple[str, ...] = ()
    status: MemoryStatus = MemoryStatus.ACTIVE
    supersedes_memory_id: Optional[str] = None
    integrity_hash: str = ""

    def __post_init__(self) -> None:
        if not self.memory_id.strip():
            raise ValueError("memory_id is required")

        if not self.tenant_id.strip():
            raise ValueError("tenant_id is required")

        if not self.source.strip():
            raise ValueError("source is required")

        if not self.created_at.strip():
            raise ValueError("created_at is required")

        if not 0.0 <= self.confidence <= 1.0:
            raise ValueError(
                "confidence must be between 0 and 1"
            )
# --- preserved from CyberMemoryRecord (merged, not present in canonical host) ---
    @property
    def subject_id(self) -> Optional[str]:
        # NOTE(auto-repair): several call sites (store put/get/fingerprint,
        # older tests) read record.subject_id as if it were a top-level
        # field. It isn't (see remember() for why) -- it lives inside
        # content. This property keeps that older code working.
        return self.content.get("subject_id")

    @property
    def tags(self) -> "tuple[str, ...]":
        return tuple(self.content.get("tags", ()))

    @property
    def source_trust(self) -> "MemorySourceTrust":
        value = self.content.get("source_trust")
        return (
            MemorySourceTrust(value)
            if value is not None
            else MemorySourceTrust.SYSTEM
        )

    @property
    def importance(self) -> "MemoryImportance":
        value = self.content.get("importance")
        return (
            MemoryImportance(value)
            if value is not None
            else MemoryImportance.MEDIUM
        )

    @property
    def digest(self) -> str:
        # NOTE(auto-repair): alias for integrity_hash, the real field name;
        # some call sites still read/write it as `digest`.
        return self.integrity_hash
# --- preserved from CyberMemoryRecord (merged, not present in canonical host) ---
    def calculate_digest(self) -> str:
        # NOTE(auto-repair): now delegates to MemoryIntegrity.calculate()
        # instead of its own separate JSON-based canonicalization, since
        # CyberMemoryFactory.create() (a second, legitimate way to build a
        # CyberMemoryRecord) already sets integrity_hash using
        # MemoryIntegrity.calculate() directly -- two different hash
        # algorithms for the same field meant nothing verified consistently.
        return MemoryIntegrity.calculate(
            tenant_id=self.tenant_id,
            memory_id=self.memory_id,
            memory_type=self.memory_type,
            created_at=self.created_at,
            source=self.source,
            content=self.content,
            provenance=self.provenance,
        )
# --- preserved from CyberMemoryRecord (merged, not present in canonical host) ---
    def canonical_payload(self) -> Dict[str, Any]:
        # NOTE(auto-repair): was referencing self.subject_id/.observed_at/
        # .source_trust/.importance/.tags/.related_memory_ids -- none real
        # fields (see remember() above for why). Using this record's
        # actual fields instead.
        return {
            "memory_id": self.memory_id,
            "tenant_id": self.tenant_id,
            "memory_type": self.memory_type.value,
            "created_at": self.created_at,
            "source": self.source,
            "content": dict(self.content),
            "confidence": self.confidence,
            "provenance": list(self.provenance),
            "status": self.status.value,
        }
# --- preserved from CyberMemoryRecord (merged, not present in canonical host) ---
    def verify_integrity(self) -> None:
        if not self.integrity_hash:
            raise MemoryValidationError(
                f"Memory {self.memory_id} has no integrity digest."
            )

        if self.integrity_hash != self.calculate_digest():
            raise MemoryValidationError(
                f"Memory integrity failure: {self.memory_id}"
            )


