# ================================================================
# INTEGRITY
# ================================================================

class MemoryIntegrity:

    @staticmethod
    def calculate(
        *,
        tenant_id: str,
        memory_id: str,
        memory_type: MemoryType,
        created_at: str,
        source: str,
        content: Mapping[str, Any],
        provenance: Sequence[str],
    ) -> str:

        canonical = repr(
            (
                tenant_id,
                memory_id,
                memory_type.value,
                created_at,
                source,
                tuple(sorted(
                    (str(k), repr(v))
                    for k, v in content.items()
                )),
                tuple(provenance),
            )
        )

        return sha256(
            canonical.encode("utf-8")
        ).hexdigest()

    @staticmethod
    def verify(
        record: CyberMemoryRecord,
    ) -> bool:
        # NOTE(auto-repair): was recomputing a hash here with its own
        # repr()-based canonicalization, different from the one
        # CyberMemoryRecord.calculate_digest()/canonical_payload() actually
        # use to set integrity_hash when a record is stored -- the two
        # algorithms could never agree. Delegating to the record's own
        # method keeps there being exactly one integrity algorithm.
        return (
            record.integrity_hash != ""
            and record.integrity_hash
            == record.calculate_digest()
        )


# ================================================================
# MEMORY STORE
# ================================================================

class InMemoryCyberMemoryStore:

    def __init__(self) -> None:
        self._records: dict[str, CyberMemoryRecord] = {}

    def put(
        self,
        record: CyberMemoryRecord,
    ) -> CyberMemoryRecord:

        existing = self._records.get(
            record.memory_id
        )

        if existing is not None:
            if existing != record:
                raise ValueError(
                    "Memory ID already exists with "
                    "different content."
                )

            return existing

        if not MemoryIntegrity.verify(record):
            raise ValueError(
                "Memory integrity verification failed."
            )

        self._records[
            record.memory_id
        ] = record

        return record

    def get(
        self,
        tenant_id: str,
        memory_id: str,
    ) -> Optional[CyberMemoryRecord]:

        record = self._records.get(memory_id)

        if record is None:
            return None

        if record.tenant_id != tenant_id:
            return None

        return record

    def query(
        self,
        tenant_id: str,
        *,
        memory_type: Optional[MemoryType] = None,
        subject_id: Optional[str] = None,
        limit: int = 100,
    ) -> tuple[CyberMemoryRecord, ...]:

        if limit <= 0:
            raise ValueError(
                "limit must be greater than zero"
            )

        results = []

        for record in self._records.values():

            if record.tenant_id != tenant_id:
                continue

            if (
                memory_type is not None
                and record.memory_type != memory_type
            ):
                continue

            if subject_id is not None:
                stored_subject = record.content.get(
                    "subject_id"
                )

                if stored_subject != subject_id:
                    continue

            results.append(record)

        results.sort(
            key=lambda item: (
                item.created_at,
                item.memory_id,
            ),
            reverse=True,
        )

        return tuple(results[:limit])

    def all_for_tenant(
        self,
        tenant_id: str,
    ) -> tuple[CyberMemoryRecord, ...]:

        return tuple(
            record
            for record in self._records.values()
            if record.tenant_id == tenant_id
        )


# ================================================================
# MEMORY FACTORY
# ================================================================

class CyberMemoryFactory:

    @staticmethod
    def create(
        *,
        tenant_id: str,
        memory_type: MemoryType,
        source: str,
        created_at: str,
        content: Mapping[str, Any],
        confidence: float,
        provenance: Sequence[str] = (),
        supersedes_memory_id: Optional[str] = None,
    ) -> CyberMemoryRecord:

        memory_id = (
            f"memory_{uuid4().hex}"
        )

        integrity_hash = (
            MemoryIntegrity.calculate(
                tenant_id=tenant_id,
                memory_id=memory_id,
                memory_type=memory_type,
                created_at=created_at,
                source=source,
                content=content,
                provenance=provenance,
            )
        )

        return CyberMemoryRecord(
            memory_id=memory_id,
            tenant_id=tenant_id,
            memory_type=memory_type,
            created_at=created_at,
            source=source,
            content=dict(content),
            confidence=confidence,
            provenance=tuple(provenance),
            supersedes_memory_id=(
                supersedes_memory_id
            ),
            integrity_hash=integrity_hash,
        )


# ================================================================
# MEMORY MANAGER
# ================================================================

class CyberMemoryManager:

    def __init__(
        self,
        store: Optional[
            InMemoryCyberMemoryStore
        ] = None,
    ) -> None:

        self.store = (
            store
            or InMemoryCyberMemoryStore()
        )

    def remember(
        self,
        *,
        tenant_id: str,
        memory_type: MemoryType,
        source: str,
        created_at: str,
        content: Mapping[str, Any],
        confidence: float,
        provenance: Sequence[str] = (),
    ) -> CyberMemoryRecord:

        record = CyberMemoryFactory.create(
            tenant_id=tenant_id,
            memory_type=memory_type,
            source=source,
            created_at=created_at,
            content=content,
            confidence=confidence,
            provenance=provenance,
        )

        return self.store.put(record)

    def retrieve_related(
        self,
        *,
        tenant_id: str,
        subject_id: str,
        limit: int = 20,
    ) -> tuple[CyberMemoryRecord, ...]:

        return self.store.query(
            tenant_id,
            subject_id=subject_id,
            limit=limit,
        )

    def verify_memory(
        self,
        *,
        tenant_id: str,
        memory_id: str,
    ) -> bool:

        record = self.store.get(
            tenant_id,
            memory_id,
        )

        if record is None:
            return False

        return MemoryIntegrity.verify(record)


# ================================================================
# VARIANCE ENGINE
# ================================================================

class LearningVarianceEngine:

    @staticmethod
    def compare(
        prediction: Prediction,
        outcome: OutcomeMemory,
        evaluated_at: str,
    ) -> OutcomeComparison:

        variances = []

        keys = set(
            prediction.expected_result.keys()
        ) | set(
            outcome.actual.keys()
        )

        for key in sorted(keys):

            expected = (
                prediction.expected_result.get(key)
            )

            actual = outcome.actual.get(key)

            numeric_delta = None

            if (
                isinstance(expected, (int, float))
                and isinstance(actual, (int, float))
            ):
                numeric_delta = (
                    float(actual) - float(expected)
                )

                magnitude = abs(
                    numeric_delta
                )

            else:
                magnitude = (
                    0.0
                    if expected == actual
                    else 1.0
                )

            variances.append(
                Variance(
                    field=key,
                    expected=expected,
                    actual=actual,
                    numeric_delta=numeric_delta,
                    magnitude=magnitude,
                )
            )

        if not variances:
            total_variance = 0.0
        else:
            total_variance = (
                sum(
                    item.magnitude
                    for item in variances
                )
                / len(variances)
            )

        prediction_quality = max(
            0.0,
            1.0 - min(
                1.0,
                total_variance,
            ),
        )

        return OutcomeComparison(
            prediction_id=prediction.prediction_id,
            outcome_id=outcome.outcome_id,
            variances=tuple(variances),
            total_variance=total_variance,
            prediction_quality=prediction_quality,
            evaluated_at=evaluated_at,
        )


# ================================================================
# LESSON EXTRACTOR
# ================================================================

class LessonExtractor:

    def extract(
        self,
        *,
        tenant_id: str,
        comparison: OutcomeComparison,
        source_memory_ids: Sequence[str],
        created_at: str,
    ) -> Optional[CyberMemoryRecord]:

        if not source_memory_ids:
            raise ValueError(
                "source_memory_ids are required"
            )

        if comparison.total_variance <= 0.0:
            return None

        significant = [
            variance
            for variance in comparison.variances
            if variance.magnitude > 0.0
        ]

        if not significant:
            return None

        fields = ", ".join(
            item.field
            for item in significant
        )

        statement = (
            "Prediction variance was observed "
            f"in fields: {fields}."
        )

        confidence = max(
            0.10,
            min(
                0.95,
                1.0 - comparison.total_variance,
            ),
        )

        return CyberMemoryFactory.create(
            tenant_id=tenant_id,
            memory_type=MemoryType.LESSON,
            source="phase18-learning-engine",
            created_at=created_at,
            content={
                "lesson_id": (
                    f"lesson_{uuid4().hex}"
                ),
                "source_memory_ids": tuple(
                    source_memory_ids
                ),
                "statement": statement,
                "prediction_quality": (
                    comparison.prediction_quality
                ),
                "total_variance": (
                    comparison.total_variance
                ),
            },
            confidence=confidence,
            provenance=source_memory_ids,
        )


# ================================================================
# LEARNING CANDIDATE GENERATOR
# ================================================================

class LearningCandidateGenerator:

    def generate(
        self,
        *,
        tenant_id: str,
        lesson: CyberMemoryRecord,
        update_type: LearningUpdateType,
        target: str,
        proposed_change: Mapping[str, Any],
        expected_benefit: float,
        operational_risk: float,
        created_at: str,
    ) -> LearningCandidate:

        if lesson.memory_type != MemoryType.LESSON:
            raise ValueError(
                "Candidate generation requires "
                "a lesson memory."
            )

        return LearningCandidate(
            candidate_id=(
                f"learning_candidate_{uuid4().hex}"
            ),
            tenant_id=tenant_id,
            update_type=update_type,
            target=target,
            proposed_change=dict(
                proposed_change
            ),
            rationale=str(
                lesson.content.get(
                    "statement",
                    "Learning-derived improvement.",
                )
            ),
            source_memory_ids=(
                lesson.provenance
                + (lesson.memory_id,)
            ),
            expected_benefit=expected_benefit,
            operational_risk=operational_risk,
            status=(
                LearningCandidateStatus.PROPOSED
            ),
            created_at=created_at,
        )


# ================================================================
# LEARNING EVALUATOR
# ================================================================

class LearningCandidateEvaluator:

    def evaluate(
        self,
        candidate: LearningCandidate,
        *,
        evaluated_at: str,
    ) -> LearningCandidate:

        if (
            candidate.status
            not in (
                LearningCandidateStatus.PROPOSED,
                LearningCandidateStatus.EVALUATED,
            )
        ):
            raise ValueError(
                "Only proposed candidates can "
                "be evaluated."
            )

        return replace(
            candidate,
            status=LearningCandidateStatus.EVALUATED,
            evaluated_at=evaluated_at,
        )


# ================================================================
# EXPLICIT APPROVAL GATE
# ================================================================

class LearningApprovalGate:

    def approve(
        self,
        candidate: LearningCandidate,
        *,
        approved_by: str,
        approved_at: str,
    ) -> LearningCandidate:

        if not approved_by.strip():
            raise ValueError(
                "approved_by is required"
            )

        if (
            candidate.status
            != LearningCandidateStatus.EVALUATED
        ):
            raise ValueError(
                "Candidate must be evaluated "
                "before approval."
            )

        return replace(
            candidate,
            status=LearningCandidateStatus.APPROVED,
            approved_at=approved_at,
            approved_by=approved_by,
        )

    def reject(
        self,
        candidate: LearningCandidate,
    ) -> LearningCandidate:

        if (
            candidate.status
            != LearningCandidateStatus.EVALUATED
        ):
            raise ValueError(
                "Candidate must be evaluated "
                "before rejection."
            )

        return replace(
            candidate,
            status=LearningCandidateStatus.REJECTED,
        )


# ================================================================
# PRODUCTION UPDATE BOUNDARY
# ================================================================

class ProductionLearningBoundary:

    @staticmethod
    def assert_not_autonomously_applicable(
        candidate: LearningCandidate,
    ) -> None:

        if (
            candidate.status
            != LearningCandidateStatus.APPROVED
        ):
            raise PermissionError(
                "Learning candidate cannot be "
                "applied without explicit approval."
            )

    @staticmethod
    def require_explicit_approval(
        candidate: LearningCandidate,
    ) -> None:

        if (
            not candidate.approved_by
            or not candidate.approved_at
        ):
            raise PermissionError(
                "Production learning update requires "
                "explicit human approval."
            )


