@dataclass(frozen=True)
class VerificationContext:
    tenant_id: str
    verification_id: str
    execution_id: str
    action_id: str
    target_id: str
    connector_id: str
    requested_at: datetime
    correlation_id: str

    def validate(self) -> None:
        fields = {
            "tenant_id": self.tenant_id,
            "verification_id": self.verification_id,
            "execution_id": self.execution_id,
            "action_id": self.action_id,
            "target_id": self.target_id,
            "connector_id": self.connector_id,
            "correlation_id": self.correlation_id,
        }

        for name, value in fields.items():
            if not value or not value.strip():
                raise InvalidVerificationRequest(
                    f"{name} must be non-empty"
                )




@dataclass
class VerificationResult:
    verification_id: str
    tenant_id: str
    execution_id: str
    action_id: str
    target_id: str

    status: VerificationStatus = VerificationStatus.PENDING

    checks_total: int = 0
    checks_passed: int = 0
    checks_failed: int = 0

    evidence: list[VerificationEvidence] = field(default_factory=list)

    started_at: Optional[datetime] = None
    completed_at: Optional[datetime] = None

    confidence: float = 0.0
    reason: str = ""

    metadata: Dict[str, Any] = field(default_factory=dict)

    @property
    def evidence_count(self) -> int:
        return len(self.evidence)

    @property
    def authoritative_evidence_count(self) -> int:
        return sum(
            1 for item in self.evidence
            if item.authoritative
        )


# ============================================================
# EXTERNAL VERIFICATION CONTRACT
# ============================================================

class VerificationAdapter:
    """
    Connector-specific verification interface.

    Phase 19 never assumes that an action succeeded merely because
    an execution request returned successfully.
    """

    connector_id: str = ""

    def verify_external_response(
        self,
        *,
        context: VerificationContext,
        execution_response: Mapping[str, Any],
    ) -> VerificationEvidence:
        raise NotImplementedError

    def check_actual_state(
        self,
        *,
        context: VerificationContext,
        expected_state: Mapping[str, Any],
    ) -> VerificationEvidence:
        raise NotImplementedError

    def check_threat_state(
        self,
        *,
        context: VerificationContext,
        expected_threat_state: Mapping[str, Any],
    ) -> VerificationEvidence:
        raise NotImplementedError

    def check_collateral_impact(
        self,
        *,
        context: VerificationContext,
        baseline: Mapping[str, Any],
        expected: Mapping[str, Any],
    ) -> VerificationEvidence:
        raise NotImplementedError


# ============================================================
# SAFE SIMULATOR FOR TESTING
# ============================================================

class VerificationSimulator(VerificationAdapter):
    """
    Deterministic local adapter.

    It is explicitly a simulator and never claims to have verified
    a real external system.
    """

    connector_id = "verification-simulator"

    def __init__(
        self,
        *,
        actual_state: Optional[Mapping[str, Any]] = None,
        threat_state: Optional[Mapping[str, Any]] = None,
        collateral_state: Optional[Mapping[str, Any]] = None,
    ):
        self.actual_state = dict(actual_state or {})
        self.threat_state = dict(threat_state or {})
        self.collateral_state = dict(collateral_state or {})

    @staticmethod
    def _evidence(
        *,
        context: VerificationContext,
        check_type: VerificationCheckType,
        value: Any,
        expected: Any,
        passed: bool,
        quality: VerificationEvidenceQuality,
        authoritative: bool = False,
    ) -> VerificationEvidence:
        # NOTE(auto-repair): was constructing VerificationEvidence with
        # tenant_id=/verification_id=/check_type=/observed_at=/value=/
        # expected=/passed=/quality=/authoritative=/digest=, none of which
        # are real fields (real ones: evidence_id/dimension/source/
        # description/observed_value/expected_value/reliable/timestamp/
        # metadata) -- every call failed immediately, and it also called a
        # calculate_digest() method this class doesn't have. checks_passed/
        # checks_failed below need a real .passed attribute (see the
        # `passed` property added to this class), so the extra fields are
        # folded into metadata instead of dropped.

        now = datetime.now(timezone.utc)

        dimension = {
            VerificationCheckType.EXTERNAL_RESPONSE: (
                VerificationDimension.ACTION_ACCEPTANCE
            ),
            VerificationCheckType.STATE_CHECK: (
                VerificationDimension.TARGET_STATE
            ),
            VerificationCheckType.THREAT_STATE_CHECK: (
                VerificationDimension.THREAT_STATE
            ),
            VerificationCheckType.COLLATERAL_IMPACT_CHECK: (
                VerificationDimension.COLLATERAL_IMPACT
            ),
        }.get(check_type, VerificationDimension.TARGET_STATE)

        evidence = VerificationEvidence(
            evidence_id=f"VE-{uuid.uuid4().hex}",
            dimension=dimension,
            source="verification-simulator",
            description=f"{check_type.value} check",
            observed_value=value,
            expected_value=expected,
            reliable=authoritative or quality
            in (
                VerificationEvidenceQuality.HIGH,
                VerificationEvidenceQuality.MEDIUM,
            ),
            timestamp=now.isoformat(),
            metadata={
                "tenant_id": context.tenant_id,
                "verification_id": context.verification_id,
                "check_type": check_type.value,
                "passed": passed,
                "quality": quality.value,
                "authoritative": authoritative,
                "mode": "SIMULATION",
                "connector_id": context.connector_id,
            },
        )

        return VerificationEvidence(
            **{
                **evidence.__dict__,
                "metadata": {
                    **evidence.metadata,
                    "digest": evidence.calculate_digest(),
                },
            }
        )

    def verify_external_response(
        self,
        *,
        context: VerificationContext,
        execution_response: Mapping[str, Any],
    ) -> VerificationEvidence:

        accepted = execution_response.get("accepted") is True

        return self._evidence(
            context=context,
            check_type=VerificationCheckType.EXTERNAL_RESPONSE,
            value=execution_response,
            expected={"accepted": True},
            passed=accepted,
            quality=VerificationEvidenceQuality.MEDIUM,
        )

    def check_actual_state(
        self,
        *,
        context: VerificationContext,
        expected_state: Mapping[str, Any],
    ) -> VerificationEvidence:

        matches = all(
            self.actual_state.get(key) == expected
            for key, expected in expected_state.items()
        )

        return self._evidence(
            context=context,
            check_type=VerificationCheckType.STATE_CHECK,
            value=self.actual_state,
            expected=dict(expected_state),
            passed=matches,
            quality=VerificationEvidenceQuality.MEDIUM,
        )

    def check_threat_state(
        self,
        *,
        context: VerificationContext,
        expected_threat_state: Mapping[str, Any],
    ) -> VerificationEvidence:

        matches = all(
            self.threat_state.get(key) == expected
            for key, expected in expected_threat_state.items()
        )

        return self._evidence(
            context=context,
            check_type=VerificationCheckType.THREAT_STATE_CHECK,
            value=self.threat_state,
            expected=dict(expected_threat_state),
            passed=matches,
            quality=VerificationEvidenceQuality.MEDIUM,
        )

    def check_collateral_impact(
        self,
        *,
        context: VerificationContext,
        baseline: Mapping[str, Any],
        expected: Mapping[str, Any],
    ) -> VerificationEvidence:

        changed = {
            key: self.collateral_state.get(key)
            for key in baseline
            if self.collateral_state.get(key) != baseline.get(key)
        }

        allowed = all(
            changed.get(key) == expected_value
            for key, expected_value in expected.items()
        )

        return self._evidence(
            context=context,
            check_type=VerificationCheckType.COLLATERAL_IMPACT_CHECK,
            value=changed,
            expected=dict(expected),
            passed=allowed,
            quality=VerificationEvidenceQuality.MEDIUM,
        )


# ============================================================
# VERIFICATION ENGINE
# ============================================================

class SecurityVerificationEngine:
    """
    Phase 19 canonical verification engine.

    Core rule:

        execution response != successful security outcome

    The engine requires post-execution evidence before declaring
    an action VERIFIED.
    """

    VERSION = "19.0.0"

    def __init__(
        self,
        *,
        adapters: Optional[Mapping[str, VerificationAdapter]] = None,
        clock: Callable[[], datetime] = lambda: datetime.now(timezone.utc),
    ):
        self._adapters: Dict[str, VerificationAdapter] = dict(
            adapters or {}
        )
        self._clock = clock

    def register_adapter(
        self,
        connector_id: str,
        adapter: VerificationAdapter,
    ) -> None:

        if not connector_id.strip():
            raise ValueError("connector_id must be non-empty")

        if connector_id in self._adapters:
            raise ValueError(
                f"Verification adapter already registered: {connector_id}"
            )

        self._adapters[connector_id] = adapter

    def get_adapter(
        self,
        connector_id: str,
    ) -> VerificationAdapter:

        adapter = self._adapters.get(connector_id)

        if adapter is None:
            raise VerificationTargetUnavailable(
                f"No verification adapter registered for: {connector_id}"
            )

        return adapter

    def verify(
        self,
        *,
        context: VerificationContext,
        execution_response: Mapping[str, Any],
        expected_state: Mapping[str, Any],
        expected_threat_state: Mapping[str, Any],
        baseline_collateral_state: Mapping[str, Any],
        expected_collateral_state: Mapping[str, Any],
        timeout_seconds: float = 30.0,
    ) -> VerificationResult:

        context.validate()

        if timeout_seconds <= 0:
            raise InvalidVerificationRequest(
                "timeout_seconds must be greater than zero"
            )

        result = VerificationResult(
            verification_id=context.verification_id,
            tenant_id=context.tenant_id,
            execution_id=context.execution_id,
            action_id=context.action_id,
            target_id=context.target_id,
            status=VerificationStatus.RUNNING,
            started_at=self._clock(),
        )

        adapter = self.get_adapter(context.connector_id)

        started_monotonic = time.monotonic()

        checks = (
            lambda: adapter.verify_external_response(
                context=context,
                execution_response=execution_response,
            ),
            lambda: adapter.check_actual_state(
                context=context,
                expected_state=expected_state,
            ),
            lambda: adapter.check_threat_state(
                context=context,
                expected_threat_state=expected_threat_state,
            ),
            lambda: adapter.check_collateral_impact(
                context=context,
                baseline=baseline_collateral_state,
                expected=expected_collateral_state,
            ),
        )

        for check in checks:
            if time.monotonic() - started_monotonic > timeout_seconds:
                result.status = VerificationStatus.FAILED
                result.reason = "Verification timeout"
                result.completed_at = self._clock()
                raise VerificationTimeout(
                    f"Verification exceeded {timeout_seconds}s"
                )

            evidence = check()
            evidence.validate_integrity()

            result.evidence.append(evidence)

        result.checks_total = len(result.evidence)
        result.checks_passed = sum(
            1 for item in result.evidence if item.passed
        )
        result.checks_failed = (
            result.checks_total - result.checks_passed
        )

        result.confidence = self._calculate_confidence(result)

        if result.checks_total == 0:
            result.status = VerificationStatus.UNKNOWN
            result.reason = "No verification evidence produced"

        elif result.checks_failed == 0:
            result.status = VerificationStatus.VERIFIED
            result.reason = (
                "All required post-execution verification checks passed."
            )

        elif result.checks_passed > 0:
            result.status = VerificationStatus.PARTIALLY_VERIFIED
            result.reason = (
                "Some verification checks passed while others failed."
            )

        else:
            result.status = VerificationStatus.FAILED
            result.reason = (
                "All post-execution verification checks failed."
            )

        result.completed_at = self._clock()

        return result

    @staticmethod
    def _calculate_confidence(
        result: VerificationResult,
    ) -> float:

        if not result.evidence:
            return 0.0

        weighted_total = 0.0
        passed_total = 0.0

        weights = {
            VerificationEvidenceQuality.NONE: 0.0,
            VerificationEvidenceQuality.LOW: 0.25,
            VerificationEvidenceQuality.MEDIUM: 0.50,
            VerificationEvidenceQuality.HIGH: 0.80,
            VerificationEvidenceQuality.AUTHORITATIVE: 1.0,
        }

        for evidence in result.evidence:
            weight = weights[evidence.quality]

            if evidence.authoritative:
                weight = max(weight, 1.0)

            weighted_total += weight

            if evidence.passed:
                passed_total += weight

        if weighted_total == 0:
            return 0.0

        return round(
            min(1.0, max(0.0, passed_total / weighted_total)),
            4,
        )


