def run_phase_20_tests() -> Dict[str, Any]:

    tests = [
        test_memory_round_trip,
        test_memory_is_tenant_isolated,
        test_duplicate_memory_is_rejected,
        test_memory_integrity_digest,
        test_outcome_variance_is_detected,
        test_successful_outcome_creates_lesson,
        test_candidate_requires_valid_risk,
        test_candidate_requires_explicit_approval,
        test_approved_candidate_still_cannot_mutate_production,
        test_analyst_correction_is_high_trust_memory,
    ]

    passed = 0
    failures: List[Dict[str, str]] = []

    for test in tests:
        try:
            test()
            passed += 1
        except Exception as exc:
            failures.append(
                {
                    "test": test.__name__,
                    "error": f"{type(exc).__name__}: {exc}",
                }
            )

    return {
        "phase": 20,
        "component": "Cyber Memory & Learning Engine",
        "version": CyberMemoryLearningEngine.VERSION,
        "total_tests": len(tests),
        "passed": passed,
        "failed": len(failures),
        "status": "PASS" if not failures else "FAIL",
        "failures": failures,
    }


