# ============================================================
# TENANT ISOLATION
# ============================================================

@dataclass(frozen=True)
class TenantContext:
    tenant_id: str
    actor_id: str
    session_id: Optional[str] = None
    request_id: Optional[str] = None




class TenantIsolation:
    """
    Enforces tenant boundaries.

    Every protected object must carry a tenant_id.
    Cross-tenant access is denied by default.
    """

    def __init__(self) -> None:
        self._tenant_objects: Dict[str, Dict[str, Any]] = {}
        self._lock = threading.RLock()

    def register(
        self,
        tenant_id: str,
        object_id: str,
        value: Any,
    ) -> None:
        if not tenant_id:
            raise ValueError("tenant_id is required")

        with self._lock:
            self._tenant_objects.setdefault(tenant_id, {})[
                object_id
            ] = value

    def exists(self, tenant_id: str, object_id: str) -> bool:
        with self._lock:
            return object_id in self._tenant_objects.get(tenant_id, {})

    def get(
        self,
        context: TenantContext,
        object_id: str,
    ) -> Any:
        with self._lock:
            tenant_data = self._tenant_objects.get(context.tenant_id)

            if tenant_data is None:
                raise TenantIsolationError("Tenant does not exist")

            if object_id not in tenant_data:
                raise TenantIsolationError(
                    "Cross-tenant or unauthorized object access"
                )

            return tenant_data[object_id]

    def delete(
        self,
        context: TenantContext,
        object_id: str,
    ) -> None:
        with self._lock:
            if object_id not in self._tenant_objects.get(
                context.tenant_id, {}
            ):
                raise TenantIsolationError(
                    "Cross-tenant delete denied"
                )

            del self._tenant_objects[context.tenant_id][object_id]

    def list_tenant_objects(
        self,
        context: TenantContext,
    ) -> Dict[str, Any]:
        with self._lock:
            return dict(
                self._tenant_objects.get(context.tenant_id, {})
            )


# ============================================================
# RBAC
# ============================================================



class RBAC:
    """
    Role-Based Access Control.
    """

    def __init__(self) -> None:
        self.roles: Dict[str, Role] = {}
        self.user_roles: Dict[str, Set[str]] = {}
        self._lock = threading.RLock()

    def create_role(
        self,
        name: str,
        permissions: Iterable[str],
    ) -> Role:
        if not name:
            raise ValueError("Role name required")

        role = Role(
            role_id=f"role_{uuid.uuid4().hex}",
            name=name,
            permissions=frozenset(permissions),
        )

        with self._lock:
            self.roles[name] = role

        return role

    def assign_role(
        self,
        actor_id: str,
        role_name: str,
    ) -> None:
        with self._lock:
            if role_name not in self.roles:
                raise KeyError("Unknown role")

            self.user_roles.setdefault(actor_id, set()).add(
                role_name
            )

    def revoke_role(
        self,
        actor_id: str,
        role_name: str,
    ) -> None:
        with self._lock:
            self.user_roles.get(actor_id, set()).discard(
                role_name
            )

    def roles_for(self, actor_id: str) -> Set[str]:
        with self._lock:
            return set(self.user_roles.get(actor_id, set()))

    def permissions_for(self, actor_id: str) -> Set[str]:
        permissions: Set[str] = set()

        with self._lock:
            for role_name in self.user_roles.get(actor_id, set()):
                role = self.roles.get(role_name)

                if role:
                    permissions.update(role.permissions)

        return permissions

    def has_permission(
        self,
        actor_id: str,
        permission: str,
    ) -> bool:
        return permission in self.permissions_for(actor_id)


# ============================================================
# ABAC
# ============================================================

@dataclass
class AccessAttributes:
    actor: Dict[str, Any] = field(default_factory=dict)
    resource: Dict[str, Any] = field(default_factory=dict)
    action: str = ""
    environment: Dict[str, Any] = field(default_factory=dict)


@dataclass
class ABACRule:
    name: str
    effect: Decision
    condition: Any


class ABAC:
    """
    Attribute-Based Access Control.

    Conditions are Python callables:

        lambda attrs: attrs.actor["department"] == "security"
    """

    def __init__(self) -> None:
        self.rules: List[ABACRule] = []
        self._lock = threading.RLock()

    def add_rule(
        self,
        name: str,
        effect: Decision,
        condition: Any,
    ) -> None:
        with self._lock:
            self.rules.append(
                ABACRule(
                    name=name,
                    effect=effect,
                    condition=condition,
                )
            )

    def evaluate(
        self,
        attributes: AccessAttributes,
    ) -> Decision:
        with self._lock:
            for rule in self.rules:
                try:
                    matched = bool(rule.condition(attributes))
                except Exception:
                    matched = False

                if matched:
                    return rule.effect

        return Decision.DENY


