# ============================================================
# SECRETS VAULT
# ============================================================

@dataclass
class SecretRecord:
    secret_id: str
    tenant_id: str
    version: int
    ciphertext: str
    created_at: float
    rotated_at: Optional[float] = None


class SecretsVault:
    """
    In-memory encrypted secret vault.

    Production deployment can replace storage with a dedicated
    KMS/HSM/Vault backend while retaining this interface.
    """

    def __init__(self) -> None:
        self._records: Dict[Tuple[str, str], SecretRecord] = {}
        self._keys: Dict[str, bytes] = {}
        self._lock = threading.RLock()

    def _tenant_key(self, tenant_id: str) -> bytes:
        with self._lock:
            if tenant_id not in self._keys:
                self._keys[tenant_id] = secrets.token_bytes(32)

            return self._keys[tenant_id]

    @staticmethod
    def _crypt(
        plaintext: bytes,
        key: bytes,
    ) -> bytes:
        """
        Lightweight authenticated stream construction.

        For production cryptographic deployment, replace this primitive
        with a vetted AEAD implementation such as AES-GCM/ChaCha20-Poly1305.
        """
        nonce = secrets.token_bytes(16)

        keystream = bytearray()

        counter = 0
        while len(keystream) < len(plaintext):
            block = hashlib.sha256(
                key
                + nonce
                + counter.to_bytes(8, "big")
            ).digest()

            keystream.extend(block)
            counter += 1

        ciphertext = bytes(
            a ^ b
            for a, b in zip(
                plaintext,
                keystream[:len(plaintext)],
            )
        )

        tag = hmac.new(
            key,
            nonce + ciphertext,
            hashlib.sha256,
        ).digest()

        return nonce + tag + ciphertext

    @classmethod
    def _decrypt(
        cls,
        encrypted: bytes,
        key: bytes,
    ) -> bytes:
        nonce = encrypted[:16]
        tag = encrypted[16:48]
        ciphertext = encrypted[48:]

        expected = hmac.new(
            key,
            nonce + ciphertext,
            hashlib.sha256,
        ).digest()

        if not secure_compare(
            base64.b64encode(tag).decode(),
            base64.b64encode(expected).decode(),
        ):
            raise PermissionError("Secret integrity check failed")

        keystream = bytearray()
        counter = 0

        while len(keystream) < len(ciphertext):
            block = hashlib.sha256(
                key
                + nonce
                + counter.to_bytes(8, "big")
            ).digest()

            keystream.extend(block)
            counter += 1

        return bytes(
            a ^ b
            for a, b in zip(
                ciphertext,
                keystream[:len(ciphertext)],
            )
        )

    def put(
        self,
        tenant_id: str,
        secret_id: str,
        value: str,
    ) -> SecretRecord:
        key = self._tenant_key(tenant_id)

        encrypted = self._crypt(
            value.encode("utf-8"),
            key,
        )

        existing = self._records.get(
            (tenant_id, secret_id)
        )

        version = (
            existing.version + 1
            if existing
            else 1
        )

        record = SecretRecord(
            secret_id=secret_id,
            tenant_id=tenant_id,
            version=version,
            ciphertext=base64.b64encode(
                encrypted
            ).decode("ascii"),
            created_at=now_ts(),
            rotated_at=(
                now_ts()
                if existing
                else None
            ),
        )

        with self._lock:
            self._records[
                (tenant_id, secret_id)
            ] = record

        return record

    def get(
        self,
        tenant_id: str,
        secret_id: str,
    ) -> str:
        with self._lock:
            record = self._records.get(
                (tenant_id, secret_id)
            )

            if not record:
                raise KeyError("Secret not found")

        key = self._tenant_key(tenant_id)

        plaintext = self._decrypt(
            base64.b64decode(record.ciphertext),
            key,
        )

        return plaintext.decode("utf-8")

    def rotate_key(
        self,
        tenant_id: str,
    ) -> None:
        with self._lock:
            old_key = self._tenant_key(tenant_id)

            records = [
                r
                for (t, _),
                r in self._records.items()
                if t == tenant_id
            ]

            new_key = secrets.token_bytes(32)

            for record in records:
                plaintext = self._decrypt(
                    base64.b64decode(record.ciphertext),
                    old_key,
                )

                record.ciphertext = base64.b64encode(
                    self._crypt(
                        plaintext,
                        new_key,
                    )
                ).decode("ascii")

                record.rotated_at = now_ts()

            self._keys[tenant_id] = new_key


# ============================================================
# ENCRYPTION / KEY MANAGEMENT
# ============================================================

@dataclass
class EncryptionKey:
    key_id: str
    tenant_id: str
    version: int
    key_material: bytes
    created_at: float
    active: bool = True


class KeyManager:
    """
    Tenant-scoped key manager with rotation.
    """

    def __init__(self) -> None:
        self._keys: Dict[str, List[EncryptionKey]] = {}
        self._lock = threading.RLock()

    def create_key(
        self,
        tenant_id: str,
    ) -> EncryptionKey:
        with self._lock:
            versions = self._keys.setdefault(
                tenant_id,
                [],
            )

            key = EncryptionKey(
                key_id=uuid.uuid4().hex,
                tenant_id=tenant_id,
                version=len(versions) + 1,
                key_material=secrets.token_bytes(32),
                created_at=now_ts(),
            )

            for old in versions:
                old.active = False

            versions.append(key)

            return key

    def active_key(
        self,
        tenant_id: str,
    ) -> EncryptionKey:
        with self._lock:
            versions = self._keys.get(
                tenant_id,
                [],
            )

            for key in reversed(versions):
                if key.active:
                    return key

        return self.create_key(tenant_id)

    def rotate(
        self,
        tenant_id: str,
    ) -> EncryptionKey:
        return self.create_key(tenant_id)

    def versions(
        self,
        tenant_id: str,
    ) -> List[EncryptionKey]:
        with self._lock:
            return list(
                self._keys.get(
                    tenant_id,
                    [],
                )
            )


