    component: str = None  # merged from AuditRecord, made optional for safety
    operation: str = None  # merged from AuditRecord, made optional for safety
    resource_type: str = None  # merged from AuditRecord, made optional for safety
    resource_id: str = None  # merged from AuditRecord, made optional for safety
    correlation_id: str = None  # merged from AuditRecord, made optional for safety
    causation_id: Optional[str] = None  # merged from AuditRecord, made optional for safety
