# ============================================================
# AGENT PERMISSIONS
# ============================================================



class AgentPermissionManager:
    LEVEL_ORDER = {
        ActionLevel.READ_ONLY: 0,
        ActionLevel.LOW_RISK: 1,
        ActionLevel.MEDIUM_RISK: 2,
        ActionLevel.HIGH_RISK: 3,
        ActionLevel.EMERGENCY: 4,
    }

    def __init__(self) -> None:
        self.agents: Dict[str, AgentIdentity] = {}
        self._lock = threading.RLock()

    def register(
        self,
        agent: AgentIdentity,
    ) -> None:
        with self._lock:
            self.agents[agent.agent_id] = agent

    def authorize(
        self,
        agent_id: str,
        tenant_id: str,
        capability: str,
        permission: str,
        action_level: ActionLevel,
    ) -> bool:

        with self._lock:
            agent = self.agents.get(agent_id)

            if not agent:
                return False

            if not agent.enabled:
                return False

            if agent.tenant_id != tenant_id:
                return False

            if capability not in agent.capabilities:
                return False

            if permission not in agent.permissions:
                return False

            return (
                self.LEVEL_ORDER[action_level]
                <= self.LEVEL_ORDER[
                    agent.max_action_level
                ]
            )

    def disable(self, agent_id: str) -> None:
        with self._lock:
            if agent_id in self.agents:
                self.agents[agent_id].enabled = False


