# ============================================================
# BREAK-GLASS ACCESS
# ============================================================



class BreakGlassManager:
    """
    Emergency access.

    Break-glass access is:
        - explicit
        - time limited
        - reason-bound
        - auditable
        - approval-bound
    """

    # [auto-repair] issue() below referenced self.MAX_TTL_SECONDS, which
    # was never defined anywhere on this class. 3600s (1 hour) is a
    # conservative default cap for emergency access -- tune to your org's
    # actual break-glass policy.
    MAX_TTL_SECONDS: ClassVar[int] = 3600

    def __init__(self) -> None:
        self._grants: Dict[str, BreakGlassGrant] = {}
        self._lock = threading.RLock()

    def request(
        self,
        tenant_id: str,
        actor_id: str,
        reason: str,
        ttl_seconds: int = 900,
    ) -> BreakGlassGrant:

        if not reason or len(reason.strip()) < 10:
            raise ValueError(
                "Break-glass reason must be meaningful"
            )

        grant = BreakGlassGrant(
            grant_id=secrets.token_urlsafe(24),
            tenant_id=tenant_id,
            principal_id=actor_id,
            reason=reason,
            expires_at=utc_now_v5()
            + timedelta(seconds=ttl_seconds),
        )

        with self._lock:
            self._grants[grant.grant_id] = grant

        return grant

    def approve(
        self,
        grant_id: str,
        *,
        tenant_id: str,
    ) -> None:
        # [auto-repair] this previously took only grant_id -- anyone who
        # knew/guessed a grant_id could approve ANY tenant's emergency
        # break-glass access request, no check at all on who's
        # approving or which tenant they belong to. validate() right
        # below already correctly checks grant.tenant_id -- bringing
        # this in line with it. Given this grants emergency privileged
        # access, this was the most consequential of the missing-check
        # bugs found this session.
        with self._lock:
            grant = self._grants.get(grant_id)

            if not grant:
                raise KeyError("Unknown break-glass grant")

            if grant.tenant_id != tenant_id:
                raise TenantIsolationError(
                    "Break-glass grant tenant mismatch."
                )

            if grant.expires_at <= utc_now_v5():
                raise PermissionError(
                    "Break-glass grant expired"
                )

            self._grants[grant_id] = BreakGlassGrant(
                **{**grant.__dict__, "approved": True}
            )

    def validate(
        self,
        grant_id: str,
        tenant_id: str,
        actor_id: str,
    ) -> bool:

        with self._lock:
            grant = self._grants.get(grant_id)

            if not grant:
                return False

            if grant.tenant_id != tenant_id:
                return False

            if grant.principal_id != actor_id:
                return False

            if not grant.approved:
                return False

            if grant.expires_at <= utc_now_v5():
                return False

            return True
    # --- preserved from BreakGlassManager (merged, not present in canonical host) ---
    def issue(
        self,
        principal: TenantPrincipal,
        reason: str,
        ttl_seconds: int = 300,
    ) -> BreakGlassGrant:
        if not principal.mfa_verified:
            raise AuthenticationError(
                "Break-glass requires MFA."
            )

        reason = require_non_empty(
            reason,
            "reason",
        )

        if (
            ttl_seconds <= 0
            or ttl_seconds > self.MAX_TTL_SECONDS
        ):
            raise ValidationError(
                "Break-glass TTL must be between "
                f"1 and {self.MAX_TTL_SECONDS} seconds."
            )

        now = utc_now()

        grant = BreakGlassGrant(
            grant_id=secure_id("bg"),
            tenant_id=principal.tenant_id,
            principal_id=principal.principal_id,
            reason=reason,
            issued_at=now,
            expires_at=now + timedelta(
                seconds=ttl_seconds
            ),
        )

        with self._lock:
            self._grants[
                grant.grant_id
            ] = grant

        return grant
    # --- preserved from BreakGlassManager (merged, not present in canonical host) ---
    def require_active(
        self,
        grant_id: str,
        principal: TenantPrincipal,
    ) -> BreakGlassGrant:
        with self._lock:
            grant = self._grants.get(
                grant_id
            )

            if grant is None:
                raise AuthorizationError(
                    "Unknown break-glass grant."
                )

            if grant.tenant_id != principal.tenant_id:
                raise TenantIsolationError(
                    "Break-glass tenant mismatch."
                )

            if grant.principal_id != principal.principal_id:
                raise AuthorizationError(
                    "Break-glass principal mismatch."
                )

            if not grant.active():
                raise AuthorizationError(
                    "Break-glass grant expired."
                )

            return grant


# ============================================================
# ENTERPRISE SECURITY GATE
# ============================================================

class EnterpriseSecurityGate:
    """
    Central enforcement point combining:

        Tenant isolation
        RBAC
        ABAC
        MFA
        Policy
        Session
        API security
        Agent permissions
        Emergency stop
        Break-glass
        Audit
        Rate limiting
    """

    def __init__(self) -> None:
        self.tenants = TenantIsolation()
        self.rbac = RBAC()
        self.abac = ABAC()
        self.mfa = MFAProvider()
        self.sessions = SessionManager()
        self.vault = SecretsVault()
        self.keys = KeyManager()
        self.audit = AuditLedger()
        self.policy = PolicyEngine()
        self.api_keys = APIKeyManager()
        self.rate_limiter = RateLimiter()
        self.agent_permissions = AgentPermissionManager()
        self.emergency_stop = EmergencyStopController()
        self.break_glass = BreakGlassManager()

    def authorize(
        self,
        context: TenantContext,
        action: str,
        permission: str,
        resource_attributes: Optional[Dict[str, Any]] = None,
        environment_attributes: Optional[Dict[str, Any]] = None,
        mfa_verified: bool = False,
        emergency: bool = False,
        break_glass_id: Optional[str] = None,
        request_cost: float = 1.0,
    ) -> Decision:

        # ----------------------------------------------------
        # Rate limiting
        # ----------------------------------------------------

        if not self.rate_limiter.allow(
            f"{context.tenant_id}:{context.actor_id}",
            request_cost,
        ):
            self.audit.append(
                tenant_id=context.tenant_id,
                actor_id=context.actor_id,
                action=action,
                resource=permission,
                outcome=AuditOutcome.DENIED,
                request_id=context.request_id,
                metadata={
                    "reason": "rate_limit",
                },
            )

            return Decision.DENY

        # ----------------------------------------------------
        # Emergency stop
        # ----------------------------------------------------

        if emergency:
            if self.emergency_stop.is_stopped(
                context.tenant_id
            ):
                if not (
                    break_glass_id
                    and self.break_glass.validate(
                        break_glass_id,
                        context.tenant_id,
                        context.actor_id,
                    )
                ):
                    self.audit.append(
                        tenant_id=context.tenant_id,
                        actor_id=context.actor_id,
                        action=action,
                        resource=permission,
                        outcome=AuditOutcome.DENIED,
                        request_id=context.request_id,
                        metadata={
                            "reason": "emergency_stop",
                        },
                    )

                    return Decision.DENY

        # ----------------------------------------------------
        # RBAC
        # ----------------------------------------------------

        if not self.rbac.has_permission(
            context.actor_id,
            permission,
        ):
            self.audit.append(
                tenant_id=context.tenant_id,
                actor_id=context.actor_id,
                action=action,
                resource=permission,
                outcome=AuditOutcome.DENIED,
                request_id=context.request_id,
                metadata={
                    "reason": "rbac",
                },
            )

            return Decision.DENY

        roles = self.rbac.roles_for(
            context.actor_id
        )

        # ----------------------------------------------------
        # ABAC
        # ----------------------------------------------------

        abac_decision = self.abac.evaluate(
            AccessAttributes(
                actor={
                    "id": context.actor_id,
                    "tenant_id": context.tenant_id,
                    "roles": roles,
                },
                resource=resource_attributes or {},
                action=action,
                environment=environment_attributes or {},
            )
        )

        if abac_decision != Decision.ALLOW:
            self.audit.append(
                tenant_id=context.tenant_id,
                actor_id=context.actor_id,
                action=action,
                resource=permission,
                outcome=AuditOutcome.DENIED,
                request_id=context.request_id,
                metadata={
                    "reason": "abac",
                },
            )

            return abac_decision

        # ----------------------------------------------------
        # Policy
        # ----------------------------------------------------

        policy_decision = self.policy.evaluate(
            action=action,
            actor_roles=roles,
            mfa_verified=mfa_verified,
            emergency=emergency,
        )

        if policy_decision != Decision.ALLOW:
            self.audit.append(
                tenant_id=context.tenant_id,
                actor_id=context.actor_id,
                action=action,
                resource=permission,
                outcome=AuditOutcome.DENIED,
                request_id=context.request_id,
                metadata={
                    "reason": "policy",
                    "decision": policy_decision.value,
                },
            )

            return policy_decision

        # ----------------------------------------------------
        # Success
        # ----------------------------------------------------

        self.audit.append(
            tenant_id=context.tenant_id,
            actor_id=context.actor_id,
            action=action,
            resource=permission,
            outcome=AuditOutcome.SUCCESS,
            request_id=context.request_id,
        )

        return Decision.ALLOW


# ============================================================
# PHASE 21 SELF TESTS
# ============================================================

def run_phase21_tests() -> Dict[str, Any]:
    """
    Internal verification suite.

    These tests intentionally test security boundaries rather
    than implementing future Cyber phases.
    """

    results: Dict[str, bool] = {}

    security = EnterpriseSecurityGate()

    # --------------------------------------------------------
    # Tenant setup
    # --------------------------------------------------------

    tenant_a = "tenant-a"
    tenant_b = "tenant-b"

    security.tenants.register(
        tenant_a,
        "asset-1",
        {"name": "A-Asset"},
    )

    security.tenants.register(
        tenant_b,
        "asset-2",
        {"name": "B-Asset"},
    )

    ctx_a = TenantContext(
        tenant_id=tenant_a,
        actor_id="user-a",
    )

    # Tenant isolation
    results["tenant_isolation_same_tenant"] = (
        security.tenants.get(
            ctx_a,
            "asset-1",
        )["name"]
        == "A-Asset"
    )

    try:
        security.tenants.get(
            ctx_a,
            "asset-2",
        )
        results["tenant_isolation_cross_tenant"] = False
    except TenantIsolationError:
        results["tenant_isolation_cross_tenant"] = True

    # --------------------------------------------------------
    # RBAC
    # --------------------------------------------------------

    security.rbac.create_role(
        "security_admin",
        {
            "security.read",
            "security.manage",
            "incident.approve",
        },
    )

    security.rbac.create_role(
        "analyst",
        {
            "security.read",
        },
    )

    security.rbac.assign_role(
        "user-a",
        "security_admin",
    )

    results["rbac_allow"] = (
        security.rbac.has_permission(
            "user-a",
            "security.manage",
        )
    )

    results["rbac_deny"] = not (
        security.rbac.has_permission(
            "unknown-user",
            "security.manage",
        )
    )

    # --------------------------------------------------------
    # ABAC
    # --------------------------------------------------------

    security.abac.add_rule(
        "same-tenant",
        Decision.ALLOW,
        lambda attrs: (
            attrs.actor.get("tenant_id")
            == attrs.resource.get("tenant_id")
        ),
    )

    abac_ok = security.abac.evaluate(
        AccessAttributes(
            actor={
                "tenant_id": tenant_a,
            },
            resource={
                "tenant_id": tenant_a,
            },
            action="read",
        )
    )

    results["abac_allow"] = (
        abac_ok == Decision.ALLOW
    )

    # --------------------------------------------------------
    # Policy
    # --------------------------------------------------------

    security.policy.register(
        SecurityPolicy(
            name="manage-security",
            action="security.manage",
            level=ActionLevel.MEDIUM_RISK,
            require_mfa=True,
            allowed_roles={"security_admin"},
        )
    )

    no_mfa = security.policy.evaluate(
        "security.manage",
        {"security_admin"},
        mfa_verified=False,
    )

    results["policy_mfa_required"] = (
        no_mfa == Decision.REQUIRE_MFA
    )

    with_mfa = security.policy.evaluate(
        "security.manage",
        {"security_admin"},
        mfa_verified=True,
    )

    results["policy_mfa_allow"] = (
        with_mfa == Decision.ALLOW
    )

    # --------------------------------------------------------
    # MFA
    # --------------------------------------------------------

    challenge = security.mfa.create_challenge(
        actor_id="user-a",
        tenant_id=tenant_a,
    )

    results["mfa_verification"] = security.mfa.verify_challenge(
        challenge.challenge_id,
        "user-a",
        lambda _: True,
    )

    # --------------------------------------------------------
    # Sessions
    # --------------------------------------------------------

    session = security.sessions.create(
        actor_id="user-a",
        tenant_id=tenant_a,
        auth_method=AuthenticationMethod.OIDC,
        mfa_verified=True,
    )

    results["session_active"] = (
        security.sessions.get(
            session.session_id,
            tenant_id=tenant_a,
        ).status
        == SessionStatus.ACTIVE
    )

    security.sessions.revoke(
        session.session_id,
        tenant_id=tenant_a,
    )

    try:
        security.sessions.get(
            session.session_id,
            tenant_id=tenant_a,
        )
        results["session_revocation"] = False
    except PermissionError:
        results["session_revocation"] = True

    # --------------------------------------------------------
    # Secrets
    # --------------------------------------------------------

    security.vault.put(
        tenant_a,
        "api-secret",
        "SUPER-SECRET",
    )

    results["secret_round_trip"] = (
        security.vault.get(
            tenant_a,
            "api-secret",
        )
        == "SUPER-SECRET"
    )

    security.vault.rotate_key(
        tenant_a
    )

    results["secret_after_rotation"] = (
        security.vault.get(
            tenant_a,
            "api-secret",
        )
        == "SUPER-SECRET"
    )

    # --------------------------------------------------------
    # Key manager
    # --------------------------------------------------------

    key1 = security.keys.create_key(
        tenant_a
    )

    key2 = security.keys.rotate(
        tenant_a
    )

    results["key_rotation"] = (
        key2.version == key1.version + 1
        and key2.active
        and not key1.active
    )

    # --------------------------------------------------------
    # API keys
    # --------------------------------------------------------

    api_key = security.api_keys.create(
        tenant_a,
        "user-a",
        {"security.read"},
    )

    api_identity = security.api_keys.validate(
        api_key
    )

    results["api_key_validation"] = (
        api_identity["tenant_id"] == tenant_a
        and api_identity["actor_id"] == "user-a"
    )

    security.api_keys.revoke(
        api_key
    )

    try:
        security.api_keys.validate(api_key)
        results["api_key_revocation"] = False
    except PermissionError:
        results["api_key_revocation"] = True

    # --------------------------------------------------------
    # Agent permissions
    # --------------------------------------------------------

    security.agent_permissions.register(
        AgentIdentity(
            agent_id="detection-agent",
            tenant_id=tenant_a,
            capabilities={"detect"},
            permissions={"security.read"},
            max_action_level=ActionLevel.READ_ONLY,
        )
    )

    results["agent_permission_allow"] = (
        security.agent_permissions.authorize(
            "detection-agent",
            tenant_a,
            "detect",
            "security.read",
            ActionLevel.READ_ONLY,
        )
    )

    results["agent_permission_deny"] = not (
        security.agent_permissions.authorize(
            "detection-agent",
            tenant_a,
            "execute",
            "security.execute",
            ActionLevel.HIGH_RISK,
        )
    )

    # --------------------------------------------------------
    # Emergency stop
    # --------------------------------------------------------

    security.emergency_stop.activate_tenant(
        tenant_a
    )

    results["emergency_stop"] = (
        security.emergency_stop.is_stopped(
            tenant_a
        )
    )

    security.emergency_stop.deactivate_tenant(
        tenant_a
    )

    # --------------------------------------------------------
    # Break glass
    # --------------------------------------------------------

    grant = security.break_glass.request(
        tenant_id=tenant_a,
        actor_id="user-a",
        reason="Production emergency requires immediate containment",
    )

    results["break_glass_initially_denied"] = not (
        security.break_glass.validate(
            grant.grant_id,
            tenant_a,
            "user-a",
        )
    )

    security.break_glass.approve(
        grant.grant_id,
        tenant_id=tenant_a,
    )

    results["break_glass_after_approval"] = (
        security.break_glass.validate(
            grant.grant_id,
            tenant_a,
            "user-a",
        )
    )

    # --------------------------------------------------------
    # Audit ledger
    # --------------------------------------------------------

    security.audit.append(
        tenant_id=tenant_a,
        actor_id="user-a",
        action="test",
        resource="phase21",
        outcome=AuditOutcome.SUCCESS,
    )

    results["audit_integrity"] = (
        security.audit.verify_integrity()
    )

    # --------------------------------------------------------
    # Rate limiter
    # --------------------------------------------------------

    limiter = RateLimiter(
        capacity=1,
        refill_rate=0.01,
    )

    first = limiter.allow("test")
    second = limiter.allow("test")

    results["rate_limit"] = (
        first is True
        and second is False
    )

    # --------------------------------------------------------
    # Enterprise security gate
    # --------------------------------------------------------

    security.abac.rules.clear()

    security.abac.add_rule(
        "tenant-match",
        Decision.ALLOW,
        lambda attrs: (
            attrs.actor["tenant_id"]
            == attrs.resource["tenant_id"]
        ),
    )

    security.policy.register(
        SecurityPolicy(
            name="read-security",
            action="security.read",
            level=ActionLevel.READ_ONLY,
            allowed_roles={"security_admin"},
        )
    )

    gate_decision = security.authorize(
        context=TenantContext(
            tenant_id=tenant_a,
            actor_id="user-a",
            request_id="phase21-test",
        ),
        action="security.read",
        permission="security.read",
        resource_attributes={
            "tenant_id": tenant_a,
        },
        mfa_verified=True,
    )

    results["enterprise_gate"] = (
        gate_decision == Decision.ALLOW
    )

    # --------------------------------------------------------
    # Final result
    # --------------------------------------------------------

    results["all_tests_passed"] = all(
        results.values()
    )

    return results


