@dataclass
class InfrastructureEvent:
    event_id: str
    tenant_id: str
    event_type: str
    payload: Dict[str, Any]
    source: str = "nexora"
    correlation_id: Optional[str] = None
    causation_id: Optional[str] = None
    timestamp: str = field(default_factory=utc_now_v10)
    attempt: int = 0
    status: EventStatus = EventStatus.PUBLISHED
    metadata: Dict[str, Any] = field(default_factory=dict)

    @classmethod
    def create(
        cls,
        tenant_id: str,
        event_type: str,
        payload: Dict[str, Any],
        source: str = "nexora",
        correlation_id: Optional[str] = None,
    ) -> "InfrastructureEvent":
        return cls(
            event_id=new_id_v3("evt"),
            tenant_id=tenant_id,
            event_type=event_type,
            payload=payload,
            source=source,
            correlation_id=correlation_id or new_id_v3("corr"),
        )

    def to_dict(self) -> Dict[str, Any]:
        data = asdict(self)
        data["status"] = self.status.value
        return data


