class EventBus:
    """Canonical thread-safe local EventBus with deterministic dispatch."""

    def __init__(self, maxsize: int = 10000) -> None:
        self._lock = threading.RLock()
        self._history = deque(maxlen=maxsize)
        self._subscribers = defaultdict(list)
        # [auto-repair] added: track which (event_type, handler) pairs
        # are "critical" (see subscribe() and publish() below).
        self._critical_subscribers = defaultdict(list)
        self._seen: Set[str] = set()

    def publish(self, event: Any) -> bool:
        event_id = getattr(event, "event_id", None)
        if not event_id:
            raise ValueError("Event must have an event_id")
        with self._lock:
            if event_id in self._seen:
                return False
            self._seen.add(event_id)
            self._history.append(event)
            event_type = getattr(event, "event_type", "")
            subscribers = tuple(self._subscribers.get(event_type, ()))
            subscribers += tuple(self._subscribers.get("*", ()))
            critical = set(self._critical_subscribers.get(event_type, ()))
            critical |= set(self._critical_subscribers.get("*", ()))
        # [auto-repair] previously every subscriber failure was caught
        # and only logged -- publish() always returned True regardless,
        # so a caller had no way to know a security-critical subscriber
        # (audit logging, emergency-stop trigger, etc.) had failed.
        # Non-critical subscribers still run best-effort and only log;
        # critical ones (opt-in via subscribe(..., critical=True)) now
        # cause publish() to raise after every subscriber has had a
        # chance to run, so one failing subscriber doesn't starve the
        # others of the event.
        critical_failures = []
        for subscriber in subscribers:
            try:
                subscriber(event)
            except Exception as exc:
                logger.exception("Event subscriber failed: %s", event_id)
                if subscriber in critical:
                    critical_failures.append((subscriber, exc))
        if critical_failures:
            names = ", ".join(getattr(s, "__name__", repr(s)) for s, _ in critical_failures)
            raise RuntimeError(
                f"Critical event subscriber(s) failed for event {event_id}: {names}"
            )
        return True

    def subscribe(
        self,
        event_type: str,
        handler: Callable[[Any], None],
        *,
        critical: bool = False,
    ) -> None:
        if not callable(handler):
            raise TypeError("handler must be callable")
        with self._lock:
            if handler not in self._subscribers[event_type]:
                self._subscribers[event_type].append(handler)
            if critical and handler not in self._critical_subscribers[event_type]:
                self._critical_subscribers[event_type].append(handler)

    def unsubscribe(self, event_type: str, subscriber: Callable[[Any], None]) -> None:
        with self._lock:
            if subscriber in self._subscribers.get(event_type, ()):
                self._subscribers[event_type].remove(subscriber)

    def queue_depth(self, event_type: Optional[str] = None) -> int:
        with self._lock:
            return len(self._history) if event_type is None else sum(1 for e in self._history if getattr(e, "event_type", None) == event_type)

    def history(self, *, tenant_id: Optional[str] = None, event_type: Optional[str] = None, limit: int = 100) -> List[Any]:
        if limit <= 0:
            return []
        with self._lock:
            events = list(reversed(self._history))
        if tenant_id is not None:
            events = [e for e in events if getattr(e, "tenant_id", None) == tenant_id]
        if event_type is not None:
            events = [e for e in events if getattr(e, "event_type", None) == event_type]
        return events[:limit]

    def size(self) -> int:
        with self._lock:
            return len(self._history)


class InMemoryEventBus(EventBus):
    """
    Deterministic local event bus used for development,
    testing and environments where external messaging is not
    configured.

    The interface is intentionally compatible with a distributed
    event-bus adapter.
    """

    def __init__(self, maxsize: int = 10000) -> None:
        self.queue: Queue[InfrastructureEvent] = Queue(
            maxsize=maxsize
        )
        self.handlers: Dict[
            str,
            List[Callable[[InfrastructureEvent], None]]
        ] = defaultdict(list)

        self.dead_letters: deque[InfrastructureEvent] = deque(
            maxlen=10000
        )

        self.journal: deque[InfrastructureEvent] = deque(
            maxlen=100000
        )

        self._lock = threading.RLock()

    def publish(self, event: InfrastructureEvent) -> str:
        with self._lock:
            self.journal.append(event)

        self.queue.put(event)

        metrics.increment(
            "events_published",
            labels={"type": event.event_type},
        )

        return event.event_id

    def subscribe(
        self,
        event_type: str,
        handler: Callable[[InfrastructureEvent], None],
    ) -> None:
        with self._lock:
            self.handlers[event_type].append(handler)

    def consume_once(self, timeout: float = 0.1) -> bool:
        try:
            event = self.queue.get(timeout=timeout)
        except Empty:
            return False

        event.status = EventStatus.PROCESSING

        handlers = list(
            self.handlers.get(event.event_type, [])
        )

        if not handlers:
            event.status = EventStatus.PROCESSED
            self.queue.task_done()
            return True

        try:
            for handler in handlers:
                handler(event)

            event.status = EventStatus.PROCESSED

            metrics.increment(
                "events_processed",
                labels={"type": event.event_type},
            )

        except Exception as exc:
            event.attempt += 1
            event.status = EventStatus.FAILED

            metrics.increment(
                "events_failed",
                labels={"type": event.event_type},
            )

            logger.exception(
                "Event processing failed: %s",
                event.event_id,
            )

            if event.attempt >= 3:
                event.status = EventStatus.DEAD_LETTER
                self.dead_letters.append(event)

                metrics.increment(
                    "events_dead_lettered",
                    labels={"type": event.event_type},
                )

        finally:
            self.queue.task_done()

        return True

    def drain(self, limit: int = 1000) -> int:
        processed = 0

        while processed < limit:
            if not self.consume_once(timeout=0):
                break

            processed += 1

        return processed

    def replay(
        self,
        event_type: Optional[str] = None,
        tenant_id: Optional[str] = None,
    ) -> int:
        count = 0

        for original in list(self.journal):
            if event_type and original.event_type != event_type:
                continue

            if tenant_id and original.tenant_id != tenant_id:
                continue

            replayed = InfrastructureEvent(
                event_id=new_id_v3("replay"),
                tenant_id=original.tenant_id,
                event_type=original.event_type,
                payload=dict(original.payload),
                source="event-replay",
                correlation_id=original.correlation_id,
                causation_id=original.event_id,
                metadata={
                    "replayed_from": original.event_id
                },
            )

            self.publish(replayed)
            count += 1

        return count

    def queue_depth(
        self,
        event_type: Optional[str] = None,
    ) -> int:
        if event_type is None:
            return self.queue.qsize()

        return sum(
            1
            for item in list(self.journal)
            if (
                item.event_type == event_type
                and item.status != EventStatus.PROCESSED
            )
        )


# ============================================================
# 7. POSTGRESQL REPOSITORY
# ============================================================

class DatabaseRepository(ABC):

    @abstractmethod
    def save_event(
        self,
        event: InfrastructureEvent,
    ) -> None:
        raise NotImplementedError

    @abstractmethod
    def save_record(
        self,
        tenant_id: str,
        record_type: str,
        record: Dict[str, Any],
    ) -> str:
        raise NotImplementedError

    @abstractmethod
    def query_records(
        self,
        tenant_id: str,
        record_type: Optional[str] = None,
        limit: int = 100,
    ) -> List[Dict[str, Any]]:
        raise NotImplementedError


class SQLiteDevelopmentRepository(DatabaseRepository):
    """
    Development-compatible repository.

    Production deployments should provide a PostgreSQL adapter
    through the same interface.
    """

    def __init__(self, path: str = ":memory:") -> None:
        self.conn = sqlite3.connect(
            path,
            check_same_thread=False,
        )

        # [auto-repair] SQLite files were created with whatever the
        # process umask allows -- typically 644 (world-readable) --
        # with nothing in this file restricting it. Audit/telemetry
        # data belongs to the owning user only.
        if path != ":memory:":
            try:
                os.chmod(path, 0o600)
            except OSError:
                pass

        self.lock = threading.RLock()

        self._initialize()

    def _initialize(self) -> None:
        with self.lock:
            self.conn.execute(
                """
                CREATE TABLE IF NOT EXISTS infrastructure_events (
                    event_id TEXT PRIMARY KEY,
                    tenant_id TEXT NOT NULL,
                    event_type TEXT NOT NULL,
                    payload TEXT NOT NULL,
                    timestamp TEXT NOT NULL,
                    status TEXT NOT NULL
                )
                """
            )

            self.conn.execute(
                """
                CREATE TABLE IF NOT EXISTS infrastructure_records (
                    record_id TEXT PRIMARY KEY,
                    tenant_id TEXT NOT NULL,
                    record_type TEXT NOT NULL,
                    payload TEXT NOT NULL,
                    created_at TEXT NOT NULL
                )
                """
            )

            self.conn.commit()

    def save_event(
        self,
        event: InfrastructureEvent,
    ) -> None:
        with self.lock:
            self.conn.execute(
                """
                INSERT OR REPLACE INTO infrastructure_events
                VALUES (?, ?, ?, ?, ?, ?)
                """,
                (
                    event.event_id,
                    event.tenant_id,
                    event.event_type,
                    json.dumps(event.payload),
                    event.timestamp,
                    event.status.value,
                ),
            )
            self.conn.commit()

    def save_record(
        self,
        tenant_id: str,
        record_type: str,
        record: Dict[str, Any],
    ) -> str:
        record_id = new_id_v3("rec")

        with self.lock:
            self.conn.execute(
                """
                INSERT INTO infrastructure_records
                VALUES (?, ?, ?, ?, ?)
                """,
                (
                    record_id,
                    tenant_id,
                    record_type,
                    json.dumps(record, default=str),
                    utc_now_v10(),
                ),
            )
            self.conn.commit()

        return record_id

    def query_records(
        self,
        tenant_id: str,
        record_type: Optional[str] = None,
        limit: int = 100,
    ) -> List[Dict[str, Any]]:

        sql = """
            SELECT record_id, record_type, payload, created_at
            FROM infrastructure_records
            WHERE tenant_id = ?
        """

        params: List[Any] = [tenant_id]

        if record_type:
            sql += " AND record_type = ?"
            params.append(record_type)

        sql += " ORDER BY created_at DESC LIMIT ?"
        params.append(limit)

        with self.lock:
            rows = self.conn.execute(
                sql,
                params,
            ).fetchall()

        return [
            {
                "record_id": row[0],
                "record_type": row[1],
                "payload": json.loads(row[2]),
                "created_at": row[3],
            }
            for row in rows
        ]


class PostgreSQLRepository(DatabaseRepository):
    """
    PostgreSQL adapter.

    psycopg is optional so the Phase 22 module remains runnable
    in a local test environment.

    Install in production:
        pip install psycopg[binary]
    """

    def __init__(self, dsn: str) -> None:
        try:
            import psycopg
        except ImportError as exc:
            raise RuntimeError(
                "PostgreSQL adapter requires psycopg."
            ) from exc

        self.psycopg = psycopg
        self.dsn = dsn
        self._initialize()

    def _connect(self):
        return self.psycopg.connect(self.dsn)

    def _initialize(self) -> None:
        with self._connect() as conn:
            conn.execute(
                """
                CREATE TABLE IF NOT EXISTS infrastructure_events (
                    event_id TEXT PRIMARY KEY,
                    tenant_id TEXT NOT NULL,
                    event_type TEXT NOT NULL,
                    payload JSONB NOT NULL,
                    timestamp TIMESTAMPTZ NOT NULL,
                    status TEXT NOT NULL
                )
                """
            )

            conn.execute(
                """
                CREATE TABLE IF NOT EXISTS infrastructure_records (
                    record_id TEXT PRIMARY KEY,
                    tenant_id TEXT NOT NULL,
                    record_type TEXT NOT NULL,
                    payload JSONB NOT NULL,
                    created_at TIMESTAMPTZ NOT NULL
                )
                """
            )

    def save_event(
        self,
        event: InfrastructureEvent,
    ) -> None:
        with self._connect() as conn:
            conn.execute(
                """
                INSERT INTO infrastructure_events
                (
                    event_id,
                    tenant_id,
                    event_type,
                    payload,
                    timestamp,
                    status
                )
                VALUES (%s, %s, %s, %s, %s, %s)
                ON CONFLICT (event_id)
                DO UPDATE SET
                    payload = EXCLUDED.payload,
                    status = EXCLUDED.status
                """,
                (
                    event.event_id,
                    event.tenant_id,
                    event.event_type,
                    json.dumps(event.payload),
                    event.timestamp,
                    event.status.value,
                ),
            )

    def save_record(
        self,
        tenant_id: str,
        record_type: str,
        record: Dict[str, Any],
    ) -> str:
        record_id = new_id_v3("rec")

        with self._connect() as conn:
            conn.execute(
                """
                INSERT INTO infrastructure_records
                VALUES (%s, %s, %s, %s, %s)
                """,
                (
                    record_id,
                    tenant_id,
                    record_type,
                    json.dumps(record),
                    utc_now_v10(),
                ),
            )

        return record_id

    def query_records(
        self,
        tenant_id: str,
        record_type: Optional[str] = None,
        limit: int = 100,
    ) -> List[Dict[str, Any]]:

        with self._connect() as conn:
            if record_type:
                rows = conn.execute(
                    """
                    SELECT
                        record_id,
                        record_type,
                        payload,
                        created_at
                    FROM infrastructure_records
                    WHERE tenant_id = %s
                      AND record_type = %s
                    ORDER BY created_at DESC
                    LIMIT %s
                    """,
                    (tenant_id, record_type, limit),
                ).fetchall()
            else:
                rows = conn.execute(
                    """
                    SELECT
                        record_id,
                        record_type,
                        payload,
                        created_at
                    FROM infrastructure_records
                    WHERE tenant_id = %s
                    ORDER BY created_at DESC
                    LIMIT %s
                    """,
                    (tenant_id, limit),
                ).fetchall()

        return [
            {
                "record_id": row[0],
                "record_type": row[1],
                "payload": row[2],
                "created_at": row[3],
            }
            for row in rows
        ]


# ============================================================
# 8. REDIS CACHE
# ============================================================

class CacheBackend(ABC):

    @abstractmethod
    def get(self, key: str) -> Optional[Any]:
        raise NotImplementedError

    @abstractmethod
    def set(
        self,
        key: str,
        value: Any,
        ttl_seconds: int = 300,
    ) -> None:
        raise NotImplementedError

    @abstractmethod
    def delete(self, key: str) -> None:
        raise NotImplementedError


class InMemoryCache(CacheBackend):

    def __init__(self) -> None:
        self.data: Dict[
            str,
            Tuple[Any, float]
        ] = {}

        self.lock = threading.RLock()

    def get(self, key: str) -> Optional[Any]:
        with self.lock:
            item = self.data.get(key)

            if item is None:
                return None

            value, expires_at = item

            if expires_at < time.time():
                del self.data[key]
                return None

            return value

    def set(
        self,
        key: str,
        value: Any,
        ttl_seconds: int = 300,
    ) -> None:
        with self.lock:
            self.data[key] = (
                value,
                time.time() + ttl_seconds,
            )

    def delete(self, key: str) -> None:
        with self.lock:
            self.data.pop(key, None)


class RedisCache(CacheBackend):
    """
    Redis production adapter.
    """

    def __init__(self, url: str) -> None:
        try:
            import redis
        except ImportError as exc:
            raise RuntimeError(
                "Redis adapter requires redis-py."
            ) from exc

        self.client = redis.Redis.from_url(
            url,
            decode_responses=True,
        )

    def get(self, key: str) -> Optional[Any]:
        value = self.client.get(key)

        if value is None:
            return None

        return json.loads(value)

    def set(
        self,
        key: str,
        value: Any,
        ttl_seconds: int = 300,
    ) -> None:
        self.client.setex(
            key,
            ttl_seconds,
            json.dumps(value, default=str),
        )

    def delete(self, key: str) -> None:
        self.client.delete(key)


# ============================================================
# 9. SEARCH / ANALYTICS
# ============================================================

class SearchAnalytics(ABC):

    @abstractmethod
    def index(
        self,
        tenant_id: str,
        document_id: str,
        document: Dict[str, Any],
    ) -> None:
        raise NotImplementedError

    @abstractmethod
    def search(
        self,
        tenant_id: str,
        query: str,
        limit: int = 20,
    ) -> List[Dict[str, Any]]:
        raise NotImplementedError

    @abstractmethod
    def aggregate(
        self,
        tenant_id: str,
        field: str,
    ) -> Dict[str, int]:
        raise NotImplementedError


class InMemorySearchAnalytics(SearchAnalytics):

    def __init__(self) -> None:
        self.documents: Dict[
            str,
            Dict[str, Dict[str, Any]]
        ] = defaultdict(dict)

        self.lock = threading.RLock()

    def index(
        self,
        tenant_id: str,
        document_id: str,
        document: Dict[str, Any],
    ) -> None:
        with self.lock:
            self.documents[tenant_id][document_id] = dict(
                document
            )

    def search(
        self,
        tenant_id: str,
        query: str,
        limit: int = 20,
    ) -> List[Dict[str, Any]]:

        query_lower = query.lower()

        results = []

        with self.lock:
            for document_id, document in (
                self.documents.get(tenant_id, {}).items()
            ):
                haystack = json.dumps(
                    document,
                    default=str,
                ).lower()

                if query_lower in haystack:
                    results.append(
                        {
                            "document_id": document_id,
                            "document": document,
                        }
                    )

                if len(results) >= limit:
                    break

        return results

    def aggregate(
        self,
        tenant_id: str,
        field: str,
    ) -> Dict[str, int]:

        counter: Counter[str] = Counter()

        with self.lock:
            documents = self.documents.get(
                tenant_id,
                {},
            ).values()

            for document in documents:
                value = document.get(field)

                if value is not None:
                    counter[str(value)] += 1

        return dict(counter)


# ============================================================
# 10. OBJECT STORAGE
# ============================================================

class ObjectStorage(ABC):

    @abstractmethod
    def put(
        self,
        tenant_id: str,
        object_name: str,
        data: bytes,
    ) -> str:
        raise NotImplementedError

    @abstractmethod
    def get(
        self,
        tenant_id: str,
        object_name: str,
    ) -> bytes:
        raise NotImplementedError

    @abstractmethod
    def delete(
        self,
        tenant_id: str,
        object_name: str,
    ) -> None:
        raise NotImplementedError


class LocalObjectStorage(ObjectStorage):
    """
    Local storage adapter for development/testing.
    """

    def __init__(self) -> None:
        self.objects: Dict[
            Tuple[str, str],
            bytes
        ] = {}

        self.lock = threading.RLock()

    def put(
        self,
        tenant_id: str,
        object_name: str,
        data: bytes,
    ) -> str:

        key = (tenant_id, object_name)

        with self.lock:
            self.objects[key] = bytes(data)

        return f"object://{tenant_id}/{object_name}"

    def get(
        self,
        tenant_id: str,
        object_name: str,
    ) -> bytes:

        with self.lock:
            if (tenant_id, object_name) not in self.objects:
                raise FileNotFoundError(object_name)

            return self.objects[
                (tenant_id, object_name)
            ]

    def delete(
        self,
        tenant_id: str,
        object_name: str,
    ) -> None:

        with self.lock:
            self.objects.pop(
                (tenant_id, object_name),
                None,
            )


# ============================================================
# 11. API GATEWAY
# ============================================================

@dataclass
class APIRequest:
    request_id: str
    tenant_id: str
    method: str
    path: str
    body: Dict[str, Any] = field(default_factory=dict)
    headers: Dict[str, str] = field(default_factory=dict)


@dataclass
class APIResponse:
    request_id: str
    status_code: int
    body: Dict[str, Any]
    worker_id: Optional[str] = None




class StatelessAPIWorker:
    """
    Stateless API worker.

    No tenant/business state is stored inside the worker.
    """

    def __init__(
        self,
        worker_id: str,
        repository: DatabaseRepository,
        event_bus: EventBus,
    ) -> None:

        self.worker_id = worker_id
        self.repository = repository
        self.event_bus = event_bus

    def handle(
        self,
        request: APIRequest,
    ) -> APIResponse:

        started = time.perf_counter()

        try:
            if request.method.upper() == "POST":
                event = InfrastructureEvent.create(
                    tenant_id=request.tenant_id,
                    event_type="security.telemetry",
                    payload=request.body,
                    source="api",
                )

                self.repository.save_event(event)
                self.event_bus.publish(event)

                response = APIResponse(
                    request_id=request.request_id,
                    status_code=202,
                    body={
                        "accepted": True,
                        "event_id": event.event_id,
                    },
                    worker_id=self.worker_id,
                )

            elif request.method.upper() == "GET":
                records = self.repository.query_records(
                    tenant_id=request.tenant_id,
                    limit=100,
                )

                response = APIResponse(
                    request_id=request.request_id,
                    status_code=200,
                    body={
                        "records": records,
                    },
                    worker_id=self.worker_id,
                )

            else:
                response = APIResponse(
                    request_id=request.request_id,
                    status_code=405,
                    body={
                        "error": "method_not_supported"
                    },
                    worker_id=self.worker_id,
                )

            metrics.observe(
                "api_latency_seconds",
                time.perf_counter() - started,
            )

            return response

        except Exception as exc:
            metrics.increment("api_errors")

            logger.exception(
                "API worker failure: %s",
                self.worker_id,
            )

            return APIResponse(
                request_id=request.request_id,
                status_code=500,
                body={
                    "error": "internal_infrastructure_error",
                    "detail": str(exc),
                },
                worker_id=self.worker_id,
            )


class APIGateway:
    """
    Load-balancing gateway over stateless API workers.
    """

    def __init__(
        self,
        workers: List[StatelessAPIWorker],
        rate_limiter: Optional[RateLimiter] = None,
    ) -> None:

        if not workers:
            raise ValueError(
                "At least one API worker is required."
            )

        self.workers = workers
        self.rate_limiter = rate_limiter or RateLimiter()

        self.index = 0
        self.lock = threading.RLock()

    def _select_worker(
        self,
    ) -> StatelessAPIWorker:

        with self.lock:
            worker = self.workers[
                self.index % len(self.workers)
            ]

            self.index += 1

            return worker

    def handle(
        self,
        request: APIRequest,
    ) -> APIResponse:

        if not self.rate_limiter.allow(
            f"tenant:{request.tenant_id}"
        ):
            return APIResponse(
                request_id=request.request_id,
                status_code=429,
                body={
                    "error": "rate_limit_exceeded"
                },
            )

        worker = self._select_worker()

        return worker.handle(request)


# ============================================================
# 12. WORKER BASE
# ============================================================

class BaseWorker(ABC):

    def __init__(
        self,
        worker_id: str,
        event_bus: EventBus,
        repository: DatabaseRepository,
    ) -> None:

        self.worker_id = worker_id
        self.event_bus = event_bus
        self.repository = repository

        self.state = WorkerState.STARTING
        self.processed = 0
        self.failed = 0

        health.register(
            f"worker:{worker_id}"
        )

    def start(self) -> None:
        self.state = WorkerState.READY

        health.update(
            f"worker:{self.worker_id}",
            healthy=True,
            ready=True,
        )

    def stop(self) -> None:
        self.state = WorkerState.STOPPED

        health.update(
            f"worker:{self.worker_id}",
            healthy=False,
            ready=False,
        )

    def process(
        self,
        event: InfrastructureEvent,
    ) -> None:

        if self.state == WorkerState.STARTING:
            self.start()

        self.state = WorkerState.RUNNING

        started = time.perf_counter()

        try:
            self.handle(event)

            self.processed += 1

            metrics.increment(
                "worker_events_processed",
                labels={
                    "worker": self.worker_id
                },
            )

        except Exception:
            self.failed += 1

            metrics.increment(
                "worker_events_failed",
                labels={
                    "worker": self.worker_id
                },
            )

            raise

        finally:
            metrics.observe(
                "worker_latency_seconds",
                time.perf_counter() - started,
                labels={
                    "worker": self.worker_id
                },
            )

            self.state = WorkerState.READY

    @abstractmethod
    def handle(
        self,
        event: InfrastructureEvent,
    ) -> None:
        raise NotImplementedError


# ============================================================
# 13. DETECTION WORKER
# ============================================================

class DetectionWorker(BaseWorker):

    def __init__(
        self,
        worker_id: str,
        event_bus: EventBus,
        repository: DatabaseRepository,
    ) -> None:

        super().__init__(
            worker_id,
            event_bus,
            repository,
        )

        event_bus.subscribe(
            "security.telemetry",
            self.process,
        )

    def handle(
        self,
        event: InfrastructureEvent,
    ) -> None:

        payload = event.payload

        suspicious = bool(
            payload.get("suspicious")
            or payload.get("malicious")
            or payload.get("threat_detected")
        )

        detection = {
            "event_id": event.event_id,
            "tenant_id": event.tenant_id,
            "detected": suspicious,
            "severity": (
                payload.get(
                    "severity",
                    Severity.MEDIUM.value,
                )
                if suspicious
                else Severity.LOW.value
            ),
            "detected_at": utc_now_v10(),
            "worker_id": self.worker_id,
        }

        record_id = self.repository.save_record(
            event.tenant_id,
            "detection",
            detection,
        )

        if suspicious:
            finding_event = InfrastructureEvent.create(
                tenant_id=event.tenant_id,
                event_type="security.detection",
                payload={
                    **detection,
                    "record_id": record_id,
                },
                source=self.worker_id,
                correlation_id=event.correlation_id,
            )

            self.event_bus.publish(
                finding_event
            )


# ============================================================
# 14. INVESTIGATION WORKER
# ============================================================

class InvestigationWorker(BaseWorker):

    def __init__(
        self,
        worker_id: str,
        event_bus: EventBus,
        repository: DatabaseRepository,
    ) -> None:

        super().__init__(
            worker_id,
            event_bus,
            repository,
        )

        event_bus.subscribe(
            "security.detection",
            self.process,
        )

    def handle(
        self,
        event: InfrastructureEvent,
    ) -> None:

        detection = event.payload

        investigation = {
            "investigation_id": new_id_v3("inv"),
            "tenant_id": event.tenant_id,
            "source_detection": detection,
            "started_at": utc_now_v10(),
            "status": "completed",
            "infrastructure_worker": self.worker_id,
        }

        self.repository.save_record(
            event.tenant_id,
            "investigation",
            investigation,
        )

        investigation_event = InfrastructureEvent.create(
            tenant_id=event.tenant_id,
            event_type="security.investigation",
            payload=investigation,
            source=self.worker_id,
            correlation_id=event.correlation_id,
        )

        self.event_bus.publish(
            investigation_event
        )


# ============================================================
# 15. RESPONSE WORKER
# ============================================================

class ResponseWorker(BaseWorker):

    def __init__(
        self,
        worker_id: str,
        event_bus: EventBus,
        repository: DatabaseRepository,
    ) -> None:

        super().__init__(
            worker_id,
            event_bus,
            repository,
        )

        event_bus.subscribe(
            "security.investigation",
            self.process,
        )

    def handle(
        self,
        event: InfrastructureEvent,
    ) -> None:

        """
        Phase 22 only wires response infrastructure.

        Actual connector-backed cyber response authorization and
        execution belong to later product layers.
        """

        response_record = {
            "response_id": new_id_v3("resp"),
            "tenant_id": event.tenant_id,
            "investigation_id": event.payload.get(
                "investigation_id"
            ),
            "status": "queued",
            "created_at": utc_now_v10(),
            "worker_id": self.worker_id,
        }

        self.repository.save_record(
            event.tenant_id,
            "response_queue",
            response_record,
        )


# ============================================================
# 16. WORKER ORCHESTRATOR
# ============================================================

class WorkerOrchestrator:

    def __init__(
        self,
        workers: Iterable[BaseWorker],
        event_bus: InMemoryEventBus,
    ) -> None:

        self.workers = list(workers)
        self.event_bus = event_bus

        self.running = False

    def start(self) -> None:
        for worker in self.workers:
            worker.start()

        self.running = True

    def stop(self) -> None:
        self.running = False

        for worker in self.workers:
            worker.stop()

    def run_once(self) -> bool:
        if not self.running:
            return False

        return self.event_bus.consume_once(
            timeout=0.01
        )

    def drain(
        self,
        limit: int = 1000,
    ) -> int:

        if not self.running:
            return 0

        return self.event_bus.drain(
            limit=limit
        )


# ============================================================
# 17. HORIZONTAL SCALING
# ============================================================

@dataclass
class ScalingDecision:
    desired_workers: int
    reason: str
    queue_depth: int


class HorizontalScaler:

    def __init__(
        self,
        min_workers: int,
        max_workers: int,
        target_queue_depth: int,
    ) -> None:

        self.min_workers = min_workers
        self.max_workers = max_workers
        self.target_queue_depth = target_queue_depth

    def calculate(
        self,
        current_workers: int,
        queue_depth: int,
    ) -> ScalingDecision:

        if queue_depth > self.target_queue_depth:
            desired = min(
                self.max_workers,
                max(
                    current_workers + 1,
                    (
                        queue_depth
                        // self.target_queue_depth
                    ),
                ),
            )

            return ScalingDecision(
                desired_workers=desired,
                reason="queue_pressure",
                queue_depth=queue_depth,
            )

        if (
            queue_depth == 0
            and current_workers > self.min_workers
        ):
            return ScalingDecision(
                desired_workers=max(
                    self.min_workers,
                    current_workers - 1,
                ),
                reason="idle_capacity",
                queue_depth=queue_depth,
            )

        return ScalingDecision(
            desired_workers=current_workers,
            reason="stable",
            queue_depth=queue_depth,
        )


# ============================================================
# 18. AUTOSCALING CONTROLLER
# ============================================================

class AutoscalingController:

    def __init__(
        self,
        scaler: HorizontalScaler,
    ) -> None:

        self.scaler = scaler
        self.current_workers = scaler.min_workers

    def evaluate(
        self,
        queue_depth: int,
    ) -> ScalingDecision:

        decision = self.scaler.calculate(
            current_workers=self.current_workers,
            queue_depth=queue_depth,
        )

        self.current_workers = (
            decision.desired_workers
        )

        metrics.gauge(
            "desired_worker_count",
            self.current_workers,
        )

        return decision


# ============================================================
# 19. HIGH AVAILABILITY
# ============================================================

@dataclass
class NodeHealth:
    node_id: str
    healthy: bool
    last_heartbeat: float
    load: float = 0.0


class HANodeRegistry:

    def __init__(
        self,
        heartbeat_timeout_seconds: int = 30,
    ) -> None:

        self.timeout = heartbeat_timeout_seconds

        self.nodes: Dict[
            str,
            NodeHealth
        ] = {}

        self.lock = threading.RLock()

    def heartbeat(
        self,
        node_id: str,
        load: float = 0.0,
    ) -> None:

        with self.lock:
            self.nodes[node_id] = NodeHealth(
                node_id=node_id,
                healthy=True,
                last_heartbeat=time.time(),
                load=load,
            )

    def health_check(self) -> Dict[str, NodeHealth]:
        now = time.time()

        with self.lock:
            for node in self.nodes.values():
                node.healthy = (
                    now - node.last_heartbeat
                    <= self.timeout
                )

            return dict(self.nodes)

    def healthy_nodes(self) -> List[NodeHealth]:
        return [
            node
            for node in self.health_check().values()
            if node.healthy
        ]


# ============================================================
# 20. BACKUP SYSTEM
# ============================================================

@dataclass
class BackupArtifact:
    backup_id: str
    created_at: str
    source: str
    checksum: str
    size_bytes: int
    status: str


class BackupManager:

    def __init__(
        self,
        object_storage: ObjectStorage,
        retention_count: int = 24,
    ) -> None:

        self.object_storage = object_storage
        self.retention_count = retention_count

        self.backups: deque[
            BackupArtifact
        ] = deque(maxlen=retention_count)

    def create_backup(
        self,
        tenant_id: str,
        data: Dict[str, Any],
    ) -> BackupArtifact:

        payload = json.dumps(
            data,
            sort_keys=True,
            default=str,
        ).encode("utf-8")

        checksum = hashlib.sha256(
            payload
        ).hexdigest()

        backup_id = new_id_v3("backup")

        object_name = (
            f"backups/{backup_id}.json"
        )

        self.object_storage.put(
            tenant_id,
            object_name,
            payload,
        )

        artifact = BackupArtifact(
            backup_id=backup_id,
            created_at=utc_now_v10(),
            source=object_name,
            checksum=checksum,
            size_bytes=len(payload),
            status="completed",
        )

        self.backups.append(artifact)

        metrics.increment(
            "backups_created"
        )

        return artifact


# ============================================================
# 21. DISASTER RECOVERY
# ============================================================

@dataclass
class RecoveryPoint:
    recovery_point_id: str
    created_at: str
    backup_id: str
    checksum: str


class DisasterRecoveryManager:

    def __init__(
        self,
        backup_manager: BackupManager,
    ) -> None:

        self.backup_manager = backup_manager

        self.recovery_points: List[
            RecoveryPoint
        ] = []

    def register_backup(
        self,
        artifact: BackupArtifact,
    ) -> RecoveryPoint:

        point = RecoveryPoint(
            recovery_point_id=new_id_v3("rp"),
            created_at=artifact.created_at,
            backup_id=artifact.backup_id,
            checksum=artifact.checksum,
        )

        self.recovery_points.append(point)

        return point

    def latest_recovery_point(
        self,
    ) -> Optional[RecoveryPoint]:

        if not self.recovery_points:
            return None

        return self.recovery_points[-1]


# ============================================================
# 22. INFRASTRUCTURE SERVICE
# ============================================================

class CyberInfrastructure:

    def __init__(
        self,
        config: Optional[InfrastructureConfig] = None,
        repository: Optional[DatabaseRepository] = None,
        cache: Optional[CacheBackend] = None,
        object_storage: Optional[ObjectStorage] = None,
    ) -> None:

        self.config = (
            config
            or InfrastructureConfig()
        )

        # Development-safe defaults.
        self.repository = (
            repository
            or SQLiteDevelopmentRepository()
        )

        self.cache = (
            cache
            or InMemoryCache()
        )

        self.object_storage = (
            object_storage
            or LocalObjectStorage()
        )

        self.event_bus = InMemoryEventBus(
            maxsize=self.config.queue_maxsize
        )

        self.search = InMemorySearchAnalytics()

        self.rate_limiter = RateLimiter()

        self.api_workers = [
            StatelessAPIWorker(
                worker_id=f"api-{i+1}",
                repository=self.repository,
                event_bus=self.event_bus,
            )
            for i in range(
                self.config.worker_count
            )
        ]

        self.gateway = APIGateway(
            workers=self.api_workers,
            rate_limiter=self.rate_limiter,
        )

        self.detection_worker = DetectionWorker(
            worker_id="detection-1",
            event_bus=self.event_bus,
            repository=self.repository,
        )

        self.investigation_worker = InvestigationWorker(
            worker_id="investigation-1",
            event_bus=self.event_bus,
            repository=self.repository,
        )

        self.response_worker = ResponseWorker(
            worker_id="response-1",
            event_bus=self.event_bus,
            repository=self.repository,
        )

        self.orchestrator = WorkerOrchestrator(
            workers=[
                self.detection_worker,
                self.investigation_worker,
                self.response_worker,
            ],
            event_bus=self.event_bus,
        )

        self.scaler = HorizontalScaler(
            min_workers=self.config.min_workers,
            max_workers=self.config.max_workers,
            target_queue_depth=self.config.target_queue_depth,
        )

        self.autoscaler = AutoscalingController(
            self.scaler
        )

        self.ha_registry = HANodeRegistry(
            heartbeat_timeout_seconds=(
                self.config.heartbeat_timeout_seconds
            )
        )

        self.backup_manager = BackupManager(
            object_storage=self.object_storage,
            retention_count=self.config.retention_count,
        )

        self.dr_manager = DisasterRecoveryManager(
            backup_manager=self.backup_manager
        )

        self.started = False

    def start(self) -> None:
        if self.started:
            return

        self.orchestrator.start()

        health.register("event_bus")
        health.register("database")
        health.register("cache")
        health.register("search")
        health.register("object_storage")
        health.register("api_gateway")

        health.update(
            "event_bus",
            healthy=True,
            ready=True,
        )

        health.update(
            "database",
            healthy=True,
            ready=True,
        )

        health.update(
            "cache",
            healthy=True,
            ready=True,
        )

        health.update(
            "search",
            healthy=True,
            ready=True,
        )

        health.update(
            "object_storage",
            healthy=True,
            ready=True,
        )

        health.update(
            "api_gateway",
            healthy=True,
            ready=True,
        )

        self.started = True

    def stop(self) -> None:
        self.orchestrator.stop()
        self.started = False

    def request(
        self,
        tenant_id: str,
        method: str,
        path: str,
        body: Optional[Dict[str, Any]] = None,
    ) -> APIResponse:

        if not self.started:
            self.start()

        request = APIRequest(
            request_id=new_id_v3("req"),
            tenant_id=tenant_id,
            method=method,
            path=path,
            body=body or {},
        )

        return self.gateway.handle(request)

    def process_events(
        self,
        limit: int = 1000,
    ) -> int:

        return self.orchestrator.drain(
            limit=limit
        )

    def scale(self) -> ScalingDecision:
        decision = self.autoscaler.evaluate(
            self.event_bus.queue_depth()
        )

        return decision

    def heartbeat(
        self,
        node_id: str,
        load: float = 0.0,
    ) -> None:

        self.ha_registry.heartbeat(
            node_id=node_id,
            load=load,
        )

    def backup(
        self,
        tenant_id: str,
    ) -> BackupArtifact:

        records = self.repository.query_records(
            tenant_id=tenant_id,
            limit=10000,
        )

        payload = {
            "tenant_id": tenant_id,
            "records": records,
            "created_at": utc_now_v10(),
        }

        artifact = self.backup_manager.create_backup(
            tenant_id=tenant_id,
            data=payload,
        )

        self.dr_manager.register_backup(
            artifact
        )

        return artifact

    def status(self) -> Dict[str, Any]:

        return {
            "service": self.config.service_name,
            "environment": self.config.environment,
            "started": self.started,
            "health": health.snapshot(),
            "queue_depth": self.event_bus.queue_depth(),
            "dead_letters": len(
                self.event_bus.dead_letters
            ),
            "metrics": metrics.snapshot(),
            "ha_nodes": {
                node.node_id: {
                    "healthy": node.healthy,
                    "load": node.load,
                }
                for node in self.ha_registry.health_check().values()
            },
            "desired_workers": (
                self.autoscaler.current_workers
            ),
        }


# ============================================================
# 23. OPTIONAL FASTAPI ADAPTER
# ============================================================

def create_fastapi_app(
    infrastructure: CyberInfrastructure,
):
    """
    Optional API deployment adapter.

    The core infrastructure remains independent from FastAPI.
    """

    try:
        from fastapi import FastAPI, Header
    except ImportError as exc:
        raise RuntimeError(
            "FastAPI adapter requires fastapi."
        ) from exc

    app = FastAPI(
        title="NEXORA CYBER Infrastructure",
        version="22.0.0",
    )

    @app.get("/health/live")
    def live():
        return {
            "status": "alive"
        }

    @app.get("/health/ready")
    def ready():
        status = infrastructure.status()

        if not status["health"]["ready"]:
            return {
                "status": "not_ready",
                "details": status["health"],
            }

        return {
            "status": "ready"
        }

    @app.get("/infrastructure/status")
    def infrastructure_status():
        return infrastructure.status()

    @app.post("/events")
    def ingest_event(
        body: Dict[str, Any],
        x_tenant_id: str = Header(...),
    ):
        response = infrastructure.request(
            tenant_id=x_tenant_id,
            method="POST",
            path="/events",
            body=body,
        )

        return {
            "request_id": response.request_id,
            "status": response.status_code,
            "body": response.body,
        }

    return app


# ============================================================
# 24. PHASE 22 TESTS
# ============================================================

class Phase22Tests:

    def __init__(self) -> None:
        self.infrastructure = CyberInfrastructure()

    def run_all(self) -> Dict[str, str]:
        tests = [
            self.test_api_gateway,
            self.test_event_bus,
            self.test_detection_worker,
            self.test_investigation_worker,
            self.test_response_worker,
            self.test_tenant_isolation,
            self.test_cache,
            self.test_search,
            self.test_object_storage,
            self.test_scaling,
            self.test_high_availability,
            self.test_backup_dr,
            self.test_health,
            self.test_end_to_end,
        ]

        results: Dict[str, str] = {}

        for test in tests:
            name = test.__name__

            try:
                test()
                results[name] = "PASS"
            except Exception as exc:
                results[name] = (
                    f"FAIL: {type(exc).__name__}: {exc}"
                )

        return results

    def test_api_gateway(self) -> None:
        self.infrastructure.start()

        response = self.infrastructure.request(
            tenant_id="tenant-a",
            method="POST",
            path="/events",
            body={
                "event": "login",
                "suspicious": True,
            },
        )

        assert response.status_code == 202
        assert response.body["accepted"] is True

    def test_event_bus(self) -> None:
        event = InfrastructureEvent.create(
            tenant_id="tenant-a",
            event_type="test.event",
            payload={"x": 1},
        )

        received = []

        self.infrastructure.event_bus.subscribe(
            "test.event",
            lambda e: received.append(e),
        )

        self.infrastructure.event_bus.publish(
            event
        )

        self.infrastructure.event_bus.drain()

        assert len(received) == 1
        assert received[0].payload["x"] == 1

    def test_detection_worker(self) -> None:
        self.infrastructure.start()

        event = InfrastructureEvent.create(
            tenant_id="tenant-a",
            event_type="security.telemetry",
            payload={
                "suspicious": True,
                "severity": "high",
            },
        )

        self.infrastructure.event_bus.publish(
            event
        )

        self.infrastructure.process_events()

        records = self.infrastructure.repository.query_records(
            tenant_id="tenant-a",
            record_type="detection",
        )

        assert len(records) >= 1
        assert records[0]["payload"]["detected"] is True

    def test_investigation_worker(self) -> None:
        self.infrastructure.start()

        event = InfrastructureEvent.create(
            tenant_id="tenant-a",
            event_type="security.telemetry",
            payload={
                "suspicious": True,
            },
        )

        self.infrastructure.event_bus.publish(
            event
        )

        self.infrastructure.process_events()

        records = self.infrastructure.repository.query_records(
            tenant_id="tenant-a",
            record_type="investigation",
        )

        assert len(records) >= 1

    def test_response_worker(self) -> None:
        self.infrastructure.start()

        event = InfrastructureEvent.create(
            tenant_id="tenant-a",
            event_type="security.investigation",
            payload={
                "investigation_id": "inv_test",
            },
        )

        self.infrastructure.event_bus.publish(
            event
        )

        self.infrastructure.process_events()

        records = self.infrastructure.repository.query_records(
            tenant_id="tenant-a",
            record_type="response_queue",
        )

        assert len(records) >= 1

    def test_tenant_isolation(self) -> None:
        self.infrastructure.start()

        self.infrastructure.repository.save_record(
            "tenant-a",
            "secret",
            {"value": "A"},
        )

        self.infrastructure.repository.save_record(
            "tenant-b",
            "secret",
            {"value": "B"},
        )

        tenant_a = (
            self.infrastructure.repository.query_records(
                "tenant-a",
                "secret",
            )
        )

        tenant_b = (
            self.infrastructure.repository.query_records(
                "tenant-b",
                "secret",
            )
        )

        assert all(
            item["payload"]["value"] == "A"
            for item in tenant_a
        )

        assert all(
            item["payload"]["value"] == "B"
            for item in tenant_b
        )

    def test_cache(self) -> None:
        cache = InMemoryCache()

        cache.set(
            "test",
            {"value": 42},
            ttl_seconds=10,
        )

        assert cache.get("test")["value"] == 42

        cache.delete("test")

        assert cache.get("test") is None

    def test_search(self) -> None:
        search = InMemorySearchAnalytics()

        search.index(
            "tenant-a",
            "doc-1",
            {
                "severity": "critical",
                "message": "malware",
            },
        )

        results = search.search(
            "tenant-a",
            "malware",
        )

        assert len(results) == 1

        aggregate = search.aggregate(
            "tenant-a",
            "severity",
        )

        assert aggregate["critical"] == 1

    def test_object_storage(self) -> None:
        storage = LocalObjectStorage()

        uri = storage.put(
            "tenant-a",
            "test.txt",
            b"hello",
        )

        assert uri.startswith(
            "object://tenant-a/"
        )

        assert storage.get(
            "tenant-a",
            "test.txt",
        ) == b"hello"

    def test_scaling(self) -> None:
        scaler = HorizontalScaler(
            min_workers=1,
            max_workers=10,
            target_queue_depth=100,
        )

        decision = scaler.calculate(
            current_workers=2,
            queue_depth=500,
        )

        assert decision.desired_workers > 2

    def test_high_availability(self) -> None:
        registry = HANodeRegistry(
            heartbeat_timeout_seconds=30
        )

        registry.heartbeat(
            "node-1",
            load=0.25,
        )

        healthy = registry.healthy_nodes()

        assert len(healthy) == 1
        assert healthy[0].node_id == "node-1"

    def test_backup_dr(self) -> None:
        storage = LocalObjectStorage()

        backup_manager = BackupManager(
            storage,
            retention_count=5,
        )

        dr = DisasterRecoveryManager(
            backup_manager
        )

        artifact = backup_manager.create_backup(
            "tenant-a",
            {
                "test": True
            },
        )

        point = dr.register_backup(
            artifact
        )

        assert point.backup_id == artifact.backup_id

        latest = dr.latest_recovery_point()

        assert latest is not None

    def test_health(self) -> None:
        self.infrastructure.start()

        status = self.infrastructure.status()

        assert status["health"]["ready"] is True

    def test_end_to_end(self) -> None:
        infrastructure = CyberInfrastructure()
        infrastructure.start()

        response = infrastructure.request(
            tenant_id="enterprise-a",
            method="POST",
            path="/events",
            body={
                "event_type": "endpoint.alert",
                "suspicious": True,
                "severity": "critical",
                "asset": "endpoint-001",
            },
        )

        assert response.status_code == 202

        processed = infrastructure.process_events(
            limit=100,
        )

        assert processed >= 1

        detections = (
            infrastructure.repository.query_records(
                "enterprise-a",
                "detection",
            )
        )

        investigations = (
            infrastructure.repository.query_records(
                "enterprise-a",
                "investigation",
            )
        )

        responses = (
            infrastructure.repository.query_records(
                "enterprise-a",
                "response_queue",
            )
        )

        assert len(detections) >= 1
        assert len(investigations) >= 1
        assert len(responses) >= 1


# ============================================================
# 25. PHASE 22 BOOTSTRAP
# ============================================================

def build_phase22_infrastructure(
    production: bool = False,
) -> CyberInfrastructure:

    config = InfrastructureConfig()

    if production:
        """
        Production configuration is selected through environment
        variables. External infrastructure remains replaceable.
        """

        try:
            repository = PostgreSQLRepository(
                config.postgres_dsn
            )
        except Exception:
            repository = SQLiteDevelopmentRepository()

        try:
            cache = RedisCache(
                config.redis_url
            )
        except Exception:
            cache = InMemoryCache()

    else:
        repository = SQLiteDevelopmentRepository()
        cache = InMemoryCache()

    return CyberInfrastructure(
        config=config,
        repository=repository,
        cache=cache,
        object_storage=LocalObjectStorage(),
    )


# ============================================================
# 26. SELF VERIFICATION
# ============================================================

def verify_phase22() -> Dict[str, Any]:
    """
    Executes the complete Phase 22 infrastructure test suite.
    """

    tests = Phase22Tests()

    results = tests.run_all()

    passed = sum(
        value == "PASS"
        for value in results.values()
    )

    failed = len(results) - passed

    return {
        "phase": 22,
        "tests_total": len(results),
        "passed": passed,
        "failed": failed,
        "status": (
            "PASS"
            if failed == 0
            else "FAIL"
        ),
        "results": results,
    }


