def render_investigation(investigation: InvestigationView) -> str:

    timeline = ""

    for event in investigation.timeline:
        timeline += f"""
        <div class="timeline-item">
            <div class="timeline-dot"></div>

            <div class="timeline-content">
                <small>{esc(event.timestamp)}</small>
                <h3>{esc(event.title)}</h3>
                <p>{esc(event.description)}</p>

                {severity_badge(event.severity)
                if event.severity else ""}
            </div>
        </div>
        """

    evidence = ""

    for item in investigation.evidence:
        evidence += f"""
        <div class="evidence-card">
            <div class="evidence-title">
                <b>{esc(item.evidence_type)}</b>
                <span>{item.confidence:.0%}</span>
            </div>

            <p>{esc(item.summary)}</p>

            <small>
                Source: {esc(item.source)} |
                Collected: {esc(item.collected_at)}
            </small>
        </div>
        """

    entities = ""

    for entity in investigation.entities:
        risk = (
            f"{entity.risk:.0f}"
            if entity.risk is not None
            else "—"
        )

        entities += f"""
        <div class="entity-chip">
            <span>{esc(entity.entity_type)}</span>
            <b>{esc(entity.name)}</b>
            <small>Risk {risk}</small>
        </div>
        """

    intel = ""

    for item in investigation.threat_intelligence:
        intel += f"""
        <div class="intel-card">
            <b>{esc(item.indicator)}</b>

            <span>
                {esc(item.indicator_type)} ·
                {esc(item.reputation)}
            </span>

            <small>
                Confidence {item.confidence:.0%} ·
                Source {esc(item.source)}
            </small>

            <small>
                Technique:
                {esc(item.technique or "Unmapped")}
            </small>
        </div>
        """

    reasoning = "".join(
        f"<li>{esc(item)}</li>"
        for item in investigation.reasoning
    )

    return f"""
    <section class="workspace-header">
        <button onclick="showDashboard()">← Command Center</button>

        <div>
            <h1>Investigation {esc(investigation.id)}</h1>
            <p>
                Incident:
                <b>{esc(investigation.incident_id)}</b>
            </p>
        </div>

        {status_badge(investigation.status)}
    </section>

    <section class="finding-banner">
        <div>
            <span>Current Assessment</span>
            <h2>{esc(investigation.conclusion)}</h2>
        </div>

        <strong>{investigation.confidence:.0%}</strong>
    </section>

    <div class="workspace-grid">

        <section class="panel">
            <div class="panel-header">
                <h2>Investigation Timeline</h2>
            </div>

            <div class="timeline">
                {timeline}
            </div>
        </section>

        <section class="panel">
            <div class="panel-header">
                <h2>Reasoning</h2>
            </div>

            <ol class="reasoning-list">
                {reasoning}
            </ol>
        </section>

    </div>

    <div class="workspace-grid">

        <section class="panel">
            <div class="panel-header">
                <h2>Evidence</h2>
            </div>

            {evidence}
        </section>

        <section class="panel">
            <div class="panel-header">
                <h2>Entities</h2>
            </div>

            <div class="entity-list">
                {entities}
            </div>
        </section>

    </div>

    <section class="panel">
        <div class="panel-header">
            <h2>Threat Intelligence</h2>
        </div>

        <div class="intel-list">
            {intel}
        </div>
    </section>

    <section class="panel">
        <div class="panel-header">
            <h2>Investigation Graph</h2>
        </div>

        <div id="investigationGraph" class="graph">
            <div class="graph-node">Identity</div>
            <div class="graph-line">↓</div>
            <div class="graph-node">Device</div>
            <div class="graph-line">↓</div>
            <div class="graph-node">Process</div>
            <div class="graph-line">↓</div>
            <div class="graph-node">Network</div>
            <div class="graph-line">↓</div>
            <div class="graph-node">IOC</div>
            <div class="graph-line">↓</div>
            <div class="graph-node">Critical Asset</div>
        </div>
    </section>

    <section class="panel">
        <div class="panel-header">
            <h2>Available Actions</h2>
        </div>

        <div class="action-grid">
            <button onclick="previewAction('collect-evidence')">
                Collect Evidence
            </button>

            <button onclick="previewAction('isolate-endpoint')">
                Evaluate Endpoint Isolation
            </button>

            <button onclick="previewAction('revoke-session')">
                Evaluate Session Revocation
            </button>
        </div>
    </section>
    """


