SCRIPT = r"""
async function api(path, options = {}) {
    const response = await fetch(path, {
        headers: {
            "Content-Type": "application/json"
        },
        ...options
    });

    if (!response.ok) {
        throw new Error(await response.text());
    }

    return response.json();
}


function setActive(buttonId) {
    document.querySelectorAll(".nav-button")
        .forEach(x => x.classList.remove("active"));

    const element = document.getElementById(buttonId);

    if (element) {
        element.classList.add("active");
    }
}


async function showDashboard() {
    setActive("nav-dashboard");

    document.getElementById("page").innerHTML =
        await api("/api/dashboard-html").then(x => x.html);
}


async function showCopilot() {
    setActive("nav-copilot");

    document.getElementById("page").innerHTML =
        await api("/api/copilot-html").then(x => x.html);
}


async function openInvestigation(incidentId) {
    document.getElementById("page").innerHTML =
        await api(
            "/api/investigation?incident_id=" +
            encodeURIComponent(incidentId)
        ).then(x => x.html);
}


async function openIncident(threatId) {
    /*
     * Threat -> investigation navigation.
     * The backend resolves the actual relationship.
     */
    document.getElementById("page").innerHTML =
        await api(
            "/api/threat/" +
            encodeURIComponent(threatId)
        ).then(x => x.html);
}


async function refreshDashboard() {
    await showDashboard();
}


async function previewAction(actionId) {
    const result = await api(
        "/api/action/preview",
        {
            method: "POST",
            body: JSON.stringify({
                action_id: actionId
            })
        }
    );

    const simulation = result.simulation || {};

    alert(
        "ACTION PREVIEW\n\n" +
        "Security benefit: " +
        simulation.security_benefit + "\n\n" +
        "Operational risk: " +
        simulation.operational_risk + "\n\n" +
        "Recommendation: " +
        simulation.recommendation
    );
}


async function askCopilot() {
    const input =
        document.getElementById("copilotQuestion");

    const question = input.value.trim();

    if (!question) {
        return;
    }

    const messages =
        document.getElementById("copilotMessages");

    const userMessage =
        document.createElement("div");

    userMessage.className = "user-message";

    userMessage.innerHTML =
        "<b>You</b><p>" +
        escapeHtml(question) +
        "</p>";

    messages.appendChild(userMessage);

    input.value = "";

    const thinking =
        document.createElement("div");

    thinking.className = "assistant-message";

    thinking.innerHTML =
        "<b>NEXORA</b><p>Analyzing security context…</p>";

    messages.appendChild(thinking);

    messages.scrollTop = messages.scrollHeight;

    try {
        const result = await api(
            "/api/copilot",
            {
                method: "POST",
                body: JSON.stringify({
                    question: question
                })
            }
        );

        const evidence =
            (result.evidence_ids || [])
            .map(x => "<li>" + escapeHtml(x) + "</li>")
            .join("");

        const entities =
            (result.related_entities || [])
            .map(x => "<li>" + escapeHtml(x) + "</li>")
            .join("");

        const actions =
            (result.suggested_actions || [])
            .map(x => "<li>" + escapeHtml(x) + "</li>")
            .join("");

        thinking.innerHTML =
            "<b>NEXORA</b>" +
            "<p>" +
            escapeHtml(result.answer) +
            "</p>" +

            "<small>Confidence: " +
            Math.round((result.confidence || 0) * 100) +
            "%</small>" +

            "<hr>" +

            "<b>Evidence</b>" +
            "<ul>" + evidence + "</ul>" +

            "<b>Related entities</b>" +
            "<ul>" + entities + "</ul>" +

            "<b>Suggested actions</b>" +
            "<ul>" + actions + "</ul>";

    } catch (error) {
        thinking.innerHTML =
            "<b>NEXORA</b>" +
            "<p>Unable to retrieve grounded response.</p>";
    }

    messages.scrollTop = messages.scrollHeight;
}


function copilotKeydown(event) {
    if (event.key === "Enter" && !event.shiftKey) {
        event.preventDefault();
        askCopilot();
    }
}


function escapeHtml(value) {
    const div = document.createElement("div");
    div.textContent = value;
    return div.innerHTML;
}


showDashboard();
"""


# ============================================================
# HTTP API
# ============================================================

class CyberFrontendHandler(BaseHTTPRequestHandler):

    def send_json(
        self,
        payload: Dict[str, Any],
        status: int = 200
    ) -> None:

        body = json.dumps(
            payload,
            ensure_ascii=False
        ).encode("utf-8")

        self.send_response(status)
        self.send_header(
            "Content-Type",
            "application/json; charset=utf-8"
        )
        self.send_header(
            "Content-Length",
            str(len(body))
        )
        self.end_headers()

        self.wfile.write(body)

    def send_html(
        self,
        body: str,
        status: int = 200
    ) -> None:

        payload = body.encode("utf-8")

        self.send_response(status)
        self.send_header(
            "Content-Type",
            "text/html; charset=utf-8"
        )
        self.send_header(
            "Content-Length",
            str(len(payload))
        )
        self.end_headers()

        self.wfile.write(payload)

    def read_json(self) -> Dict[str, Any]:
        length = int(
            self.headers.get("Content-Length", "0")
        )

        if length <= 0:
            return {}

        raw = self.rfile.read(length)

        try:
            return json.loads(
                raw.decode("utf-8")
            )
        except json.JSONDecodeError:
            return {}

    def do_GET(self) -> None:

        parsed = urllib.parse.urlparse(
            self.path
        )

        path = parsed.path

        if path == "/":
            self.send_html(MAIN_HTML)
            return

        if path == "/api/dashboard-html":
            self.send_json({
                "html": render_dashboard()
            })
            return

        if path == "/api/copilot-html":
            self.send_json({
                "html": render_copilot()
            })
            return

        if path == "/api/investigation":
            params = urllib.parse.parse_qs(
                parsed.query
            )

            incident_id = params.get(
                "incident_id",
                ["INC-1042"]
            )[0]

            investigation = (
                adapter.get_investigation(
                    incident_id
                )
            )

            self.send_json({
                "html": render_investigation(
                    investigation
                )
            })
            return

        if path.startswith("/api/threat/"):
            threat_id = path.split("/")[-1]

            incidents = adapter.get_incidents()

            incident = incidents[0]

            investigation = (
                adapter.get_investigation(
                    incident.id
                )
            )

            self.send_json({
                "html": render_investigation(
                    investigation
                ),
                "threat_id": threat_id,
            })
            return

        self.send_json(
            {"error": "Not found"},
            status=404
        )

    def do_POST(self) -> None:

        path = urllib.parse.urlparse(
            self.path
        ).path

        data = self.read_json()

        if path == "/api/copilot":

            question = str(
                data.get("question", "")
            )

            result = adapter.ask_copilot(
                question
            )

            self.send_json(
                asdict(result)
            )

            return

        if path == "/api/action/preview":

            action_id = str(
                data.get("action_id", "")
            )

            result = (
                adapter.request_action_preview(
                    action_id
                )
            )

            self.send_json(result)

            return

        self.send_json(
            {"error": "Not found"},
            status=404
        )

    def log_message(
        self,
        format: str,
        *args: Any
    ) -> None:
        return


