# ============================================================
# BASIC FRONTEND VERIFICATION
# ============================================================

def verify_frontend_contracts() -> None:

    assert "Security Command Center" in MAIN_HTML
    assert "AI Security Copilot" in MAIN_HTML
    assert "Investigation Workspace" not in MAIN_HTML

    dashboard = render_dashboard()

    assert "Critical Threats" in dashboard
    assert "Active Incidents" in dashboard
    assert "High-Risk Assets" in dashboard
    assert "Pending Approvals" in dashboard
    assert "Autonomous Operations" in dashboard
    assert "Attack Paths" in dashboard

    investigation = adapter.get_investigation(
        "INC-1042"
    )

    rendered = render_investigation(
        investigation
    )

    assert "Investigation Timeline" in rendered
    assert "Evidence" in rendered
    assert "Entities" in rendered
    assert "Threat Intelligence" in rendered
    assert "Reasoning" in rendered
    assert "Investigation Graph" in rendered

    copilot = adapter.ask_copilot(
        "Why is this incident high risk?"
    )

    assert copilot.answer
    assert copilot.confidence >= 0
    assert copilot.evidence_ids
    assert copilot.related_entities

    preview = adapter.request_action_preview(
        "ACT-702"
    )

    assert preview["execution_allowed"] is False

    print(
        "[PASS] Phase 23 frontend contracts verified."
    )


# ============================================================
# SERVER
# ============================================================

def main() -> None:

    verify_frontend_contracts()

    server = ThreadingHTTPServer(
        ("127.0.0.1", 8080),
        CyberFrontendHandler
    )

    print(
        "NEXORA CYBER™ Phase 23 Frontend"
    )

    print(
        "Running at http://127.0.0.1:8080"
    )

    try:
        server.serve_forever()

    except KeyboardInterrupt:
        print("\nStopping frontend...")

    finally:
        server.server_close()


