# [dedup-fix] removed duplicate: from __future__ import annotations

import asyncio
import inspect
import json
import random
import statistics
import time
import traceback
import uuid

from dataclasses import dataclass, field, asdict
from datetime import datetime, timezone
from enum import Enum
from typing import (
    Any,
    Awaitable,
    Callable,
    Dict,
    Iterable,
    List,
    Mapping,
    Optional,
    Protocol,
    Sequence,
    Tuple,
)


# ============================================================
# 1. COMMON TEST TYPES
# ============================================================

class TestType(str, Enum):
    UNIT = "unit"
    CONTRACT = "contract"
    INTEGRATION = "integration"
    SECURITY = "security"
    E2E = "end_to_end"
    FAILURE = "failure"
    LOAD = "load"
    ADVERSARIAL = "adversarial"
    SCENARIO = "realistic_cyber_scenario"


class TestStatus(str, Enum):
    PASS = "pass"
    FAIL = "fail"
    ERROR = "error"
    SKIP = "skip"


class Severity(str, Enum):
    INFO = "info"
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"
    WARNING = 'warning'  # merged from Severity
    ERROR = 'error'  # merged from Severity
    DEBUG = 'DEBUG'  # merged from Severity


# ============================================================
# 2. TEST RESULT MODELS
# ============================================================

@dataclass
class AssertionResult:
    name: str
    passed: bool
    expected: Any = None
    actual: Any = None
    message: str = ""


@dataclass
class TestResult:
    test_id: str
    name: str
    test_type: TestType
    status: TestStatus
    duration_ms: float
    severity: Severity = Severity.INFO
    assertions: List[AssertionResult] = field(default_factory=list)
    error: Optional[str] = None
    traceback_text: Optional[str] = None
    metadata: Dict[str, Any] = field(default_factory=dict)
    timestamp: str = field(
        default_factory=lambda: datetime.now(timezone.utc).isoformat()
    )

    @property
    def passed(self) -> bool:
        return self.status == TestStatus.PASS


@dataclass
class TestSuiteResult:
    suite_id: str
    name: str
    results: List[TestResult] = field(default_factory=list)
    started_at: str = field(
        default_factory=lambda: datetime.now(timezone.utc).isoformat()
    )
    finished_at: Optional[str] = None

    @property
    def total(self) -> int:
        return len(self.results)

    @property
    def passed(self) -> int:
        return sum(r.status == TestStatus.PASS for r in self.results)

    @property
    def failed(self) -> int:
        return sum(r.status == TestStatus.FAIL for r in self.results)

    @property
    def errors(self) -> int:
        return sum(r.status == TestStatus.ERROR for r in self.results)

    @property
    def skipped(self) -> int:
        return sum(r.status == TestStatus.SKIP for r in self.results)

    @property
    def pass_rate(self) -> float:
        if not self.total:
            return 1.0
        return self.passed / self.total


# ============================================================
# 3. TEST ASSERTIONS
# ============================================================

class TestAssertionError(AssertionError):
    pass


class Assert:
    @staticmethod
    def true(value: Any, message: str = "") -> None:
        if not value:
            raise TestAssertionError(
                message or f"Expected truthy value, got {value!r}"
            )

    @staticmethod
    def false(value: Any, message: str = "") -> None:
        if value:
            raise TestAssertionError(
                message or f"Expected falsy value, got {value!r}"
            )

    @staticmethod
    def equal(expected: Any, actual: Any, message: str = "") -> None:
        if expected != actual:
            raise TestAssertionError(
                message
                or f"Expected {expected!r}, got {actual!r}"
            )

    @staticmethod
    def not_equal(left: Any, right: Any, message: str = "") -> None:
        if left == right:
            raise TestAssertionError(
                message or f"Expected values to differ: {left!r}"
            )

    @staticmethod
    def contains(container: Any, item: Any, message: str = "") -> None:
        if item not in container:
            raise TestAssertionError(
                message
                or f"Expected {container!r} to contain {item!r}"
            )

    @staticmethod
    def not_none(value: Any, message: str = "") -> None:
        if value is None:
            raise TestAssertionError(
                message or "Expected value to be non-None"
            )

    @staticmethod
    def instance_of(value: Any, expected_type: type, message: str = "") -> None:
        if not isinstance(value, expected_type):
            raise TestAssertionError(
                message
                or f"Expected {expected_type}, got {type(value)}"
            )

    @staticmethod
    def greater_than(actual: float, minimum: float, message: str = "") -> None:
        if not actual > minimum:
            raise TestAssertionError(
                message
                or f"Expected {actual} > {minimum}"
            )

    @staticmethod
    def less_equal(actual: float, maximum: float, message: str = "") -> None:
        if not actual <= maximum:
            raise TestAssertionError(
                message
                or f"Expected {actual} <= {maximum}"
            )


# ============================================================
# 4. COMPONENT ADAPTER
# ============================================================

class CyberComponent(Protocol):

    def health(self) -> Mapping[str, Any]:
        ...

    def process(self, payload: Mapping[str, Any]) -> Any:
        ...


@dataclass
class ComponentAdapter:
    """
    Generic adapter allowing Phase 24 to validate existing
    Phase 21–23 components without importing their implementations.
    """

    name: str
    component: Any

    def health(self) -> Mapping[str, Any]:
        method = getattr(self.component, "health", None)

        if method is None:
            return {
                "status": "unknown",
                "component": self.name,
            }

        result = method()

        if inspect.isawaitable(result):
            raise RuntimeError(
                f"{self.name}.health() is async; use AsyncComponentAdapter."
            )

        return result

    def process(self, payload: Mapping[str, Any]) -> Any:
        method = getattr(self.component, "process", None)

        if method is None:
            raise AttributeError(
                f"Component '{self.name}' does not expose process()."
            )

        return method(payload)


@dataclass
class AsyncComponentAdapter:
    name: str
    component: Any

    async def health(self) -> Mapping[str, Any]:
        method = getattr(self.component, "health", None)

        if method is None:
            return {
                "status": "unknown",
                "component": self.name,
            }

        result = method()

        if inspect.isawaitable(result):
            result = await result

        return result

    async def process(self, payload: Mapping[str, Any]) -> Any:
        method = getattr(self.component, "process", None)

        if method is None:
            raise AttributeError(
                f"Component '{self.name}' does not expose process()."
            )

        result = method(payload)

        if inspect.isawaitable(result):
            result = await result

        return result


# ============================================================
# 5. TEST CASE DEFINITION
# ============================================================

@dataclass
class TestCase:
    name: str
    test_type: TestType
    function: Callable[[], Any]
    severity: Severity = Severity.MEDIUM
    metadata: Dict[str, Any] = field(default_factory=dict)


# ============================================================
# 6. TEST RUNNER
# ============================================================

class TestRunner:

    def __init__(self):
        self.tests: List[TestCase] = []

    def register(
        self,
        name: str,
        test_type: TestType,
        function: Callable[[], Any],
        severity: Severity = Severity.MEDIUM,
        metadata: Optional[Dict[str, Any]] = None,
    ) -> None:
        self.tests.append(
            TestCase(
                name=name,
                test_type=test_type,
                function=function,
                severity=severity,
                metadata=metadata or {},
            )
        )

    async def _execute(self, test: TestCase) -> TestResult:
        started = time.perf_counter()

        assertions: List[AssertionResult] = []

        try:
            result = test.function()

            if inspect.isawaitable(result):
                result = await result

            if isinstance(result, list):
                assertions.extend(
                    a for a in result if isinstance(a, AssertionResult)
                )

            duration = (time.perf_counter() - started) * 1000

            return TestResult(
                test_id=str(uuid.uuid4()),
                name=test.name,
                test_type=test.test_type,
                status=TestStatus.PASS,
                duration_ms=duration,
                severity=test.severity,
                assertions=assertions,
                metadata=test.metadata,
            )

        except TestAssertionError as exc:
            duration = (time.perf_counter() - started) * 1000

            return TestResult(
                test_id=str(uuid.uuid4()),
                name=test.name,
                test_type=test.test_type,
                status=TestStatus.FAIL,
                duration_ms=duration,
                severity=test.severity,
                error=str(exc),
                metadata=test.metadata,
            )

        except Exception as exc:
            duration = (time.perf_counter() - started) * 1000

            return TestResult(
                test_id=str(uuid.uuid4()),
                name=test.name,
                test_type=test.test_type,
                status=TestStatus.ERROR,
                duration_ms=duration,
                severity=test.severity,
                error=str(exc),
                traceback_text=traceback.format_exc(),
                metadata=test.metadata,
            )

    async def run(self) -> TestSuiteResult:
        suite = TestSuiteResult(
            suite_id=str(uuid.uuid4()),
            name="NEXORA CYBER Phase 24 Validation",
        )

        for test in self.tests:
            suite.results.append(await self._execute(test))

        suite.finished_at = datetime.now(timezone.utc).isoformat()

        return suite


# ============================================================
# 7. CONTRACT TESTING
# ============================================================

class ContractTester:

    REQUIRED_COMPONENT_METHODS = (
        "process",
    )

    def __init__(self, runner: TestRunner):
        self.runner = runner

    def register_component_contract(
        self,
        adapter: ComponentAdapter,
    ) -> None:

        def contract() -> None:
            for method_name in self.REQUIRED_COMPONENT_METHODS:
                method = getattr(adapter.component, method_name, None)

                Assert.not_none(
                    method,
                    f"{adapter.name}: missing required method {method_name}",
                )

                Assert.true(
                    callable(method),
                    f"{adapter.name}: {method_name} is not callable",
                )

        self.runner.register(
            name=f"contract:{adapter.name}",
            test_type=TestType.CONTRACT,
            function=contract,
            severity=Severity.HIGH,
            metadata={"component": adapter.name},
        )


