# 14. E2E LIFECYCLE TESTING
# ============================================================

class E2ETester:

    REQUIRED_STAGES = (
        "observe",
        "detect",
        "correlate",
        "investigate",
        "reason",
        "risk_assess",
        "predict",
        "simulate",
        "plan",
        "govern",
        "approve",
        "execute",
        "verify",
        "learn",
        "update_posture",
    )

    def __init__(self, runner: TestRunner):
        self.runner = runner

    def register_lifecycle_test(
        self,
        lifecycle: Any,
    ) -> None:

        def test() -> None:
            method = getattr(
                lifecycle,
                "run",
                None,
            )

            Assert.not_none(
                method,
                "Autonomous lifecycle does not expose run()",
            )

            result = method(
                {
                    "tenant_id": "e2e-test",
                    "event_id": str(uuid.uuid4()),
                    "event_type": "authentication",
                    "severity": "high",
                }
            )

            Assert.not_none(result)

            if isinstance(result, Mapping):
                stages = result.get("stages")

                if stages is not None:
                    for stage in self.REQUIRED_STAGES:
                        Assert.contains(
                            stages,
                            stage,
                            f"Lifecycle missing stage: {stage}",
                        )

        self.runner.register(
            name="e2e:autonomous-security-lifecycle",
            test_type=TestType.E2E,
            function=test,
            severity=Severity.CRITICAL,
        )


