class ScenarioTester:

    def __init__(self, runner: TestRunner):
        self.runner = runner

    def register(
        self,
        component: ComponentAdapter,
        scenario: CyberScenario,
    ) -> None:

        def test() -> None:
            outputs = []

            for event in scenario.events:
                payload = {
                    "tenant_id": "scenario-test",
                    "scenario": scenario.name,
                    "event_id": str(uuid.uuid4()),
                    "untrusted": True,
                    **event,
                }

                result = component.process(payload)

                Assert.not_none(result)

                outputs.append(result)

            serialized = json.dumps(
                outputs,
                default=str,
            ).lower()

            # Scenario validation is deliberately evidence-oriented:
            # it checks that the component processes the scenario,
            # rather than fabricating a successful detection.
            matched = [
                indicator
                for indicator in scenario.expected_indicators
                if indicator.lower() in serialized
            ]

            Assert.greater_than(
                len(matched),
                0,
                (
                    f"{component.name} produced no recognizable "
                    f"scenario indicators for {scenario.name}"
                ),
            )

        self.runner.register(
            name=f"scenario:{component.name}:{scenario.name}",
            test_type=TestType.SCENARIO,
            function=test,
            severity=scenario.severity,
            metadata={
                "scenario": scenario.name,
                "description": scenario.description,
            },
        )


# ============================================================
# 16. VERIFICATION OF TEST RESULTS
# ============================================================

@dataclass
class ValidationGate:
    name: str
    passed: bool
    reason: str


class ValidationVerifier:

    def verify(
        self,
        suite: TestSuiteResult,
    ) -> List[ValidationGate]:

        gates: List[ValidationGate] = []

        gates.append(
            ValidationGate(
                name="no-test-errors",
                passed=suite.errors == 0,
                reason=(
                    "No test execution errors"
                    if suite.errors == 0
                    else f"{suite.errors} test execution errors"
                ),
            )
        )

        gates.append(
            ValidationGate(
                name="no-test-failures",
                passed=suite.failed == 0,
                reason=(
                    "No failed tests"
                    if suite.failed == 0
                    else f"{suite.failed} tests failed"
                ),
            )
        )

        critical_failures = [
            r
            for r in suite.results
            if r.status in (
                TestStatus.FAIL,
                TestStatus.ERROR,
            )
            and r.severity == Severity.CRITICAL
        ]

        gates.append(
            ValidationGate(
                name="critical-security-gate",
                passed=len(critical_failures) == 0,
                reason=(
                    "No critical validation failures"
                    if not critical_failures
                    else (
                        f"{len(critical_failures)} "
                        "critical validation failures"
                    )
                ),
            )
        )

        return gates


