# 18. PHASE 24 VALIDATION HARNESS
# ============================================================

class Phase24Validation:

    def __init__(self):
        self.runner = TestRunner()

        self.contract = ContractTester(
            self.runner
        )

        self.unit = UnitTester(
            self.runner
        )

        self.integration = IntegrationTester(
            self.runner
        )

        self.security = SecurityTester(
            self.runner
        )

        self.failure = FailureInjector(
            self.runner
        )

        self.adversarial = AdversarialTester(
            self.runner
        )

        self.load = LoadTester(
            self.runner
        )

        self.e2e = E2ETester(
            self.runner
        )

        self.scenarios = ScenarioTester(
            self.runner
        )

        self.verifier = ValidationVerifier()

        self.components: Dict[str, ComponentAdapter] = {}

    def register_component(
        self,
        name: str,
        component: Any,
        *,
        include_load_test: bool = True,
    ) -> None:

        adapter = ComponentAdapter(
            name=name,
            component=component,
        )

        self.components[name] = adapter

        self.contract.register_component_contract(
            adapter
        )

        self.unit.register_basic_component_test(
            adapter
        )

        self.security.register_tenant_isolation_test(
            adapter
        )

        self.security.register_secret_leak_test(
            adapter
        )

        self.failure.register_malformed_input_test(
            adapter
        )

        self.failure.register_repeated_failure_test(
            adapter
        )

        self.adversarial.register_prompt_injection_test(
            adapter
        )

        self.adversarial.register_malicious_telemetry_test(
            adapter
        )

        if include_load_test:
            self.load.register_load_test(
                adapter
            )

        for scenario in ScenarioLibrary.all():
            self.scenarios.register(
                adapter,
                scenario,
            )

    def register_integration_pipeline(
        self,
        name: str,
        component_names: Sequence[str],
    ) -> None:

        missing = [
            name
            for name in component_names
            if name not in self.components
        ]

        if missing:
            raise ValueError(
                f"Unknown components: {missing}"
            )

        components = [
            self.components[name]
            for name in component_names
        ]

        self.integration.register_pipeline_test(
            name,
            components,
        )

    def register_lifecycle(
        self,
        lifecycle: Any,
    ) -> None:

        self.e2e.register_lifecycle_test(
            lifecycle
        )

    async def run(self) -> Dict[str, Any]:

        suite = await self.runner.run()

        gates = self.verifier.verify(
            suite
        )

        return ValidationReport.build(
            suite,
            gates,
        )


# ============================================================
# 19. SAFE LOCAL TEST COMPONENT
# ============================================================

class Phase24TestDouble:
    """
    Test-only component.

    This is NOT a Cyber production engine.
    It exists solely so the Phase 24 framework can execute
    its own self-validation when no Phase 21–23 runtime is
    attached yet.
    """

    def health(self) -> Mapping[str, Any]:
        return {
            "status": "healthy",
            "component": "phase24-test-double",
        }

    def process(
        self,
        payload: Mapping[str, Any],
    ) -> Mapping[str, Any]:

        if payload is None:
            raise ValueError("payload cannot be None")

        if not isinstance(payload, Mapping):
            raise TypeError("payload must be a mapping")

        event_type = payload.get("event_type")

        if event_type == "__INVALID_EVENT__":
            raise ValueError("unsupported event")

        return {
            "processed": True,
            "tenant_id": payload.get("tenant_id"),
            "event_type": event_type,
            "scenario": payload.get("scenario"),
            "indicator": self._indicator(payload),
            "simulation": True,
        }

    @staticmethod
    def _indicator(
        payload: Mapping[str, Any],
    ) -> str:

        text = json.dumps(
            payload,
            default=str,
        ).lower()

        indicators = [
            "encryption",
            "ransom",
            "credential",
            "authentication",
            "privileged",
            "lateral",
            "remote",
            "privilege",
            "escalation",
            "cloud",
            "security",
            "data",
            "outbound",
            "transfer",
            "anomaly",
            "unusual",
            "behavior",
            "exposed",
            "vulnerability",
            "exploit",
            "identity",
            "initial",
            "exfil",
        ]

        for indicator in indicators:
            if indicator in text:
                return indicator

        return "processed"


# ============================================================
# 20. PHASE 24 SELF-TEST
# ============================================================

async def phase24_self_test() -> Dict[str, Any]:

    validation = Phase24Validation()

    validation.register_component(
        "phase24-test-double",
        Phase24TestDouble(),
        include_load_test=True,
    )

    return await validation.run()


# ============================================================
# 21. OPTIONAL RUNTIME INTEGRATION
# ============================================================

async def validate_existing_cyber_runtime(
    components: Mapping[str, Any],
    lifecycle: Optional[Any] = None,
) -> Dict[str, Any]:
    """
    Attach existing Phase 21–23 components.

    Example:

        report = await validate_existing_cyber_runtime(
            {
                "cyber-core": cyber_core,
                "cyber-data-fabric": data_fabric,
                "cyber-governance": governance,
                "cyber-response": response,
            },
            lifecycle=autonomous_lifecycle,
        )

    No production component is created here.
    """

    validation = Phase24Validation()

    for name, component in components.items():
        validation.register_component(
            name,
            component,
        )

    names = list(components.keys())

    if len(names) >= 2:
        validation.register_integration_pipeline(
            "cyber-component-integration",
            names,
        )

    if lifecycle is not None:
        validation.register_lifecycle(
            lifecycle
        )

    return await validation.run()


# ============================================================
# 22. REPORT FORMATTER
# ============================================================

def format_validation_summary(
    report: Mapping[str, Any],
) -> str:

    summary = report["summary"]

    lines = [
        "",
        "============================================================",
        "NEXORA CYBER™ — PHASE 24 VALIDATION RESULT",
        "============================================================",
        f"Total Tests : {summary['total']}",
        f"Passed      : {summary['passed']}",
        f"Failed      : {summary['failed']}",
        f"Errors      : {summary['errors']}",
        f"Skipped     : {summary['skipped']}",
        f"Pass Rate   : {summary['pass_rate'] * 100:.2f}%",
        "",
        "VALIDATION GATES",
        "------------------------------------------------------------",
    ]

    for gate in report["gates"]:
        state = "PASS" if gate["passed"] else "FAIL"
        lines.append(
            f"[{state}] {gate['name']} — {gate['reason']}"
        )

    lines.extend(
        [
            "",
            "TEST CATEGORIES",
            "------------------------------------------------------------",
        ]
    )

    for category, values in report["by_type"].items():
        lines.append(
            f"{category}: "
            f"{values['passed']}/{values['total']} passed"
        )

    lines.append(
        "============================================================"
    )

    return "\n".join(lines)


# ============================================================
# 23. COMMAND-LINE ENTRY
# ============================================================

def main_v2() -> None:

    report = asyncio.run(
        phase24_self_test()
    )

    print(
        format_validation_summary(
            report
        )
    )

    # Machine-readable output is intentionally available
    # without creating any file.
    print(
        json.dumps(
            report,
            indent=2,
            default=str,
        )
    )


