# ============================================================
# 1. DEPLOYMENT MODES
# ============================================================

class DeploymentMode(str, Enum):
    SAAS = "saas"
    DEDICATED_TENANT = "dedicated_tenant"
    PRIVATE_CLOUD = "private_cloud"
    ON_PREM = "on_prem"
    HYBRID = "hybrid"


class Environment(str, Enum):
    DEVELOPMENT = "development"
    TESTING = "testing"
    STAGING = "staging"
    PRODUCTION = "production"


class ServiceState(str, Enum):
    STARTING = "starting"
    READY = "ready"
    DEGRADED = "degraded"
    STOPPING = "stopping"
    STOPPED = "stopped"
    FAILED = "failed"
    CREATED = 'created'  # merged from ServiceState
    RUNNING = 'running'  # merged from ServiceState


# ============================================================
# 2. DEPLOYMENT CONFIGURATION
# ============================================================

@dataclass(frozen=True)
class DeploymentConfig:
    deployment_id: str
    mode: DeploymentMode
    environment: Environment

    region: str = "default"
    tenant_id: Optional[str] = None

    api_host: str = "0.0.0.0"
    api_port: int = 8000

    event_bus_endpoint: Optional[str] = None
    database_endpoint: Optional[str] = None
    redis_endpoint: Optional[str] = None
    search_endpoint: Optional[str] = None
    object_storage_endpoint: Optional[str] = None

    tls_enabled: bool = True
    encryption_enabled: bool = True

    replicas: int = 1
    worker_count: int = 1

    autoscaling_enabled: bool = False
    high_availability: bool = False

    health_timeout_seconds: float = 5.0

    metadata: Mapping[str, Any] = field(
        default_factory=dict
    )


# ============================================================
# 3. CONFIGURATION VALIDATION
# ============================================================

@dataclass
class ConfigIssue:
    field: str
    message: str
    severity: str


@dataclass
class ConfigValidationResult:
    valid: bool
    issues: List[ConfigIssue] = field(
        default_factory=list
    )


class DeploymentConfigValidator:

    @staticmethod
    def validate(
        config: DeploymentConfig,
    ) -> ConfigValidationResult:

        issues: List[ConfigIssue] = []

        if not config.deployment_id:
            issues.append(
                ConfigIssue(
                    "deployment_id",
                    "deployment_id is required",
                    "error",
                )
            )

        if config.api_port < 1 or config.api_port > 65535:
            issues.append(
                ConfigIssue(
                    "api_port",
                    "api_port must be between 1 and 65535",
                    "error",
                )
            )

        if config.replicas < 1:
            issues.append(
                ConfigIssue(
                    "replicas",
                    "replicas must be >= 1",
                    "error",
                )
            )

        if config.worker_count < 1:
            issues.append(
                ConfigIssue(
                    "worker_count",
                    "worker_count must be >= 1",
                    "error",
                )
            )

        if config.environment == Environment.PRODUCTION:

            if not config.tls_enabled:
                issues.append(
                    ConfigIssue(
                        "tls_enabled",
                        "TLS must be enabled in production",
                        "error",
                    )
                )

            if not config.encryption_enabled:
                issues.append(
                    ConfigIssue(
                        "encryption_enabled",
                        "Encryption must be enabled in production",
                        "error",
                    )
                )

        if (
            config.mode
            == DeploymentMode.DEDICATED_TENANT
            and not config.tenant_id
        ):
            issues.append(
                ConfigIssue(
                    "tenant_id",
                    "Dedicated tenant deployment requires tenant_id",
                    "error",
                )
            )

        if config.mode == DeploymentMode.HYBRID:
            required = {
                "event_bus_endpoint": config.event_bus_endpoint,
                "database_endpoint": config.database_endpoint,
            }

            for name, value in required.items():
                if not value:
                    issues.append(
                        ConfigIssue(
                            name,
                            f"{name} is required for hybrid deployment",
                            "error",
                        )
                    )

        return ConfigValidationResult(
            valid=not any(
                issue.severity == "error"
                for issue in issues
            ),
            issues=issues,
        )


# ============================================================
# 4. ENVIRONMENT LOADER
# ============================================================

class EnvironmentConfigLoader:

    @staticmethod
    def _bool(
        value: Optional[str],
        default: bool,
    ) -> bool:

        if value is None:
            return default

        return value.lower() in {
            "1",
            "true",
            "yes",
            "on",
        }

    @classmethod
    def from_environment(
        cls,
    ) -> DeploymentConfig:

        mode = DeploymentMode(
            os.getenv(
                "NEXORA_DEPLOYMENT_MODE",
                DeploymentMode.SAAS.value,
            )
        )

        environment = Environment(
            os.getenv(
                "NEXORA_ENVIRONMENT",
                Environment.PRODUCTION.value,
            )
        )

        return DeploymentConfig(
            deployment_id=os.getenv(
                "NEXORA_DEPLOYMENT_ID",
                str(uuid.uuid4()),
            ),
            mode=mode,
            environment=environment,
            region=os.getenv(
                "NEXORA_REGION",
                "default",
            ),
            tenant_id=os.getenv(
                "NEXORA_TENANT_ID"
            ),
            api_host=os.getenv(
                "NEXORA_API_HOST",
                "0.0.0.0",
            ),
            api_port=int(
                os.getenv(
                    "NEXORA_API_PORT",
                    "8000",
                )
            ),
            event_bus_endpoint=os.getenv(
                "NEXORA_EVENT_BUS_ENDPOINT"
            ),
            database_endpoint=os.getenv(
                "NEXORA_DATABASE_ENDPOINT"
            ),
            redis_endpoint=os.getenv(
                "NEXORA_REDIS_ENDPOINT"
            ),
            search_endpoint=os.getenv(
                "NEXORA_SEARCH_ENDPOINT"
            ),
            object_storage_endpoint=os.getenv(
                "NEXORA_OBJECT_STORAGE_ENDPOINT"
            ),
            tls_enabled=cls._bool(
                os.getenv("NEXORA_TLS"),
                True,
            ),
            encryption_enabled=cls._bool(
                os.getenv("NEXORA_ENCRYPTION"),
                True,
            ),
            replicas=int(
                os.getenv(
                    "NEXORA_REPLICAS",
                    "1",
                )
            ),
            worker_count=int(
                os.getenv(
                    "NEXORA_WORKERS",
                    "1",
                )
            ),
            autoscaling_enabled=cls._bool(
                os.getenv("NEXORA_AUTOSCALING"),
                False,
            ),
            high_availability=cls._bool(
                os.getenv("NEXORA_HA"),
                False,
            ),
        )


# ============================================================
# 5. SERVICE REGISTRY
# ============================================================

@dataclass
class ServiceRegistration:
    service_id: str
    name: str
    host: str
    port: int

    state: ServiceState = ServiceState.STARTING

    metadata: Dict[str, Any] = field(
        default_factory=dict
    )

    registered_at: float = field(
        default_factory=time.time
    )

    last_heartbeat: float = field(
        default_factory=time.time
    )


class ServiceRegistry:

    def __init__(self):
        self._services: Dict[str, ServiceRegistration] = {}
        self._lock = threading.RLock()

    def register(
        self,
        service: ServiceRegistration,
    ) -> None:

        with self._lock:
            self._services[
                service.service_id
            ] = service

    def heartbeat(
        self,
        service_id: str,
    ) -> bool:

        with self._lock:

            service = self._services.get(
                service_id
            )

            if service is None:
                return False

            service.last_heartbeat = time.time()

            return True

    def update_state(
        self,
        service_id: str,
        state: ServiceState,
    ) -> bool:

        with self._lock:

            service = self._services.get(
                service_id
            )

            if service is None:
                return False

            service.state = state
            service.last_heartbeat = time.time()

            return True

    def unregister(
        self,
        service_id: str,
    ) -> None:

        with self._lock:
            self._services.pop(
                service_id,
                None,
            )

    def get(
        self,
        service_name: str,
    ) -> List[ServiceRegistration]:

        with self._lock:
            return [
                service
                for service in self._services.values()
                if service.name == service_name
            ]

    def all(
        self,
    ) -> List[ServiceRegistration]:

        with self._lock:
            return list(
                self._services.values()
            )

    def healthy(
        self,
        heartbeat_timeout: float = 30.0,
    ) -> List[ServiceRegistration]:

        now = time.time()

        with self._lock:
            return [
                service
                for service in self._services.values()
                if (
                    service.state
                    == ServiceState.READY
                    and
                    now - service.last_heartbeat
                    <= heartbeat_timeout
                )
            ]


# ============================================================
# 6. SERVICE DISCOVERY
# ============================================================

class ServiceDiscovery:

    def __init__(
        self,
        registry: ServiceRegistry,
    ):
        self.registry = registry

    def discover(
        self,
        service_name: str,
    ) -> List[str]:

        services = self.registry.get(
            service_name
        )

        return [
            f"{service.host}:{service.port}"
            for service in services
            if service.state
            == ServiceState.READY
        ]

    def discover_one(
        self,
        service_name: str,
    ) -> Optional[str]:

        endpoints = self.discover(
            service_name
        )

        if not endpoints:
            return None

        return endpoints[
            hash(service_name) % len(endpoints)
        ]


# ============================================================
# 7. HEALTH CHECKS
# ============================================================

@dataclass
class HealthResult:
    component: str
    healthy: bool
    latency_ms: float
    details: Dict[str, Any] = field(
        default_factory=dict
    )


class HealthCheck:

    def __init__(
        self,
        name: str,
        check: Callable[[], Any],
    ):
        self.name = name
        self.check = check

    def run(self) -> HealthResult:

        started = time.perf_counter()

        try:
            result = self.check()

            if asyncio.iscoroutine(result):
                raise RuntimeError(
                    "Async health checks must use AsyncHealthCheck"
                )

            healthy = bool(result)

            return HealthResult(
                component=self.name,
                healthy=healthy,
                latency_ms=(
                    time.perf_counter()
                    - started
                ) * 1000,
            )

        except Exception as exc:

            return HealthResult(
                component=self.name,
                healthy=False,
                latency_ms=(
                    time.perf_counter()
                    - started
                ) * 1000,
                details={
                    "error": str(exc)
                },
            )


class AsyncHealthCheck:

    def __init__(
        self,
        name: str,
        check: Callable[[], Any],
    ):
        self.name = name
        self.check = check

    async def run(self) -> HealthResult:

        started = time.perf_counter()

        try:
            result = self.check()

            if asyncio.iscoroutine(result):
                result = await result

            return HealthResult(
                component=self.name,
                healthy=bool(result),
                latency_ms=(
                    time.perf_counter()
                    - started
                ) * 1000,
            )

        except Exception as exc:

            return HealthResult(
                component=self.name,
                healthy=False,
                latency_ms=(
                    time.perf_counter()
                    - started
                ) * 1000,
                details={
                    "error": str(exc)
                },
            )


# ============================================================
# 8. READINESS MANAGER
# ============================================================

class ReadinessManager:

    def __init__(self):
        self.checks: List[HealthCheck] = []
        self._ready = False

    def add_check(
        self,
        check: HealthCheck,
    ) -> None:

        self.checks.append(check)

    def evaluate(self) -> List[HealthResult]:

        results = [
            check.run()
            for check in self.checks
        ]

        self._ready = all(
            result.healthy
            for result in results
        )

        return results

    @property
    def ready(self) -> bool:
        return self._ready


# ============================================================
# 9. RUNTIME SERVICE
# ============================================================

class RuntimeService:

    def __init__(
        self,
        name: str,
        config: DeploymentConfig,
        registry: ServiceRegistry,
    ):

        self.name = name
        self.config = config
        self.registry = registry

        self.service_id = str(
            uuid.uuid4()
        )

        self.state = ServiceState.STOPPED

        self.registration = ServiceRegistration(
            service_id=self.service_id,
            name=self.name,
            host=socket.gethostname(),
            port=self.config.api_port,
        )

    def start(self) -> None:

        if self.state not in {
            ServiceState.STOPPED,
            ServiceState.FAILED,
        }:
            return

        self.state = ServiceState.STARTING

        self.registration.state = (
            ServiceState.STARTING
        )

        self.registry.register(
            self.registration
        )

        self.state = ServiceState.READY

        self.registration.state = (
            ServiceState.READY
        )

        self.registry.update_state(
            self.service_id,
            ServiceState.READY,
        )

    def stop(self) -> None:

        if self.state == ServiceState.STOPPED:
            return

        self.state = ServiceState.STOPPING

        self.registry.update_state(
            self.service_id,
            ServiceState.STOPPING,
        )

        self.registry.unregister(
            self.service_id
        )

        self.state = ServiceState.STOPPED

    def heartbeat(self) -> None:

        if self.state == ServiceState.READY:
            self.registry.heartbeat(
                self.service_id
            )


# ============================================================
# 10. GRACEFUL SHUTDOWN
# ============================================================

class GracefulShutdown:

    def __init__(self):
        self._shutdown_requested = False
        self._callbacks: List[
            Callable[[], Any]
        ] = []

    def register(
        self,
        callback: Callable[[], Any],
    ) -> None:

        self._callbacks.append(
            callback
        )

    def request(self) -> None:

        if self._shutdown_requested:
            return

        self._shutdown_requested = True

        for callback in self._callbacks:

            try:
                result = callback()

                if asyncio.iscoroutine(result):
                    asyncio.run(result)

            except Exception:
                # Shutdown must continue even if one cleanup
                # handler fails.
                continue

    @property
    def requested(self) -> bool:
        return self._shutdown_requested

    def install_signal_handlers(self) -> None:

        def handler(
            signum: int,
            frame: Any,
        ) -> None:
            self.request()

        for sig in (
            signal.SIGTERM,
            signal.SIGINT,
        ):
            try:
                signal.signal(
                    sig,
                    handler,
                )
            except (ValueError, RuntimeError):
                pass


# ============================================================
# 11. DEPLOYMENT CAPABILITIES
# ============================================================

@dataclass(frozen=True)
class DeploymentCapabilities:

    persistent_storage: bool
    external_event_bus: bool
    external_cache: bool
    object_storage: bool
    isolated_network: bool
    autoscaling: bool
    high_availability: bool
    customer_managed_infrastructure: bool


class CapabilityResolver:

    @staticmethod
    def resolve(
        mode: DeploymentMode,
        config: DeploymentConfig,
    ) -> DeploymentCapabilities:

        if mode == DeploymentMode.SAAS:

            return DeploymentCapabilities(
                persistent_storage=True,
                external_event_bus=True,
                external_cache=True,
                object_storage=True,
                isolated_network=False,
                autoscaling=config.autoscaling_enabled,
                high_availability=config.high_availability,
                customer_managed_infrastructure=False,
            )

        if mode == DeploymentMode.DEDICATED_TENANT:

            return DeploymentCapabilities(
                persistent_storage=True,
                external_event_bus=True,
                external_cache=True,
                object_storage=True,
                isolated_network=True,
                autoscaling=config.autoscaling_enabled,
                high_availability=config.high_availability,
                customer_managed_infrastructure=False,
            )

        if mode == DeploymentMode.PRIVATE_CLOUD:

            return DeploymentCapabilities(
                persistent_storage=True,
                external_event_bus=True,
                external_cache=True,
                object_storage=True,
                isolated_network=True,
                autoscaling=config.autoscaling_enabled,
                high_availability=config.high_availability,
                customer_managed_infrastructure=True,
            )

        if mode == DeploymentMode.ON_PREM:

            return DeploymentCapabilities(
                persistent_storage=True,
                external_event_bus=True,
                external_cache=True,
                object_storage=True,
                isolated_network=True,
                autoscaling=config.autoscaling_enabled,
                high_availability=config.high_availability,
                customer_managed_infrastructure=True,
            )

        if mode == DeploymentMode.HYBRID:

            return DeploymentCapabilities(
                persistent_storage=True,
                external_event_bus=True,
                external_cache=True,
                object_storage=True,
                isolated_network=True,
                autoscaling=config.autoscaling_enabled,
                high_availability=config.high_availability,
                customer_managed_infrastructure=True,
            )

        raise ValueError(
            f"Unsupported deployment mode: {mode}"
        )


# ============================================================
# 12. DEPLOYMENT PLAN
# ============================================================

@dataclass
class DeploymentPlan:

    deployment_id: str
    mode: DeploymentMode
    environment: Environment

    services: List[str]
    replicas: int
    worker_count: int

    capabilities: DeploymentCapabilities

    networking: Dict[str, Any]
    storage: Dict[str, Any]
    scaling: Dict[str, Any]

    metadata: Dict[str, Any] = field(
        default_factory=dict
    )


class DeploymentPlanner:

    DEFAULT_SERVICES = (
        "api",
        "event-worker",
        "detection-worker",
        "investigation-worker",
        "response-worker",
    )

    @classmethod
    def create(
        cls,
        config: DeploymentConfig,
    ) -> DeploymentPlan:

        validation = DeploymentConfigValidator.validate(
            config
        )

        if not validation.valid:
            messages = [
                issue.message
                for issue in validation.issues
                if issue.severity == "error"
            ]

            raise ValueError(
                "Invalid deployment configuration: "
                + "; ".join(messages)
            )

        capabilities = CapabilityResolver.resolve(
            config.mode,
            config,
        )

        return DeploymentPlan(
            deployment_id=config.deployment_id,
            mode=config.mode,
            environment=config.environment,
            services=list(cls.DEFAULT_SERVICES),
            replicas=config.replicas,
            worker_count=config.worker_count,
            capabilities=capabilities,
            networking={
                "tls": config.tls_enabled,
                "isolated": capabilities.isolated_network,
                "api_host": config.api_host,
                "api_port": config.api_port,
            },
            storage={
                "database": config.database_endpoint,
                "object_storage": (
                    config.object_storage_endpoint
                ),
            },
            scaling={
                "replicas": config.replicas,
                "workers": config.worker_count,
                "autoscaling": config.autoscaling_enabled,
                "high_availability": config.high_availability,
            },
        )


