class DeploymentManifestBuilder:

    @staticmethod
    def build(
        plan: DeploymentPlan,
    ) -> Dict[str, Any]:

        return {
            "apiVersion": "nexora.cyber/v1",
            "kind": "CyberDeployment",
            "metadata": {
                "name": plan.deployment_id,
                "deployment_mode": plan.mode.value,
                "environment": plan.environment.value,
            },
            "spec": {
                "services": [
                    {
                        "name": service,
                        "replicas": plan.replicas,
                    }
                    for service in plan.services
                ],
                "workers": {
                    "count": plan.worker_count,
                },
                "networking": plan.networking,
                "storage": plan.storage,
                "scaling": plan.scaling,
                "capabilities": asdict(
                    plan.capabilities
                ),
            },
        }


# ============================================================
# 14. RUNTIME DEPLOYMENT CONTROLLER
# ============================================================

class DeploymentController:

    def __init__(
        self,
        config: DeploymentConfig,
    ):

        self.config = config

        self.registry = ServiceRegistry()

        self.discovery = ServiceDiscovery(
            self.registry
        )

        self.shutdown = GracefulShutdown()

        self.services: Dict[
            str,
            RuntimeService,
        ] = {}

        self.readiness = ReadinessManager()

        self.plan = DeploymentPlanner.create(
            config
        )

        self.started = False

    def add_service(
        self,
        name: str,
        port: Optional[int] = None,
    ) -> RuntimeService:

        service_config = DeploymentConfig(
            deployment_id=self.config.deployment_id,
            mode=self.config.mode,
            environment=self.config.environment,
            region=self.config.region,
            tenant_id=self.config.tenant_id,
            api_host=self.config.api_host,
            api_port=port or self.config.api_port,
            event_bus_endpoint=self.config.event_bus_endpoint,
            database_endpoint=self.config.database_endpoint,
            redis_endpoint=self.config.redis_endpoint,
            search_endpoint=self.config.search_endpoint,
            object_storage_endpoint=(
                self.config.object_storage_endpoint
            ),
            tls_enabled=self.config.tls_enabled,
            encryption_enabled=self.config.encryption_enabled,
            replicas=self.config.replicas,
            worker_count=self.config.worker_count,
            autoscaling_enabled=(
                self.config.autoscaling_enabled
            ),
            high_availability=(
                self.config.high_availability
            ),
            health_timeout_seconds=(
                self.config.health_timeout_seconds
            ),
        )

        service = RuntimeService(
            name=name,
            config=service_config,
            registry=self.registry,
        )

        self.services[name] = service

        self.shutdown.register(
            service.stop
        )

        return service

    def start(self) -> None:

        validation = DeploymentConfigValidator.validate(
            self.config
        )

        if not validation.valid:
            raise RuntimeError(
                "Deployment configuration failed validation"
            )

        for service_name in self.plan.services:

            if service_name not in self.services:
                self.add_service(
                    service_name
                )

        for service in self.services.values():
            service.start()

        self.started = True

    def stop(self) -> None:

        self.shutdown.request()

        self.started = False

    def heartbeat(self) -> None:

        for service in self.services.values():
            service.heartbeat()

    def health(self) -> Dict[str, Any]:

        services = self.registry.all()

        healthy = [
            service
            for service in services
            if service.state
            == ServiceState.READY
        ]

        return {
            "healthy": (
                len(services) == len(healthy)
                and len(services) > 0
            ),
            "services": [
                {
                    "id": service.service_id,
                    "name": service.name,
                    "state": service.state.value,
                    "endpoint": (
                        f"{service.host}:{service.port}"
                    ),
                }
                for service in services
            ],
        }

    def readiness_status(self) -> bool:

        results = self.readiness.evaluate()

        return all(
            result.healthy
            for result in results
        )


