# ============================================================
# 16. DEPLOYMENT MODE VALIDATION
# ============================================================

class DeploymentModeValidator:

    @staticmethod
    def validate_all_modes() -> Dict[str, Any]:

        results: Dict[str, Any] = {}

        for mode in DeploymentMode:

            tenant_id = (
                "test-tenant"
                if mode
                == DeploymentMode.DEDICATED_TENANT
                else None
            )

            kwargs: Dict[str, Any] = {}

            if mode == DeploymentMode.HYBRID:
                kwargs.update(
                    {
                        "event_bus_endpoint": (
                            "eventbus://test"
                        ),
                        "database_endpoint": (
                            "postgres://test"
                        ),
                    }
                )

            config = DeploymentConfig(
                deployment_id=str(
                    uuid.uuid4()
                ),
                mode=mode,
                environment=Environment.TESTING,
                tenant_id=tenant_id,
                **kwargs,
            )

            validation = (
                DeploymentConfigValidator.validate(
                    config
                )
            )

            results[mode.value] = {
                "valid": validation.valid,
                "issues": [
                    asdict(issue)
                    for issue in validation.issues
                ],
            }

        return results


# ============================================================
# 17. DEPLOYMENT SELF-TEST
# ============================================================

class DeploymentSelfTest:

    @staticmethod
    def run() -> Dict[str, Any]:

        results: Dict[str, Any] = {}

        # ----------------------------------------------------
        # SaaS
        # ----------------------------------------------------

        saas = DeploymentFactory.create(
            DeploymentMode.SAAS,
            Environment.TESTING,
        )

        saas.start()

        results["saas"] = saas.health()

        saas.stop()

        # ----------------------------------------------------
        # Dedicated Tenant
        # ----------------------------------------------------

        dedicated = DeploymentFactory.create(
            DeploymentMode.DEDICATED_TENANT,
            Environment.TESTING,
            tenant_id="tenant-test",
        )

        dedicated.start()

        results["dedicated_tenant"] = (
            dedicated.health()
        )

        dedicated.stop()

        # ----------------------------------------------------
        # Private Cloud
        # ----------------------------------------------------

        private = DeploymentFactory.create(
            DeploymentMode.PRIVATE_CLOUD,
            Environment.TESTING,
        )

        private.start()

        results["private_cloud"] = (
            private.health()
        )

        private.stop()

        # ----------------------------------------------------
        # On-Prem
        # ----------------------------------------------------

        on_prem = DeploymentFactory.create(
            DeploymentMode.ON_PREM,
            Environment.TESTING,
        )

        on_prem.start()

        results["on_prem"] = (
            on_prem.health()
        )

        on_prem.stop()

        # ----------------------------------------------------
        # Hybrid
        # ----------------------------------------------------

        hybrid = DeploymentFactory.create(
            DeploymentMode.HYBRID,
            Environment.TESTING,
            event_bus_endpoint="eventbus://test",
            database_endpoint="postgres://test",
        )

        hybrid.start()

        results["hybrid"] = (
            hybrid.health()
        )

        hybrid.stop()

        # ----------------------------------------------------
        # All-mode configuration validation
        # ----------------------------------------------------

        results["mode_validation"] = (
            DeploymentModeValidator.validate_all_modes()
        )

        return results


