def create_production_deployment_from_env() -> DeploymentController:
    """
    Reads deployment configuration from environment variables
    and returns a validated controller.

    Actual external infrastructure is intentionally not faked.
    """

    config = (
        EnvironmentConfigLoader.from_environment()
    )

    validation = (
        DeploymentConfigValidator.validate(
            config
        )
    )

    if not validation.valid:
        raise RuntimeError(
            json.dumps(
                [
                    asdict(issue)
                    for issue in validation.issues
                    if issue.severity == "error"
                ],
                indent=2,
            )
        )

    return DeploymentController(
        config
    )


