# ============================================================
# 5. FILE HASHING
# ============================================================

class IntegrityHasher:

    @staticmethod
    def sha256_file(
        path: Path,
        chunk_size: int = 1024 * 1024,
    ) -> str:

        digest = hashlib.sha256()

        with path.open("rb") as handle:

            while True:
                chunk = handle.read(chunk_size)

                if not chunk:
                    break

                digest.update(chunk)

        return digest.hexdigest()

    @staticmethod
    def sha256_bytes(
        data: bytes,
    ) -> str:

        return hashlib.sha256(data).hexdigest()

    @staticmethod
    def sha256_text(
        text: str,
    ) -> str:

        return IntegrityHasher.sha256_bytes(
            text.encode("utf-8")
        )


# ============================================================
# 6. ARTIFACT SCANNER
# ============================================================

class ArtifactScanner:

    DEFAULT_IGNORED_DIRECTORIES = {
        ".git",
        ".venv",
        "venv",
        "__pycache__",
        ".pytest_cache",
        ".mypy_cache",
        "node_modules",
        ".idea",
        ".vscode",
        "dist",
        "build",
    }

    @staticmethod
    def _safe_relative(
        root: Path,
        path: Path,
    ) -> str:

        return str(
            path.relative_to(root)
        ).replace("\\", "/")

    @classmethod
    def scan(
        cls,
        root: str | Path,
        artifact_type: ArtifactType,
        extensions: Optional[Sequence[str]] = None,
        ignored_directories: Optional[Iterable[str]] = None,
    ) -> List[ArtifactRecord]:

        root_path = Path(root).resolve()

        if not root_path.exists():
            return []

        ignored = set(
            ignored_directories
            or cls.DEFAULT_IGNORED_DIRECTORIES
        )

        normalized_extensions = None

        if extensions:
            normalized_extensions = {
                extension.lower()
                if extension.startswith(".")
                else "." + extension.lower()
                for extension in extensions
            }

        records: List[ArtifactRecord] = []

        for path in root_path.rglob("*"):

            if not path.is_file():
                continue

            if any(
                part in ignored
                for part in path.parts
            ):
                continue

            if normalized_extensions:
                if (
                    path.suffix.lower()
                    not in normalized_extensions
                ):
                    continue

            relative = cls._safe_relative(
                root_path,
                path,
            )

            try:

                stat = path.stat()

                digest = IntegrityHasher.sha256_file(
                    path
                )

                records.append(
                    ArtifactRecord(
                        artifact_id=str(uuid.uuid4()),
                        artifact_type=artifact_type,
                        path=relative,
                        status=ArtifactStatus.PRESENT,
                        size_bytes=stat.st_size,
                        sha256=digest,
                        modified_at=stat.st_mtime,
                    )
                )

            except OSError as exc:

                records.append(
                    ArtifactRecord(
                        artifact_id=str(uuid.uuid4()),
                        artifact_type=artifact_type,
                        path=relative,
                        status=ArtifactStatus.INVALID,
                        description=str(exc),
                    )
                )

        return sorted(
            records,
            key=lambda record: record.path,
        )


# ============================================================
# 7. ARTIFACT REGISTRY
# ============================================================

class ArtifactRegistry:

    def __init__(self):

        self._records: Dict[
            str,
            ArtifactRecord,
        ] = {}

    def add(
        self,
        record: ArtifactRecord,
    ) -> None:

        self._records[
            record.artifact_id
        ] = record

    def add_many(
        self,
        records: Iterable[ArtifactRecord],
    ) -> None:

        for record in records:
            self.add(record)

    def all(self) -> List[ArtifactRecord]:

        return list(
            self._records.values()
        )

    def by_type(
        self,
        artifact_type: ArtifactType,
    ) -> List[ArtifactRecord]:

        return [
            record
            for record in self._records.values()
            if record.artifact_type == artifact_type
        ]

    def paths(self) -> List[str]:

        return [
            record.path
            for record in self._records.values()
        ]


