# ============================================================
# 18. CHECKSUM MANIFEST
# ============================================================

@dataclass
class ChecksumRecord:
    path: str
    algorithm: str
    digest: str


class ChecksumManifest:

    @staticmethod
    def create(
        root: str | Path,
        records: Sequence[ArtifactRecord],
    ) -> List[ChecksumRecord]:

        root_path = Path(root).resolve()

        checksums: List[
            ChecksumRecord
        ] = []

        for record in records:

            if record.status != ArtifactStatus.PRESENT:
                continue

            path = root_path / record.path

            if not path.is_file():
                continue

            digest = IntegrityHasher.sha256_file(
                path
            )

            checksums.append(
                ChecksumRecord(
                    path=record.path,
                    algorithm=HASH_ALGORITHM,
                    digest=digest,
                )
            )

        return checksums

    @staticmethod
    def verify(
        root: str | Path,
        checksums: Sequence[ChecksumRecord],
    ) -> Dict[str, str]:

        root_path = Path(root).resolve()

        results: Dict[str, str] = {}

        for checksum in checksums:

            path = root_path / checksum.path

            if not path.is_file():

                results[
                    checksum.path
                ] = "missing"

                continue

            actual = IntegrityHasher.sha256_file(
                path
            )

            if actual == checksum.digest:
                results[
                    checksum.path
                ] = "verified"
            else:
                results[
                    checksum.path
                ] = "mismatch"

        return results


