class FinalIPPackageBuilder:

    def __init__(
        self,
        product: str = "NEXORA CYBER™",
        product_version: str = "1.0.0",
    ):

        self.product = product
        self.product_version = product_version

        self.registry = ArtifactRegistry()

        self.dependencies = DependencyInventory()

        self.licenses = LicenseInventory()

        self.ip = IPInventory()

        self.threat_model = (
            ThreatModelRegistry()
        )

        self.runbooks = RunbookRegistry()

        self.documentation = (
            DocumentationRegistry()
        )

        self.tests = TestInventory()

    def register_artifacts(
        self,
        records: Iterable[ArtifactRecord],
    ) -> None:

        self.registry.add_many(records)

    def create_manifest(
        self,
    ) -> PackageManifest:

        return PackageManifest(
            package_id=str(uuid.uuid4()),
            package_format_version=(
                PACKAGE_FORMAT_VERSION
            ),
            product=self.product,
            product_version=self.product_version,
            created_at=time.time(),
            artifacts=self.registry.all(),
            metadata={
                "generator": (
                    "NEXORA CYBER Phase 26"
                ),
                "hash_algorithm": HASH_ALGORITHM,
            },
        )

    def validate(
        self,
    ) -> PackageValidationResult:

        return (
            PackageCompletenessValidator.validate(
                self.registry
            )
        )

    def export_manifest(
        self,
        path: str | Path,
    ) -> None:

        manifest = self.create_manifest()

        Path(path).write_text(
            json.dumps(
                asdict(manifest),
                indent=2,
                default=str,
            ),
            encoding="utf-8",
        )

    def export_inventory(
        self,
        path: str | Path,
    ) -> None:

        inventory = {
            "package_manifest": asdict(
                self.create_manifest()
            ),
            "dependencies": [
                asdict(item)
                for item in self.dependencies
                .parse_requirements("")
            ],
            "licenses": [
                asdict(item)
                for item in self.licenses.records
            ],
            "ip_inventory": [
                asdict(item)
                for item in self.ip.records
            ],
            "threat_model": [
                asdict(item)
                for item in self.threat_model.records
            ],
            "runbooks": [
                asdict(item)
                for item in self.runbooks.records
            ],
            "documentation": [
                asdict(item)
                for item in self.documentation.records
            ],
            "tests": [
                asdict(item)
                for item in self.tests.records
            ],
        }

        Path(path).write_text(
            json.dumps(
                inventory,
                indent=2,
                default=str,
            ),
            encoding="utf-8",
        )


