# ============================================================

@dataclass
class HandoverSection:
    name: str
    required: bool
    artifacts: List[str]

    verified: bool = False

    notes: str = ""


@dataclass
class HandoverPackage:
    handover_id: str

    product: str
    version: str

    created_at: float

    sections: List[HandoverSection]

    integrity_status: str = "unverified"


class HandoverBuilder:

    SECTION_DEFINITIONS = (
        (
            "source_code",
            ArtifactType.SOURCE_CODE,
        ),
        (
            "architecture",
            ArtifactType.ARCHITECTURE,
        ),
        (
            "api_documentation",
            ArtifactType.API_DOCUMENTATION,
        ),
        (
            "database_schemas",
            ArtifactType.DATABASE_SCHEMA,
        ),
        (
            "connector_sdk",
            ArtifactType.CONNECTOR_SDK,
        ),
        (
            "deployment",
            ArtifactType.DEPLOYMENT,
        ),
        (
            "tests",
            ArtifactType.TESTS,
        ),
        (
            "security_tests",
            ArtifactType.SECURITY_TESTS,
        ),
        (
            "threat_model",
            ArtifactType.THREAT_MODEL,
        ),
        (
            "runbooks",
            ArtifactType.RUNBOOK,
        ),
        (
            "admin_guide",
            ArtifactType.ADMIN_GUIDE,
        ),
        (
            "developer_guide",
            ArtifactType.DEVELOPER_GUIDE,
        ),
        (
            "buyer_documentation",
            ArtifactType.BUYER_DOCUMENTATION,
        ),
    )

    @classmethod
    def build(
        cls,
        builder: FinalIPPackageBuilder,
    ) -> HandoverPackage:

        sections: List[
            HandoverSection
        ] = []

        for section_name, artifact_type in (
            cls.SECTION_DEFINITIONS
        ):

            records = builder.registry.by_type(
                artifact_type
            )

            valid_paths = [
                record.path
                for record in records
                if record.status
                == ArtifactStatus.PRESENT
            ]

            sections.append(
                HandoverSection(
                    name=section_name,
                    required=True,
                    artifacts=valid_paths,
                    verified=bool(valid_paths),
                )
            )

        overall_verified = all(
            (
                not section.required
                or section.verified
            )
            for section in sections
        )

        return HandoverPackage(
            handover_id=str(uuid.uuid4()),
            product=builder.product,
            version=builder.product_version,
            created_at=time.time(),
            sections=sections,
            integrity_status=(
                "verified"
                if overall_verified
                else "incomplete"
            ),
        )


# ============================================================
# 21. PACKAGE INTEGRITY ENGINE
# ============================================================

class PackageIntegrityEngine:

    @staticmethod
    def calculate_manifest_digest(
        manifest: PackageManifest,
    ) -> str:

        canonical = json.dumps(
            asdict(manifest),
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        )

        return IntegrityHasher.sha256_text(
            canonical
        )

    @staticmethod
    def verify_artifact_records(
        root: str | Path,
        records: Sequence[ArtifactRecord],
    ) -> Dict[str, str]:

        root_path = Path(root).resolve()

        result: Dict[str, str] = {}

        for record in records:

            path = root_path / record.path

            if not path.exists():

                result[
                    record.path
                ] = "missing"

                continue

            if not path.is_file():

                result[
                    record.path
                ] = "not_a_file"

                continue

            if not record.sha256:

                result[
                    record.path
                ] = "no_recorded_hash"

                continue

            actual = (
                IntegrityHasher.sha256_file(
                    path
                )
            )

            result[
                record.path
            ] = (
                "verified"
                if actual == record.sha256
                else "mismatch"
            )

        return result


# ============================================================
# 22. PACKAGE AUDIT
# ============================================================

@dataclass
class PackageAuditResult:
    package_valid: bool

    completeness_valid: bool

    integrity_valid: bool

    errors: List[str]
    warnings: List[str]

    artifact_count: int

    generated_at: float


class PackageAuditor:

    @staticmethod
    def audit(
        builder: FinalIPPackageBuilder,
        root: Optional[str | Path] = None,
    ) -> PackageAuditResult:

        errors: List[str] = []
        warnings: List[str] = []

        completeness = builder.validate()

        for issue in completeness.issues:

            if issue.severity == Severity.ERROR:
                errors.append(
                    issue.message
                )
            else:
                warnings.append(
                    issue.message
                )

        integrity_valid = True

        if root is not None:

            integrity = (
                PackageIntegrityEngine
                .verify_artifact_records(
                    root,
                    builder.registry.all(),
                )
            )

            for path, status in integrity.items():

                if status != "verified":

                    integrity_valid = False

                    errors.append(
                        f"{path}: {status}"
                    )

        package_valid = (
            completeness.valid
            and integrity_valid
        )

        return PackageAuditResult(
            package_valid=package_valid,
            completeness_valid=completeness.valid,
            integrity_valid=integrity_valid,
            errors=errors,
            warnings=warnings,
            artifact_count=len(
                builder.registry.all()
            ),
            generated_at=time.time(),
        )


