class Phase26SelfTest:

    @staticmethod
    def test_hashing() -> bool:

        digest = (
            IntegrityHasher.sha256_text(
                "NEXORA CYBER"
            )
        )

        return (
            isinstance(digest, str)
            and len(digest) == 64
        )

    @staticmethod
    def test_registry() -> bool:

        registry = ArtifactRegistry()

        record = ArtifactRecord(
            artifact_id="test",
            artifact_type=ArtifactType.SOURCE_CODE,
            path="src/nexora.py",
            status=ArtifactStatus.PRESENT,
        )

        registry.add(record)

        return (
            len(registry.all()) == 1
            and len(
                registry.by_type(
                    ArtifactType.SOURCE_CODE
                )
            ) == 1
        )

    @staticmethod
    def test_dependency_parser() -> bool:

        import tempfile

        with tempfile.TemporaryDirectory() as temp:

            path = (
                Path(temp)
                / "requirements.txt"
            )

            path.write_text(
                "fastapi==1.2.3\n"
                "pydantic>=2.0\n"
                "# comment\n",
                encoding="utf-8",
            )

            records = (
                DependencyInventory
                .parse_requirements(path)
            )

            return (
                len(records) == 2
                and records[0].name
                == "fastapi"
            )

    @staticmethod
    def test_sbom() -> bool:

        dependencies = [
            DependencyRecord(
                name="example",
                version="1.0.0",
            )
        ]

        sbom = SBOMBuilder.from_dependencies(
            dependencies
        )

        return (
            sbom["bomFormat"]
            == "CycloneDX"
            and len(
                sbom["components"]
            ) == 1
        )

    @staticmethod
    def test_ip_inventory() -> bool:

        inventory = IPInventory()

        record = inventory.register(
            name="Cyber Core",
            ip_type=IPType.SOURCE_CODE,
        )

        return (
            record.owner == "NEXORA"
            and len(inventory.records) == 1
        )

    @staticmethod
    def test_completeness_failure() -> bool:

        builder = FinalIPPackageBuilder()

        result = builder.validate()

        return not result.valid

    @staticmethod
    def test_handover_builder() -> bool:

        builder = FinalIPPackageBuilder()

        builder.register_artifacts(
            [
                ArtifactRecord(
                    artifact_id=str(uuid.uuid4()),
                    artifact_type=artifact_type,
                    path=f"{artifact_type.value}/placeholder",
                    status=ArtifactStatus.PRESENT,
                )
                for artifact_type
                in REQUIRED_ARTIFACT_TYPES
            ]
        )

        handover = HandoverBuilder.build(
            builder
        )

        return (
            len(handover.sections)
            == len(REQUIRED_ARTIFACT_TYPES)
            and handover.integrity_status
            == "verified"
        )

    @classmethod
    def run(cls) -> Dict[str, bool]:

        tests = {
            "hashing": cls.test_hashing(),
            "registry": cls.test_registry(),
            "dependency_parser": (
                cls.test_dependency_parser()
            ),
            "sbom": cls.test_sbom(),
            "ip_inventory": (
                cls.test_ip_inventory()
            ),
            "completeness_failure": (
                cls.test_completeness_failure()
            ),
            "handover_builder": (
                cls.test_handover_builder()
            ),
        }

        tests["all_passed"] = all(
            tests.values()
        )

        return tests


# ============================================================
# 26. SAFE PACKAGE INSPECTION
# ============================================================

class PackageInspector:

    @staticmethod
    def inspect_directory(
        root: str | Path,
    ) -> Dict[str, object]:

        root_path = Path(root).resolve()

        if not root_path.exists():
            return {
                "exists": False,
                "root": str(root_path),
                "files": [],
            }

        files = []

        for path in root_path.rglob("*"):

            if not path.is_file():
                continue

            try:
                stat = path.stat()

                files.append(
                    {
                        "path": str(
                            path.relative_to(
                                root_path
                            )
                        ).replace(
                            "\\",
                            "/",
                        ),
                        "size_bytes": stat.st_size,
                        "sha256": (
                            IntegrityHasher
                            .sha256_file(path)
                        ),
                    }
                )

            except OSError:
                continue

        return {
            "exists": True,
            "root": str(root_path),
            "file_count": len(files),
            "files": sorted(
                files,
                key=lambda item: item["path"],
            ),
        }


