class Phase26Controller:

    def __init__(
        self,
        product_version: str = "1.0.0",
    ):

        self.builder = FinalIPPackageBuilder(
            product="NEXORA CYBER™",
            product_version=product_version,
        )

    def register_existing_artifacts(
        self,
        root: str | Path,
    ) -> None:

        root_path = Path(root)

        # Source code
        self.builder.register_artifacts(
            ArtifactScanner.scan(
                root_path,
                ArtifactType.SOURCE_CODE,
                extensions=(
                    ".py",
                    ".ts",
                    ".tsx",
                    ".js",
                    ".go",
                    ".rs",
                    ".java",
                ),
            )
        )

        # Documentation / architecture
        self.builder.register_artifacts(
            ArtifactScanner.scan(
                root_path,
                ArtifactType.ARCHITECTURE,
                extensions=(
                    ".md",
                    ".yaml",
                    ".yml",
                    ".json",
                ),
            )
        )

        # Tests
        self.builder.register_artifacts(
            ArtifactScanner.scan(
                root_path,
                ArtifactType.TESTS,
                extensions=(
                    ".py",
                    ".ts",
                    ".js",
                ),
            )
        )

    def audit(
        self,
        root: Optional[str | Path] = None,
    ) -> PackageAuditResult:

        return PackageAuditor.audit(
            self.builder,
            root=root,
        )

    def create_handover(
        self,
    ) -> HandoverPackage:

        return HandoverBuilder.build(
            self.builder
        )

    def prepare_release(
        self,
    ) -> ReleaseRecord:

        return ReleaseManager.prepare(
            self.builder
        )


