# ============================================================
# 2. BOUNDARY CLASSIFICATION
# ============================================================

class BoundaryType(str, Enum):

    CYBER_OWNED = "cyber_owned"

    REFERENCE_ONLY = "reference_only"

    EXTERNAL = "external"

    FORBIDDEN = "forbidden"


class BoundaryStatus(str, Enum):

    ALLOWED = "allowed"

    BLOCKED = "blocked"

    VIOLATION = "violation"

    UNKNOWN = "unknown"


# ============================================================
# 3. REFERENCE FOUNDATION RECORD
# ============================================================

@dataclass(frozen=True)
class FoundationReference:

    reference_id: str

    name: str

    category: str

    role: str = FOUNDATION_ROLE

    allowed_usage: Tuple[str, ...] = ()

    forbidden_usage: Tuple[str, ...] = ()

    source_hash: Optional[str] = None

    metadata: Mapping[str, Any] = field(
        default_factory=dict
    )


class FoundationReferenceRegistry:

    def __init__(self):

        self._references: Dict[
            str,
            FoundationReference,
        ] = {}

    def register(
        self,
        name: str,
        category: str,
        allowed_usage: Sequence[str] = (),
        forbidden_usage: Sequence[str] = (),
        source_hash: Optional[str] = None,
        metadata: Optional[
            Mapping[str, Any]
        ] = None,
    ) -> FoundationReference:

        reference = FoundationReference(
            reference_id=str(uuid.uuid4()),
            name=name,
            category=category,
            allowed_usage=tuple(
                allowed_usage
            ),
            forbidden_usage=tuple(
                forbidden_usage
            ),
            source_hash=source_hash,
            metadata=dict(
                metadata or {}
            ),
        )

        self._references[
            reference.reference_id
        ] = reference

        return reference

    def all(
        self,
    ) -> List[FoundationReference]:

        return list(
            self._references.values()
        )

    def find(
        self,
        name: str,
    ) -> Optional[FoundationReference]:

        for reference in self._references.values():

            if reference.name == name:
                return reference

        return None


