# ============================================================
# 6. IMPORT REPRESENTATION
# ============================================================

@dataclass
class ImportReference:

    module: str

    source_file: str

    line_number: int

    imported_name: Optional[str] = None


# ============================================================
# 7. PYTHON IMPORT SCANNER
# ============================================================

class PythonImportScanner:

    @staticmethod
    def scan_file(
        path: str | Path,
    ) -> List[ImportReference]:

        path = Path(path)

        if not path.is_file():
            return []

        try:

            source = path.read_text(
                encoding="utf-8"
            )

            tree = ast.parse(
                source,
                filename=str(path),
            )

        except (
            OSError,
            UnicodeDecodeError,
            SyntaxError,
        ):

            return []

        imports: List[
            ImportReference
        ] = []

        for node in ast.walk(tree):

            if isinstance(
                node,
                ast.Import,
            ):

                for alias in node.names:

                    imports.append(
                        ImportReference(
                            module=alias.name,
                            source_file=str(path),
                            line_number=node.lineno,
                            imported_name=(
                                alias.asname
                            ),
                        )
                    )

            elif isinstance(
                node,
                ast.ImportFrom,
            ):

                module = (
                    node.module
                    or ""
                )

                for alias in node.names:

                    imports.append(
                        ImportReference(
                            module=module,
                            source_file=str(path),
                            line_number=node.lineno,
                            imported_name=alias.name,
                        )
                    )

        return imports

    @classmethod
    def scan_directory(
        cls,
        root: str | Path,
    ) -> List[ImportReference]:

        root = Path(root)

        results: List[
            ImportReference
        ] = []

        if not root.exists():
            return results

        for path in root.rglob("*.py"):

            results.extend(
                cls.scan_file(path)
            )

        return results


# ============================================================
# 8. DEPENDENCY CLASSIFIER
# ============================================================

class DependencyClassifier:

    def __init__(
        self,
        forbidden_prefixes: Sequence[str] =
        DEFAULT_FORBIDDEN_PREFIXES,
        forbidden_terms: Sequence[str] =
        DEFAULT_FORBIDDEN_TERMS,
    ):

        self.forbidden_prefixes = tuple(
            forbidden_prefixes
        )

        self.forbidden_terms = tuple(
            forbidden_terms
        )

    def classify(
        self,
        module: str,
    ) -> BoundaryType:

        normalized = (
            module.strip()
            .lower()
        )

        if not normalized:
            return BoundaryType.UNKNOWN

        for prefix in self.forbidden_prefixes:

            if (
                normalized == prefix
                or normalized.startswith(
                    prefix + "."
                )
            ):

                return BoundaryType.FORBIDDEN

        for term in self.forbidden_terms:

            if term in normalized:

                return BoundaryType.FORBIDDEN

        if (
            normalized.startswith(
                CYBER_NAMESPACE + "."
            )
            or normalized
            == CYBER_NAMESPACE
        ):

            return BoundaryType.CYBER_OWNED

        if (
            normalized.startswith(
                "reference."
            )
            or normalized.startswith(
                "foundation."
            )
        ):

            return BoundaryType.REFERENCE_ONLY

        return BoundaryType.EXTERNAL


# ============================================================
# 9. BOUNDARY VIOLATION
# ============================================================

@dataclass
class BoundaryViolation:

    violation_id: str

    source_file: str

    module: str

    line_number: int

    boundary_type: BoundaryType

    reason: str

    severity: str = "critical"


# ============================================================
# 10. BOUNDARY VALIDATOR
# ============================================================

class BoundaryValidator:

    def __init__(
        self,
        classifier: Optional[
            DependencyClassifier
        ] = None,
    ):

        self.classifier = (
            classifier
            or DependencyClassifier()
        )

    def validate_imports(
        self,
        imports: Sequence[
            ImportReference
        ],
    ) -> List[BoundaryViolation]:

        violations: List[
            BoundaryViolation
        ] = []

        for reference in imports:

            classification = (
                self.classifier.classify(
                    reference.module
                )
            )

            if (
                classification
                == BoundaryType.FORBIDDEN
            ):

                violations.append(
                    BoundaryViolation(
                        violation_id=str(
                            uuid.uuid4()
                        ),
                        source_file=(
                            reference.source_file
                        ),
                        module=reference.module,
                        line_number=(
                            reference.line_number
                        ),
                        boundary_type=(
                            classification
                        ),
                        reason=(
                            "Forbidden Business "
                            "OS dependency detected."
                        ),
                    )
                )

        return violations


# ============================================================
# 11. SOURCE CONTAMINATION SCANNER
# ============================================================

@dataclass
class ContaminationFinding:

    finding_id: str

    source_file: str

    line_number: int

    matched_term: str

    reason: str

    severity: str = "high"


class BusinessContaminationScanner:

    def __init__(
        self,
        forbidden_terms: Sequence[str] =
        DEFAULT_FORBIDDEN_TERMS,
    ):

        self.forbidden_terms = tuple(
            forbidden_terms
        )

    def scan_text(
        self,
        text: str,
        source_file: str = "<memory>",
    ) -> List[ContaminationFinding]:

        findings: List[
            ContaminationFinding
        ] = []

        lines = text.splitlines()

        for line_number, line in enumerate(
            lines,
            start=1,
        ):

            normalized = line.lower()

            for term in self.forbidden_terms:

                if term.lower() in normalized:

                    findings.append(
                        ContaminationFinding(
                            finding_id=str(
                                uuid.uuid4()
                            ),
                            source_file=source_file,
                            line_number=line_number,
                            matched_term=term,
                            reason=(
                                "Business-specific "
                                "implementation reference "
                                "detected."
                            ),
                        )
                    )

        return findings

    def scan_file(
        self,
        path: str | Path,
    ) -> List[ContaminationFinding]:

        path = Path(path)

        if not path.is_file():
            return []

        try:

            text = path.read_text(
                encoding="utf-8"
            )

        except (
            OSError,
            UnicodeDecodeError,
        ):

            return []

        return self.scan_text(
            text,
            str(path),
        )


# ============================================================
# 12. CYBER MODULE OWNERSHIP
# ============================================================

@dataclass
class OwnershipResult:

    valid: bool

    module: str

    expected_namespace: str

    actual_namespace: Optional[str]

    reason: str


class ModuleOwnershipValidator:

    @staticmethod
    def validate(
        module_name: str,
    ) -> OwnershipResult:

        if module_name == CYBER_NAMESPACE:
            return OwnershipResult(
                valid=True,
                module=module_name,
                expected_namespace=CYBER_NAMESPACE,
                actual_namespace=module_name,
                reason="Cyber root namespace.",
            )

        if module_name.startswith(
            CYBER_NAMESPACE + "."
        ):

            return OwnershipResult(
                valid=True,
                module=module_name,
                expected_namespace=CYBER_NAMESPACE,
                actual_namespace=module_name,
                reason="Cyber-owned namespace.",
            )

        return OwnershipResult(
            valid=False,
            module=module_name,
            expected_namespace=CYBER_NAMESPACE,
            actual_namespace=module_name,
            reason=(
                "Module does not belong to "
                "the Cyber namespace."
            ),
        )


