    """
    Explicit boundary for consuming patterns from
    extracted foundation material.

    The adapter does not import Business OS code.
    """

    adapter_name = "base_reference_adapter"

    def transform(
        self,
        payload: Mapping[str, Any],
    ) -> Mapping[str, Any]:

        raise NotImplementedError


