# ============================================================
# 14. REFERENCE ADAPTER REGISTRY
# ============================================================

class ReferenceAdapterRegistry:

    def __init__(self):

        self._adapters: Dict[
            str,
            ReferenceAdapter,
        ] = {}

    def register(
        self,
        adapter: ReferenceAdapter,
    ) -> None:

        if not isinstance(
            adapter,
            ReferenceAdapter,
        ):

            raise TypeError(
                "Adapter must implement ReferenceAdapter."
            )

        self._adapters[
            adapter.adapter_name
        ] = adapter

    def get(
        self,
        name: str,
    ) -> Optional[ReferenceAdapter]:

        return self._adapters.get(name)

    def all(
        self,
    ) -> List[ReferenceAdapter]:

        return list(
            self._adapters.values()
        )

    def transform(
        self,
        adapter_name: str,
        payload: Mapping[str, Any],
    ) -> Mapping[str, Any]:

        adapter = self.get(
            adapter_name
        )

        if adapter is None:

            raise KeyError(
                f"Unknown reference adapter: "
                f"{adapter_name}"
            )

        return adapter.transform(
            payload
        )


# ============================================================
# 15. REFERENCE TRUST BOUNDARY
# ============================================================

class ReferenceTrustBoundary:

    """
    External/extracted material is always untrusted.

    This boundary intentionally does not execute arbitrary
    callable objects supplied by reference data.
    """

    @staticmethod
    def sanitize_mapping(
        payload: Mapping[str, Any],
    ) -> Dict[str, Any]:

        sanitized: Dict[
            str,
            Any,
        ] = {}

        for key, value in payload.items():

            if not isinstance(
                key,
                str,
            ):

                continue

            if callable(value):

                continue

            if isinstance(
                value,
                Mapping,
            ):

                sanitized[key] = (
                    ReferenceTrustBoundary
                    .sanitize_mapping(value)
                )

            elif isinstance(
                value,
                (
                    str,
                    int,
                    float,
                    bool,
                ),
            ) or value is None:

                sanitized[key] = value

            elif isinstance(
                value,
                (list, tuple),
            ):

                sanitized[key] = [
                    item
                    for item in value
                    if not callable(item)
                ]

        return sanitized


# ============================================================
# 16. FOUNDATION HASHING
# ============================================================

class FoundationHasher:

    @staticmethod
    def hash_file(
        path: str | Path,
    ) -> str:

        path = Path(path)

        digest = hashlib.sha256()

        with path.open("rb") as handle:

            while True:

                chunk = handle.read(
                    1024 * 1024
                )

                if not chunk:
                    break

                digest.update(chunk)

        return digest.hexdigest()


# ============================================================
# 17. ARCHITECTURE RULE
# ============================================================

@dataclass(frozen=True)
class ArchitectureRule:

    rule_id: str

    name: str

    description: str

    severity: str = "critical"


class ArchitectureRuleSet:

    def __init__(self):

        self.rules: List[
            ArchitectureRule
        ] = []

        self._load_defaults()

    def _load_defaults(
        self,
    ) -> None:

        self.rules.extend(
            [
                ArchitectureRule(
                    rule_id="R27-001",
                    name=(
                        "no_business_runtime_dependency"
                    ),
                    description=(
                        "Cyber modules must not depend "
                        "on Business OS runtime."
                    ),
                ),
                ArchitectureRule(
                    rule_id="R27-002",
                    name=(
                        "no_business_ontology_dependency"
                    ),
                    description=(
                        "Cyber modules must not depend "
                        "on Business ontology."
                    ),
                ),
                ArchitectureRule(
                    rule_id="R27-003",
                    name=(
                        "reference_material_isolated"
                    ),
                    description=(
                        "Extracted foundation material "
                        "must remain reference-only."
                    ),
                ),
                ArchitectureRule(
                    rule_id="R27-004",
                    name=(
                        "cyber_namespace_ownership"
                    ),
                    description=(
                        "Cyber-owned implementation must "
                        "remain under Cyber namespace."
                    ),
                ),
                ArchitectureRule(
                    rule_id="R27-005",
                    name=(
                        "no_silent_execution"
                    ),
                    description=(
                        "Reference material must not "
                        "execute arbitrary code."
                    ),
                ),
            ]
        )


# ============================================================
# 18. ARCHITECTURE CONFORMANCE RESULT
# ============================================================

@dataclass
class ArchitectureConformanceResult:

    valid: bool

    rules_checked: int

    violations: List[
        BoundaryViolation
    ]

    checked_at: float


class ArchitectureConformanceEngine:

    def __init__(
        self,
        validator: Optional[
            BoundaryValidator
        ] = None,
    ):

        self.validator = (
            validator
            or BoundaryValidator()
        )

        self.rules = (
            ArchitectureRuleSet()
        )

    def validate_imports(
        self,
        imports: Sequence[
            ImportReference
        ],
    ) -> ArchitectureConformanceResult:

        violations = (
            self.validator
            .validate_imports(imports)
        )

        return ArchitectureConformanceResult(
            valid=not violations,
            rules_checked=len(
                self.rules.rules
            ),
            violations=violations,
            checked_at=time.time(),
        )


# ============================================================
# 19. RUNTIME DEPENDENCY INSPECTOR
# ============================================================

@dataclass
class RuntimeDependencyResult:

    module: str

    loaded: bool

    forbidden_loaded: bool

    forbidden_modules: List[str]

    valid: bool


class RuntimeDependencyInspector:

    @staticmethod
    def inspect(
        loaded_modules: Optional[
            Iterable[str]
        ] = None,
    ) -> RuntimeDependencyResult:

        modules = set(
            loaded_modules
            if loaded_modules is not None
            else sys.modules.keys()
        )

        forbidden = []

        classifier = (
            DependencyClassifier()
        )

        for module in modules:

            if (
                classifier.classify(module)
                == BoundaryType.FORBIDDEN
            ):

                forbidden.append(module)

        return RuntimeDependencyResult(
            module=CYBER_NAMESPACE,
            loaded=(
                CYBER_NAMESPACE
                in modules
            ),
            forbidden_loaded=bool(
                forbidden
            ),
            forbidden_modules=sorted(
                forbidden
            ),
            valid=not forbidden,
        )


# ============================================================
# 20. CYBER ENVIRONMENT GUARD
# ============================================================

class CyberEnvironmentGuard:

    @staticmethod
    def assert_no_business_runtime(
        loaded_modules: Optional[
            Iterable[str]
        ] = None,
    ) -> None:

        result = (
            RuntimeDependencyInspector
            .inspect(loaded_modules)
        )

        if result.forbidden_loaded:

            raise RuntimeError(
                "Cyber runtime boundary violation: "
                + ", ".join(
                    result.forbidden_modules
                )
            )

    @staticmethod
    def is_clean(
        loaded_modules: Optional[
            Iterable[str]
        ] = None,
    ) -> bool:

        return (
            RuntimeDependencyInspector
            .inspect(
                loaded_modules
            )
            .valid
        )


# ============================================================
# 21. COMPONENT BOUNDARY RECORD
# ============================================================

@dataclass
class ComponentBoundary:

    component: str

    namespace: str

    ownership: BoundaryType

    business_dependency_allowed: bool

    reference_dependency_allowed: bool

    external_dependency_allowed: bool


class CyberComponentBoundaryRegistry:

    def __init__(self):

        self.components: Dict[
            str,
            ComponentBoundary,
        ] = {}

    def register(
        self,
        component: str,
        reference_dependency_allowed: bool = True,
        external_dependency_allowed: bool = True,
    ) -> ComponentBoundary:

        boundary = ComponentBoundary(
            component=component,
            namespace=CYBER_NAMESPACE,
            ownership=BoundaryType.CYBER_OWNED,
            business_dependency_allowed=False,
            reference_dependency_allowed=(
                reference_dependency_allowed
            ),
            external_dependency_allowed=(
                external_dependency_allowed
            ),
        )

        self.components[
            component
        ] = boundary

        return boundary


# ============================================================
# 22. PHASE 27 BOUNDARY AUDIT
# ============================================================

@dataclass
class BoundaryAuditReport:

    audit_id: str

    phase: int

    product: str

    passed: bool

    import_violations: List[
        BoundaryViolation
    ]

    contamination_findings: List[
        ContaminationFinding
    ]

    runtime_result: RuntimeDependencyResult

    ownership_results: List[
        OwnershipResult
    ]

    checked_files: int

    checked_imports: int

    generated_at: float


class Phase27BoundaryAuditor:

    def __init__(self):

        self.import_scanner = (
            PythonImportScanner()
        )

        self.boundary_validator = (
            BoundaryValidator()
        )

        self.contamination_scanner = (
            BusinessContaminationScanner()
        )

    def audit_directory(
        self,
        root: str | Path,
    ) -> BoundaryAuditReport:

        root = Path(root)

        imports = (
            self.import_scanner
            .scan_directory(root)
        )

        import_violations = (
            self.boundary_validator
            .validate_imports(imports)
        )

        contamination_findings: List[
            ContaminationFinding
        ] = []

        checked_files = 0

        ownership_results: List[
            OwnershipResult
        ] = []

        for path in root.rglob("*.py"):

            checked_files += 1

            contamination_findings.extend(
                self.contamination_scanner
                .scan_file(path)
            )

            module = (
                self._path_to_module(
                    root,
                    path,
                )
            )

            ownership_results.append(
                ModuleOwnershipValidator
                .validate(module)
            )

        runtime_result = (
            RuntimeDependencyInspector
            .inspect()
        )

        passed = (
            not import_violations
            and not contamination_findings
            and runtime_result.valid
            and all(
                result.valid
                for result
                in ownership_results
                if result.module.startswith(
                    CYBER_NAMESPACE
                )
            )
        )

        return BoundaryAuditReport(
            audit_id=str(uuid.uuid4()),
            phase=PHASE,
            product=PRODUCT_NAME,
            passed=passed,
            import_violations=(
                import_violations
            ),
            contamination_findings=(
                contamination_findings
            ),
            runtime_result=runtime_result,
            ownership_results=(
                ownership_results
            ),
            checked_files=checked_files,
            checked_imports=len(imports),
            generated_at=time.time(),
        )

    @staticmethod
    def _path_to_module(
        root: Path,
        path: Path,
    ) -> str:

        try:

            relative = path.relative_to(
                root
            )

        except ValueError:

            return path.stem

        parts = list(
            relative.with_suffix("")
            .parts
        )

        if parts and parts[-1] == "__init__":
            parts = parts[:-1]

        if not parts:
            return path.stem

        return ".".join(parts)


# ============================================================
# 23. SAFE REFERENCE CONSUMPTION
# ============================================================

class SafeReferenceConsumer:

    def __init__(
        self,
        registry: Optional[
            ReferenceAdapterRegistry
        ] = None,
    ):

        self.registry = (
            registry
            or ReferenceAdapterRegistry()
        )

    def consume(
        self,
        adapter_name: str,
        payload: Mapping[str, Any],
    ) -> Mapping[str, Any]:

        sanitized = (
            ReferenceTrustBoundary
            .sanitize_mapping(
                payload
            )
        )

        result = self.registry.transform(
            adapter_name,
            sanitized,
        )

        return {
            "phase": PHASE,
            "product": PRODUCT_NAME,
            "reference_only": True,
            "trusted": False,
            "result": result,
        }


