class Phase27SelfTest:

    @staticmethod
    def test_reference_registry() -> bool:

        registry = (
            build_default_reference_registry()
        )

        references = registry.all()

        return (
            len(references) >= 9
            and all(
                reference.role
                == FOUNDATION_ROLE
                for reference
                in references
            )
        )

    @staticmethod
    def test_adapter_registry() -> bool:

        registry = (
            build_default_adapter_registry()
        )

        return (
            len(registry.all()) >= 8
        )

    @staticmethod
    def test_reference_is_untrusted() -> bool:

        consumer = SafeReferenceConsumer(
            build_default_adapter_registry()
        )

        result = consumer.consume(
            "event_architecture_reference",
            {
                "event": "login",
                "severity": "high",
                "callable": lambda: "must not execute",
            },
        )

        return (
            result["trusted"] is False
            and result["reference_only"] is True
            and "callable"
            not in result["result"]["payload"]
        )

    @staticmethod
    def test_forbidden_import_detection() -> bool:

        imports = [
            ImportReference(
                module="nexora_business.runtime",
                source_file="test.py",
                line_number=10,
            )
        ]

        violations = (
            BoundaryValidator()
            .validate_imports(imports)
        )

        return len(violations) == 1

    @staticmethod
    def test_allowed_cyber_import() -> bool:

        imports = [
            ImportReference(
                module="nexora_cyber.core",
                source_file="test.py",
                line_number=10,
            )
        ]

        violations = (
            BoundaryValidator()
            .validate_imports(imports)
        )

        return len(violations) == 0

    @staticmethod
    def test_external_import() -> bool:

        imports = [
            ImportReference(
                module="json",
                source_file="test.py",
                line_number=1,
            )
        ]

        violations = (
            BoundaryValidator()
            .validate_imports(imports)
        )

        return len(violations) == 0

    @staticmethod
    def test_business_contamination_detection() -> bool:

        scanner = (
            BusinessContaminationScanner()
        )

        findings = scanner.scan_text(
            """
            from nexora_business.runtime import X
            business_ontology.load()
            """,
            source_file="test.py",
        )

        return len(findings) >= 2

    @staticmethod
    def test_clean_source() -> bool:

        scanner = (
            BusinessContaminationScanner()
        )

        findings = scanner.scan_text(
            """
            from nexora_cyber.core import CyberEvent
            import json
            """,
            source_file="clean.py",
        )

        return len(findings) == 0

    @staticmethod
    def test_ownership() -> bool:

        valid = (
            ModuleOwnershipValidator
            .validate(
                "nexora_cyber.core"
            )
        )

        invalid = (
            ModuleOwnershipValidator
            .validate(
                "nexora_business.runtime"
            )
        )

        return (
            valid.valid
            and not invalid.valid
        )

    @staticmethod
    def test_runtime_guard() -> bool:

        clean_modules = {
            "sys",
            "json",
            "nexora_cyber",
        }

        dirty_modules = {
            "sys",
            "nexora_cyber",
            "nexora_business.runtime",
        }

        clean = (
            CyberEnvironmentGuard
            .is_clean(
                clean_modules
            )
        )

        dirty = (
            CyberEnvironmentGuard
            .is_clean(
                dirty_modules
            )
        )

        return (
            clean is True
            and dirty is False
        )

    @staticmethod
    def test_runtime_guard_raises() -> bool:

        try:

            CyberEnvironmentGuard.assert_no_business_runtime(
                {
                    "nexora_cyber",
                    "nexora_business.runtime",
                }
            )

        except RuntimeError:

            return True

        return False

    @staticmethod
    def test_component_boundaries() -> bool:

        registry = (
            build_default_boundary_registry()
        )

        return (
            len(
                registry.components
            ) >= 20
            and all(
                not boundary
                .business_dependency_allowed
                for boundary
                in registry.components.values()
            )
        )

    @staticmethod
    def test_architecture_rules() -> bool:

        rules = ArchitectureRuleSet()

        names = {
            rule.name
            for rule in rules.rules
        }

        required = {
            "no_business_runtime_dependency",
            "no_business_ontology_dependency",
            "reference_material_isolated",
            "cyber_namespace_ownership",
            "no_silent_execution",
        }

        return required.issubset(names)

    @staticmethod
    def test_controller() -> bool:

        controller = Phase27Controller()

        summary = (
            controller.reference_summary()
        )

        boundaries = (
            controller.boundary_summary()
        )

        return (
            summary["reference_count"]
            >= 9
            and boundaries[
                "business_dependency_allowed"
            ]
            is False
        )

    @staticmethod
    def test_reference_adapters() -> bool:

        controller = Phase27Controller()

        adapter_names = (
            [
                adapter.adapter_name
                for adapter
                in controller
                .adapter_registry
                .all()
            ]
        )

        for adapter_name in adapter_names:

            result = (
                controller.consume_reference(
                    adapter_name,
                    {
                        "source": "foundation",
                        "data": "test",
                    },
                )
            )

            if result["trusted"]:
                return False

        return True

    @classmethod
    def run(cls) -> Dict[str, bool]:

        results = {
            "reference_registry":
                cls.test_reference_registry(),

            "adapter_registry":
                cls.test_adapter_registry(),

            "reference_untrusted":
                cls.test_reference_is_untrusted(),

            "forbidden_import_detection":
                cls.test_forbidden_import_detection(),

            "allowed_cyber_import":
                cls.test_allowed_cyber_import(),

            "external_import":
                cls.test_external_import(),

            "business_contamination_detection":
                cls.test_business_contamination_detection(),

            "clean_source":
                cls.test_clean_source(),

            "module_ownership":
                cls.test_ownership(),

            "runtime_guard":
                cls.test_runtime_guard(),

            "runtime_guard_raises":
                cls.test_runtime_guard_raises(),

            "component_boundaries":
                cls.test_component_boundaries(),

            "architecture_rules":
                cls.test_architecture_rules(),

            "controller":
                cls.test_controller(),

            "reference_adapters":
                cls.test_reference_adapters(),
        }

        results["all_passed"] = all(
            results.values()
        )

        return results


