class HydraError(Exception):
    """
    Base class for expected HYDRA application errors.

    Every expected application error has:
        - human-readable message
        - stable machine-readable code
        - optional structured details

    The details mapping must never contain raw secrets.
    """

    default_code: ClassVar[str] = "HYDRA_ERROR"

    def __init__(
        self,
        message: str,
        *,
        code: str | None = None,
        details: Mapping[str, Any] | None = None,
    ) -> None:
        if not isinstance(message, str):
            raise TypeError("HydraError message must be a string.")

        self.message = message
        self.code = code or self.default_code
        self.details = dict(details or {})

        super().__init__(message)

    def __str__(self) -> str:
        return self.message

    def to_dict(self) -> dict[str, Any]:
        """
        Return a serialization-safe representation of the error.
        """
        return {
            "error": self.code,
            "message": self.message,
            "details": to_primitive(self.details),
        }


class ConfigurationError(HydraError):
    """Invalid or unsafe application configuration."""

    default_code = "CONFIGURATION_ERROR"






class NotFoundError(HydraError):
    """Requested resource does not exist."""

    default_code = "NOT_FOUND"


class ConflictError(HydraError):
    """Requested operation conflicts with current state."""

    default_code = "CONFLICT"


class StateTransitionError(HydraError):
    """Invalid state transition."""

    default_code = "INVALID_STATE_TRANSITION"


class DependencyError(HydraError):
    """Required runtime dependency is unavailable."""

    default_code = "DEPENDENCY_ERROR"


class SerializationError(HydraError):
    """Object cannot be safely serialized."""

    default_code = "SERIALIZATION_ERROR"


