class HydraSettings(BaseSettings):
    """
    Central validated HYDRA configuration.

    Environment variables use:

        HYDRA_<FIELD>

    Examples:

        HYDRA_ENVIRONMENT=production
        HYDRA_LOG_LEVEL=INFO
        HYDRA_APPLICATION_SECRET=<secret>

    Secrets are represented by Pydantic SecretStr and are never returned
    directly by public diagnostics.
    """

    model_config = SettingsConfigDict(
        env_prefix="HYDRA_",
        env_file=".env",
        env_file_encoding="utf-8",
        case_sensitive=False,
        extra="ignore",
        validate_assignment=True,
    )

    app_name: str = Field(
        default=HYDRA_NAME,
        min_length=1,
        max_length=MAX_APP_NAME_LENGTH,
    )

    environment: Environment = Environment.DEVELOPMENT

    debug: bool = False

    log_level: str = Field(
        default="INFO",
        min_length=1,
        max_length=MAX_LOG_LEVEL_LENGTH,
    )

    database_url: str = Field(
        default=DEFAULT_DATABASE_URL,
        min_length=1,
        max_length=MAX_DATABASE_URL_LENGTH,
    )

    application_secret: SecretStr | None = None

    @field_validator("app_name")
    @classmethod
    def validate_app_name(cls, value: str) -> str:
        """
        Normalize and validate application name.
        """
        normalized = value.strip()

        if not normalized:
            raise ValueError("Application name cannot be empty.")

        return normalized

    @field_validator("log_level")
    @classmethod
    def validate_log_level(cls, value: str) -> str:
        """
        Normalize logging level and ensure it is supported.
        """
        normalized = value.strip().upper()

        if normalized not in ALLOWED_LOG_LEVELS:
            raise ValueError(
                f"Unsupported log level '{value}'. "
                f"Allowed levels: {sorted(ALLOWED_LOG_LEVELS)}."
            )

        return normalized

    @field_validator("database_url")
    @classmethod
    def validate_database_url(cls, value: str) -> str:
        """
        Perform foundational database URL validation.

        Phase 0 does not create database connections.
        """
        normalized = value.strip()

        if not normalized:
            raise ValueError("Database URL cannot be empty.")

        if "\x00" in normalized:
            raise ValueError("Database URL contains an invalid null byte.")

        return normalized

    @field_validator("application_secret")
    @classmethod
    def validate_application_secret(
        cls,
        value: SecretStr | None,
    ) -> SecretStr | None:
        """
        Validate configured secret length.

        A secret shorter than the minimum is rejected rather than silently
        accepting weak application credentials.
        """
        if value is None:
            return None

        raw = value.get_secret_value()

        if len(raw) < MIN_APPLICATION_SECRET_LENGTH:
            raise ValueError(
                "Application secret must contain at least "
                f"{MIN_APPLICATION_SECRET_LENGTH} characters."
            )

        return value

    @model_validator(mode="after")
    def validate_runtime_security(self) -> "HydraSettings":
        """
        Apply environment-sensitive safety rules.
        """
        if self.environment == Environment.PRODUCTION:
            if self.debug:
                raise ConfigurationError(
                    "Debug mode must be disabled in production."
                )

            if self.application_secret is None:
                raise ConfigurationError(
                    "HYDRA_APPLICATION_SECRET is required in production."
                )

        return self

    @property
    def is_production(self) -> bool:
        """Whether this is a production configuration."""
        return self.environment == Environment.PRODUCTION

    @property
    def is_testing(self) -> bool:
        """Whether this is a testing configuration."""
        return self.environment == Environment.TESTING

    @property
    def is_development(self) -> bool:
        """Whether this is a development configuration."""
        return self.environment == Environment.DEVELOPMENT

    def public_dict(self) -> dict[str, Any]:
        """
        Return configuration suitable for diagnostics.

        Raw secrets are never exposed.
        """
        result = self.model_dump()

        if self.application_secret is not None:
            result["application_secret"] = "***CONFIGURED***"
        else:
            result["application_secret"] = None

        return result


@lru_cache(maxsize=1)
def get_settings() -> HydraSettings:
    """
    Return the process-level validated configuration.

    Configuration is intentionally cached so all components within one
    process observe the same validated configuration.
    """
    return HydraSettings()


def reset_settings() -> None:
    """
    Reset cached settings.

    Primarily useful for controlled testing and process reinitialization.
    """
    get_settings.cache_clear()


# ============================================================================
# IDENTIFIER PRIMITIVES
# ============================================================================


def generate_id() -> UUID:
    """
    Generate a UUID4 identifier.
    """
    return uuid.uuid4()


def parse_id(value: UUID | str) -> UUID:
    """
    Parse a UUID from either a UUID instance or string.

    Empty strings and invalid UUID values are rejected.
    """
    if isinstance(value, UUID):
        return value

    if not isinstance(value, str):
        raise ValidationError(
            "Identifier must be a UUID or UUID string.",
            details={
                "received_type": type(value).__name__,
            },
        )

    normalized = value.strip()

    if not normalized:
        raise ValidationError("Identifier cannot be empty.")

    try:
        return UUID(normalized)
    except ValueError as exc:
        raise ValidationError(
            "Identifier is not a valid UUID.",
            details={"value": normalized},
        ) from exc


def id_to_string(value: UUID | str) -> str:
    """
    Convert an identifier to canonical UUID string form.
    """
    return str(parse_id(value))


