def to_iso8601(value: datetime) -> str:
    """
    Convert timezone-aware datetime to canonical UTC ISO-8601.

    Example:

        2026-09-06T12:00:00.000000Z
    """
    normalized = ensure_utc(value)

    result = normalized.isoformat(timespec="microseconds")

    if result.endswith("+00:00"):
        result = f"{result[:-6]}Z"

    return result


def from_iso8601(value: str) -> datetime:
    """
    Parse ISO-8601 datetime and normalize it to UTC.

    A timezone is mandatory.
    """
    if not isinstance(value, str):
        raise ValidationError(
            "ISO-8601 datetime must be a string.",
            details={
                "received_type": type(value).__name__,
            },
        )

    normalized = value.strip()

    if not normalized:
        raise ValidationError("ISO-8601 datetime cannot be empty.")

    if normalized.endswith(("Z", "z")):
        normalized = normalized[:-1] + "+00:00"

    try:
        parsed = datetime.fromisoformat(normalized)
    except ValueError as exc:
        raise ValidationError(
            "Invalid ISO-8601 datetime.",
            details={"value": value},
        ) from exc

    return ensure_utc(parsed)


# ============================================================================
# SERIALIZATION
# ============================================================================


def _serialize_mapping_key(key: Any) -> str:
    """
    Convert a mapping key into a deterministic string.

    JSON object keys are strings, so this boundary is explicit.
    """
    if isinstance(key, str):
        return key

    if isinstance(key, UUID):
        return str(key)

    if isinstance(key, Enum):
        return str(_serialize_mapping_key(key.value))

    if isinstance(key, (int, float, bool)):
        return str(key)

    raise SerializationError(
        "Unsupported mapping key type.",
        details={
            "key_type": type(key).__name__,
        },
    )


def to_primitive(value: Any) -> Any:
    """
    Convert supported Python values to JSON-compatible primitives.

    Supported:
        None
        bool
        int
        float
        str
        UUID
        datetime
        date
        Enum
        dataclass
        Pydantic BaseModel
        Mapping
        list
        tuple
        set/frozenset

    Unsupported arbitrary objects are rejected.

    This prevents accidental serialization of internal objects,
    sockets, handles, secrets, locks, services, and other runtime state.
    """

    if value is None:
        return None

    if isinstance(value, bool):
        return value

    if isinstance(value, int):
        return value

    if isinstance(value, float):
        if value != value:
            raise SerializationError(
                "NaN values are not permitted in serialized output."
            )

        if value in (float("inf"), float("-inf")):
            raise SerializationError(
                "Infinite values are not permitted in serialized output."
            )

        return value

    if isinstance(value, str):
        return value

    if isinstance(value, UUID):
        return str(value)

    if isinstance(value, datetime):
        return to_iso8601(value)

    if isinstance(value, date):
        return value.isoformat()

    if isinstance(value, Enum):
        return to_primitive(value.value)

    if isinstance(value, BaseModel):
        return to_primitive(value.model_dump(mode="python"))

    if is_dataclass(value) and not isinstance(value, type):
        return {
            field.name: to_primitive(getattr(value, field.name))
            for field in fields(value)
        }

    if isinstance(value, Mapping):
        result: dict[str, Any] = {}

        for key, item in value.items():
            serialized_key = _serialize_mapping_key(key)

            if serialized_key in result:
                raise SerializationError(
                    "Mapping key collision occurred during serialization.",
                    details={"key": serialized_key},
                )

            result[serialized_key] = to_primitive(item)

        return result

    if isinstance(value, (list, tuple)):
        return [to_primitive(item) for item in value]

    if isinstance(value, (set, frozenset)):
        # Sets have no semantic order. Sorting the serialized representation
        # makes output deterministic where values are mutually comparable
        # after conversion.
        serialized_items = [
            to_primitive(item)
            for item in value
        ]

        try:
            return sorted(
                serialized_items,
                key=lambda item: json.dumps(
                    item,
                    sort_keys=True,
                    separators=(",", ":"),
                ),
            )
        except TypeError as exc:
            raise SerializationError(
                "Set contains values that cannot be deterministically "
                "serialized."
            ) from exc

    raise SerializationError(
        "Unsupported value type for serialization.",
        details={
            "type": type(value).__name__,
        },
    )


def to_json(value: Any) -> str:
    """
    Serialize a supported value to deterministic JSON.

    This is a Phase 0 utility only; persistence belongs to later phases.
    """
    primitive = to_primitive(value)

    try:
        return json.dumps(
            primitive,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
    except (TypeError, ValueError) as exc:
        raise SerializationError(
            "Unable to encode serialized value as JSON."
        ) from exc


# ============================================================================
# SECURITY PRIMITIVES
# ============================================================================


def generate_secure_token(length_bytes: int = 32) -> str:
    """
    Generate a cryptographically secure URL-safe token.

    Minimum:
        16 bytes

    Maximum:
        4096 bytes
    """
    if not isinstance(length_bytes, int):
        raise SecurityError("Token length must be an integer.")

    if isinstance(length_bytes, bool):
        raise SecurityError("Token length must be an integer.")

    if length_bytes < 16:
        raise SecurityError(
            "Token length must be at least 16 bytes."
        )

    if length_bytes > 4096:
        raise SecurityError(
            "Token length exceeds the maximum permitted size."
        )

    return secrets.token_urlsafe(length_bytes)


def constant_time_equals(
    left: str | bytes,
    right: str | bytes,
) -> bool:
    """
    Compare two byte/string secrets using constant-time comparison.

    The function normalizes strings to UTF-8 bytes before comparison.
    """
    if isinstance(left, str):
        left = left.encode("utf-8")

    if isinstance(right, str):
        right = right.encode("utf-8")

    if not isinstance(left, bytes) or not isinstance(right, bytes):
        raise SecurityError(
            "constant_time_equals accepts only str or bytes."
        )

    return hmac.compare_digest(left, right)


def sha256_fingerprint(value: str | bytes) -> str:
    """
    Generate a SHA-256 fingerprint.

    This is a fingerprinting utility, not password hashing.
    """
    if isinstance(value, str):
        value = value.encode("utf-8")

    if not isinstance(value, bytes):
        raise SecurityError(
            "sha256_fingerprint accepts only str or bytes."
        )

    return hashlib.sha256(value).hexdigest()


def redact_secret(
    value: str | bytes | None,
    *,
    visible_prefix: int = 0,
    visible_suffix: int = 0,
    mask: str = "***REDACTED***",
) -> str:
    """
    Safely redact a secret.

    By default the entire value is hidden.

    Prefix/suffix visibility should only be used where operationally
    justified.
    """
    if value is None:
        return mask

    if isinstance(value, bytes):
        text = value.decode("utf-8", errors="replace")
    elif isinstance(value, str):
        text = value
    else:
        raise SecurityError(
            "redact_secret accepts str, bytes, or None."
        )

    if visible_prefix < 0 or visible_suffix < 0:
        raise SecurityError(
            "Visible prefix/suffix cannot be negative."
        )

    if visible_prefix + visible_suffix > len(text):
        raise SecurityError(
            "Visible portions exceed secret length."
        )

    if visible_prefix == 0 and visible_suffix == 0:
        return mask

    prefix = text[:visible_prefix]

    suffix = (
        text[-visible_suffix:]
        if visible_suffix > 0
        else ""
    )

    return f"{prefix}{mask}{suffix}"


def redact_mapping(
    values: Mapping[str, Any],
    *,
    sensitive_keys: Sequence[str] | None = None,
) -> dict[str, Any]:
    """
    Return a sanitized copy of a mapping.

    Matching is case-insensitive.

    The original mapping is never mutated.
    """
    keys = {
        key.strip().lower()
        for key in (
            sensitive_keys
            if sensitive_keys is not None
            else SENSITIVE_KEY_NAMES
        )
    }

    result: dict[str, Any] = {}

    for key, value in values.items():
        if key.lower() in keys:
            result[key] = "***REDACTED***"
        else:
            result[key] = value

    return result


