@runtime_checkable
class Identifiable(Protocol):
    """
    Contract for an object exposing a stable UUID identifier.
    """

    @property
    def id(self) -> UUID:
        ...


@runtime_checkable
class Timestamped(Protocol):
    """
    Contract for an object exposing lifecycle timestamps.
    """

    @property
    def created_at(self) -> datetime:
        ...

    @property
    def updated_at(self) -> datetime:
        ...


@runtime_checkable
class TenantScoped(Protocol):
    """
    Contract for future tenant-owned resources.

    The actual tenant domain model is deliberately not implemented in
    Phase 0. This contract establishes the architectural boundary.
    """

    @property
    def tenant_id(self) -> UUID:
        ...


@runtime_checkable
class Serializable(Protocol):
    """
    Contract for objects capable of producing structured data.
    """

    def to_dict(self) -> Mapping[str, Any]:
        ...


@runtime_checkable
class Auditable(Protocol):
    """
    Contract for objects exposing audit-relevant metadata.

    The actual audit record system belongs to a later phase.
    """

    @property
    def audit_metadata(self) -> Mapping[str, Any]:
        ...


@runtime_checkable
class Service(Protocol):
    """
    Minimal asynchronous service lifecycle contract.
    """

    async def start(self) -> None:
        ...

    async def stop(self) -> None:
        ...


@runtime_checkable
class HealthCheckable(Protocol):
    """
    Contract for service/application health reporting.
    """

    async def health(self) -> Mapping[str, Any]:
        ...


# ============================================================================
# FOUNDATION DATA MODELS
# ============================================================================




class ApplicationState(str, Enum):
    """
    HYDRA application lifecycle states.
    """

    CREATED = "created"
    STARTING = "starting"
    RUNNING = "running"
    STOPPING = "stopping"
    STOPPED = "stopped"
    FAILED = "failed"


class FoundationStatus(BaseModel):
    """
    Small Pydantic model representing Phase 0 application status.

    This is infrastructure status, not a security finding/incident/risk
    object.
    """

    model_config = ConfigDict(extra="forbid")

    application: str
    version: str
    phase: int
    environment: str
    state: str
    timestamp: datetime

    @field_validator("timestamp")
    @classmethod
    def validate_timestamp(
        cls,
        value: datetime,
    ) -> datetime:
        return ensure_utc(value)


# ============================================================================
# ABSTRACT SERVICE FOUNDATION
# ============================================================================


class BaseService(ABC):
    """
    Reusable asynchronous lifecycle foundation.

    This class contains only generic service lifecycle mechanics.
    It does not contain cybersecurity behavior.
    """

    name: ClassVar[str] = "base_service"

    def __init__(self) -> None:
        self._state = ServiceState.CREATED
        self._state_changed_at = utc_now()

    @property
    def state(self) -> ServiceState:
        return self._state

    @property
    def state_changed_at(self) -> datetime:
        return self._state_changed_at

    def _transition(
        self,
        new_state: ServiceState,
        *,
        allowed_from: set[ServiceState],
    ) -> None:
        """
        Perform a validated lifecycle transition.
        """
        if self._state not in allowed_from:
            raise StateTransitionError(
                f"Service '{self.name}' cannot transition from "
                f"'{self._state.value}' to '{new_state.value}'.",
                details={
                    "service": self.name,
                    "current_state": self._state.value,
                    "requested_state": new_state.value,
                },
            )

        self._state = new_state
        self._state_changed_at = utc_now()

    async def start(self) -> None:
        """
        Start the service.
        """
        self._transition(
            ServiceState.STARTING,
            allowed_from={
                ServiceState.CREATED,
                ServiceState.STOPPED,
            },
        )

        try:
            await self.on_start()
        except Exception:
            self._state = ServiceState.FAILED
            self._state_changed_at = utc_now()
            raise

        self._transition(
            ServiceState.RUNNING,
            allowed_from={ServiceState.STARTING},
        )

    async def stop(self) -> None:
        """
        Stop the service.
        """
        self._transition(
            ServiceState.STOPPING,
            allowed_from={ServiceState.RUNNING},
        )

        try:
            await self.on_stop()
        except Exception:
            self._state = ServiceState.FAILED
            self._state_changed_at = utc_now()
            raise

        self._transition(
            ServiceState.STOPPED,
            allowed_from={ServiceState.STOPPING},
        )

    @abstractmethod
    async def on_start(self) -> None:
        """
        Concrete service startup hook.
        """
        raise NotImplementedError

    @abstractmethod
    async def on_stop(self) -> None:
        """
        Concrete service shutdown hook.
        """
        raise NotImplementedError


# ============================================================================
# LOGGING FOUNDATION
# ============================================================================


class SensitiveDataFilter(logging.Filter):
    """
    Defensive logging filter for structured mapping arguments.

    Logging discipline remains the primary protection; this filter provides
    an additional defensive boundary.
    """

    def filter(
        self,
        record: logging.LogRecord,
    ) -> bool:
        """
        Sanitize mapping-style logging arguments where possible.
        """
        if isinstance(record.args, dict):
            record.args = redact_mapping(record.args)

        return True


class HydraFormatter(logging.Formatter):
    """
    Stable HYDRA log formatter.

    The formatter intentionally avoids logging arbitrary object
    representations that may contain secrets.
    """

    def format(
        self,
        record: logging.LogRecord,
    ) -> str:
        timestamp = datetime.fromtimestamp(
            record.created,
            tz=UTC,
        ).isoformat(timespec="milliseconds")

        return (
            f"{timestamp} | "
            f"{record.levelname:<8} | "
            f"{record.name} | "
            f"{record.getMessage()}"
        )


def configure_logging(
    settings: HydraSettings,
) -> logging.Logger:
    """
    Configure the HYDRA logger.

    Repeated calls are idempotent from the application's perspective:
    handlers installed by HYDRA are removed before a fresh configuration.
    """
    logger = logging.getLogger(LOGGER_NAME)

    logger.setLevel(settings.log_level)
    logger.propagate = False

    for handler in list(logger.handlers):
        logger.removeHandler(handler)
        handler.close()

    handler = logging.StreamHandler(sys.stdout)
    handler.setLevel(settings.log_level)
    handler.setFormatter(HydraFormatter())
    handler.addFilter(SensitiveDataFilter())

    logger.addHandler(handler)

    return logger


def get_logger(
    name: str | None = None,
) -> logging.Logger:
    """
    Return a logger inside the HYDRA namespace.
    """
    if not name:
        return logging.getLogger(LOGGER_NAME)

    if name == LOGGER_NAME:
        return logging.getLogger(LOGGER_NAME)

    if name.startswith(f"{LOGGER_NAME}."):
        return logging.getLogger(name)

    return logging.getLogger(
        f"{LOGGER_NAME}.{name}"
    )


# ============================================================================
# APPLICATION FOUNDATION
# ============================================================================


@dataclass(frozen=True)
class ApplicationIdentity:
    """
    Immutable identity of the running HYDRA application.
    """

    name: str
    version: str
    phase: int


class HydraApplication:
    """
    Phase 0 application foundation.

    Responsibilities:
        - Load validated configuration
        - Configure logging
        - Manage foundation lifecycle
        - Provide safe application status
        - Provide controlled shutdown

    No cybersecurity engines are initialized here.
    """

    def __init__(
        self,
        settings: HydraSettings | None = None,
    ) -> None:
        self.settings = settings or get_settings()

        self.identity = ApplicationIdentity(
            name=self.settings.app_name,
            version=HYDRA_VERSION,
            phase=HYDRA_PHASE,
        )

        self._state = ApplicationState.CREATED
        self._created_at = utc_now()
        self._started_at: datetime | None = None
        self._stopped_at: datetime | None = None

        self.logger = configure_logging(self.settings)

    @property
    def state(self) -> ApplicationState:
        return self._state

    @property
    def created_at(self) -> datetime:
        return self._created_at

    @property
    def started_at(self) -> datetime | None:
        return self._started_at

    @property
    def stopped_at(self) -> datetime | None:
        return self._stopped_at

    async def start(self) -> None:
        """
        Start the Phase 0 application foundation.
        """
        if self._state not in {
            ApplicationState.CREATED,
            ApplicationState.STOPPED,
        }:
            raise StateTransitionError(
                f"Application cannot start from state "
                f"'{self._state.value}'.",
                details={
                    "state": self._state.value,
                },
            )

        self._state = ApplicationState.STARTING

        try:
            self._validate_runtime()

            self.logger.info(
                "Starting HYDRA foundation | version=%s | phase=%s",
                self.identity.version,
                self.identity.phase,
            )

            self._started_at = utc_now()
            self._stopped_at = None
            self._state = ApplicationState.RUNNING

            self.logger.info(
                "HYDRA foundation started | environment=%s",
                self.settings.environment.value,
            )

        except Exception:
            self._state = ApplicationState.FAILED
            self.logger.exception(
                "HYDRA foundation startup failed."
            )
            raise

    async def stop(self) -> None:
        """
        Stop the Phase 0 application foundation.
        """
        if self._state != ApplicationState.RUNNING:
            raise StateTransitionError(
                f"Application cannot stop from state "
                f"'{self._state.value}'.",
                details={
                    "state": self._state.value,
                },
            )

        self._state = ApplicationState.STOPPING

        try:
            self.logger.info("Stopping HYDRA foundation.")

            self._stopped_at = utc_now()
            self._state = ApplicationState.STOPPED

            self.logger.info("HYDRA foundation stopped.")

        except Exception:
            self._state = ApplicationState.FAILED
            self.logger.exception(
                "HYDRA foundation shutdown failed."
            )
            raise

    def _validate_runtime(self) -> None:
        """
        Validate foundational runtime assumptions.
        """
        if sys.version_info < (3, 11):
            raise DependencyError(
                "HYDRA requires Python 3.11 or newer.",
                details={
                    "current_python": ".".join(
                        map(str, sys.version_info[:3])
                    )
                },
            )

        # Force validation of the configuration object.
        self.settings.model_validate(
            self.settings.model_dump()
        )

        # Ensure application identity itself is valid.
        if not self.identity.name.strip():
            raise ConfigurationError(
                "Application name cannot be empty."
            )

    async def health(self) -> Mapping[str, Any]:
        """
        Return safe application health information.
        """
        return {
            "application": self.identity.name,
            "version": self.identity.version,
            "phase": self.identity.phase,
            "state": self._state.value,
            "environment": self.settings.environment.value,
            "timestamp": utc_now(),
        }

    def status(self) -> FoundationStatus:
        """
        Return a validated foundation status model.
        """
        return FoundationStatus(
            application=self.identity.name,
            version=self.identity.version,
            phase=self.identity.phase,
            environment=self.settings.environment.value,
            state=self._state.value,
            timestamp=utc_now(),
        )


def create_application(
    settings: HydraSettings | None = None,
) -> HydraApplication:
    """
    Create a configured HYDRA Phase 0 application instance.

    Creation does not automatically start the application.
    """
    return HydraApplication(settings=settings)


# ============================================================================
# PHASE 0 SELF-VERIFICATION
# ============================================================================




class VerificationSuite:
    """
    Internal Phase 0 verification suite.

    This is deliberately lightweight and dependency-minimal.
    It verifies foundation behavior without claiming that future
    cybersecurity functionality exists.
    """

    def __init__(self) -> None:
        self.results: list[VerificationResult] = []

    def check(
        self,
        name: str,
        function: Any,
    ) -> None:
        """
        Execute one check and record its result.
        """
        try:
            function()

        except Exception as exc:
            self.results.append(
                VerificationResult(
                    name=name,
                    passed=False,
                    detail=(
                        f"{type(exc).__name__}: {exc}"
                    ),
                )
            )

        else:
            self.results.append(
                VerificationResult(
                    name=name,
                    passed=True,
                    detail="OK",
                )
            )

    @property
    def passed(self) -> bool:
        return all(
            result.passed
            for result in self.results
        )

    def summary(self) -> dict[str, Any]:
        """
        Return verification summary.
        """
        return {
            "phase": HYDRA_PHASE,
            "total": len(self.results),
            "passed": sum(
                1
                for result in self.results
                if result.passed
            ),
            "failed": sum(
                1
                for result in self.results
                if not result.passed
            ),
            "success": self.passed,
            "results": [
                {
                    "name": result.name,
                    "passed": result.passed,
                    "detail": result.detail,
                }
                for result in self.results
            ],
        }


def verify_phase0(
    *,
    raise_on_failure: bool = True,
) -> dict[str, Any]:
    """
    Run the complete Phase 0 foundation verification suite.

    Important:
        Passing this suite means only that the Phase 0 foundation
        functionality tested here behaves correctly. It does NOT mean
        that future cybersecurity capabilities are implemented.
    """
    suite = VerificationSuite()

    # ------------------------------------------------------------------------
    # IDENTIFIERS
    # ------------------------------------------------------------------------

    def verify_uuid_generation() -> None:
        identifier = generate_id()

        if not isinstance(identifier, UUID):
            raise AssertionError(
                "Generated identifier is not UUID."
            )

        if identifier.version != 4:
            raise AssertionError(
                "Generated identifier is not UUID4."
            )

    suite.check(
        "uuid_generation",
        verify_uuid_generation,
    )

    def verify_uuid_parsing() -> None:
        identifier = generate_id()
        parsed = parse_id(str(identifier))

        if parsed != identifier:
            raise AssertionError(
                "UUID parsing changed identifier."
            )

    suite.check(
        "uuid_parsing",
        verify_uuid_parsing,
    )

    # ------------------------------------------------------------------------
    # TIME
    # ------------------------------------------------------------------------

    def verify_utc_clock() -> None:
        current = utc_now()

        if current.tzinfo is None:
            raise AssertionError(
                "utc_now() returned naive datetime."
            )

        if current.utcoffset() != timezone.utc.utcoffset(current):
            raise AssertionError(
                "utc_now() did not return UTC."
            )

    suite.check(
        "utc_clock",
        verify_utc_clock,
    )

    def verify_timezone_normalization() -> None:
        source = datetime(
            2026,
            1,
            1,
            15,
            0,
            tzinfo=timezone(
                timezone.utc.utcoffset(
                    datetime.now(timezone.utc)
                )
                or timezone.utc.utcoffset(
                    datetime.now(timezone.utc)
                )
            ),
        )

        # The above source is UTC by construction. Now use a fixed +05
        # offset to verify actual normalization.
        from datetime import timedelta

        source = datetime(
            2026,
            1,
            1,
            15,
            0,
            tzinfo=timezone(timedelta(hours=5)),
        )

        normalized = ensure_utc(source)

        if normalized.hour != 10:
            raise AssertionError(
                "Timezone normalization produced wrong UTC hour."
            )

        if normalized.utcoffset() != timedelta(0):
            raise AssertionError(
                "Normalized datetime is not UTC."
            )

    suite.check(
        "timezone_normalization",
        verify_timezone_normalization,
    )

    def verify_naive_datetime_rejection() -> None:
        try:
            ensure_utc(
                datetime(
                    2026,
                    1,
                    1,
                    12,
                    0,
                )
            )
        except ValidationError:
            return

        raise AssertionError(
            "Naive datetime was not rejected."
        )

    suite.check(
        "naive_datetime_rejection",
        verify_naive_datetime_rejection,
    )

    def verify_iso_round_trip() -> None:
        original = datetime(
            2026,
            5,
            20,
            14,
            30,
            45,
            123456,
            tzinfo=UTC,
        )

        encoded = to_iso8601(original)
        decoded = from_iso8601(encoded)

        if not encoded.endswith("Z"):
            raise AssertionError(
                "ISO output does not use UTC Z suffix."
            )

        if decoded != original:
            raise AssertionError(
                "ISO round-trip changed timestamp."
            )

    suite.check(
        "iso8601_round_trip",
        verify_iso_round_trip,
    )

    # ------------------------------------------------------------------------
    # SERIALIZATION
    # ------------------------------------------------------------------------

    def verify_serialization() -> None:
        @dataclass(frozen=True)
        class Record:
            identifier: UUID
            created_at: datetime
            status: str

        identifier = generate_id()
        created_at = utc_now()

        record = Record(
            identifier=identifier,
            created_at=created_at,
            status="active",
        )

        serialized = to_primitive(
            {
                "record": record,
                "items": [1, 2, 3],
                "status": ExampleStatus.ACTIVE,
            }
        )

        if serialized["record"]["identifier"] != str(identifier):
            raise AssertionError(
                "UUID dataclass serialization failed."
            )

        if serialized["status"] != "active":
            raise AssertionError(
                "Enum serialization failed."
            )

        encoded = to_json(serialized)

        if not isinstance(encoded, str):
            raise AssertionError(
                "JSON serializer did not return string."
            )

    suite.check(
        "serialization",
        verify_serialization,
    )

    # ------------------------------------------------------------------------
    # SECURITY
    # ------------------------------------------------------------------------

    def verify_secure_token() -> None:
        first = generate_secure_token(32)
        second = generate_secure_token(32)

        if not first or not second:
            raise AssertionError(
                "Secure token generation returned empty value."
            )

        if first == second:
            raise AssertionError(
                "Two secure token generations unexpectedly matched."
            )

    suite.check(
        "secure_token_generation",
        verify_secure_token,
    )

    def verify_constant_time_comparison() -> None:
        if not constant_time_equals(
            "hydra-secret",
            "hydra-secret",
        ):
            raise AssertionError(
                "Equal values did not compare equal."
            )

        if constant_time_equals(
            "hydra-secret",
            "different-secret",
        ):
            raise AssertionError(
                "Different values compared equal."
            )

    suite.check(
        "constant_time_comparison",
        verify_constant_time_comparison,
    )

    def verify_fingerprint() -> None:
        fingerprint = sha256_fingerprint("HYDRA")

        if len(fingerprint) != 64:
            raise AssertionError(
                "SHA-256 fingerprint has unexpected length."
            )

        if fingerprint != sha256_fingerprint("HYDRA"):
            raise AssertionError(
                "SHA-256 fingerprint is not deterministic."
            )

    suite.check(
        "sha256_fingerprint",
        verify_fingerprint,
    )

    def verify_redaction() -> None:
        secret = "super-secret-value"

        redacted = redact_secret(secret)

        if secret in redacted:
            raise AssertionError(
                "Secret appeared in fully redacted output."
            )

        mapping = {
            "username": "operator",
            "password": secret,
            "token": "token-value",
        }

        sanitized = redact_mapping(mapping)

        if sanitized["password"] != "***REDACTED***":
            raise AssertionError(
                "Password was not redacted."
            )

        if sanitized["token"] != "***REDACTED***":
            raise AssertionError(
                "Token was not redacted."
            )

        if mapping["password"] != secret:
            raise AssertionError(
                "Original mapping was mutated."
            )

    suite.check(
        "secret_redaction",
        verify_redaction,
    )

    # ------------------------------------------------------------------------
    # CONFIGURATION
    # ------------------------------------------------------------------------

    def verify_development_configuration() -> None:
        settings = HydraSettings(
            environment=Environment.DEVELOPMENT,
            debug=True,
        )

        if not settings.is_development:
            raise AssertionError(
                "Development environment detection failed."
            )

    suite.check(
        "development_configuration",
        verify_development_configuration,
    )

    def verify_production_debug_rejection() -> None:
        secret = SecretStr(
            "a" * MIN_APPLICATION_SECRET_LENGTH
        )

        try:
            HydraSettings(
                environment=Environment.PRODUCTION,
                debug=True,
                application_secret=secret,
            )
        except ConfigurationError:
            return

        raise AssertionError(
            "Production debug configuration was accepted."
        )

    suite.check(
        "production_debug_rejection",
        verify_production_debug_rejection,
    )

    def verify_production_secret_requirement() -> None:
        try:
            HydraSettings(
                environment=Environment.PRODUCTION,
                debug=False,
            )
        except ConfigurationError:
            return

        raise AssertionError(
            "Production configuration without secret was accepted."
        )

    suite.check(
        "production_secret_requirement",
        verify_production_secret_requirement,
    )

    def verify_public_config_redaction() -> None:
        secret_value = "a" * MIN_APPLICATION_SECRET_LENGTH

        settings = HydraSettings(
            environment=Environment.DEVELOPMENT,
            application_secret=SecretStr(secret_value),
        )

        public = settings.public_dict()

        if public["application_secret"] != "***CONFIGURED***":
            raise AssertionError(
                "Public configuration did not hide secret."
            )

        if secret_value in str(public):
            raise AssertionError(
                "Raw secret leaked into public configuration."
            )

    suite.check(
        "public_configuration_redaction",
        verify_public_config_redaction,
    )

    # ------------------------------------------------------------------------
    # LIFECYCLE
    # ------------------------------------------------------------------------

    def verify_application_lifecycle() -> None:
        settings = HydraSettings(
            environment=Environment.TESTING,
            debug=False,
        )

        application = HydraApplication(settings)

        if application.state != ApplicationState.CREATED:
            raise AssertionError(
                "Application did not start in CREATED state."
            )

        import asyncio

        asyncio.run(application.start())

        if application.state != ApplicationState.RUNNING:
            raise AssertionError(
                "Application did not reach RUNNING state."
            )

        status = application.status()

        if status.phase != HYDRA_PHASE:
            raise AssertionError(
                "Application reports incorrect phase."
            )

        asyncio.run(application.stop())

        if application.state != ApplicationState.STOPPED:
            raise AssertionError(
                "Application did not reach STOPPED state."
            )

    suite.check(
        "application_lifecycle",
        verify_application_lifecycle,
    )

    # ------------------------------------------------------------------------
    # FINAL RESULT
    # ------------------------------------------------------------------------

    summary = suite.summary()

    if raise_on_failure and not summary["success"]:
        failed = [
            result
            for result in summary["results"]
            if not result["passed"]
        ]

        raise AssertionError(
            "Phase 0 verification failed: "
            + "; ".join(
                f"{item['name']}: {item['detail']}"
                for item in failed
            )
        )

    return summary


