class HydraDomainError(Exception):
    """Base exception for Phase 1 domain violations."""




class TruthIntegrityError(HydraDomainError):
    """Raised when a truth-domain invariant is violated."""


class InvalidStateTransitionError(HydraDomainError):
    """Raised when an object is created with an invalid lifecycle state."""


