# ============================================================================
# CORE PRIMITIVES
# ============================================================================

class DomainModel(BaseModel):
    """
    Base model for all Phase 1 domain objects.

    Extra fields are forbidden so that malformed or silently evolving
    payloads cannot enter the truth core unnoticed.
    """

    model_config = ConfigDict(
        extra="forbid",
        validate_assignment=True,
        validate_default=True,
        str_strip_whitespace=True,
        use_enum_values=False,
    )


class TenantScopedModel(DomainModel):
    """Base for all tenant-scoped truth records."""

    tenant_id: str = Field(min_length=1, max_length=256)

    @field_validator("tenant_id")
    @classmethod
    def validate_tenant_id(cls, value: str) -> str:
        if not value.strip():
            raise ValueError("tenant_id cannot be empty")
        return value


class TimestampedModel(TenantScopedModel):
    """Tenant-scoped model with authoritative UTC timestamps."""

    created_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))
    updated_at: datetime | None = None

    @field_validator("created_at", "updated_at")
    @classmethod
    def normalize_utc(
        cls,
        value: datetime | None,
    ) -> datetime | None:
        if value is None:
            return None

        if value.tzinfo is None:
            raise ValueError("timestamps must be timezone-aware")

        return value.astimezone(timezone.utc)


