class CyberIncident(TimestampedModel):
    """
    Security incident aggregate.

    An incident may contain findings but remains a distinct domain object.
    """

    incident_id: UUID = Field(default_factory=uuid4)

    title: str = Field(min_length=1, max_length=512)

    description: str = Field(min_length=1, max_length=20000)

    severity: IncidentSeverity

    status: IncidentStatus = IncidentStatus.OPEN

    truth_class: TruthClass = Field(default_factory=lambda: TruthClass.INFERENCE)

    finding_ids: list[UUID] = Field(default_factory=list)
    event_ids: list[UUID] = Field(default_factory=list)
    evidence_ids: list[UUID] = Field(default_factory=list)
    entity_ids: list[UUID] = Field(default_factory=list)

    opened_at: datetime = Field(
        default_factory=lambda: datetime.now(timezone.utc)
    )

    closed_at: datetime | None = None

    @field_validator("opened_at", "closed_at")
    @classmethod
    def normalize_incident_time(
        cls,
        value: datetime | None,
    ) -> datetime | None:
        if value is None:
            return None
        if value.tzinfo is None:
            raise ValueError("incident timestamps must be timezone-aware")
        return value.astimezone(timezone.utc)

    @model_validator(mode="after")
    def validate_closed_state(self) -> "CyberIncident":
        closed_states = {
            IncidentStatus.RESOLVED,
            IncidentStatus.CLOSED,
        }

        if self.status in closed_states and self.closed_at is None:
            raise InvalidStateTransitionError(
                "resolved/closed incidents require closed_at"
            )

        if self.status not in closed_states and self.closed_at is not None:
            raise InvalidStateTransitionError(
                "open incidents cannot have closed_at"
            )

        return self


