class CyberExecution(TimestampedModel):
    """
    Record of an actual attempted operation.

    It does not assert that the operation succeeded.
    Verification is responsible for establishing outcome.
    """

    execution_id: UUID = Field(default_factory=uuid4)

    action_id: UUID

    status: ExecutionStatus = ExecutionStatus.STARTED

    executor_id: str = Field(
        min_length=1,
        max_length=256,
    )

    started_at: datetime = Field(
        default_factory=lambda: datetime.now(timezone.utc)
    )

    completed_at: datetime | None = None

    external_execution_id: str | None = Field(
        default=None,
        max_length=512,
    )

    result_reference: str | None = Field(
        default=None,
        max_length=2048,
    )

    error_message: str | None = Field(
        default=None,
        max_length=10000,
    )

    @field_validator("started_at", "completed_at")
    @classmethod
    def normalize_execution_times(
        cls,
        value: datetime | None,
    ) -> datetime | None:
        if value is None:
            return None
        if value.tzinfo is None:
            raise ValueError("execution timestamps must be timezone-aware")
        return value.astimezone(timezone.utc)

    @model_validator(mode="after")
    def validate_execution_state(self) -> "CyberExecution":
        terminal_states = {
            ExecutionStatus.COMPLETED,
            ExecutionStatus.FAILED,
            ExecutionStatus.CANCELLED,
        }

        if self.status in terminal_states and self.completed_at is None:
            raise InvalidStateTransitionError(
                "terminal execution states require completed_at"
            )

        if self.status == ExecutionStatus.FAILED and not self.error_message:
            raise InvalidStateTransitionError(
                "failed execution requires error_message"
            )

        return self


# ============================================================================
# CYBER VERIFICATION
# ============================================================================

class CyberVerification(TimestampedModel):
    """
    Independent verification of execution outcome.

    Execution says what was attempted/performed.
    Verification establishes what actually happened afterwards.
    """

    verification_id: UUID = Field(default_factory=uuid4)

    execution_id: UUID

    status: VerificationStatus = Field(default_factory=lambda: VerificationStatus.PENDING)

    verifier_id: str = Field(
        min_length=1,
        max_length=256,
    )

    evidence_ids: list[UUID] = Field(default_factory=list)

    observed_state: dict[str, Any] = Field(default_factory=dict)

    verified_at: datetime | None = None

    rationale: str | None = Field(
        default=None,
        max_length=10000,
    )

    @field_validator("verified_at")
    @classmethod
    def normalize_verified_at(
        cls,
        value: datetime | None,
    ) -> datetime | None:
        if value is None:
            return None
        if value.tzinfo is None:
            raise ValueError("verified_at must be timezone-aware")
        return value.astimezone(timezone.utc)

    @model_validator(mode="after")
    def validate_verification_state(self) -> "CyberVerification":
        final_states = {
            VerificationStatus.VERIFIED,
            VerificationStatus.FAILED,
            VerificationStatus.INCONCLUSIVE,
        }

        if self.status in final_states and self.verified_at is None:
            raise InvalidStateTransitionError(
                "final verification states require verified_at"
            )

        return self


# ============================================================================
# CYBER MEMORY
# ============================================================================

class CyberMemory(TimestampedModel):
    """
    Provenance-aware memory record.

    Phase 1 defines the primitive only.
    Memory engines and retrieval systems belong to later phases.
    """

    memory_id: UUID = Field(default_factory=uuid4)

    kind: MemoryKind = MemoryKind.GENERAL

    truth_class: TruthClass

    subject: str = Field(
        min_length=1,
        max_length=512,
    )

    content: dict[str, Any] = Field(default_factory=dict)

    source_ids: list[UUID] = Field(default_factory=list)

    confidence: ConfidenceScore | None = None

    valid_from: datetime | None = None
    valid_until: datetime | None = None

    @field_validator("valid_from", "valid_until")
    @classmethod
    def normalize_memory_time(
        cls,
        value: datetime | None,
    ) -> datetime | None:
        if value is None:
            return None
        if value.tzinfo is None:
            raise ValueError("memory timestamps must be timezone-aware")
        return value.astimezone(timezone.utc)

    @model_validator(mode="after")
    def validate_memory_interval(self) -> "CyberMemory":
        if (
            self.valid_from is not None
            and self.valid_until is not None
            and self.valid_until < self.valid_from
        ):
            raise ValueError(
                "valid_until cannot be earlier than valid_from"
            )

        return self


