# ============================================================================
# TENANT INTEGRITY HELPERS
# ============================================================================

class TruthCoreIntegrity:
    """
    Small deterministic integrity service for Phase 1.

    It does not perform detection, risk analysis or response.
    """

    @staticmethod
    def ensure_same_tenant(
        expected_tenant_id: str,
        *records: TenantScopedModel,
    ) -> None:
        for record in records:
            if record.tenant_id != expected_tenant_id:
                raise TenantIsolationError(
                    "cross-tenant reference detected"
                )

    @staticmethod
    def ensure_unique_ids(
        records: Sequence[DomainModel],
        attribute: str,
    ) -> None:
        seen: set[Any] = set()

        for record in records:
            value = getattr(record, attribute, None)

            if value is None:
                raise TruthIntegrityError(
                    f"record missing required identifier: {attribute}"
                )

            if value in seen:
                raise TruthIntegrityError(
                    f"duplicate identifier detected: {value}"
                )

            seen.add(value)


