def verify_phase1() -> int:
    """
    Run deterministic Phase 1 verification.

    Returns:
        0 when all checks pass.
        1 when one or more checks fail.
    """

    print("=" * 72)
    print("HYDRA — PHASE 1 VERIFICATION")
    print("=" * 72)
    print(f"Phase:    {PHASE}")
    print(f"Scope:    {PHASE_NAME}")
    print(f"Version:  {PRODUCT_VERSION}")
    print()

    results = Phase1VerificationSuite.run()

    for result in results:
        status = "PASS" if result.passed else "FAIL"
        print(f"[{status}] {result.check}")

        if not result.passed:
            print(f"       {result.detail}")

    passed = sum(result.passed for result in results)
    total = len(results)

    print()
    print(f"Verification result: {passed}/{total} checks passed")

    if passed == total:
        print("PHASE 1 VERIFICATION: PASS")
        return 0

    print("PHASE 1 VERIFICATION: FAIL")
    return 1


