def normalize_timestamp(value: datetime | str) -> str:
    """
    Normalize a timestamp to an aware UTC ISO-8601 string.

    Naive timestamps are rejected rather than silently interpreted.
    """
    if isinstance(value, str):
        parsed = datetime.fromisoformat(
            value.replace("Z", "+00:00")
        )
    elif isinstance(value, datetime):
        parsed = value
    else:
        raise TypeError(
            "timestamp must be datetime or ISO-8601 string"
        )

    if parsed.tzinfo is None:
        raise ValueError(
            "timestamp must be timezone-aware"
        )

    return parsed.astimezone(timezone.utc).isoformat()








