class CyberRecordIdentity:
    """
    Deterministic identity generator.

    The same tenant/source/schema/event/payload produces the same fingerprint.
    """

    @staticmethod
    def fingerprint(
        *,
        tenant_id: str,
        source: str,
        source_event_id: str,
        event_type: str,
        schema_name: str,
        schema_version: str,
        payload: Mapping[str, Any],
    ) -> str:

        canonical = {
            "tenant_id": tenant_id,
            "source": source,
            "source_event_id": source_event_id,
            "event_type": event_type,
            "schema_name": schema_name,
            "schema_version": schema_version,
            "payload": deep_copy(dict(payload)),
        }

        return stable_hash(canonical)

    @staticmethod
    def record_id(
        fingerprint: str,
    ) -> str:

        if not fingerprint:
            raise ValueError(
                "fingerprint cannot be empty"
            )

        return (
            "telemetry_"
            + fingerprint[:32]
        )


