def assert_connector_tenant(
    account: ConnectorAccount,
) -> None:
    """
    Validate the account's tenant boundary.

    Connector implementations must use the account's tenant scope and
    must never receive another tenant's account implicitly.
    """
    if not account.tenant_id.strip():
        raise TenantIsolationError(
            "Connector account has no tenant."
        )


