class TestHealthConnector(
    CyberConnector
):
    """
    Local test-only connector.

    This class does not represent a production vendor integration.
    """

    def __init__(
        self,
    ) -> None:

        super().__init__(
            connector_id="local.test.connector",
            display_name="Local Test Connector",
            capabilities={
                ConnectorCapability.HEALTH,
            },
        )

    def health(
        self,
        account: ConnectorAccount,
    ) -> ConnectorHealth:

        assert_connector_tenant(
            account
        )

        return ConnectorHealth(
            connector_id=self.connector_id,
            status=ConnectorStatus.HEALTHY,
            checked_at=iso_now(),
            message=(
                "Deterministic local "
                "test connector healthy."
            ),
        )
    # --- preserved from TestHealthConnector (merged, not present in canonical host) ---
    def _health_check(self) -> Optional[str]:
        return "Deterministic local test connector healthy."
    # --- preserved from TestHealthConnector (merged, not present in canonical host) ---
    def capabilities(self) -> frozenset:
        return frozenset({ConnectorCapability.HEALTH})


