class InMemoryIdempotencyStore:

    def __init__(self) -> None:
        self._lock = threading.RLock()
        self._keys: set[Tuple[str, str]] = set()

    def seen(
        self,
        tenant_id: str,
        idempotency_key: str,
    ) -> bool:

        with self._lock:
            return (
                tenant_id,
                idempotency_key,
            ) in self._keys

    def record(
        self,
        tenant_id: str,
        idempotency_key: str,
    ) -> bool:

        with self._lock:

            key = (
                tenant_id,
                idempotency_key,
            )

            if key in self._keys:
                return False

            self._keys.add(key)
            return True


