class UrllibHTTPTransport:

    """
    Standard-library HTTP transport.

    Security properties:
    - no automatic redirect handler
    - bounded response size
    - bounded timeout
    - explicit HTTP method
    """

    def __init__(
        self,
        *,
        max_response_bytes: int = MAX_RESPONSE_BYTES,
        user_agent: str = "HYDRA-Cyber-Connector/4.0",
    ) -> None:

        if max_response_bytes <= 0:
            raise ValueError(
                "max_response_bytes must be positive."
            )

        self.max_response_bytes = (
            max_response_bytes
        )

        self.user_agent = user_agent

    def request(
        self,
        *,
        method: str,
        url: str,
        headers: Optional[Mapping[str, str]] = None,
        body: Optional[bytes] = None,
        timeout_seconds: float = 10.0,
    ) -> HTTPResponse:

        method = method.upper()

        if timeout_seconds <= 0:
            raise ValueError(
                "timeout_seconds must be positive."
            )

        if timeout_seconds > MAX_TIMEOUT_SECONDS:
            raise ValueError(
                "timeout exceeds safety limit."
            )

        request_headers = {
            "User-Agent": self.user_agent,
            "Accept": "application/json",
        }

        if headers:
            for key, value in headers.items():
                request_headers[str(key)] = str(value)

        request_object = urllib_request.Request(
            url=url,
            data=body,
            headers=request_headers,
            method=method,
        )

        try:

            response = urllib_request.urlopen(
                request_object,
                timeout=timeout_seconds,
            )

            try:

                body_bytes = response.read(
                    self.max_response_bytes + 1
                )

                if len(body_bytes) > self.max_response_bytes:
                    raise ConnectorProtocolError(
                        "HTTP response exceeded maximum size."
                    )

                headers_out = {
                    str(key): str(value)
                    for key, value
                    in response.headers.items()
                }

                return HTTPResponse(
                    status_code=int(
                        response.status
                    ),
                    headers=headers_out,
                    body=body_bytes,
                )

            finally:
                response.close()

        except urllib_error.HTTPError as exc:

            body_bytes = exc.read(
                self.max_response_bytes + 1
            )

            if len(body_bytes) > self.max_response_bytes:
                body_bytes = body_bytes[
                    : self.max_response_bytes
                ]

            headers_out = {
                str(key): str(value)
                for key, value
                in exc.headers.items()
            }

            return HTTPResponse(
                status_code=int(exc.code),
                headers=headers_out,
                body=body_bytes,
            )

        except urllib_error.URLError as exc:

            raise ConnectorUnavailableError(
                f"HTTP transport unavailable: {exc.reason}"
            ) from exc

        except TimeoutError as exc:

            raise ConnectorTimeoutError(
                "HTTP transport timed out."
            ) from exc


