class ConnectorEventSink(Protocol):

    def accept(
        self,
        event: ConnectorEvent,
    ) -> bool:
        ...


class InMemoryConnectorEventSink:

    """
    Small local event sink useful for Phase 4 integration tests.

    It does not replace the Phase 3 Data Fabric.
    """

    def __init__(self) -> None:
        self._lock = threading.RLock()
        self._events: List[ConnectorEvent] = []

    def accept(
        self,
        event: ConnectorEvent,
    ) -> bool:

        with self._lock:
            self._events.append(event)

        return True

    def list(
        self,
        *,
        tenant_id: Optional[str] = None,
    ) -> List[ConnectorEvent]:

        with self._lock:

            if tenant_id is None:
                return list(self._events)

            return [
                event
                for event in self._events
                if event.tenant_id == tenant_id
            ]


