def verify_idempotency() -> bool:

    store = InMemoryIdempotencyStore()

    tenant = "tenant-A"
    key = "event-key-001"

    first = store.record(
        tenant,
        key,
    )

    second = store.record(
        tenant,
        key,
    )

    other_tenant = store.record(
        "tenant-B",
        key,
    )

    return (
        first is True
        and second is False
        and other_tenant is True
        and store.seen(
            tenant,
            key,
        )
    )


