def verify_checkpointing() -> bool:

    store = InMemoryCheckpointStore()

    checkpoint = ConnectorCheckpoint(
        connector_id="connector-001",
        tenant_id="tenant-A",
        cursor="cursor-42",
        sequence=42,
        updated_at=utc_now(),
    )

    store.save(
        checkpoint
    )

    restored = store.get(
        "connector-001",
        "tenant-A",
    )

    return (
        restored is not None
        and restored.cursor == "cursor-42"
        and restored.sequence == 42
    )


