def verify_connector_manager() -> bool:

    registry = ConnectorRegistry()

    for index in range(2):

        config = ConnectorConfig(
            connector_id=f"manager-{index}",
            tenant_id="tenant-A",
            name=f"Manager {index}",
            family=ConnectorFamily.SIEM,
        )

        registry.register(
            SimulatedConnector(
                config
            )
        )

    manager = ConnectorManager(
        registry
    )

    initialization = (
        manager.initialize_all()
    )

    health = (
        manager.health_report()
    )

    manager.stop_all()

    return (
        len(initialization) == 2
        and all(
            initialization.values()
        )
        and len(health) == 2
        and all(
            item.status
            == ConnectorStatus.READY
            for item in health
        )
        and all(
            connector.status
            == ConnectorStatus.STOPPED
            for connector
            in registry.list()
        )
    )


