def validate_mapping(
    value: Mapping[str, Any],
    field_name: str,
) -> Dict[str, Any]:

    if not isinstance(value, Mapping):
        raise TypeError(
            f"{field_name} must be a mapping."
        )

    if len(value) > MAX_ENRICHMENT_ITEMS:
        raise ValueError(
            f"{field_name} exceeds "
            f"{MAX_ENRICHMENT_ITEMS} items."
        )

    return dict(value)


