class TenantSafeThreatIntelProvider:

    """
    Adapter that binds a provider to a tenant boundary.

    It prevents a provider implementation from being used to silently
    inject another tenant's intelligence.
    """

    def __init__(
        self,
        tenant_id: str,
        provider: ThreatIntelProvider,
    ) -> None:

        self.tenant_id = validate_identifier(
            tenant_id,
            "tenant_id",
        )

        self.provider = provider

    @property
    def provider_id(self) -> str:

        return (
            f"{self.tenant_id}:"
            f"{self.provider.provider_id}"
        )

    def lookup(
        self,
        ioc_type: IOCType,
        value: str,
    ) -> Optional[
        ThreatIntelRecord
    ]:

        result = self.provider.lookup(
            ioc_type,
            value,
        )

        if result is None:
            return None

        if result.tenant_id != self.tenant_id:

            raise ThreatIntelProviderConflictError(
                "Provider returned cross-tenant "
                "intelligence."
            )

        return result


