def clamp_score(value: float) -> float:
    """
    Normalize a security score to [0, 100].

    Rejects NaN and infinity instead of silently converting malformed
    numerical input into apparently valid security intelligence.
    """
    try:
        numeric = float(value)
    except (TypeError, ValueError) as exc:
        raise ValidationError(
            f"Expected numeric score, received {value!r}."
        ) from exc

    if not math.isfinite(numeric):
        raise ValidationError(
            f"Security score must be finite, received {value!r}."
        )

    return max(0.0, min(100.0, numeric))


def clamp_probability(value: float) -> float:
    """
    Normalize a confidence/probability value to [0, 1].
    """
    try:
        numeric = float(value)
    except (TypeError, ValueError) as exc:
        raise ValidationError(
            f"Expected probability, received {value!r}."
        ) from exc

    if not math.isfinite(numeric):
        raise ValidationError(
            f"Probability must be finite, received {value!r}."
        )

    return max(0.0, min(1.0, numeric))


def positive_int(
    value: int,
    *,
    name: str,
    maximum: int,
) -> int:
    """
    Validate bounded positive integer configuration.

    Bounds are intentionally enforced so graph traversal cannot be
    accidentally configured into an uncontrolled computation.
    """
    if isinstance(value, bool):
        raise ValidationError(f"{name} must be an integer.")

    try:
        numeric = int(value)
    except (TypeError, ValueError) as exc:
        raise ValidationError(
            f"{name} must be an integer."
        ) from exc

    if numeric < 1:
        raise ValidationError(
            f"{name} must be >= 1."
        )

    if numeric > maximum:
        raise ValidationError(
            f"{name} must be <= {maximum}."
        )

    return numeric


def utc_timestamp() -> float:
    """
    UTC epoch timestamp.

    Epoch time is used here because Phase 7 contracts in the existing
    foundation use a numeric calculation timestamp.
    """
    return time.time()


