def test_vulnerability_controls_reduce_score() -> None:
    base = VulnerabilityContext(
        vulnerability_id="CVE-TEST-002",
        cvss=9.0,
        exploitable=True,
        internet_exposed=True,
        exploit_available=True,
        active_threat_activity=80,
        compensating_controls=0,
    )

    protected = VulnerabilityContext(
        vulnerability_id="CVE-TEST-002",
        cvss=9.0,
        exploitable=True,
        internet_exposed=True,
        exploit_available=True,
        active_threat_activity=80,
        compensating_controls=80,
    )

    engine = VulnerabilityContextEngine()

    base_score = engine.assess(base)
    protected_score = engine.assess(protected)

    assert protected_score < base_score






