def test_attack_path_cycle_is_bounded() -> None:
    service = Phase7RiskAttackPathService()

    for node_id in ("a", "b", "c"):
        service.add_node(
            GraphNode(
                node_id=node_id,
                node_type=NodeType.ASSET,
                criticality=50,
            )
        )

    service.add_edge(
        GraphEdge(
            source="a",
            target="b",
            edge_type=EdgeType.LEADS_TO,
            confidence=1.0,
            exploitability=80,
        )
    )

    service.add_edge(
        GraphEdge(
            source="b",
            target="c",
            edge_type=EdgeType.LEADS_TO,
            confidence=1.0,
            exploitability=80,
        )
    )

    service.add_edge(
        GraphEdge(
            source="c",
            target="a",
            edge_type=EdgeType.LEADS_TO,
            confidence=1.0,
            exploitability=80,
        )
    )

    paths = service.discover_attack_paths(
        ["a"],
        ["c"],
    )

    assert len(paths) == 1
    assert paths[0].nodes == [
        "a",
        "b",
        "c",
    ]








