def test_aggregation_by_subject() -> None:
    engine = CyberRiskEngine()

    assessments = [
        engine.calculate(
            AssetRiskContext(
                asset_id="same-asset",
                criticality=40,
                exposure=30,
            )
        ),
        engine.calculate(
            AssetRiskContext(
                asset_id="same-asset",
                criticality=90,
                exposure=90,
            )
        ),
    ]

    result = (
        RiskAggregationEngine()
        .aggregate_by_subject(
            assessments
        )
    )

    assert set(result) == {
        "same-asset"
    }

    assert result["same-asset"] == max(
        assessment.score
        for assessment in assessments
    )


