    paths = service.discover_attack_paths(
        ["internet"],
        ["critical-server"],
    )

    assessment = service.assess_risk(
        AssetRiskContext(
            asset_id="critical-server",
            criticality=90,
            exposure=90,
            exploitability=90,
        ),
        attack_paths=paths,
        evidence_ids=("evidence-1",),
    )

    assert paths
    assert assessment.attack_path_ids
    assert assessment.evidence_ids == [
        "evidence-1"
    ]
    assert assessment.score > 0.0


