def require_nonempty(
    value: str,
    field_name: str,
) -> str:
    if not isinstance(value, str):
        raise TypeError(
            f"{field_name} must be a string."
        )

    value = value.strip()

    if not value:
        raise ValueError(
            f"{field_name} is required."
        )

    return value


def bounded_int(
    value: int,
    *,
    field_name: str,
    minimum: int = 0,
    maximum: int = 100_000,
) -> int:
    if isinstance(value, bool):
        raise TypeError(
            f"{field_name} must be an integer."
        )

    if not isinstance(value, int):
        raise TypeError(
            f"{field_name} must be an integer."
        )

    if value < minimum or value > maximum:
        raise ValueError(
            f"{field_name} must be between "
            f"{minimum} and {maximum}."
        )

    return value


def bounded_score(
    value: float,
    *,
    field_name: str,
) -> float:
    try:
        score = float(value)
    except (TypeError, ValueError) as exc:
        raise ValueError(
            f"{field_name} must be numeric."
        ) from exc

    if score != score:
        raise ValueError(
            f"{field_name} cannot be NaN."
        )

    if score in (
        float("inf"),
        float("-inf"),
    ):
        raise ValueError(
            f"{field_name} must be finite."
        )

    if not 0.0 <= score <= 100.0:
        raise ValueError(
            f"{field_name} must be between 0 and 100."
        )

    return score


