@dataclass(frozen=True)
class AgentResult:
    """
    Structured result returned by a Phase 8 agent.

    Phase 8 does not invent findings or intelligence.
    Agents return an explicit status and preserve supplied references.
    """

    status: str

    agent: str

    agent_id: UUID

    run_id: UUID

    findings: Tuple[
        Mapping[str, Any],
        ...
    ] = ()

    evidence_ids: Tuple[str, ...] = ()

    metadata: Mapping[str, Any] = field(
        default_factory=dict
    )

    def as_dict(self) -> Dict[str, Any]:
        return {
            "status": self.status,
            "agent": self.agent,
            "agent_id": str(
                self.agent_id
            ),
            "run_id": str(
                self.run_id
            ),
            "findings": [
                dict(item)
                for item in self.findings
            ],
            "evidence_ids": list(
                self.evidence_ids
            ),
            "metadata": dict(
                self.metadata
            ),
        }


