def test_side_effecting_tool_registration_is_blocked() -> None:

    sink = InMemoryAgentAuditSink()

    tenant = uuid4()

    agent = create_agent(
        agent_type=AgentType.EXECUTION,
        tenant_id=tenant,
        audit_sink=sink,
    )

    tool = RegisteredTool(
        definition=ToolDefinition(
            name="dangerous_external_action",
            description=(
                "Test side-effecting operation."
            ),
            capabilities=frozenset({
                Capability.EXECUTE_ACTION
            }),
            side_effecting=True,
        ),
        handler=lambda context, arguments: {
            "executed": True
        },
    )

    # The capability itself may be present in the role.
    # Side-effecting execution is nevertheless blocked in Phase 8.
    try:
        agent.runtime.register_tool(
            tool
        )

    except PermissionError:
        return

    raise AssertionError(
        "Side-effecting tool escaped Phase 8 registration boundary."
    )


def test_read_only_tool_can_execute() -> None:

    sink = InMemoryAgentAuditSink()

    tenant = uuid4()

    agent = create_agent(
        agent_type=AgentType.DETECTION,
        tenant_id=tenant,
        audit_sink=sink,
    )

    tool = RegisteredTool(
        definition=ToolDefinition(
            name="read_event",
            description=(
                "Read an event reference."
            ),
            capabilities=frozenset({
                Capability.READ_EVENTS
            }),
            side_effecting=False,
        ),
        handler=lambda context, arguments: {
            "event_id": arguments.get(
                "event_id"
            ),
            "read_only": True,
        },
    )

    # Factory policy intentionally has no tool names.
    # A tool must first be explicitly allowed by a policy.
    agent.runtime.policy = AgentPolicy(
        allowed_capabilities=frozenset({
            Capability.READ_EVENTS
        }),
        allowed_tools=frozenset({
            "read_event"
        }),
        limits=AgentLimits(
            max_actions_per_run=0,
            max_tool_calls_per_run=10,
            max_execution_risk_score=0.0,
            allow_external_side_effects=False,
        ),
    )

    agent.runtime.register_tool(
        tool
    )

    context = AgentContext(
        run_id=uuid4(),
        tenant_id=tenant,
        actor_id=agent.identity.agent_id,
        agent_identity=agent.identity,
        correlation_id="read-tool-test",
    )

    result = agent.runtime.invoke_tool(
        context,
        "read_event",
        {
            "event_id": "evt-123"
        },
    )

    assert result == {
        "event_id": "evt-123",
        "read_only": True,
    }

    assert len(
        sink.events
    ) == 1

    assert (
        sink.events[0].success
        is True
    )


