def test_agent_registry_is_tenant_scoped() -> None:

    sink = InMemoryAgentAuditSink()

    tenant_a = uuid4()
    tenant_b = uuid4()

    agent_a = create_agent(
        agent_type=AgentType.DETECTION,
        tenant_id=tenant_a,
        audit_sink=sink,
    )

    agent_b = create_agent(
        agent_type=AgentType.INVESTIGATION,
        tenant_id=tenant_b,
        audit_sink=sink,
    )

    registry = CyberAgentRegistry()

    registry.register(
        agent_a
    )

    registry.register(
        agent_b
    )

    assert len(
        registry.for_tenant(
            tenant_a
        )
    ) == 1

    assert (
        registry.for_tenant(
            tenant_a
        )[0].identity.agent_id
        == agent_a.identity.agent_id
    )

    assert len(
        registry.for_tenant(
            tenant_b
        )
    ) == 1


