def test_audit_failure_is_recorded() -> None:

    sink = InMemoryAgentAuditSink()

    tenant = uuid4()

    agent = create_agent(
        agent_type=AgentType.DETECTION,
        tenant_id=tenant,
        audit_sink=sink,
    )

    agent.runtime.policy = AgentPolicy(
        allowed_capabilities=frozenset({
            Capability.READ_EVENTS
        }),
        allowed_tools=frozenset({
            "failing_read"
        }),
    )

    tool = RegisteredTool(
        definition=ToolDefinition(
            name="failing_read",
            description="Intentional failure test.",
            capabilities=frozenset({
                Capability.READ_EVENTS
            }),
        ),
        handler=lambda context, arguments: (
            1 / 0
        ),
    )

    agent.runtime.register_tool(
        tool
    )

    context = AgentContext(
        run_id=uuid4(),
        tenant_id=tenant,
        actor_id=agent.identity.agent_id,
        agent_identity=agent.identity,
        correlation_id="audit-failure",
    )

    try:
        agent.runtime.invoke_tool(
            context,
            "failing_read",
            {},
        )

    except ZeroDivisionError:
        pass

    else:
        raise AssertionError(
            "Expected tool failure did not occur."
        )

    assert len(
        sink.events
    ) == 1

    assert (
        sink.events[0].success
        is False
    )

    assert (
        sink.events[0].details[
            "error_type"
        ]
        == "ZeroDivisionError"
    )


