def run_phase_8_tests() -> Dict[str, Any]:

    started = utc_now()

    results: Dict[
        str,
        str,
    ] = {}

    failures: list[
        Dict[str, str]
    ] = []

    for test in PHASE8_TESTS:

        name = test.__name__

        try:
            test()

            results[name] = "PASS"

        except Exception as exc:

            results[name] = "FAIL"

            failures.append({
                "test": name,
                "error": (
                    f"{type(exc).__name__}: "
                    f"{exc}"
                ),
            })

    finished = utc_now()

    return {
        "phase": PHASE,
        "component": PHASE_NAME,
        "version": PHASE_VERSION,
        "started_at": started.isoformat(),
        "finished_at": finished.isoformat(),
        "tests_total": len(
            PHASE8_TESTS
        ),
        "tests_passed": sum(
            value == "PASS"
            for value
            in results.values()
        ),
        "tests_failed": sum(
            value == "FAIL"
            for value
            in results.values()
        ),
        "results": results,
        "failures": failures,
        "status": (
            "VERIFIED"
            if not failures
            else "FAILED"
        ),
    }


# ============================================================
# 21. PUBLIC VERIFICATION CONTRACT
# ============================================================

def verify_phase8() -> Dict[str, Any]:
    return run_phase_8_tests()


