def calculate_action_binding(
    request: CyberActionRequest,
) -> str:
    """
    Create a cryptographic binding for the exact action request.

    This prevents an approval for one action from being silently reused
    against another target/action.
    """

    request.validate()

    payload = {
        "action_id": str(
            request.action_id
        ),
        "tenant_id": str(
            request.tenant_id
        ),
        "requested_by": str(
            request.requested_by
        ),
        "agent_id": str(
            request.agent_id
        ),
        "action": request.action.value,
        "action_level": (
            request.action_level.value
        ),
        "target_id": request.target_id,
        "target_type": request.target_type,
        "risk_score": request.risk_score,
        "confidence": request.confidence,
        "incident_id": request.incident_id,
        "finding_id": request.finding_id,
        "reason": request.reason,
        "evidence_ids": list(
            request.evidence_ids
        ),
    }

    return sha256(
        canonical_json(
            payload
        ).encode("utf-8")
    ).hexdigest()


