@dataclass(frozen=True)
class PermissionEvaluation:

    allowed: bool

    reason: str


class PermissionEvaluator:
    """
    Phase-9 permission boundary.

    The actual identity/capability issuance belongs to the security/agent
    layers. This component only verifies whether the already-granted action
    capability contains the requested response action.
    """

    def evaluate(
        self,
        request: CyberActionRequest,
        granted_actions: frozenset[
            ResponseAction
        ],
    ) -> PermissionEvaluation:

        request.validate()

        if request.action not in granted_actions:

            return PermissionEvaluation(
                allowed=False,
                reason=(
                    "Agent is not granted the "
                    "requested response capability."
                ),
            )

        return PermissionEvaluation(
            allowed=True,
            reason=(
                "Required response capability "
                "is granted."
            ),
        )


