def stable_fingerprint(
    value: Any,
) -> str:
    """
    Deterministic SHA-256 fingerprint.

    Used only to identify the simulated source state.
    """

    import json

    encoded = json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        default=str,
    ).encode("utf-8")

    return sha256(
        encoded
    ).hexdigest()


