# ============================================================
# GENERIC CONTRACT VALIDATOR
# ============================================================

class ContractValidator:

    @staticmethod
    def require_fields(
        obj: Any,
        fields: Sequence[str],
    ) -> dict[str, Any]:

        missing = [
            field_name
            for field_name in fields
            if not hasattr(
                obj,
                field_name,
            )
            and not (
                isinstance(
                    obj,
                    Mapping,
                )
                and field_name in obj
            )
        ]

        if missing:
            raise AssertionError(
                f"Missing required fields: {missing}"
            )

        return {
            "required_fields": list(fields),
            "missing": [],
        }

    @staticmethod
    def require_callable(
        obj: Any,
        methods: Sequence[str],
    ) -> dict[str, Any]:

        missing = [
            method
            for method in methods
            if not callable(
                getattr(
                    obj,
                    method,
                    None,
                )
            )
        ]

        if missing:
            raise AssertionError(
                f"Missing callable methods: {missing}"
            )

        return {
            "methods": list(methods),
            "missing": [],
        }


