def _test_audit_chain_and_tamper_detection() -> None:

    chain = _make_audit_chain()

    result = (
        AuditChainValidator
        .validate_chain(
            chain
        )
    )

    assert result[
        "chain_valid"
    ]

    tampered = [
        dict(record)
        for record in chain
    ]

    tampered[0][
        "event"
    ] = "tampered"

    try:

        AuditChainValidator.validate_chain(
            tampered
        )

    except AssertionError:

        return

    raise AssertionError(
        "Tampered audit record was accepted."
    )


