def _test_idempotency() -> None:

    calls = {
        "count": 0
    }

    def processor(
        event_id: str,
    ) -> dict[str, str]:

        calls[
            "count"
        ] += 1

        return {
            "event_id":
                event_id,
            "status":
                "processed",
        }

    result = (
        IdempotencyValidator
        .validate(
            processor,
            "evt-1",
        )
    )

    assert result[
        "idempotent"
    ]

    assert calls[
        "count"
    ] == 2


