def run_phase11_tests() -> dict[str, Any]:

    tests = [
        _test_contracts,
        _test_tenant_isolation,
        _test_provenance_and_evidence,
        _test_confidence_and_reasoning,
        _test_external_input,
        _test_audit_chain_and_tamper_detection,
        _test_idempotency,
        _test_replay_safety,
        _test_secret_boundary,
        _test_negative_confidence,
        _test_callable_telemetry_rejected,
    ]

    failures: list[
        dict[str, str]
    ] = []

    started = time.perf_counter()

    for test in tests:

        try:

            test()

        except Exception as exc:

            failures.append(
                {
                    "test":
                        test.__name__,
                    "error":
                        (
                            f"{type(exc).__name__}: "
                            f"{exc}"
                        ),
                }
            )

    elapsed_ms = (
        time.perf_counter()
        - started
    ) * 1000.0

    return {
        "phase":
            PHASE,
        "product":
            PRODUCT,
        "tests_total":
            len(tests),
        "tests_passed":
            len(tests) - len(failures),
        "tests_failed":
            len(failures),
        "status":
            (
                "PASS"
                if not failures
                else "FAIL"
            ),
        "failures":
            failures,
        "elapsed_ms":
            round(
                elapsed_ms,
                3,
            ),
    }


