# ============================================================
# BASE CYBER AGENT
# ============================================================

class BaseCyberAgent:

    def __init__(
        self,
        identity: AgentIdentity,
        policy: AgentPolicy,
    ) -> None:

        self.identity = identity
        self.policy = policy

        self.runtime = AgentRuntime(
            identity,
            policy,
        )

    @property
    def agent_id(self) -> str:
        return self.identity.agent_id

    @property
    def tenant_id(self) -> str:
        return self.identity.tenant_id

    @property
    def agent_type(self) -> AgentType:
        return self.identity.agent_type

    @property
    def state(self) -> AgentState:
        return self.runtime.state

    def initialize(self) -> None:

        self.runtime.transition(
            AgentState.INITIALIZING
        )

        self.runtime.transition(
            AgentState.READY
        )

    def start(self) -> None:

        if self.state is AgentState.CREATED:
            self.initialize()

        self.runtime.transition(
            AgentState.RUNNING
        )

    def pause(self) -> None:

        self.runtime.transition(
            AgentState.PAUSED
        )

    def disable(self) -> None:

        self.runtime.transition(
            AgentState.DISABLED
        )

    def terminate(self) -> None:

        self.runtime.transition(
            AgentState.TERMINATED
        )

    def register_tool(
        self,
        tool: RegisteredTool,
    ) -> None:

        self.runtime.register_tool(
            tool
        )

    def invoke_tool(
        self,
        tool_name: str,
        *,
        tenant_id: str,
        **kwargs: Any,
    ) -> Any:

        return self.runtime.invoke_tool(
            tool_name,
            tenant_id=tenant_id,
            **kwargs,
        )

    def validate_action(
        self,
        request: AgentActionRequest,
    ) -> AgentActionResult:

        return self.runtime.validate_action(
            request
        )


