# ============================================================
# AGENT FACTORY
# ============================================================

class AgentFactory:

    @staticmethod
    def create(
        agent_type: AgentType,
        *,
        tenant_id: str,
        name: Optional[str] = None,
        version: str = "1.0",
    ) -> BaseCyberAgent:

        if not tenant_id:
            raise AgentValidationError(
                "tenant_id is required"
            )

        agent_class = AGENT_CLASSES.get(
            agent_type
        )

        if agent_class is None:
            raise AgentValidationError(
                f"No agent implementation for "
                f"{agent_type.value}"
            )

        policy = AGENT_POLICIES[
            agent_type
        ]

        identity = AgentIdentity(
            agent_id=(
                f"agent-{uuid.uuid4().hex}"
            ),
            tenant_id=tenant_id,
            agent_type=agent_type,
            name=(
                name
                or f"{agent_type.value}-agent"
            ),
            version=version,
        )

        return agent_class(
            identity,
            policy,
        )


# ============================================================
# AGENT REGISTRY
# ============================================================

class AgentRegistry:

    def __init__(self) -> None:

        self._agents: dict[
            str,
            BaseCyberAgent,
        ] = {}

    def register(
        self,
        agent: BaseCyberAgent,
    ) -> None:

        if agent.agent_id in self._agents:
            raise AgentValidationError(
                "Agent already registered."
            )

        self._agents[
            agent.agent_id
        ] = agent

    def get(
        self,
        agent_id: str,
        *,
        tenant_id: str,
    ) -> BaseCyberAgent:

        agent = self._agents.get(
            agent_id
        )

        if agent is None:
            raise AgentValidationError(
                "Agent not found."
            )

        if agent.tenant_id != tenant_id:
            raise AgentTenantError(
                "Cross-tenant agent access denied."
            )

        return agent

    def list_for_tenant(
        self,
        tenant_id: str,
    ) -> list[BaseCyberAgent]:

        return [
            agent
            for agent
            in self._agents.values()
            if agent.tenant_id == tenant_id
        ]

    def remove(
        self,
        agent_id: str,
        *,
        tenant_id: str,
    ) -> None:

        agent = self.get(
            agent_id,
            tenant_id=tenant_id,
        )

        del self._agents[
            agent.agent_id
        ]


# ============================================================
# AGENT AUDIT CONTEXT
# ============================================================

class AgentAuditContext:

    def __init__(self) -> None:
        self.records: list[
            AgentAuditRecord
        ] = []

    def record(
        self,
        *,
        agent: BaseCyberAgent,
        event_type: str,
        details: Optional[
            Mapping[str, Any]
        ] = None,
    ) -> AgentAuditRecord:

        record = AgentAuditRecord(
            event_id=(
                f"audit-{uuid.uuid4().hex}"
            ),
            tenant_id=agent.tenant_id,
            agent_id=agent.agent_id,
            event_type=event_type,
            timestamp=time.time(),
            details=dict(
                details or {}
            ),
        )

        self.records.append(
            record
        )

        return record

    def list_for_tenant(
        self,
        tenant_id: str,
    ) -> list[AgentAuditRecord]:

        return [
            record
            for record
            in self.records
            if record.tenant_id == tenant_id
        ]


