# ============================================================
# TEST HELPERS
# ============================================================

def _assert_raises(
    expected: type[Exception],
    function: Callable[[], Any],
) -> None:

    try:
        function()

    except expected:
        return

    except Exception as exc:
        raise AssertionError(
            f"Expected {expected.__name__}, "
            f"got {type(exc).__name__}"
        ) from exc

    raise AssertionError(
        f"Expected {expected.__name__} "
        "but no exception was raised."
    )


