def test_agent_factory() -> None:

    agent = AgentFactory.create(
        AgentType.DETECTION,
        tenant_id="tenant-a",
    )

    assert agent.agent_type is (
        AgentType.DETECTION
    )

    assert agent.tenant_id == "tenant-a"


