# ============================================================
# TEST 3 — LIFECYCLE
# ============================================================

def test_agent_lifecycle() -> None:

    agent = AgentFactory.create(
        AgentType.DETECTION,
        tenant_id="tenant-a",
    )

    agent.initialize()

    assert (
        agent.state
        is AgentState.READY
    )

    agent.start()

    assert (
        agent.state
        is AgentState.RUNNING
    )

    agent.pause()

    assert (
        agent.state
        is AgentState.PAUSED
    )


