def test_action_boundary() -> None:

    agent = AgentFactory.create(
        AgentType.RESPONSE_PLANNER,
        tenant_id="tenant-a",
    )

    agent.initialize()

    request = AgentActionRequest(
        action_id="action-1",
        tenant_id="tenant-a",
        agent_id=agent.agent_id,
        action_type="propose",
        risk_level="medium",
    )

    result = agent.validate_action(
        request
    )

    assert result.accepted
    assert result.fingerprint


