# ============================================================
# TEST 9 — TENANT ISOLATION
# ============================================================

def _legacy_test_tenant_isolation_1() -> None:

    registry = AgentRegistry()

    agent_a = AgentFactory.create(
        AgentType.DETECTION,
        tenant_id="tenant-a",
    )

    agent_b = AgentFactory.create(
        AgentType.DETECTION,
        tenant_id="tenant-b",
    )

    registry.register(
        agent_a
    )

    registry.register(
        agent_b
    )

    tenant_a_agents = (
        registry.list_for_tenant(
            "tenant-a"
        )
    )

    assert len(
        tenant_a_agents
    ) == 1

    assert (
        tenant_a_agents[0].tenant_id
        == "tenant-a"
    )

    _assert_raises(
        AgentTenantError,
        lambda:
            registry.get(
                agent_a.agent_id,
                tenant_id="tenant-b",
            ),
    )


