# ============================================================
# TEST 11 — AUDIT TENANT SCOPE
# ============================================================

def test_audit_tenant_scope() -> None:

    audit = AgentAuditContext()

    agent_a = AgentFactory.create(
        AgentType.DETECTION,
        tenant_id="tenant-a",
    )

    agent_b = AgentFactory.create(
        AgentType.RISK,
        tenant_id="tenant-b",
    )

    audit.record(
        agent=agent_a,
        event_type="agent_started",
    )

    audit.record(
        agent=agent_b,
        event_type="agent_started",
    )

    records = audit.list_for_tenant(
        "tenant-a"
    )

    assert len(records) == 1

    assert (
        records[0].tenant_id
        == "tenant-a"
    )

    assert records[0].digest()


# ============================================================
# TEST 12 — ACTION BINDING
# ============================================================

def test_action_binding() -> None:

    agent = AgentFactory.create(
        AgentType.RESPONSE_PLANNER,
        tenant_id="tenant-a",
    )

    request_a = AgentActionRequest(
        action_id="same-id",
        tenant_id="tenant-a",
        agent_id=agent.agent_id,
        action_type="propose",
        risk_level="low",
        parameters={
            "target": "endpoint-1"
        },
    )

    request_b = AgentActionRequest(
        action_id="same-id",
        tenant_id="tenant-a",
        agent_id=agent.agent_id,
        action_type="propose",
        risk_level="low",
        parameters={
            "target": "endpoint-2"
        },
    )

    assert (
        request_a.fingerprint()
        != request_b.fingerprint()
    )


