# ============================================================
# TEST 14 — TOOL LIMIT
# ============================================================

def test_tool_limit() -> None:

    policy = AgentPolicy(
        allowed_capabilities=frozenset({
            AgentCapability.DETECT
        }),
        allowed_permissions=frozenset({
            AgentPermission.DETECT
        }),
        limits=AgentLimits(
            max_tool_calls_per_run=1
        ),
    )

    identity = AgentIdentity(
        agent_id="agent-limit",
        tenant_id="tenant-a",
        agent_type=AgentType.DETECTION,
        name="limit-agent",
    )

    agent = DetectionAgent(
        identity,
        policy,
    )

    agent.initialize()

    agent.register_tool(
        RegisteredTool(
            name="limited",
            capability=AgentCapability.DETECT,
            handler=lambda **kwargs: "ok",
        )
    )

    agent.invoke_tool(
        "limited",
        tenant_id="tenant-a",
    )

    _assert_raises(
        AgentLimitError,
        lambda:
            agent.invoke_tool(
                "limited",
                tenant_id="tenant-a",
            ),
    )


# ============================================================
# PHASE 12 TEST RUNNER
# ============================================================

def run_phase12_tests() -> dict[str, Any]:

    tests = [
        test_agent_factory,
        test_all_standard_agents,
        test_agent_lifecycle,
        test_capability_boundary,
        test_tool_capability_enforcement,
        test_unauthorized_tool,
        test_action_boundary,
        test_high_risk_denial,
        test_tenant_isolation,
        test_execution_boundary,
        test_audit_tenant_scope,
        test_action_binding,
        test_disabled_agent,
        test_tool_limit,
    ]

    started = time.perf_counter()

    passed = 0
    failures: list[
        dict[str, str]
    ] = []

    for test in tests:

        try:
            test()
            passed += 1

        except Exception as exc:

            failures.append(
                {
                    "test":
                        test.__name__,
                    "error":
                        (
                            f"{type(exc).__name__}: "
                            f"{exc}"
                        ),
                }
            )

    elapsed_ms = (
        time.perf_counter()
        - started
    ) * 1000.0

    return {
        "phase": PHASE,
        "product": PRODUCT,
        "component": "Cyber Agent System",
        "tests_total": len(tests),
        "tests_passed": passed,
        "tests_failed": len(failures),
        "status": (
            "PASS"
            if not failures
            else "FAIL"
        ),
        "failures": failures,
        "elapsed_ms": round(
            elapsed_ms,
            3,
        ),
    }


