def test_expired_approval_denied() -> None:

    current_time = [
        1000.0
    ]

    engine = CyberGovernanceEngine(
        clock=lambda:
            current_time[0]
    )

    request = _request(
        "disable_account",
        ActionLevel.HIGH_RISK_HUMAN_APPROVAL,
    )

    decision = engine.evaluate(
        request
    )

    approval = (
        engine.create_required_approval(
            request,
            decision,
            approvers=(
                "human-1",
            ),
            ttl_seconds=10,
        )
    )

    current_time[0] = 1011.0

    try:

        engine.approve(
            request,
            approval.approval_id,
            "human-1",
        )

    except PermissionError:

        pass

    else:

        raise AssertionError(
            "Expired approval accepted."
        )

    _assert(
        not engine.authorize_execution(
            request,
            decision,
            approval_id=(
                approval.approval_id
            ),
        )
    )




