class KnowledgeType(str, Enum):
    FACT = "FACT"
    EVIDENCE = "EVIDENCE"
    INFERENCE = "INFERENCE"
    PREDICTION = "PREDICTION"
    RECOMMENDATION = "RECOMMENDATION"
    DECISION = "DECISION"
    ACTION = "ACTION"
    EXECUTION = "EXECUTION"
    VERIFICATION = "VERIFICATION"
    OUTCOME = "OUTCOME"




class MemoryConflictStatus(str, Enum):
    NONE = "NONE"
    CONFLICT = "CONFLICT"


# ============================================================================
