class Phase18Error(Exception):
    """Base exception for Phase 18."""








class MemoryIntegrityError(Phase18Error):
    """Raised when a stored memory fingerprint does not match its content."""


class LearningBoundaryError(Phase18Error):
    """Raised when learning is attempted from an invalid verification state."""




# ============================================================================
# PHASE 18 — HELPERS
# ============================================================================


def _utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _validate_non_empty(value: str, field_name: str) -> None:
    if not isinstance(value, str) or not value.strip():
        raise MemoryValidationError(f"{field_name} must be a non-empty string")


def _validate_confidence(value: float, field_name: str = "confidence") -> None:
    if not isinstance(value, (int, float)):
        raise MemoryValidationError(f"{field_name} must be numeric")

    if not 0.0 <= float(value) <= 1.0:
        raise MemoryValidationError(
            f"{field_name} must be between 0.0 and 1.0"
        )


def _canonicalize(value: Any) -> Any:
    """
    Convert supported Python values into deterministic JSON-compatible data.

    This is deliberately used for fingerprints only. It does not replace
    the original memory content.
    """
    if isinstance(value, Enum):
        return value.value

    if isinstance(value, Mapping):
        return {
            str(key): _canonicalize(value[key])
            for key in sorted(value, key=lambda item: str(item))
        }

    if isinstance(value, (list, tuple)):
        return [_canonicalize(item) for item in value]

    if isinstance(value, set):
        normalized = [_canonicalize(item) for item in value]
        return sorted(normalized, key=lambda item: repr(item))

    if isinstance(value, datetime):
        return value.isoformat()

    if value is None or isinstance(value, (str, int, float, bool)):
        return value

    return repr(value)


def _canonical_json(value: Any) -> str:
    return json.dumps(
        _canonicalize(value),
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
    )


def _immutable_mapping(value: Optional[Mapping[str, Any]]) -> Mapping[str, Any]:
    if value is None:
        return MappingProxyType({})

    return MappingProxyType(
        {
            str(key): value_item
            for key, value_item in value.items()
        }
    )


# ============================================================================
# PHASE 18 — PROVENANCE
# ============================================================================


@dataclass(frozen=True)
class MemoryProvenance:
    """
    Records where a memory came from.

    A memory without provenance cannot be treated as equally trustworthy
    to an evidence-backed memory.
    """

    source: str
    source_type: str
    observed_at: str
    confidence: float
    evidence_ids: Tuple[str, ...] = ()
    reference: Optional[str] = None
    metadata: Mapping[str, Any] = field(
        default_factory=lambda: MappingProxyType({})
    )

    def __post_init__(self) -> None:
        _validate_non_empty(self.source, "source")
        _validate_non_empty(self.source_type, "source_type")
        _validate_non_empty(self.observed_at, "observed_at")
        _validate_confidence(self.confidence)

        for evidence_id in self.evidence_ids:
            _validate_non_empty(evidence_id, "evidence_id")

        object.__setattr__(
            self,
            "metadata",
            _immutable_mapping(self.metadata),
        )


