@dataclass(frozen=True)
class MemoryQuery:
    tenant_id: str
    memory_type: Optional[MemoryType] = None
    subject_id: Optional[str] = None
    verification_id: Optional[str] = None
    knowledge_type: Optional[KnowledgeType] = None
    limit: int = 100

    def __post_init__(self) -> None:
        _validate_non_empty(self.tenant_id, "tenant_id")

        if self.subject_id is not None:
            _validate_non_empty(self.subject_id, "subject_id")

        if self.verification_id is not None:
            _validate_non_empty(self.verification_id, "verification_id")

        if self.limit < 1:
            raise MemoryValidationError("limit must be >= 1")


# ============================================================================
# PHASE 18 — PHASE 17 CONSUMPTION CONTRACT
# ============================================================================


class VerificationResultPort(Protocol):
    """
    Structural boundary for Phase 17 CyberVerificationResult.

    Phase 18 consumes the Phase 17 result. It does not recreate or replace
    the Phase 17 verification engine.
    """

    verification_id: str
    tenant_id: str
    action_id: str
    target_id: str
    status: Any
    confidence: float
    evidence: Sequence[Any]
    verified_at: str
    state_fingerprint: str
    verification_complete: bool
    actual_state_confirmed: bool
    threat_state_confirmed: bool
    collateral_impact_checked: bool


# ============================================================================
# PHASE 18 — MEMORY FINGERPRINT
# ============================================================================


class MemoryFingerprint:
    """Generates and validates deterministic memory integrity fingerprints."""

    @staticmethod
    def generate(
        *,
        memory_id: str,
        tenant_id: str,
        memory_type: MemoryType,
        knowledge_type: KnowledgeType,
        subject_id: str,
        content: Mapping[str, Any],
        provenance: MemoryProvenance,
        created_at: str,
        valid_at: str,
        supersedes_memory_id: Optional[str],
        verification_id: Optional[str],
        metadata: Mapping[str, Any],
    ) -> str:

        canonical = {
            "memory_id": memory_id,
            "tenant_id": tenant_id,
            "memory_type": memory_type.value,
            "knowledge_type": knowledge_type.value,
            "subject_id": subject_id,
            "content": content,
            "provenance": {
                "source": provenance.source,
                "source_type": provenance.source_type,
                "observed_at": provenance.observed_at,
                "confidence": provenance.confidence,
                "evidence_ids": provenance.evidence_ids,
                "reference": provenance.reference,
                "metadata": provenance.metadata,
            },
            "created_at": created_at,
            "valid_at": valid_at,
            "supersedes_memory_id": supersedes_memory_id,
            "verification_id": verification_id,
            "metadata": metadata,
        }

        return sha256(
            _canonical_json(canonical).encode("utf-8")
        ).hexdigest()

    @classmethod
    def for_record(cls, record: CyberMemoryRecord) -> str:
        return cls.generate(
            memory_id=record.memory_id,
            tenant_id=record.tenant_id,
            memory_type=record.memory_type,
            knowledge_type=record.knowledge_type,
            subject_id=record.subject_id,
            content=record.content,
            provenance=record.provenance,
            created_at=record.created_at,
            valid_at=record.valid_at,
            supersedes_memory_id=record.supersedes_memory_id,
            verification_id=record.verification_id,
            metadata=record.metadata,
        )

    @classmethod
    def verify(cls, record: CyberMemoryRecord) -> bool:
        expected = cls.for_record(record)
        return expected == record.fingerprint


# ============================================================================
# PHASE 18 — REPOSITORY CONTRACT
# ============================================================================


class MemoryRepository(Protocol):
    def save(self, record: CyberMemoryRecord) -> None:
        ...

    def get(self, tenant_id: str, memory_id: str) -> CyberMemoryRecord:
        ...

    def query(self, query: MemoryQuery) -> Tuple[CyberMemoryRecord, ...]:
        ...

    def all_for_tenant(self, tenant_id: str) -> Tuple[CyberMemoryRecord, ...]:
        ...


# ============================================================================
# PHASE 18 — IN-MEMORY REPOSITORY
# ============================================================================


class InMemorySecurityMemoryRepository:
    """
    Reference repository for Phase 18.

    This intentionally does NOT claim database persistence. It gives the
    memory layer a real repository boundary and deterministic test backend.
    """

    def __init__(self) -> None:
        self._records: dict[str, CyberMemoryRecord] = {}

    def save(self, record: CyberMemoryRecord) -> None:
        existing = self._records.get(record.memory_id)

        if existing is not None:
            if existing.fingerprint == record.fingerprint:
                raise DuplicateMemoryError(
                    f"Memory already exists: {record.memory_id}"
                )

            raise DuplicateMemoryError(
                f"Memory ID collision: {record.memory_id}"
            )

        if not MemoryFingerprint.verify(record):
            raise MemoryIntegrityError(
                f"Invalid memory fingerprint: {record.memory_id}"
            )

        self._records[record.memory_id] = record

    def get(
        self,
        tenant_id: str,
        memory_id: str,
    ) -> CyberMemoryRecord:

        _validate_non_empty(tenant_id, "tenant_id")
        _validate_non_empty(memory_id, "memory_id")

        record = self._records.get(memory_id)

        if record is None:
            raise MemoryNotFoundError(memory_id)

        if record.tenant_id != tenant_id:
            raise TenantIsolationError(
                f"Memory {memory_id} does not belong to tenant {tenant_id}"
            )

        if not MemoryFingerprint.verify(record):
            raise MemoryIntegrityError(memory_id)

        return record

    def query(
        self,
        query: MemoryQuery,
    ) -> Tuple[CyberMemoryRecord, ...]:

        matches: list[CyberMemoryRecord] = []

        for record in self._records.values():

            if record.tenant_id != query.tenant_id:
                continue

            if (
                query.memory_type is not None
                and record.memory_type != query.memory_type
            ):
                continue

            if (
                query.subject_id is not None
                and record.subject_id != query.subject_id
            ):
                continue

            if (
                query.verification_id is not None
                and record.verification_id != query.verification_id
            ):
                continue

            if (
                query.knowledge_type is not None
                and record.knowledge_type != query.knowledge_type
            ):
                continue

            matches.append(record)

        matches.sort(
            key=lambda record: record.valid_at,
            reverse=True,
        )

        return tuple(matches[: query.limit])

    def all_for_tenant(
        self,
        tenant_id: str,
    ) -> Tuple[CyberMemoryRecord, ...]:

        return self.query(
            MemoryQuery(
                tenant_id=tenant_id,
                limit=max(len(self._records), 1),
            )
        )


# ============================================================================
# PHASE 18 — MEMORY ENGINE
# ============================================================================


class SecurityMemoryEngine:
    """
    Main Phase 18 memory service.

    Responsibilities:
        write
        retrieve
        verify integrity
        preserve provenance
        enforce tenant boundaries
    """

    def __init__(self, repository: MemoryRepository) -> None:
        self._repository = repository

    def create_memory(
        self,
        *,
        tenant_id: str,
        memory_type: MemoryType,
        knowledge_type: KnowledgeType,
        subject_id: str,
        content: Mapping[str, Any],
        provenance: MemoryProvenance,
        valid_at: Optional[str] = None,
        supersedes_memory_id: Optional[str] = None,
        verification_id: Optional[str] = None,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> CyberMemoryRecord:

        created_at = _utc_now()
        effective_valid_at = valid_at or created_at
        effective_metadata = _immutable_mapping(metadata)

        memory_id = str(uuid4())

        fingerprint = MemoryFingerprint.generate(
            memory_id=memory_id,
            tenant_id=tenant_id,
            memory_type=memory_type,
            knowledge_type=knowledge_type,
            subject_id=subject_id,
            content=content,
            provenance=provenance,
            created_at=created_at,
            valid_at=effective_valid_at,
            supersedes_memory_id=supersedes_memory_id,
            verification_id=verification_id,
            metadata=effective_metadata,
        )

        record = CyberMemoryRecord(
            memory_id=memory_id,
            tenant_id=tenant_id,
            memory_type=memory_type,
            knowledge_type=knowledge_type,
            subject_id=subject_id,
            content=content,
            provenance=provenance,
            created_at=created_at,
            valid_at=effective_valid_at,
            supersedes_memory_id=supersedes_memory_id,
            verification_id=verification_id,
            fingerprint=fingerprint,
            metadata=effective_metadata,
        )

        self._repository.save(record)
        return record

    def get(
        self,
        *,
        tenant_id: str,
        memory_id: str,
    ) -> CyberMemoryRecord:

        return self._repository.get(
            tenant_id=tenant_id,
            memory_id=memory_id,
        )

    def query(
        self,
        query: MemoryQuery,
    ) -> Tuple[CyberMemoryRecord, ...]:

        records = self._repository.query(query)

        for record in records:
            if not MemoryFingerprint.verify(record):
                raise MemoryIntegrityError(record.memory_id)

        return records

    def verify_integrity(
        self,
        *,
        tenant_id: str,
        memory_id: str,
    ) -> bool:

        record = self.get(
            tenant_id=tenant_id,
            memory_id=memory_id,
        )

        if not MemoryFingerprint.verify(record):
            raise MemoryIntegrityError(memory_id)

        return True

    def find_by_verification(
        self,
        *,
        tenant_id: str,
        verification_id: str,
    ) -> Tuple[CyberMemoryRecord, ...]:

        return self.query(
            MemoryQuery(
                tenant_id=tenant_id,
                verification_id=verification_id,
            )
        )


# ============================================================================
# PHASE 18 — CONTRADICTION DETECTOR
# ============================================================================


@dataclass(frozen=True)
class MemoryConflict:
    tenant_id: str
    subject_id: str
    memory_type: MemoryType
    knowledge_type: KnowledgeType
    existing_memory_id: str
    incoming_content: Mapping[str, Any]
    existing_content: Mapping[str, Any]
    detected_at: str


class MemoryConflictDetector:
    """
    Detects contradictory memories without deleting or mutating historical
    records.

    The detector intentionally does not decide which fact is true.
    """

    @staticmethod
    def detect(
        *,
        existing: Iterable[CyberMemoryRecord],
        incoming: CyberMemoryRecord,
    ) -> Optional[MemoryConflict]:

        for record in existing:

            if record.tenant_id != incoming.tenant_id:
                continue

            if record.subject_id != incoming.subject_id:
                continue

            if record.memory_type != incoming.memory_type:
                continue

            if record.knowledge_type != incoming.knowledge_type:
                continue

            if record.content == incoming.content:
                continue

            return MemoryConflict(
                tenant_id=incoming.tenant_id,
                subject_id=incoming.subject_id,
                memory_type=incoming.memory_type,
                knowledge_type=incoming.knowledge_type,
                existing_memory_id=record.memory_id,
                incoming_content=incoming.content,
                existing_content=record.content,
                detected_at=_utc_now(),
            )

        return None


# ============================================================================
# PHASE 18 — VERIFICATION EVIDENCE EXTRACTION
# ============================================================================


class VerificationEvidenceExtractor:
    """
    Converts Phase 17 evidence objects into memory-safe structured data.

    No Phase 17 class is recreated here.
    """

    @staticmethod
    def extract(evidence: Sequence[Any]) -> Tuple[Mapping[str, Any], ...]:
        extracted: list[Mapping[str, Any]] = []

        for item in evidence:
            extracted.append(
                {
                    "evidence_id": getattr(item, "evidence_id", None),
                    "dimension": getattr(
                        getattr(item, "dimension", None),
                        "value",
                        str(getattr(item, "dimension", "")),
                    ),
                    "source": getattr(
                        getattr(item, "source", None),
                        "value",
                        str(getattr(item, "source", "")),
                    ),
                    "description": getattr(item, "description", ""),
                    "observed_value": getattr(
                        item,
                        "observed_value",
                        None,
                    ),
                    "expected_value": getattr(
                        item,
                        "expected_value",
                        None,
                    ),
                    "reliable": bool(
                        getattr(item, "reliable", False)
                    ),
                    "timestamp": getattr(
                        item,
                        "timestamp",
                        None,
                    ),
                }
            )

        return tuple(extracted)


# ============================================================================
# PHASE 18 — VERIFIED OUTCOME LEARNER
# ============================================================================


class VerifiedOutcomeLearner:
    """
    Converts Phase 17 verification outcomes into durable Phase 18 memory.

    Critical boundary:

        VERIFIED + verification_complete=True
            -> eligible for accepted learning

        PARTIALLY_VERIFIED / FAILED / INCONCLUSIVE
            -> outcome may be recorded
            -> positive learning is NOT accepted
    """

    def __init__(
        self,
        memory_engine: SecurityMemoryEngine,
    ) -> None:
        self._memory = memory_engine

    @staticmethod
    def _status_value(result: VerificationResultPort) -> str:
        status = result.status
        return str(getattr(status, "value", status)).upper()

    def record_verification_outcome(
        self,
        result: VerificationResultPort,
    ) -> tuple[CyberMemoryRecord, LearningObservation]:

        _validate_non_empty(result.tenant_id, "tenant_id")
        _validate_non_empty(
            result.verification_id,
            "verification_id",
        )
        _validate_non_empty(result.action_id, "action_id")
        _validate_non_empty(result.target_id, "target_id")

        _validate_confidence(
            float(result.confidence),
            "verification confidence",
        )

        status = self._status_value(result)

        evidence = VerificationEvidenceExtractor.extract(
            result.evidence
        )

        outcome_content = {
            "verification_id": result.verification_id,
            "action_id": result.action_id,
            "target_id": result.target_id,
            "verification_status": status,
            "verification_complete": bool(
                result.verification_complete
            ),
            "actual_state_confirmed": bool(
                result.actual_state_confirmed
            ),
            "threat_state_confirmed": bool(
                result.threat_state_confirmed
            ),
            "collateral_impact_checked": bool(
                result.collateral_impact_checked
            ),
            "verification_confidence": float(result.confidence),
            "state_fingerprint": result.state_fingerprint,
            "evidence": evidence,
        }

        provenance = MemoryProvenance(
            source="PHASE_17_SECURITY_VERIFICATION",
            source_type="VERIFICATION_ENGINE",
            observed_at=result.verified_at,
            confidence=float(result.confidence),
            evidence_ids=tuple(
                item.get("evidence_id")
                for item in evidence
                if item.get("evidence_id")
            ),
            reference=result.verification_id,
        )

        outcome_memory = self._memory.create_memory(
            tenant_id=result.tenant_id,
            memory_type=MemoryType.OUTCOME,
            knowledge_type=KnowledgeType.OUTCOME,
            subject_id=result.target_id,
            content=outcome_content,
            provenance=provenance,
            valid_at=result.verified_at,
            verification_id=result.verification_id,
            metadata={
                "action_id": result.action_id,
                "phase": 18,
                "source_phase": 17,
            },
        )

        if (
            status == "VERIFIED"
            and bool(result.verification_complete)
        ):
            learning_status = LearningStatus.ACCEPTED

            lesson = (
                "The executed security action produced an outcome "
                "that passed the Phase 17 verification boundary."
            )

        elif status == "FAILED":
            learning_status = LearningStatus.REJECTED

            lesson = (
                "The security action failed verification and must not "
                "be learned as a successful outcome."
            )

        else:
            learning_status = LearningStatus.INCONCLUSIVE

            lesson = (
                "The security action did not establish a fully verified "
                "outcome; future learning must treat this result as "
                "inconclusive."
            )

        learning = LearningObservation(
            learning_id=str(uuid4()),
            tenant_id=result.tenant_id,
            source_memory_ids=(outcome_memory.memory_id,),
            verification_id=result.verification_id,
            outcome=status,
            lesson=lesson,
            confidence=float(result.confidence),
            status=learning_status,
            created_at=_utc_now(),
            metadata={
                "verification_complete": bool(
                    result.verification_complete
                ),
                "state_fingerprint": result.state_fingerprint,
            },
        )

        return outcome_memory, learning


# ============================================================================
# PHASE 18 — LEARNING BOUNDARY
# ============================================================================


class LearningBoundary:
    """
    Final defensive boundary before an outcome is considered accepted
    learning.
    """

    @staticmethod
    def assert_accepted_learning(
        result: VerificationResultPort,
    ) -> None:

        status = str(
            getattr(result.status, "value", result.status)
        ).upper()

        if status != "VERIFIED":
            raise LearningBoundaryError(
                "Only VERIFIED verification results may produce "
                "accepted learning"
            )

        if not result.verification_complete:
            raise LearningBoundaryError(
                "Verification must be complete before accepted learning"
            )

        if not result.actual_state_confirmed:
            raise LearningBoundaryError(
                "Actual state must be confirmed before accepted learning"
            )


# ============================================================================
# PHASE 18 — MEMORY FACTORY
# ============================================================================


class SecurityMemoryFactory:
    """
    Convenience factory for creating correctly classified memory records.
    """

    def __init__(self, engine: SecurityMemoryEngine) -> None:
        self._engine = engine

    def event(
        self,
        *,
        tenant_id: str,
        subject_id: str,
        content: Mapping[str, Any],
        provenance: MemoryProvenance,
    ) -> CyberMemoryRecord:

        return self._engine.create_memory(
            tenant_id=tenant_id,
            memory_type=MemoryType.EVENT,
            knowledge_type=KnowledgeType.FACT,
            subject_id=subject_id,
            content=content,
            provenance=provenance,
        )

    def evidence(
        self,
        *,
        tenant_id: str,
        subject_id: str,
        content: Mapping[str, Any],
        provenance: MemoryProvenance,
    ) -> CyberMemoryRecord:

        return self._engine.create_memory(
            tenant_id=tenant_id,
            memory_type=MemoryType.EVIDENCE,
            knowledge_type=KnowledgeType.EVIDENCE,
            subject_id=subject_id,
            content=content,
            provenance=provenance,
        )

    def decision(
        self,
        *,
        tenant_id: str,
        subject_id: str,
        content: Mapping[str, Any],
        provenance: MemoryProvenance,
    ) -> CyberMemoryRecord:

        return self._engine.create_memory(
            tenant_id=tenant_id,
            memory_type=MemoryType.DECISION,
            knowledge_type=KnowledgeType.DECISION,
            subject_id=subject_id,
            content=content,
            provenance=provenance,
        )

    def action(
        self,
        *,
        tenant_id: str,
        subject_id: str,
        content: Mapping[str, Any],
        provenance: MemoryProvenance,
    ) -> CyberMemoryRecord:

        return self._engine.create_memory(
            tenant_id=tenant_id,
            memory_type=MemoryType.ACTION,
            knowledge_type=KnowledgeType.ACTION,
            subject_id=subject_id,
            content=content,
            provenance=provenance,
        )


# ============================================================================
# PHASE 18 — TEST FIXTURES
# ============================================================================


class _FakeStatus(str, Enum):
    VERIFIED = "VERIFIED"
    PARTIALLY_VERIFIED = "PARTIALLY_VERIFIED"
    FAILED = "FAILED"
    INCONCLUSIVE = "INCONCLUSIVE"


@dataclass(frozen=True)
class _FakeEvidence:
    evidence_id: str
    dimension: str
    source: str
    description: str
    observed_value: Any
    expected_value: Any
    reliable: bool
    timestamp: str


@dataclass(frozen=True)
class _FakeVerificationResult:
    verification_id: str
    tenant_id: str
    action_id: str
    target_id: str
    status: _FakeStatus
    confidence: float
    evidence: Sequence[_FakeEvidence]
    verified_at: str
    state_fingerprint: str
    verification_complete: bool
    actual_state_confirmed: bool
    threat_state_confirmed: bool
    collateral_impact_checked: bool


def _fixture_provenance(
    tenant_id: str = "tenant-a",
) -> MemoryProvenance:

    return MemoryProvenance(
        source="test-source",
        source_type="TEST",
        observed_at=_utc_now(),
        confidence=0.95,
        evidence_ids=("evidence-1",),
        reference=f"ref-{tenant_id}",
    )


def _fixture_result(
    *,
    tenant_id: str = "tenant-a",
    status: _FakeStatus = _FakeStatus.VERIFIED,
    complete: bool = True,
    actual_state_confirmed: bool = True,
) -> _FakeVerificationResult:

    now = _utc_now()

    return _FakeVerificationResult(
        verification_id=str(uuid4()),
        tenant_id=tenant_id,
        action_id="action-001",
        target_id="endpoint-001",
        status=status,
        confidence=0.94,
        evidence=(
            _FakeEvidence(
                evidence_id="evidence-001",
                dimension="TARGET_STATE",
                source="EDR",
                description="Endpoint state confirmed",
                observed_value={"isolation": True},
                expected_value={"isolation": True},
                reliable=True,
                timestamp=now,
            ),
        ),
        verified_at=now,
        state_fingerprint="state-fingerprint-001",
        verification_complete=complete,
        actual_state_confirmed=actual_state_confirmed,
        threat_state_confirmed=True,
        collateral_impact_checked=True,
    )


