def test_provenance_validation() -> None:
    provenance = _fixture_provenance()

    assert provenance.source == "test-source"
    assert provenance.confidence == 0.95
    assert provenance.evidence_ids == ("evidence-1",)


def test_invalid_confidence_rejected() -> None:
    try:
        MemoryProvenance(
            source="source",
            source_type="TEST",
            observed_at=_utc_now(),
            confidence=1.5,
        )
    except MemoryValidationError:
        return

    raise AssertionError("Invalid confidence was accepted")


def test_memory_fingerprint_is_deterministic() -> None:
    provenance = _fixture_provenance()

    first = MemoryFingerprint.generate(
        memory_id="m1",
        tenant_id="t1",
        memory_type=MemoryType.EVENT,
        knowledge_type=KnowledgeType.FACT,
        subject_id="asset1",
        content={"b": 2, "a": 1},
        provenance=provenance,
        created_at="2026-01-01T00:00:00+00:00",
        valid_at="2026-01-01T00:00:00+00:00",
        supersedes_memory_id=None,
        verification_id=None,
        metadata={"x": 1},
    )

    second = MemoryFingerprint.generate(
        memory_id="m1",
        tenant_id="t1",
        memory_type=MemoryType.EVENT,
        knowledge_type=KnowledgeType.FACT,
        subject_id="asset1",
        content={"a": 1, "b": 2},
        provenance=provenance,
        created_at="2026-01-01T00:00:00+00:00",
        valid_at="2026-01-01T00:00:00+00:00",
        supersedes_memory_id=None,
        verification_id=None,
        metadata={"x": 1},
    )

    assert first == second


def test_create_and_retrieve_memory() -> None:
    repository = InMemorySecurityMemoryRepository()
    engine = SecurityMemoryEngine(repository)

    record = engine.create_memory(
        tenant_id="tenant-a",
        memory_type=MemoryType.EVENT,
        knowledge_type=KnowledgeType.FACT,
        subject_id="asset-a",
        content={"event": "login"},
        provenance=_fixture_provenance(),
    )

    retrieved = engine.get(
        tenant_id="tenant-a",
        memory_id=record.memory_id,
    )

    assert retrieved.memory_id == record.memory_id
    assert retrieved.content["event"] == "login"
    assert engine.verify_integrity(
        tenant_id="tenant-a",
        memory_id=record.memory_id,
    )




def test_query_is_tenant_scoped() -> None:
    repository = InMemorySecurityMemoryRepository()
    engine = SecurityMemoryEngine(repository)

    engine.create_memory(
        tenant_id="tenant-a",
        memory_type=MemoryType.EVENT,
        knowledge_type=KnowledgeType.FACT,
        subject_id="asset-a",
        content={"tenant": "a"},
        provenance=_fixture_provenance("tenant-a"),
    )

    engine.create_memory(
        tenant_id="tenant-b",
        memory_type=MemoryType.EVENT,
        knowledge_type=KnowledgeType.FACT,
        subject_id="asset-b",
        content={"tenant": "b"},
        provenance=_fixture_provenance("tenant-b"),
    )

    results = engine.query(
        MemoryQuery(tenant_id="tenant-a")
    )

    assert len(results) == 1
    assert results[0].tenant_id == "tenant-a"


def test_verification_memory_created_from_phase17_result() -> None:
    repository = InMemorySecurityMemoryRepository()
