# ============================================================================
# TIME / VALIDATION
# ============================================================================



def ensure_aware(value: datetime, field_name: str) -> datetime:
    if value.tzinfo is None or value.utcoffset() is None:
        raise Phase19ValidationError(
            f"{field_name} must be timezone-aware"
        )
    return value.astimezone(timezone.utc)




# ============================================================================
# ERRORS
# ============================================================================

class Phase19Error(Exception):
    """Base Phase 19 exception."""


class Phase19ValidationError(Phase19Error):
    """Invalid Phase 19 data."""




class SafetyBoundaryError(Phase19Error):
    """A safety boundary was violated."""


class ApprovalError(Phase19Error):
    """Approval operation failed."""


class KillSwitchActiveError(Phase19Error):
    """Tenant/action is blocked by a kill switch."""


class EmergencyStopActiveError(Phase19Error):
    """Global emergency stop is active."""


class AuthorizationDeniedError(Phase19Error):
    """Requested autonomous operation is denied."""




class ExpiredApprovalError(Phase19Error):
    """Approval has expired."""


# ============================================================================
# AUTONOMY
# ============================================================================

class AutonomyLevel(str, Enum):
    """
    Ordered operational autonomy.

    OBSERVE:
        No autonomous action.

    RECOMMEND:
        System may produce recommendations only.

    APPROVAL_REQUIRED:
        System may prepare an action, but human approval is mandatory.

    LIMITED_AUTONOMY:
        Explicitly classified low-risk actions may proceed automatically.

    FULL_AUTONOMY:
        Allowed action classes may proceed automatically.

    EMERGENCY_ONLY:
        Normal autonomous actions are suspended.
    """

    OBSERVE = "observe"
    RECOMMEND = "recommend"
    APPROVAL_REQUIRED = "approval_required"
    LIMITED_AUTONOMY = "limited_autonomy"
    FULL_AUTONOMY = "full_autonomy"
    EMERGENCY_ONLY = "emergency_only"


_AUTONOMY_RANK = {
    AutonomyLevel.OBSERVE: 0,
    AutonomyLevel.RECOMMEND: 1,
    AutonomyLevel.APPROVAL_REQUIRED: 2,
    AutonomyLevel.LIMITED_AUTONOMY: 3,
    AutonomyLevel.FULL_AUTONOMY: 4,
    AutonomyLevel.EMERGENCY_ONLY: -1,
}


class ActionSafetyClass(str, Enum):
    """
    Operational risk class.

    READ_ONLY:
        Observation / retrieval.

    REVERSIBLE:
        Action can be safely rolled back.

    CONTAINMENT:
        Security containment with bounded blast radius.

    DISRUPTIVE:
        Service/user/network disruption possible.

    DESTRUCTIVE:
        Potential irreversible impact.

    CRITICAL:
        High-impact action affecting critical infrastructure,
        identity, data, or broad tenant scope.
    """

    READ_ONLY = "read_only"
    REVERSIBLE = "reversible"
    CONTAINMENT = "containment"
    DISRUPTIVE = "disruptive"
    DESTRUCTIVE = "destructive"
    CRITICAL = "critical"


_SAFETY_RANK = {
    ActionSafetyClass.READ_ONLY: 0,
    ActionSafetyClass.REVERSIBLE: 1,
    ActionSafetyClass.CONTAINMENT: 2,
    ActionSafetyClass.DISRUPTIVE: 3,
    ActionSafetyClass.DESTRUCTIVE: 4,
    ActionSafetyClass.CRITICAL: 5,
}


class ApprovalRequirement(str, Enum):
    NOT_REQUIRED = "not_required"
    REQUIRED = "required"
    MANDATORY_MULTI_APPROVER = "mandatory_multi_approver"
    DENIED = "denied"


class SafetyDecision(str, Enum):
    ALLOW_AUTONOMOUS = "allow_autonomous"
    ALLOW_AFTER_APPROVAL = "allow_after_approval"
    REQUIRE_APPROVAL = "require_approval"
    DENY = "deny"
    BLOCKED_KILL_SWITCH = "blocked_kill_switch"
    BLOCKED_EMERGENCY_STOP = "blocked_emergency_stop"


# ============================================================================
# APPROVAL STATE
# ============================================================================



_ALLOWED_TRANSITIONS = {
    ApprovalStatus.PENDING: {
        ApprovalStatus.APPROVED,
        ApprovalStatus.REJECTED,
        ApprovalStatus.EXPIRED,
        ApprovalStatus.REVOKED,
    },
    ApprovalStatus.APPROVED: {
        ApprovalStatus.REVOKED,
        ApprovalStatus.EXPIRED,
    },
    ApprovalStatus.REJECTED: set(),
    ApprovalStatus.EXPIRED: set(),
    ApprovalStatus.REVOKED: set(),
}


# ============================================================================
# ACTION REQUEST
# ============================================================================

@dataclass(frozen=True)
class AutonomyActionRequest:
    tenant_id: str
    action_id: str
    target_id: str
    action_type: str
    safety_class: ActionSafetyClass

    requested_by: str
    requested_at: datetime

    risk_score: float = 0.0
    reversible: bool = False
    critical_target: bool = False
    blast_radius: int = 1
    metadata: Mapping[str, str] = field(default_factory=dict)

    def __post_init__(self) -> None:
        require_non_empty(self.tenant_id, "tenant_id")
        require_non_empty(self.action_id, "action_id")
        require_non_empty(self.target_id, "target_id")
        require_non_empty(self.action_type, "action_type")
        require_non_empty(self.requested_by, "requested_by")

        ensure_aware(self.requested_at, "requested_at")

        if not 0.0 <= self.risk_score <= 1.0:
            raise Phase19ValidationError(
                "risk_score must be between 0 and 1"
            )

        if self.blast_radius < 1:
            raise Phase19ValidationError(
                "blast_radius must be >= 1"
            )

        if self.critical_target and (
            self.safety_class != ActionSafetyClass.CRITICAL
        ):
            raise Phase19ValidationError(
                "critical_target requires CRITICAL safety class"
            )


# ============================================================================
# TENANT SAFETY POLICY
# ============================================================================

@dataclass(frozen=True)
class AutonomyPolicy:
    tenant_id: str
    autonomy_level: AutonomyLevel

    maximum_automatic_safety_class: ActionSafetyClass = (
        ActionSafetyClass.REVERSIBLE
    )

    require_approval_above_risk: float = 0.70
    mandatory_multi_approval_above_risk: float = 0.90

    maximum_blast_radius: int = 10

    allow_critical_actions: bool = False
    allow_destructive_actions: bool = False

    approval_ttl_seconds: int = 900
    minimum_approvers: int = 1

    enabled: bool = True

    version: int = 1

    def __post_init__(self) -> None:
        require_non_empty(self.tenant_id, "tenant_id")

        if not 0.0 <= self.require_approval_above_risk <= 1.0:
            raise Phase19ValidationError(
                "require_approval_above_risk must be between 0 and 1"
            )

        if not 0.0 <= self.mandatory_multi_approval_above_risk <= 1.0:
            raise Phase19ValidationError(
                "mandatory_multi_approval_above_risk must be between 0 and 1"
            )

        if (
            self.mandatory_multi_approval_above_risk
            < self.require_approval_above_risk
        ):
            raise Phase19ValidationError(
                "multi-approval threshold cannot be below approval threshold"
            )

        if self.maximum_blast_radius < 1:
            raise Phase19ValidationError(
                "maximum_blast_radius must be >= 1"
            )

        if self.approval_ttl_seconds <= 0:
            raise Phase19ValidationError(
                "approval_ttl_seconds must be > 0"
            )

        if self.minimum_approvers <= 0:
            raise Phase19ValidationError(
                "minimum_approvers must be > 0"
            )


