@dataclass(frozen=True)
class KillSwitchState:
    tenant_id: str
    active: bool
    activated_at: Optional[datetime] = None
    activated_by: Optional[str] = None
    reason: Optional[str] = None
    version: int = 1

    def __post_init__(self) -> None:
        require_non_empty(self.tenant_id, "tenant_id")

        if self.active:
            if self.activated_at is None:
                raise Phase19ValidationError(
                    "active kill switch requires activated_at"
                )

            ensure_aware(self.activated_at, "activated_at")

            if not self.activated_by:
                raise Phase19ValidationError(
                    "active kill switch requires activated_by"
                )

            if not self.reason:
                raise Phase19ValidationError(
                    "active kill switch requires reason"
                )


