# ============================================================================
# APPROVAL
# ============================================================================

@dataclass
class ApprovalRecord:
    approval_id: str
    tenant_id: str
    action_id: str

    required_approvers: int
    status: ApprovalStatus

    created_at: datetime
    expires_at: datetime

    approvers: Tuple[str, ...] = ()
    rejection_reason: Optional[str] = None
    revocation_reason: Optional[str] = None

    metadata: Dict[str, str] = field(default_factory=dict)

    def __post_init__(self) -> None:
        require_non_empty(self.approval_id, "approval_id")
        require_non_empty(self.tenant_id, "tenant_id")
        require_non_empty(self.action_id, "action_id")

        ensure_aware(self.created_at, "created_at")
        ensure_aware(self.expires_at, "expires_at")

        if self.expires_at <= self.created_at:
            raise Phase19ValidationError(
                "expires_at must be after created_at"
            )

        if self.required_approvers <= 0:
            raise Phase19ValidationError(
                "required_approvers must be > 0"
            )

    def is_expired(self, now: Optional[datetime] = None) -> bool:
        current = ensure_aware(
            now or utc_now(),
            "now",
        )

        if current >= self.expires_at:
            return True

        return False

    def transition(
        self,
        new_status: ApprovalStatus,
        *,
        reason: Optional[str] = None,
        now: Optional[datetime] = None,
    ) -> None:
        if new_status not in _ALLOWED_TRANSITIONS[self.status]:
            raise InvalidStateTransitionError(
                f"Cannot transition approval "
                f"{self.status.value} -> {new_status.value}"
            )

        current = ensure_aware(now or utc_now(), "now")

        if (
            new_status == ApprovalStatus.EXPIRED
            and current < self.expires_at
        ):
            raise InvalidStateTransitionError(
                "Approval cannot be marked expired before expiration"
            )

        if new_status == ApprovalStatus.REJECTED:
            self.rejection_reason = reason

        if new_status == ApprovalStatus.REVOKED:
            self.revocation_reason = reason

        self.status = new_status

    def add_approval(
        self,
        approver_id: str,
        *,
        now: Optional[datetime] = None,
    ) -> None:
        require_non_empty(approver_id, "approver_id")

        current = ensure_aware(now or utc_now(), "now")

        if self.is_expired(current):
            if self.status == ApprovalStatus.PENDING:
                self.status = ApprovalStatus.EXPIRED

            raise ExpiredApprovalError(
                "Approval has expired"
            )

        if self.status != ApprovalStatus.PENDING:
            raise ApprovalError(
                f"Approval is not pending: {self.status.value}"
            )

        if approver_id in self.approvers:
            raise ApprovalError(
                "Duplicate approver is not allowed"
            )

        self.approvers = (*self.approvers, approver_id)

        if len(self.approvers) >= self.required_approvers:
            self.status = ApprovalStatus.APPROVED


