# ============================================================================
# REPOSITORY PORTS
# ============================================================================

class ApprovalRepository(Protocol):
    def save(self, approval: ApprovalRecord) -> None:
        ...

    def get(
        self,
        tenant_id: str,
        approval_id: str,
    ) -> ApprovalRecord:
        ...


class SafetyPolicyRepository(Protocol):
    def get(self, tenant_id: str) -> AutonomyPolicy:
        ...

    def save(self, policy: AutonomyPolicy) -> None:
        ...


class KillSwitchRepository(Protocol):
    def get(self, tenant_id: str) -> KillSwitchState:
        ...

    def save(self, state: KillSwitchState) -> None:
        ...


# ============================================================================
# IN-MEMORY REPOSITORIES
# ============================================================================

class InMemoryApprovalRepository:
    def __init__(self) -> None:
        self._records: Dict[Tuple[str, str], ApprovalRecord] = {}

    def save(self, approval: ApprovalRecord) -> None:
        key = (approval.tenant_id, approval.approval_id)
        self._records[key] = approval

    def get(
        self,
        tenant_id: str,
        approval_id: str,
    ) -> ApprovalRecord:
        require_non_empty(tenant_id, "tenant_id")
        require_non_empty(approval_id, "approval_id")

        record = self._records.get((tenant_id, approval_id))

        if record is None:
            raise ApprovalError(
                "Approval not found"
            )

        if record.tenant_id != tenant_id:
            raise TenantIsolationError(
                "Approval belongs to another tenant"
            )

        return record


class InMemorySafetyPolicyRepository:
    def __init__(self) -> None:
        self._policies: Dict[str, AutonomyPolicy] = {}

    def get(self, tenant_id: str) -> AutonomyPolicy:
        require_non_empty(tenant_id, "tenant_id")

        policy = self._policies.get(tenant_id)

        if policy is None:
            raise AuthorizationDeniedError(
                "No autonomy policy exists for tenant"
            )

        return policy

    def save(self, policy: AutonomyPolicy) -> None:
        self._policies[policy.tenant_id] = policy


class InMemoryKillSwitchRepository:
    def __init__(self) -> None:
        self._states: Dict[str, KillSwitchState] = {}

    def get(self, tenant_id: str) -> KillSwitchState:
        require_non_empty(tenant_id, "tenant_id")

        return self._states.get(
            tenant_id,
            KillSwitchState(
                tenant_id=tenant_id,
                active=False,
            ),
        )

    def save(self, state: KillSwitchState) -> None:
        self._states[state.tenant_id] = state


