class KillSwitchController:
    def __init__(
        self,
        repository: KillSwitchRepository,
    ) -> None:
        self.repository = repository

    def activate(
        self,
        tenant_id: str,
        *,
        actor: str,
        reason: str,
        now: Optional[datetime] = None,
    ) -> KillSwitchState:
        require_non_empty(tenant_id, "tenant_id")
        require_non_empty(actor, "actor")
        require_non_empty(reason, "reason")

        previous = self.repository.get(tenant_id)

        timestamp = ensure_aware(now or utc_now(), "now")

        state = KillSwitchState(
            tenant_id=tenant_id,
            active=True,
            activated_at=timestamp,
            activated_by=actor,
            reason=reason,
            version=previous.version + 1,
        )

        self.repository.save(state)
        return state

    def deactivate(
        self,
        tenant_id: str,
        *,
        actor: str,
    ) -> KillSwitchState:
        require_non_empty(tenant_id, "tenant_id")
        require_non_empty(actor, "actor")

        previous = self.repository.get(tenant_id)

        state = KillSwitchState(
            tenant_id=tenant_id,
            active=False,
            version=previous.version + 1,
        )

        self.repository.save(state)
        return state

    def assert_not_active(self, tenant_id: str) -> None:
        state = self.repository.get(tenant_id)

        if state.active:
            raise KillSwitchActiveError(
                f"Tenant kill switch is active: {tenant_id}"
            )


