# ============================================================================
# POLICY ENGINE
# ============================================================================

class AutonomyPolicyEngine:
    """
    Pure Phase 19 policy evaluation.

    It does not execute anything.
    """

    def evaluate(
        self,
        request: AutonomyActionRequest,
        policy: AutonomyPolicy,
        *,
        kill_switch_active: bool,
        emergency_stop_active: bool,
        now: Optional[datetime] = None,
    ) -> SafetyEvaluation:
        timestamp = ensure_aware(
            now or utc_now(),
            "now",
        )

        reasons = []

        if request.tenant_id != policy.tenant_id:
            raise TenantIsolationError(
                "Request and policy belong to different tenants"
            )

        if emergency_stop_active:
            return self._result(
                request,
                policy,
                SafetyDecision.BLOCKED_EMERGENCY_STOP,
                ApprovalRequirement.DENIED,
                ("EMERGENCY_STOP_ACTIVE",),
                True,
                timestamp,
            )

        if kill_switch_active:
            return self._result(
                request,
                policy,
                SafetyDecision.BLOCKED_KILL_SWITCH,
                ApprovalRequirement.DENIED,
                ("TENANT_KILL_SWITCH_ACTIVE",),
                True,
                timestamp,
            )

        if not policy.enabled:
            return self._result(
                request,
                policy,
                SafetyDecision.DENY,
                ApprovalRequirement.DENIED,
                ("AUTONOMY_POLICY_DISABLED",),
                False,
                timestamp,
            )

        if policy.autonomy_level in {
            AutonomyLevel.OBSERVE,
            AutonomyLevel.RECOMMEND,
            AutonomyLevel.APPROVAL_REQUIRED,
            AutonomyLevel.EMERGENCY_ONLY,
        }:
            return self._result(
                request,
                policy,
                SafetyDecision.REQUIRE_APPROVAL,
                ApprovalRequirement.REQUIRED,
                ("AUTONOMY_LEVEL_RESTRICTS_AUTONOMOUS_ACTION",),
                False,
                timestamp,
            )

        if request.critical_target:
            return self._result(
                request,
                policy,
                SafetyDecision.DENY,
                ApprovalRequirement.DENIED,
                ("CRITICAL_TARGET_AUTONOMY_DENIED",),
                False,
                timestamp,
            )

        if (
            request.safety_class == ActionSafetyClass.CRITICAL
            and not policy.allow_critical_actions
        ):
            return self._result(
                request,
                policy,
                SafetyDecision.DENY,
                ApprovalRequirement.DENIED,
                ("CRITICAL_ACTION_DENIED_BY_POLICY",),
                False,
                timestamp,
            )

        if (
            request.safety_class == ActionSafetyClass.DESTRUCTIVE
            and not policy.allow_destructive_actions
        ):
            return self._result(
                request,
                policy,
                SafetyDecision.DENY,
                ApprovalRequirement.DENIED,
                ("DESTRUCTIVE_ACTION_DENIED_BY_POLICY",),
                False,
                timestamp,
            )

        if (
            _SAFETY_RANK[request.safety_class]
            > _SAFETY_RANK[policy.maximum_automatic_safety_class]
        ):
            reasons.append(
                "ACTION_SAFETY_CLASS_EXCEEDS_AUTONOMOUS_LIMIT"
            )

        if request.risk_score >= policy.mandatory_multi_approval_above_risk:
            return self._result(
                request,
                policy,
                SafetyDecision.REQUIRE_APPROVAL,
                ApprovalRequirement.MANDATORY_MULTI_APPROVER,
                tuple(reasons) + ("HIGH_RISK_REQUIRES_MULTI_APPROVAL",),
                False,
                timestamp,
            )

        if request.risk_score >= policy.require_approval_above_risk:
            return self._result(
                request,
                policy,
                SafetyDecision.REQUIRE_APPROVAL,
                ApprovalRequirement.REQUIRED,
                tuple(reasons) + ("RISK_REQUIRES_APPROVAL",),
                False,
                timestamp,
            )

        if request.blast_radius > policy.maximum_blast_radius:
            return self._result(
                request,
                policy,
                SafetyDecision.REQUIRE_APPROVAL,
                ApprovalRequirement.REQUIRED,
                tuple(reasons) + ("BLAST_RADIUS_EXCEEDS_AUTONOMOUS_LIMIT",),
                False,
                timestamp,
            )

        if reasons:
            return self._result(
                request,
                policy,
                SafetyDecision.REQUIRE_APPROVAL,
                ApprovalRequirement.REQUIRED,
                tuple(reasons),
                False,
                timestamp,
            )

        return self._result(
            request,
            policy,
            SafetyDecision.ALLOW_AUTONOMOUS,
            ApprovalRequirement.NOT_REQUIRED,
            ("POLICY_PERMITS_AUTONOMOUS_ACTION",),
            False,
            timestamp,
        )

    def _result(
        self,
        request: AutonomyActionRequest,
        policy: AutonomyPolicy,
        decision: SafetyDecision,
        requirement: ApprovalRequirement,
        reasons: Tuple[str, ...],
        blocked: bool,
        timestamp: datetime,
    ) -> SafetyEvaluation:
        canonical = "|".join(
            (
                request.tenant_id,
                request.action_id,
                request.target_id,
                request.action_type,
                request.safety_class.value,
                decision.value,
                requirement.value,
                str(policy.version),
                str(blocked),
                ",".join(reasons),
            )
        )

        fingerprint = sha256(
            canonical.encode("utf-8")
        ).hexdigest()

        return SafetyEvaluation(
            evaluation_id=str(uuid4()),
            tenant_id=request.tenant_id,
            action_id=request.action_id,
            decision=decision,
            approval_requirement=requirement,
            reason_codes=reasons,
            evaluated_at=timestamp,
            policy_version=policy.version,
            kill_switch_active=(
                decision == SafetyDecision.BLOCKED_KILL_SWITCH
            ),
            emergency_stop_active=(
                decision == SafetyDecision.BLOCKED_EMERGENCY_STOP
            ),
            fingerprint=fingerprint,
        )


# ============================================================================
# HUMAN OVERRIDE
# ============================================================================

@dataclass(frozen=True)
class HumanOverride:
    override_id: str
    tenant_id: str
    action_id: str
    operator_id: str
    decision: SafetyDecision
    reason: str
    created_at: datetime
    expires_at: Optional[datetime] = None

    def __post_init__(self) -> None:
        require_non_empty(self.override_id, "override_id")
        require_non_empty(self.tenant_id, "tenant_id")
        require_non_empty(self.action_id, "action_id")
        require_non_empty(self.operator_id, "operator_id")
        require_non_empty(self.reason, "reason")

        ensure_aware(self.created_at, "created_at")

        if self.expires_at is not None:
            ensure_aware(self.expires_at, "expires_at")

            if self.expires_at <= self.created_at:
                raise Phase19ValidationError(
                    "expires_at must be after created_at"
                )

    def active(self, now: Optional[datetime] = None) -> bool:
        timestamp = ensure_aware(
            now or utc_now(),
            "now",
        )

        if self.expires_at is None:
            return True

        return timestamp < self.expires_at


# ============================================================================
# PHASE 18 COMPATIBILITY PORT
# ============================================================================

class VerifiedOutcomePort(Protocol):
    """
    Structural interface only.

    Phase 19 does not recreate Phase 18 memory/learning.
    """

    def is_verified_outcome(
        self,
        *,
        tenant_id: str,
        action_id: str,
    ) -> bool:
        ...


class NoImplicitLearningAuthorization:
    """
    Explicit safety boundary.

    A learned/verified historical outcome is never treated as
    automatic authorization for a new action.
    """

    @staticmethod
    def assert_not_authorized_by_learning(
        *,
        learning_verified: bool,
    ) -> None:
        if learning_verified:
            raise SafetyBoundaryError(
                "Historical verification/learning cannot independently "
                "authorize a new autonomous action"
            )


# ============================================================================
# AUTONOMY CONTROL ENGINE
# ============================================================================

class AutonomyControlEngine:
    def __init__(
        self,
        policy_repository: SafetyPolicyRepository,
        kill_switch_repository: KillSwitchRepository,
        approval_manager: ApprovalManager,
        emergency_stop: EmergencyStopController,
    ) -> None:
        self.policy_repository = policy_repository
        self.kill_switch_repository = kill_switch_repository
        self.approval_manager = approval_manager
        self.emergency_stop = emergency_stop

        self.policy_engine = AutonomyPolicyEngine()

        self._overrides: Dict[
            Tuple[str, str],
            HumanOverride,
        ] = {}

    def evaluate(
        self,
        request: AutonomyActionRequest,
        *,
        now: Optional[datetime] = None,
    ) -> SafetyEvaluation:
        policy = self.policy_repository.get(
            request.tenant_id
        )

        kill_state = self.kill_switch_repository.get(
            request.tenant_id
        )

        return self.policy_engine.evaluate(
            request,
            policy,
            kill_switch_active=kill_state.active,
            emergency_stop_active=self.emergency_stop.state.active,
            now=now,
        )

    def request_approval(
        self,
        request: AutonomyActionRequest,
        *,
        now: Optional[datetime] = None,
    ) -> ApprovalRecord:
        evaluation = self.evaluate(
            request,
            now=now,
        )

        if evaluation.approval_requirement not in {
            ApprovalRequirement.REQUIRED,
            ApprovalRequirement.MANDATORY_MULTI_APPROVER,
        }:
            raise ApprovalError(
                "Approval is not required for this action"
            )

        policy = self.policy_repository.get(
            request.tenant_id
        )

        if (
            evaluation.approval_requirement
            == ApprovalRequirement.MANDATORY_MULTI_APPROVER
            and policy.minimum_approvers < 2
        ):
            policy = AutonomyPolicy(
                tenant_id=policy.tenant_id,
                autonomy_level=policy.autonomy_level,
                maximum_automatic_safety_class=(
                    policy.maximum_automatic_safety_class
                ),
                require_approval_above_risk=(
                    policy.require_approval_above_risk
                ),
                mandatory_multi_approval_above_risk=(
                    policy.mandatory_multi_approval_above_risk
                ),
                maximum_blast_radius=policy.maximum_blast_radius,
                allow_critical_actions=policy.allow_critical_actions,
                allow_destructive_actions=policy.allow_destructive_actions,
                approval_ttl_seconds=policy.approval_ttl_seconds,
                minimum_approvers=2,
                enabled=policy.enabled,
                version=policy.version,
            )

        return self.approval_manager.create(
            request,
            policy,
            now=now,
        )

    def install_human_override(
        self,
        override: HumanOverride,
    ) -> None:
        self._overrides[
            (override.tenant_id, override.action_id)
        ] = override

    def get_active_override(
        self,
        tenant_id: str,
        action_id: str,
        *,
        now: Optional[datetime] = None,
    ) -> Optional[HumanOverride]:
        override = self._overrides.get(
            (tenant_id, action_id)
        )

        if override is None:
            return None

        if not override.active(now):
            return None

        return override

    def assert_action_authorized_for_execution(
        self,
        request: AutonomyActionRequest,
        evaluation: SafetyEvaluation,
        *,
        approval: Optional[ApprovalRecord] = None,
        now: Optional[datetime] = None,
    ) -> None:
        """
        Final Phase 19 safety gate.

        This method does NOT execute an action.
        It only determines whether an existing execution layer may proceed.
        """

        self.emergency_stop.assert_not_active()

        self.kill_switch_repository.get(
            request.tenant_id
        )

        kill_state = self.kill_switch_repository.get(
            request.tenant_id
        )

        if kill_state.active:
            raise KillSwitchActiveError(
                "Tenant kill switch is active"
            )

        if request.tenant_id != evaluation.tenant_id:
            raise TenantIsolationError(
                "Request/evaluation tenant mismatch"
            )

        if request.action_id != evaluation.action_id:
            raise SafetyBoundaryError(
                "Request/evaluation action mismatch"
            )

        override = self.get_active_override(
            request.tenant_id,
            request.action_id,
            now=now,
        )

        if override is not None:
            if override.decision == SafetyDecision.DENY:
                raise AuthorizationDeniedError(
                    "Human override explicitly denied action"
                )

            if override.decision in {
                SafetyDecision.ALLOW_AUTONOMOUS,
                SafetyDecision.ALLOW_AFTER_APPROVAL,
            }:
                return

        if evaluation.decision == SafetyDecision.DENY:
            raise AuthorizationDeniedError(
                "Policy denied action"
            )

        if evaluation.decision in {
            SafetyDecision.BLOCKED_KILL_SWITCH,
            SafetyDecision.BLOCKED_EMERGENCY_STOP,
        }:
            raise SafetyBoundaryError(
                "Safety boundary blocks action"
            )

        if evaluation.decision == SafetyDecision.ALLOW_AUTONOMOUS:
            return

        if evaluation.decision == SafetyDecision.REQUIRE_APPROVAL:
            if approval is None:
                raise ApprovalError(
                    "Approval is required"
                )

            current = ensure_aware(
                now or utc_now(),
                "now",
            )

            if approval.is_expired(current):
                raise ExpiredApprovalError(
                    "Approval has expired"
                )

            if approval.status != ApprovalStatus.APPROVED:
                raise ApprovalError(
                    f"Approval is not approved: "
                    f"{approval.status.value}"
                )

            return

        raise AuthorizationDeniedError(
            f"Unsupported safety decision: "
            f"{evaluation.decision.value}"
        )


# ============================================================================
# AUDIT FACTORY
# ============================================================================

class AutonomyAuditFactory:
    @staticmethod
    def create(
        request: AutonomyActionRequest,
        evaluation: SafetyEvaluation,
        *,
        actor: str,
        now: Optional[datetime] = None,
    ) -> AutonomyAuditRecord:
        require_non_empty(actor, "actor")

        timestamp = ensure_aware(
            now or utc_now(),
            "now",
        )

        canonical = "|".join(
            (
                evaluation.fingerprint,
                request.tenant_id,
                request.action_id,
                actor,
                evaluation.decision.value,
                str(timestamp.timestamp()),
            )
        )

        fingerprint = sha256(
            canonical.encode("utf-8")
        ).hexdigest()

        return AutonomyAuditRecord(
            audit_id=str(uuid4()),
            tenant_id=request.tenant_id,
            action_id=request.action_id,
            decision=evaluation.decision,
            reason_codes=evaluation.reason_codes,
            actor=actor,
            timestamp=timestamp,
            fingerprint=fingerprint,
        )


