def _make_policy(
    tenant_id: str = "tenant-a",
    *,
    level: AutonomyLevel = AutonomyLevel.FULL_AUTONOMY,
    maximum_class: ActionSafetyClass = (
        ActionSafetyClass.REVERSIBLE
    ),
    minimum_approvers: int = 1,
) -> AutonomyPolicy:
    return AutonomyPolicy(
        tenant_id=tenant_id,
        autonomy_level=level,
        maximum_automatic_safety_class=maximum_class,
        minimum_approvers=minimum_approvers,
    )


def _make_request(
    tenant_id: str = "tenant-a",
    *,
    action_id: str = "action-1",
    safety_class: ActionSafetyClass = (
        ActionSafetyClass.REVERSIBLE
    ),
    risk_score: float = 0.10,
    blast_radius: int = 1,
) -> AutonomyActionRequest:
    return AutonomyActionRequest(
        tenant_id=tenant_id,
        action_id=action_id,
        target_id="asset-1",
        action_type="isolate_endpoint",
        safety_class=safety_class,
        requested_by="hydra",
        requested_at=utc_now(),
        risk_score=risk_score,
        reversible=(
            safety_class
            in {
                ActionSafetyClass.READ_ONLY,
                ActionSafetyClass.REVERSIBLE,
            }
        ),
        blast_radius=blast_radius,
    )


