# ============================================================================
# SECRET BOUNDARY
# ============================================================================

@dataclass(frozen=True)
class SecretValue:
    """
    Secret container.

    __repr__ deliberately never exposes the value.
    """

    _value: str

    def __post_init__(self) -> None:
        if not self._value:
            raise Phase20ValidationError(
                "SecretValue cannot be empty"
            )

    def reveal(self) -> str:
        return self._value

    def __repr__(self) -> str:
        return "SecretValue(<redacted>)"


@dataclass(frozen=True)
class ConnectorCredentials:
    authentication_type: AuthenticationType

    api_key: Optional[SecretValue] = None
    bearer_token: Optional[SecretValue] = None

    username: Optional[str] = None
    password: Optional[SecretValue] = None

    custom_header_name: Optional[str] = None
    custom_header_value: Optional[SecretValue] = None

    def headers(self) -> Dict[str, str]:
        auth = self.authentication_type

        if auth == AuthenticationType.NONE:
            return {}

        if auth == AuthenticationType.API_KEY:
            if self.api_key is None:
                raise ConnectorConfigurationError(
                    "API key authentication requires api_key"
                )

            return {
                "X-API-Key": self.api_key.reveal()
            }

        if auth == AuthenticationType.BEARER:
            if self.bearer_token is None:
                raise ConnectorConfigurationError(
                    "Bearer authentication requires bearer_token"
                )

            return {
                "Authorization": (
                    f"Bearer {self.bearer_token.reveal()}"
                )
            }

        if auth == AuthenticationType.BASIC:
            if not self.username or self.password is None:
                raise ConnectorConfigurationError(
                    "Basic authentication requires username/password"
                )

            encoded = base64.b64encode(
                (
                    f"{self.username}:"
                    f"{self.password.reveal()}"
                ).encode("utf-8")
            ).decode("ascii")

            return {
                "Authorization": f"Basic {encoded}"
            }

        if auth == AuthenticationType.CUSTOM_HEADER:
            if (
                not self.custom_header_name
                or self.custom_header_value is None
            ):
                raise ConnectorConfigurationError(
                    "Custom header authentication is incomplete"
                )

            return {
                self.custom_header_name:
                    self.custom_header_value.reveal()
            }

        raise ConnectorConfigurationError(
            f"Unsupported authentication type: {auth}"
        )


