# ============================================================================
# HTTP CLIENT
# ============================================================================

class ConnectorHTTPClient:
    """
    Authenticated HTTP client with bounded retries.

    Retry policy:
    - transport failures -> retry
    - timeout -> retry
    - 429 -> retry
    - 5xx -> retry
    - 4xx except 429 -> no retry
    """

    def __init__(
        self,
        config: ConnectorConfig,
        transport: Optional[HTTPTransport] = None,
    ) -> None:
        self.config = config

        # [auto-repair] this defaulted to UrllibHTTPTransport(), which
        # calls urllib's urlopen() directly with zero SSRF protection --
        # no private/loopback/link-local/metadata-IP blocking at all,
        # unlike HTTPTransport (which resolves to the hardened,
        # DNS-rebinding-safe _HardenedHTTPTransport elsewhere in this
        # file, already verified against 169.254.169.254/127.0.0.1/
        # 10.x during this session's security review). The type hint
        # on the transport= parameter above already said HTTPTransport;
        # the fallback just didn't match it. Confirmed via grep that
        # nothing else in this file relies on UrllibHTTPTransport being
        # the default here.
        #
        # HTTPTransport fixes its timeout at construction time (unlike
        # UrllibHTTPTransport, which took timeout_seconds per-call) --
        # constructing it with config.timeout_seconds here, and see the
        # matching fix in request() below that stops passing
        # timeout_seconds into transport.request() for this path.
        self.transport = (
            transport
            if transport is not None
            else HTTPTransport(timeout_seconds=config.timeout_seconds)
        )

    def request(
        self,
        *,
        method: HTTPMethod,
        path: str,
        query: Optional[Mapping[str, str]] = None,
        body: Optional[Mapping[str, Any]] = None,
    ) -> HTTPResponse:

        if not path.startswith("/"):
            raise Phase20ValidationError(
                "path must start with '/'"
            )

        # [auto-repair] base_url is another "made optional for safety"
        # field (see ConnectorConfig) that wasn't actually handled
        # safely here -- .rstrip() on None crashed with AttributeError
        # on every request() call for a config that didn't explicitly
        # set it. Raising a clear, actionable error instead of letting
        # that confusing AttributeError surface.
        if not self.config.base_url:
            raise ConnectorConfigurationError(
                "ConnectorConfig.base_url is required to make requests."
            )

        url = (
            self.config.base_url.rstrip("/")
            + path
        )

        if query:
            url += "?" + urlencode(
                query,
                doseq=True,
            )

        headers = {
            "Accept": "application/json",
            "User-Agent": "HYDRA-Enterprise-Connector/20",
        }

        # [auto-repair] config.credentials and config.default_headers
        # were both made Optional (default None) -- see the "made
        # optional for safety" comments on ConnectorConfig's fields --
        # but this method still called .headers() / dict() on them
        # unconditionally. Confirmed live: a config built without
        # explicitly supplying both fields (i.e. using their own
        # declared defaults) crashed on every single request() call,
        # AttributeError first, then TypeError once credentials was
        # supplied. Being Optional wasn't safe until these two lines
        # actually handled the None case.
        if self.config.credentials is not None:
            headers.update(
                self.config.credentials.headers()
            )

        headers.update(
            dict(self.config.default_headers or {})
        )

        payload = None

        if body is not None:
            payload = json.dumps(
                body,
                separators=(",", ":"),
                default=str,
            ).encode("utf-8")

            headers["Content-Type"] = (
                "application/json"
            )

        last_error: Optional[Exception] = None

        for attempt in range(
            self.config.max_retries + 1
        ):
            try:
                # [auto-repair] stopped passing timeout_seconds here --
                # HTTPTransport.request() (the new default, see __init__
                # above) doesn't accept it as a per-call argument, only
                # at construction time, unlike the old UrllibHTTPTransport
                # default. The transport is now constructed with
                # config.timeout_seconds already, so this achieves the
                # same effective timeout without the TypeError.
                response = self.transport.request(
                    method=method,
                    url=url,
                    headers=headers,
                    body=payload,
                )

                if response.status_code == 429:
                    if attempt < self.config.max_retries:
                        self._backoff(attempt)
                        continue

                    raise ConnectorRateLimitError(
                        "Remote connector rate-limited request"
                    )

                if 500 <= response.status_code <= 599:
                    if attempt < self.config.max_retries:
                        self._backoff(attempt)
                        continue

                return response

            except ConnectorTimeoutError as exc:
                last_error = exc

                if attempt >= self.config.max_retries:
                    raise

                self._backoff(attempt)

            except ConnectorTransportError as exc:
                last_error = exc

                if attempt >= self.config.max_retries:
                    raise

                self._backoff(attempt)

        raise ConnectorTransportError(
            "Connector request failed"
        ) from last_error

    def _backoff(
        self,
        attempt: int,
    ) -> None:
        # [auto-repair] retry_backoff_seconds is also "made optional
        # for safety" on ConnectorConfig (defaults to None) -- the
        # multiplication below crashed with TypeError whenever a config
        # didn't explicitly set it. 1.0s is a reasonable default backoff
        # base.
        backoff_base = self.config.retry_backoff_seconds
        if backoff_base is None:
            backoff_base = 1.0
        delay = (
            backoff_base
            * (2 ** attempt)
        )

        if delay > 0:
            time.sleep(delay)


# ============================================================================
# JSON RESPONSE HELPERS
# ============================================================================

def decode_json_response(
    response: HTTPResponse,
) -> Any:
    if response.status_code in {
        401,
        403,
    }:
        if response.status_code == 401:
            raise ConnectorAuthenticationError(
                "Remote connector rejected authentication"
            )

        raise ConnectorAuthorizationError(
            "Remote connector rejected authorization"
        )

    if not 200 <= response.status_code < 300:
        raise ConnectorResponseError(
            f"Remote connector returned HTTP "
            f"{response.status_code}"
        )

    if not response.body:
        return {}

    try:
        return json.loads(
            response.body.decode("utf-8")
        )
    except (
        UnicodeDecodeError,
        json.JSONDecodeError,
    ) as exc:
        raise ConnectorResponseError(
            "Remote connector returned invalid JSON"
        ) from exc


def ensure_mapping(
    value: Any,
    field_name: str = "response",
) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise ConnectorResponseError(
            f"{field_name} must be a JSON object"
        )

    return value


# ============================================================================
# CONNECTOR BASE
# ============================================================================

class EnterpriseConnector(Protocol):

    @property
    def config(self) -> ConnectorConfig:
        ...

    def health_check(self) -> ConnectorHealth:
        ...

    def ingest(
        self,
        *,
        path: str,
        query: Optional[Mapping[str, str]] = None,
    ) -> IntegrationResult:
        ...


# ============================================================================
# BASE CONNECTOR IMPLEMENTATION
# ============================================================================

class BaseEnterpriseConnector:
    connector_type: ConnectorType

    def __init__(
        self,
        config: ConnectorConfig,
        transport: Optional[HTTPTransport] = None,
    ) -> None:
        if config.connector_type != self.connector_type:
            raise ConnectorConfigurationError(
                "Connector type does not match implementation"
            )

        self._config = config

        self.http = ConnectorHTTPClient(
            config,
            transport=transport,
        )

        self._lock = Lock()

        self._consecutive_failures = 0

    @property
    def config(self) -> ConnectorConfig:
        return self._config

    def health_check(self) -> ConnectorHealth:
        started = time.monotonic()

        if not self._config.enabled:
            return ConnectorHealth(
                connector_id=self._config.connector_id,
                tenant_id=self._config.tenant_id,
                state=ConnectorState.DISABLED,
                checked_at=utc_now(),
                consecutive_failures=(
                    self._consecutive_failures
                ),
                message="Connector is disabled",
            )

        try:
            response = self.http.request(
                method=HTTPMethod.GET,
                path="/health",
            )

            elapsed = (
                time.monotonic() - started
            ) * 1000.0

            if 200 <= response.status_code < 300:
                with self._lock:
                    self._consecutive_failures = 0

                return ConnectorHealth(
                    connector_id=(
                        self._config.connector_id
                    ),
                    tenant_id=self._config.tenant_id,
                    state=ConnectorState.HEALTHY,
                    checked_at=utc_now(),
                    latency_ms=elapsed,
                    status_code=response.status_code,
                    consecutive_failures=0,
                )

            with self._lock:
                self._consecutive_failures += 1
                failures = self._consecutive_failures

            state = (
                ConnectorState.UNHEALTHY
                if failures >= 3
                else ConnectorState.DEGRADED
            )

            return ConnectorHealth(
                connector_id=self._config.connector_id,
                tenant_id=self._config.tenant_id,
                state=state,
                checked_at=utc_now(),
                latency_ms=elapsed,
                status_code=response.status_code,
                consecutive_failures=failures,
                message=(
                    f"Health endpoint returned "
                    f"{response.status_code}"
                ),
            )

        except ConnectorError as exc:
            with self._lock:
                self._consecutive_failures += 1
                failures = self._consecutive_failures

            state = (
                ConnectorState.UNHEALTHY
                if failures >= 3
                else ConnectorState.DEGRADED
            )

            return ConnectorHealth(
                connector_id=self._config.connector_id,
                tenant_id=self._config.tenant_id,
                state=state,
                checked_at=utc_now(),
                latency_ms=(
                    time.monotonic() - started
                ) * 1000.0,
                consecutive_failures=failures,
                message=str(exc),
            )

    def ingest(
        self,
        *,
        path: str,
        query: Optional[Mapping[str, str]] = None,
    ) -> IntegrationResult:

        started = utc_now()

        try:
            response = self.http.request(
                method=HTTPMethod.GET,
                path=path,
                query=query,
            )

            payload = decode_json_response(
                response
            )

            telemetry = tuple(
                self._normalize_payload(
                    payload
                )
            )

            self._mark_success()

            return IntegrationResult(
                result_id=str(uuid4()),
                tenant_id=self._config.tenant_id,
                connector_id=self._config.connector_id,
                operation=IntegrationOperation.INGEST,
                status=IntegrationResultStatus.SUCCESS,
                started_at=started,
                completed_at=utc_now(),
                item_count=len(telemetry),
                telemetry=telemetry,
            )

        except ConnectorError as exc:
            self._mark_failure()

            return IntegrationResult(
                result_id=str(uuid4()),
                tenant_id=self._config.tenant_id,
                connector_id=self._config.connector_id,
                operation=IntegrationOperation.INGEST,
                status=IntegrationResultStatus.FAILED,
                started_at=started,
                completed_at=utc_now(),
                error_code=type(exc).__name__,
                error_message=str(exc),
            )

    def _mark_success(self) -> None:
        with self._lock:
            self._consecutive_failures = 0

    def _mark_failure(self) -> None:
        with self._lock:
            self._consecutive_failures += 1

    def _normalize_payload(
        self,
        payload: Any,
    ) -> Iterable[NormalizedTelemetry]:
        """
        Generic JSON normalization.

        Vendor-specific mappings must be implemented by a real
        vendor adapter after its documented API schema is known.
        """

        records: Sequence[Any]

        if isinstance(payload, list):
            records = payload

        elif isinstance(payload, Mapping):
            candidate = (
                payload.get("items")
                or payload.get("results")
                or payload.get("data")
            )

            if isinstance(candidate, list):
                records = candidate
            else:
                records = [payload]

        else:
            raise ConnectorResponseError(
                "Telemetry payload must be JSON object/list"
            )

        for record in records:
            if not isinstance(record, Mapping):
                continue

            yield NormalizedTelemetry(
                telemetry_id=str(uuid4()),
                tenant_id=self._config.tenant_id,
                connector_id=self._config.connector_id,
                kind=TelemetryKind.EVENT,
                observed_at=utc_now(),
                received_at=utc_now(),
                source_type=(
                    self.connector_type.value
                ),
                source_name=self._config.name,
                entity_id=(
                    str(record["id"])
                    if "id" in record
                    else None
                ),
                severity=(
                    str(record["severity"])
                    if "severity" in record
                    else None
                ),
                title=(
                    str(record["title"])
                    if "title" in record
                    else None
                ),
                description=(
                    str(record["description"])
                    if "description" in record
                    else None
                ),
                attributes=dict(record),
                provenance={
                    "connector_id": (
                        self._config.connector_id
                    ),
                    "connector_type": (
                        self.connector_type.value
                    ),
                },
            )


