# ============================================================================
# INTEGRATION AUDIT
# ============================================================================

@dataclass(frozen=True)
class IntegrationAuditRecord:
    audit_id: str
    tenant_id: str
    connector_id: str
    operation: IntegrationOperation

    status: IntegrationResultStatus

    actor: str
    timestamp: datetime

    item_count: int

    fingerprint: str

    def __post_init__(self) -> None:
        require_non_empty(
            self.audit_id,
            "audit_id",
        )
        require_non_empty(
            self.tenant_id,
            "tenant_id",
        )
        require_non_empty(
            self.connector_id,
            "connector_id",
        )
        require_non_empty(
            self.actor,
            "actor",
        )

        ensure_aware(
            self.timestamp,
            "timestamp",
        )

        if self.item_count < 0:
            raise Phase20ValidationError(
                "item_count cannot be negative"
            )


class IntegrationAuditFactory:

    @staticmethod
    def create(
        result: IntegrationResult,
        *,
        actor: str,
        now: Optional[datetime] = None,
    ) -> IntegrationAuditRecord:

        require_non_empty(
            actor,
            "actor",
        )

        timestamp = ensure_aware(
            now or utc_now(),
            "now",
        )

        canonical = "|".join(
            (
                result.tenant_id,
                result.connector_id,
                result.operation.value,
                result.status.value,
                str(result.item_count),
                actor,
                str(timestamp.timestamp()),
            )
        )

        fingerprint = sha256(
            canonical.encode("utf-8")
        ).hexdigest()

        return IntegrationAuditRecord(
            audit_id=str(uuid4()),
            tenant_id=result.tenant_id,
            connector_id=result.connector_id,
            operation=result.operation,
            status=result.status,
            actor=actor,
            timestamp=timestamp,
            item_count=result.item_count,
            fingerprint=fingerprint,
        )


