# ============================================================================
# PHASE 20 SERVICE
# ============================================================================

class EnterpriseIntegrationService:
    """
    Application-level integration service.

    This service only orchestrates connector operations.
    It does not perform detection, response, execution,
    verification, memory, or learning.
    """

    def __init__(
        self,
        registry: ConnectorRegistry,
    ) -> None:
        self.registry = registry

    def register(
        self,
        config: ConnectorConfig,
        *,
        transport: Optional[HTTPTransport] = None,
    ) -> EnterpriseConnector:

        connector = ConnectorFactory.create(
            config,
            transport=transport,
        )

        self.registry.register(
            connector
        )

        return connector

    def health(
        self,
        tenant_id: str,
        connector_id: str,
    ) -> ConnectorHealth:

        connector = self.registry.get(
            tenant_id,
            connector_id,
        )

        return connector.health_check()

    def ingest(
        self,
        tenant_id: str,
        connector_id: str,
        *,
        path: str,
        query: Optional[Mapping[str, str]] = None,
    ) -> IntegrationResult:

        connector = self.registry.get(
            tenant_id,
            connector_id,
        )

        return connector.ingest(
            path=path,
            query=query,
        )


# ============================================================================
# TEST TRANSPORT
#
# This is ONLY an injectable test transport.
# It is not production integration and is never exposed as
# an enterprise connector.
# ============================================================================

class TestHTTPTransport:
    def __init__(
        self,
        responses: Optional[
            Mapping[str, HTTPResponse]
        ] = None,
        errors: Optional[
            Mapping[str, Exception]
        ] = None,
    ) -> None:
        self.responses = dict(
            responses or {}
        )

        self.errors = dict(
            errors or {}
        )

        self.calls = []

    def request(
        self,
        *,
        method: HTTPMethod,
        url: str,
        headers: Mapping[str, str],
        body: Optional[bytes],
        timeout_seconds: float,
    ) -> HTTPResponse:

        self.calls.append(
            {
                "method": method,
                "url": url,
                "headers": dict(headers),
                "body": body,
                "timeout": timeout_seconds,
            }
        )

        if url in self.errors:
            raise self.errors[url]

        if url not in self.responses:
            raise ConnectorTransportError(
                f"No test response configured for {url}"
            )

        return self.responses[url]


