def _make_config(
    *,
    tenant_id: str = "tenant-a",
    connector_id: str = "siem-1",
    connector_type: ConnectorType = ConnectorType.SIEM,
    auth: AuthenticationType = AuthenticationType.BEARER,
) -> ConnectorConfig:

    credentials = ConnectorCredentials(
        authentication_type=auth,
        bearer_token=(
            SecretValue("secret-token")
            if auth == AuthenticationType.BEARER
            else None
        ),
        api_key=(
            SecretValue("api-key")
            if auth == AuthenticationType.API_KEY
            else None
        ),
    )

    return ConnectorConfig(
        connector_id=connector_id,
        tenant_id=tenant_id,
        name="Test Connector",
        connector_type=connector_type,
        base_url="https://security.example.test",
        credentials=credentials,
    )


def _make_response(
    *,
    status_code: int = 200,
    payload: Optional[Any] = None,
) -> HTTPResponse:

    return HTTPResponse(
        status_code=status_code,
        headers={
            "Content-Type": "application/json"
        },
        body=json.dumps(
            payload or {}
        ).encode("utf-8"),
        elapsed_ms=2.0,
    )


