def test_generic_payload_can_be_single_object() -> None:
    config = _make_config()

    transport = TestHTTPTransport(
        responses={
            "https://security.example.test/event":
                _make_response(
                    payload={
                        "id": "single-event",
                        "severity": "high",
                    }
                )
        }
    )

    connector = SIEMConnector(
        config,
        transport=transport,
    )

    result = connector.ingest(
        path="/event"
    )

    assert result.status == (
        IntegrationResultStatus.SUCCESS
    )

    assert result.item_count == 1
    assert result.telemetry[0].entity_id == (
        "single-event"
    )


