"""
HYDRA™ — PHASE 21
CROSS-LAYER WIRING & ORCHESTRATION

PURPOSE
-------
Connect previously implemented HYDRA layers through explicit,
typed contracts without duplicating their implementations.

PHASE 21 RESPONSIBILITIES
-------------------------
1. Cross-layer message contracts
2. Tenant-scoped execution context
3. Integration -> observation handoff
4. Observation -> detection handoff contract
5. Detection -> correlation handoff contract
6. Correlation -> investigation handoff contract
7. Investigation -> reasoning handoff contract
8. Reasoning -> risk handoff contract
9. Risk -> prediction handoff contract
10. Prediction -> simulation handoff contract
11. Simulation -> governance handoff contract
12. Governance -> approval handoff contract
13. Approval -> execution handoff contract
14. Execution -> verification handoff contract
15. Verification -> memory/learning handoff contract
16. Cross-layer event envelope
17. Strong tenant isolation
18. Correlation IDs / causation IDs
19. Idempotency boundaries
20. Wiring validation
21. Pipeline orchestration
22. Failure isolation
23. Audit-safe pipeline state

IMPORTANT
---------
This phase DOES NOT recreate or replace previous engines.

It only wires existing interfaces.

No new detection algorithm.
No new correlation engine.
No new investigation engine.
No new reasoning engine.
No new prediction algorithm.
No new simulation engine.
No new governance engine.
No new execution engine.
No new verification engine.
No new memory engine.

Those remain owned by their respective phases.
"""


# (duplicate "from __future__ import annotations" removed by auto-repair)

from dataclasses import dataclass, field
from datetime import datetime, timezone
from enum import Enum
from hashlib import sha256
from threading import Lock
from typing import (
    Any,
    Callable,
    Dict,
    Generic,
    Mapping,
    Optional,
    Protocol,
    Sequence,
    Tuple,
    TypeVar,
)
from uuid import uuid4


# ============================================================================
# COMMON HELPERS
# ============================================================================







# ============================================================================
# ERRORS
# ============================================================================

class Phase21Error(Exception):
    """Base Phase 21 error."""


class Phase21ValidationError(Phase21Error):
    """Invalid Phase 21 data."""


class WiringError(Phase21Error):
    """Cross-layer wiring failure."""




class DuplicateMessageError(Phase21Error):
    """Duplicate message was submitted."""


class PipelineExecutionError(Phase21Error):
    """Pipeline execution failed."""


class StageNotConfiguredError(Phase21Error):
    """Required pipeline stage is not configured."""


class InvalidTransitionError(Phase21Error):
    """Invalid pipeline transition."""


# ============================================================================
# LIFECYCLE
# ============================================================================



LIFECYCLE_ORDER: Tuple[LifecycleStage, ...] = (
    LifecycleStage.OBSERVE,
    LifecycleStage.DETECT,
    LifecycleStage.CORRELATE,
    LifecycleStage.INVESTIGATE,
    LifecycleStage.REASON,
    LifecycleStage.RISK_ASSESS,
    LifecycleStage.PREDICT,
    LifecycleStage.SIMULATE,
    LifecycleStage.GOVERN,
    LifecycleStage.APPROVE,
    LifecycleStage.EXECUTE,
    LifecycleStage.VERIFY,
    LifecycleStage.LEARN,
)


# ============================================================================
# MESSAGE TYPES
# ============================================================================

class MessageKind(str, Enum):
    OBSERVATION = "observation"
    DETECTION = "detection"
    CORRELATION = "correlation"
    INVESTIGATION = "investigation"
    REASONING = "reasoning"
    RISK = "risk"
    PREDICTION = "prediction"
    SIMULATION = "simulation"
    GOVERNANCE = "governance"
    APPROVAL = "approval"
    EXECUTION = "execution"
    VERIFICATION = "verification"
    LEARNING = "learning"


class MessageStatus(str, Enum):
    CREATED = "created"
    ACCEPTED = "accepted"
    PROCESSED = "processed"
    REJECTED = "rejected"
    FAILED = "failed"




# ============================================================================
# PIPELINE CONTEXT
# ============================================================================

@dataclass(frozen=True)
class PipelineContext:
    """
    Immutable context propagated through the entire lifecycle.

    correlation_id:
        Identifies one logical security workflow.

    causation_id:
        Identifies the message that caused the current message.

    tenant_id:
        Hard tenant boundary.
    """

    tenant_id: str
    correlation_id: str

    causation_id: Optional[str] = None

    actor_id: Optional[str] = None

    created_at: datetime = field(
        default_factory=utc_now
    )

    metadata: Mapping[str, str] = field(
        default_factory=dict
    )

    def __post_init__(self) -> None:
        require_non_empty(
            self.tenant_id,
            "tenant_id",
        )

        require_non_empty(
            self.correlation_id,
            "correlation_id",
        )

        ensure_aware(
            self.created_at,
            "created_at",
        )


# ============================================================================
# CROSS-LAYER MESSAGE
# ============================================================================

@dataclass(frozen=True)
class PipelineMessage:
    """
    Universal cross-layer envelope.

    The envelope carries metadata and provenance.
    Payload remains owned by the originating phase.
    """

    message_id: str
    tenant_id: str

    stage: LifecycleStage
    kind: MessageKind

    truth_class: TruthClass

    context: PipelineContext

    payload: Any

    created_at: datetime = field(
        default_factory=utc_now
    )

    status: MessageStatus = (
        MessageStatus.CREATED
    )

    schema_version: str = "21.1"

    fingerprint: str = ""

    def __post_init__(self) -> None:
        require_non_empty(
            self.message_id,
            "message_id",
        )

        require_non_empty(
            self.tenant_id,
            "tenant_id",
        )

        require_non_empty(
            self.schema_version,
            "schema_version",
        )

        ensure_aware(
            self.created_at,
            "created_at",
        )

        if self.context.tenant_id != self.tenant_id:
            raise TenantIsolationError(
                "Message tenant differs from context tenant"
            )

        expected = PipelineMessage.calculate_fingerprint(
            message_id=self.message_id,
            tenant_id=self.tenant_id,
            stage=self.stage,
            kind=self.kind,
            truth_class=self.truth_class,
            correlation_id=self.context.correlation_id,
            causation_id=self.context.causation_id,
            schema_version=self.schema_version,
        )

        if self.fingerprint and self.fingerprint != expected:
            raise Phase21ValidationError(
                "Pipeline message fingerprint mismatch"
            )

    @staticmethod
    def calculate_fingerprint(
        *,
        message_id: str,
        tenant_id: str,
        stage: LifecycleStage,
        kind: MessageKind,
        truth_class: TruthClass,
        correlation_id: str,
        causation_id: Optional[str],
        schema_version: str,
    ) -> str:

        canonical = "|".join(
            (
                message_id,
                tenant_id,
                stage.value,
                kind.value,
                truth_class.value,
                correlation_id,
                causation_id or "",
                schema_version,
            )
        )

        return sha256(
            canonical.encode("utf-8")
        ).hexdigest()


# ============================================================================
# MESSAGE FACTORY
# ============================================================================

class PipelineMessageFactory:

    @staticmethod
    def create(
        *,
        tenant_id: str,
        stage: LifecycleStage,
        kind: MessageKind,
        truth_class: TruthClass,
        payload: Any,
        correlation_id: Optional[str] = None,
        causation_id: Optional[str] = None,
        actor_id: Optional[str] = None,
        metadata: Optional[Mapping[str, str]] = None,
    ) -> PipelineMessage:

        tenant_id = require_non_empty(
            tenant_id,
            "tenant_id",
        )

        message_id = str(uuid4())

        context = PipelineContext(
            tenant_id=tenant_id,
            correlation_id=(
                correlation_id
                if correlation_id
                else str(uuid4())
            ),
            causation_id=causation_id,
            actor_id=actor_id,
            metadata=dict(
                metadata or {}
            ),
        )

        fingerprint = PipelineMessage.calculate_fingerprint(
            message_id=message_id,
            tenant_id=tenant_id,
            stage=stage,
            kind=kind,
            truth_class=truth_class,
            correlation_id=context.correlation_id,
            causation_id=context.causation_id,
            schema_version="21.1",
        )

        return PipelineMessage(
            message_id=message_id,
            tenant_id=tenant_id,
            stage=stage,
            kind=kind,
            truth_class=truth_class,
            context=context,
            payload=payload,
            fingerprint=fingerprint,
        )


# ============================================================================
# STAGE CONTRACT
# ============================================================================

T = TypeVar("T")


class StageHandler(Protocol):

    @property
    def stage(self) -> LifecycleStage:
        ...

    def handle(
        self,
        message: PipelineMessage,
    ) -> PipelineMessage:
        ...


# ============================================================================
# ADAPTER BETWEEN EXISTING PHASE INTERFACES
# ============================================================================

class CallableStageHandler:
    """
    Thin adapter around an already-existing phase interface.

    It does not implement the underlying security logic.
    """

    def __init__(
        self,
        stage: LifecycleStage,
        handler: Callable[
            [PipelineMessage],
            PipelineMessage,
        ],
    ) -> None:

        if not callable(handler):
            raise Phase21ValidationError(
                "handler must be callable"
            )

        self._stage = stage
        self._handler = handler

    @property
    def stage(self) -> LifecycleStage:
        return self._stage

    def handle(
        self,
        message: PipelineMessage,
    ) -> PipelineMessage:

        if message.tenant_id != (
            message.context.tenant_id
        ):
            raise TenantIsolationError(
                "Message tenant/context mismatch"
            )

        if message.stage != self._stage:
            raise WiringError(
                f"Handler for {self._stage.value} "
                f"received {message.stage.value}"
            )

        result = self._handler(
            message
        )

        if not isinstance(
            result,
            PipelineMessage,
        ):
            raise WiringError(
                "Stage handler must return PipelineMessage"
            )

        if result.tenant_id != message.tenant_id:
            raise TenantIsolationError(
                "Stage handler changed tenant"
            )

        if (
            result.context.correlation_id
            != message.context.correlation_id
        ):
            raise WiringError(
                "Stage handler changed correlation_id"
            )

        return result


# ============================================================================
# PIPELINE STATE
# ============================================================================

@dataclass
class PipelineState:
    correlation_id: str
    tenant_id: str

    current_stage: Optional[LifecycleStage] = None

    completed_stages: Tuple[
        LifecycleStage,
        ...
    ] = ()

    failed_stage: Optional[LifecycleStage] = None

    last_message_id: Optional[str] = None

    started_at: datetime = field(
        default_factory=utc_now
    )

    updated_at: datetime = field(
        default_factory=utc_now
    )

    def mark_completed(
        self,
        stage: LifecycleStage,
        message_id: str,
    ) -> None:

        if (
            self.completed_stages
            and self.completed_stages[-1]
            != stage
        ):
            expected_index = (
                len(self.completed_stages)
            )

            if expected_index < len(
                LIFECYCLE_ORDER
            ):
                expected = LIFECYCLE_ORDER[
                    expected_index
                ]

                if expected != stage:
                    raise InvalidTransitionError(
                        f"Expected {expected.value}, "
                        f"received {stage.value}"
                    )

        self.current_stage = stage

        self.completed_stages = (
            *self.completed_stages,
            stage,
        )

        self.last_message_id = message_id
        self.updated_at = utc_now()


# ============================================================================
# MESSAGE DEDUPLICATION
# ============================================================================

class MessageDeduplicationStore:

    def __init__(self) -> None:
        self._processed: Dict[
            Tuple[str, str],
            datetime,
        ] = {}

        self._lock = Lock()

    def reserve(
        self,
        tenant_id: str,
        message_id: str,
    ) -> bool:

        key = (
            tenant_id,
            message_id,
        )

        with self._lock:
            if key in self._processed:
                return False

            self._processed[key] = utc_now()

            return True

    def contains(
        self,
        tenant_id: str,
        message_id: str,
    ) -> bool:

        return (
            tenant_id,
            message_id,
        ) in self._processed


# ============================================================================
# PIPELINE AUDIT
# ============================================================================

@dataclass(frozen=True)
class PipelineAuditRecord:
    audit_id: str

    tenant_id: str
    correlation_id: str
    message_id: str

    stage: LifecycleStage

    status: MessageStatus

    timestamp: datetime

    fingerprint: str

    error: Optional[str] = None

    def __post_init__(self) -> None:
        require_non_empty(
            self.audit_id,
            "audit_id",
        )

        require_non_empty(
            self.tenant_id,
            "tenant_id",
        )

        require_non_empty(
            self.correlation_id,
            "correlation_id",
        )

        require_non_empty(
            self.message_id,
            "message_id",
        )

        ensure_aware(
            self.timestamp,
            "timestamp",
        )


class PipelineAuditSink(Protocol):

    def record(
        self,
        audit: PipelineAuditRecord,
    ) -> None:
        ...


class InMemoryPipelineAuditSink:

    def __init__(self) -> None:
        self.records = []

        self._lock = Lock()

    def record(
        self,
        audit: PipelineAuditRecord,
    ) -> None:

        with self._lock:
            self.records.append(
                audit
            )

    def for_tenant(
        self,
        tenant_id: str,
    ) -> Tuple[
        PipelineAuditRecord,
        ...
    ]:

        return tuple(
            record
            for record in self.records
            if record.tenant_id == tenant_id
        )


# ============================================================================
# LAYER WIRING
# ============================================================================

class CrossLayerWiring:

    def __init__(
        self,
        handlers: Optional[
            Mapping[
                LifecycleStage,
                StageHandler,
            ]
        ] = None,
    ) -> None:

        self._handlers: Dict[
            LifecycleStage,
            StageHandler,
        ] = dict(
            handlers or {}
        )

    def register(
        self,
        handler: StageHandler,
    ) -> None:

        stage = handler.stage

        if stage in self._handlers:
            raise WiringError(
                f"Stage already wired: {stage.value}"
            )

        self._handlers[stage] = handler

    def get(
        self,
        stage: LifecycleStage,
    ) -> StageHandler:

        handler = self._handlers.get(
            stage
        )

        if handler is None:
            raise StageNotConfiguredError(
                f"No handler configured for "
                f"{stage.value}"
            )

        return handler

    def validate(
        self,
    ) -> Tuple[
        LifecycleStage,
        ...
    ]:

        missing = tuple(
            stage
            for stage in LIFECYCLE_ORDER
            if stage not in self._handlers
        )

        if missing:
            raise WiringError(
                "Pipeline has missing stages: "
                + ", ".join(
                    stage.value
                    for stage in missing
                )
            )

        return LIFECYCLE_ORDER


# ============================================================================
# CROSS-LAYER ORCHESTRATOR
# ============================================================================

class CrossLayerOrchestrator:
    """
    Deterministic lifecycle orchestrator.

    Important:
        The orchestrator does not decide what each security
        engine means. It only moves typed outputs between
        already-existing interfaces.
    """

    def __init__(
        self,
        wiring: CrossLayerWiring,
        *,
        audit_sink: Optional[
            PipelineAuditSink
        ] = None,
        dedup_store: Optional[
            MessageDeduplicationStore
        ] = None,
    ) -> None:

        self.wiring = wiring

        self.audit_sink = (
            audit_sink
            if audit_sink is not None
            else InMemoryPipelineAuditSink()
        )

        self.dedup = (
            dedup_store
            if dedup_store is not None
            else MessageDeduplicationStore()
        )

        self._states: Dict[
            Tuple[str, str],
            PipelineState,
        ] = {}

        self._lock = Lock()

    def start(
        self,
        *,
        tenant_id: str,
        payload: Any,
        kind: MessageKind = MessageKind.OBSERVATION,
        truth_class: Optional[TruthClass] = None,
        actor_id: Optional[str] = None,
    ) -> PipelineMessage:

        if truth_class is None:
            # Resolved at call-time so this binds to the canonical/final
            # TruthClass rather than the generation live when this method
            # was defined.
            truth_class = TruthClass.FACT

        tenant_id = require_non_empty(
            tenant_id,
            "tenant_id",
        )

        message = PipelineMessageFactory.create(
            tenant_id=tenant_id,
            stage=LifecycleStage.OBSERVE,
            kind=kind,
            truth_class=truth_class,
            payload=payload,
            actor_id=actor_id,
        )

        self._initialize_state(
            message
        )

        return message

    def run(
        self,
        message: PipelineMessage,
    ) -> PipelineState:

        self.wiring.validate()

        self._validate_initial_message(
            message
        )

        current = message

        for stage in LIFECYCLE_ORDER:

            if current.stage != stage:
                raise InvalidTransitionError(
                    f"Pipeline expected "
                    f"{stage.value}, got "
                    f"{current.stage.value}"
                )

            current = self._process_stage(
                current
            )

        return self.get_state(
            message.tenant_id,
            message.context.correlation_id,
        )

    def _process_stage(
        self,
        message: PipelineMessage,
    ) -> PipelineMessage:

        if message.tenant_id != (
            message.context.tenant_id
        ):
            raise TenantIsolationError(
                "Cross-layer tenant violation"
            )

        if not self.dedup.reserve(
            message.tenant_id,
            message.message_id,
        ):
            raise DuplicateMessageError(
                f"Message already processed: "
                f"{message.message_id}"
            )

        self._set_current_stage(
            message
        )

        handler = self.wiring.get(
            message.stage
        )

        try:
            result = handler.handle(
                message
            )

            self._validate_stage_output(
                message,
                result,
            )

            self._mark_completed(
                result
            )

            self._audit(
                result,
                MessageStatus.PROCESSED,
            )

            return result

        except Exception as exc:

            self._mark_failed(
                message,
                exc,
            )

            self._audit(
                message,
                MessageStatus.FAILED,
                error=str(exc),
            )

            raise PipelineExecutionError(
                f"Stage {message.stage.value} "
                f"failed: {exc}"
            ) from exc

    def _validate_initial_message(
        self,
        message: PipelineMessage,
    ) -> None:

        if not isinstance(
            message,
            PipelineMessage,
        ):
            raise Phase21ValidationError(
                "Initial input must be PipelineMessage"
            )

        if message.stage != (
            LifecycleStage.OBSERVE
        ):
            raise InvalidTransitionError(
                "Pipeline must begin at OBSERVE"
            )

        if message.tenant_id != (
            message.context.tenant_id
        ):
            raise TenantIsolationError(
                "Initial message tenant mismatch"
            )

    def _validate_stage_output(
        self,
        previous: PipelineMessage,
        current: PipelineMessage,
    ) -> None:

        if current.tenant_id != previous.tenant_id:
            raise TenantIsolationError(
                "Stage output changed tenant"
            )

        if (
            current.context.correlation_id
            != previous.context.correlation_id
        ):
            raise WiringError(
                "Stage output changed correlation ID"
            )

        if current.context.causation_id != (
            previous.message_id
        ):
            raise WiringError(
                "Stage output causation_id must point "
                "to previous message"
            )

        current_index = (
            LIFECYCLE_ORDER.index(
                current.stage
            )
        )

        previous_index = (
            LIFECYCLE_ORDER.index(
                previous.stage
            )
        )

        if current_index != (
            previous_index + 1
        ):
            raise InvalidTransitionError(
                "Pipeline stages must advance exactly "
                "one lifecycle stage at a time"
            )

    def _initialize_state(
        self,
        message: PipelineMessage,
    ) -> None:

        key = (
            message.tenant_id,
            message.context.correlation_id,
        )

        with self._lock:
            if key in self._states:
                raise WiringError(
                    "Correlation ID already initialized"
                )

            self._states[key] = PipelineState(
                correlation_id=(
                    message.context.correlation_id
                ),
                tenant_id=message.tenant_id,
            )

    def _set_current_stage(
        self,
        message: PipelineMessage,
    ) -> None:

        state = self._get_state_internal(
            message.tenant_id,
            message.context.correlation_id,
        )

        state.current_stage = message.stage
        state.updated_at = utc_now()

    def _mark_completed(
        self,
        message: PipelineMessage,
    ) -> None:

        state = self._get_state_internal(
            message.tenant_id,
            message.context.correlation_id,
        )

        state.mark_completed(
            message.stage,
            message.message_id,
        )

    def _mark_failed(
        self,
        message: PipelineMessage,
        error: Exception,
    ) -> None:

        state = self._get_state_internal(
            message.tenant_id,
            message.context.correlation_id,
        )

        state.failed_stage = message.stage
        state.updated_at = utc_now()

    def _get_state_internal(
        self,
        tenant_id: str,
        correlation_id: str,
    ) -> PipelineState:

        key = (
            tenant_id,
            correlation_id,
        )

        state = self._states.get(key)

        if state is None:
            raise WiringError(
                "Pipeline state not found"
            )

        if state.tenant_id != tenant_id:
            raise TenantIsolationError(
                "Pipeline state belongs to another tenant"
            )

        return state

    def get_state(
        self,
        tenant_id: str,
        correlation_id: str,
    ) -> PipelineState:

        return self._get_state_internal(
            require_non_empty(
                tenant_id,
                "tenant_id",
            ),
            require_non_empty(
                correlation_id,
                "correlation_id",
            ),
        )

    def _audit(
        self,
        message: PipelineMessage,
        status: MessageStatus,
        error: Optional[str] = None,
    ) -> None:

        audit = PipelineAuditRecord(
            audit_id=str(uuid4()),
            tenant_id=message.tenant_id,
            correlation_id=(
                message.context.correlation_id
            ),
            message_id=message.message_id,
            stage=message.stage,
            status=status,
            timestamp=utc_now(),
            fingerprint=sha256(
                (
                    message.fingerprint
                    + status.value
                    + (error or "")
                ).encode("utf-8")
            ).hexdigest(),
            error=error,
        )

        self.audit_sink.record(
            audit
        )


# ============================================================================
# PHASE-BOUNDARY FACTORY
# ============================================================================

class Phase21WiringFactory:

    @staticmethod
    def build(
        handlers: Mapping[
            LifecycleStage,
            StageHandler,
        ],
    ) -> CrossLayerWiring:

        wiring = CrossLayerWiring()

        for stage in LIFECYCLE_ORDER:

            handler = handlers.get(
                stage
            )

            if handler is None:
                raise StageNotConfiguredError(
                    f"Missing handler: {stage.value}"
                )

            if handler.stage != stage:
                raise WiringError(
                    f"Handler stage mismatch for "
                    f"{stage.value}"
                )

            wiring.register(
                handler
            )

        wiring.validate()

        return wiring


# ============================================================================
# TEST HANDLERS
#
# These are deterministic test doubles only.
# They do NOT implement any HYDRA security capability.
# ============================================================================

def _test_stage_handler(
    stage: LifecycleStage,
) -> Callable[
    [PipelineMessage],
    PipelineMessage,
]:

    next_index = (
        LIFECYCLE_ORDER.index(stage) + 1
    )

    if next_index >= len(
        LIFECYCLE_ORDER
    ):
        next_stage = stage
    else:
        next_stage = LIFECYCLE_ORDER[
            next_index
        ]

    def handler(
        message: PipelineMessage,
    ) -> PipelineMessage:

        return PipelineMessageFactory.create(
            tenant_id=message.tenant_id,
            stage=next_stage,
            kind=message.kind,
            truth_class=message.truth_class,
            payload=message.payload,
            correlation_id=(
                message.context.correlation_id
            ),
            causation_id=message.message_id,
            actor_id=message.context.actor_id,
        )

    return handler


def _test_wiring() -> CrossLayerWiring:

    handlers = {}

    for stage in LIFECYCLE_ORDER:

        handlers[stage] = CallableStageHandler(
            stage,
            _test_stage_handler(
                stage
            ),
        )

    return Phase21WiringFactory.build(
        handlers
    )


