def test_pipeline_failure_is_audited() -> None:

    def failing_handler(
        message: PipelineMessage,
    ) -> PipelineMessage:

        raise RuntimeError(
            "controlled test failure"
        )

    handlers = {}

    for stage in LIFECYCLE_ORDER:

        if stage == LifecycleStage.OBSERVE:
            handler = CallableStageHandler(
                stage,
                failing_handler,
            )
        else:
            handler = CallableStageHandler(
                stage,
                _test_stage_handler(
                    stage
                ),
            )

        handlers[stage] = handler

    wiring = Phase21WiringFactory.build(
        handlers
    )

    audit = InMemoryPipelineAuditSink()

    orchestrator = CrossLayerOrchestrator(
        wiring,
        audit_sink=audit,
    )

    initial = orchestrator.start(
        tenant_id="tenant-a",
        payload={},
    )

    try:
        orchestrator.run(
            initial
        )
    except PipelineExecutionError:
        pass
    else:
        raise AssertionError(
            "Pipeline failure expected"
        )

    assert len(
        audit.records
    ) == 1

    assert audit.records[0].status == (
        MessageStatus.FAILED
    )


