def run_phase_21_tests() -> Dict[str, Any]:

    passed = 0
    failures = []

    for test in _PHASE_21_TESTS:

        try:
            test()
            passed += 1

        except Exception as exc:

            failures.append(
                {
                    "test": test.__name__,
                    "error": (
                        f"{type(exc).__name__}: "
                        f"{exc}"
                    ),
                }
            )

    return {
        "phase": 21,
        "total": len(
            _PHASE_21_TESTS
        ),
        "passed": passed,
        "failed": len(
            failures
        ),
        "failures": failures,
        "success": not failures,
    }


