def canonicalize(value: Any) -> Any:
    """
    Deterministic representation used only for fingerprints.

    This does not serialize executable objects and does not mutate
    source objects.
    """
    if value is None:
        return None

    if isinstance(value, Enum):
        return value.value

    if isinstance(value, UUID):
        return str(value)

    if isinstance(value, datetime):
        return ensure_aware(value, "datetime").isoformat()

    if isinstance(value, Mapping):
        return {
            str(key): canonicalize(value[key])
            for key in sorted(value.keys(), key=str)
        }

    if isinstance(value, (list, tuple)):
        return [canonicalize(item) for item in value]

    if isinstance(value, (set, frozenset)):
        return sorted(
            (canonicalize(item) for item in value),
            key=lambda item: repr(item),
        )

    if hasattr(value, "__dict__"):
        return canonicalize(vars(value))

    return value




