class Phase22ValidationError(Phase22Error):
    """Invalid Phase 22 integration input."""


class IntegrationBoundaryError(Phase22Error):
    """Integration boundary violation."""


class IntegrationCompatibilityError(Phase22Error):
    """Source/target contract incompatibility."""


class IntegrationTenantIsolationError(Phase22Error):
    """Tenant isolation violation."""


class IntegrationDuplicateError(Phase22Error):
    """Duplicate integration message."""


class IntegrationMappingError(Phase22Error):
    """Failure while mapping a NEXORA object."""


class IntegrationNotRegisteredError(Phase22Error):
    """Requested integration is not registered."""


