@dataclass(frozen=True)
class NEXORACyberEnvelope:
    """
    Generic boundary representation for an existing NEXORA CYBER
    object.

    The integration layer intentionally does not recreate the
    original NEXORA CYBER domain classes.
    """

    object_id: str
    tenant_id: str
    object_kind: NEXORAObjectKind

    schema_name: str
    schema_version: str

    payload: Mapping[str, Any]

    source_system: str
    source_component: str

    correlation_id: str
    causation_id: Optional[str]

    occurred_at: datetime
    received_at: datetime

    provenance: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        require_non_empty(self.object_id, "object_id")
        require_non_empty(self.tenant_id, "tenant_id")
        require_non_empty(self.schema_name, "schema_name")
        require_non_empty(self.schema_version, "schema_version")
        require_non_empty(self.source_system, "source_system")
        require_non_empty(self.source_component, "source_component")
        require_non_empty(self.correlation_id, "correlation_id")

        ensure_aware(self.occurred_at, "occurred_at")
        ensure_aware(self.received_at, "received_at")

        if self.causation_id is not None:
            require_non_empty(self.causation_id, "causation_id")


