# ============================================================
# SCHEMA COMPATIBILITY
# ============================================================

@dataclass(frozen=True)
class SchemaCompatibility:
    schema_name: str
    supported_versions: Tuple[str, ...]

    def __post_init__(self) -> None:
        require_non_empty(self.schema_name, "schema_name")

        if not self.supported_versions:
            raise Phase22ValidationError(
                "supported_versions cannot be empty"
            )

        for version in self.supported_versions:
            require_non_empty(version, "schema_version")

    def supports(self, schema_name: str, version: str) -> bool:
        return (
            schema_name == self.schema_name
            and version in self.supported_versions
        )


# ============================================================
# OBJECT KIND MAPPING
# ============================================================

_NEXORA_TO_HYDRA_KIND = {
    NEXORAObjectKind.ENTITY: HydraObjectKind.CYBER_ENTITY,
    NEXORAObjectKind.EVENT: HydraObjectKind.CYBER_EVENT,
    NEXORAObjectKind.EVIDENCE: HydraObjectKind.CYBER_EVIDENCE,
    NEXORAObjectKind.FINDING: HydraObjectKind.CYBER_FINDING,
    NEXORAObjectKind.INCIDENT: HydraObjectKind.CYBER_INCIDENT,
    NEXORAObjectKind.RISK: HydraObjectKind.CYBER_RISK,
    NEXORAObjectKind.DECISION: HydraObjectKind.CYBER_DECISION,
    NEXORAObjectKind.ACTION: HydraObjectKind.CYBER_ACTION,
    NEXORAObjectKind.APPROVAL: HydraObjectKind.CYBER_APPROVAL,
    NEXORAObjectKind.EXECUTION: HydraObjectKind.CYBER_EXECUTION,
    NEXORAObjectKind.VERIFICATION: HydraObjectKind.CYBER_VERIFICATION,
    NEXORAObjectKind.MEMORY: HydraObjectKind.CYBER_MEMORY,
}


# ============================================================
# PROVENANCE
# ============================================================

@dataclass(frozen=True)
class IntegrationProvenance:
    original_object_id: str
    original_tenant_id: str

    source_system: str
    source_component: str

    source_schema: str
    source_schema_version: str

    original_correlation_id: str
    original_causation_id: Optional[str]

    occurred_at: datetime
    integrated_at: datetime

    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        require_non_empty(
            self.original_object_id,
            "original_object_id",
        )
        require_non_empty(
            self.original_tenant_id,
            "original_tenant_id",
        )
        require_non_empty(
            self.source_system,
            "source_system",
        )
        require_non_empty(
            self.source_component,
            "source_component",
        )
        require_non_empty(
            self.source_schema,
            "source_schema",
        )
        require_non_empty(
            self.source_schema_version,
            "source_schema_version",
        )
        require_non_empty(
            self.original_correlation_id,
            "original_correlation_id",
        )

        ensure_aware(self.occurred_at, "occurred_at")
        ensure_aware(self.integrated_at, "integrated_at")


# ============================================================
# NEXORA -> HYDRA MAPPER
# ============================================================

class NEXORAToHydraMapper(Protocol):
    def map(
        self,
        envelope: NEXORACyberEnvelope,
        context: NEXORACyberIntegrationContext,
    ) -> HydraIntegrationEnvelope:
        ...


class DefaultNEXORAToHydraMapper:
    """
    Generic safe mapper.

    It preserves the source payload rather than guessing semantics.
    """

    def map(
        self,
        envelope: NEXORACyberEnvelope,
        context: NEXORACyberIntegrationContext,
    ) -> HydraIntegrationEnvelope:

        if envelope.tenant_id != context.tenant_id:
            raise IntegrationTenantIsolationError(
                "NEXORA envelope tenant does not match integration context"
            )

        if envelope.correlation_id != context.correlation_id:
            raise IntegrationBoundaryError(
                "NEXORA correlation ID does not match integration context"
            )

        try:
            hydra_kind = _NEXORA_TO_HYDRA_KIND[
                envelope.object_kind
            ]
        except KeyError as exc:
            raise IntegrationMappingError(
                f"Unsupported NEXORA object kind: "
                f"{envelope.object_kind}"
            ) from exc

        provenance = IntegrationProvenance(
            original_object_id=envelope.object_id,
            original_tenant_id=envelope.tenant_id,
            source_system=envelope.source_system,
            source_component=envelope.source_component,
            source_schema=envelope.schema_name,
            source_schema_version=envelope.schema_version,
            original_correlation_id=envelope.correlation_id,
            original_causation_id=envelope.causation_id,
            occurred_at=envelope.occurred_at,
            integrated_at=utc_now(),
            metadata=dict(envelope.provenance),
        )

        provenance_payload = canonicalize(provenance)

        message_id = str(uuid4())

        fingerprint = stable_fingerprint(
            context.integration_id,
            envelope.object_id,
            envelope.tenant_id,
            envelope.object_kind,
            envelope.schema_name,
            envelope.schema_version,
            envelope.payload,
            envelope.correlation_id,
            envelope.causation_id,
        )

        return HydraIntegrationEnvelope(
            message_id=message_id,
            tenant_id=envelope.tenant_id,
            object_id=envelope.object_id,
            object_kind=hydra_kind,
            schema_name=envelope.schema_name,
            schema_version=envelope.schema_version,
            payload=dict(envelope.payload),
            source_system=envelope.source_system,
            source_component=envelope.source_component,
            correlation_id=envelope.correlation_id,
            causation_id=envelope.causation_id,
            occurred_at=envelope.occurred_at,
            received_at=utc_now(),
            provenance=provenance_payload,
            integration_id=context.integration_id,
            fingerprint=fingerprint,
        )


# ============================================================
# HYDRA -> NEXORA MAPPING
# ============================================================

_HYDRA_TO_NEXORA_KIND = {
    value: key
    for key, value in _NEXORA_TO_HYDRA_KIND.items()
}


class HydraToNEXORAMapper(Protocol):
    def map(
        self,
        envelope: HydraIntegrationEnvelope,
        context: NEXORACyberIntegrationContext,
    ) -> NEXORACyberEnvelope:
        ...


class DefaultHydraToNEXORAMapper:
    """
    Reverse compatibility mapper.

    It does not invent NEXORA-specific domain semantics.
    """

    def map(
        self,
        envelope: HydraIntegrationEnvelope,
        context: NEXORACyberIntegrationContext,
    ) -> NEXORACyberEnvelope:

        if envelope.tenant_id != context.tenant_id:
            raise IntegrationTenantIsolationError(
                "HYDRA envelope tenant does not match integration context"
            )

        if envelope.correlation_id != context.correlation_id:
            raise IntegrationBoundaryError(
                "HYDRA correlation ID does not match integration context"
            )

        try:
            nexora_kind = _HYDRA_TO_NEXORA_KIND[
                envelope.object_kind
            ]
        except KeyError as exc:
            raise IntegrationMappingError(
                f"Unsupported HYDRA object kind: "
                f"{envelope.object_kind}"
            ) from exc

        provenance = dict(envelope.provenance)

        return NEXORACyberEnvelope(
            object_id=envelope.object_id,
            tenant_id=envelope.tenant_id,
            object_kind=nexora_kind,
            schema_name=envelope.schema_name,
            schema_version=envelope.schema_version,
            payload=dict(envelope.payload),
            source_system=envelope.source_system,
            source_component=envelope.source_component,
            correlation_id=envelope.correlation_id,
            causation_id=envelope.causation_id,
            occurred_at=envelope.occurred_at,
            received_at=utc_now(),
            provenance=provenance,
        )


# ============================================================
# IDEMPOTENCY BOUNDARY
# ============================================================

class IntegrationDeduplicationStore(Protocol):
    def reserve(
        self,
        tenant_id: str,
        fingerprint: str,
    ) -> bool:
        ...

    def contains(
        self,
        tenant_id: str,
        fingerprint: str,
    ) -> bool:
        ...


class InMemoryIntegrationDeduplicationStore:
    """
    Phase 22 boundary only.

    This is deliberately not persistence/recovery.
    """

    def __init__(self) -> None:
        self._entries: set[tuple[str, str]] = set()

    def reserve(
        self,
        tenant_id: str,
        fingerprint: str,
    ) -> bool:

        key = (tenant_id, fingerprint)

        if key in self._entries:
            return False

        self._entries.add(key)
        return True

    def contains(
        self,
        tenant_id: str,
        fingerprint: str,
    ) -> bool:

        return (tenant_id, fingerprint) in self._entries


# ============================================================
# INTEGRATION CAPABILITIES
# ============================================================

@dataclass(frozen=True)
class IntegrationCapabilities:
    inbound: bool
    outbound: bool

    supported_objects: Tuple[HydraObjectKind, ...]

    supported_schema_names: Tuple[str, ...]

    preserves_tenant: bool
    preserves_correlation: bool
    preserves_causation: bool
    preserves_provenance: bool
    supports_idempotency: bool

    def __post_init__(self) -> None:
        if not self.inbound and not self.outbound:
            raise Phase22ValidationError(
                "Integration must support inbound or outbound flow"
            )

        if not self.supported_objects:
            raise Phase22ValidationError(
                "supported_objects cannot be empty"
            )

        if not self.supported_schema_names:
            raise Phase22ValidationError(
                "supported_schema_names cannot be empty"
            )


# ============================================================
# INTEGRATION DEFINITION
# ============================================================

@dataclass(frozen=True)
class NEXORACyberIntegrationDefinition:
    integration_id: str
    name: str
    version: str

    status: IntegrationStatus

    compatibility: Tuple[SchemaCompatibility, ...]

    capabilities: IntegrationCapabilities

    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        require_non_empty(
            self.integration_id,
            "integration_id",
        )
        require_non_empty(self.name, "name")
        require_non_empty(self.version, "version")

        if not self.compatibility:
            raise Phase22ValidationError(
                "compatibility cannot be empty"
            )


