def run_phase_22_tests() -> Dict[str, Any]:

    tests = [
        test_factory_creates_valid_integration,
        test_tenant_is_preserved,
        test_cross_tenant_message_is_rejected,
        test_correlation_is_preserved,
        test_correlation_mismatch_is_rejected,
        test_causation_is_preserved,
        test_object_kind_is_mapped,
        test_payload_is_not_silently_changed,
        test_provenance_is_preserved,
        test_schema_version_is_checked,
        test_duplicate_message_is_rejected,
        test_different_objects_are_not_deduplicated,
        test_reverse_mapping_preserves_identity,
        test_reverse_mapping_preserves_payload,
        test_registry_registration,
        test_registry_rejects_duplicate_registration,
        test_handoff_to_phase_21_boundary,
        test_handoff_preserves_tenant,
        test_handoff_preserves_correlation,
        test_fingerprint_is_deterministic,
        test_integration_result_contains_correct_direction,
        test_missing_registration_is_rejected,
    ]

    passed = 0
    failed = 0
    failures: list[Dict[str, str]] = []

    for test in tests:
        try:
            test()
            passed += 1
        except Exception as exc:
            failed += 1
            failures.append(
                {
                    "test": test.__name__,
                    "error": repr(exc),
                }
            )

    return {
        "phase": 22,
        "total": len(tests),
        "passed": passed,
        "failed": failed,
        "success": failed == 0,
        "failures": failures,
    }


