# ============================================================
# HELPERS
# ============================================================







def dt_to_text(value: datetime) -> str:
    return ensure_aware(value, "datetime").isoformat()


def text_to_dt(value: str) -> datetime:
    parsed = datetime.fromisoformat(value)

    if parsed.tzinfo is None:
        raise Phase23PersistenceError(
            "Persisted datetime is not timezone-aware"
        )

    return parsed






def fingerprint(*values: Any) -> str:
    return sha256(
        canonical_json(values).encode("utf-8")
    ).hexdigest()


# ============================================================
# ERRORS
# ============================================================

class Phase23Error(Exception):
    pass


class Phase23ValidationError(Phase23Error):
    pass


class Phase23PersistenceError(Phase23Error):
    pass


class Phase23NotFoundError(Phase23Error):
    pass


class Phase23TenantIsolationError(Phase23Error):
    pass


class Phase23IntegrityError(Phase23Error):
    pass


class Phase23TransactionError(Phase23Error):
    pass


class Phase23RecoveryError(Phase23Error):
    pass


class Phase23DuplicateError(Phase23Error):
    pass


# ============================================================
# RECORD TYPES
# ============================================================

class PersistenceRecordType(str, Enum):
    INTEGRATION_MESSAGE = "INTEGRATION_MESSAGE"
    PIPELINE_STATE = "PIPELINE_STATE"
    CHECKPOINT = "CHECKPOINT"
    IDEMPOTENCY = "IDEMPOTENCY"


class PersistenceStatus(str, Enum):
    ACTIVE = "ACTIVE"
    COMPLETED = "COMPLETED"
    FAILED = "FAILED"
    RECOVERED = "RECOVERED"


class RecoveryStatus(str, Enum):
    NOT_REQUIRED = "NOT_REQUIRED"
    RECOVERABLE = "RECOVERABLE"
    RECOVERED = "RECOVERED"
    BLOCKED = "BLOCKED"


# ============================================================
# DURABLE RECORD
# ============================================================

@dataclass(frozen=True)
class DurableRecord:
    record_id: str
    tenant_id: str
    record_type: PersistenceRecordType

    aggregate_id: str
    correlation_id: str

    payload: Mapping[str, Any]

    status: PersistenceStatus

    created_at: datetime
    updated_at: datetime

    fingerprint: str

    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        require_non_empty(self.record_id, "record_id")
        require_non_empty(self.tenant_id, "tenant_id")
        require_non_empty(self.aggregate_id, "aggregate_id")
        require_non_empty(self.correlation_id, "correlation_id")
        require_non_empty(self.fingerprint, "fingerprint")

        ensure_aware(self.created_at, "created_at")
        ensure_aware(self.updated_at, "updated_at")


# ============================================================
# PIPELINE CHECKPOINT
# ============================================================

@dataclass(frozen=True)
class PersistenceCheckpoint:
    checkpoint_id: str

    tenant_id: str
    pipeline_id: str
    correlation_id: str

    current_stage: str
    completed_stages: Tuple[str, ...]

    failed_stage: Optional[str]

    last_message_id: Optional[str]

    checkpoint_sequence: int

    state_payload: Mapping[str, Any]

    created_at: datetime

    fingerprint: str

    def __post_init__(self) -> None:
        require_non_empty(
            self.checkpoint_id,
            "checkpoint_id",
        )
        require_non_empty(
            self.tenant_id,
            "tenant_id",
        )
        require_non_empty(
            self.pipeline_id,
            "pipeline_id",
        )
        require_non_empty(
            self.correlation_id,
            "correlation_id",
        )
        require_non_empty(
            self.current_stage,
            "current_stage",
        )

        if self.checkpoint_sequence < 0:
            raise Phase23ValidationError(
                "checkpoint_sequence cannot be negative"
            )

        ensure_aware(self.created_at, "created_at")
        require_non_empty(
            self.fingerprint,
            "fingerprint",
        )


# ============================================================
# RECOVERY RECORD
