# ============================================================
# SQLITE STORE
# ============================================================

class SQLitePersistenceStore:

    def __init__(
        self,
        database_path: str | Path,
    ) -> None:

        self.database_path = str(database_path)

        self._lock = threading.RLock()

        self._initialize()

        # [auto-repair] SQLite files were created with whatever the
        # process umask allows (typically 644/755 -- world-readable)
        # with nothing restricting it anywhere in this class. This is
        # the one persistence class in this file with no ":memory:"
        # default, so it's always backed by a real file on disk.
        try:
            os.chmod(self.database_path, 0o600)
            parent_dir = Path(self.database_path).parent
            if str(parent_dir) not in ("", "."):
                os.chmod(parent_dir, 0o700)
        except OSError:
            pass

    # --------------------------------------------------------
    # CONNECTION
    # --------------------------------------------------------

    @contextmanager
    def _connection(self) -> Iterator[sqlite3.Connection]:

        connection = sqlite3.connect(
            self.database_path,
            timeout=30.0,
            isolation_level=None,
            check_same_thread=False,
        )

        connection.row_factory = sqlite3.Row

        try:
            yield connection
        finally:
            connection.close()

    # --------------------------------------------------------
    # INITIALIZATION
    # --------------------------------------------------------

    def _initialize(self) -> None:

        parent = Path(
            self.database_path
        ).parent

        if str(parent) not in ("", "."):
            parent.mkdir(
                parents=True,
                exist_ok=True,
            )

        with self._lock:
            with self._connection() as connection:

                connection.execute(
                    "PRAGMA foreign_keys = ON"
                )

                connection.execute(
                    """
                    CREATE TABLE IF NOT EXISTS durable_records (
                        record_id TEXT PRIMARY KEY,
                        tenant_id TEXT NOT NULL,
                        record_type TEXT NOT NULL,
                        aggregate_id TEXT NOT NULL,
                        correlation_id TEXT NOT NULL,
                        payload_json TEXT NOT NULL,
                        status TEXT NOT NULL,
                        created_at TEXT NOT NULL,
                        updated_at TEXT NOT NULL,
                        fingerprint TEXT NOT NULL,
                        metadata_json TEXT NOT NULL
                    )
                    """
                )

                connection.execute(
                    """
                    CREATE INDEX IF NOT EXISTS
                    idx_durable_tenant_type
                    ON durable_records (
                        tenant_id,
                        record_type
                    )
                    """
                )

                connection.execute(
                    """
                    CREATE INDEX IF NOT EXISTS
                    idx_durable_tenant_aggregate
                    ON durable_records (
                        tenant_id,
                        aggregate_id
                    )
                    """
                )

                connection.execute(
                    """
                    CREATE TABLE IF NOT EXISTS checkpoints (
                        checkpoint_id TEXT PRIMARY KEY,
                        tenant_id TEXT NOT NULL,
                        pipeline_id TEXT NOT NULL,
                        correlation_id TEXT NOT NULL,
                        current_stage TEXT NOT NULL,
                        completed_stages_json TEXT NOT NULL,
                        failed_stage TEXT,
                        last_message_id TEXT,
                        checkpoint_sequence INTEGER NOT NULL,
                        state_payload_json TEXT NOT NULL,
                        created_at TEXT NOT NULL,
                        fingerprint TEXT NOT NULL
                    )
                    """
                )

                connection.execute(
                    """
                    CREATE INDEX IF NOT EXISTS
                    idx_checkpoint_pipeline
                    ON checkpoints (
                        tenant_id,
                        pipeline_id,
                        checkpoint_sequence
                    )
                    """
                )

                connection.execute(
                    """
                    CREATE TABLE IF NOT EXISTS idempotency_keys (
                        tenant_id TEXT NOT NULL,
                        idempotency_key TEXT NOT NULL,
                        correlation_id TEXT NOT NULL,
                        created_at TEXT NOT NULL,
                        PRIMARY KEY (
                            tenant_id,
                            idempotency_key
                        )
                    )
                    """
                )

    # --------------------------------------------------------
    # TRANSACTION
    # --------------------------------------------------------

    @contextmanager
    def transaction(
        self,
    ) -> Iterator[sqlite3.Connection]:

        with self._lock:
            with self._connection() as connection:

                try:
                    connection.execute(
                        "BEGIN IMMEDIATE"
                    )

                    yield connection

                    connection.execute(
                        "COMMIT"
                    )

                except Exception as exc:

                    try:
                        connection.execute(
                            "ROLLBACK"
                        )
                    except sqlite3.Error:
                        pass

                    raise Phase23TransactionError(
                        "Persistence transaction failed"
                    ) from exc

    # --------------------------------------------------------
    # DURABLE RECORD
    # --------------------------------------------------------

    def save_record(
        self,
        record: DurableRecord,
    ) -> None:

        if not record.tenant_id:
            raise Phase23TenantIsolationError(
                "Record tenant cannot be empty"
            )

        expected = fingerprint(
            record.record_id,
            record.tenant_id,
            record.record_type,
            record.aggregate_id,
            record.correlation_id,
            record.payload,
            record.status,
            record.created_at,
            record.updated_at,
            record.metadata,
        )

        if expected != record.fingerprint:
            raise Phase23IntegrityError(
                "Durable record fingerprint mismatch"
            )

        with self.transaction() as connection:

            try:
                connection.execute(
                    """
                    INSERT INTO durable_records (
                        record_id,
                        tenant_id,
                        record_type,
                        aggregate_id,
                        correlation_id,
                        payload_json,
                        status,
                        created_at,
                        updated_at,
                        fingerprint,
                        metadata_json
                    )
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        record.record_id,
                        record.tenant_id,
                        record.record_type.value,
                        record.aggregate_id,
                        record.correlation_id,
                        canonical_json(record.payload),
                        record.status.value,
                        dt_to_text(record.created_at),
                        dt_to_text(record.updated_at),
                        record.fingerprint,
                        canonical_json(record.metadata),
                    ),
                )

            except sqlite3.IntegrityError as exc:
                raise Phase23DuplicateError(
                    f"Record already exists: {record.record_id}"
                ) from exc

    def get_record(
        self,
        tenant_id: str,
        record_id: str,
    ) -> DurableRecord:

        require_non_empty(
            tenant_id,
            "tenant_id",
        )

        require_non_empty(
            record_id,
            "record_id",
        )

        with self._lock:
            with self._connection() as connection:

                row = connection.execute(
                    """
                    SELECT *
                    FROM durable_records
                    WHERE tenant_id = ?
                      AND record_id = ?
                    """,
                    (
                        tenant_id,
                        record_id,
                    ),
                ).fetchone()

        if row is None:
            raise Phase23NotFoundError(
                f"Record not found: {record_id}"
            )

        record = DurableRecord(
            record_id=row["record_id"],
            tenant_id=row["tenant_id"],
            record_type=PersistenceRecordType(
                row["record_type"]
            ),
            aggregate_id=row["aggregate_id"],
            correlation_id=row["correlation_id"],
            payload=json.loads(
                row["payload_json"]
            ),
            status=PersistenceStatus(
                row["status"]
            ),
            created_at=text_to_dt(
                row["created_at"]
            ),
            updated_at=text_to_dt(
                row["updated_at"]
            ),
            fingerprint=row["fingerprint"],
            metadata=json.loads(
                row["metadata_json"]
            ),
        )

        expected = fingerprint(
            record.record_id,
            record.tenant_id,
            record.record_type,
            record.aggregate_id,
            record.correlation_id,
            record.payload,
            record.status,
            record.created_at,
            record.updated_at,
            record.metadata,
        )

        if expected != record.fingerprint:
            raise Phase23IntegrityError(
                f"Integrity check failed for {record_id}"
            )

        if record.tenant_id != tenant_id:
            raise Phase23TenantIsolationError(
                "Tenant mismatch during record retrieval"
            )

        return record

    # --------------------------------------------------------
    # CHECKPOINT
    # --------------------------------------------------------

    def save_checkpoint(
        self,
        checkpoint: PersistenceCheckpoint,
    ) -> None:

        expected = fingerprint(
            checkpoint.checkpoint_id,
            checkpoint.tenant_id,
            checkpoint.pipeline_id,
            checkpoint.correlation_id,
            checkpoint.current_stage,
            checkpoint.completed_stages,
            checkpoint.failed_stage,
            checkpoint.last_message_id,
            checkpoint.checkpoint_sequence,
            checkpoint.state_payload,
            checkpoint.created_at,
        )

        if expected != checkpoint.fingerprint:
            raise Phase23IntegrityError(
                "Checkpoint fingerprint mismatch"
            )

        with self.transaction() as connection:

            connection.execute(
                """
                INSERT INTO checkpoints (
                    checkpoint_id,
                    tenant_id,
                    pipeline_id,
                    correlation_id,
                    current_stage,
                    completed_stages_json,
                    failed_stage,
                    last_message_id,
                    checkpoint_sequence,
                    state_payload_json,
                    created_at,
                    fingerprint
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    checkpoint.checkpoint_id,
                    checkpoint.tenant_id,
                    checkpoint.pipeline_id,
                    checkpoint.correlation_id,
                    checkpoint.current_stage,
                    canonical_json(
                        checkpoint.completed_stages
                    ),
                    checkpoint.failed_stage,
                    checkpoint.last_message_id,
                    checkpoint.checkpoint_sequence,
                    canonical_json(
                        checkpoint.state_payload
                    ),
                    dt_to_text(
                        checkpoint.created_at
                    ),
                    checkpoint.fingerprint,
                ),
            )

    def get_latest_checkpoint(
        self,
        tenant_id: str,
        pipeline_id: str,
    ) -> Optional[PersistenceCheckpoint]:

        require_non_empty(
            tenant_id,
            "tenant_id",
        )

        require_non_empty(
            pipeline_id,
            "pipeline_id",
        )

        with self._lock:
            with self._connection() as connection:

                row = connection.execute(
                    """
                    SELECT *
                    FROM checkpoints
                    WHERE tenant_id = ?
                      AND pipeline_id = ?
                    ORDER BY checkpoint_sequence DESC
                    LIMIT 1
                    """,
                    (
                        tenant_id,
                        pipeline_id,
                    ),
                ).fetchone()

        if row is None:
            return None

        checkpoint = PersistenceCheckpoint(
            checkpoint_id=row["checkpoint_id"],
            tenant_id=row["tenant_id"],
            pipeline_id=row["pipeline_id"],
            correlation_id=row["correlation_id"],
            current_stage=row["current_stage"],
            completed_stages=tuple(
                json.loads(
                    row["completed_stages_json"]
                )
            ),
            failed_stage=row["failed_stage"],
            last_message_id=row["last_message_id"],
            checkpoint_sequence=row[
                "checkpoint_sequence"
            ],
            state_payload=json.loads(
                row["state_payload_json"]
            ),
            created_at=text_to_dt(
                row["created_at"]
            ),
            fingerprint=row["fingerprint"],
        )

        expected = fingerprint(
            checkpoint.checkpoint_id,
            checkpoint.tenant_id,
            checkpoint.pipeline_id,
            checkpoint.correlation_id,
            checkpoint.current_stage,
            checkpoint.completed_stages,
            checkpoint.failed_stage,
            checkpoint.last_message_id,
            checkpoint.checkpoint_sequence,
            checkpoint.state_payload,
            checkpoint.created_at,
        )

        if expected != checkpoint.fingerprint:
            raise Phase23IntegrityError(
                "Stored checkpoint integrity verification failed"
            )

        if checkpoint.tenant_id != tenant_id:
            raise Phase23TenantIsolationError(
                "Checkpoint tenant mismatch"
            )

        return checkpoint

    # --------------------------------------------------------
    # IDEMPOTENCY
    # --------------------------------------------------------

    def reserve_idempotency(
        self,
        tenant_id: str,
        key: str,
        correlation_id: str,
    ) -> bool:

        require_non_empty(
            tenant_id,
            "tenant_id",
        )

        require_non_empty(
            key,
            "key",
        )

        require_non_empty(
            correlation_id,
            "correlation_id",
        )

        with self.transaction() as connection:

            try:
                connection.execute(
                    """
                    INSERT INTO idempotency_keys (
                        tenant_id,
                        idempotency_key,
                        correlation_id,
                        created_at
                    )
                    VALUES (?, ?, ?, ?)
                    """,
                    (
                        tenant_id,
                        key,
                        correlation_id,
                        dt_to_text(utc_now()),
                    ),
                )

                return True

            except sqlite3.IntegrityError:
                return False

    # --------------------------------------------------------
    # RECOVERY QUERIES
    # --------------------------------------------------------

    def list_recoverable_checkpoints(
        self,
        tenant_id: str,
    ) -> Tuple[PersistenceCheckpoint, ...]:

        require_non_empty(
            tenant_id,
            "tenant_id",
        )

        with self._lock:
            with self._connection() as connection:

                rows = connection.execute(
                    """
                    SELECT *
                    FROM checkpoints
                    WHERE tenant_id = ?
                      AND failed_stage IS NOT NULL
                    ORDER BY checkpoint_sequence DESC
                    """,
                    (
                        tenant_id,
                    ),
                ).fetchall()

        result = []

        for row in rows:

            checkpoint = PersistenceCheckpoint(
                checkpoint_id=row["checkpoint_id"],
                tenant_id=row["tenant_id"],
                pipeline_id=row["pipeline_id"],
                correlation_id=row["correlation_id"],
                current_stage=row["current_stage"],
                completed_stages=tuple(
                    json.loads(
                        row["completed_stages_json"]
                    )
                ),
                failed_stage=row["failed_stage"],
                last_message_id=row[
                    "last_message_id"
                ],
                checkpoint_sequence=row[
                    "checkpoint_sequence"
                ],
                state_payload=json.loads(
                    row["state_payload_json"]
                ),
                created_at=text_to_dt(
                    row["created_at"]
                ),
                fingerprint=row["fingerprint"],
            )

            expected = fingerprint(
                checkpoint.checkpoint_id,
                checkpoint.tenant_id,
                checkpoint.pipeline_id,
                checkpoint.correlation_id,
                checkpoint.current_stage,
                checkpoint.completed_stages,
                checkpoint.failed_stage,
                checkpoint.last_message_id,
                checkpoint.checkpoint_sequence,
                checkpoint.state_payload,
                checkpoint.created_at,
            )

            if expected != checkpoint.fingerprint:
                raise Phase23IntegrityError(
                    f"Corrupted checkpoint: "
                    f"{checkpoint.checkpoint_id}"
                )

            result.append(checkpoint)

        return tuple(result)


# ============================================================
# CHECKPOINT MANAGER
# ============================================================

class CheckpointManager:

    def __init__(
        self,
        store: PersistencePort,
    ) -> None:
        self._store = store

    def create_checkpoint(
        self,
        tenant_id: str,
        pipeline_id: str,
        correlation_id: str,
        current_stage: str,
        completed_stages: Sequence[str],
        failed_stage: Optional[str],
        last_message_id: Optional[str],
        checkpoint_sequence: int,
        state_payload: Mapping[str, Any],
    ) -> PersistenceCheckpoint:

        created_at = utc_now()

        checkpoint_id = str(uuid4())

        checkpoint_fingerprint = fingerprint(
            checkpoint_id,
            tenant_id,
            pipeline_id,
            correlation_id,
            current_stage,
            tuple(completed_stages),
            failed_stage,
            last_message_id,
            checkpoint_sequence,
            state_payload,
            created_at,
        )

        return PersistenceCheckpoint(
            checkpoint_id=checkpoint_id,
            tenant_id=tenant_id,
            pipeline_id=pipeline_id,
            correlation_id=correlation_id,
            current_stage=current_stage,
            completed_stages=tuple(
                completed_stages
            ),
            failed_stage=failed_stage,
            last_message_id=last_message_id,
            checkpoint_sequence=checkpoint_sequence,
            state_payload=dict(state_payload),
            created_at=created_at,
            fingerprint=checkpoint_fingerprint,
        )

    def persist_checkpoint(
        self,
        checkpoint: PersistenceCheckpoint,
    ) -> None:

        self._store.save_checkpoint(
            checkpoint
        )


# ============================================================
# RECOVERY ENGINE
# ============================================================

class RecoveryEngine:

    def __init__(
        self,
        store: SQLitePersistenceStore,
    ) -> None:

        self._store = store

    def inspect(
        self,
        tenant_id: str,
        pipeline_id: str,
    ) -> RecoveryRecord:

        checkpoint = self._store.get_latest_checkpoint(
            tenant_id,
            pipeline_id,
        )

        if checkpoint is None:

            return RecoveryRecord(
                recovery_id=str(uuid4()),
                tenant_id=tenant_id,
                pipeline_id=pipeline_id,
                correlation_id="unknown",
                checkpoint_id="none",
                status=RecoveryStatus.NOT_REQUIRED,
                recovered_stage=None,
                recovered_message_id=None,
                started_at=utc_now(),
                completed_at=utc_now(),
                reason="No checkpoint exists",
            )

        if checkpoint.tenant_id != tenant_id:
            raise Phase23TenantIsolationError(
                "Recovery checkpoint belongs to another tenant"
            )

        recoverable = (
            checkpoint.failed_stage is not None
        )

        return RecoveryRecord(
            recovery_id=str(uuid4()),
            tenant_id=tenant_id,
            pipeline_id=pipeline_id,
            correlation_id=checkpoint.correlation_id,
            checkpoint_id=checkpoint.checkpoint_id,
            status=(
                RecoveryStatus.RECOVERABLE
                if recoverable
                else RecoveryStatus.NOT_REQUIRED
            ),
            recovered_stage=(
                checkpoint.current_stage
                if recoverable
                else None
            ),
            recovered_message_id=(
                checkpoint.last_message_id
                if recoverable
                else None
            ),
            started_at=utc_now(),
            completed_at=utc_now(),
            reason=(
                "Failed checkpoint available for recovery"
                if recoverable
                else "Latest checkpoint is not failed"
            ),
        )

    def recover_checkpoint(
        self,
        tenant_id: str,
        checkpoint_id: str,
    ) -> PersistenceCheckpoint:

        require_non_empty(
            tenant_id,
            "tenant_id",
        )

        require_non_empty(
            checkpoint_id,
            "checkpoint_id",
        )

        # SQLitePersistenceStore intentionally exposes
        # tenant-scoped retrieval only through pipeline lookup.
        # Therefore recovery validates the tenant before returning
        # any checkpoint.
        checkpoints = (
            self._store.list_recoverable_checkpoints(
                tenant_id
            )
        )

        for checkpoint in checkpoints:

            if checkpoint.checkpoint_id == checkpoint_id:

                if checkpoint.tenant_id != tenant_id:
                    raise Phase23TenantIsolationError(
                        "Checkpoint tenant mismatch"
                    )

                return checkpoint

        raise Phase23RecoveryError(
            f"Recoverable checkpoint not found: "
            f"{checkpoint_id}"
        )


# ============================================================
# DURABLE RECORD FACTORY
# ============================================================

class DurableRecordFactory:

    @staticmethod
    def create(
        tenant_id: str,
        record_type: PersistenceRecordType,
        aggregate_id: str,
        correlation_id: str,
        payload: Mapping[str, Any],
        status: PersistenceStatus = PersistenceStatus.ACTIVE,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> DurableRecord:

        now = utc_now()
        record_id = str(uuid4())

        metadata_dict = dict(
            metadata or {}
        )

        record_fingerprint = fingerprint(
            record_id,
            tenant_id,
            record_type,
            aggregate_id,
            correlation_id,
            payload,
            status,
            now,
            now,
            metadata_dict,
        )

        return DurableRecord(
            record_id=record_id,
            tenant_id=tenant_id,
            record_type=record_type,
            aggregate_id=aggregate_id,
            correlation_id=correlation_id,
            payload=dict(payload),
            status=status,
            created_at=now,
            updated_at=now,
            fingerprint=record_fingerprint,
            metadata=metadata_dict,
        )


# ============================================================
# PERSISTENCE SERVICE
# ============================================================

class PersistenceService:

    def __init__(
        self,
        store: SQLitePersistenceStore,
    ) -> None:

        self._store = store

    def persist_integration_message(
        self,
        tenant_id: str,
        message_id: str,
        correlation_id: str,
        payload: Mapping[str, Any],
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> DurableRecord:

        record = DurableRecordFactory.create(
            tenant_id=tenant_id,
            record_type=(
                PersistenceRecordType
                .INTEGRATION_MESSAGE
            ),
            aggregate_id=message_id,
            correlation_id=correlation_id,
            payload=payload,
            metadata=metadata,
        )

        self._store.save_record(record)

        return record

    def persist_pipeline_state(
        self,
        tenant_id: str,
        pipeline_id: str,
        correlation_id: str,
        payload: Mapping[str, Any],
        status: PersistenceStatus,
    ) -> DurableRecord:

        record = DurableRecordFactory.create(
            tenant_id=tenant_id,
            record_type=(
                PersistenceRecordType.PIPELINE_STATE
            ),
            aggregate_id=pipeline_id,
            correlation_id=correlation_id,
            payload=payload,
            status=status,
        )

        self._store.save_record(record)

        return record

    def reserve_message(
        self,
        tenant_id: str,
        message_fingerprint: str,
        correlation_id: str,
    ) -> bool:

        return self._store.reserve_idempotency(
            tenant_id=tenant_id,
            key=message_fingerprint,
            correlation_id=correlation_id,
        )


# ============================================================
# PERSISTENCE-AWARE PIPELINE BOUNDARY
# ============================================================

class PersistablePipelineState(Protocol):

    tenant_id: str
    pipeline_id: str
    correlation_id: str
    current_stage: str
    completed_stages: Sequence[str]
    failed_stage: Optional[str]
    last_message_id: Optional[str]


class PipelinePersistenceBridge:

    def __init__(
        self,
        checkpoint_manager: CheckpointManager,
    ) -> None:

        self._checkpoint_manager = (
            checkpoint_manager
        )

    def checkpoint(
        self,
        state: PersistablePipelineState,
        sequence: int,
        state_payload: Mapping[str, Any],
    ) -> PersistenceCheckpoint:

        checkpoint = (
            self._checkpoint_manager
            .create_checkpoint(
                tenant_id=state.tenant_id,
                pipeline_id=state.pipeline_id,
                correlation_id=state.correlation_id,
                current_stage=state.current_stage,
                completed_stages=state.completed_stages,
                failed_stage=state.failed_stage,
                last_message_id=state.last_message_id,
                checkpoint_sequence=sequence,
                state_payload=state_payload,
            )
        )

        self._checkpoint_manager.persist_checkpoint(
            checkpoint
        )

        return checkpoint


# ============================================================
# TEST FIXTURES
# ============================================================

@dataclass
class _TestPipelineState:

    tenant_id: str
    pipeline_id: str
    correlation_id: str

    current_stage: str = "OBSERVE"

    completed_stages: list[str] = field(
        default_factory=list
    )

    failed_stage: Optional[str] = None

    last_message_id: Optional[str] = None


def _temp_db() -> str:
    fd, path = tempfile.mkstemp(
        suffix=".sqlite3"
    )
    os.close(fd)

    try:
        os.unlink(path)
    except FileNotFoundError:
        pass

    return path


