def test_record_integrity_is_verified() -> None:

    path = _temp_db()

    try:
        store = SQLitePersistenceStore(path)

        record = DurableRecordFactory.create(
            tenant_id="tenant-a",
            record_type=(
                PersistenceRecordType.PIPELINE_STATE
            ),
            aggregate_id="pipeline-1",
            correlation_id="corr-1",
            payload={"stage": "OBSERVE"},
        )

        store.save_record(record)

        with sqlite3.connect(path) as connection:
            connection.execute(
                """
                UPDATE durable_records
                SET payload_json = ?
                WHERE record_id = ?
                """,
                (
                    json.dumps(
                        {"stage": "TAMPERED"}
                    ),
                    record.record_id,
                ),
            )

        try:
            store.get_record(
                "tenant-a",
                record.record_id,
            )
        except Phase23IntegrityError:
            return

        raise AssertionError(
            "Tampered record was accepted"
        )

    finally:
        os.unlink(path)


