def run_phase_23_tests() -> Dict[str, Any]:

    tests = [
        test_database_initializes,
        test_durable_record_round_trip,
        test_tenant_isolation_on_record_read,
        test_record_integrity_is_verified,
        test_duplicate_record_is_rejected,
        test_checkpoint_round_trip,
        test_latest_checkpoint_is_selected,
        test_failed_checkpoint_is_recoverable,
        test_recovery_returns_exact_checkpoint,
        test_recovery_cannot_cross_tenant,
        test_idempotency_survives_store_restart,
        test_idempotency_is_tenant_scoped,
        test_pipeline_persistence_bridge,
        test_integration_message_persistence,
        test_pipeline_state_persistence,
        test_atomic_transaction_rolls_back,
        test_non_failed_checkpoint_is_not_marked_recoverable,
    ]

    passed = 0
    failed = 0
    failures: list[Dict[str, str]] = []

    for test in tests:
        try:
            test()
            passed += 1

        except Exception as exc:
            failed += 1

            failures.append(
                {
                    "test": test.__name__,
                    "error": repr(exc),
                }
            )

    return {
        "phase": 23,
        "total": len(tests),
        "passed": passed,
        "failed": failed,
        "success": failed == 0,
        "failures": failures,
    }


