# ============================================================
# AUDIT FINGERPRINT
# ============================================================

class AuditFingerprint:

    @staticmethod
    def generate(
        record: AuditRecord,
    ) -> str:

        return fingerprint(
            record.audit_id,
            record.tenant_id,
            record.timestamp,
            record.actor_id,
            record.action,
            record.outcome,
            record.component,
            record.operation,
            record.resource_type,
            record.resource_id,
            record.correlation_id,
            record.causation_id,
            record.details,
            record.sequence,
            record.previous_fingerprint,
        )

    @staticmethod
    def verify(
        record: AuditRecord,
    ) -> bool:

        return (
            AuditFingerprint.generate(record)
            == record.fingerprint
        )


