class TelemetryFactory:

    @staticmethod
    def event(
        context: ObservabilityContext,
        kind: TelemetryKind,
        severity: Severity,
        message: str,
        sequence: int = 0,
        attributes: Optional[
            Mapping[str, Any]
        ] = None,
    ) -> TelemetryEvent:

        event_id = str(uuid4())
        timestamp = utc_now()

        attrs = dict(
            attributes or {}
        )

        event_fingerprint = fingerprint(
            event_id,
            context.tenant_id,
            kind,
            severity,
            timestamp,
            context.component,
            context.operation,
            context.correlation_id,
            context.causation_id,
            message,
            attrs,
            sequence,
        )

        return TelemetryEvent(
            event_id=event_id,
            tenant_id=context.tenant_id,
            kind=kind,
            severity=severity,
            timestamp=timestamp,
            component=context.component,
            operation=context.operation,
            correlation_id=context.correlation_id,
            causation_id=context.causation_id,
            message=message,
            attributes=attrs,
            sequence=sequence,
            fingerprint=event_fingerprint,
        )


