class TraceBuilder:

    def __init__(
        self,
        tenant_id: str,
        trace_id: Optional[str] = None,
        parent_span_id: Optional[str] = None,
        correlation_id: Optional[str] = None,
    ) -> None:

        self._tenant_id = require_non_empty(
            tenant_id,
            "tenant_id",
        )

        self._trace_id = (
            trace_id
            or str(uuid4())
        )

        self._parent_span_id = (
            parent_span_id
        )

        self._correlation_id = (
            correlation_id
            or str(uuid4())
        )

        self._span_id = str(uuid4())
        self._started_at = utc_now()

    def finish(
        self,
        component: str,
        operation: str,
        status: HealthStatus,
        attributes: Optional[
            Mapping[str, Any]
        ] = None,
    ) -> TraceSpan:

        ended_at = utc_now()

        attrs = dict(
            attributes or {}
        )

        span_fingerprint = fingerprint(
            self._span_id,
            self._trace_id,
            self._tenant_id,
            operation,
            component,
            self._started_at,
            ended_at,
            self._parent_span_id,
            self._correlation_id,
            status,
            attrs,
        )

        return TraceSpan(
            span_id=self._span_id,
            trace_id=self._trace_id,
            tenant_id=self._tenant_id,
            operation=operation,
            component=component,
            started_at=self._started_at,
            ended_at=ended_at,
            parent_span_id=self._parent_span_id,
            correlation_id=self._correlation_id,
            status=status,
            attributes=attrs,
            fingerprint=span_fingerprint,
        )


