def run_phase_24_tests() -> Dict[str, Any]:

    tests = [
        test_structured_event_is_emitted,
        test_telemetry_is_tenant_scoped,
        test_telemetry_sequence_is_monotonic,
        test_metric_is_emitted,
        test_metric_is_tenant_scoped,
        test_trace_span_has_valid_duration,
        test_audit_record_is_emitted,
        test_audit_fingerprint_is_valid,
        test_audit_chain_is_created,
        test_audit_chain_detects_tampering,
        test_cross_tenant_audit_isolated,
        test_correlation_view_joins_telemetry,
        test_correlation_view_cannot_cross_tenant,
        test_audit_sequence_gap_is_rejected,
        test_invalid_audit_fingerprint_is_rejected,
        test_duplicate_audit_id_is_rejected,
        test_health_snapshot_reports_unknown_without_components,
        test_health_snapshot_reports_healthy_components,
        test_health_snapshot_reports_failure,
        test_health_snapshot_reports_degraded,
    ]

    passed = 0
    failed = 0
    failures: list[Dict[str, str]] = []

    for test in tests:
        try:
            test()
            passed += 1
        except Exception as exc:
            failed += 1
            failures.append(
                {
                    "test": test.__name__,
                    "error": repr(exc),
                }
            )

    return {
        "phase": 24,
        "total": len(tests),
        "passed": passed,
        "failed": failed,
        "success": failed == 0,
        "failures": failures,
    }


