# ============================================================================







def constant_time_equal(left: str, right: str) -> bool:
    """
    Constant-time comparison for secret-derived strings.
    """
    return hmac.compare_digest(
        left.encode("utf-8"),
        right.encode("utf-8"),
    )


def canonical_text(value: Any) -> str:
    if value is None:
        return "null"

    if isinstance(value, bool):
        return "true" if value else "false"

    if isinstance(value, (int, float)):
        return repr(value)

    if isinstance(value, Mapping):
        items = sorted(
            (
                str(key),
                canonical_text(item),
            )
            for key, item in value.items()
        )
        return "{" + ",".join(
            f"{key}:{item}" for key, item in items
        ) + "}"

    if isinstance(value, (list, tuple)):
        return "[" + ",".join(
            canonical_text(item) for item in value
        ) + "]"

    if isinstance(value, (set, frozenset)):
        return "{" + ",".join(
            sorted(canonical_text(item) for item in value)
        ) + "}"

    return str(value)




