@dataclass(frozen=True)
class SecurityConfig:
    """
    Security configuration.

    Unsafe production defaults are rejected by validate().
    """

    environment: str = "development"

    min_password_length: int = 12
    password_iterations: int = 310_000

    api_key_bytes: int = 32

    replay_window_seconds: int = 300
    rate_limit_capacity: int = 100
    rate_limit_refill_per_second: float = 1.0

    session_ttl_seconds: int = 3600

    require_https: bool = True
    allow_insecure_localhost: bool = True

    max_request_bytes: int = 10 * 1024 * 1024

    @property
    def production(self) -> bool:
        return self.environment.lower() == "production"

    def validate(self) -> None:
        if self.min_password_length < 12:
            raise SecurityConfigurationError(
                "Minimum password length must be >= 12"
            )

        if self.password_iterations < 100_000:
            raise SecurityConfigurationError(
                "Password KDF iterations are too low"
            )

        if self.api_key_bytes < 32:
            raise SecurityConfigurationError(
                "API key entropy must be at least 256 bits"
            )

        if self.replay_window_seconds <= 0:
            raise SecurityConfigurationError(
                "Replay window must be positive"
            )

        if self.rate_limit_capacity <= 0:
            raise SecurityConfigurationError(
                "Rate-limit capacity must be positive"
            )

        if self.rate_limit_refill_per_second <= 0:
            raise SecurityConfigurationError(
                "Rate-limit refill rate must be positive"
            )

        if self.session_ttl_seconds <= 0:
            raise SecurityConfigurationError(
                "Session TTL must be positive"
            )

        if self.max_request_bytes <= 0:
            raise SecurityConfigurationError(
                "Maximum request size must be positive"
            )


# ============================================================================
# SECTION 5 — SECRET REFERENCES
# ============================================================================

@dataclass(frozen=True)
class SecretReference:
    """
    Logical reference to a secret.

    The secret value itself is never stored here.
    """

    name: str
    version: Optional[str] = None

    def __post_init__(self) -> None:
        require_non_empty(self.name, "secret name")

    def display_name(self) -> str:
        if self.version:
            return f"{self.name}@{self.version}"
        return self.name


class SecretProvider(Protocol):
    def resolve(self, reference: SecretReference) -> str:
        ...


class InMemorySecretProvider:
    """
    Test/development secret provider.

    This is deliberately scoped to Phase-25 testing and does not claim
    to be an enterprise external secret manager.
    """

    def __init__(self) -> None:
        # [auto-repair] this dict, and the compatibility patch further
        # down whose own comment literally says "tenant-safe snapshots",
        # were both keyed on reference.display_name() alone -- no
        # tenant_id anywhere. Two tenants both storing a secret named
        # "database_password" (a very likely real-world collision)
        # would silently overwrite/leak each other's value. The patch's
        # comment claimed tenant-safety it didn't actually implement.
        # Fixing both here and in the patch below.
        self._secrets: Dict[Tuple[str, str], str] = {}
        self._lock = threading.RLock()

    def put(
        self,
        reference: SecretReference,
        value: str,
        *,
        tenant_id: str,
    ) -> None:
        require_non_empty(value, "secret value")
        require_non_empty(tenant_id, "tenant_id")

        with self._lock:
            self._secrets[(tenant_id, reference.display_name())] = value

    def resolve(
        self,
        reference: SecretReference,
        *,
        tenant_id: str,
    ) -> str:
        require_non_empty(tenant_id, "tenant_id")

        with self._lock:
            value = self._secrets.get((tenant_id, reference.display_name()))

        if value is None:
            raise SecretError(
                f"Secret not available: {reference.display_name()}"
            )

        return value


# ============================================================================
# SECTION 6 — SECRET REDACTION
# ============================================================================

SENSITIVE_KEY_PATTERN = re.compile(
    r"(password|passwd|secret|token|api[_-]?key|"
    r"authorization|cookie|private[_-]?key|credential)",
    re.IGNORECASE,
)


def redact_sensitive(
    value: Any,
    *,
    replacement: str = "[REDACTED]",
) -> Any:
    """
    Recursively removes sensitive values from structured data.
    """

    if isinstance(value, Mapping):
        result: Dict[str, Any] = {}

        for key, item in value.items():
            key_text = str(key)

            if SENSITIVE_KEY_PATTERN.search(key_text):
                result[key_text] = replacement
            else:
                result[key_text] = redact_sensitive(
                    item,
                    replacement=replacement,
                )

        return result

    if isinstance(value, list):
        return [
            redact_sensitive(item, replacement=replacement)
            for item in value
        ]

    if isinstance(value, tuple):
        return tuple(
            redact_sensitive(item, replacement=replacement)
            for item in value
        )

    if isinstance(value, set):
        return {
            redact_sensitive(item, replacement=replacement)
            for item in value
        }

    return value


# ============================================================================
# SECTION 7 — PASSWORD CREDENTIALS
# ============================================================================

@dataclass(frozen=True)
class PasswordHash:
    algorithm: str
    iterations: int
    salt_b64: str
    digest_b64: str


class PasswordHasher:
    """
    PBKDF2-HMAC-SHA256 password hashing boundary.

    Passwords are never persisted in plaintext.
    """

    ALGORITHM = "pbkdf2_sha256"

    def __init__(self, config: SecurityConfig) -> None:
        self.config = config

    def hash(self, password: str) -> PasswordHash:
        if not isinstance(password, str):
            raise CredentialError("Password must be text")

        if len(password) < self.config.min_password_length:
            raise CredentialError(
                "Password does not meet minimum length"
            )

        salt = secrets.token_bytes(16)

        digest = hashlib.pbkdf2_hmac(
            "sha256",
            password.encode("utf-8"),
            salt,
            self.config.password_iterations,
        )

        return PasswordHash(
            algorithm=self.ALGORITHM,
            iterations=self.config.password_iterations,
            salt_b64=base64.b64encode(salt).decode("ascii"),
            digest_b64=base64.b64encode(digest).decode("ascii"),
        )

    def verify(
        self,
        password: str,
        stored: PasswordHash,
    ) -> bool:
        if stored.algorithm != self.ALGORITHM:
            return False

        try:
            salt = base64.b64decode(
                stored.salt_b64.encode("ascii"),
                validate=True,
            )

            expected = base64.b64decode(
                stored.digest_b64.encode("ascii"),
                validate=True,
            )
        except Exception:
            return False

        actual = hashlib.pbkdf2_hmac(
            "sha256",
            password.encode("utf-8"),
            salt,
            stored.iterations,
        )

        return hmac.compare_digest(actual, expected)


