# ============================================================================
# SECTION 9 — PRINCIPAL / RBAC MODEL
# ============================================================================

@dataclass(frozen=True)
class Principal:
    principal_id: str
    tenant_id: str
    principal_type: PrincipalType
    roles: FrozenSet[str] = frozenset()
    active: bool = True

    def __post_init__(self) -> None:
        require_non_empty(
            self.principal_id,
            "principal_id",
        )
        require_non_empty(self.tenant_id, "tenant_id")






class RBACPolicy:
    """
    Explicit role -> permission mapping.

    Unknown roles do not grant permissions.
    """

    def __init__(self) -> None:
        self._roles: Dict[str, Role] = {}
        self._lock = threading.RLock()

    def add_role(self, role: Role) -> None:
        with self._lock:
            self._roles[role.name] = role

    def get_role(self, role_name: str) -> Optional[Role]:
        with self._lock:
            return self._roles.get(role_name)

    def permissions_for(
        self,
        principal: Principal,
    ) -> FrozenSet[Permission]:

        permissions = set()

        with self._lock:
            for role_name in principal.roles:
                role = self._roles.get(role_name)

                if role is None:
                    continue

                permissions.update(role.permissions)

        return frozenset(permissions)


# ============================================================================
# SECTION 10 — AUTHORIZATION REQUEST
# ============================================================================



@dataclass(frozen=True)
class AuthorizationResult:
    decision: SecurityDecision
    reason: str
    principal_id: str
    tenant_id: str
    permission: Permission


class AuthorizationEngine:
    """
    Fail-closed tenant-scoped RBAC authorization.
    """

    def __init__(self, rbac: RBACPolicy) -> None:
        self.rbac = rbac

    def authorize(
        self,
        request: AuthorizationRequest,
    ) -> AuthorizationResult:

        request.validate()

        principal = request.principal

        if not principal.active:
            return AuthorizationResult(
                decision=SecurityDecision.DENY,
                reason="principal_inactive",
                principal_id=principal.principal_id,
                tenant_id=request.tenant_id,
                permission=request.permission,
            )

        permissions = self.rbac.permissions_for(principal)

        if request.permission in permissions:
            return AuthorizationResult(
                decision=SecurityDecision.ALLOW,
                reason="explicit_permission",
                principal_id=principal.principal_id,
                tenant_id=request.tenant_id,
                permission=request.permission,
            )

        return AuthorizationResult(
            decision=SecurityDecision.DENY,
            reason="permission_not_granted",
            principal_id=principal.principal_id,
            tenant_id=request.tenant_id,
            permission=request.permission,
        )


# ============================================================================
# SECTION 11 — SECURITY POLICY
# ============================================================================



class SecurityPolicyEvaluator:
    def __init__(self, policy: SecurityPolicy) -> None:
        self.policy = policy

    def evaluate(
        self,
        *,
        principal: Optional[Principal],
        request_tenant_id: str,
        permission: Permission,
        is_https: bool,
        environment: str,
    ) -> SecurityDecision:

        if self.policy.require_authenticated_principal:
            if principal is None:
                return SecurityDecision.DENY

        if principal is None:
            return SecurityDecision.DENY

        if (
            self.policy.deny_cross_tenant_access
            and principal.tenant_id != request_tenant_id
        ):
            return SecurityDecision.DENY

        if (
            self.policy.deny_inactive_principals
            and not principal.active
        ):
            return SecurityDecision.DENY

        if (
            self.policy.require_https_in_production
            and environment.lower() == "production"
            and not is_https
        ):
            return SecurityDecision.DENY

        if not permission.resource.strip():
            return SecurityDecision.DENY

        if not permission.action.strip():
            return SecurityDecision.DENY

        return SecurityDecision.ALLOW


# ============================================================================
# SECTION 12 — REQUEST SECURITY
# ============================================================================

@dataclass(frozen=True)
class SecurityRequest:
    method: str
    path: str
    tenant_id: str
    request_id: str
    correlation_id: str
    timestamp: datetime
    body_size: int
    is_https: bool
    headers: Mapping[str, str] = field(
        default_factory=dict
    )

    def validate(self, config: SecurityConfig) -> None:
        require_non_empty(self.method, "method")
        require_non_empty(self.path, "path")
        require_non_empty(self.tenant_id, "tenant_id")
        require_non_empty(self.request_id, "request_id")
        require_non_empty(
            self.correlation_id,
            "correlation_id",
        )

        ensure_aware(self.timestamp, "timestamp")

        if self.body_size < 0:
            raise Phase25ValidationError(
                "body_size cannot be negative"
            )

        if self.body_size > config.max_request_bytes:
            raise SecurityPolicyError(
                "Request exceeds configured maximum size"
            )

        if (
            config.production
            and config.require_https
            and not self.is_https
        ):
            raise SecurityPolicyError(
                "HTTPS is required in production"
            )


class RequestSecurityValidator:
    def __init__(self, config: SecurityConfig) -> None:
        self.config = config

    def validate(
        self,
        request: SecurityRequest,
    ) -> SecurityRequest:

        request.validate(self.config)

        if "\x00" in request.path:
            raise SecurityPolicyError(
                "Null byte detected in path"
            )

        if len(request.path) > 4096:
            raise SecurityPolicyError(
                "Path exceeds security boundary"
            )

        return request


# ============================================================================
# SECTION 13 — REPLAY PROTECTION
# ============================================================================

@dataclass(frozen=True)
class ReplayKey:
    tenant_id: str
    request_id: str


class ReplayProtectionStore:
    """
    In-memory replay boundary.

    Durable distributed replay state is intentionally outside Phase 25.
    """

    def __init__(self) -> None:
        self._entries: Dict[ReplayKey, datetime] = {}
        self._lock = threading.RLock()

    def check_and_record(
        self,
        *,
        tenant_id: str,
        request_id: str,
        now: datetime,
        window_seconds: int,
    ) -> None:

        ensure_aware(now, "now")

        key = ReplayKey(
            tenant_id=require_non_empty(
                tenant_id,
                "tenant_id",
            ),
            request_id=require_non_empty(
                request_id,
                "request_id",
            ),
        )

        cutoff = now - timedelta(
            seconds=window_seconds
        )

        with self._lock:

            expired = [
                existing_key
                for existing_key, timestamp
                in self._entries.items()
                if timestamp < cutoff
            ]

            for existing_key in expired:
                del self._entries[existing_key]

            if key in self._entries:
                raise ReplayDetectedError(
                    "Request replay detected"
                )

            self._entries[key] = now


# ============================================================================
# SECTION 14 — RATE LIMITING
# ============================================================================

@dataclass
class _Bucket:
    tokens: float
    last_refill: float


class TokenBucketRateLimiter:
    """
    Tenant-scoped token bucket.

    Thread-safe for concurrent in-process callers.
    """

    def __init__(
        self,
        capacity: int,
        refill_per_second: float,
    ) -> None:

        if capacity <= 0:
            raise Phase25ValidationError(
                "capacity must be positive"
            )

        if refill_per_second <= 0:
            raise Phase25ValidationError(
                "refill_per_second must be positive"
            )

        self.capacity = float(capacity)
        self.refill_per_second = refill_per_second

        self._buckets: Dict[str, _Bucket] = {}
        self._lock = threading.RLock()

    def allow(
        self,
        key: str,
        *,
        cost: float = 1.0,
        now_monotonic: Optional[float] = None,
    ) -> bool:

        key = require_non_empty(key, "rate-limit key")

        if cost <= 0:
            raise Phase25ValidationError(
                "cost must be positive"
            )

        current = (
            time.monotonic()
            if now_monotonic is None
            else now_monotonic
        )

        with self._lock:
            bucket = self._buckets.get(key)

            if bucket is None:
                bucket = _Bucket(
                    tokens=self.capacity,
                    last_refill=current,
                )
                self._buckets[key] = bucket

            elapsed = max(
                0.0,
                current - bucket.last_refill,
            )

            bucket.tokens = min(
                self.capacity,
                bucket.tokens
                + elapsed * self.refill_per_second,
            )

            bucket.last_refill = current

            if bucket.tokens < cost:
                return False

            bucket.tokens -= cost
            return True


# ============================================================================
# SECTION 15 — SECURITY HEADERS
# ============================================================================

SECURITY_HEADERS: Mapping[str, str] = {
    "X-Content-Type-Options": "nosniff",
    "X-Frame-Options": "DENY",
    "Referrer-Policy": "no-referrer",
    "Cache-Control": "no-store",
    "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
}


class SecurityHeaders:
    """
    Returns immutable baseline security headers.
    """

    @staticmethod
    def build(
        *,
        include_hsts: bool,
    ) -> Dict[str, str]:

        result = dict(SECURITY_HEADERS)

        if include_hsts:
            result["Strict-Transport-Security"] = (
                "max-age=31536000; includeSubDomains"
            )

        return result


# ============================================================================
# SECTION 16 — SECURITY EVENTS
# ============================================================================

@dataclass(frozen=True)
class SecurityEvent:
    event_id: str
    event_type: SecurityEventType
    severity: SecuritySeverity
    tenant_id: str
    principal_id: Optional[str]
    correlation_id: Optional[str]
    occurred_at: datetime
    details: Mapping[str, Any]
    fingerprint: str


class SecurityEventFactory:

    @staticmethod
    def create(
        *,
        event_type: SecurityEventType,
        severity: SecuritySeverity,
        tenant_id: str,
        principal_id: Optional[str],
        correlation_id: Optional[str],
        details: Mapping[str, Any],
    ) -> SecurityEvent:

        tenant_id = require_non_empty(
            tenant_id,
            "tenant_id",
        )

        occurred_at = utc_now()

        safe_details = redact_sensitive(details)

        event_id = secrets.token_hex(16)

        canonical = canonical_text(
            {
                "event_id": event_id,
                "event_type": event_type.value,
                "severity": severity.value,
                "tenant_id": tenant_id,
                "principal_id": principal_id,
                "correlation_id": correlation_id,
                "occurred_at": occurred_at.isoformat(),
                "details": safe_details,
            }
        )

        return SecurityEvent(
            event_id=event_id,
            event_type=event_type,
            severity=severity,
            tenant_id=tenant_id,
            principal_id=principal_id,
            correlation_id=correlation_id,
            occurred_at=occurred_at,
            details=safe_details,
            fingerprint=sha256_hex(canonical),
        )


class SecurityEventSink(Protocol):
    def append(self, event: SecurityEvent) -> None:
        ...


class InMemorySecurityEventSink:
    """
    Phase-25 test/development sink.

    Durable event persistence remains outside this phase.
    """

    def __init__(self) -> None:
        self._events: list[SecurityEvent] = []
        self._lock = threading.RLock()

    def append(self, event: SecurityEvent) -> None:
        with self._lock:
            self._events.append(event)

    def events_for_tenant(
        self,
        tenant_id: str,
    ) -> Tuple[SecurityEvent, ...]:

        with self._lock:
            return tuple(
                event
                for event in self._events
                if event.tenant_id == tenant_id
            )


# ============================================================================
# SECTION 17 — SECURITY GATE
# ============================================================================

@dataclass(frozen=True)
class SecurityGateResult:
    decision: SecurityDecision
    reason: str
    tenant_id: str
    principal_id: Optional[str]


class SecurityGate:
    """
    Central Phase-25 fail-closed security boundary.

    Order:
        request validation
        replay protection
        policy evaluation
        RBAC authorization
        rate limiting
    """

    def __init__(
        self,
        *,
        config: SecurityConfig,
        request_validator: RequestSecurityValidator,
        replay_store: ReplayProtectionStore,
        policy_evaluator: SecurityPolicyEvaluator,
        authorization_engine: AuthorizationEngine,
        rate_limiter: TokenBucketRateLimiter,
        event_sink: Optional[SecurityEventSink] = None,
    ) -> None:

        self.config = config
        self.request_validator = request_validator
        self.replay_store = replay_store
        self.policy_evaluator = policy_evaluator
        self.authorization_engine = authorization_engine
        self.rate_limiter = rate_limiter
        self.event_sink = event_sink

    def _emit(
        self,
        *,
        event_type: SecurityEventType,
        severity: SecuritySeverity,
        tenant_id: str,
        principal_id: Optional[str],
        correlation_id: Optional[str],
        details: Mapping[str, Any],
    ) -> None:

        if self.event_sink is None:
            return

        self.event_sink.append(
            SecurityEventFactory.create(
                event_type=event_type,
                severity=severity,
                tenant_id=tenant_id,
                principal_id=principal_id,
                correlation_id=correlation_id,
                details=details,
            )
        )

    def authorize_request(
        self,
        *,
        request: SecurityRequest,
        principal: Optional[Principal],
        permission: Permission,
    ) -> SecurityGateResult:

        # ------------------------------------------------------------
        # 1. REQUEST VALIDATION
        # ------------------------------------------------------------

        self.request_validator.validate(request)

        # ------------------------------------------------------------
        # 2. REPLAY PROTECTION
        # ------------------------------------------------------------

        try:
            self.replay_store.check_and_record(
                tenant_id=request.tenant_id,
                request_id=request.request_id,
                now=request.timestamp,
                window_seconds=self.config.replay_window_seconds,
            )
        except ReplayDetectedError:

            self._emit(
                event_type=SecurityEventType.REPLAY_DETECTED,
                severity=SecuritySeverity.HIGH,
                tenant_id=request.tenant_id,
                principal_id=(
                    principal.principal_id
                    if principal
                    else None
                ),
                correlation_id=request.correlation_id,
                details={
                    "request_id": request.request_id,
                },
            )

            raise

        # ------------------------------------------------------------
        # 3. RATE LIMIT
        # ------------------------------------------------------------

        rate_key = (
            f"{request.tenant_id}:"
            f"{principal.principal_id if principal else 'anonymous'}"
        )

        if not self.rate_limiter.allow(rate_key):

            self._emit(
                event_type=SecurityEventType.RATE_LIMITED,
                severity=SecuritySeverity.WARNING,
                tenant_id=request.tenant_id,
                principal_id=(
                    principal.principal_id
                    if principal
                    else None
                ),
                correlation_id=request.correlation_id,
                details={
                    "request_id": request.request_id,
                },
            )

            raise RateLimitExceededError(
                "Security rate limit exceeded"
            )

        # ------------------------------------------------------------
        # 4. POLICY
        # ------------------------------------------------------------

        policy_decision = self.policy_evaluator.evaluate(
            principal=principal,
            request_tenant_id=request.tenant_id,
            permission=permission,
            is_https=request.is_https,
            environment=self.config.environment,
        )

        if policy_decision != SecurityDecision.ALLOW:

            self._emit(
                event_type=SecurityEventType.POLICY_VIOLATION,
                severity=SecuritySeverity.HIGH,
                tenant_id=request.tenant_id,
                principal_id=(
                    principal.principal_id
                    if principal
                    else None
                ),
                correlation_id=request.correlation_id,
                details={
                    "permission": permission.canonical,
                },
            )

            return SecurityGateResult(
                decision=SecurityDecision.DENY,
                reason="security_policy_denied",
                tenant_id=request.tenant_id,
                principal_id=(
                    principal.principal_id
                    if principal
                    else None
                ),
            )

        # ------------------------------------------------------------
        # 5. RBAC
        # ------------------------------------------------------------

        if principal is None:
            return SecurityGateResult(
                decision=SecurityDecision.DENY,
                reason="authentication_required",
                tenant_id=request.tenant_id,
                principal_id=None,
            )

        try:
            result = self.authorization_engine.authorize(
                AuthorizationRequest(
                    principal=principal,
                    tenant_id=request.tenant_id,
                    permission=permission,
                    context={
                        "request_id": request.request_id,
                        "correlation_id": request.correlation_id,
                    },
                )
            )
        except TenantIsolationError:

            self._emit(
                event_type=SecurityEventType.TENANT_ISOLATION_VIOLATION,
                severity=SecuritySeverity.CRITICAL,
                tenant_id=request.tenant_id,
                principal_id=principal.principal_id,
                correlation_id=request.correlation_id,
                details={
                    "permission": permission.canonical,
                },
            )

            raise

        if result.decision != SecurityDecision.ALLOW:

            self._emit(
                event_type=SecurityEventType.AUTHORIZATION_DENIED,
                severity=SecuritySeverity.WARNING,
                tenant_id=request.tenant_id,
                principal_id=principal.principal_id,
                correlation_id=request.correlation_id,
                details={
                    "permission": permission.canonical,
                    "reason": result.reason,
                },
            )

            return SecurityGateResult(
                decision=SecurityDecision.DENY,
                reason=result.reason,
                tenant_id=request.tenant_id,
                principal_id=principal.principal_id,
            )

        self._emit(
            event_type=SecurityEventType.AUTHORIZATION_ALLOWED,
            severity=SecuritySeverity.INFO,
            tenant_id=request.tenant_id,
            principal_id=principal.principal_id,
            correlation_id=request.correlation_id,
            details={
                "permission": permission.canonical,
            },
        )

        return SecurityGateResult(
            decision=SecurityDecision.ALLOW,
            reason="authorized",
            tenant_id=request.tenant_id,
            principal_id=principal.principal_id,
        )


# ============================================================================
# SECTION 18 — SECURE TOKEN GENERATION
# ============================================================================

class SecureTokenGenerator:

    @staticmethod
    def generate_urlsafe(byte_length: int = 32) -> str:
        if byte_length < 32:
            raise Phase25ValidationError(
                "Token entropy must be at least 256 bits"
            )

        return secrets.token_urlsafe(byte_length)


# ============================================================================
# SECTION 19 — SECURITY CONFIG FACTORY
# ============================================================================

class Phase25SecurityFactory:

    @staticmethod
    def create_config(
        environment: str = "development",
    ) -> SecurityConfig:

        config = SecurityConfig(
            environment=environment,
        )

        config.validate()

        return config

    @staticmethod
    def create_rbac() -> RBACPolicy:

        rbac = RBACPolicy()

        rbac.add_role(
            Role(
                name="security_admin",
                permissions=frozenset(
                    {
                        Permission("security", "read"),
                        Permission("security", "write"),
                        Permission("security", "admin"),
                    }
                ),
            )
        )

        rbac.add_role(
            Role(
                name="security_operator",
                permissions=frozenset(
                    {
                        Permission("security", "read"),
                        Permission("security", "operate"),
                    }
                ),
            )
        )

        rbac.add_role(
            Role(
                name="security_viewer",
                permissions=frozenset(
                    {
                        Permission("security", "read"),
                    }
                ),
            )
        )

        return rbac

    @staticmethod
    def create_gate(
        config: SecurityConfig,
        rbac: RBACPolicy,
        event_sink: Optional[SecurityEventSink] = None,
    ) -> SecurityGate:

        return SecurityGate(
            config=config,
            request_validator=RequestSecurityValidator(
                config
            ),
            replay_store=ReplayProtectionStore(),
            policy_evaluator=SecurityPolicyEvaluator(
                SecurityPolicy()
            ),
            authorization_engine=AuthorizationEngine(
                rbac
            ),
            rate_limiter=TokenBucketRateLimiter(
                capacity=config.rate_limit_capacity,
                refill_per_second=config.rate_limit_refill_per_second,
            ),
            event_sink=event_sink,
        )


