def run_phase_25_tests() -> Dict[str, Any]:
    """
    Deterministic Phase-25 test runner.

    Returns results instead of falsely claiming execution.
    """

    tests = [
        test_config_validation,
        test_password_hashing,
        test_password_plaintext_not_stored,
        test_api_key_generation_and_verification,
        test_api_key_plaintext_not_stored,
        test_api_key_revocation,
        test_rbac_allow,
        test_rbac_deny_unknown_permission,
        test_cross_tenant_isolation,
        test_inactive_principal_denied,
        test_request_size_boundary,
        test_production_https_requirement,
        test_null_byte_rejection,
        test_replay_protection,
        test_replay_is_tenant_scoped,
        test_rate_limiter,
        test_rate_limiter_refill,
        test_sensitive_redaction,
        test_security_headers,
        test_security_event_redacts_secrets,
        test_security_gate_allow,
        test_security_gate_deny_without_principal,
        test_security_gate_denies_unprivileged_action,
        test_security_gate_tenant_mismatch,
        test_security_gate_generates_audit_safe_event,
    ]

    passed = 0
    failed = 0
    failures: list[Dict[str, str]] = []

    for test in tests:
        try:
            test()
            passed += 1
        except Exception as exc:
            failed += 1
            failures.append(
                {
                    "test": test.__name__,
                    "error": str(exc),
                }
            )

    return {
        "phase": "25",
        "name": "Security Hardening",
        "total": len(tests),
        "passed": passed,
        "failed": failed,
        "success": failed == 0,
        "failures": failures,
    }


