@dataclass(frozen=True)
class SimulationSafetyPolicy:
    """
    Hard safety boundary.

    A Phase-26 simulation must remain synthetic and isolated.
    """

    allow_real_network: bool = False
    allow_real_execution: bool = False
    allow_destructive_actions: bool = False
    allow_real_credentials: bool = False
    allow_external_side_effects: bool = False
    require_dry_run: bool = True
    max_steps: int = 1000
    max_workers: int = 32
    max_events: int = 100_000
    max_duration_seconds: float = 300.0

    def validate(self) -> None:
        if self.allow_real_network:
            raise SimulationSafetyError(
                "Real network access is forbidden"
            )

        if self.allow_real_execution:
            raise SimulationSafetyError(
                "Real execution is forbidden"
            )

        if self.allow_destructive_actions:
            raise SimulationSafetyError(
                "Destructive actions are forbidden"
            )

        if self.allow_real_credentials:
            raise SimulationSafetyError(
                "Real credentials are forbidden"
            )

        if self.allow_external_side_effects:
            raise SimulationSafetyError(
                "External side effects are forbidden"
            )

        if not self.require_dry_run:
            raise SimulationSafetyError(
                "Phase-26 requires dry-run safety"
            )

        if self.max_steps <= 0:
            raise Phase26ValidationError(
                "max_steps must be positive"
            )

        if self.max_workers <= 0:
            raise Phase26ValidationError(
                "max_workers must be positive"
            )

        if self.max_events <= 0:
            raise Phase26ValidationError(
                "max_events must be positive"
            )

        if self.max_duration_seconds <= 0:
            raise Phase26ValidationError(
                "max_duration_seconds must be positive"
            )


class SimulationEnvironmentGuard:
    """
    Runtime safety guard.

    This object intentionally contains no real-system execution capability.
    """

    def __init__(
        self,
        policy: SimulationSafetyPolicy,
    ) -> None:

        policy.validate()
        self.policy = policy

    def assert_safe(self) -> None:
        self.policy.validate()

    def assert_dry_run(self, mode: SimulationMode) -> None:
        self.assert_safe()

        if self.policy.require_dry_run:
            if mode not in {
                SimulationMode.DRY_RUN,
                SimulationMode.WHAT_IF,
                SimulationMode.CHAOS,
                SimulationMode.LOAD,
            }:
                raise SimulationSafetyError(
                    "Unsupported simulation mode"
                )

    def assert_no_external_target(
        self,
        target: str,
    ) -> None:

        target = require_non_empty(
            target,
            "target",
        )

        forbidden_prefixes = (
            "http://",
            "https://",
            "ssh://",
            "tcp://",
            "udp://",
            "prod://",
            "live://",
        )

        if target.lower().startswith(
            forbidden_prefixes
        ):
            raise SimulationIsolationError(
                "External/live target is forbidden"
            )


