@dataclass(frozen=True)
class SyntheticSecurityEvent:
    event_id: str
    simulation_id: str
    tenant_id: str
    correlation_id: str
    event_type: SyntheticEventType
    source_asset: str
    timestamp: datetime
    attributes: Mapping[str, Any]
    fingerprint: str

    @staticmethod
    def create(
        *,
        simulation_id: str,
        tenant_id: str,
        correlation_id: str,
        event_type: SyntheticEventType,
        source_asset: str,
        attributes: Mapping[str, Any],
        timestamp: Optional[datetime] = None,
    ) -> "SyntheticSecurityEvent":

        timestamp = timestamp or utc_now()

        event_id = (
            "sim_evt_"
            + secrets.token_hex(12)
        )

        payload = {
            "event_id": event_id,
            "simulation_id": simulation_id,
            "tenant_id": tenant_id,
            "correlation_id": correlation_id,
            "event_type": event_type.value,
            "source_asset": source_asset,
            "timestamp": timestamp.isoformat(),
            "attributes": attributes,
        }

        return SyntheticSecurityEvent(
            event_id=event_id,
            simulation_id=simulation_id,
            tenant_id=tenant_id,
            correlation_id=correlation_id,
            event_type=event_type,
            source_asset=source_asset,
            timestamp=timestamp,
            attributes=dict(attributes),
            fingerprint=fingerprint(payload),
        )


class SyntheticEventGenerator:
    """
    Generates synthetic telemetry only.

    No real endpoint, cloud, identity, or network source is touched.
    """

    EVENT_TYPES = tuple(SyntheticEventType)

    def generate(
        self,
        *,
        context: SimulationContext,
        count: int,
    ) -> Tuple[SyntheticSecurityEvent, ...]:

        if count < 0:
            raise Phase26ValidationError(
                "count cannot be negative"
            )

        events = []

        rng = random.Random(
            context.seed
        )

        for index in range(count):

            event_type = rng.choice(
                self.EVENT_TYPES
            )

            asset_id = (
                f"sim-asset-"
                f"{rng.randint(1, 1000)}"
            )

            events.append(
                SyntheticSecurityEvent.create(
                    simulation_id=context.simulation_id,
                    tenant_id=context.tenant_id,
                    correlation_id=context.correlation_id,
                    event_type=event_type,
                    source_asset=asset_id,
                    attributes={
                        "synthetic": True,
                        "sequence": index,
                        "simulation_seed": context.seed,
                    },
                )
            )

        return tuple(events)


