@dataclass(frozen=True)
class ScenarioStep:
    step_id: str
    name: str
    step_type: ScenarioStepType
    target: str
    simulated_only: bool = True
    metadata: Mapping[str, Any] = field(
        default_factory=dict
    )

    def validate(
        self,
        guard: SimulationEnvironmentGuard,
    ) -> None:

        require_non_empty(
            self.step_id,
            "step_id",
        )

        require_non_empty(
            self.name,
            "name",
        )

        require_non_empty(
            self.target,
            "target",
        )

        if not self.simulated_only:
            raise SimulationSafetyError(
                "Non-simulated scenario step is forbidden"
            )

        guard.assert_no_external_target(
            self.target
        )


@dataclass(frozen=True)
class SimulationScenario:
    scenario_id: str
    name: str
    tenant_id: str
    steps: Tuple[ScenarioStep, ...]
    metadata: Mapping[str, Any] = field(
        default_factory=dict
    )

    def validate(
        self,
        guard: SimulationEnvironmentGuard,
    ) -> None:

        require_non_empty(
            self.scenario_id,
            "scenario_id",
        )

        require_non_empty(
            self.name,
            "scenario name",
        )

        require_non_empty(
            self.tenant_id,
            "tenant_id",
        )

        if not self.steps:
            raise Phase26ValidationError(
                "Scenario requires at least one step"
            )

        if (
            len(self.steps)
            > guard.policy.max_steps
        ):
            raise SimulationSafetyError(
                "Scenario exceeds maximum step count"
            )

        seen = set()

        for step in self.steps:
            if step.step_id in seen:
                raise Phase26ValidationError(
                    "Duplicate scenario step"
                )

            seen.add(step.step_id)

            step.validate(guard)


