@dataclass(frozen=True)
class SimulatedAction:
    action_id: str
    simulation_id: str
    tenant_id: str
    target: str
    operation: str
    parameters: Mapping[str, Any]
    destructive: bool = False
    external_side_effect: bool = False

    def validate(
        self,
        guard: SimulationEnvironmentGuard,
    ) -> None:

        if self.destructive:
            raise SimulationSafetyError(
                "Destructive simulated action rejected"
            )

        if self.external_side_effect:
            raise SimulationSafetyError(
                "External side effect rejected"
            )

        guard.assert_no_external_target(
            self.target
        )


@dataclass(frozen=True)
class SimulatedActionResult:
    action_id: str
    accepted: bool
    changed_real_state: bool
    external_side_effect: bool
    details: Mapping[str, Any]


class SafeActionSimulator:
    """
    Simulates action outcomes without executing real actions.
    """

    def __init__(
        self,
        guard: SimulationEnvironmentGuard,
    ) -> None:

        self.guard = guard

    def simulate(
        self,
        action: SimulatedAction,
    ) -> SimulatedActionResult:

        self.guard.assert_safe()

        action.validate(
            self.guard
        )

        return SimulatedActionResult(
            action_id=action.action_id,
            accepted=True,
            changed_real_state=False,
            external_side_effect=False,
            details={
                "simulated": True,
                "operation": action.operation,
                "target": action.target,
            },
        )


# ============================================================================
# SECTION 9 — FAILURE INJECTION
# ============================================================================

@dataclass(frozen=True)
class FailureInjection:
    failure_type: FailureType
    step_id: Optional[str] = None
    probability: float = 1.0
    delay_seconds: float = 0.0

    def validate(self) -> None:

        if not (
            0.0 <= self.probability <= 1.0
        ):
            raise Phase26ValidationError(
                "Failure probability must be between 0 and 1"
            )

        if self.delay_seconds < 0:
            raise Phase26ValidationError(
                "Failure delay cannot be negative"
            )

        if (
            self.failure_type == FailureType.NONE
            and self.probability > 0
        ):
            raise Phase26ValidationError(
                "NONE failure cannot have positive probability"
            )




# ============================================================================
# SECTION 10 — BLAST RADIUS
# ============================================================================

@dataclass(frozen=True)
class BlastRadius:
    affected_assets: FrozenSet[str]
    dependency_count: int
    critical_assets: int
    level: BlastRadiusLevel
    rationale: str


class BlastRadiusEstimator:
    """
    Estimates simulated impact only.

    It does not inspect real infrastructure.
    """

    def estimate(
        self,
        *,
        assets: Iterable[str],
        critical_assets: Iterable[str],
        dependency_count: int,
    ) -> BlastRadius:

        affected = frozenset(
            require_non_empty(
                asset,
                "asset",
            )
            for asset in assets
        )

        critical = frozenset(
            require_non_empty(
                asset,
                "critical asset",
            )
            for asset in critical_assets
        )

        if dependency_count < 0:
            raise Phase26ValidationError(
                "dependency_count cannot be negative"
            )

        critical_count = len(
            affected.intersection(critical)
        )

        total = len(affected)

        if total == 0:
            level = BlastRadiusLevel.NONE

        elif critical_count >= 3:
            level = BlastRadiusLevel.CRITICAL

        elif critical_count >= 1:
            level = BlastRadiusLevel.HIGH

        elif total >= 20 or dependency_count >= 20:
            level = BlastRadiusLevel.MEDIUM

        else:
            level = BlastRadiusLevel.LOW

        return BlastRadius(
            affected_assets=affected,
            dependency_count=dependency_count,
            critical_assets=critical_count,
            level=level,
            rationale=(
                f"{total} affected assets, "
                f"{critical_count} critical assets, "
                f"{dependency_count} dependencies"
            ),
        )


