# ============================================================================
# SECTION 13 — SIMULATION REGISTRY
# ============================================================================

class SimulationRegistry:
    """
    Tracks simulation IDs.

    Tenant-scoped and thread-safe.
    """

    def __init__(self) -> None:
        self._ids: set[
            Tuple[str, str]
        ] = set()

        self._lock = threading.RLock()

    def reserve(
        self,
        tenant_id: str,
        simulation_id: str,
    ) -> None:

        key = (
            require_non_empty(
                tenant_id,
                "tenant_id",
            ),
            require_non_empty(
                simulation_id,
                "simulation_id",
            ),
        )

        with self._lock:
            if key in self._ids:
                raise SimulationDuplicateError(
                    "Simulation already exists"
                )

            self._ids.add(key)


# ============================================================================
# SECTION 14 — SIMULATION ENGINE
# ============================================================================

class SimulationStepHandler(Protocol):

    def run(
        self,
        context: SimulationContext,
        step: ScenarioStep,
    ) -> Mapping[str, Any]:
        ...


class DefaultSimulationStepHandler:
    """
    Safe deterministic simulation handler.

    It produces state descriptions only.
    """

    def run(
        self,
        context: SimulationContext,
        step: ScenarioStep,
    ) -> Mapping[str, Any]:

        return {
            "simulated": True,
            "simulation_id": context.simulation_id,
            "tenant_id": context.tenant_id,
            "step_id": step.step_id,
            "step_type": step.step_type.value,
            "target": step.target,
        }


class SafeSimulationEngine:
    """
    Main Phase-26 simulation engine.

    No real-world action is executed.
    """

    def __init__(
        self,
        *,
        policy: Optional[
            SimulationSafetyPolicy
        ] = None,
        step_handler: Optional[
            SimulationStepHandler
        ] = None,
        registry: Optional[
            SimulationRegistry
        ] = None,
    ) -> None:

        self.policy = (
            policy
            or SimulationSafetyPolicy()
        )

        self.guard = (
            SimulationEnvironmentGuard(
                self.policy
            )
        )

        self.step_handler = (
            step_handler
            or DefaultSimulationStepHandler()
        )

        self.registry = (
            registry
            or SimulationRegistry()
        )

    def run(
        self,
        *,
        context: SimulationContext,
        scenario: SimulationScenario,
        failure_injections: Sequence[
            FailureInjection
        ] = (),
    ) -> SimulationResult:

        self.guard.assert_dry_run(
            context.mode
        )

        if (
            context.tenant_id
            != scenario.tenant_id
        ):
            raise SimulationTenantIsolationError(
                "Scenario tenant does not match simulation tenant"
            )

        scenario.validate(
            self.guard
        )

        if len(failure_injections) > len(
            scenario.steps
        ):
            raise Phase26ValidationError(
                "Too many failure injections"
            )

        self.registry.reserve(
            context.tenant_id,
            context.simulation_id,
        )

        started_at = utc_now()

        failure_injector = FailureInjector(
            seed=context.seed
        )

        step_results = []

        overall_outcome = (
            SimulationOutcome.SUCCESS
        )

        status = SimulationStatus.RUNNING

        for index, step in enumerate(
            scenario.steps
        ):

            step_started = time.monotonic()

            injection = (
                failure_injections[index]
                if index < len(
                    failure_injections
                )
                else None
            )

            try:

                failure_injector.apply(
                    injection
                )

                details = (
                    self.step_handler.run(
                        context,
                        step,
                    )
                )

                duration = (
                    time.monotonic()
                    - step_started
                )

                step_results.append(
                    SimulationStepResult(
                        step_id=step.step_id,
                        step_type=step.step_type,
                        status=SimulationOutcome.SUCCESS,
                        duration_seconds=duration,
                        details=details,
                    )
                )

            except SimulationTimeoutError as exc:

                duration = (
                    time.monotonic()
                    - step_started
                )

                step_results.append(
                    SimulationStepResult(
                        step_id=step.step_id,
                        step_type=step.step_type,
                        status=SimulationOutcome.TIMED_OUT,
                        duration_seconds=duration,
                        details={
                            "simulated": True,
                        },
                        failure=str(exc),
                    )
                )

                overall_outcome = (
                    SimulationOutcome.TIMED_OUT
                )

                status = (
                    SimulationStatus.TIMED_OUT
                )

                break

            except InjectedFailureError as exc:

                duration = (
                    time.monotonic()
                    - step_started
                )

                step_results.append(
                    SimulationStepResult(
                        step_id=step.step_id,
                        step_type=step.step_type,
                        status=SimulationOutcome.PARTIAL,
                        duration_seconds=duration,
                        details={
                            "simulated": True,
                        },
                        failure=str(exc),
                    )
                )

                overall_outcome = (
                    SimulationOutcome.PARTIAL
                )

            except Exception as exc:

                duration = (
                    time.monotonic()
                    - step_started
                )

                step_results.append(
                    SimulationStepResult(
                        step_id=step.step_id,
                        step_type=step.step_type,
                        status=SimulationOutcome.FAILED,
                        duration_seconds=duration,
                        details={
                            "simulated": True,
                        },
                        failure=str(exc),
                    )
                )

                overall_outcome = (
                    SimulationOutcome.FAILED
                )

                status = (
                    SimulationStatus.FAILED
                )

                break

        finished_at = utc_now()

        if status == SimulationStatus.RUNNING:
            status = (
                SimulationStatus.COMPLETED
            )

        synthetic_events = (
            SyntheticEventGenerator().generate(
                context=context,
                count=min(
                    len(step_results),
                    self.policy.max_events,
                ),
            )
        )

        affected_assets = {
            event.source_asset
            for event in synthetic_events
        }

        blast_radius = (
            BlastRadiusEstimator().estimate(
                assets=affected_assets,
                critical_assets={
                    "sim-asset-1",
                    "sim-asset-2",
                    "sim-asset-3",
                },
                dependency_count=len(
                    affected_assets
                ),
            )
        )

        payload = {
            "simulation_id": context.simulation_id,
            "tenant_id": context.tenant_id,
            "correlation_id": context.correlation_id,
            "scenario_id": scenario.scenario_id,
            "status": status.value,
            "outcome": overall_outcome.value,
            "started_at": started_at.isoformat(),
            "finished_at": finished_at.isoformat(),
            "steps": [
                {
                    "step_id": item.step_id,
                    "status": item.status.value,
                }
                for item in step_results
            ],
            "events": [
                event.fingerprint
                for event in synthetic_events
            ],
            "blast_radius": blast_radius.level.value,
        }

        return SimulationResult(
            simulation_id=context.simulation_id,
            tenant_id=context.tenant_id,
            correlation_id=context.correlation_id,
            scenario_id=scenario.scenario_id,
            status=status,
            outcome=overall_outcome,
            started_at=started_at,
            finished_at=finished_at,
            steps=tuple(step_results),
            synthetic_events=synthetic_events,
            blast_radius=blast_radius,
            fingerprint=fingerprint(payload),
        )


# ============================================================================
# SECTION 15 — WHAT-IF MODEL
# ============================================================================

@dataclass(frozen=True)
class WhatIfVariable:
    name: str
    baseline: float
    alternative: float

    def __post_init__(self) -> None:
        require_non_empty(
            self.name,
            "variable name",
        )


@dataclass(frozen=True)
class WhatIfResult:
    variable: str
    baseline: float
    alternative: float
    delta: float
    relative_change: Optional[float]


class WhatIfSimulator:
    """
    Pure mathematical what-if simulation.

    No real-world side effects.
    """

    def simulate(
        self,
        variable: WhatIfVariable,
    ) -> WhatIfResult:

        delta = (
            variable.alternative
            - variable.baseline
        )

        if variable.baseline == 0:
            relative_change = None
        else:
            relative_change = (
                delta
                / abs(variable.baseline)
            )

        return WhatIfResult(
            variable=variable.name,
            baseline=variable.baseline,
            alternative=variable.alternative,
            delta=delta,
            relative_change=relative_change,
        )


# ============================================================================
# SECTION 16 — LOAD WORKLOAD
# ============================================================================

@dataclass(frozen=True)
class LoadProfile:
    operations: int
    workers: int
    operation_cost: float = 1.0

    def validate(
        self,
        policy: SimulationSafetyPolicy,
    ) -> None:

        if self.operations <= 0:
            raise Phase26ValidationError(
                "operations must be positive"
            )

        if self.workers <= 0:
            raise Phase26ValidationError(
                "workers must be positive"
            )

        if self.workers > policy.max_workers:
            raise SimulationSafetyError(
                "Worker count exceeds safety boundary"
            )

        if (
            self.operation_cost <= 0
        ):
            raise Phase26ValidationError(
                "operation_cost must be positive"
            )


@dataclass(frozen=True)
class LoadResult:
    operations_requested: int
    operations_completed: int
    operations_failed: int
    duration_seconds: float
    throughput_per_second: float


class SimulationWorkload(Protocol):

    def execute(
        self,
        sequence: int,
    ) -> None:
        ...


class SyntheticWorkload:
    """
    CPU-light deterministic workload.

    It does not touch external systems.
    """

    def execute(
        self,
        sequence: int,
    ) -> None:

        value = hashlib.sha256(
            f"simulation-{sequence}".encode(
                "utf-8"
            )
        ).digest()

        if not value:
            raise RuntimeError(
                "Unexpected empty workload result"
            )


class StressHarness:
    """
    Bounded concurrency stress harness.

    Designed for simulation-only workloads.
    """

    def __init__(
        self,
        *,
        policy: SimulationSafetyPolicy,
    ) -> None:

        self.policy = policy

    def run(
        self,
        profile: LoadProfile,
        workload: Optional[
            SimulationWorkload
        ] = None,
    ) -> LoadResult:

        profile.validate(
            self.policy
        )

        workload = (
            workload
            or SyntheticWorkload()
        )

        started = time.monotonic()

        completed = 0
        failed = 0

        lock = threading.Lock()

        def worker(sequence: int) -> None:
            nonlocal completed
            nonlocal failed

            try:
                workload.execute(
                    sequence
                )

                with lock:
                    completed += 1

            except Exception:
                with lock:
                    failed += 1

        with ThreadPoolExecutor(
            max_workers=profile.workers
        ) as executor:

            futures: list[
                Future[None]
            ] = [
                executor.submit(
                    worker,
                    index,
                )
                for index in range(
                    profile.operations
                )
            ]

            for future in as_completed(
                futures
            ):
                future.result()

        duration = (
            time.monotonic()
            - started
        )

        throughput = (
            completed / duration
            if duration > 0
            else float(completed)
        )

        return LoadResult(
            operations_requested=profile.operations,
            operations_completed=completed,
            operations_failed=failed,
            duration_seconds=duration,
            throughput_per_second=throughput,
        )


