class TenantSimulationBoundary:

    @staticmethod
    def assert_same_tenant(
        context: SimulationContext,
        tenant_id: str,
    ) -> None:

        tenant_id = require_non_empty(
            tenant_id,
            "tenant_id",
        )

        if (
            context.tenant_id
            != tenant_id
        ):
            raise SimulationTenantIsolationError(
                "Cross-tenant simulation operation rejected"
            )


# ============================================================================
# SECTION 18 — SIMULATION FACTORY
# ============================================================================

class Phase26SimulationFactory:

    @staticmethod
    def context(
        *,
        tenant_id: str,
        mode: Optional[SimulationMode] = None,
        seed: int = 42,
        simulation_id: Optional[str] = None,
        correlation_id: Optional[str] = None,
    ) -> SimulationContext:

        if mode is None:
            # Resolved at call-time so this binds to the canonical/final
            # SimulationMode rather than the generation live when this
            # method was defined.
            mode = SimulationMode.DRY_RUN

        return SimulationContext(
            simulation_id=(
                simulation_id
                or "sim_"
                + secrets.token_hex(10)
            ),
            tenant_id=tenant_id,
            correlation_id=(
                correlation_id
                or "corr_"
                + secrets.token_hex(10)
            ),
            seed=seed,
            mode=mode,
            created_at=utc_now(),
        )

    @staticmethod
    def basic_scenario(
        tenant_id: str,
    ) -> SimulationScenario:

        return SimulationScenario(
            scenario_id=(
                "scenario_"
                + secrets.token_hex(8)
            ),
            name="Safe Cyber Lifecycle Scenario",
            tenant_id=tenant_id,
            steps=(
                ScenarioStep(
                    step_id="step-1",
                    name="Synthetic Observation",
                    step_type=ScenarioStepType.OBSERVE,
                    target="sim://asset/1",
                ),
                ScenarioStep(
                    step_id="step-2",
                    name="Synthetic Detection",
                    step_type=ScenarioStepType.DETECT,
                    target="sim://asset/1",
                ),
                ScenarioStep(
                    step_id="step-3",
                    name="Synthetic Investigation",
                    step_type=ScenarioStepType.INVESTIGATE,
                    target="sim://incident/1",
                ),
                ScenarioStep(
                    step_id="step-4",
                    name="Safe Response Simulation",
                    step_type=ScenarioStepType.EXECUTE,
                    target="sim://action/1",
                ),
                ScenarioStep(
                    step_id="step-5",
                    name="Synthetic Verification",
                    step_type=ScenarioStepType.VERIFY,
                    target="sim://action/1",
                ),
            ),
        )


