def run_phase_26_tests() -> Dict[str, Any]:
    """
    Executes the Phase-26 test suite when explicitly called.
    """

    tests = [
        test_safety_policy_rejects_real_network,
        test_safety_policy_rejects_real_execution,
        test_safety_policy_requires_dry_run,
        test_external_target_blocked,
        test_synthetic_event_generation,
        test_event_generation_is_deterministic_in_structure,
        test_scenario_validation,
        test_scenario_rejects_external_target,
        test_safe_action_simulation,
        test_destructive_action_blocked,
        test_failure_injection,
        test_timeout_injection,
        test_blast_radius_none,
        test_blast_radius_critical,
        test_simulation_engine_success,
        test_simulation_engine_partial_failure,
        test_simulation_engine_timeout,
        test_simulation_tenant_isolation,
        test_simulation_duplicate_id_blocked,
        test_simulation_fingerprint_exists,
        test_what_if_simulation,
        test_what_if_zero_baseline,
        test_stress_harness,
        test_stress_worker_boundary,
        test_tenant_boundary,
        test_simulation_has_no_real_side_effects,
    ]

    passed = 0
    failed = 0
    failures: list[
        Dict[str, str]
    ] = []

    for test in tests:
        try:
            test()
            passed += 1

        except Exception as exc:
            failed += 1

            failures.append(
                {
                    "test": test.__name__,
                    "error": str(exc),
                }
            )

    return {
        "phase": "26",
        "name": "Safe Simulation & Stress Testing",
        "total": len(tests),
        "passed": passed,
        "failed": failed,
        "success": failed == 0,
        "failures": failures,
    }


