@dataclass(frozen=True)
class FinalTruthRecord:
    truth_class: TruthClass
    value: Any
    source: str
    confidence: float

    def validate(self) -> None:
        require_non_empty(
            self.source,
            "truth source",
        )

        if not (
            0.0 <= self.confidence <= 1.0
        ):
            raise Phase27ValidationError(
                "Truth confidence must be between 0 and 1"
            )


class TruthBoundaryValidator:

    @staticmethod
    def validate(
        record: FinalTruthRecord,
    ) -> None:

        record.validate()

        # AI inference/prediction may never silently
        # become authoritative FACT.
        if (
            record.truth_class
            == TruthClass.FACT
            and record.source.lower()
            in {
                "ai",
                "llm",
                "model",
                "prediction",
                "inference",
            }
        ):
            raise ContractViolationError(
                "AI-derived inference cannot be authoritative FACT"
            )


