class IntegrationCheckSeverity(str, Enum):
    INFO = "info"
    WARNING = "warning"
    ERROR = "error"
    CRITICAL = "critical"


@dataclass(frozen=True)
class IntegrationFinding:
    check_id: str
    severity: IntegrationCheckSeverity
    component: str
    message: str


@dataclass
class IntegrationReport:
    started_at: datetime
    finished_at: Optional[datetime] = None

    findings: list[
        IntegrationFinding
    ] = field(default_factory=list)

    checks_run: int = 0

    def add(
        self,
        finding: IntegrationFinding,
    ) -> None:

        self.findings.append(
            finding
        )

    @property
    def errors(self) -> Tuple[
        IntegrationFinding,
        ...
    ]:

        return tuple(
            finding
            for finding in self.findings
            if finding.severity
            in {
                IntegrationCheckSeverity.ERROR,
                IntegrationCheckSeverity.CRITICAL,
            }
        )

    @property
    def warnings(self) -> Tuple[
        IntegrationFinding,
        ...
    ]:

        return tuple(
            finding
            for finding in self.findings
            if finding.severity
            == IntegrationCheckSeverity.WARNING
        )

    @property
    def success(self) -> bool:
        return not self.errors


# ============================================================================
# 10. FINAL INTEGRATION CHECKER
# ============================================================================

class FinalIntegrationChecker:

    REQUIRED_PHASE_BOUNDARIES = (
        21,
        23,
        24,
        25,
        26,
    )

    def __init__(
        self,
        registry: FinalComponentRegistry,
    ) -> None:

        self.registry = registry

    def _check(
        self,
        report: IntegrationReport,
        check_id: str,
        component: str,
        callback: Callable[[], None],
    ) -> None:

        report.checks_run += 1

        try:
            callback()

        except Exception as exc:

            report.add(
                IntegrationFinding(
                    check_id=check_id,
                    severity=IntegrationCheckSeverity.ERROR,
                    component=component,
                    message=str(exc),
                )
            )

    def check_component_registry(
        self,
        report: IntegrationReport,
    ) -> None:

        def check() -> None:

            components = self.registry.all()

            names = [
                item.name
                for item in components
            ]

            if len(names) != len(set(names)):
                raise ContractViolationError(
                    "Duplicate component names detected"
                )

            for item in components:
                item.validate()

        self._check(
            report,
            "REGISTRY-001",
            "component_registry",
            check,
        )

    def check_required_boundaries(
        self,
        report: IntegrationReport,
    ) -> None:

        def check() -> None:

            components = self.registry.all()

            phases = {
                component.phase
                for component in components
            }

            missing = [
                phase
                for phase in self.REQUIRED_PHASE_BOUNDARIES
                if phase not in phases
            ]

            if missing:
                raise ContractViolationError(
                    "Required phase boundaries missing: "
                    + str(missing)
                )

        self._check(
            report,
            "BOUNDARY-001",
            "phase_boundaries",
            check,
        )

    def check_health_contracts(
        self,
        report: IntegrationReport,
    ) -> None:

        def check() -> None:

            for item in self.registry.all():

                health_method = getattr(
                    item.component,
                    "health",
                    None,
                )

                if health_method is None:
                    continue

                if not callable(
                    health_method
                ):
                    raise ContractViolationError(
                        f"Invalid health contract: {item.name}"
                    )

                health = health_method()

                if not isinstance(
                    health,
                    ComponentHealth,
                ):
                    raise ContractViolationError(
                        f"Invalid health result: {item.name}"
                    )

                health.validate()

                if (
                    health.state
                    == HealthState.FAILED
                ):
                    raise FinalReadinessError(
                        f"Component unhealthy: {item.name}"
                    )

        self._check(
            report,
            "HEALTH-001",
            "component_health",
            check,
        )

    def check_tenant_context(
        self,
        report: IntegrationReport,
    ) -> None:

        def check() -> None:

            context = FinalTenantContext(
                tenant_id="tenant-a",
                correlation_id="corr-final",
                request_id="req-final",
            )

            context.validate()

            TenantBoundaryValidator.assert_same_tenant(
                context,
                "tenant-a",
            )

            try:
                TenantBoundaryValidator.assert_same_tenant(
                    context,
                    "tenant-b",
                )
            except TenantIsolationError:
                return

            raise TenantIsolationError(
                "Tenant boundary failed"
            )

        self._check(
            report,
            "TENANT-001",
            "tenant_isolation",
            check,
        )

    def check_truth_boundary(
        self,
        report: IntegrationReport,
    ) -> None:

        def check() -> None:

            valid = FinalTruthRecord(
                truth_class=TruthClass.EVIDENCE,
                value={
                    "source": "synthetic-verification"
                },
                source="verification",
                confidence=0.95,
            )

            TruthBoundaryValidator.validate(
                valid
            )

            invalid = FinalTruthRecord(
                truth_class=TruthClass.FACT,
                value="unverified",
                source="AI",
                confidence=0.90,
            )

            try:
                TruthBoundaryValidator.validate(
                    invalid
                )
            except ContractViolationError:
                return

            raise ContractViolationError(
                "AI-derived fact boundary failed"
            )

        self._check(
            report,
            "TRUTH-001",
            "truth_boundary",
            check,
        )

    def check_lifecycle_contract(
        self,
        report: IntegrationReport,
    ) -> None:

        def check() -> None:

            for index in range(
                len(FINAL_LIFECYCLE) - 1
            ):

                message = (
                    FinalLifecycleMessage.create(
                        message_id=(
                            f"final-msg-{index}"
                        ),
                        tenant_id="tenant-a",
                        correlation_id="corr-final",
                        causation_id=(
                            f"final-msg-{index - 1}"
                            if index > 0
                            else None
                        ),
                        source_stage=(
                            FINAL_LIFECYCLE[index]
                        ),
                        target_stage=(
                            FINAL_LIFECYCLE[index + 1]
                        ),
                        truth_class=TruthClass.EVIDENCE,
                        payload={
                            "synthetic": True,
                            "stage": index,
                        },
                    )
                )

                LifecycleContractValidator.validate(
                    message
                )

        self._check(
            report,
            "LIFECYCLE-001",
            "lifecycle_contract",
            check,
        )

    def run(
        self,
    ) -> IntegrationReport:

        report = IntegrationReport(
            started_at=utc_now()
        )

        self.check_component_registry(
            report
        )

        self.check_required_boundaries(
            report
        )

        self.check_health_contracts(
            report
        )

        self.check_tenant_context(
            report
        )

        self.check_truth_boundary(
            report
        )

        self.check_lifecycle_contract(
            report
        )

        report.finished_at = utc_now()

        return report


