# ============================================================================
# 14. FINAL LIFECYCLE SYNTHETIC VERIFICATION
# ============================================================================

@dataclass(frozen=True)
class LifecycleVerificationResult:
    stages_checked: int
    transitions_checked: int
    tenant_consistency: bool
    correlation_consistency: bool
    ordering_valid: bool
    fingerprint_integrity: bool

    @property
    def passed(self) -> bool:
        return all(
            (
                self.stages_checked
                == len(FINAL_LIFECYCLE),
                self.transitions_checked
                == len(FINAL_LIFECYCLE) - 1,
                self.tenant_consistency,
                self.correlation_consistency,
                self.ordering_valid,
                self.fingerprint_integrity,
            )
        )


class FinalLifecycleVerifier:

    def verify(
        self,
        *,
        tenant_id: str = "tenant-final",
        correlation_id: str = "correlation-final",
    ) -> LifecycleVerificationResult:

        require_non_empty(
            tenant_id,
            "tenant_id",
        )

        require_non_empty(
            correlation_id,
            "correlation_id",
        )

        previous_message_id: Optional[
            str
        ] = None

        tenant_consistent = True
        correlation_consistent = True
        ordering_valid = True
        fingerprints_valid = True

        transitions = 0

        for index in range(
            len(FINAL_LIFECYCLE) - 1
        ):

            source = FINAL_LIFECYCLE[index]
            target = FINAL_LIFECYCLE[index + 1]

            message_id = (
                f"lifecycle-final-{index}"
            )

            message = (
                FinalLifecycleMessage.create(
                    message_id=message_id,
                    tenant_id=tenant_id,
                    correlation_id=correlation_id,
                    causation_id=previous_message_id,
                    source_stage=source,
                    target_stage=target,
                    truth_class=TruthClass.EVIDENCE,
                    payload={
                        "synthetic": True,
                        "phase": 27,
                        "index": index,
                    },
                )
            )

            try:
                LifecycleContractValidator.validate(
                    message
                )
            except Exception:
                ordering_valid = False
                fingerprints_valid = False

            tenant_consistent &= (
                message.tenant_id
                == tenant_id
            )

            correlation_consistent &= (
                message.correlation_id
                == correlation_id
            )

            previous_message_id = (
                message.message_id
            )

            transitions += 1

        return LifecycleVerificationResult(
            stages_checked=len(
                FINAL_LIFECYCLE
            ),
            transitions_checked=transitions,
            tenant_consistency=tenant_consistent,
            correlation_consistency=correlation_consistent,
            ordering_valid=ordering_valid,
            fingerprint_integrity=fingerprints_valid,
        )


# ============================================================================
# 15. FINAL HANDOVER MANIFEST
# ============================================================================

@dataclass(frozen=True)
class FinalHandoverManifest:
    platform_name: str
    final_phase: int
    lifecycle_stages: Tuple[str, ...]
    required_boundaries: Tuple[int, ...]
    security_ready: bool
    audit_ready: bool
    simulation_ready: bool
    lifecycle_ready: bool
    integration_ready: bool
    generated_at: datetime
    fingerprint: str

    @property
    def ready_for_handover(self) -> bool:
        return all(
            (
                self.final_phase == 27,
                self.security_ready,
                self.audit_ready,
                self.simulation_ready,
                self.lifecycle_ready,
                self.integration_ready,
            )
        )


class FinalHandoverBuilder:

    def build(
        self,
        *,
        integration_report: IntegrationReport,
        security: SecurityReadiness,
        audit: AuditReadiness,
        simulation: SimulationReadiness,
        lifecycle: LifecycleVerificationResult,
    ) -> FinalHandoverManifest:

        SecurityReadinessValidator.validate(
            security
        )

        AuditReadinessValidator.validate(
            audit
        )

        SimulationReadinessValidator.validate(
            simulation
        )

        if not lifecycle.passed:
            raise FinalReadinessError(
                "Lifecycle verification failed"
            )

        if not integration_report.success:
            raise FinalReadinessError(
                "Integration verification failed"
            )

        generated_at = utc_now()

        payload = {
            "platform_name": (
                "HYDRA™ Autonomous "
                "Cybersecurity Intelligence "
                "& Operations Platform"
            ),
            "final_phase": 27,
            "lifecycle_stages": [
                stage.value
                for stage in FINAL_LIFECYCLE
            ],
            "required_boundaries": [
                21,
                23,
                24,
                25,
                26,
            ],
            "security_ready": security.ready,
            "audit_ready": audit.ready,
            "simulation_ready": simulation.ready,
            "lifecycle_ready": lifecycle.passed,
            "integration_ready": (
                integration_report.success
            ),
            "generated_at": (
                generated_at.isoformat()
            ),
        }

        return FinalHandoverManifest(
            platform_name=payload[
                "platform_name"
            ],
            final_phase=27,
            lifecycle_stages=tuple(
                payload["lifecycle_stages"]
            ),
            required_boundaries=(
                21,
                23,
                24,
                25,
                26,
            ),
            security_ready=security.ready,
            audit_ready=audit.ready,
            simulation_ready=simulation.ready,
            lifecycle_ready=lifecycle.passed,
            integration_ready=(
                integration_report.success
            ),
            generated_at=generated_at,
            fingerprint=fingerprint(
                payload
            ),
        )


# ============================================================================
# 16. FINAL VALIDATION ORCHESTRATOR
# ============================================================================

@dataclass(frozen=True)
class FinalValidationResult:
    integration_report: IntegrationReport
    lifecycle_result: LifecycleVerificationResult
    handover_manifest: Optional[
        FinalHandoverManifest
    ]
    ready: bool
    blockers: Tuple[str, ...]


class FinalValidationOrchestrator:

    def __init__(
        self,
        registry: FinalComponentRegistry,
    ) -> None:

        self.registry = registry

    def validate(
        self,
        *,
        security: SecurityReadiness,
        audit: AuditReadiness,
        simulation: SimulationReadiness,
    ) -> FinalValidationResult:

        blockers: list[str] = []

        integration_report = (
            FinalIntegrationChecker(
                self.registry
            ).run()
        )

        lifecycle_result = (
            FinalLifecycleVerifier().verify()
        )

        if not integration_report.success:
            blockers.append(
                "integration_checks_failed"
            )

        if not lifecycle_result.passed:
            blockers.append(
                "lifecycle_verification_failed"
            )

        if not security.ready:
            blockers.append(
                "security_not_ready"
            )

        if not audit.ready:
            blockers.append(
                "audit_not_ready"
            )

        if not simulation.ready:
            blockers.append(
                "simulation_not_safe"
            )

        manifest = None

        if not blockers:
            try:
                manifest = (
                    FinalHandoverBuilder().build(
                        integration_report=(
                            integration_report
                        ),
                        security=security,
                        audit=audit,
                        simulation=simulation,
                        lifecycle=lifecycle_result,
                    )
                )
            except Exception as exc:
                blockers.append(
                    f"handover_manifest_failed: {exc}"
                )

        return FinalValidationResult(
            integration_report=integration_report,
            lifecycle_result=lifecycle_result,
            handover_manifest=manifest,
            ready=not blockers,
            blockers=tuple(blockers),
        )


