def test_final_lifecycle_has_expected_stages() -> None:

    _assert(
        len(FINAL_LIFECYCLE) == 13,
        "Final lifecycle stage count is incorrect",
    )

    _assert(
        FINAL_LIFECYCLE[0]
        == LifecycleStage.OBSERVE,
        "Lifecycle does not begin with OBSERVE",
    )

    _assert(
        FINAL_LIFECYCLE[-1]
        == LifecycleStage.LEARN,
        "Lifecycle does not end with LEARN",
    )


def test_lifecycle_transitions_are_contiguous() -> None:

    for index in range(
        len(FINAL_LIFECYCLE) - 1
    ):

        current = FINAL_LIFECYCLE[index]
        following = FINAL_LIFECYCLE[index + 1]

        _assert(
            FINAL_LIFECYCLE.index(
                following
            )
            ==
            FINAL_LIFECYCLE.index(
                current
            ) + 1,
            "Lifecycle transition gap detected",
        )


