HYDRA_MASTER_BUILD = "part1-integration-v1"
HYDRA_MASTER_SOURCE = "Cyber_hydra_all_FIXED_SYNTAX.py"


class HydraMasterIntegrationError(Exception):
    """Master integration boundary failure."""


class HydraComponentRegistry:
    """Explicit component registry for merge-time wiring."""

    def __init__(self):
        self._components = {}

    def register(self, name, component, *, replace=False):
        if not isinstance(name, str) or not name.strip():
            raise HydraMasterIntegrationError("Component name must be non-empty.")
        if name in self._components and not replace:
            raise HydraMasterIntegrationError(
                f"Duplicate component registration: {name}"
            )
        self._components[name] = component
        return component

    def unregister(self, name):
        return self._components.pop(name, None)

    def get(self, name):
        try:
            return self._components[name]
        except KeyError as exc:
            raise HydraMasterIntegrationError(
                f"Component not registered: {name}"
            ) from exc

    def snapshot(self):
        return dict(self._components)


class HydraMasterRuntime:
    """
    Explicit lifecycle orchestrator for already-implemented components.

    This is the merge boundary for Cyber Part 1. It does not infer hidden
    dependencies or execute cybersecurity actions by itself.
    """

    def __init__(self):
        self.registry = HydraComponentRegistry()
        self._started = False

    @property
    def started(self):
        return self._started

    def register_component(self, name, component, *, replace=False):
        return self.registry.register(name, component, replace=replace)

    async def start(self):
        if self._started:
            return
        started = []
        try:
            for name, component in self.registry.snapshot().items():
                method = getattr(component, "start", None)
                if callable(method):
                    result = method()
                    if hasattr(result, "__await__"):
                        await result
                started.append((name, component))
            self._started = True
        except Exception as exc:
            for _, component in reversed(started):
                method = getattr(component, "stop", None)
                if callable(method):
                    try:
                        result = method()
                        if hasattr(result, "__await__"):
                            await result
                    except Exception:
                        pass
            raise HydraMasterIntegrationError(
                f"Startup rollback triggered: {type(exc).__name__}: {exc}"
            ) from exc

    async def stop(self):
        failures = []
        for name, component in reversed(list(self.registry.snapshot().items())):
            method = getattr(component, "stop", None)
            if callable(method):
                try:
                    result = method()
                    if hasattr(result, "__await__"):
                        await result
                except Exception as exc:
                    failures.append((name, type(exc).__name__, str(exc)))
        self._started = False
        if failures:
            raise HydraMasterIntegrationError(
                f"Shutdown failures: {failures}"
            )

    async def health(self):
        component_health = {}
        for name, component in self.registry.snapshot().items():
            method = getattr(component, "health", None)
            if callable(method):
                try:
                    result = method()
                    if hasattr(result, "__await__"):
                        result = await result
                    component_health[name] = result
                except Exception as exc:
                    component_health[name] = {
                        "status": "error",
                        "error_type": type(exc).__name__,
                    }
        return {
            "master_build": HYDRA_MASTER_BUILD,
            "started": self._started,
            "components": component_health,
        }


def create_master_runtime():
    """Factory for the Cyber Part 1 merge boundary."""
    return HydraMasterRuntime()


