def _canonical_component_collision_report() -> dict[str,_Any]:
    import ast as _ast, collections as _collections
    tree = _ast.parse(open(__file__, encoding="utf-8").read())
    classes = _collections.defaultdict(list); funcs = _collections.defaultdict(list)
    for node in tree.body:
        if isinstance(node, _ast.ClassDef): classes[node.name].append(node.lineno)
        elif isinstance(node, (_ast.FunctionDef,_ast.AsyncFunctionDef)): funcs[node.name].append(node.lineno)
    return {
        "duplicate_class_groups": {k:v for k,v in classes.items() if len(v)>1},
        "duplicate_function_groups": {k:v for k,v in funcs.items() if len(v)>1},
    }


def run_canonical_regression_suite() -> dict[str,_Any]:
    """Deterministic final-suite checks for the authoritative consolidation layer."""
    checks=[]
