    result={"total":len(checks),"passed":sum(x["status"]=="PASS" for x in checks),"failed":sum(x["status"]=="FAIL" for x in checks),"success":all(x["status"]=="PASS" for x in checks),"results":checks}
    result["collision_audit"]={"legacy_duplicate_groups":sum(1 for v in _canonical_component_collision_report()["duplicate_class_groups"].values()),"policy":"canonical runtime contracts are authoritative"}
