def _tenant_boundary_check() -> None:
    a=ObservabilityContext("tenant-a","corr",None,"c","op",None,utc_now())
    if a.tenant_id != "tenant-a": raise AssertionError("tenant binding lost")
    try:
        if a.tenant_id == "tenant-b": raise AssertionError("cross-tenant access accepted")
    except AssertionError: raise

# Harden canonical connector configuration against plaintext transport.
_original_connector_config_post_init = ConnectorConfig.__post_init__
def _connector_config_post_init_hardened(self):
    _original_connector_config_post_init(self)
    if not self.verify_tls and str(self.base_url).lower().startswith("https"):
        raise ValueError("verify_tls=False is forbidden for HTTPS connector endpoints")
    if str(self.base_url).lower().startswith("http://") and self.verify_tls is False:
        raise ValueError("unencrypted connector transport is not permitted by the canonical security boundary")
ConnectorConfig.__post_init__ = _connector_config_post_init_hardened

# Canonical tenant gate: fail closed before policy/RBAC evaluation.
if 'SecurityGate' in globals() and hasattr(SecurityGate, 'authorize_request'):
    _original_security_authorize_request = SecurityGate.authorize_request
    def _security_authorize_request_tenant_first(self, *, request, principal, permission):
        if principal is not None and getattr(principal, 'tenant_id', None) != request.tenant_id:
            raise TenantIsolationError("Security request tenant does not match principal tenant")
        return _original_security_authorize_request(self, request=request, principal=principal, permission=permission)
    SecurityGate.authorize_request = _security_authorize_request_tenant_first

