# Agent status is descriptive metadata; authorization uses enabled/active state.
def _agent_identity_post_init(self):
    # [auto-repair] this originally used require_non_empty() (a
    # string-only check) on agent_id/tenant_id -- but every real usage
    # of AgentIdentity in this file (validate() included, a few lines
    # up) treats agent_id/tenant_id as UUID objects, not strings. Since
    # this __post_init__ was never actually running before (see the
    # note where created_at was added), that mismatch was never
    # exercised. Now that it's wired up for real, using the right check
    # for a UUID-typed field instead of the string-only one.
    if not self.agent_id:
        raise ValidationError("agent_id is required.")
    if not self.tenant_id:
        raise ValidationError("tenant_id is required.")
    require_non_empty(self.name, "name")
    if self.created_at is not None:
        ensure_aware(self.created_at, "created_at")
AgentIdentity.__post_init__ = _agent_identity_post_init

# Merge the two historical emergency-stop contracts without weakening either.
_original_esc_init = EmergencyStopController.__init__
_original_esc_activate = EmergencyStopController.activate
_original_esc_deactivate = EmergencyStopController.deactivate

def _esc_init_canonical(self):
    _original_esc_init(self)
    self.stopped_tenants = set()
    # [auto-repair] the LATER _esc_activate patch (search
    # "EmergencyStopController merged both tenant-scoped and global
    # forms" further down) only records a global stop inside
    # `if hasattr(self, "_lock"):` -- since nothing ever set self._lock,
    # that block silently never ran, so a global (no tenant_id)
    # activate() call recorded nothing. Adding it here makes that
    # guarded block actually do its job.
    self._lock = threading.RLock()

def _esc_activate_canonical(self, tenant_id=None, *, actor=None, reason=None, now=None):
    if tenant_id is not None:
        self.stopped_tenants.add(tenant_id)
        if actor is None: actor = "system"
        if reason is None: reason = "emergency stop"
    return _original_esc_activate(self, actor=actor or "system", reason=reason or "emergency stop", now=now)

def _esc_deactivate_canonical(self, tenant_id=None, *, actor=None):
    if tenant_id is not None:
        self.stopped_tenants.discard(tenant_id)
    if actor is None: actor = "system"
    return _original_esc_deactivate(self, actor=actor)

def _esc_is_stopped_canonical(self, tenant_id=None):
    if tenant_id is not None:
        return tenant_id in self.stopped_tenants
    return bool(self.state.active)

def _esc_assert_execution_allowed(self, tenant_id=None):
    if self._esc_is_stopped_canonical(tenant_id):
        raise PermissionError("Emergency stop is active")
    return True

EmergencyStopController.__init__ = _esc_init_canonical
EmergencyStopController.activate = _esc_activate_canonical
EmergencyStopController.deactivate = _esc_deactivate_canonical
EmergencyStopController.is_stopped = _esc_is_stopped_canonical
EmergencyStopController.assert_execution_allowed = _esc_assert_execution_allowed

def _esc_assert_execution_allowed_v2(self, tenant_id=None):
    if _esc_is_stopped_canonical(self, tenant_id):
        raise PermissionError("Emergency stop is active")
    return True
EmergencyStopController.assert_execution_allowed = _esc_assert_execution_allowed_v2
def _cyber_policy_validate(self):
    require_non_empty(str(self.policy_id), "policy_id")
    if self.tenant_id is not None: require_non_empty(self.tenant_id, "tenant_id")
    if self.version is not None: require_non_empty(str(self.version), "version")
    return self
CyberPolicy.validate = _cyber_policy_validate

# Restore the richer governance ledger append contract lost to a later shadow.
def _ledger_append_canonical(self, record=None, **kwargs):
    if record is not None and not kwargs:
        self._records.append(record)
        return record
    required = ("tenant_id","action_id","event_type","decision","actor_id","reason")
    missing = [k for k in required if k not in kwargs]
    if missing:
        raise TypeError(f"missing governance audit fields: {missing}")
    import hashlib as _hashlib
    metadata = dict(kwargs.get("metadata") or {})
    previous_hash = self._records[-1].record_hash if self._records else "GENESIS"
    payload = {"tenant_id":str(kwargs["tenant_id"]),"action_id":str(kwargs["action_id"]),"event_type":kwargs["event_type"],"decision":kwargs["decision"],"actor_id":str(kwargs["actor_id"]) if kwargs["actor_id"] else None,"reason":kwargs["reason"],"metadata":metadata,"previous_hash":previous_hash}
    record_hash = _hashlib.sha256(canonical_json(payload).encode()).hexdigest()
    rec = GovernanceAuditRecord(record_id=uuid4(),timestamp=utc_now(),tenant_id=kwargs["tenant_id"],action_id=kwargs["action_id"],event_type=kwargs["event_type"],decision=kwargs["decision"],actor_id=kwargs["actor_id"],reason=kwargs["reason"],metadata=metadata,previous_hash=previous_hash,record_hash=record_hash)
    self._records.append(rec)
    return rec
GovernanceAuditLedger.append = _ledger_append_canonical


GovernanceAuditLedger.append = _ledger_append_canonical


# ============================================================================
# CANONICAL MODEL ANNOTATION RE-RESOLUTION
# ============================================================================
# CyberEvidence, CyberFinding, CyberIncident, CyberRisk, CyberDecision,
# CyberAction and CyberVerification are defined near the top of this file,
# before the canonical TruthClass / VerificationStatus enums above exist.
# Because `from __future__ import annotations` is active, their field
# annotations are stored as strings and get resolved by Pydantic against
# the module namespace *at model-build time* -- which, at that point, only
# has an earlier TruthClass/VerificationStatus generation missing members
# such as OUTCOME and PARTIALLY_VERIFIED. model_rebuild(force=True) makes
# each model re-resolve its annotations now, against the canonical enums
# defined above, so a caller passing e.g. TruthClass.OUTCOME is accepted
# instead of being rejected by a stale, narrower enum. This does not
# change any field's declared name, constraints or default -- only which
# generation of the enum type the field validates against.
for _canonical_model in (
    CyberEvidence,
    CyberFinding,
    CyberIncident,
    CyberRisk,
    CyberDecision,
    CyberAction,
    CyberVerification,
):
    try:
        _canonical_model.model_rebuild(force=True)
    except Exception:
        # Best-effort: if a model has no forward refs left to resolve, or
        # model_rebuild is unavailable in this Pydantic version, leave the
        # model as-is rather than fail import.
        pass



