def _final_assert(condition: bool, message: str = "Assertion failed.") -> None:
    if not condition:
        raise AssertionError(message)


# The merged file had a single-argument helper even though later phase
# tests and validators use the conventional (condition, message) form.
_assert = _final_assert


def _final_stable_fingerprint(*values: Any) -> str:
    """Deterministic, collision-safe multi-argument fingerprint."""
    payload = json.dumps(
        [_final_serialize(v) for v in values],
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        default=_final_serialize,
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def _final_serialize(value: Any, _seen: Optional[set[int]] = None) -> Any:
    if _seen is None:
        _seen = set()
    primitive = value is None or isinstance(value, (bool, int, float, str))
    if primitive:
        return value
    oid = id(value)
    if oid in _seen:
        raise ValueError("Circular reference detected during serialization")
    _seen.add(oid)
    try:
        if isinstance(value, Enum):
            return _final_serialize(value.value, _seen)
        if isinstance(value, datetime):
            return value.isoformat()
        if is_dataclass(value):
            return _final_serialize(asdict(value), _seen)
        if isinstance(value, Mapping):
            normalized: dict[str, Any] = {}
            original_keys: dict[str, Any] = {}
            for key, item in value.items():
                skey = str(key)
                if skey in normalized and original_keys[skey] != key:
                    raise ValueError(
                        f"Mapping key collision after string normalization: "
                        f"{original_keys[skey]!r} vs {key!r}"
                    )
                original_keys[skey] = key
                normalized[skey] = _final_serialize(item, _seen)
            return normalized
        if isinstance(value, (list, tuple)):
            return [_final_serialize(item, _seen) for item in value]
        if isinstance(value, (set, frozenset)):
            return sorted(
                (_final_serialize(item, _seen) for item in value),
                key=lambda item: repr(item),
            )
        if hasattr(value, "to_dict"):
            return _final_serialize(value.to_dict(), _seen)
        if hasattr(value, "__dict__"):
            return _final_serialize(
                {
                    key: item
                    for key, item in vars(value).items()
                    if not key.startswith("_")
                },
                _seen,
            )
        return f"<opaque:{type(value).__module__}.{type(value).__qualname__}>"
    finally:
        _seen.discard(oid)


def _final_canonical_json(value: Any) -> str:
    return json.dumps(
        _final_serialize(value),
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    )


def _final_deep_copy(value: Any) -> Any:
    # The historical helper's name implies a defensive copy, not a
    # JSON type-erasing round-trip.
    return _final_copy.deepcopy(value)


def _final_deterministic_id(*parts: str) -> str:
    payload = json.dumps(
        [str(part) for part in parts],
        separators=(",", ":"),
        ensure_ascii=False,
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


# Canonical serialization helpers.
serialize_value = _final_serialize
canonical_json = _final_canonical_json
canonical_json_bytes = lambda value: canonical_json(value).encode("utf-8")
sha256_hex = lambda value: hashlib.sha256(canonical_json_bytes(value)).hexdigest()
deep_copy_json = _final_deep_copy
deterministic_id = _final_deterministic_id
stable_fingerprint = _final_stable_fingerprint


def _final_canonical(value: Any, _seen: Optional[set[int]] = None) -> str:
    if _seen is None:
        _seen = set()
    primitive = value is None or isinstance(value, (bool, int, float, str))
    if primitive:
        return "null" if value is None else repr(value)
    oid = id(value)
    if oid in _seen:
        # [auto-repair] was `return f"<circular:{type(value).__name__}>"`
        # -- two different circular structures involving the same type
        # at the cycle point would silently produce the same canonical
        # text there, which is a real fingerprint-collision risk for a
        # function whose whole purpose is producing hashes/audit
        # fingerprints. Nothing in this file currently relies on the
        # old graceful-substitution behavior (no test exercises it).
        # Failing loudly is correct here: this function can't produce
        # a safe deterministic serialization of a circular structure,
        # so it shouldn't pretend to.
        raise ValueError(
            f"Cannot produce a canonical serialization of a circular "
            f"reference (type {type(value).__name__})."
        )
    _seen.add(oid)
    try:
        if isinstance(value, Enum):
            return _final_canonical(value.value, _seen)
        if isinstance(value, datetime):
            return value.astimezone(timezone.utc).isoformat()
        if isinstance(value, Mapping):
            items = sorted(value.items(), key=lambda item: str(item[0]))
            return "{" + ",".join(
                f"{repr(str(k))}:{_final_canonical(v, _seen)}"
                for k, v in items
            ) + "}"
        if isinstance(value, (list, tuple)):
            return "[" + ",".join(
                _final_canonical(v, _seen) for v in value
            ) + "]"
        if isinstance(value, (set, frozenset)):
            vals = sorted(
                (_final_canonical(v, _seen) for v in value)
            )
            return "[" + ",".join(vals) + "]"
        if hasattr(value, "to_dict"):
            return _final_canonical(value.to_dict(), _seen)
        if hasattr(value, "__dict__"):
            public = {
                key: item
                for key, item in vars(value).items()
                if not key.startswith("_")
            }
            return _final_canonical(public, _seen)
        return f"<opaque:{type(value).__module__}.{type(value).__qualname__}>"
    finally:
        _seen.discard(oid)


_canonical_final = _final_canonical


