# ---------------------------------------------------------------------------
# AuthorizationRequest: support both surviving historical constructor shapes
# while using resource_tenant_id as the authoritative tenant field.
# ---------------------------------------------------------------------------

def _authorization_request_init(
    self,
    principal,
    resource=None,
    operation=None,
    resource_tenant_id=None,
    resource_attributes=None,
    environment_attributes=None,
    **kwargs,
):
    tenant_id = kwargs.pop("tenant_id", None)
    permission = kwargs.pop("permission", None)
    context = kwargs.pop("context", None)
    if kwargs:
        raise TypeError(
            f"Unexpected AuthorizationRequest arguments: {sorted(kwargs)}"
        )
    if resource_tenant_id is None:
        resource_tenant_id = tenant_id
    if resource is None and permission is not None:
        resource = getattr(permission, "resource", None) or getattr(permission, "canonical", "security")
    if operation is None and permission is not None:
        operation = getattr(permission, "action", None) or getattr(permission, "value", "read")
    if resource is None:
        resource = "security"
    if operation is None:
        operation = "read"
    if resource_tenant_id is None:
        resource_tenant_id = getattr(principal, "tenant_id", None)
    if resource_attributes is None:
        resource_attributes = SecurityAttributes({})
    if environment_attributes is None:
        environment_attributes = SecurityAttributes({})
    object.__setattr__(self, "principal", principal)
    object.__setattr__(self, "resource", str(resource))
    object.__setattr__(self, "operation", str(operation))
    object.__setattr__(self, "resource_tenant_id", resource_tenant_id)
    object.__setattr__(self, "resource_attributes", resource_attributes)
    object.__setattr__(self, "environment_attributes", environment_attributes)
    # compatibility aliases expected by Phase 25 authorization code
    object.__setattr__(self, "tenant_id", resource_tenant_id)
    object.__setattr__(self, "permission", permission)


def _authorization_request_validate(self):
    if not self.resource_tenant_id:
        raise ValueError("resource_tenant_id is required")
    principal_tenant = getattr(self.principal, "tenant_id", None)
    if principal_tenant != self.resource_tenant_id:
        raise TenantIsolationError(
            "Principal tenant does not match request tenant"
        )
    if not getattr(self.principal, "authenticated", True):
        raise PermissionError("Principal is not authenticated")


AuthorizationRequest.__init__ = _authorization_request_init
AuthorizationRequest.validate = _authorization_request_validate


# ---------------------------------------------------------------------------
# Permission: merged file had an Enum but Phase 25 uses resource/action pairs.
# Make it a compact immutable value object while preserving named permissions.
# ---------------------------------------------------------------------------

class _CanonicalPermission:
    __slots__ = ("resource", "action", "scope")

    def __init__(self, resource: str, action: Optional[str] = None, scope: Optional[str] = None):
        if action is None:
            value = str(resource)
            if ":" in value:
                resource, action = value.split(":", 1)
            else:
                resource, action = "*", value
        self.resource = str(resource)
        self.action = str(action)
        self.scope = scope

    @property
    def value(self) -> str:
        return self.canonical

    @property
    def canonical(self) -> str:
        return f"{self.resource}:{self.action}"

    def matches(self, resource: str, operation: str, scope: Optional[str] = None) -> bool:
        return (
            self.resource in ("*", resource)
            and self.action in ("*", operation)
            and (self.scope is None or self.scope == scope)
        )

    def __hash__(self):
        return hash((self.resource, self.action, self.scope))

    def __eq__(self, other):
        return (
            isinstance(other, _CanonicalPermission)
            and (self.resource, self.action, self.scope)
            == (other.resource, other.action, other.scope)
        )

    def __repr__(self):
        return f"Permission({self.canonical!r})"


for _name, _value in {
    "READ": ("*", "read"),
    "ANALYZE": ("*", "analyze"),
    "INVESTIGATE": ("*", "investigate"),
    "PLAN": ("*", "plan"),
    "PROPOSE": ("*", "propose"),
    "EXECUTE": ("*", "execute"),
    "VERIFY": ("*", "verify"),
    "LEARN": ("*", "learn"),
}.items():
    setattr(_CanonicalPermission, _name, _CanonicalPermission(*_value))
Permission = _CanonicalPermission


# Final RBAC permission contract: supports both enum-like names and Phase-6 resource/action records.
class _FinalPermission:
    __slots__ = ("permission_id", "resource", "operation", "action", "scope")
    def __init__(self, permission_id=None, resource=None, operation=None, scope=None, action=None):
        if resource is None and operation is None and action is None:
            text = str(permission_id or "")
            if ":" in text:
                resource, operation = text.split(":", 1)
            else:
                resource, operation = "*", text
        else:
            resource = "*" if resource is None else resource
            operation = operation if operation is not None else action
        self.permission_id = str(permission_id or f"{resource}:{operation}")
        self.resource = str(resource)
        self.operation = str(operation)
        self.action = self.operation
        self.scope = scope
    @property
    def value(self): return f"{self.resource}:{self.operation}"
    @property
    def canonical(self): return self.value
    def matches(self, resource, operation, scope=None):
        return self.resource in ("*", resource) and self.operation in ("*", operation) and (self.scope is None or self.scope == scope)
    def __hash__(self): return hash((self.resource,self.operation,self.scope))
    def __eq__(self, other): return isinstance(other, _FinalPermission) and (self.resource,self.operation,self.scope)==(other.resource,other.operation,other.scope)
    def __repr__(self): return f"Permission({self.canonical!r})"
for _n,_v in {"READ":("*","read"),"ANALYZE":("*","analyze"),"INVESTIGATE":("*","investigate"),"PLAN":("*","plan"),"PROPOSE":("*","propose"),"EXECUTE":("*","execute"),"VERIFY":("*","verify"),"LEARN":("*","learn")}.items():
    setattr(_FinalPermission,_n,_FinalPermission(_n,*_v))
Permission = _FinalPermission

