def _agent_identity_validate(self):
    require_nonempty(self.name, "name")
    require_nonempty(self.version, "version")
    aid = self.agent_id
    tid = self.tenant_id
    if not isinstance(aid, (str, UUID)):
        raise TypeError("agent_id must be UUID or str")
    if isinstance(aid, str):
        if not re.fullmatch(r"[A-Za-z0-9_:.\-]{1,160}", aid):
            raise ValueError("agent_id has invalid characters")
    if not isinstance(tid, (str, UUID)):
        raise TypeError("tenant_id must be UUID or str")
    if isinstance(tid, str):
        if not re.fullmatch(r"[A-Za-z0-9_:.\-]{1,160}", tid):
            raise ValueError("tenant_id has invalid characters")
    if self.agent_type is not None and "AgentType" in globals():
        if not isinstance(self.agent_type, AgentType):
            raise TypeError("agent_type must be AgentType")
    if "AgentStatus" in globals() and not isinstance(self.status, AgentStatus):
        try:
            object.__setattr__(
                self, "status",
                AgentStatus(str(self.status).strip().lower()),
            )
        except Exception:
            pass


AgentIdentity.validate = _agent_identity_validate


def _agent_limits_validate(self):
    numeric = {
        "max_actions_per_run": self.max_actions_per_run,
        "max_tool_calls_per_run": self.max_tool_calls_per_run,
        "max_high_risk_requests": self.max_high_risk_requests,
        "max_execution_requests": self.max_execution_requests,
    }
    for name, value in numeric.items():
        if not isinstance(value, int) or isinstance(value, bool) or value < 0:
            raise ValueError(f"{name} must be a non-negative integer")
    if not 0.0 <= float(self.max_execution_risk_score) <= 100.0:
        raise ValueError("max_execution_risk_score must be between 0 and 100")
    # Phase-8 agents never receive direct side-effect authority.
    if self.allow_external_side_effects or self.allow_external_execution:
        raise ValueError("External execution/side effects are forbidden at agent layer")


