ToolDefinition.__init__ = _tool_definition_init


def _map_capability_to_phase8(value):
    if isinstance(value, Capability):
        return value
    if isinstance(value, AgentCapability):
        mapping = {
            AgentCapability.READ_TELEMETRY: Capability.READ_EVENTS,
            AgentCapability.READ_ASSETS: Capability.READ_ENTITIES,
            AgentCapability.READ_FINDINGS: Capability.READ_FINDINGS,
            AgentCapability.READ_INCIDENTS: Capability.READ_INCIDENTS,
            AgentCapability.READ_THREAT_INTELLIGENCE: Capability.READ_THREAT_INTEL,
            AgentCapability.DETECT: Capability.ANALYZE_DETECTION,
            AgentCapability.CORRELATE: Capability.CORRELATE,
            AgentCapability.INVESTIGATE: Capability.INVESTIGATE,
            AgentCapability.ANALYZE: Capability.ANALYZE,
            AgentCapability.ASSESS_RISK: Capability.ASSESS_RISK,
            AgentCapability.ANALYZE_ATTACK_PATH: Capability.ANALYZE_ATTACK_PATH,
            AgentCapability.PROPOSE_ACTION: Capability.PROPOSE_ACTION,
            AgentCapability.LEARN: Capability.LEARN,
        }
        return mapping.get(value, Capability.ANALYZE)
    try:
        return Capability(value)
    except Exception:
        return Capability.ANALYZE


def _registered_tool_init(self, definition=None, handler=None, name=None, capability=None, **kwargs):
    if kwargs:
        raise TypeError(f"Unexpected RegisteredTool arguments: {sorted(kwargs)}")
    if definition is None:
        if name is None:
            raise ValueError("RegisteredTool requires name or definition")
        cap = _map_capability_to_phase8(
            capability if capability is not None else Capability.ANALYZE
        )
        definition = ToolDefinition(
            name=str(name),
            capabilities=frozenset({cap}),
            side_effecting=False,
        )
    elif not isinstance(definition, ToolDefinition):
        raise TypeError("definition must be ToolDefinition")
    object.__setattr__(self, "definition", definition)
    object.__setattr__(self, "handler", handler)


RegisteredTool.__init__ = _registered_tool_init


def _agent_runtime_init(
    self,
    identity,
    policy,
    audit_sink=None,
    tools=None,
):
    self.identity = identity
    self.policy = policy
    self.audit_sink = audit_sink if audit_sink is not None else (
        InMemoryAgentAuditSink() if "InMemoryAgentAuditSink" in globals()
        else type("_FallbackAuditSink", (), {
            "record": lambda _self, _event: None
        })()
    )
    self.tools = dict(tools or {})
    self.state = AgentState.READY
    self.action_count = 0
    self.high_risk_count = 0
    self.execution_request_count = 0
    self.started_at = None
    self._lock = threading.RLock()
    self.identity.validate()
    self.policy.validate()
    if self.identity.agent_type == getattr(AgentType, "EXECUTION", object()):
        if self.policy.limits.allow_external_side_effects:
            raise ValueError("Execution agent cannot receive external side-effect authority")


def _agent_runtime_require_tenant(self, tenant_id):
    if str(tenant_id) != str(self.identity.tenant_id):
        raise PermissionError("Agent tenant boundary violation")


AgentRuntime.__init__ = _agent_runtime_init
AgentRuntime.require_tenant = _agent_runtime_require_tenant


def _agent_runtime_validate_action(self, request):
    with self._lock:
        self.require_tenant(request.tenant_id)
        if request.agent_id != self.identity.agent_id:
            raise AgentTenantError("Action does not belong to this agent.")
        if self.state not in {AgentState.READY, AgentState.RUNNING}:
            raise AgentStateError("Agent cannot request actions in its current state.")
        self.require_capability(AgentCapability.PROPOSE_ACTION)
        self.require_permission(AgentPermission.PROPOSE)
        if self.action_count >= self.policy.limits.max_actions_per_run:
            raise AgentLimitError("Action limit exceeded.")
        risk = str(request.risk_level).lower()
        # [auto-repair] added (matches the fix in the class body
        # above, which this patch overrides at runtime -- confirmed
        # via a live test that without this, a LOW-max-risk agent
        # validated a MEDIUM-risk action with no error at all).
        # AgentLimits.max_risk_level was never compared against the
        # request's risk level anywhere in this method.
        _RISK_ORDER_LOCAL = {"none": -1, "read_only": 0, "low": 1, "medium": 2, "high": 3, "critical": 4}
        _max_risk = str(self.policy.limits.max_risk_level).lower()
        if _max_risk.startswith("risklevel."):
            _max_risk = _max_risk.split(".", 1)[1]
        if _RISK_ORDER_LOCAL.get(risk, 99) > _RISK_ORDER_LOCAL.get(_max_risk, -1):
            raise AgentLimitError("Requested risk exceeds agent's configured max_risk_level.")
        if risk in {"high", "critical"} and self.high_risk_count >= self.policy.limits.max_high_risk_requests:
            raise AgentLimitError("High-risk action limit exceeded.")
        if str(request.action_type).lower() in {"execute", "execution"}:
            if not self.policy.allow_execution_requests:
                raise AgentPermissionError("Agent is not authorized to request execution.")
            if self.execution_request_count >= self.policy.limits.max_execution_requests:
                raise AgentLimitError("Execution request limit exceeded.")
        self.action_count += 1
        if risk in {"high", "critical"}:
            self.high_risk_count += 1
        if str(request.action_type).lower() in {"execute", "execution"}:
            self.execution_request_count += 1
        return AgentActionResult(
            action_id=request.action_id,
            accepted=True,
            reason="Agent-level validation passed. Downstream governance and authorization are still required.",
            fingerprint=request.fingerprint(),
        )


AgentRuntime.validate_action = _agent_runtime_validate_action


