# MFA: attempt limits, expiry, single-use burn, cleanup.
if "MFAProvider" in globals():
    _mfa_verify_original = MFAProvider.verify_challenge
    def _mfa_verify_hardened(self, challenge_id, actor_id, validator):
        lock = getattr(self, "_lock", threading.RLock())
        with lock:
            attempts = getattr(self, "_attempts", None)
            if attempts is None:
                attempts = {}
                self._attempts = attempts
            maximum = getattr(self, "_MAX_ATTEMPTS", 5)
            challenge = getattr(self, "_challenges", {}).get(challenge_id)
            if challenge is None:
                return False
            now = utc_now_v5()
            if challenge.expires_at < now:
                self._challenges.pop(challenge_id, None)
                attempts.pop(challenge_id, None)
                return False
            if getattr(challenge, "verified", False):
                return False
            if challenge.actor_id != actor_id:
                return False
            count = attempts.get(challenge_id, 0)
            if count >= maximum:
                raise PermissionError("Too many attempts")
            attempts[challenge_id] = count + 1
            ok = bool(validator(challenge))
            if ok:
                challenge.verified = True
                self._challenges.pop(challenge_id, None)
                attempts.pop(challenge_id, None)
            return ok
    MFAProvider.verify_challenge = _mfa_verify_hardened


# SecretVault rotation: stage plaintext and re-encrypt everything before
# changing the tenant key.
if "SecretVault" in globals():
    # [auto-repair] The rotation logic below was written for a different
    # SecretVault shape than the one that actually exists in this file:
    # it expects self._tenant_key()/self._keys[tenant_id] (per-tenant
    # keys) and self._records[...] holding objects with .ciphertext/
    # .rotated_at. The real SecretVault here has one single self._key
    # for all tenants and stores raw encrypted bytes in self._secrets --
    # none of those names exist on it. Calling rotate_key() would have
    # crashed with AttributeError partway through re-encrypting secrets,
    # which is a bad place to fail. Left as an explicit NotImplementedError
    # instead of guessing at a per-tenant-key redesign; a working
    # rotate_key needs someone to decide whether keys should be global
    # or per-tenant first.
    def _rotate_key_atomic(self, tenant_id: str) -> None:
        raise NotImplementedError(
            "SecretVault.rotate_key is not implemented against the "
            "current single-key SecretVault design -- see the "
            "[auto-repair] note above this function."
        )
    SecretVault.rotate_key = _rotate_key_atomic


# ---------------------------------------------------------------------------
# Encryption / connector transport hardening
# ---------------------------------------------------------------------------

if "EncryptionEngine" in globals():
    _enc_encrypt_original = EncryptionEngine.encrypt
    _enc_decrypt_original = EncryptionEngine.decrypt
    def _enc_encrypt(self, plaintext: bytes, *, aad: bytes = b"") -> str:
        nonce = secrets.token_bytes(16)
        stream = self._keystream(nonce, len(plaintext))
        ciphertext = bytes(a ^ b for a, b in zip(plaintext, stream))
        versioned = b"\x01" + nonce + ciphertext
        tag = hmac.new(self._key, aad + versioned, hashlib.sha256).digest()
        return base64.urlsafe_b64encode(versioned + tag).decode("ascii")
    def _enc_decrypt(self, encoded: str, *, aad: bytes = b"") -> bytes:
        raw = base64.urlsafe_b64decode(encoded.encode("ascii"))
        if len(raw) < 1 + 16 + 32:
            raise ValueError("Ciphertext is truncated")
        version = raw[0]
        if version != 1:
            raise ValueError(f"Unsupported encryption version: {version}")
        body = raw[:-32]
        tag = raw[-32:]
        expected = hmac.new(self._key, aad + body, hashlib.sha256).digest()
        if not hmac.compare_digest(tag, expected):
            raise ValueError("Ciphertext authentication failed")
        nonce = body[1:17]
        ciphertext = body[17:]
        stream = self._keystream(nonce, len(ciphertext))
        return bytes(a ^ b for a, b in zip(ciphertext, stream))
    EncryptionEngine.encrypt = _enc_encrypt
    EncryptionEngine.decrypt = _enc_decrypt


if "PasswordHasher" in globals():
    def _password_verify(self, password: str, encoded: str) -> bool:
        try:
            return self._verify_impl(password, encoded) if hasattr(self, "_verify_impl") else self._verify_original(password, encoded)
        except (ValueError, base64.binascii.Error) as exc:
            raise CredentialError(f"Malformed password hash: {exc}") from exc
    # Keep the historical implementation available; only normalize errors
    # if it exposes the expected internal helper.
    if hasattr(PasswordHasher, "_verify"):
        _password_original = PasswordHasher._verify
        def _verify_password_compat(self, password, encoded):
            try:
                return _password_original(self, password, encoded)
            except (ValueError, base64.binascii.Error) as exc:
                raise CredentialError(f"Malformed password hash: {exc}") from exc
        PasswordHasher._verify = _verify_password_compat


# No-redirect + public-host guard for generic HTTP connectors.
class _FinalNoRedirect(_final_urllib_request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        raise _final_urllib_error.HTTPError(
            newurl, code, "Redirects disabled", headers, fp
        )


_FINAL_HTTP_OPENER = _final_urllib_request.build_opener(_FinalNoRedirect)


def _final_assert_public_host(url: str) -> None:
    parsed = _final_urllib_parse.urlparse(url)
    if parsed.scheme not in {"https", "http"}:
        raise ConnectorConfigurationError("Unsupported URL scheme")
    host = parsed.hostname
    if not host:
        raise ConnectorConfigurationError("Missing host")
    try:
        infos = _final_socket.getaddrinfo(
            host,
            parsed.port or (443 if parsed.scheme == "https" else 80),
            type=_final_socket.SOCK_STREAM,
        )
    except OSError as exc:
        raise ConnectorConfigurationError(f"DNS resolution failed for {host}") from exc
    for info in infos:
        ip = _final_ipaddress.ip_address(info[4][0])
        if (
            ip.is_private
            or ip.is_loopback
            or ip.is_link_local
            or ip.is_multicast
            or ip.is_reserved
            or ip.is_unspecified
        ):
            raise ConnectorConfigurationError(f"SSRF blocked: {host} -> {ip}")


