def _cyber_action_request_init(
    self,
    action_id=None,
    tenant_id=None,
    requested_by=None,
    agent_id=None,
    action=None,
    action_level=None,
    target_id="target-001",
    target_type="generic",
    risk_score=0.0,
    confidence=1.0,
    incident_id=None,
    finding_id=None,
    reason="",
    evidence_ids=(),
    **kwargs,
):
    # Accept the richer Phase-14 shape:
    # tenant_id/principal_id/principal_type/action_type/risk_level/metadata.
    principal_id = kwargs.pop("principal_id", requested_by)
    principal_type = kwargs.pop("principal_type", None)
    action_type = kwargs.pop("action_type", action)
    risk_level = kwargs.pop("risk_level", action_level)
    metadata = kwargs.pop("metadata", {})
    request_id = kwargs.pop("request_id", None)
    if kwargs:
        raise TypeError(f"Unexpected CyberActionRequest arguments: {sorted(kwargs)}")
    if tenant_id is None:
        raise ValueError("tenant_id is required")
    if requested_by is None:
        requested_by = principal_id or "system"
    if agent_id is None:
        agent_id = requested_by
    if action is None:
        try:
            action = ResponseAction(action_type or "collect_evidence")
        except Exception:
            action = next(iter(ResponseAction))
    if action_level is None:
        action_level = (
            risk_level if isinstance(risk_level, ActionLevel)
            else ActionLevel.LOW_RISK_AUTONOMOUS
        )
    if request_id is None:
        request_id = f"req_{uuid4().hex}"
    object.__setattr__(self, "action_id", action_id or uuid4())
    object.__setattr__(self, "tenant_id", tenant_id)
    object.__setattr__(self, "requested_by", requested_by)
    object.__setattr__(self, "agent_id", agent_id)
    object.__setattr__(self, "action", action)
    object.__setattr__(self, "action_level", action_level)
    object.__setattr__(self, "target_id", str(target_id))
    object.__setattr__(self, "target_type", str(target_type))
    object.__setattr__(self, "risk_score", float(risk_score))
    object.__setattr__(self, "confidence", float(confidence))
    object.__setattr__(self, "incident_id", incident_id)
    object.__setattr__(self, "finding_id", finding_id)
    object.__setattr__(self, "reason", str(reason))
    object.__setattr__(self, "evidence_ids", tuple(evidence_ids))
    object.__setattr__(self, "requested_at", utc_now_v7() if "utc_now_v7" in globals() else utc_now())
    object.__setattr__(self, "request_id", str(request_id))
    object.__setattr__(self, "principal_id", str(principal_id) if principal_id is not None else "")
    object.__setattr__(self, "principal_type", principal_type)
    object.__setattr__(self, "action_type", str(action_type or getattr(action, "value", action)))
    object.__setattr__(self, "risk_level", action_level)
    object.__setattr__(self, "metadata", dict(metadata or {}))


