def _cyber_policy_matches(self, request, context=None):
    if getattr(self, "tenant_id", None) not in (None, request.tenant_id):
        return False
    if getattr(self, "subject", None) is not None:
        subject = self.subject
        if subject.tenant_id not in (None, str(request.tenant_id)):
            return False
        if subject.principal_id not in (None, str(getattr(request, "principal_id", ""))):
            return False
        if subject.action_types and str(getattr(request, "action_type", request.action)).lower() not in {
            str(v).lower() for v in subject.action_types
        }:
            return False
        if subject.target_types and str(request.target_type) not in subject.target_types:
            return False
    if self.rules:
        return any(rule.matches(request) for rule in self.rules)
    return bool(getattr(self, "effect", None))


CyberPolicy.matches = _cyber_policy_matches


# Make store ordering deterministic and compatible with the policy superset.
def _policy_store_active_for_tenant(self, tenant_id):
    policies = [
        policy for policy in self._policies.values()
        if getattr(policy, "enabled", True)
        and (
            getattr(getattr(policy, "subject", None), "tenant_id", None) in (None, str(tenant_id))
            or getattr(policy, "tenant_id", None) in (None, tenant_id)
        )
    ]
    return sorted(
        policies,
        key=lambda policy: (
            getattr(policy, "priority", 100),
            str(policy.policy_id),
        ),
    )


CyberPolicyStore.active_for_tenant = _policy_store_active_for_tenant


# Governance engine needs the compatibility aliases and deterministic policy precedence.
def _gov_evaluate(self, request, *, context=None):
    matched = self.evaluate_policies(request, context)
    decision = self._default_decision(request.risk_level)
    reasons = []
    if request.risk_level == ActionLevel.READ_ONLY:
        reasons.append("read_only_action")
    elif request.risk_level == ActionLevel.LOW_RISK_AUTONOMOUS:
        reasons.append("low_risk_autonomous_action")
    elif request.risk_level in {ActionLevel.MEDIUM_RISK_APPROVAL, ActionLevel.MEDIUM_RISK}:
        decision = GovernanceDecision.REQUIRE_APPROVAL
        reasons.append("medium_risk_requires_approval")
    elif request.risk_level in {ActionLevel.HIGH_RISK_HUMAN, ActionLevel.HIGH_RISK_HUMAN_APPROVAL, ActionLevel.HIGH_RISK}:
        decision = GovernanceDecision.REQUIRE_APPROVAL
        reasons.append("high_risk_requires_human_approval")
    elif request.risk_level in {ActionLevel.EMERGENCY_BREAK_GLASS, ActionLevel.EMERGENCY}:
        decision = GovernanceDecision.BREAK_GLASS
        reasons.append("emergency_break_glass_path")
    for policy in matched:
        effect = getattr(policy, "effect", None)
        if effect == PolicyEffect.DENY:
            decision = GovernanceDecision.DENY
            reasons.append(f"policy_denied:{policy.policy_id}")
            break
        if effect == PolicyEffect.REQUIRE_APPROVAL:
            decision = GovernanceDecision.REQUIRE_APPROVAL
            reasons.append(f"policy_requires_approval:{policy.policy_id}")
        elif effect == PolicyEffect.ALLOW and decision != GovernanceDecision.REQUIRE_APPROVAL:
            decision = GovernanceDecision.ALLOW
            reasons.append(f"policy_allowed:{policy.policy_id}")
    return GovernanceDecisionRecord(
        decision_id=f"gov_{uuid4().hex}",
        request_id=request.request_id,
        tenant_id=request.tenant_id,
        decision=decision,
        action_level=request.risk_level,
        matched_policy_ids=tuple(str(p.policy_id) for p in matched),
        reason_codes=tuple(reasons),
    )


CyberGovernanceEngine.evaluate = _gov_evaluate


