# The state must mark the stage just processed, not the next stage emitted.
if "CrossLayerOrchestrator" in globals():
    _clo_process_original = CrossLayerOrchestrator._process_stage
    def _clo_process_stage(self, message):
        if message.tenant_id != message.context.tenant_id:
            raise TenantIsolationError("Cross-layer tenant violation")
        if not self.dedup.reserve(message.tenant_id, message.message_id):
            raise DuplicateMessageError(f"Message already processed: {message.message_id}")
        self._set_current_stage(message)
        handler = self.wiring.get(message.stage)
        try:
            result = handler.handle(message)
            self._validate_stage_output(message, result)
            self._mark_completed(message)
            self._audit(result, MessageStatus.PROCESSED)
            return result
        except Exception as exc:
            self._mark_failed(message, exc)
            self._audit(message, MessageStatus.FAILED, error=str(exc))
            raise PipelineExecutionError(
                f"Stage {message.stage.value} failed: {exc}"
            ) from exc
    CrossLayerOrchestrator._process_stage = _clo_process_stage


# ---------------------------------------------------------------------------
# Phase 23 persistence: preserve duplicate/integrity exception semantics.
# ---------------------------------------------------------------------------

if "SQLitePersistenceStore" in globals():
    _sp_transaction_original = SQLitePersistenceStore.transaction
    # The contextmanager method is replaced with a function that does not
    # blanket-wrap Phase23DuplicateError / Phase23IntegrityError.
    @contextmanager
    def _sp_transaction(self):
        with self._lock:
            with self._connection() as connection:
                try:
                    connection.execute("BEGIN IMMEDIATE")
                    yield connection
                    connection.execute("COMMIT")
                except Exception:
                    try:
                        connection.execute("ROLLBACK")
                    except sqlite3.Error:
                        pass
                    raise
    SQLitePersistenceStore.transaction = _sp_transaction


