if "APIKeyManager" in globals():
    _api_create_original = getattr(APIKeyManager, "create", None)
    def _api_init(self, config=None):
        self.config = config or getattr(self, "config", None)
        if self.config is None:
            class _KeyConfig:
                api_key_bytes = 48
            self.config = _KeyConfig()
        self._keys = {}
        self._records = {}
        self._lock = threading.RLock()
        self.PREFIX = "hydra_"
    APIKeyManager.__init__ = _api_init

    if hasattr(APIKeyManager, "generate"):
        _api_generate_original = APIKeyManager.generate
        def _api_generate(self, tenant_id, principal_id, *, expires_at=None):
            try:
                return _api_generate_original(self, tenant_id, principal_id, expires_at=expires_at)
            except AttributeError:
                raw = secrets.token_urlsafe(self.config.api_key_bytes)
                plaintext = self.PREFIX + raw
                key_id = secrets.token_hex(12)
                record = APIKeyRecord(
                    key_id=key_id,
                    tenant_id=tenant_id,
                    principal_id=principal_id,
                    key_hash=sha256_hex(plaintext),
                    created_at=utc_now(),
                    expires_at=expires_at,
                )
                self._records[key_id] = record
                return GeneratedAPIKey(key_id=key_id, plaintext_key=plaintext, record=record)
        APIKeyManager.generate = _api_generate


