if "ResponseIdempotencyStore" in globals():
    _ris_get_original = ResponseIdempotencyStore.get
    def _ris_init(self):
        self._records = {}
        self._lock = threading.RLock()
    def _ris_get(self, key):
        with self._lock:
            return self._records.get(key)
    def _ris_put(self, key, result, *, now):
        with self._lock:
            if key in self._records:
                return
            self._records[key] = IdempotencyRecord(
                key=key,
                response_id=result.response_id,
                result=result,
                created_at=now,
            )
    ResponseIdempotencyStore.__init__ = _ris_init
    ResponseIdempotencyStore.get = _ris_get
    ResponseIdempotencyStore.put = _ris_put


# ResponseParameterGuard is allowlist-first rather than blacklist-only.
if "ResponseParameterGuard" in globals():
    ResponseParameterGuard.ALLOWED_PARAMS = frozenset({
        "endpoint_id", "ioc_value", "session_id", "account_id",
        "ticket_id", "priority", "reason", "duration_minutes",
        "target_hash", "external_reference", "device_id",
        "username", "ip_address", "domain", "file_hash",
    })
    def _response_parameter_sanitize(cls, parameters):
        if not isinstance(parameters, Mapping):
            raise TypeError("parameters must be a mapping")
        clean = {}
        for key, value in parameters.items():
            normalized = str(key).strip().lower()
            if normalized not in cls.ALLOWED_PARAMS:
                raise ValueError(f"Unauthorized response parameter: {key}")
            clean[normalized] = str(value)[:2000]
        return clean
    ResponseParameterGuard.sanitize = classmethod(_response_parameter_sanitize)


# Security gate: rate limit before replay-store mutation.
if "SecurityGate" in globals():
    _security_gate_authorize_original = SecurityGate.authorize_request
    def _security_gate_authorize(self, *, request, principal, permission):
        rate_key = (
            f"{request.tenant_id}:"
            f"{principal.principal_id if principal else 'anonymous'}"
        )
        if not self.rate_limiter.allow(rate_key):
            self._emit(
                event_type=SecurityEventType.RATE_LIMITED,
                severity=SecuritySeverity.WARNING,
                tenant_id=request.tenant_id,
                principal_id=principal.principal_id if principal else None,
                correlation_id=request.correlation_id,
                details={"request_id": request.request_id},
            )
            raise RateLimitExceededError("Security rate limit exceeded")
        return _security_gate_authorize_original(
            self, request=request, principal=principal, permission=permission
        )
    SecurityGate.authorize_request = _security_gate_authorize


