def _score01(name, value):
    try:
        value = float(value)
    except Exception as exc:
        raise ValueError(f"{name} must be numeric") from exc
    if not 0.0 <= value <= 1.0:
        raise ValueError(f"{name} must be in [0,1], got {value}")
    return value


