# ---------------------------------------------------------------------------
# Final filesystem/module verification and phase dispatcher
# ---------------------------------------------------------------------------

def _compute_collision_audit(path: str = None) -> dict[str, int]:
    source_path = path
    if source_path is None:
        source_path = globals().get("__file__")
    if not source_path:
        return {"duplicate_symbol_groups": 0, "legacy_definition_versions": 0}
    try:
        with open(source_path, encoding="utf-8") as handle:
            parsed = ast.parse(handle.read())
    except (NameError, FileNotFoundError, OSError, SyntaxError):
        return {"duplicate_symbol_groups": 0, "legacy_definition_versions": 0}
    classes = {}
    functions = {}
    for node in parsed.body:
        if isinstance(node, ast.ClassDef):
            classes.setdefault(node.name, []).append(node.lineno)
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            functions.setdefault(node.name, []).append(node.lineno)
    groups = sum(1 for vals in list(classes.values()) + list(functions.values()) if len(vals) > 1)
    versions = sum(len(vals) for vals in list(classes.values()) + list(functions.values()) if len(vals) > 1)
    return {
        "duplicate_symbol_groups": groups,
        "legacy_definition_versions": versions,
    }


HYDRA_MASTER_COLLISION_AUDIT = _compute_collision_audit()


