# Agent identity/property-safe initialization.
def _base_cyber_agent_init_v2(self, identity=None, policy=None, runtime=None):
    if runtime is not None:
        self.runtime = runtime
    else:
        if identity is None or policy is None:
            raise TypeError("identity and policy are required")
        self.runtime = AgentRuntime(identity, policy)

    if not isinstance(getattr(type(self), "identity", None), property):
        self.identity = self.runtime.identity
    if not isinstance(getattr(type(self), "policy", None), property):
        self.policy = self.runtime.policy

    self._state = getattr(self, "_state", AgentState.READY)
    self._actions_used = getattr(self, "_actions_used", 0)
    self._tools = getattr(self, "_tools", {})
    self.audit_identity = getattr(self, "audit_identity", None)
    self.tenant = getattr(self, "tenant", None)
    self._current_run_uuid = getattr(self, "_current_run_uuid", uuid4())


