if "GovernanceAuditLedger" in globals():
    def _gal_init(self):
        self._records = []
        self._lock = threading.RLock()
    GovernanceAuditLedger.__init__ = _gal_init

    def _gal_append(
        self,
        *,
        tenant_id,
        action_id,
        event_type,
        decision,
        actor_id,
        reason,
        metadata=None,
    ):
        with self._lock:
            previous = self._records[-1].record_hash if self._records else "GENESIS"
            payload = {
                "tenant_id": str(tenant_id),
                "action_id": str(action_id),
                "event_type": event_type,
                "decision": str(decision),
                "actor_id": str(actor_id) if actor_id else None,
                "reason": reason,
                "metadata": dict(metadata or {}),
                "previous_hash": previous,
            }
            record_hash = hashlib.sha256(canonical_json(payload).encode("utf-8")).hexdigest()
            record = GovernanceAuditRecord(
                record_id=uuid4(),
                timestamp=utc_now_v7(),
                tenant_id=tenant_id,
                action_id=action_id,
                event_type=event_type,
                decision=decision,
                actor_id=actor_id,
                reason=reason,
                metadata=dict(metadata or {}),
                previous_hash=previous,
                record_hash=record_hash,
            )
            self._records.append(record)
            return record

    def _gal_records(self, tenant_id=None):
        with self._lock:
            if tenant_id is None:
                return tuple(self._records)
            return tuple(
                record for record in self._records
                if str(record.tenant_id) == str(tenant_id)
            )

    def _gal_verify_chain(self):
        with self._lock:
            previous = "GENESIS"
            for record in self._records:
                payload = {
                    "tenant_id": str(record.tenant_id),
                    "action_id": str(record.action_id),
                    "event_type": record.event_type,
                    "decision": str(record.decision),
                    "actor_id": str(record.actor_id) if record.actor_id else None,
                    "reason": record.reason,
                    "metadata": dict(record.metadata),
                    "previous_hash": previous,
                }
                expected = hashlib.sha256(canonical_json(payload).encode("utf-8")).hexdigest()
                if record.previous_hash != previous or record.record_hash != expected:
                    return False
                previous = record.record_hash
            return True

    GovernanceAuditLedger.append = _gal_append
    GovernanceAuditLedger.records = _gal_records
    GovernanceAuditLedger.verify_chain = _gal_verify_chain


# Phase 21: the last stage is terminal, so its handler may return the terminal
# stage without violating a "next stage" transition.
_clo_validate_stage_output_original = CrossLayerOrchestrator._validate_stage_output
def _clo_validate_stage_output_v2(self, previous, current):
    if current.tenant_id != previous.tenant_id:
        raise TenantIsolationError("Stage output changed tenant")
    if current.context.correlation_id != previous.context.correlation_id:
        raise WiringError("Stage output changed correlation ID")
    if current.context.causation_id != previous.message_id:
        raise WiringError("Stage output causation_id must point to previous message")
    previous_index = LIFECYCLE_ORDER.index(previous.stage)
    current_index = LIFECYCLE_ORDER.index(current.stage)
    if previous_index == len(LIFECYCLE_ORDER) - 1:
        if current_index != previous_index:
            raise InvalidTransitionError("Terminal lifecycle stage must remain terminal")
        return
    if current_index != previous_index + 1:
        raise InvalidTransitionError("Pipeline stages must advance exactly one lifecycle stage at a time")


CrossLayerOrchestrator._validate_stage_output = _clo_validate_stage_output_v2


