# Phase 23 transaction semantics: duplicate/integrity errors survive wrapping,
# generic transaction failures still become Phase23TransactionError.
@contextmanager
def _sp_transaction_v2(self):
    with self._lock:
        with self._connection() as connection:
            try:
                connection.execute("BEGIN IMMEDIATE")
                yield connection
                connection.execute("COMMIT")
            except Exception as exc:
                try:
                    connection.execute("ROLLBACK")
                except sqlite3.Error:
                    pass
                if isinstance(exc, (Phase23DuplicateError, Phase23IntegrityError, Phase23TenantIsolationError)):
                    raise
                raise Phase23TransactionError("Persistence transaction failed") from exc


SQLitePersistenceStore.transaction = _sp_transaction_v2


