# API-key revocation accepts both key-id and raw-key forms.
if "APIKeyManager" in globals():
    def _api_revoke(self, value):
        with self._lock:
            if value in getattr(self, "_records", {}):
                record = self._records[value]
                object.__setattr__(record, "revoked", True) if hasattr(type(record), "__dataclass_fields__") and getattr(type(record), "__dataclass_params__", None) and getattr(type(record).__dataclass_params__, "frozen", False) else None
                # Some merged records are mutable; update them normally.
                try:
                    record.revoked = True
                except Exception:
                    pass
                return
            digest = secure_hash(value)
            legacy = self._keys.get(digest)
            if legacy is not None:
                legacy["revoked"] = True
                return
            # The Phase-25 record model can also be looked up by key_id.
            for key_id, record in getattr(self, "_records", {}).items():
                if key_id == value:
                    try:
                        record.revoked = True
                    except Exception:
                        pass
                    return
    APIKeyManager.revoke = _api_revoke


