# ToolDefinition also serves as the surviving AgentTool contract.
def _tool_definition_init_v3(
    self,
    name: str,
    capabilities=None,
    side_effecting: bool = False,
    description: str = "",
    handler=None,
    **kwargs,
):
    if kwargs:
        raise TypeError(f"Unexpected ToolDefinition arguments: {sorted(kwargs)}")
    object.__setattr__(self, "name", str(name))
    object.__setattr__(self, "capabilities", frozenset(capabilities or ()))
    object.__setattr__(self, "side_effecting", bool(side_effecting))
    object.__setattr__(self, "description", str(description))
    object.__setattr__(self, "handler", handler)


ToolDefinition.__init__ = _tool_definition_init_v3


def _tool_invoke(self, *, agent, arguments):
    # Capability check is explicit and fail-closed.
    agent_caps = set(getattr(agent, "capabilities", ()))
    if not set(self.capabilities).issubset(agent_caps):
        missing = set(self.capabilities) - agent_caps
        raise PermissionError(
            f"Agent lacks tool capabilities: {sorted(map(str, missing))}"
        )
    if self.side_effecting:
        raise PermissionError("Side-effecting tools are not executable in the agent layer")
    if self.handler is None:
        raise RuntimeError(f"Tool '{self.name}' has no handler")
    try:
        return self.handler(agent=agent, arguments=arguments)
    except TypeError:
        return self.handler(**dict(arguments))


ToolDefinition.invoke = _tool_invoke
AgentTool = ToolDefinition
