def _cyber_agent_register_tool_v2(self, tool):
    capability_values = set(getattr(tool, "capabilities", ()))
    if isinstance(tool, RegisteredTool):
        capability_values = set(tool.definition.capabilities)
    agent_caps = set(self.identity.capabilities or ())
    if capability_values:
        # Map where a merged identity stores AgentCapability values.
        normalized_agent_caps = {
            _map_capability_to_phase8(c) for c in agent_caps
        }
        normalized_tool_caps = {
            _map_capability_to_phase8(c) for c in capability_values
        }
        if not normalized_tool_caps.issubset(normalized_agent_caps):
            raise AgentCapabilityError(
                f"Agent '{self.name}' lacks required tool capabilities"
            )
    self._tools[tool.name] = tool


CyberAgent.register_tool = _cyber_agent_register_tool_v2


# AgentRuntime uses capability normalization so Capability and AgentCapability
# generations interoperate deterministically.
def _runtime_has_capability(self, capability):
    wanted = _map_capability_to_phase8(capability)
    for candidate in self.policy.allowed_capabilities:
        if _map_capability_to_phase8(candidate) == wanted:
            return True
    return False


def _runtime_require_capability(self, capability):
    if not _runtime_has_capability(self, capability):
        raise AgentCapabilityError(
            f"Agent '{self.identity.agent_id}' does not have capability "
            f"'{getattr(capability, 'value', capability)}'"
        )


AgentRuntime.has_capability = _runtime_has_capability
AgentRuntime.require_capability = _runtime_require_capability


# Phase 11 reasoning validator: support the canonical evidence_ids field.
def _validate_hypothesis_compat(cls, hypothesis):
    if not isinstance(hypothesis, Mapping):
        raise AssertionError("Hypothesis must be a mapping")
    state = str(hypothesis.get("verification_status", "")).upper()
    evidence = hypothesis.get("evidence")
    if evidence is None:
        evidence = hypothesis.get("evidence_ids", [])
    if not state:
        state = "PARTIALLY_VERIFIED" if evidence else "UNVERIFIED"
    if state not in cls.VERIFIED_STATES:
        raise AssertionError(f"Invalid verification state: {state}")
    if state == "VERIFIED" and not evidence:
        raise AssertionError("A VERIFIED hypothesis must contain evidence.")
    if "confidence" in hypothesis:
        confidence = float(hypothesis["confidence"])
        if not 0.0 <= confidence <= 1.0:
            raise AssertionError("Hypothesis confidence must be [0,1]")
    return {
        "verification_status": state,
        "evidence_count": len(evidence or ()),
    }


EvidenceDisciplineValidator.validate_hypothesis = classmethod(_validate_hypothesis_compat)


