# Phase 25 role permission semantics: Permission is a value object, so RBAC
# compares it by canonical resource/action identity.
def _rbac_permissions_for(self, principal):
    permissions = set()
    with self._lock:
        for role_name in principal.roles:
            role = self._roles.get(role_name)
            if role is None:
                continue
            permissions.update(role.permissions)
    return frozenset(permissions)


RBACPolicy.permissions_for = _rbac_permissions_for


def _authorization_authorize(self, request):
    request.validate()
    principal = request.principal
    if not principal.active:
        return AuthorizationResult(
            decision=SecurityDecision.DENY,
            reason="principal_inactive",
            principal_id=principal.principal_id,
            tenant_id=request.tenant_id,
            permission=request.permission,
        )
    permissions = self.rbac.permissions_for(principal)
    requested = request.permission
    allowed = any(
        (
            p == requested
            or (
                getattr(p, "resource", None) in ("*", requested.resource)
                and getattr(p, "action", None) in ("*", requested.action)
            )
        )
        for p in permissions
    )
    return AuthorizationResult(
        decision=SecurityDecision.ALLOW if allowed else SecurityDecision.DENY,
        reason="explicit_permission" if allowed else "permission_not_granted",
        principal_id=principal.principal_id,
        tenant_id=request.tenant_id,
        permission=requested,
    )


AuthorizationEngine.authorize = _authorization_authorize


# API-key manager revocation with modern record semantics.
if "APIKeyManager" in globals():
    def _api_revoke_v2(self, value):
        with self._lock:
            record = self._records.get(value)
            if record is not None:
                try:
                    record.revoked = True
                except Exception:
                    object.__setattr__(record, "revoked", True)
                return
            try:
                digest = secure_hash(value)
                legacy = self._keys.get(digest)
                if legacy is not None:
                    legacy["revoked"] = True
                    return
            except Exception:
                pass
            raise AuthenticationError("Unknown API key")
    APIKeyManager.revoke = _api_revoke_v2


# Phase 24 audit chain duplicate check must precede sequence validation.
if "InMemoryAuditSink" in globals():
    def _ias_append_v2_exact(self, record):
        with self._lock:
            tenant_records = self._records.get(record.tenant_id, [])
            if any(existing.audit_id == record.audit_id for existing in tenant_records):
                raise AuditDuplicateError(
                    f"Audit record already exists: {record.audit_id}"
                )
            expected_sequence = self._sequence.get(record.tenant_id, -1) + 1
            if record.sequence != expected_sequence:
                raise AuditSequenceError(
                    f"Expected audit sequence {expected_sequence}, received {record.sequence}"
                )
            previous = self._last_fingerprint.get(record.tenant_id)
            if record.previous_fingerprint != previous:
                raise AuditIntegrityError("Audit chain predecessor mismatch")
            if not AuditFingerprint.verify(record):
                raise AuditIntegrityError("Audit record fingerprint is invalid")
            self._records.setdefault(record.tenant_id, []).append(record)
            self._sequence[record.tenant_id] = record.sequence
            self._last_fingerprint[record.tenant_id] = record.fingerprint
    InMemoryAuditSink.append = _ias_append_v2_exact


