# AgentTool/ToolDefinition registration is intentionally permissive; capability
# enforcement occurs at invocation. Explicit RegisteredTool registration still
# fails early when it declares a capability the agent lacks.
def _cyber_agent_register_tool_final(self, tool):
    if isinstance(tool, RegisteredTool):
        declared = set(tool.definition.capabilities)
        allowed = {_map_capability_to_phase8(c) for c in self.identity.capabilities}
        normalized = {_map_capability_to_phase8(c) for c in declared}
        if not normalized.issubset(allowed):
            raise AgentCapabilityError(
                f"Agent '{self.name}' lacks required tool capabilities"
            )
    if not getattr(tool, "name", None):
        raise ValueError("Tool name is required")
    if tool.name in self._tools:
        raise ValueError(f"Tool already registered: {tool.name}")
    self._tools[tool.name] = tool


CyberAgent.register_tool = _cyber_agent_register_tool_final


