# Phase-14 governance ledger accepts both a canonical record object and the
# explicit keyword form.
def _gal_append_final(self, record=None, **kwargs):
    with self._lock:
        if record is None:
            record = GovernanceAuditRecord(**kwargs)

        tenant_id = getattr(record, "tenant_id", "")
        action_id = getattr(record, "action_id", None) or uuid4()
        event_type = getattr(record, "event_type", "")
        decision = getattr(record, "decision", "")
        actor_id = getattr(record, "actor_id", None)
        reason = getattr(record, "reason", "")
        metadata = dict(getattr(record, "metadata", {}) or {})
        previous = self._records[-1].record_hash if self._records else "GENESIS"

        payload = {
            "tenant_id": str(tenant_id),
            "action_id": str(action_id),
            "event_type": event_type,
            "decision": str(decision),
            "actor_id": str(actor_id) if actor_id else None,
            "reason": reason,
            "metadata": metadata,
            "previous_hash": previous,
        }
        record_hash = hashlib.sha256(canonical_json(payload).encode("utf-8")).hexdigest()

        canonical_record = GovernanceAuditRecord(
            record_id=getattr(record, "record_id", None) or uuid4(),
            timestamp=getattr(record, "timestamp", None) or utc_now_v7(),
            tenant_id=tenant_id,
            action_id=action_id,
            event_type=event_type,
            decision=decision,
            actor_id=actor_id,
            reason=reason,
            metadata=metadata,
            previous_hash=previous,
            record_hash=record_hash,
            audit_id=getattr(record, "audit_id", None),
            request_id=getattr(record, "request_id", None),
            details=getattr(record, "details", None),
        )
        self._records.append(canonical_record)
        return canonical_record


