# 2) Registry must use canonical tenant context, not the audit-only identity.
def _registry_register_final(self, agent):
    agent_id = str(getattr(agent, "agent_id", ""))
    if not agent_id:
        raise ValueError("agent_id is required")
    if agent_id in self._agents:
        raise ValueError(f"Agent already registered: {agent_id}")
    self._agents[agent_id] = agent

def _registry_get_final(self, agent_id):
    key = str(agent_id)
    try:
        return self._agents[key]
    except KeyError:
        raise KeyError(f"Unknown Cyber agent: {agent_id}") from None

def _registry_for_tenant_final(self, tenant_id):
    tid = str(tenant_id)
    out = []
    for agent in self._agents.values():
        tenant = getattr(agent, "tenant", None)
        aid_tenant = getattr(tenant, "tenant_id", tenant if isinstance(tenant, str) else None)
        if str(aid_tenant) == tid:
            out.append(agent)
    return out

def _registry_unregister_final(self, agent_id):
    self._agents.pop(str(agent_id), None)

CyberAgentRegistry.register = _registry_register_final
CyberAgentRegistry.get = _registry_get_final
CyberAgentRegistry.for_tenant = _registry_for_tenant_final
CyberAgentRegistry.unregister = _registry_unregister_final

# 3) GovernanceAuditLedger: support both canonical keyword appends and
#    merged Phase-14 record-object appends, while preserving a real hash chain.
def _gal_init_final(self):
    self._lock = _fr_threading.RLock()
    self._records = []
    self._last_hash = "GENESIS"

def _gal_hash_final(record, previous_hash):
    payload = {
        "tenant_id": str(record.tenant_id),
        "action_id": str(record.action_id),
        "event_type": record.event_type,
        "decision": record.decision,
        "actor_id": str(record.actor_id) if record.actor_id else None,
        "reason": record.reason,
        "metadata": dict(record.metadata or {}),
        "previous_hash": previous_hash,
    }
    return sha256_hex(payload)

def _gal_append_final2(self, record=None, *, tenant_id=None, action_id=None,
                       event_type=None, decision=None, actor_id=None,
                       reason="", metadata=None, **kwargs):
    with self._lock:
        if record is not None and not isinstance(record, GovernanceAuditRecord):
            raise TypeError("record must be GovernanceAuditRecord")
        if record is None:
            if tenant_id is None or action_id is None or event_type is None or decision is None:
                raise TypeError("append() requires a record or canonical audit fields")
            record = GovernanceAuditRecord(
                record_id=uuid4(),
                timestamp=utc_now_v7(),
                tenant_id=tenant_id,
                action_id=action_id,
                event_type=str(event_type),
                decision=str(decision),
                actor_id=actor_id,
                reason=str(reason),
                metadata=deep_copy_json(dict(metadata or {})),
                audit_id=str(kwargs.get("audit_id") or uuid4()),
                request_id=str(kwargs.get("request_id") or ""),
                details=deep_copy_json(dict(kwargs.get("details") or {})),
            )
        md = deep_copy_json(dict(getattr(record, "metadata", {}) or {}))
        prev = self._last_hash
        current = _gal_hash_final(record, prev)
        updates = {
            "metadata": md,
            "previous_hash": prev,
            "record_hash": current,
            "audit_id": getattr(record, "audit_id", None) or str(getattr(record, "record_id", uuid4())),
            "details": deep_copy_json(dict(getattr(record, "details", {}) or {})),
        }
        try:
            record = replace(record, **updates)
        except Exception:
            d = dict(vars(record))
            d.update(updates)
            record = GovernanceAuditRecord(**d)
        self._records.append(record)
        self._last_hash = current
        return record

def _gal_records_final(self, tenant_id=None):
    with self._lock:
        if tenant_id is None:
            return tuple(self._records)
        return tuple(r for r in self._records if str(r.tenant_id) == str(tenant_id))

def _gal_verify_chain_final(self):
    with self._lock:
        prev = "GENESIS"
        for r in self._records:
            if getattr(r, "previous_hash", None) != prev:
                return False
            if getattr(r, "record_hash", None) != _gal_hash_final(r, prev):
                return False
            prev = r.record_hash
        return True

GovernanceAuditLedger.__init__ = _gal_init_final
GovernanceAuditLedger.append = _gal_append_final2
GovernanceAuditLedger.records = _gal_records_final
GovernanceAuditLedger.verify_chain = _gal_verify_chain_final

