import socket as _fr_socket
import ipaddress as _fr_ipaddress
import urllib.parse as _fr_urlparse
import urllib.request as _fr_urllib_request
import urllib.error as _fr_urllib_error
import copy as _fr_copy
import math as _fr_math
from collections import OrderedDict as _fr_OrderedDict

class _FRNoRedirect(_fr_urllib_request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        raise _fr_urllib_error.HTTPError(
            newurl, code, "Redirects disabled", headers, fp
        )

_FR_HTTP_OPENER = _fr_urllib_request.build_opener(_FRNoRedirect())

def _fr_public_host_ips(url: str):
    parsed = _fr_urlparse.urlparse(url)
    if parsed.scheme not in {"http", "https"}:
        raise ConnectorConfigurationError("Only HTTP/HTTPS URLs are permitted")
    host = parsed.hostname
    if not host:
        raise ConnectorConfigurationError("URL host is required")
    try:
        infos = _fr_socket.getaddrinfo(host, parsed.port or (443 if parsed.scheme=="https" else 80), type=_fr_socket.SOCK_STREAM)
    except OSError as exc:
        raise ConnectorUnavailableError(f"DNS resolution failed: {host}") from exc
    ips=[]
    for info in infos:
        ip=_fr_ipaddress.ip_address(info[4][0])
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_reserved or ip.is_unspecified:
            raise ConnectorConfigurationError(f"SSRF blocked: {host} -> {ip}")
        ips.append(str(ip))
    if not ips:
        raise ConnectorConfigurationError("No resolved address")
    return parsed, tuple(dict.fromkeys(ips))

# HTTP transport: no redirects + explicit SSRF boundary. This rejects
# private/link-local destinations rather than trusting a connector URL.
def _http_transport_request_final8(self, *, method, url, headers=None, body=None):
    parsed, _ = _fr_public_host_ips(url)
    req = _fr_urllib_request.Request(
        url=url,
        method=method.upper(),
        headers=dict(headers or {}),
        data=body,
    )
    try:
        with _FR_HTTP_OPENER.open(req, timeout=self.timeout_seconds) as response:
            return HTTPResponse(
                status_code=response.status,
                headers=dict(response.headers.items()),
                body=response.read(),
            )
    except _fr_urllib_error.HTTPError as exc:
        if exc.code == 401:
            raise ConnectorAuthenticationError("External system rejected authentication")
        if exc.code == 403:
            raise ConnectorAuthorizationError("External system rejected authorization")
        if exc.code == 429:
            retry_after=None
            raw=exc.headers.get("Retry-After")
            if raw:
                try: retry_after=float(raw)
                except ValueError: retry_after=None
            raise ConnectorRateLimitError("External system rate-limited request", retry_after=retry_after)
        if 500 <= exc.code < 600:
            raise ConnectorUnavailableError(f"External server error: {exc.code}")
        raise ConnectorProtocolError(f"HTTP error: {exc.code}")
    except TimeoutError as exc:
        raise ConnectorTimeoutError("Connector request timed out") from exc
    except _fr_urllib_error.URLError as exc:
        raise ConnectorUnavailableError(str(exc)) from exc
HTTPTransport.request = _http_transport_request_final8

# Thread-safe replay-resistant MFA challenge lifecycle.
def _mfa_provider_init_final8(self):
    self._lock = threading.RLock()
    self._challenges = {}
    self._attempts = {}
    self._MAX_ATTEMPTS = 5
MFAProvider.__init__ = _mfa_provider_init_final8

def _mfa_verify_challenge_final8(self, challenge_id, actor_id, validator):
    with self._lock:
        ch=self._challenges.get(challenge_id)
        now=now_ts()
        if ch is None:
            return False
        if ch.actor_id != actor_id:
            return False
        if ch.expires_at <= now:
            self._challenges.pop(challenge_id, None)
            self._attempts.pop(challenge_id, None)
            return False
        if getattr(ch, "verified", False):
            return False
        tries=self._attempts.get(challenge_id,0)
        if tries >= self._MAX_ATTEMPTS:
            self._challenges.pop(challenge_id, None)
            self._attempts.pop(challenge_id, None)
            raise PermissionError("Too many MFA attempts")
        self._attempts[challenge_id]=tries+1
        ok=bool(validator(ch))
        if ok:
            ch.verified=True
            self._challenges.pop(challenge_id,None)
            self._attempts.pop(challenge_id,None)
        return ok
MFAProvider.verify_challenge = _mfa_verify_challenge_final8

