# Strict response-parameter allowlist.
class _FRResponseParameterGuard:
    ALLOWED_PARAMS=frozenset({
        "endpoint_id","ioc_value","session_id","account_id","ticket_id",
        "priority","reason","duration_minutes","target_hash","external_reference",
    })
    @classmethod
    def sanitize(cls, parameters):
        clean={}
        for key,value in parameters.items():
            sk=str(key)
            if sk not in cls.ALLOWED_PARAMS:
                raise ValueError(f"Unauthorized parameter: {key}")
            if isinstance(value,(dict,list,tuple,set,frozenset)):
                raise ValueError(f"Structured parameter not allowed: {key}")
            clean[sk]=str(value)[:2000]
        return clean
ResponseParameterGuard.sanitize=_FRResponseParameterGuard.sanitize

# EncryptionEngine: versioned authenticated ciphertext with optional AAD.
def _enc_encrypt_final8(self, plaintext: bytes, *, aad: bytes=b""):
    nonce=secrets.token_bytes(16)
    stream=self._keystream(nonce,len(plaintext))
    ct=bytes(a^b for a,b in zip(plaintext,stream))
    body=b"\x01"+nonce+ct
    tag=hmac.new(self._key,aad+body,hashlib.sha256).digest()
    return base64.urlsafe_b64encode(body+tag).decode("ascii")
def _enc_decrypt_final8(self, token: str, *, aad: bytes=b""):
    try: raw=base64.urlsafe_b64decode(token.encode("ascii"))
    except Exception as exc: raise SecretError("Invalid encrypted value.") from exc
    if len(raw)<1+16+32 or raw[0] != 1: raise SecretError("Unsupported or invalid encrypted value.")
    tag=raw[-32:]; body=raw[:-32]
    expected=hmac.new(self._key,aad+body,hashlib.sha256).digest()
    if not hmac.compare_digest(tag,expected): raise SecretError("Encrypted value integrity check failed.")
    nonce=body[1:17]; ciphertext=body[17:]
    stream=self._keystream(nonce,len(ciphertext))
    return bytes(a^b for a,b in zip(ciphertext,stream))
EncryptionEngine.encrypt=_enc_encrypt_final8
EncryptionEngine.decrypt=_enc_decrypt_final8

# Atomic encrypted secret-key rotation for SecretsVault.
def _secretsvault_rotate_key_final8(self, tenant_id):
    with self._lock:
        old_key=self._tenant_key(tenant_id)
        new_key=secrets.token_bytes(32)
        staged={}
        for k,r in list(self._records.items()):
            if k[0] != tenant_id: continue
            staged[k]=self._decrypt(base64.b64decode(r.ciphertext),old_key)
        encrypted={k:base64.b64encode(self._crypt(pt,new_key)).decode("ascii") for k,pt in staged.items()}
        for k,ct in encrypted.items():
            r=self._records[k]
            self._records[k]=SecretRecord(
                secret_id=r.secret_id, tenant_id=r.tenant_id,
                version=r.version+1, ciphertext=ct,
                created_at=r.created_at, rotated_at=now_ts()
            )
        self._keys[tenant_id]=new_key
