_old_auto_eval9=AutoscalingController.evaluate
def _auto_eval9(self, queue_depth):
    now=time.monotonic()
    if now-self._last_scale_at < self._MIN_INTERVAL:
        return ScalingDecision(
            self.current_workers,
            "cooldown",
            queue_depth,
        )
    decision=self.scaler.calculate(current_workers=self.current_workers,queue_depth=queue_depth)
    if decision.desired_workers != self.current_workers:
        self._last_scale_at=now
    self.current_workers=decision.desired_workers
    metrics.gauge("desired_worker_count",self.current_workers)
    return decision
