def _auto_apply9(self, queue_depth, orchestrator, create_worker):
    decision=self.evaluate(queue_depth)
    desired=decision.desired_workers
    while len(orchestrator.workers)<desired:
        orchestrator.workers.append(create_worker())
    while len(orchestrator.workers)>desired:
        idle=getattr(orchestrator,"remove_idle_worker",None)
        if callable(idle):
            idle()
        else:
            orchestrator.workers.pop()
    return decision
