# PasswordHasher must distinguish a malformed stored hash from a wrong
# password so credential-storage tampering is observable.
def _pw_verify_final13(self, password, stored):
    if stored.algorithm != self.ALGORITHM:
        raise CredentialError(f"Unsupported password hash algorithm: {stored.algorithm}")
    try:
        salt=base64.b64decode(stored.salt_b64.encode("ascii"),validate=True)
        expected=base64.b64decode(stored.digest_b64.encode("ascii"),validate=True)
    except (ValueError, base64.binascii.Error) as exc:
        raise CredentialError(f"Malformed password hash: {exc}") from exc
    actual=hashlib.pbkdf2_hmac("sha256",password.encode("utf-8"),salt,stored.iterations)
    return hmac.compare_digest(actual,expected)
PasswordHasher.verify=_pw_verify_final13

