# Explicit Hydra bounds/semantic validations.
def _hydra_risk_post_final13(self):
    for field_name in ("score","likelihood","impact","confidence"):
        v=getattr(self,field_name)
        if not isinstance(v,(int,float)) or isinstance(v,bool) or not 0.0 <= float(v) <= 1.0:
            raise ValueError(f"{field_name} must be in [0,1]")
    if not str(self.rationale).strip():
        raise ValueError("risk rationale is required")
    expected=(HydraActionRisk.CRITICAL if self.score>=0.85 else
              HydraActionRisk.HIGH if self.score>=0.65 else
              HydraActionRisk.MEDIUM if self.score>=0.35 else
              HydraActionRisk.LOW)
    # Do not require exact score-band equality when legacy callers explicitly use
    # READ_ONLY; otherwise keep level/risk consistency enforced.
    if self.level != HydraActionRisk.READ_ONLY and self.level != expected:
        raise ValueError(f"risk level {self.level} inconsistent with score {self.score}")
