FINAL_HARDENING_VERSION = "3.0.0"

# ---------- canonical helpers ----------
def _hard_assert(condition: bool, message: str = "") -> None:
    if not condition:
        raise AssertionError(message)

# Replace the unsafe global assert helper with an optimization-safe helper.
_assert = _hard_assert

# Final break-glass contract: bounded lifetime, explicit approval, tenant binding.
if "BreakGlassManager" in globals():
    BreakGlassManager.MAX_TTL_SECONDS = 900
    def _bg_issue_final(self, principal, reason, ttl_seconds=300):
        if not principal.mfa_verified:
            raise AuthenticationError("Break-glass requires MFA")
        if ttl_seconds <= 0 or ttl_seconds > self.MAX_TTL_SECONDS:
            raise ValidationError(f"Break-glass TTL must be between 1 and {self.MAX_TTL_SECONDS} seconds.")
        grant = BreakGlassGrant(
            grant_id=secure_id("bg"), tenant_id=principal.tenant_id,
            principal_id=principal.principal_id, reason=require_non_empty(reason,"reason"),
            expires_at=utc_now() + timedelta(seconds=ttl_seconds),
            approved=True,
        )
        with self._lock: self._grants[grant.grant_id] = grant
        return grant
    BreakGlassManager.issue = _bg_issue_final
    def _bg_require_active_final(self, grant_id, principal):
        with self._lock:
            grant=self._grants.get(grant_id)
            if grant is None or grant.tenant_id != principal.tenant_id or grant.principal_id != principal.principal_id or not grant.active():
                raise PermissionError("Break-glass grant is not active for this principal")
            return grant
    BreakGlassManager.require_active = _bg_require_active_final

# ---------- Phase-6 policy engine compatibility ----------
if "CyberPolicyEngine" in globals():
    _cpe_old_init = CyberPolicyEngine.__init__
    def _cpe_init_final(self, *, emergency_stop_manager=None, tenant_boundary=None,
                        rbac=None, abac=None, emergency_stop=None,
                        risk_registry=None, **kwargs):
        if kwargs:
            raise TypeError(f"Unexpected CyberPolicyEngine arguments: {sorted(kwargs)}")
        stop = emergency_stop_manager or emergency_stop or EmergencyStopManager()
        _cpe_old_init(self, emergency_stop_manager=stop)
        self.tenant_boundary = tenant_boundary
        self.rbac = rbac
        self.abac = abac
        self.emergency_stop = emergency_stop
        self.risk_registry = risk_registry
    CyberPolicyEngine.__init__ = _cpe_init_final

# ---------- Complete Phase-6 policy engine runtime ----------
if "CyberPolicyEngine" in globals():
    _cpe_old_init2 = CyberPolicyEngine.__init__
    def _cpe_init2(self, *, emergency_stop_manager=None, tenant_boundary=None, rbac=None, abac=None,
                   emergency_stop=None, risk_registry=None, **kwargs):
        if kwargs: raise TypeError(f"Unexpected CyberPolicyEngine arguments: {sorted(kwargs)}")
        stop = emergency_stop_manager or EmergencyStopManager()
        _cpe_old_init2(self, emergency_stop_manager=stop)
        self.tenant_boundary=tenant_boundary; self.rbac=rbac; self.abac=abac
        self.emergency_stop=emergency_stop; self.risk_registry=risk_registry
        self._rules=[]; self._policy_lock=_hard_threading.RLock()
    CyberPolicyEngine.__init__=_cpe_init2
    def _cpe_register_rule(self, rule):
        with self._policy_lock: self._rules.append(rule)
    CyberPolicyEngine.register_rule=_cpe_register_rule
    def _cpe_evaluate_phase6(self, request=None, action_type=None, *args, **kwargs):
        if request is None and args:
            request=args[-1]
        if request is None: raise TypeError("request is required")
        request.validate()
        action_type = action_type or getattr(request,"operation","")
        stopped = False
        if getattr(self, "emergency_stop", None) is not None:
            try:
                stopped = self.emergency_stop.is_stopped(tenant_id=request.principal.tenant_id, action_type=action_type)
            except Exception:
                stopped = False
        if not stopped:
            stopped = self._stop_manager.is_stopped(tenant_id=request.principal.tenant_id, action_type=action_type)
        if stopped:
            return GovernanceDecision(new_id("decision"), PolicyEffect.DENY, "Emergency stop active.", (), RiskLevel.CRITICAL, False, True)
        profile = self.risk_registry.get(action_type) if self.risk_registry is not None else None
        risk = profile.risk_level if profile is not None else RiskLevel.HIGH
        if profile is not None and profile.requires_mfa and not request.principal.mfa_verified:
            return GovernanceDecision(new_id("decision"), PolicyEffect.DENY, "MFA is required for this action.", (), risk, False, False)
        if self.abac is not None and not self.abac.evaluate(request):
            return GovernanceDecision(new_id("decision"), PolicyEffect.DENY, "ABAC denied the request.", (), risk, False, False)
        with self._policy_lock:
            matched=[r for r in sorted(self._rules,key=lambda x:(-x.priority,str(x.rule_id))) if r.matches(request.principal, request.resource, request.operation, risk)]
        if not matched:
            return GovernanceDecision(new_id("decision"), PolicyEffect.DENY, "No applicable policy rule matched.", (), risk, False, False)
        effect=PolicyEffect.ALLOW; approval=False; reasons=[]
        for rule in matched:
            reasons.append(rule.reason or rule.rule_id)
            if rule.effect == PolicyEffect.DENY:
                return GovernanceDecision(new_id("decision"), PolicyEffect.DENY, "; ".join(reasons), tuple(r.rule_id for r in matched), risk, False, False)
            if rule.effect == PolicyEffect.REQUIRE_APPROVAL or (profile and profile.requires_approval):
                effect=PolicyEffect.REQUIRE_APPROVAL; approval=True
            elif rule.effect == PolicyEffect.COMPLIANCE_BLOCK:
                effect=PolicyEffect.COMPLIANCE_BLOCK
        return GovernanceDecision(new_id("decision"), effect, "; ".join(reasons), tuple(r.rule_id for r in matched), risk, approval, False)
    CyberPolicyEngine.evaluate_phase6 = _cpe_evaluate_phase6

    # Make the control plane call the canonical Phase-6 path.
    def _csp_authorize_final(self, request, action_type, agent=None):
        self.tenant_boundary.require_authenticated(request.principal)
        if agent:
            profile=self.risk_registry.get(action_type)
            self.agent_authorization.authorize(agent=agent, tenant_id=request.principal.tenant_id, action_type=action_type, requested_risk=profile.risk_level)
        decision=self.policy.evaluate_phase6(request=request, action_type=action_type)
        self.audit.append(tenant_id=request.principal.tenant_id, actor_type=request.principal.actor_type,
                          actor_id=request.principal.principal_id, action=f"authorize:{action_type}",
                          target=request.resource, category=AuditCategory.AUTHORIZATION,
                          result=decision.effect.value, policy_decision=decision.effect.value,
                          decision_id=decision.decision_id, request_id=getattr(request,"request_id", ""),
                          correlation_id="")
        return decision
    CyberSecurityControlPlane.authorize_action=_csp_authorize_final

