# ---------- Emergency stop compatibility ----------
if "EmergencyStopController" in globals():
    def _esc_is_stopped_final(self, tenant_id=None):
        if tenant_id is not None:
            return tenant_id in getattr(self, "stopped_tenants", set())
        # [auto-repair] was getattr(self, "state", False) -- the thing
        # that actually gets written for a global stop is self._state
        # (see _esc_activate above), so this was reading a name that
        # never existed and always fell through to False, i.e. a global
        # emergency stop could never be observed as active.
        state = getattr(self, "_state", False)
        if isinstance(state, dict):
            return bool(state.get("stopped", state.get("active", False)))
        return bool(getattr(state, "active", state is True))
    EmergencyStopController.is_stopped = _esc_is_stopped_final
    def _esc_assert_final(self, tenant_id=None):
        if _esc_is_stopped_final(self, tenant_id):
            raise PermissionError("Emergency stop is active")
        return True
    EmergencyStopController.assert_execution_allowed = _esc_assert_final

