# ---------- Governance must fail closed above autonomous envelope ----------
if "HydraInMemoryPolicy" in globals():
    def _hydra_policy_govern_final(self, *, context, action_risk, explicit_deny=False):
        context.require_permission("defensive:propose")
        if explicit_deny:
            return HydraGovernanceResult(False, False, "Explicit policy denial.")
        rank = self._rank[action_risk]
        if rank > self._rank[self.max_autonomous_risk]:
            return HydraGovernanceResult(
                True,
                True,
                "Action exceeds autonomous risk threshold; approval required.",
            )
        return HydraGovernanceResult(
            True,
            False,
            "Action is within configured defensive policy envelope.",
        )
    HydraInMemoryPolicy.govern = _hydra_policy_govern_final

