# RegisteredTool: preserve strict mapping return while supporting both handler conventions.
if "RegisteredTool" in globals():
    def _registered_tool_execute_final(self, context, arguments):
        args = dict(arguments or {})
        handler = self.handler
        try:
            result = handler(context, args)
        except TypeError as first_error:
            try:
                result = handler(agent=context, arguments=args)
            except TypeError:
                try:
                    result = handler(**args)
                except TypeError:
                    raise first_error
        if not isinstance(result, Mapping):
            raise TypeError("Tool handler must return a mapping")
        return dict(result)
    RegisteredTool.execute = _registered_tool_execute_final

