# ---------- Response idempotency: canonical record + atomic claim ----------
if "ResponseIdempotencyStore" in globals():
    def _ris_init_final(self):
        self._records = {}
        self._lock = _hard_threading.RLock()
        self._inflight = {}
        self._inflight_cv = _hard_threading.Condition(self._lock)
    ResponseIdempotencyStore.__init__ = _ris_init_final

    def _ris_get_final(self, key):
        with self._lock:
            return self._records.get(key)
    ResponseIdempotencyStore.get = _ris_get_final

    def _ris_put_final(self, key, result, *, now):
        with self._lock:
            if key in self._records:
                return
            self._records[key] = IdempotencyRecord(
                key=key,
                response_id=result.response_id,
                result=result,
                created_at=now,
            )
            self._inflight.pop(key, None)
            self._inflight_cv.notify_all()
    ResponseIdempotencyStore.put = _ris_put_final

    def _ris_claim_final(self, key, response_id):
        with self._lock:
            if key in self._records:
                return False
            owner = self._inflight.get(key)
            if owner is None:
                self._inflight[key] = response_id
                return True
            return False
    ResponseIdempotencyStore.claim = _ris_claim_final

    def _ris_complete_final(self, key, result, *, now):
        self.put(key, result, now=now)
    ResponseIdempotencyStore.complete = _ris_complete_final

    def _ris_release_final(self, key):
        with self._lock:
            self._inflight.pop(key, None)
            self._inflight_cv.notify_all()
    ResponseIdempotencyStore.release = _ris_release_final

    def _ris_wait_final(self, key, timeout=30.0):
        deadline = time.monotonic() + timeout
        with self._inflight_cv:
            while key not in self._records and key in self._inflight:
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise TimeoutError("Timed out waiting for idempotent response")
                self._inflight_cv.wait(timeout=remaining)
            return self._records.get(key)
    ResponseIdempotencyStore.wait = _ris_wait_final

