# ---------- Pipeline fingerprint includes payload ----------
if "PipelineMessage" in globals():
    _PIPELINE_PAYLOAD_MISSING_FINAL = object()
    PipelineMessage._fingerprint_payload_hashes = _HardOrderedDict()
    PipelineMessage._fingerprint_payload_limit = 100000
    # [auto-repair] added (Repair Phase 14). This cache is shared,
    # mutable, class-level state (an OrderedDict despite the misleading
    # "_HardOrderedDict" name -- that's just collections.OrderedDict
    # under an alias, not actually thread-safe). Concurrent
    # PipelineMessage construction from multiple threads could race on
    # the read/write/evict sequence below. A single lock around every
    # access closes that.
    PipelineMessage._fingerprint_cache_lock = threading.RLock()
    @staticmethod
    def _pipeline_fingerprint_final(*, message_id, tenant_id, stage, kind,
                                     truth_class, correlation_id, causation_id,
                                     schema_version, payload=_PIPELINE_PAYLOAD_MISSING_FINAL):
        payload_hash = None
        if payload is _PIPELINE_PAYLOAD_MISSING_FINAL:
            with PipelineMessage._fingerprint_cache_lock:
                payload_hash = PipelineMessage._fingerprint_payload_hashes.get(str(message_id))
        else:
            payload_hash = hashlib.sha256(canonical_json(payload).encode("utf-8")).hexdigest()
        parts = [str(message_id), str(tenant_id), stage.value, kind.value,
                 truth_class.value, str(correlation_id), causation_id or "", str(schema_version)]
        if payload_hash is not None:
            parts.append(payload_hash)
        return hashlib.sha256("|".join(parts).encode("utf-8")).hexdigest()
    PipelineMessage.calculate_fingerprint = _pipeline_fingerprint_final

    def _pm_post_final(self):
        require_non_empty(self.message_id, "message_id")
        require_non_empty(self.tenant_id, "tenant_id")
        require_non_empty(self.schema_version, "schema_version")
        ensure_aware(self.created_at, "created_at")
        if self.context.tenant_id != self.tenant_id:
            raise TenantIsolationError("Message tenant differs from context tenant")
        expected = PipelineMessage.calculate_fingerprint(
            message_id=self.message_id, tenant_id=self.tenant_id, stage=self.stage,
            kind=self.kind, truth_class=self.truth_class,
            correlation_id=self.context.correlation_id,
            causation_id=self.context.causation_id,
            schema_version=self.schema_version, payload=self.payload,
        )
        if self.fingerprint and self.fingerprint != expected:
            raise Phase21ValidationError("Pipeline message fingerprint mismatch")
        object.__setattr__(self, "fingerprint", expected)

    PipelineMessage.__post_init__ = _pm_post_final

    def _pm_factory_create_final(*, tenant_id, stage, kind, truth_class, payload,
                                 correlation_id=None, causation_id=None,
                                 actor_id=None, metadata=None):
        tenant_id = require_non_empty(tenant_id, "tenant_id")
        message_id = str(uuid4())
        context = PipelineContext(
            tenant_id=tenant_id, correlation_id=correlation_id or str(uuid4()),
            causation_id=causation_id, actor_id=actor_id, metadata=dict(metadata or {}),
        )
        payload_hash = hashlib.sha256(canonical_json(payload).encode("utf-8")).hexdigest()
        with PipelineMessage._fingerprint_cache_lock:
            PipelineMessage._fingerprint_payload_hashes[message_id] = payload_hash
            while len(PipelineMessage._fingerprint_payload_hashes) > PipelineMessage._fingerprint_payload_limit:
                PipelineMessage._fingerprint_payload_hashes.popitem(last=False)
        fp = PipelineMessage.calculate_fingerprint(
            message_id=message_id, tenant_id=tenant_id, stage=stage, kind=kind,
            truth_class=truth_class, correlation_id=context.correlation_id,
            causation_id=context.causation_id, schema_version="21.1", payload=payload,
        )
        return PipelineMessage(
            message_id=message_id, tenant_id=tenant_id, stage=stage, kind=kind,
            truth_class=truth_class, context=context, payload=_hard_copy.deepcopy(payload), fingerprint=fp,
        )
    PipelineMessageFactory.create = staticmethod(_pm_factory_create_final)

# ---------- IntegrationResult status + explicit validation ----------
if "IntegrationResult" in globals():
    def _integration_result_init_final(self, result_id=None, tenant_id=None, connector_id="",
                                       operation=None, status=None, started_at=None,
                                       completed_at=None, item_count=0, telemetry=(),
                                       external_reference=None, error_code=None,
                                       error_message=None, metadata=None,
                                       integration_id=None, message_id=None, object_id=None,
                                       direction=None, fingerprint=None, correlation_id=None,
                                       processed_at=None, **kwargs):
        if kwargs:
            raise TypeError(f"Unexpected IntegrationResult arguments: {sorted(kwargs)}")
        resolved_status = status if status is not None else IntegrationResultStatus.SUCCESS
        if isinstance(resolved_status, Enum):
            # Preserve cross-phase status enums at the integration boundary;
            # callers may intentionally compare IntegrationMessageStatus.ACCEPTED.
            pass
        elif not isinstance(resolved_status, IntegrationResultStatus):
            try:
                resolved_status = IntegrationResultStatus(resolved_status)
            except ValueError:
                raw = str(getattr(resolved_status, "value", resolved_status)).strip().lower()
                resolved_status = IntegrationResultStatus.FAILED if raw in {"failed", "error"} else IntegrationResultStatus.SUCCESS
        started = started_at or processed_at or utc_now()
        completed = completed_at or processed_at or started
        object.__setattr__(self, "result_id", result_id or message_id or str(uuid4()))
        object.__setattr__(self, "tenant_id", tenant_id or "")
        object.__setattr__(self, "connector_id", connector_id or integration_id or "")
        object.__setattr__(self, "operation", operation or direction or "")
        object.__setattr__(self, "status", resolved_status)
        object.__setattr__(self, "started_at", started)
        object.__setattr__(self, "completed_at", completed)
        object.__setattr__(self, "item_count", int(item_count))
        object.__setattr__(self, "telemetry", tuple(telemetry or ()))
        object.__setattr__(self, "external_reference", external_reference)
        object.__setattr__(self, "error_code", error_code)
        object.__setattr__(self, "error_message", error_message)
        object.__setattr__(self, "metadata", dict(metadata or {}))
        object.__setattr__(self, "integration_id", integration_id)
        object.__setattr__(self, "message_id", message_id or result_id)
        object.__setattr__(self, "object_id", object_id)
        object.__setattr__(self, "direction", direction)
        object.__setattr__(self, "fingerprint", fingerprint or "")
        object.__setattr__(self, "correlation_id", correlation_id)
        object.__setattr__(self, "processed_at", processed_at or completed)
        if not self.result_id or not self.tenant_id or not self.connector_id:
            raise Phase20ValidationError("IntegrationResult requires result_id, tenant_id and connector_id")
        if self.item_count < 0:
            raise Phase20ValidationError("item_count cannot be negative")
        if self.status == IntegrationResultStatus.FAILED and not self.error_code:
            raise Phase20ValidationError("Failed integration result requires error_code")
    IntegrationResult.__init__ = _integration_result_init_final

# ---------- Pinned HTTP transport to close DNS-rebinding SSRF ----------
class _PinnedHTTPConnection(_hard_http_client.HTTPConnection):
    def __init__(self, hostname, pinned_ip, port=None, timeout=None):
        super().__init__(hostname, port=port, timeout=timeout)
        self._pinned_ip = pinned_ip
        self._server_hostname = hostname
    def connect(self):
        self.sock = _hard_socket.create_connection((self._pinned_ip, self.port), self.timeout)

class _PinnedHTTPSConnection(_hard_http_client.HTTPSConnection):
    def __init__(self, hostname, pinned_ip, port=None, timeout=None, context=None):
        super().__init__(hostname, port=port, timeout=timeout, context=context)
        self._pinned_ip = pinned_ip
        self._server_hostname = hostname
    def connect(self):
        raw = _hard_socket.create_connection((self._pinned_ip, self.port), self.timeout)
        self.sock = self._context.wrap_socket(raw, server_hostname=self._server_hostname)

def _resolve_safe_ip_final(host, port, *, allow_private=False, allowed_networks=()):
    infos = _hard_socket.getaddrinfo(host, port, type=_hard_socket.SOCK_STREAM)
    if not infos:
        raise ConnectorConfigurationError(f"DNS returned no addresses for {host}")
    allowed = tuple(_hard_ipaddress.ip_network(x, strict=False) for x in allowed_networks)
    candidates=[]
    for info in infos:
        ip = _hard_ipaddress.ip_address(info[4][0])
        if isinstance(ip, _hard_ipaddress.IPv6Address) and ip.ipv4_mapped:
            ip = ip.ipv4_mapped
        if allow_private or any(ip in net for net in allowed):
            candidates.append(ip)
            continue
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_reserved or ip.is_unspecified:
            continue
        candidates.append(ip)
    if not candidates:
        raise ConnectorConfigurationError(f"SSRF blocked: {host}")
    return str(candidates[0])

class _HardenedHTTPTransport(HTTPTransport):
    def __init__(self, timeout_seconds=10.0, *, allow_private_hosts=False, allowed_private_networks=()):
        super().__init__(timeout_seconds=timeout_seconds)
        self.allow_private_hosts = bool(allow_private_hosts)
        self.allowed_private_networks = tuple(allowed_private_networks)
    def request(self, *, method, url, headers=None, body=None):
        parsed = _hard_urllib_parse.urlparse(url)
        if parsed.scheme not in {"http", "https"} or not parsed.hostname:
            raise ConnectorConfigurationError("Unsupported or invalid URL")
        if parsed.username or parsed.password:
            raise ConnectorConfigurationError("Embedded URL credentials are forbidden")
        port = parsed.port or (443 if parsed.scheme == "https" else 80)
        pinned_ip = _resolve_safe_ip_final(
            parsed.hostname,
            port,
            allow_private=self.allow_private_hosts,
            allowed_networks=self.allowed_private_networks,
        )
        request_headers = dict(headers or {})
        request_headers.setdefault("Host", parsed.hostname if port in (80,443) else f"{parsed.hostname}:{port}")
        path = parsed.path or "/"
        if parsed.query:
            path += "?" + parsed.query
        conn = (
            _PinnedHTTPSConnection(parsed.hostname, pinned_ip, port=port, timeout=self.timeout_seconds)
            if parsed.scheme == "https" else
            _PinnedHTTPConnection(parsed.hostname, pinned_ip, port=port, timeout=self.timeout_seconds)
        )
        try:
            conn.request(method.upper(), path, body=body, headers=request_headers)
            response = conn.getresponse()
            body_bytes = response.read()
            if response.status in (301,302,303,307,308):
                raise ConnectorProtocolError("Redirects are disabled for connector requests")
            if response.status == 401:
                raise ConnectorAuthenticationError("External system rejected authentication")
            if response.status == 403:
                raise ConnectorAuthorizationError("External system rejected authorization")
            if response.status == 429:
                raw = response.getheader("Retry-After")
                try:
                    retry_after = float(raw) if raw is not None else None
                except ValueError:
                    retry_after = None
                raise ConnectorRateLimitError("External system rate-limited request", retry_after=retry_after)
            if 500 <= response.status < 600:
                raise ConnectorUnavailableError(f"External server error: {response.status}")
            return HTTPResponse(status_code=response.status, headers=dict(response.getheaders()), body=body_bytes)
        except _hard_http_client.HTTPException as exc:
            raise ConnectorUnavailableError(str(exc)) from exc
        except TimeoutError as exc:
            raise ConnectorTimeoutError("Connector request timed out") from exc
        finally:
            conn.close()

HTTPTransport = _HardenedHTTPTransport

# ---------- Standard AEAD cryptography ----------
try:
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM as _AESGCM
except ImportError as _crypto_exc:
    _AESGCM = None

if "EncryptionEngine" in globals():
    def _enc_init_aead(self, key: bytes):
        if not isinstance(key, (bytes, bytearray)) or len(key) < 32:
            raise ValidationError("Encryption key must be at least 256 bits.")
        if _AESGCM is None:
            raise RuntimeError("cryptography package with AESGCM is required for secure encryption")
        self._key = hmac.new(b"NEXORA-HYDRA-ENCRYPTION-V1", bytes(key), hashlib.sha256).digest()
    def _enc_encrypt_aead(self, plaintext: bytes, *, aad: bytes = b"") -> str:
        nonce = secrets.token_bytes(12)
        body = b"\x01" + nonce + _AESGCM(self._key).encrypt(nonce, bytes(plaintext), bytes(aad))
        return base64.urlsafe_b64encode(body).decode("ascii")
    def _enc_decrypt_aead(self, token: str, *, aad: bytes = b"") -> bytes:
        try:
            raw = base64.urlsafe_b64decode(token.encode("ascii"))
        except Exception as exc:
            raise SecretError("Invalid encrypted value") from exc
        if len(raw) < 1 + 12 + 16 or raw[0] != 1:
            raise SecretError("Unsupported or invalid encrypted value")
        nonce = raw[1:13]
        ciphertext = raw[13:]
        try:
            return _AESGCM(self._key).decrypt(nonce, ciphertext, bytes(aad))
        except Exception as exc:
            raise SecretError("Encrypted value integrity check failed") from exc
    EncryptionEngine.__init__ = _enc_init_aead
    EncryptionEngine.encrypt = _enc_encrypt_aead
    EncryptionEngine.decrypt = _enc_decrypt_aead

# Tenant-scoped AEAD for the Phase-6 encrypted secret vault, including AAD binding.
if "SecretsVault" in globals():
    def _sv_encrypt(plaintext: bytes, key: bytes, *, aad: bytes = b""):
        if _AESGCM is None:
            raise RuntimeError("cryptography package with AESGCM is required for secure encryption")
        nonce = secrets.token_bytes(12)
        return b"\x01" + nonce + _AESGCM(key).encrypt(nonce, bytes(plaintext), bytes(aad))
    def _sv_decrypt(encrypted: bytes, key: bytes, *, aad: bytes = b""):
        if len(encrypted) < 1 + 12 + 16 or encrypted[0] != 1:
            raise PermissionError("Invalid encrypted secret payload")
        nonce = encrypted[1:13]
        try:
            return _AESGCM(key).decrypt(nonce, encrypted[13:], bytes(aad))
        except Exception as exc:
            raise PermissionError("Secret integrity check failed") from exc
    # Keep static method backward compatible while making it authenticated AEAD.
    SecretsVault._crypt = staticmethod(_sv_encrypt)
    SecretsVault._decrypt = classmethod(lambda cls, encrypted, key, aad=b"": _sv_decrypt(encrypted, key, aad=aad))
    _sv_old_put = SecretsVault.put
    def _sv_put_final(self, tenant_id, secret_id, value):
        with self._lock:
            key = self._tenant_key(tenant_id)
            aad = f"hydra-secret:{tenant_id}:{secret_id}".encode()
            encrypted = self._crypt(value.encode("utf-8"), key, aad=aad)
            existing = self._records.get((tenant_id, secret_id))
            version = existing.version + 1 if existing else 1
            record = SecretRecord(secret_id=secret_id, tenant_id=tenant_id, version=version,
                                  ciphertext=base64.b64encode(encrypted).decode("ascii"),
                                  created_at=now_ts(), rotated_at=now_ts() if existing else None)
            self._records[(tenant_id, secret_id)] = record
            return record
    SecretsVault.put = _sv_put_final
    def _sv_get_final(self, tenant_id, secret_id):
        with self._lock:
            record = self._records.get((tenant_id, secret_id))
            if not record: raise KeyError("Secret not found")
            key = self._tenant_key(tenant_id)
            aad = f"hydra-secret:{tenant_id}:{secret_id}".encode()
            plaintext = self._decrypt(base64.b64decode(record.ciphertext), key, aad=aad)
            return plaintext.decode("utf-8")
    SecretsVault.get = _sv_get_final
    def _sv_rotate_final(self, tenant_id):
        with self._lock:
            old_key = self._tenant_key(tenant_id)
            new_key = secrets.token_bytes(32)
            staged = {}
            for (t, sid), record in list(self._records.items()):
                if t != tenant_id: continue
                aad = f"hydra-secret:{tenant_id}:{sid}".encode()
                plaintext = self._decrypt(base64.b64decode(record.ciphertext), old_key, aad=aad)
                staged[(t,sid)] = self._crypt(plaintext, new_key, aad=aad)
            for key_tuple, ciphertext in staged.items():
                self._records[key_tuple].ciphertext = base64.b64encode(ciphertext).decode("ascii")
                self._records[key_tuple].rotated_at = now_ts()
            self._keys[tenant_id] = new_key
    SecretsVault.rotate_key = _sv_rotate_final

# ---------- Password hardening: bounded iterations + optional process secret pepper ----------
_PASSWORD_MIN_ITERS = 100_000
_PASSWORD_MAX_ITERS = 2_000_000

def _password_pepper_final(self):
    pepper = _hard_os.environ.get("HYDRA_PASSWORD_PEPPER", "")
    if getattr(self.config, "production", False) and not pepper:
        raise CredentialError("HYDRA_PASSWORD_PEPPER must be configured in production")
    return pepper.encode("utf-8")

if "PasswordHasher" in globals():
    def _ph_hash_final(self, password: str):
        if not isinstance(password, str):
            raise CredentialError("Password must be text")
        if len(password) < self.config.min_password_length:
            raise CredentialError("Password does not meet minimum length")
        iterations = int(self.config.password_iterations)
        if not _PASSWORD_MIN_ITERS <= iterations <= _PASSWORD_MAX_ITERS:
            raise CredentialError("Suspicious password KDF iteration count")
        salt = secrets.token_bytes(16)
        material = hmac.new(_password_pepper_final(self), password.encode("utf-8"), hashlib.sha256).digest()
        digest = hashlib.pbkdf2_hmac("sha256", material, salt, iterations)
        return PasswordHash(
            algorithm=self.ALGORITHM,
            iterations=iterations,
            salt_b64=base64.b64encode(salt).decode("ascii"),
            digest_b64=base64.b64encode(digest).decode("ascii"),
        )
    def _ph_verify_final(self, password: str, stored: PasswordHash) -> bool:
        if stored.algorithm != self.ALGORITHM:
            raise CredentialError(f"Unsupported hash algorithm: {stored.algorithm}")
        if not _PASSWORD_MIN_ITERS <= int(stored.iterations) <= _PASSWORD_MAX_ITERS:
            raise CredentialError("Suspicious password KDF parameters")
        try:
            salt = base64.b64decode(stored.salt_b64.encode("ascii"), validate=True)
            expected = base64.b64decode(stored.digest_b64.encode("ascii"), validate=True)
        except (ValueError, _hard_binascii.Error) as exc:
            raise CredentialError(f"Malformed password hash: {exc}") from exc
        material = hmac.new(_password_pepper_final(self), password.encode("utf-8"), hashlib.sha256).digest()
        actual = hashlib.pbkdf2_hmac("sha256", material, salt, int(stored.iterations))
        return hmac.compare_digest(actual, expected)
    PasswordHasher.hash = _ph_hash_final
    PasswordHasher.verify = _ph_verify_final

# ---------- MFA single-use + bounded attempts + expiry cleanup ----------
if "MFAProvider" in globals():
    def _mfa_verify_challenge_final(self, challenge_id, actor_id, validator):
        now = now_ts()
        with self._lock:
            stale = [k for k, ch in self._challenges.items() if ch.expires_at < now]
            for key in stale:
                self._challenges.pop(key, None)
            challenge = self._challenges.get(challenge_id)
            if challenge is None or challenge.actor_id != actor_id or challenge.verified:
                return False
            attempts = getattr(challenge, "attempts", 0)
            if attempts >= 5:
                self._challenges.pop(challenge_id, None)
                return False
            challenge.attempts = attempts + 1
            if challenge.expires_at < now:
                self._challenges.pop(challenge_id, None)
                return False
            ok = bool(validator(challenge))
            if ok:
                challenge.verified = True
                self._challenges.pop(challenge_id, None)
            return ok
    MFAProvider.verify_challenge = _mfa_verify_challenge_final

# ---------- Secret provider: bounded TTL and tenant-safe snapshots ----------
if "InMemorySecretProvider" in globals():
    _isp_old_init = InMemorySecretProvider.__init__
    def _isp_init_final(self, default_ttl_seconds=3600, max_entries=10000):
        _isp_old_init(self)
        self._secret_ttls = {}
        self._default_ttl_seconds = int(default_ttl_seconds)
        self._max_entries = int(max_entries)
    InMemorySecretProvider.__init__ = _isp_init_final
    _isp_old_put = InMemorySecretProvider.put
    def _isp_put_final(self, reference, value, tenant_id, ttl_seconds=None):
        # [auto-repair] this wrapper's own key wasn't tenant-scoped
        # either (see the class body fix above for the full story) --
        # now uses the same (tenant_id, display_name) key so the TTL
        # bookkeeping actually lines up with the tenant-scoped secret it
        # is tracking, instead of one tenant's write silently resetting
        # or evicting a same-named secret's TTL for a different tenant.
        _isp_old_put(self, reference, value, tenant_id=tenant_id)
        key = (tenant_id, reference.display_name())
        with self._lock:
            self._secret_ttls[key] = time.monotonic() + int(ttl_seconds or self._default_ttl_seconds)
            while len(self._secrets) > self._max_entries:
                oldest = next(iter(self._secrets))
                self._secrets.pop(oldest, None)
                self._secret_ttls.pop(oldest, None)
    InMemorySecretProvider.put = _isp_put_final
    _isp_old_resolve = InMemorySecretProvider.resolve
    def _isp_resolve_final(self, reference, tenant_id):
        key = (tenant_id, reference.display_name())
        with self._lock:
            expiry = self._secret_ttls.get(key)
            if expiry is not None and time.monotonic() >= expiry:
                self._secrets.pop(key, None)
                self._secret_ttls.pop(key, None)
                raise SecretError(f"Secret expired: {reference.display_name()}")
        return _isp_old_resolve(self, reference, tenant_id=tenant_id)
    InMemorySecretProvider.resolve = _isp_resolve_final

# ---------- Token bucket stale-entry eviction ----------
if "TokenBucketRateLimiter" in globals():
    _tb_old_init = TokenBucketRateLimiter.__init__
    def _tb_init_final(self, capacity, refill_per_second, *, max_entries=100000, stale_after_seconds=3600):
        _tb_old_init(self, capacity, refill_per_second)
        self._max_entries = int(max_entries)
        self._stale_after_seconds = float(stale_after_seconds)
    TokenBucketRateLimiter.__init__ = _tb_init_final
    _tb_old_allow = TokenBucketRateLimiter.allow
    def _tb_allow_final(self, key, *, cost=1.0, now_monotonic=None):
        now = time.monotonic() if now_monotonic is None else now_monotonic
        with self._lock:
            if len(self._buckets) >= self._max_entries:
                stale = [k for k, b in self._buckets.items() if now - b.last_refill > self._stale_after_seconds]
                for k in stale:
                    self._buckets.pop(k, None)
                if len(self._buckets) >= self._max_entries and key not in self._buckets:
                    # bounded admission: evict oldest bucket by last_refill.
                    oldest = min(self._buckets.items(), key=lambda kv: kv[1].last_refill)[0]
                    self._buckets.pop(oldest, None)
        return _tb_old_allow(self, key, cost=cost, now_monotonic=now)
    TokenBucketRateLimiter.allow = _tb_allow_final

# ---------- Cross-tool memory bound ----------
if "CrossToolCyberMemory" in globals():
    def _ctm_init_final(self, max_records=100000):
        self._records = _HardOrderedDict()
        self._lock = _hard_threading.RLock()
        self._max_records = int(max_records)
    CrossToolCyberMemory.__init__ = _ctm_init_final
    def _ctm_remember_final(self, record):
        with self._lock:
            old = self._records.get(record.memory_id)
            if old and old.tenant_id != record.tenant_id:
                raise PermissionError("Cross-tenant memory overwrite denied")
            self._records[record.memory_id] = record
            self._records.move_to_end(record.memory_id)
            while len(self._records) > self._max_records:
                self._records.popitem(last=False)
    CrossToolCyberMemory.remember = _ctm_remember_final
    def _ctm_recall_final(self, tenant_id, subject_id):
        with self._lock:
            return [r for r in self._records.values() if r.tenant_id == tenant_id and r.subject_id == subject_id]
    CrossToolCyberMemory.recall = _ctm_recall_final

