if "InMemoryCheckpointStore" in globals():
    _cp_old_init = InMemoryCheckpointStore.__init__
    def _cp_init_final(self):
        _cp_old_init(self)
        self._lock = _hard_threading.RLock()
    InMemoryCheckpointStore.__init__ = _cp_init_final

# ---------- Threat intelligence pagination + defensive copies ----------
if "ThreatIntelRepository" in globals():
    def _ti_get_ioc_final(self, tenant_id, ioc_type, value):
        normalized = IOCNormalizer.normalize(value, ioc_type)
        key = f"{tenant_id}:{ioc_type.value}:{normalized}"
        with self._lock:
            ioc = self._iocs.get(key)
            return _hard_copy.deepcopy(ioc) if ioc is not None else None
    ThreatIntelRepository.get_ioc = _ti_get_ioc_final
    def _ti_list_iocs_final(self, tenant_id, ioc_type=None, *, limit=1000, offset=0):
        if limit <= 0 or offset < 0:
            raise ValueError("limit must be positive and offset non-negative")
        with self._lock:
            result = [ioc for ioc in self._iocs.values() if ioc.tenant_id == tenant_id and (ioc_type is None or ioc.ioc_type == ioc_type)]
            result.sort(key=lambda x: str(getattr(x, "canonical_key", "")))
            return _hard_copy.deepcopy(result[offset:offset + limit])
    ThreatIntelRepository.list_iocs = _ti_list_iocs_final

# ---------- Safe serialization of dataclass classes ----------
_original_final_serialize = _final_serialize

def _final_serialize_hardened(value, _seen=None):
    if is_dataclass(value) and isinstance(value, type):
        return f"<dataclass-class:{value.__module__}.{value.__qualname__}>"
    return _original_final_serialize(value, _seen)

_final_serialize = _final_serialize_hardened
serialize_value = _final_serialize_hardened
canonical_json = lambda value: json.dumps(_final_serialize_hardened(value), sort_keys=True, separators=(",", ":"), ensure_ascii=False)
canonical_json_bytes = lambda value: canonical_json(value).encode("utf-8")
sha256_hex = lambda value: hashlib.sha256(canonical_json_bytes(value)).hexdigest()

