if "_canonical_model" in globals() and hasattr(_canonical_model, "model_rebuild"):
    _canonical_model.model_rebuild(force=True)

# ---------- Collision audit: unknown must never be reported as zero ----------
def _compute_collision_audit_final(path=None):
    source_path = path or globals().get("__file__")
    if not source_path or str(source_path).startswith("<") or not _hard_os.path.exists(source_path):
        return {"duplicate_symbol_groups": -1, "legacy_definition_versions": -1, "status": "UNKNOWN"}
    import ast as _hard_ast
    with open(source_path, encoding="utf-8") as _fh:
        tree = _hard_ast.parse(_fh.read())
    classes = {}
    funcs = {}
    for node in tree.body:
        if isinstance(node, (_hard_ast.ClassDef, _hard_ast.FunctionDef, _hard_ast.AsyncFunctionDef)):
            target = classes if isinstance(node, _hard_ast.ClassDef) else funcs
            target.setdefault(node.name, []).append(node.lineno)
    class_dupes = sum(1 for v in classes.values() if len(v) > 1)
    versions = sum(len(v) for v in classes.values() if len(v) > 1)
    return {"duplicate_symbol_groups": class_dupes, "legacy_definition_versions": versions, "status": "OK"}
_compute_collision_audit = _compute_collision_audit_final
HYDRA_MASTER_COLLISION_AUDIT = _compute_collision_audit_final()

# ---------- Final validation runner: None is a failure, phase 6 included ----------
def _phase_result_ok_final(result):
    if result is None:
        return False
    if isinstance(result, Mapping):
        if result.get("success") is False or result.get("status") in {"FAIL", "FAILED", "EXCEPTION", "NO_RESULT"}:
            return False
        if result.get("failed", 0) or result.get("tests_failed", 0):
            return False
        if "results" in result and isinstance(result["results"], Mapping):
            if any(v not in {"PASS", "VERIFIED", True} for v in result["results"].values()):
                return False
    return True

