# ---------- Phase-27 runtime entrypoint correctness ----------
def _run_all_phases_final16():
    order=[
        ("phase1",run_phase1_self_test),("phase2",run_phase2_self_test),("phase3",run_phase3_self_tests),
        ("phase4",run_phase4_verification),("phase5",run_phase5_tests),("phase6",run_phase6_tests),
        ("phase7",run_phase7_tests),("phase8",run_phase_8_tests),("phase8_agents",run_phase_8_agent_tests),
        ("phase9",run_phase_9_tests),("phase10",run_phase10_tests),("phase11",run_phase11_tests),
        ("phase12",run_phase_12_tests),("phase13",run_phase_13_tests),("phase14",run_phase_14_tests),
        ("phase15",run_phase_15_tests),("phase16",run_phase_16_tests),("phase17",run_phase_17_tests),
        ("phase18",run_phase_18_tests),("phase19",run_phase_19_tests),("phase20",run_phase_20_tests),
        ("phase21",run_phase_21_tests),("phase22",run_phase_22_tests),("phase23",run_phase_23_tests),
        ("phase24",run_phase_24_tests),("phase25",run_phase_25_tests),("phase26",run_phase_26_tests),
        ("phase27",run_phase_27_tests),
    ]
    out={}; failures=[]
    for label, fn in order:
        try:
            result = fn()
            out[label] = result
            if not _phase_result_ok_final(result):
                failures.append(label)
        except Exception as exc:
            out[label] = {"status":"EXCEPTION","error":f"{type(exc).__name__}: {exc}"}
            failures.append(label)
    out["summary"]={"phases":27,"auxiliary_checks":len(order)-27,"failed_phases":failures,"success":not failures}
    return out
run_hydra_phase_original = run_hydra_phase

def run_hydra_phase_final(name: str):
    key = str(name).strip().lower()
    if key == "all":
        return _run_all_phases_final16()
    if key == "phase_22":
        key = "phase22"
    dispatch = {
        "phase1": run_phase1_self_test, "phase2": run_phase2_self_test,
        "phase3": run_phase3_self_tests, "phase4": run_phase4_verification,
        "phase5": run_phase5_tests, "phase6": run_phase6_tests,
        "phase7": run_phase7_tests, "phase8": run_phase_8_tests,
        "phase8_agents": run_phase_8_agent_tests, "phase9": run_phase_9_tests,
        "phase10": run_phase10_tests, "phase11": run_phase11_tests,
        "phase12": run_phase_12_tests, "phase13": run_phase_13_tests,
        "phase14": run_phase_14_tests, "phase15": run_phase_15_tests,
        "phase16": run_phase_16_tests, "phase17": run_phase_17_tests,
        "phase18": run_phase_18_tests, "phase19": run_phase_19_tests,
        "phase20": run_phase_20_tests, "phase21": run_phase_21_tests,
        "phase22": run_phase_22_tests, "phase23": run_phase_23_tests,
        "phase24": run_phase_24_tests, "phase25": run_phase_25_tests,
        "phase26": run_phase_26_tests, "phase27": run_phase_27_tests,
        "master": lambda: {"master": run_hydra_master_verification(), "hardening": run_final_hardening_verification()},
    }
    fn = dispatch.get(key)
    if fn is None:
        raise ValueError("Unknown phase; use phase1..phase27, phase8_agents, master, or all")
    result = fn()
    if result is None:
        return {"status":"NO_RESULT","success":False}
    return result
run_hydra_phase = run_hydra_phase_final

# Final AuditLedger append compatibility: support Phase-6 richer keyword contract while preserving hash-chain semantics.
if "AuditLedger" in globals():
    def _audit_append_final(self, *, context=None, action, target=None, category=None, result="",
                            decision_id="", evidence_ids=(), metadata=None, policy_effect=None,
                            tenant_id=None, actor_id=None, resource=None, outcome=None, request_id=None,
                            actor_type=None, policy_decision=None, correlation_id=None, **kwargs):
        if context is None:
            if tenant_id is None: raise TypeError("append requires tenant_id or context")
            context = CyberTenantContext(
                tenant_id=tenant_id, actor_id=actor_id or "system",
                actor_type=actor_type or ActorType.SYSTEM, request_id=request_id or "",
            )
        elif actor_type is not None or tenant_id is not None or actor_id is not None:
            if actor_type is not None and actor_type != context.actor_type: raise TenantIsolationError("actor_type conflicts with context")
        resolved_effect = policy_effect
        if resolved_effect is None and policy_decision is not None:
            try: resolved_effect = PolicyEffect(policy_decision)
            except Exception: resolved_effect = None
        with self._lock:
            previous = self._records[-1].current_hash if self._records else self.GENESIS_HASH
            record = CyberAuditRecord(
                audit_id=new_id("audit"), tenant_id=context.tenant_id, timestamp=utc_now_iso(),
                actor_type=context.actor_type, actor_id=context.actor_id, action=action,
                target=target if target is not None else (resource or ""),
                category=category or AuditCategory.EXECUTION, decision_id=decision_id,
                request_id=context.request_id, correlation_id=correlation_id or "",
                # [auto-repair] was `outcome.value if outcome is not None
                # else ""` -- crashed with AttributeError whenever a
                # caller passed outcome as a plain string instead of an
                # AuditOutcome enum member (confirmed live: this is the
                # version that actually runs, since AuditLedger.append
                # gets reassigned to this function -- the same fix in
                # the class body alone wasn't enough).
                result=result or ((outcome.value if hasattr(outcome, "value") else str(outcome)) if outcome is not None else ""),
                policy_effect=resolved_effect, evidence_ids=tuple(evidence_ids), metadata=metadata or {},
                previous_hash=previous,
            )
            current = record.calculate_hash()
            record = CyberAuditRecord(**{**asdict(record), "current_hash": current})
            self._records.append(record)
            return record
    AuditLedger.append = _audit_append_final

# ---------- Audit chain verification is snapshot-consistent ----------
if "AuditLedger" in globals():
    def _audit_verify_integrity_final(self):
        with self._lock:
            expected = self.GENESIS_HASH
            for record in self._records:
                if record.previous_hash != expected or record.current_hash != record.calculate_hash():
                    return False
                expected = record.current_hash
            return True
    AuditLedger.verify_integrity = _audit_verify_integrity_final
    def _audit_verify_chain_final(self, *, tenant_id=None):
        with self._lock:
            records = list(self._records)
            if tenant_id is not None:
                records = [r for r in records if r.tenant_id == tenant_id]
            expected = self.GENESIS_HASH
            failures=[]
            for index, record in enumerate(records):
                if record.previous_hash != expected:
                    failures.append({"index":index,"audit_id":record.audit_id,"type":"PREVIOUS_HASH_MISMATCH"})
                calculated = record.calculate_hash()
                if not hmac.compare_digest(calculated, record.current_hash):
                    failures.append({"index":index,"audit_id":record.audit_id,"type":"CURRENT_HASH_MISMATCH"})
                expected = record.current_hash
            return {"valid": not failures, "record_count": len(records), "failures": failures}
    AuditLedger.verify_chain = _audit_verify_chain_final

