# ---------- Final adversarial hardening verification ----------
def run_final_hardening_verification() -> dict:
    checks=[]
    def check(name, fn):
        try:
            fn(); checks.append({"name":name,"status":"PASS"})
        except Exception as exc:
            checks.append({"name":name,"status":"FAIL","detail":f"{type(exc).__name__}: {exc}"})

    check("aggregate_27_phase_runs", lambda: _hard_assert(run_hydra_phase("all")["summary"]["success"]))
    check("master_verification", lambda: _hard_assert(run_hydra_master_verification().get("failed", 1) == 0))
    check("breakglass_requires_approval", lambda: _hard_assert(not BreakGlassGrant("g","t","p","r",utc_now()+timedelta(seconds=30),approved=False).active()))

    def payload_tamper():
        msg=PipelineMessageFactory.create(tenant_id="t",stage=LifecycleStage.OBSERVE,kind=MessageKind.OBSERVATION,truth_class=TruthClass.FACT,payload={"x":1})
        object.__setattr__(msg,"payload",{"x":2})
        try:
            PipelineMessage(message_id=msg.message_id,tenant_id=msg.tenant_id,stage=msg.stage,kind=msg.kind,truth_class=msg.truth_class,context=msg.context,payload=msg.payload,fingerprint=msg.fingerprint)
        except Phase21ValidationError:
            return
        raise AssertionError("payload tamper was accepted")
    check("payload_fingerprint_tamper", payload_tamper)

    def mfa_replay():
        p=MFAProvider(); ch=p.create_challenge("actor","tenant",10)
        _hard_assert(p.verify_challenge(ch.challenge_id,"actor",lambda _: True))
        _hard_assert(not p.verify_challenge(ch.challenge_id,"actor",lambda _: True))
    check("mfa_single_use",mfa_replay)

    def idem_race():
        store=ResponseIdempotencyStore(); wins=[]; guard=_hard_threading.Lock()
        def worker(i):
            if store.claim("same-key",f"r{i}"):
                with guard: wins.append(i)
        with concurrent.futures.ThreadPoolExecutor(max_workers=16) as ex: list(ex.map(worker,range(64)))
        _hard_assert(len(wins)==1,"multiple idempotency winners")
    import concurrent.futures
    check("idempotency_atomic_claim",idem_race)

    def crypto_check():
        engine=EncryptionEngine(b"k"*32); token=engine.encrypt(b"secret",aad=b"tenant-a")
        _hard_assert(engine.decrypt(token,aad=b"tenant-a")==b"secret")
        try: engine.decrypt(token,aad=b"tenant-b"); raise AssertionError("AAD swap accepted")
        except SecretError: pass
    check("aead_aad_binding",crypto_check)

    def ssrf_check():
        try: _resolve_safe_ip_final("127.0.0.1",80)
        except ConnectorConfigurationError: return
        raise AssertionError("private address accepted")
    check("ssrf_private_address",ssrf_check)

    def rate_bound():
        limiter=TokenBucketRateLimiter(1,1,max_entries=32)
        for i in range(200): limiter.allow(f"principal-{i}",now_monotonic=1000.0)
        _hard_assert(len(limiter._buckets)<=32)
    check("rate_limiter_bound",rate_bound)

    def memory_bound():
        memory=CrossToolCyberMemory(max_records=32)
        for i in range(100): memory.remember(CrossToolMemoryRecord(str(i),"tenant","subject","source",{"i":i},"trusted"))
        _hard_assert(len(memory._records)<=32)
    check("memory_bound",memory_bound)

    def audit_race():
        ledger=AuditLedger()
        def add(i): ledger.append(tenant_id="tenant",actor_id="actor",action=f"test.{i}",target="x",category=AuditCategory.SYSTEM,result="ok")
        with concurrent.futures.ThreadPoolExecutor(max_workers=8) as ex: list(ex.map(add,range(100)))
        _hard_assert(ledger.verify_integrity())
    check("audit_concurrent_integrity",audit_race)

    def mapping_collision():
        try: canonical_json({1:"a","1":"b"})
        except Exception: return
        raise AssertionError("mapping key collision was accepted")
    check("canonical_mapping_collision",mapping_collision)

    checks.append({"name":"collision_audit", "status":"PASS" if HYDRA_MASTER_COLLISION_AUDIT.get("status") == "OK" else "FAIL"})
    return {"total":len(checks),"passed":sum(x["status"]=="PASS" for x in checks),"failed":sum(x["status"]=="FAIL" for x in checks),"verified":all(x["status"]=="PASS" for x in checks),"checks":checks}

# ============================================================================
# FINAL SEMANTIC CLOSURE — fail closed on invalid runtime states
# ============================================================================
# Applied after historical repair passes so exported behavior cannot silently
# reinterpret invalid state as successful execution.
def _phase_result_ok_final_strict(result):
    if result is None:
        return False
    if isinstance(result, bool):
        return result
    if isinstance(result, str):
        normalized = result.strip().upper()
        if normalized in {"FAIL", "FAILED", "EXCEPTION", "NO_RESULT", "ERROR"}:
            return False
        if normalized.startswith(("FAIL:", "FAILED:", "EXCEPTION:", "ERROR:")):
            return False
        return True
    if isinstance(result, Mapping):
        if result.get("success") is False or result.get("verified") is False:
            return False
        if result.get("status") in {"FAIL", "FAILED", "EXCEPTION", "NO_RESULT", "ERROR"}:
            return False
        if result.get("failed", 0) or result.get("tests_failed", 0) or result.get("failures"):
            return False
        nested = result.get("results")
        if isinstance(nested, Mapping):
            return all(_phase_result_ok_final_strict(v) for v in nested.values())
        return True
    if isinstance(result, (list, tuple, set)):
        return all(_phase_result_ok_final_strict(v) for v in result)
    return False
_phase_result_ok_final = _phase_result_ok_final_strict

# Invalid integration status must never be silently converted into SUCCESS.
if "IntegrationResult" in globals():
    _integration_result_init_semantic_original = IntegrationResult.__init__
    def _integration_result_init_semantic(self, *args, **kwargs):
        status = kwargs.get("status")
        if status is not None and not isinstance(status, Enum):
            try:
                IntegrationResultStatus(status)
            except (TypeError, ValueError) as exc:
                raise Phase20ValidationError(f"Invalid integration result status: {status!r}") from exc
        _integration_result_init_semantic_original(self, *args, **kwargs)
    IntegrationResult.__init__ = _integration_result_init_semantic

# Simulated response markers are safety-critical. Registry/marker failures
# propagate instead of returning an ambiguous response that could look real.
if "CyberResponseDispatcher" in globals() and "SimulatedResponseConnector" in globals():
    _response_dispatch_semantic_original = CyberResponseDispatcher.dispatch
    def _response_dispatch_semantic(self, request):
        result = _response_dispatch_semantic_original(self, request)
        connectors = self.connector_registry.find_capable(
            tenant_id=request.tenant_id,
            action_type=request.action_type,
        )
        if connectors and isinstance(connectors[0], SimulatedResponseConnector):
            object.__setattr__(result, "executed", False)
            object.__setattr__(result, "_simulated", True)
            object.__setattr__(result, "external_request_id", None)
            message = str(getattr(result, "message", "")).strip()
            if not message.startswith("SIMULATED:"):
                object.__setattr__(result, "message", ("SIMULATED: " + message).strip())
        return result
    CyberResponseDispatcher.dispatch = _response_dispatch_semantic

